            ('trajectory_prefix_distance', 'structural', 'trajectory_prefix_distance'),
            ('trajectory_unpacked_points', 'generation', 'trajectory_unpacked_points'),
            ('translate_to', 'converse', 'translate_to'),
            ('translation_sources', 'taxonomy', 'translation_sources'),
            ('translations', 'converse', 'translations'),
            ('type_label', 'lexical', 'type_label'),
            ('usage_overlap', 'consensus', 'usage_overlap'),
            ('variant_walk', 'generation', 'variant_walk'),
            ('vertex_atom', 'realize', 'vertex_atom'),
            ('vertex_tier', 'realize', 'vertex_tier'),
            ('vocab_dominant_pos', 'generation', 'vocab_dominant_pos'),
            ('walk_branches', 'consensus', 'walk_branches'),
            ('walk_completes_floor', 'generation', 'walk_completes_floor'),
            ('walk_continuations', 'generation', 'walk_continuations'),
            ('walk_edge_weight', 'consensus', 'walk_edge_weight'),
            ('walk_strongest', 'consensus', 'walk_strongest'),
            ('walk_text', 'generation', 'walk_text'),
            ('witness_precedes_chain', 'converse', 'witness_precedes_chain'),
            ('word_anchor', 'structural', 'word_anchor'),
            ('word_case_variant_ids', 'lexical', 'word_case_variant_ids'),
            ('word_case_variants', 'lexical', 'word_case_variants'),
            ('word_curve', 'structural', 'word_curve'),
            ('word_language', 'converse', 'word_language'),
            ('word_order', 'generation', 'word_order'),
            ('word_segment', 'converse', 'word_segment'),
            ('word_shape_distance', 'structural', 'word_shape_distance'),
            ('word_shape_peers_fast', 'lexical', 'word_shape_peers_fast')
        ) AS t(src_name, dst_schema, dst_name)
    LOOP
        FOR r IN
            SELECT pg_catalog.pg_get_function_identity_arguments(p.oid) AS args
            FROM pg_catalog.pg_proc p
            JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
            WHERE n.nspname = 'laplace'
              AND p.proname = m.src_name
        LOOP
            -- Already relocated (partial prior run, or a signature the install
            -- script created directly): leave the destination alone.
            IF EXISTS (
                SELECT 1
                FROM pg_catalog.pg_proc p2
                JOIN pg_catalog.pg_namespace n2 ON n2.oid = p2.pronamespace
                WHERE n2.nspname = m.dst_schema
                  AND p2.proname = m.dst_name
                  AND pg_catalog.pg_get_function_identity_arguments(p2.oid) = r.args
            ) THEN
                CONTINUE;
            END IF;

            EXECUTE format('ALTER FUNCTION laplace.%I(%s) SET SCHEMA %I',
                           m.src_name, r.args, m.dst_schema);

            IF m.dst_name <> m.src_name THEN
                EXECUTE format('ALTER FUNCTION %I.%I(%s) RENAME TO %I',
                               m.dst_schema, m.src_name, r.args, m.dst_name);
            END IF;
        END LOOP;
    END LOOP;
END
$relocate$;
CREATE OR REPLACE FUNCTION laplace.laplace_substrate_version()
    RETURNS text
    AS 'laplace_substrate', 'pg_laplace_substrate_version'
    LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
-- CREATE TABLE IF NOT EXISTS does not widen an installed table. Preserve existing
-- evidence with its original neutral opponent while allowing the new COPY layout
-- to write explicit opponent ratings; this recurses to existing partitions too.
ALTER TABLE attestations ADD COLUMN IF NOT EXISTS opponent_rating_fp1e9
    bigint NOT NULL DEFAULT 1500000000000;
ALTER TABLE attestations ADD COLUMN IF NOT EXISTS fold_replayable
    boolean NOT NULL DEFAULT true;
-- Idempotency tokens for the working-set write lane. One row per applied
-- working set (id = the working set's intent hash), claimed with
-- INSERT ... ON CONFLICT DO NOTHING inside the apply transaction: a retry
-- after commit-ambiguity finds the token and skips the additive lanes
-- (attestation count merges) that would otherwise double-apply.
CREATE TABLE IF NOT EXISTS ingest_flush_journal (
    working_set_id  bytea        PRIMARY KEY CHECK (octet_length(working_set_id) = 16),
    source_id       bytea        CHECK (source_id IS NULL OR octet_length(source_id) = 16),
    receipt_kind    text         NOT NULL DEFAULT 'applied'
        CHECK (receipt_kind IN ('applied', 'reconciled-existing')),
    applied_at      timestamptz  NOT NULL DEFAULT now()
);

-- Existing installations predate source ownership. Those historical NULL rows stay
-- conservative (they cannot be attributed safely); every new working set records the
-- decomposer source so source eviction can retract its replay claims along with its data.
-- Replay-token v2 includes semantic row payloads and native intent-stage digests. The
-- writer checks a change's legacy v1 token before claiming v2, so upgrading cannot
-- silently reapply historical additive evidence. Because v1 cannot prove semantic
-- payload equality, that hit is an explicit reconciliation-required failure rather
-- than accepted replay. The historical claim remains untouched until a governed
-- source reconciliation can migrate or rebuild it with a provable v2 token.
ALTER TABLE ingest_flush_journal
    ADD COLUMN IF NOT EXISTS source_id bytea
    CHECK (source_id IS NULL OR octet_length(source_id) = 16);
ALTER TABLE ingest_flush_journal
    ADD COLUMN IF NOT EXISTS receipt_kind text NOT NULL DEFAULT 'applied';

DO $$
BEGIN
    ALTER TABLE ingest_flush_journal DROP CONSTRAINT IF EXISTS ingest_flush_journal_receipt_kind_check;
    ALTER TABLE ingest_flush_journal ADD CONSTRAINT ingest_flush_journal_receipt_kind_check
        CHECK (receipt_kind IN ('applied', 'reconciled-existing'));
END $$;

CREATE INDEX IF NOT EXISTS ingest_flush_journal_source
    ON ingest_flush_journal (source_id)
    WHERE source_id IS NOT NULL;

-- A working set may be one atomic analysis over several independent witnesses.
-- The receipt owns all participating sources while each evidence row retains its
-- actual source_id.  The nullable scalar above remains the compatible fast path
-- for historical and single-source receipts.
CREATE TABLE IF NOT EXISTS ingest_flush_journal_sources (
    working_set_id bytea NOT NULL
        REFERENCES ingest_flush_journal(working_set_id) ON DELETE CASCADE,
    source_id bytea NOT NULL CHECK (octet_length(source_id) = 16),
    PRIMARY KEY (working_set_id, source_id)
);

INSERT INTO ingest_flush_journal_sources (working_set_id, source_id)
SELECT working_set_id, source_id
FROM ingest_flush_journal
WHERE source_id IS NOT NULL
ON CONFLICT DO NOTHING;

CREATE INDEX IF NOT EXISTS ingest_flush_journal_sources_source
    ON ingest_flush_journal_sources (source_id);
-- Compatibility recovery journal for the retired index-cycle loader. Current
-- ingest never inserts here or drops a production index. Keep the table so an
-- upgraded database can restore indexes an older interrupted run left absent;
-- recovery deletes each row only after the index is valid again.
CREATE TABLE IF NOT EXISTS index_cycle_journal (
    index_name  text         PRIMARY KEY,
    table_name  text         NOT NULL,
    index_def   text         NOT NULL,
    dropped_at  timestamptz  NOT NULL DEFAULT now()
);
-- Persistent per-run ingest ledger. One row per IngestRunner run, inserted as
-- 'running' at run start and driven to a terminal status on every exit path.
-- A row still 'running' with no live ingest process is the diagnosable
-- signature of a cut-off run — the counts and files_done say how far it got.
-- Ops metadata, not substrate content: rows are never folded, never walked,
-- and (flush-journal precedent) not preserved across dump/restore.
--
-- STATUS VOCABULARY. Ordinary terminal states are ok / failed / cancelled,
-- plus capped (a deliberate MaxInputUnits smoke run), skipped-complete (a run
-- short-circuited by a completion marker), and empty-noop (declared input,
-- applied none, could not account for it — the runner throws on this one).
--
-- The last three come from IIngestNoOpExplainer: a decomposer accounting for
-- a run that legitimately applied nothing.
--   already-present   novelty gate proved every record already in the substrate
--   already-complete  marker-gated backfill with nothing left to do
--   dependency-unset  optional dependency absent (syzygy tablebases)
--
-- THIS CHECK IS A WRITE GATE, NOT DOCUMENTATION. A status the C# side emits
-- and this list omits does not degrade to an unrecognised-but-stored value:
-- the UPDATE raises 23514, the writer logs INGEST_RUN_JOURNAL_WRITE_FAILED and
-- (correctly) does not abort the ingest, and the row stays 'running' forever —
-- indistinguishable from a killed run, and the journal verifier then fails a
-- run that succeeded. Adding a status to DeriveRunStatus or to an explainer
-- means adding it here in the same change.
CREATE TABLE IF NOT EXISTS ingest_run_journal (
    run_id             uuid         PRIMARY KEY,
    source_name        text         NOT NULL,
    source_id          bytea        CHECK (source_id IS NULL OR octet_length(source_id) = 16),
    layer              int          NOT NULL,
    status             text         NOT NULL DEFAULT 'running'
        CHECK (status IN ('running','ok','failed','empty-noop','capped',
                          'cancelled','skipped-complete',
                          'already-present','already-complete','dependency-unset')),
    phase              text         NOT NULL DEFAULT 'extracting',
    started_at         timestamptz  NOT NULL DEFAULT now(),
    ended_at           timestamptz,
    units_attempted    bigint       NOT NULL DEFAULT 0,
    units_applied      bigint       NOT NULL DEFAULT 0,
    units_failed       bigint       NOT NULL DEFAULT 0,
    entities           bigint       NOT NULL DEFAULT 0,
    physicalities      bigint       NOT NULL DEFAULT 0,
    attestations       bigint       NOT NULL DEFAULT 0,
    files_done         bigint       NOT NULL DEFAULT 0,
    files_total        bigint       NOT NULL DEFAULT 0,
    input_units_done   bigint       NOT NULL DEFAULT 0,
    input_units_total  bigint       NOT NULL DEFAULT 0,
    fold_drain_ms      bigint       NOT NULL DEFAULT 0,
    writer_maintenance_ms bigint     NOT NULL DEFAULT 0,
    fold_span_ms       bigint       NOT NULL DEFAULT 0,
    consensus_backend_ms bigint     NOT NULL DEFAULT 0,
    highway_mask_backend_ms bigint  NOT NULL DEFAULT 0,
    consensus_calls    bigint       NOT NULL DEFAULT 0,
    highway_mask_calls bigint       NOT NULL DEFAULT 0,
    highway_mask_pairs bigint       NOT NULL DEFAULT 0,
    throughput_rows    bigint,
    throughput_elapsed_ms bigint,
    throughput_rows_per_s double precision,
    throughput_baseline_rows_per_s double precision,
    throughput_slowdown_ratio double precision,
    throughput_compared boolean      NOT NULL DEFAULT false,
    throughput_status  text          NOT NULL DEFAULT 'not-measured',
    evidence_persisted boolean      NOT NULL DEFAULT true,
    error              text
);

ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS phase text NOT NULL DEFAULT 'extracting';
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS fold_drain_ms bigint NOT NULL DEFAULT 0;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS writer_maintenance_ms bigint NOT NULL DEFAULT 0;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS fold_span_ms bigint NOT NULL DEFAULT 0;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS consensus_backend_ms bigint NOT NULL DEFAULT 0;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS highway_mask_backend_ms bigint NOT NULL DEFAULT 0;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS consensus_calls bigint NOT NULL DEFAULT 0;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS highway_mask_calls bigint NOT NULL DEFAULT 0;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS highway_mask_pairs bigint NOT NULL DEFAULT 0;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS throughput_rows bigint;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS throughput_elapsed_ms bigint;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS throughput_rows_per_s double precision;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS throughput_baseline_rows_per_s double precision;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS throughput_slowdown_ratio double precision;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS throughput_compared boolean NOT NULL DEFAULT false;
ALTER TABLE ingest_run_journal
    ADD COLUMN IF NOT EXISTS throughput_status text NOT NULL DEFAULT 'not-measured';

CREATE INDEX IF NOT EXISTS ingest_run_journal_source_started
    ON ingest_run_journal (source_name, started_at DESC);

-- Accepted baseline and observed measurement are separate authority. A run may
-- produce a perfectly valid measurement without anyone having accepted that
-- measurement as the comparison standard. CI/readers fail closed on that state;
-- only ops.ingest_throughput_accept() may establish or move the accepted baseline.
CREATE TABLE IF NOT EXISTS ingest_throughput_baseline (
    source_name          text PRIMARY KEY,
    baseline_rows_per_s  double precision NOT NULL CHECK (baseline_rows_per_s > 0),
    baseline_rows        bigint NOT NULL CHECK (baseline_rows > 0),
    baseline_elapsed_ms  bigint NOT NULL CHECK (baseline_elapsed_ms > 0),
    accepted_run_id      uuid,
    established_at       timestamptz NOT NULL DEFAULT now(),
    last_rows_per_s      double precision,
    last_run_id          uuid,
    last_slowdown_ratio  double precision,
    last_status          text,
    last_observed_at     timestamptz
);

-- Migrate the repository's previously accepted corpus measurements into the
-- substrate on first install/upgrade. NpgsqlIngestObservability persists the same
-- IngestRunner WallClock used by the historical INGEST_COMPLETE elapsed_s record,
-- so these baselines and all new production samples share one timing boundary.
-- ON CONFLICT DO NOTHING preserves any baseline already accepted in this DB.
INSERT INTO ingest_throughput_baseline
    (source_name, baseline_rows_per_s, baseline_rows, baseline_elapsed_ms, established_at)
VALUES
    ('CILIDecomposer',         50900.5, 5802654, 114000, now()),
    ('FrameNetDecomposer',      2558.6, 1399559, 547000, now()),
    ('ISO639Decomposer',       18405.5,   73622,   4000, now()),
    ('MapNetDecomposer',        3750.0,   15000,   4000, now()),
    ('PropBankDecomposer',     29019.1,  290191,  10000, now()),
    ('SemLinkDecomposer',       9030.2,   90302,  10000, now()),
    ('UnicodeDecomposer',      94782.6, 3980870,  42000, now()),
    ('VerbNetDecomposer',       8146.0,   32584,   4000, now()),
    ('WordFrameNetDecomposer', 12195.0,   73170,   6000, now()),
    ('WordNetDecomposer',      26620.8, 3540569, 133000, now())
ON CONFLICT (source_name) DO NOTHING;

-- One terminal journal update is the shared ingest boundary for CLI, console,
-- UI, API, OpenAI-compatible and MCP entry points. Derive the measurement here,
-- not in an Actions parser, so every surface records the same verdict even when
-- no workflow or log scraper is involved.
CREATE OR REPLACE FUNCTION ops.ingest_throughput_apply()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_rows bigint;
    v_elapsed_ms bigint;
    v_rate double precision;
    v_baseline double precision;
    v_slowdown double precision;
BEGIN
    -- Only a clean completed ingest is a throughput sample. Marker skips,
    -- capped smoke runs, failures and cancellations retain not-measured.
    IF NEW.status <> 'ok' OR NEW.ended_at IS NULL THEN
        RETURN NEW;
    END IF;

    v_rows := NEW.entities + NEW.physicalities + NEW.attestations;
    -- The managed runner supplies IngestRunResult.WallClock here: exactly the
    -- Stopwatch boundary emitted as INGEST_COMPLETE elapsed_s and used by the
    -- accepted historical runner-clock baselines. Direct SQL/manual journal
    -- transitions have no runner stopwatch, so only those fall back to the
    -- journal timestamp window.
    v_elapsed_ms := COALESCE(
        NULLIF(NEW.throughput_elapsed_ms, 0),
        round(extract(epoch FROM (NEW.ended_at - NEW.started_at)) * 1000.0)::bigint);
    NEW.throughput_rows := v_rows;
    NEW.throughput_elapsed_ms := v_elapsed_ms;

    IF v_rows <= 0 OR v_elapsed_ms <= 0 THEN
        NEW.throughput_status := 'unmeasured';
        NEW.throughput_compared := false;
        RETURN NEW;
    END IF;

    v_rate := (v_rows::double precision * 1000.0) / v_elapsed_ms::double precision;
    NEW.throughput_rows_per_s := v_rate;

    SELECT b.baseline_rows_per_s
      INTO v_baseline
      FROM @extschema@.ingest_throughput_baseline b
     WHERE b.source_name = NEW.source_name;

    IF NOT FOUND THEN
        -- A measurement is evidence, not authority to accept itself. Record the
        -- exact run rate in the journal and fail closed until an operator accepts
        -- a baseline explicitly. This prevents a catastrophically slow first run
        -- from normalizing the regression it should reveal.
        NEW.throughput_baseline_rows_per_s := NULL;
        NEW.throughput_slowdown_ratio := NULL;
        NEW.throughput_compared := false;
        NEW.throughput_status := 'unbaselined';
        RETURN NEW;
    END IF;

    v_slowdown := v_baseline / v_rate;
    NEW.throughput_baseline_rows_per_s := v_baseline;
    NEW.throughput_slowdown_ratio := v_slowdown;
    NEW.throughput_compared := true;
    NEW.throughput_status := CASE WHEN v_slowdown > 1.5 THEN 'slow' ELSE 'ok' END;

    UPDATE @extschema@.ingest_throughput_baseline
       SET last_rows_per_s = v_rate,
           last_run_id = NEW.run_id,
           last_slowdown_ratio = v_slowdown,
           last_status = NEW.throughput_status,
           last_observed_at = now()
     WHERE source_name = NEW.source_name;

    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS ingest_run_throughput_apply ON ingest_run_journal;
CREATE TRIGGER ingest_run_throughput_apply
BEFORE UPDATE OF status, ended_at, entities, physicalities, attestations
ON ingest_run_journal
FOR EACH ROW
WHEN (OLD.status = 'running' AND NEW.status <> 'running')
EXECUTE FUNCTION ops.ingest_throughput_apply();

-- Deliberate baseline authority. The latest measured clean run may be slow or
-- may be the first measurement for a new source; accepting it is an explicit
-- operator action, never something a run or a red gate can do to itself.
-- CI `check` is read-only and never calls this function.
DROP FUNCTION IF EXISTS ops.ingest_throughput_accept(text);
CREATE OR REPLACE FUNCTION ops.ingest_throughput_accept(p_source text)
RETURNS TABLE(source_name text, baseline_rows_per_s double precision, accepted_run_id uuid)
LANGUAGE plpgsql VOLATILE
AS $$
DECLARE
    r @extschema@.ingest_run_journal%ROWTYPE;
BEGIN
    SELECT j.* INTO r
      FROM @extschema@.ingest_run_journal j
     WHERE j.source_name = p_source
       AND j.status = 'ok'
       AND j.throughput_rows_per_s > 0
       AND j.throughput_rows > 0
       AND j.throughput_elapsed_ms > 0
     ORDER BY j.started_at DESC
     LIMIT 1;

    IF r.run_id IS NULL THEN
        RAISE EXCEPTION 'ingest_throughput_accept: no measured clean run for source %', p_source;
    END IF;

    INSERT INTO @extschema@.ingest_throughput_baseline AS b
        (source_name, baseline_rows_per_s, baseline_rows, baseline_elapsed_ms,
         accepted_run_id, established_at, last_rows_per_s, last_run_id,
         last_slowdown_ratio, last_status, last_observed_at)
    VALUES
        (p_source, r.throughput_rows_per_s, r.throughput_rows, r.throughput_elapsed_ms,
         r.run_id, now(), r.throughput_rows_per_s, r.run_id, 1.0, 'accepted', now())
    ON CONFLICT ON CONSTRAINT ingest_throughput_baseline_pkey DO UPDATE SET
        baseline_rows_per_s = EXCLUDED.baseline_rows_per_s,
        baseline_rows = EXCLUDED.baseline_rows,
        baseline_elapsed_ms = EXCLUDED.baseline_elapsed_ms,
        accepted_run_id = EXCLUDED.accepted_run_id,
        established_at = EXCLUDED.established_at,
        last_rows_per_s = EXCLUDED.last_rows_per_s,
        last_run_id = EXCLUDED.last_run_id,
        last_slowdown_ratio = 1.0,
        last_status = 'accepted',
        last_observed_at = EXCLUDED.last_observed_at;

    RETURN QUERY
    SELECT b.source_name, b.baseline_rows_per_s, b.accepted_run_id
      FROM @extschema@.ingest_throughput_baseline b
     WHERE b.source_name = p_source;
END
$$;

-- The CREATE TABLE above is IF NOT EXISTS, so on any database that already has this
-- table the status list frozen at its creation is the list that is enforced — a new
-- status added above would be rejected on every box except a freshly created one.
-- Re-assert the constraint from the schema of record on every install. This is the
-- .sql.in doing its job (idempotent, versioned, applied by install-extensions), not a
-- hand-ALTER against a live database.
DO $$
BEGIN
    ALTER TABLE ingest_run_journal DROP CONSTRAINT IF EXISTS ingest_run_journal_status_check;
    ALTER TABLE ingest_run_journal ADD CONSTRAINT ingest_run_journal_status_check
        CHECK (status IN ('running','ok','failed','empty-noop','capped',
                          'cancelled','skipped-complete',
                          'already-present','already-complete','dependency-unset'));
END $$;
-- Persistent per-FILE ingest ledger. One row per file per run.
--
-- ingest_run_journal carries files_done/files_total and nothing else about which
-- files those were, so a multi-file source is a single row for the whole run: a
-- 686-file UD ingest that dies at file 30 records "cancelled, files_done=10" and
-- the identity of every file it applied, skipped or was mid-apply on is lost.
-- Measured 2026-08-15 on the standing ledger: 36 run rows, 16 with files_total=0.
-- Per-file RESUME already exists (GH #898 — each finished file deposits a
-- HasLayerCompleted marker on the file's content identity and a restart true-skips
-- it), so the file boundary is already a real unit with a real identity; it simply
-- never reached the ledger. This table is that unit, written down.
--
-- Ops metadata, not substrate content: rows are never folded, never walked, and
-- (ingest_run_journal precedent) not preserved across dump/restore.
--
-- STATUS VOCABULARY, and this CHECK is a write gate rather than documentation —
-- a status the C# side emits and this list omits raises 23514, the writer logs
-- INGEST_FILE_JOURNAL_WRITE_FAILED and does not abort the ingest, and the row
-- stays 'running' forever, indistinguishable from a killed file.
--   inventoried        admitted by the run snapshot; not opened yet
--   not-selected       inventoried with an explicit non-admitted disposition
--   running           opened, not yet finished
--   composed          extraction/composition complete; waiting for its boundary to apply
--   ok                applied to completion, marker deposited
--   skipped-complete  true-skipped before opening: marker already present
--   failed            raised; error carries the message
--   cancelled         no terminal write arrived (process killed, cluster bounced)
CREATE TABLE IF NOT EXISTS ingest_file_journal (
    run_id        uuid         NOT NULL,
    file_label    text         NOT NULL,
    source_name   text         NOT NULL,
    file_id       bytea        CHECK (file_id IS NULL OR octet_length(file_id) = 16),
    resume_fingerprint bytea    CHECK (resume_fingerprint IS NULL OR octet_length(resume_fingerprint) = 16),
    status        text         NOT NULL DEFAULT 'running'
        CHECK (status IN ('inventoried','not-selected','running','composed','ok',
                          'skipped-complete','failed','cancelled')),
    started_at    timestamptz  NOT NULL DEFAULT now(),
    ended_at      timestamptz,
    bytes         bigint       NOT NULL DEFAULT 0,
    records       bigint       NOT NULL DEFAULT 0,
    entities      bigint       NOT NULL DEFAULT 0,
    physicalities bigint       NOT NULL DEFAULT 0,
    attestations  bigint       NOT NULL DEFAULT 0,
    error         text,
    modified_at   timestamptz,
    artifact_id   text,
    relative_path text,
    disposition   text         NOT NULL DEFAULT 'admitted'
        CHECK (disposition IN ('admitted','equivalent-packaging','superseded',
                               'excluded-with-reason','unsupported-with-why-not','absent')),
    disposition_reason text,
    PRIMARY KEY (run_id, file_label)
);

-- Observed filesystem time is occurrence metadata, never file identity. Keep it nullable:
-- an upload with no supplied mtime has no such observation and must not fabricate one.
ALTER TABLE ingest_file_journal
    ADD COLUMN IF NOT EXISTS modified_at timestamptz;
ALTER TABLE ingest_file_journal
    ADD COLUMN IF NOT EXISTS resume_fingerprint bytea
        CHECK (resume_fingerprint IS NULL OR octet_length(resume_fingerprint) = 16);
ALTER TABLE ingest_file_journal
    ADD COLUMN IF NOT EXISTS artifact_id text;
ALTER TABLE ingest_file_journal
    ADD COLUMN IF NOT EXISTS relative_path text;
ALTER TABLE ingest_file_journal
    ADD COLUMN IF NOT EXISTS disposition text NOT NULL DEFAULT 'admitted';
ALTER TABLE ingest_file_journal
    ADD COLUMN IF NOT EXISTS disposition_reason text;

-- The read this table exists for: which files did a run finish, and which one was
-- it holding when it died.
CREATE INDEX IF NOT EXISTS ingest_file_journal_run_status
    ON ingest_file_journal (run_id, status);

-- Cross-run: has this file ever completed, and how large was it when it did.
-- bytes is here because input size is the quantity the file pump is NOT bounded by
-- (measured 2026-08-15: UD's 686 treebanks span 4,577 B to 360,217,466 B, a 78,000x
-- spread, against file_channel=30 / file_workers=10 — counts, not bytes).
CREATE INDEX IF NOT EXISTS ingest_file_journal_source_label
    ON ingest_file_journal (source_name, file_label, started_at DESC);

-- Re-assert the CHECK from the schema of record on every install: CREATE TABLE above
-- is IF NOT EXISTS, so on a database that already has the table the vocabulary frozen
-- at creation is the one enforced. Same reason ingest_run_journal does this.
DO $$
BEGIN
    ALTER TABLE ingest_file_journal DROP CONSTRAINT IF EXISTS ingest_file_journal_status_check;
    ALTER TABLE ingest_file_journal ADD CONSTRAINT ingest_file_journal_status_check
        CHECK (status IN ('inventoried','not-selected','running','composed','ok',
                          'skipped-complete','failed','cancelled'));
    ALTER TABLE ingest_file_journal DROP CONSTRAINT IF EXISTS ingest_file_journal_disposition_check;
    ALTER TABLE ingest_file_journal ADD CONSTRAINT ingest_file_journal_disposition_check
        CHECK (disposition IN ('admitted','equivalent-packaging','superseded',
                               'excluded-with-reason','unsupported-with-why-not','absent'));
END $$;
CREATE INDEX IF NOT EXISTS entities_type_btree ON entities USING btree (type_id);
CREATE INDEX IF NOT EXISTS entities_tier_type_btree ON entities USING btree (tier, type_id);
-- entities_tier_btree (single-column btree on entities(tier)) is redundant with
-- LIST(tier) partitioning. Drop it on upgrade. New installs never create it
-- (removed from manifest.install). A BRIN on tier alone is also non-discriminating
-- inside a LIST(tier) leaf — see entities_tier_brin.sql.in (now a DROP).
DO $do$
BEGIN
    -- Release extension membership first (no-op on a fresh install where the index
    -- was never created / never a member); the guarded DROP then removes the object.
    BEGIN
        EXECUTE format('ALTER EXTENSION %I DROP INDEX laplace.entities_tier_btree',
                       'laplace_substrate');
    EXCEPTION WHEN OTHERS THEN
        NULL;  -- not a member (fresh install or already released) — nothing to detach
    END;
    EXECUTE 'DROP INDEX IF EXISTS laplace.entities_tier_btree';
END $do$;
-- entities is LIST(tier)-partitioned. A (tier, type_id) btree is redundant with
-- partition pruning + entities_type_btree(type_id): every tier+type lookup prunes
-- to one leaf and seeks type_id there. The compound index doubles secondary
-- maintenance on every INSERT/COPY (MEASURED: homogeneous 500k binary COPY
-- ~350k rows/s at 2-way with both indexes vs ~510k with type alone; 8-way with
-- both clears 500k). Keep entities_type_btree and the cheap tier/tier_type BRINs.
-- Drop the compound btree on upgrade; new installs never create it.
DO $do$
BEGIN
    BEGIN
        EXECUTE format('ALTER EXTENSION %I DROP INDEX laplace.entities_tier_type_btree',
                       'laplace_substrate');
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    EXECUTE 'DROP INDEX IF EXISTS laplace.entities_tier_type_btree';
END $do$;
CREATE INDEX IF NOT EXISTS entities_first_observed_btree ON entities USING btree (first_observed_by) WHERE first_observed_by IS NOT NULL;
CREATE INDEX IF NOT EXISTS entities_created_at_brin ON entities USING brin (created_at);
CREATE INDEX IF NOT EXISTS physicalities_type_btree ON physicalities USING btree (type);
CREATE INDEX IF NOT EXISTS physicalities_coord_gist ON physicalities USING gist (coord gist_geometry_ops_nd);
-- Angular distance ignores a centroid's radius. Raw coord <<->> mixes angular
-- separation with radius/dispersion, so no finite over-fetch multiplier can
-- guarantee the true nearest angular rows. Unit directions lie on S3, where
-- Euclidean chord distance is strictly monotone with angle; this expression
-- index therefore provides exact angular KNN ordering.
--
-- Type=1 physicality identity is (entity_id, Content), so each entity contributes
-- one canonical direction. The partial predicate avoids taxing Set/projection
-- writes that no angular entity read consumes. This is an always-live production
-- index: ingest never drops or rebuilds it.
CREATE INDEX IF NOT EXISTS physicalities_direction_gist
    ON physicalities USING gist (
        public.laplace_direction_4d(coord) gist_geometry_ops_nd)
    WHERE type = 1 AND public.laplace_direction_4d(coord) IS NOT NULL;
-- hilbert_index equality lookups. NOT optional, and not a partitioning artefact.
--
-- structural.anagrams_of() is the caller that proves it:
--     JOIN v_word_points w2 ON w2.hilbert_index = w1.hilbert_index
--     WHERE w1.id = word_id(p_word)
-- Anagrams share a letter multiset, so they compose to the same coordinate and
-- therefore the same hilbert index — the equality join IS the anagram test. It
-- resolves w1 by id and then needs every row carrying that hilbert value.
--
-- This index did not exist before 2026-08-04 because it did not need to: the
-- primary key was (hilbert_index, id), so hilbert was the leading column and a
-- separate btree would have been redundant. Repartitioning physicalities to
-- HASH(id) moved the PK to (id) — a hash partition key must be a subset of every
-- unique constraint — and that silently removed the only index covering
-- hilbert_index. The join kept returning correct answers while degrading to a
-- sequential scan of all 64 partitions, which is the failure mode that shows up
-- as "still works, mysteriously slower".
--
-- Losing an index because a DIFFERENT index changed shape is the hazard of
-- relying on a compound key's prefix. Named explicitly here so the coverage no
-- longer depends on the PK's leading column staying what it happens to be.
CREATE INDEX IF NOT EXISTS physicalities_hilbert_btree
    ON physicalities USING btree (hilbert_index);
-- physicalities_ducet_rank_btree — makes collation-range queries an index scan.
--
-- ops.ducet_rank(coord) = (x^2 + y^2) * atom_window is IMMUTABLE and pure
-- arithmetic on the stored PointZM, so it is indexable. Without this index a
-- collation-range read is a full scan of every physicality followed by a sort:
-- MEASURED 2026-08-12, ops.ducet_ordered(12140, 6) took 1,444 ms to return six
-- rows, essentially all of it scan and sort, because LIMIT cannot help until
-- after the ordering is established.
--
-- The expression is written out rather than calling ops.ducet_rank, because a
-- functional index must reference a function that cannot be redefined under it;
-- inlining keeps the index independent of the ops schema's migration state.
-- THE UNITS ARE THEREFORE UNSCALED: x^2 + y^2 = s/N, NOT the rank — the planner
-- does not match this index through ducet_rank's * atom_window() scale factor.
-- A reader must range-filter and sort on the raw expression and convert its
-- bound into s/N space once (ops.ducet_ordered does exactly this). Predicating
-- on ducet_rank() bypasses the index: MEASURED 2026-08-13, 1,434 ms seq scan
-- vs 6 ms Merge Append over the per-partition expression indexes.
--
-- What this unlocks, and it is the tier-0 half of "precedes / follows / occurs
-- near": DUCET rank is the Hopf latitude parameter, so a btree range on this
-- expression IS a collation range. "Every atom that collates between X and Y"
-- becomes an index scan with no allkeys.txt lookup at runtime.
--
-- NOTE ON ORDER: this is a tier-0 organ. Composed entities are centroids, sit
-- inside the ball (radius_origin < 1, avg 0.373 at tier 2), and carry no
-- collation rank -- their value on this expression is meaningless, not merely
-- imprecise. Filter to tier 0 when reading, or the range returns interior noise.
--
-- APPLY OFF-INGEST. CREATE INDEX takes a ShareLock that blocks writers; on a
-- live seed this stalls the ingest for the duration of the build. CONCURRENTLY
-- is NOT the escape hatch: physicalities is partitioned and Postgres refuses
-- CREATE INDEX CONCURRENTLY on a partitioned parent (verified 2026-08-13 on
-- this cluster's major version). The manifest entries are correct as they
-- stand — a fresh install has no writers, and once the index exists the
-- IF NOT EXISTS makes every later manifest run a no-op. The one expensive case
-- is the FIRST upgrade of a cluster that predates this index: run that upgrade
-- inside an ingest pause (scripts/wait-for-quiet-substrate.sh), not against
-- hot writers.
CREATE INDEX IF NOT EXISTS physicalities_ducet_rank_btree
    ON physicalities (((public.ST_X(coord)^2 + public.ST_Y(coord)^2)));
-- REMOVED 2026-07-28. radius_origin is a STORED generated column that the SQL surface
-- only ever PROJECTS (structural_neighbors_of selects it); it is never a predicate, a
-- join key, or an ORDER BY anywhere in the extension. A btree on it therefore cannot be
-- chosen by the planner under any query we ship — MEASURED 0 scans against 99,152,023 on
-- physicalities_entity_btree, at 1,285 MB across the 64 partitions, taking a write on
-- every physicality insert.
--
-- Dropped rather than deleted-from-manifest so populated databases shed it on upgrade.
DROP INDEX IF EXISTS physicalities_radius_btree;
-- REMOVED 2026-07-28. Partial btree on alignment_residual WHERE NOT NULL. Nothing in the
-- extension, the app, or the engine reads alignment_residual — the intent stage writes the
-- column and no query consumes it — so the index had 0 scans and 512 kB (almost every row
-- is NULL, which is why it stayed small rather than why it was useful).
--
-- It was also declared TWICE: here and as a hardcoded CREATE INDEX string in
-- Laplace.Cli/IngestCommands.cs. That duplicate is deleted with it; the extension is the
-- deployment unit and owns its own indexes.
DROP INDEX IF EXISTS physicalities_residual_btree;
CREATE INDEX IF NOT EXISTS physicalities_observed_brin ON physicalities USING brin (observed_at);
CREATE INDEX IF NOT EXISTS physicalities_traj_probe ON physicalities USING btree (observed_at) WHERE type = 1 AND trajectory IS NOT NULL;
-- First-constituent index over the AUTHORITATIVE trajectory geometry.
--
-- Answers "which composed entities begin with this child" as a range scan. For text the
-- first constituent is the first codepoint, so this is what makes a first-letter browse
-- possible without rendering a single name -- the access path constituent_edges was
-- reaching for, done as an index instead of a hand-refreshed copy. Postgres maintains it
-- on write, transactionally; there is nothing to regenerate and nothing that can go stale.
--
-- Built on laplace_trajectory_constituent_ids, which has shipped in laplace_geom since the
-- beginning and is IMMUTABLE. That matters for more than convenience: laplace_geom is
-- pinned at its project version with no upgrade script, so a function ADDED to it never
-- reaches an already-installed database -- and an index expression is evaluated immediately
-- at CREATE INDEX, so it hard-fails rather than degrading. Depending only on what geom
-- already exports keeps this substrate upgrade self-contained.
--
-- Scoped to type = 1 (the canonical content physicality a composed entity's constituents
-- are decoded from) and to rows that carry a trajectory, so the index covers only what it
-- can answer for.
CREATE INDEX IF NOT EXISTS physicalities_traj_first_id_btree
    ON physicalities (((public.laplace_trajectory_constituent_ids(trajectory))[1]))
    WHERE trajectory IS NOT NULL AND type = 1;
-- Containment index over a trajectory's constituent ids. THE read model stands on
-- this: compose a point locally from content (a hash, no round-trip), then ask which
-- trajectories CONTAIN it — constituent_ids(trajectory) @> ARRAY[point]. Precedes,
-- follows, contains, part-of and co-occurrence are that same probe read at different
-- offsets, and generation.trajectory_continuations() serves generation from it. Without this it
-- is a sequential scan of every trajectory in the substrate.
--
-- It is also the most expensive index here to maintain: GIN writes one entry per
-- array element and chess trajectories average 137 constituents, so it takes roughly
-- 96% of index-entry writes on this table. That is the price of the capability, not
-- waste. It cannot be narrowed by predicate — the only discriminator that would help
-- (entity type) lives on `entities`, not here.
--
-- fastupdate + the pending list are the lever that IS available. With fastupdate on
-- (the default) inserts land in an unordered pending list, and a backend flushes it
-- into the main structure once it exceeds the limit — in the FOREGROUND of whichever
-- backend crosses the threshold. At the 4 MB default and ~137 entries per row a bulk
-- seed crosses it constantly, so that stall recurs throughout the load; this is the
-- random-write behaviour behind the measured 50 MB/s of WAL producing 2.5 MB/s of net
-- data growth. A larger list batches more entries per merge, and GIN merges are much
-- more efficient in bulk because entries for the same key combine into one posting
-- list update.
--
-- The pending list is scanned LINEARLY on every search until it is flushed, so left
-- alone a raised limit would simply move the cost onto the probe this index exists to
-- serve. It is not left alone: NpgsqlIngestOps.CleanGinPendingListsAsync drains every
-- laplace GIN at the end of an ingest, right after the post-ingest ANALYZE, so the
-- limit is sized for write batching and readers never scan a populated list. That is
-- the whole trade-off removed rather than split — do not raise this without keeping
-- that flush, or the read path pays for the write path.
--
-- 32 MB (8x the default) is a CONSIDERED STARTING POINT, NOT A MEASURED OPTIMUM.
-- Re-measure on the next full seed and move it.
CREATE INDEX IF NOT EXISTS physicalities_constituents_gin
    ON physicalities USING gin (public.laplace_trajectory_constituent_ids(trajectory))
    WITH (fastupdate = on, gin_pending_list_limit = 32768)
    WHERE type = 1 AND trajectory IS NOT NULL;

-- Evictable calculated chess position paths use Projection physicalities. They need the
-- same containment operator without widening content queries to every projection type.
CREATE INDEX IF NOT EXISTS physicalities_projection_constituents_gin
    ON physicalities USING gin (public.laplace_trajectory_constituent_ids(trajectory))
    WITH (fastupdate = on, gin_pending_list_limit = 32768)
    WHERE type = 3 AND trajectory IS NOT NULL;
-- Containment index over a SET physicality's member ids (PhysicalityType.Set = 5).
--
-- Separate from physicalities_constituents_gin rather than widening its `type = 1`
-- predicate. Two reasons, both structural. The text index is the most expensive one on
-- this table -- ~96% of its index-entry writes -- and admitting a second shape into it
-- would put set writes behind the same pending-list flush that the text seed already
-- saturates. And the two shapes answer different questions: a text trajectory's
-- constituent order carries sequence, while a set's does
-- not, so a probe that means "contains this token at some offset" and one that means
-- "this member is in the set" must not share a posting list.
--
-- Set identities are content-addressed, so repeated member sets reuse one physicality.
-- This index scales with distinct compositions rather than the number of attributes that
-- point at them. Pending-list tuning remains measurement-driven.
CREATE INDEX IF NOT EXISTS physicalities_set_constituents_gin
    ON physicalities USING gin (public.laplace_trajectory_constituent_ids(trajectory))
    WHERE type = 5 AND trajectory IS NOT NULL;
CREATE INDEX IF NOT EXISTS attestations_type_btree ON attestations USING btree (type_id);
CREATE INDEX IF NOT EXISTS attestations_object_btree ON attestations USING btree (object_id) WHERE object_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS attestations_source_btree ON attestations USING btree (source_id);
CREATE INDEX IF NOT EXISTS attestations_context_btree ON attestations USING btree (context_id) WHERE context_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS attestations_relation_btree ON attestations USING btree (subject_id, type_id, object_id);
CREATE INDEX IF NOT EXISTS attestations_last_observed_brin ON attestations USING brin (last_observed_at);
-- Generic id-only entity presence is a thin fixed SQL surface over one set
-- operation. It is intentionally PARALLEL RESTRICTED: caller-side batching owns
-- concurrency, so a single probe must not recursively fan into Gather workers.
CREATE OR REPLACE FUNCTION laplace.entities_present_ordinals(p_ids bytea[])
    RETURNS TABLE(idx int)
    LANGUAGE sql STABLE PARALLEL RESTRICTED
AS $$
    SELECT (u.ord - 1)::int
    FROM unnest(p_ids) WITH ORDINALITY u(id, ord)
    JOIN laplace.entities e ON e.id = u.id
$$;

-- The old (ids,tiers) plpgsql overload materialized a temp table, built an index,
-- looped tiers, and dynamically relied on per-iteration planning. It has no caller:
-- the hot tier-keyed route is laplace.entities_stored_bitmap/tier_batch_existence_probe,
-- whose native implementation owns the routing directly. Keep one operation, not a
-- second SQL implementation that can drift back onto the hot path.
DROP FUNCTION IF EXISTS laplace.entities_present_ordinals(bytea[], smallint[]);
-- Physicalities are HASH(id); id is the routing key. The old hilbert-keyed
-- overload describes the retired RANGE(hilbert_index) schema and has no live
-- caller. Keep one fixed set operation and do not spawn a second PostgreSQL
-- parallel fan underneath caller-owned batching.
CREATE OR REPLACE FUNCTION laplace.physicalities_present_ordinals(p_ids bytea[])
    RETURNS TABLE(idx int)
    LANGUAGE sql STABLE PARALLEL RESTRICTED
AS $$
    SELECT (u.ord - 1)::int
    FROM unnest(p_ids) WITH ORDINALITY u(id, ord)
    JOIN laplace.physicalities p ON p.id = u.id
$$;

DROP FUNCTION IF EXISTS laplace.physicalities_present_ordinals(bytea[], bytea[]);
-- Id-only attestation presence is a diagnostic/preflight surface. It cannot prune
-- LIST(type_id)->HASH(subject_id) because those keys are not supplied, so the hot
-- ingest path must never use it; the native keyed bitmap route owns that operation.
-- Keep this one fixed set function because intent_preflight still calls it.
CREATE OR REPLACE FUNCTION laplace.attestations_present_ordinals(p_ids bytea[])
    RETURNS TABLE(idx int)
    LANGUAGE sql STABLE PARALLEL RESTRICTED
AS $$
    SELECT (u.ord - 1)::int
    FROM unnest(p_ids) WITH ORDINALITY u(id, ord)
    JOIN laplace.attestations a ON a.id = u.id
$$;

-- RETIRED: keyed presence is implemented by descent_probe.c's native per-type
-- routing. The former three-array plpgsql body built a temp table + index + ANALYZE
-- and looped types, duplicating an operation the native path already owns.
DROP FUNCTION IF EXISTS laplace.attestations_present_ordinals(bytea[], bytea[], bytea[]);
-- Diagnostic table-agnostic presence wrapper. The concrete fixed surfaces own the
-- set operations; this function only dispatches between them. Caller-side batching
-- owns concurrency, so the wrapper is PARALLEL RESTRICTED with its callees.
CREATE OR REPLACE FUNCTION laplace.table_present_ordinals(p_table text, p_ids bytea[])
    RETURNS TABLE(idx int)
    LANGUAGE sql STABLE PARALLEL RESTRICTED
AS $$
    SELECT o.idx FROM laplace.entities_present_ordinals(p_ids) o
    WHERE p_table = 'entities'
    UNION ALL
    SELECT o.idx FROM laplace.physicalities_present_ordinals(p_ids) o
    WHERE p_table = 'physicalities'
    UNION ALL
    SELECT o.idx FROM laplace.attestations_present_ordinals(p_ids) o
    WHERE p_table = 'attestations'
$$;
CREATE OR REPLACE FUNCTION laplace.entities_exist_bitmap(ids bytea[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_entities_exist_bitmap'
    LANGUAGE C STABLE;
-- KEYED (2026-07-16): id alone cannot prune the LIST(type_id) ->
-- HASH(subject_id) partitioning; the caller passes the partition keys it
-- already holds. Parallel arrays, length-checked natively.
DROP FUNCTION IF EXISTS laplace.attestations_exist_bitmap(bytea[]);
CREATE OR REPLACE FUNCTION laplace.attestations_exist_bitmap(
    ids bytea[], type_ids bytea[], subject_ids bytea[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_attestations_exist_bitmap'
    LANGUAGE C STABLE;

-- Back-compat overload for pre-keyed binaries. A GitHub workflow RE-RUN
-- re-executes its original commit SHA, so a re-run of any seed workflow
-- from before the keyed probe builds old client code that calls the 1-arg
-- form — which the keyed migration dropped, turning version skew into
-- 42883 crashes mid-ingest (observed 2026-07-16, ChessOpenings bootstrap).
-- This shim answers the old contract CORRECTLY through the un-pruned
-- id-only path: slow (one descent per leaf per id, the very cost the keyed
-- probe removes) but never wrong — presence bits only, LSB-first within
-- each byte, identical layout to the native bitmap. New code never calls
-- this; delete only when no pre-keyed binary can reach this database.
CREATE OR REPLACE FUNCTION laplace.attestations_exist_bitmap(ids bytea[])
    RETURNS bytea
    LANGUAGE plpgsql STABLE
 AS $$
DECLARE
    n  int := coalesce(array_length(ids, 1), 0);
    bm bytea;
BEGIN
    IF n = 0 THEN
        RETURN ''::bytea;
    END IF;
    WITH hits AS (
        SELECT (u.ord - 1)::int AS idx
        FROM unnest(ids) WITH ORDINALITY u(id, ord)
        JOIN laplace.attestations t ON t.id = u.id
    ),
    bytes AS (
        SELECT idx / 8 AS b, bit_or(1 << (idx % 8))::int AS v
        FROM hits
        GROUP BY 1
    )
    SELECT string_agg(set_byte('\x00'::bytea, 0, coalesce(bytes.v, 0)), ''::bytea ORDER BY g.b)
    INTO bm
    FROM generate_series(0, (n + 7) / 8 - 1) g(b)
    LEFT JOIN bytes ON bytes.b = g.b;
    RETURN bm;
END $$;
CREATE OR REPLACE FUNCTION laplace.entities_stored_bitmap(ids bytea[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_entities_stored_bitmap'
    LANGUAGE C STABLE;

-- KEYED overload (additive — old binaries keep the 1-arg form, no version
-- skew break): the write lane knows every staged entity's tier, so the
-- probe prunes LIST(tier) instead of descending every leaf per id.
-- Perfcache fast path stays OFF: stored-row semantics (see 1-arg comment
-- chain in descent_probe.c).
CREATE OR REPLACE FUNCTION laplace.entities_stored_bitmap(ids bytea[], tiers smallint[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_entities_stored_bitmap_keyed'
    LANGUAGE C STABLE;
CREATE OR REPLACE FUNCTION laplace.physicalities_exist_bitmap(ids bytea[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_physicalities_exist_bitmap'
    LANGUAGE C STABLE;

-- The (ids, hilberts) keyed overload is GONE (2026-08-04). It pruned each probe
-- to the RANGE(hilbert_index) band holding the row; physicalities is now
-- HASH(id), where a hilbert key names no partition at all. A probe that reports
-- a stored row absent is not a slow path — COPY has no ON CONFLICT, so it aborts
-- the ingest (see the novel-by-construction post-mortem in NpgsqlWorkingSetApply).
-- The id-only probe above needs no partition hint: HASH(id) routes on the id it
-- is already given.
DROP FUNCTION IF EXISTS laplace.physicalities_exist_bitmap(bytea[], bytea[]);
-- Legacy/back-compat entry point. The real trunk-to-leaf, tier-by-tier
-- descent is now driven entirely by the C# orchestrator (TierTreeDescent.cs)
-- via repeated tier_batch_existence_probe() rounds -- `parents` here is
-- validated for shape only and otherwise unused; there is no native
-- tree-walk or default-present assumption left in this function. See
-- pg_laplace_content_descent_bitmap() in laplace_substrate.c.
CREATE OR REPLACE FUNCTION laplace.content_descent_bitmap(ids bytea[], parents int[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_content_descent_bitmap'
    LANGUAGE C STABLE;
-- One round of the tier-by-tier, trunk-to-leaf batch existence probe.
--
-- Takes exactly the candidate ids the C# orchestrator (TierTreeDescent.cs)
-- needs checked for the current tier/round -- already filtered to exclude
-- descendants of nodes proven present in an earlier (higher-tier) round,
-- per the content-addressing guarantee that a present node's whole subtree
-- is present too. Returns a bitmap with a bit set iff that id was
-- positively confirmed present (perfcache codepoint match, or a real
-- committed entities row) -- never a default-present assumption. See
-- laplace_tier_batch_existence_probe() / batch_presence_core() in
-- descent_probe.c.
CREATE OR REPLACE FUNCTION laplace.tier_batch_existence_probe(ids bytea[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_tier_batch_existence_probe'
    LANGUAGE C STABLE;

-- KEYED overload (additive — no version skew break): the descent is
-- tier-by-tier BY CONSTRUCTION, so the caller always knows the tier of
-- every candidate in a round. Pruning LIST(tier) turns each probe from
-- one index descent per leaf into one per id. Perfcache codepoint fast
-- path stays ON (identical semantics to the 1-arg form).
CREATE OR REPLACE FUNCTION laplace.tier_batch_existence_probe(ids bytea[], tiers smallint[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_tier_batch_existence_probe_keyed'
    LANGUAGE C STABLE;
DROP FUNCTION IF EXISTS laplace.content_descent_novel_ordinals(bytea[], int[]);
DO $idem$ BEGIN
    CREATE TYPE laplace_glicko2_result AS (
        rating     bigint,
        rd         bigint,
        volatility bigint
    );
EXCEPTION WHEN duplicate_object THEN NULL;
END $idem$;
