CREATE OR REPLACE FUNCTION laplace.laplace_glicko2_finalfunc(internal)
    RETURNS laplace_glicko2_result
    AS 'laplace_substrate', 'pg_laplace_glicko2_finalfunc'
    LANGUAGE C;
CREATE OR REPLACE AGGREGATE laplace.laplace_glicko2_accumulate(
    prior_rating     bigint,
