    LANGUAGE C STABLE;
DROP FUNCTION IF EXISTS laplace.trajectory_point_count(geometry);
CREATE OR REPLACE FUNCTION structural.trajectory_point_count(p_traj geometry)
    RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT
 AS $$
    SELECT CASE WHEN p_traj IS NULL THEN 0
                ELSE public.ST_NPoints(p_traj)::integer END
$$;
DROP FUNCTION IF EXISTS laplace.trajectory_prefix_distance(geometry, geometry);
CREATE OR REPLACE FUNCTION structural.trajectory_prefix_distance(
    p_a geometry, p_b geometry)
    RETURNS double precision
    LANGUAGE sql STABLE STRICT
 AS $$
    SELECT public.laplace_frechet_4d(p_a, p_b)
$$;
-- entities is LIST(tier)-partitioned, so tier is constant inside every leaf
-- (including the tier=2 HASH subpartitions). A BRIN on tier alone cannot exclude
-- any page range (min=max for every range) while still charging write-time
-- maintenance — Copilot #859. Drop on upgrade; new installs never create it.
DO $do$
BEGIN
    BEGIN
        EXECUTE format('ALTER EXTENSION %I DROP INDEX laplace.entities_tier_brin',
                       'laplace_substrate');
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    EXECUTE 'DROP INDEX IF EXISTS laplace.entities_tier_brin';
END $do$;
-- type_id only: tier is constant inside each LIST(tier) leaf, so including it
-- in the BRIN key adds size/maintenance with no discrimination (Copilot #859).
-- Index name kept for stable references. DROP+CREATE so an in-place upgrade
-- that still has the old (tier, type_id) shape is rewritten, not left behind
-- by CREATE INDEX IF NOT EXISTS.
DO $do$
BEGIN
    BEGIN
        EXECUTE format('ALTER EXTENSION %I DROP INDEX laplace.entities_tier_type_brin',
                       'laplace_substrate');
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    EXECUTE 'DROP INDEX IF EXISTS laplace.entities_tier_type_brin';
END $do$;

CREATE INDEX IF NOT EXISTS entities_tier_type_brin
    ON entities USING brin (type_id) WITH (pages_per_range = 64);

COMMENT ON INDEX entities_tier_type_brin IS
    'BRIN type_id banding for ingest validation at scale (tier is partition-constant).';
-- consensus_object_btree (object_id) WHERE object_id IS NOT NULL is a strict
-- prefix of consensus_object_type_btree (object_id, type_id) under the SAME
-- partial predicate: every access path the single-column index serves, the
-- composite serves from its identical leading column. Measured 2026-08-13 on
-- the live seed epoch: 24 scans in a full day against 396 MB of maintained
-- mass across the partition tree — write tax with no unique read capability
-- (every consensus insert paid a ninth btree; the fold's own probes ride the
-- PK). Dropped on upgrade; new installs never create it. This file IS the
-- drop, per the entities_tier_btree convention, so both manifests keep the
-- same entry.
DO $do$
BEGIN
    -- Release extension membership first (no-op on a fresh install where the
    -- index was never created / never a member); the guarded DROP then
    -- removes the object.
    BEGIN
        EXECUTE format('ALTER EXTENSION %I DROP INDEX laplace.consensus_object_btree',
                       'laplace_substrate');
    EXCEPTION WHEN OTHERS THEN
        NULL;  -- not a member (fresh install or already released)
    END;
    EXECUTE 'DROP INDEX IF EXISTS laplace.consensus_object_btree';
END $do$;
CREATE INDEX IF NOT EXISTS consensus_type_btree ON consensus (type_id);
-- The third key is the content-addressed cell id used by consensus.upsert's MERGE.
-- (subject_id,type_id) remains the read prefix, while dynamic relations in the
-- DEFAULT partition can now prove one exact target row without fetching every
-- cell for the subject/type pair and filtering on id. Named relation partitions
-- happened to choose their id-leading PK; the DEFAULT chose the former two-key
-- index and paid the filter for every Atomic/UD dynamic cell.
CREATE INDEX IF NOT EXISTS consensus_subject_type_btree ON consensus (subject_id, type_id, id);
CREATE INDEX IF NOT EXISTS consensus_type_subject_btree ON consensus (type_id, subject_id) WHERE object_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS consensus_eff_mu_btree ON consensus (((rating - 2*rd)) DESC) WHERE object_id IS NOT NULL;
-- Retired into consensus_subject. Fresh installs create the combined
-- subject/effective-μ covering index here and must not maintain a
-- second tree with the same ordered prefix.
--
-- A populated pre-combination database is deliberately left unchanged during
-- extension upgrade.  Replacing a partitioned index cannot use CONCURRENTLY
-- inside the extension transaction, and dropping a live read path during deploy
-- violates the online-index law.  Its next greenfield reseed gets the combined
-- shape.  An empty old-schema database can be corrected in place safely.
--
-- Effective μ is the second key because bounded subject reads order by it. On
-- a real 746k-row default leaf the former covering + rank trees occupied
-- 83 MB + 28 MB; this combined shape occupied 69 MB and preserved the measured
-- index-only full and top-k plans.
CREATE INDEX IF NOT EXISTS consensus_subject
    ON consensus (subject_id, ((rating - 2*rd)) DESC)
    INCLUDE (object_id, rating, rd);

DO $do$
DECLARE
    v_combined boolean;
    v_empty boolean;
BEGIN
    SELECT i.indexprs IS NOT NULL
      INTO v_combined
      FROM pg_index i
      WHERE i.indexrelid = to_regclass('laplace.consensus_subject');
    SELECT NOT EXISTS (SELECT 1 FROM laplace.consensus LIMIT 1) INTO v_empty;

    IF NOT COALESCE(v_combined, false) AND v_empty THEN
        DROP INDEX IF EXISTS laplace.consensus_subject;
        CREATE INDEX consensus_subject
            ON laplace.consensus (subject_id, ((rating - 2*rd)) DESC)
            INCLUDE (object_id, rating, rd);
        v_combined := true;
    END IF;

    IF COALESCE(v_combined, false) THEN
        DROP INDEX IF EXISTS laplace.consensus_subject_eff_mu_btree;
    ELSE
        RAISE NOTICE 'consensus subject indexes retained online; combined shape applies at reseed';
    END IF;
END $do$;
CREATE INDEX IF NOT EXISTS consensus_subject_type_eff_mu_btree ON consensus (subject_id, type_id, ((rating - 2*rd)) DESC) WHERE object_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS consensus_object_type_btree ON consensus (object_id, type_id) WHERE object_id IS NOT NULL;
CREATE OR REPLACE FUNCTION laplace.consensus_id(
    p_subject bytea, p_type bytea, p_object bytea)
    RETURNS bytea LANGUAGE sql IMMUTABLE        PARALLEL SAFE
 AS $$
    SELECT public.laplace_hash128_blake3(
        p_subject || p_type
        || COALESCE(p_object, '\x00000000000000000000000000000000'::bytea))
$$;
-- Mask refresh queue: entities whose CONSENSUS participation changed and whose
-- highway_mask therefore needs recomputing.
--
-- Why this exists (2026-07-21): highway_mask_refresh derives a mask purely from an
-- entity's consensus edges, so the exact refresh set after a fold is "every subject
-- and object written by that fold". That set was being tracked client-side in a
-- HashSet<Hash128> capped at 8,388,608 (ConsensusAccumulatingWriter); any ingest
-- larger than the cap threw the set away and fell back to highway_mask_rebuild --
-- a full pass over every entity in the substrate. Every large source therefore paid
-- a multi-minute full rebuild, which is batch-rebuild-as-a-class, the thing the
-- substrate forbids: the fold-time refresh is the intended mechanism and the full
-- rebuild is a rare REGENERATE tool for highway bit renumbering only.
--
-- Capturing the set here instead makes it exact, unbounded, and deduplicated by the
-- primary key, with no client memory and no overflow path.
--
-- SUPERSEDED ON THE INGEST PATH (2026-07-21). The fold no longer queues here and
-- no ingest drains it: highway_mask_deposit runs INLINE in every lane, which is
-- O(pairs the fold already holds in RAM) with zero consensus re-reads, versus this
-- queue's O(touched entities x consensus probes) recompute in one serial pass at
-- the end of a run. What survives here is the REPAIR path, which deposit cannot
-- express: deposit only OR-accumulates, so anything that must CLEAR bits --
-- per-source eviction removing an entity's last governed edge -- queues the
-- affected entities here and calls highway_mask_drain(), whose
-- highway_mask_refresh recomputes each mask from scratch and can therefore clear.
-- (highway_mask_rebuild remains the full REGENERATE tool for bit renumbering.)
--
-- UNLOGGED: pure derived work-queue. Losing it on a crash costs a regenerate, never
-- data — and the masks it would have written are themselves recomputable from
-- consensus at any time (recompute-not-accumulate).
CREATE UNLOGGED TABLE IF NOT EXISTS highway_mask_dirty (
    id bytea PRIMARY KEY
);
-- Write epoch for the working-set apply (PR1 of the trusted-novelty series).
--
-- Why this exists: the apply path bulk-probes every id the content spine already
-- claimed novel, because a concurrent writer may have landed overlapping rows
-- between the unlocked descent and the apply transaction. That probe is the
-- guard, not the common case — on a quiet substrate nothing intervened and the
-- probe re-proves absence the descent already knew. A monotonic DB-side write
-- epoch makes "nothing intervened" PROVABLE: every write-lane transaction calls
-- nextval BEFORE writing, so an apply that recorded last_value after its own
-- commit and reads the same value at its next verify has witnessed every
-- write-lane transaction in between (its own bumps subtracted) and knows no
-- foreign writer touched the substrate.
--
-- THIS PR ONLY INTRODUCES THE EPOCH AND ITS TELEMETRY. Writers bump it and log
-- the per-apply foreign delta so live seeds quantify how often the trust
-- condition would hold; no probe/skip decision reads it yet.
--
-- Semantics:
--   * Every write-lane transaction (apply control tx, parallel COPY sub-tx,
--     attestation merge sub-tx, consensus fold segment, highway-mask deposit)
--     calls nextval BEFORE its writes.
--   * Sequence advances survive rollback and crash. That is the CONSERVATIVE
--     direction: an aborted write still moves the epoch, so the next apply sees
--     a foreign delta and re-probes — a false "someone wrote" costs one probe;
--     a rewinding epoch could hide a committed foreign write behind an equal
--     reading, which would be fatal to a future probe skip.
--   * CACHE 1, explicitly: per-session value caching would let a writer's bump
--     land out of order with its writes as observed by another session's
--     last_value read, and the foreign-delta arithmetic (delta = calls made)
--     only holds when every nextval is a single uncached increment.
--
-- Older installed extensions lack this sequence; writers probe to_regclass once
-- and degrade to always-probing. Grants match sibling schema objects: none
-- beyond the extension schema's own — the write lane connects as the
-- installing role.
CREATE SEQUENCE IF NOT EXISTS apply_write_epoch CACHE 1;

COMMENT ON SEQUENCE apply_write_epoch IS
    'Laplace: monotonic write-lane epoch. Every write-lane transaction calls '
    'nextval before writing; an unchanged last_value across a window proves no '
    'writer intervened. Advances survive rollback (conservative: aborted writes '
    'still force the next apply to re-probe).';
-- The single most-repeated join in the SQL surface: an entity paired with its
-- type=1 (identity/content) physicality. Every KNN router, vocab builder, and
-- geometric peer walk was hand-rolling this. Callers that need a trajectory
-- filter add `WHERE trajectory IS NOT NULL` — the view does not invent that
-- filter so sites that only need coord keep working.
--
-- PERFORMANCE CONTRACT (measured 2026-08-01 on live ~4M entities / ~4M type=1
-- physicalities, 64 Hilbert bands, laplace_admin):
--   * Point lookup `WHERE id = $1 LIMIT 1` / structural.word_anchor($1):
--       execution ~0.3–0.7 ms (Nested Loop: entity_id btree → entities pkey).
--       Cold planning of the 64-partition Append is ~30 ms; PREPARE / warm
--       plan cache brings wall to ~8 ms. Prefer prepared statements on hot paths.
--   * KNN `ORDER BY coord <<->> $anchor LIMIT k` (k≈48):
--       execution ~38–65 ms — same order as bare `physicalities WHERE type=1`.
--       Plan is Merge Append of per-band GiST Order By, then Nested Loop into
--       entities for the LIMIT survivors (NOT a 4M-row hash join). Do not fear
--       the join for bounded KNN; do not use this view for unbounded scans.
--   * Do NOT SELECT this view without a selective predicate or LIMIT — it is
--     ~4M rows and will seq-scan.
-- DROP+CREATE: physicality_tableoid was inserted before coord; CREATE OR REPLACE
-- VIEW cannot rename/reorder columns (PG error on upgrade).
DROP VIEW IF EXISTS laplace.v_word_points CASCADE;
CREATE VIEW laplace.v_word_points AS
SELECT e.id,
       e.tier,
       e.type_id,
       e.highway_mask,
       e.first_observed_by,
       e.created_at,
       p.id              AS physicality_id,
       p.tableoid        AS physicality_tableoid,
       p.coord,
       p.hilbert_index,
       p.trajectory,
       p.radius_origin,
       p.n_constituents,
       p.alignment_residual,
       p.source_dim,
       p.observed_at     AS physicality_observed_at
FROM laplace.entities e
JOIN laplace.physicalities p ON p.entity_id = e.id AND p.type = 1;
DROP FUNCTION IF EXISTS laplace.effective_mu(bigint, bigint);
CREATE OR REPLACE FUNCTION consensus.effective_mu(p_rating bigint, p_rd bigint)
    RETURNS bigint
    AS 'laplace_substrate', 'pg_laplace_effective_mu'
    LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE OR REPLACE FUNCTION consensus.eff_mu(p_rating bigint, p_rd bigint)
    RETURNS bigint LANGUAGE sql IMMUTABLE        PARALLEL SAFE AS $$
    SELECT p_rating - 2 * p_rd
$$;
CREATE OR REPLACE FUNCTION consensus.eff_mu_display(p_rating bigint, p_rd bigint)
    RETURNS numeric LANGUAGE sql IMMUTABLE        PARALLEL SAFE AS $$
    SELECT round((consensus.eff_mu(p_rating, p_rd) / 1e9)::numeric, 3)
$$;

-- Display form of an ALREADY-COMPUTED fp1e9 eff-mu (e.g. synset_members.mu).
-- Same rounding, same scale, one definition file — never re-derived inline.
CREATE OR REPLACE FUNCTION consensus.eff_mu_display(p_eff_mu_fp bigint)
    RETURNS numeric LANGUAGE sql IMMUTABLE        PARALLEL SAFE AS $$
    SELECT round((p_eff_mu_fp / 1e9)::numeric, 3)
$$;
DROP FUNCTION IF EXISTS laplace.refuted(bigint, bigint);
CREATE OR REPLACE FUNCTION consensus.refuted(p_rating bigint, p_rd bigint)
    RETURNS boolean LANGUAGE sql IMMUTABLE        PARALLEL SAFE AS $$
    SELECT p_rating + 2 * p_rd < consensus.glicko2_neutral_mu()
$$;
CREATE OR REPLACE VIEW laplace.v_consensus_resolved AS
SELECT c.id, c.subject_id, c.type_id, c.object_id,
       c.rating, c.rd, c.volatility, c.witness_count,
       c.last_observed_at,
       consensus.eff_mu(c.rating, c.rd)         AS eff_mu_raw,
       consensus.eff_mu_display(c.rating, c.rd) AS eff_mu
FROM laplace.consensus c;
CREATE OR REPLACE VIEW laplace.v_consensus_edges AS
SELECT c.id, c.subject_id, c.type_id, c.object_id,
       c.rating, c.rd, c.volatility, c.witness_count,
       c.last_observed_at,
       c.eff_mu_raw, c.eff_mu
FROM laplace.v_consensus_resolved c
WHERE c.object_id IS NOT NULL
  AND c.eff_mu_raw > 0;
-- Shared predicate for the ~21 functions that each reimplemented
-- `NOT consensus.refuted(c.rating, c.rd)` inline as a WHERE clause. Not a duplicate of
-- v_consensus_edges (which additionally requires object_id IS NOT NULL AND
-- eff_mu_raw > 0 -- a different, narrower filter for a different purpose).
CREATE OR REPLACE VIEW laplace.v_consensus_unrefuted AS
SELECT c.*
FROM laplace.consensus c
WHERE NOT consensus.refuted(c.rating, c.rd);
DROP FUNCTION IF EXISTS laplace.relation_type_resolve(text);
CREATE OR REPLACE FUNCTION consensus.relation_type_resolve(p_surface text) RETURNS bytea
    LANGUAGE c IMMUTABLE STRICT PARALLEL SAFE AS 'laplace_substrate', 'pg_relation_type_resolve';
DROP FUNCTION IF EXISTS laplace.relation_type_in_family(bytea, text);
CREATE OR REPLACE FUNCTION consensus.relation_type_in_family(p_type_id bytea, p_family text) RETURNS boolean
    LANGUAGE c IMMUTABLE STRICT PARALLEL SAFE AS 'laplace_substrate', 'pg_relation_type_in_family';
-- relation_in_family: dynamic-aware family membership.
--
-- The C companion consensus.relation_type_in_family() is IMMUTABLE and only knows the
-- STATIC governed relation set baked into the highway manifest. Dynamic
-- relations minted at ingest (EDEP_nsubj, DEP_obj, FEAT_case, ...) are NOT in
-- that set, so the C function returns FALSE for them even though they belong to
-- their family. Each dynamic child carries an IS_A edge to its static family
-- root in consensus (emitted by RelationTypeRegistry.SeedDynamic), so we resolve
-- membership by (a) the static C check OR (b) that IS_A -> family-root edge.
--
-- STABLE, not IMMUTABLE: it reads consensus. The static OR-branch delegates to
-- the exact same C function, so for static-only data this is bit-identical to
-- consensus.relation_type_in_family(); it only ADDS recognition of dynamic children.
DROP FUNCTION IF EXISTS laplace.relation_in_family(bytea, text);
CREATE OR REPLACE FUNCTION consensus.relation_in_family(p_type_id bytea, p_family text)
    RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT consensus.relation_type_in_family(p_type_id, p_family)
        OR EXISTS (
            SELECT 1 FROM laplace.consensus c
            WHERE c.subject_id = p_type_id
              AND c.type_id = laplace.relation_type_id('IS_A')
              AND c.object_id = laplace.relation_type_id(p_family)
              -- A REFUTED IS_A is not membership. consensus carries no outcome
              -- column -- refutation lives in the fold, and the walk's own law is
              -- that a non-positive score dead-ends rather than being walked. Bare
              -- row presence made "witnessed as NOT in this family" and "witnessed
              -- as in this family" the same answer.
              AND consensus.eff_mu(c.rating, c.rd) > 0
        )
$$;
-- relation_family_members: enumerate the STATIC governed members of a relation
-- family — the set-returning companion to consensus.relation_type_in_family(which can
-- only answer membership one id at a time). Callers that filtered big scans
-- with `consensus.relation_type_in_family(c.type_id, 'X')` per row could never use the
-- (subject_id, type_id) indexes; joining against this set makes the same
-- predicate sargable. Membership truth stays with the C check — this just
-- applies it over the RelationType entity roster (hundreds of rows) instead
-- of per consensus row (millions).
--
-- STATIC members only, exactly like relation_type_in_family. Callers that
-- also want dynamic children (IS_A -> family root) keep using
-- relation_in_family or the feat_dynamic CTE pattern.
--
-- No SET search_path so it inlines into the caller's FROM (the
-- consensus_by_ids precedent).
DROP FUNCTION IF EXISTS laplace.relation_family_members(text);
CREATE OR REPLACE FUNCTION consensus.relation_family_members(p_family text)
    RETURNS TABLE(id bytea)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT et.id
    FROM laplace.entities et
    WHERE et.type_id = laplace.entity_type_id('RelationType')
      AND consensus.relation_type_in_family(et.id, p_family)
$$;
-- The relation-type ids in a salience band, as an ARRAY the planner can prune with.
--
-- THE DEFECT THIS RETIRES. 25 sites across the read path wrote the band test as
-- `consensus.relation_highway_band(c.type_id) = N` directly against consensus. consensus is
-- LIST-partitioned by type_id and holds ~48M rows, so a function applied to the
-- partition key means: no partition pruning (the planner cannot evaluate a C
-- STABLE call at plan time), no index on the predicate, and one function
-- invocation PER EDGE SCANNED. The band is a property of ~221 relation types, and
-- it was being recomputed tens of millions of times to filter rows.
--
-- chat.sql.in's band lens already had the right shape and said why: resolve the
-- types up front, "there are ~189 governed types, so resolving the set up front
-- turns the filter into an indexed (subject_id, type_id) probe". This makes that
-- one call instead of a hand-rolled CTE at every site.
--
-- Applying relation_highway_band to the RelationType entities is fine and is the
-- point: 221 rows, once, versus 48M rows, per query. Same predicate, moved to the
-- small side of the join.
--
-- STABLE, not IMMUTABLE: relation_highway_band resolves through the manifest and
-- the entity set can gain dynamically-minted relations at ingest. PARALLEL SAFE
-- and no SET search_path, so it inlines into the caller's plan and the array
-- becomes a bound parameter rather than an opaque function scan.
CREATE OR REPLACE FUNCTION laplace.relation_band_types(p_band int)
    RETURNS bytea[]
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT COALESCE(array_agg(e.id), '{}'::bytea[])
    FROM laplace.entities e
    WHERE e.type_id = laplace.entity_type_id('RelationType')
      AND consensus.relation_highway_band(e.id) = p_band
$$;

-- Multi-band form. Callers testing several bands (the content bands 1/2/4/7 are
-- the common set) get one array rather than N calls unioned, so the probe stays a
-- single `= ANY`.
CREATE OR REPLACE FUNCTION laplace.relation_band_types(p_bands int[])
    RETURNS bytea[]
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT COALESCE(array_agg(e.id), '{}'::bytea[])
    FROM laplace.entities e
    WHERE e.type_id = laplace.entity_type_id('RelationType')
      AND consensus.relation_highway_band(e.id) = ANY (p_bands)
$$;

-- Retired before release: this helper shipped with no caller. Keep the DROP in
-- the extension script so an upgrade removes installations from the brief
-- broken-main window instead of preserving dead API surface indefinitely.
DROP FUNCTION IF EXISTS laplace.relation_family_type_ids(text);
DROP FUNCTION IF EXISTS laplace.relation_rank(bytea);
CREATE OR REPLACE FUNCTION consensus.relation_rank(p_type_id bytea) RETURNS float8
    LANGUAGE c IMMUTABLE STRICT PARALLEL SAFE AS 'laplace_substrate', 'pg_relation_rank';
-- consensus.relation_is_symmetric(type_id) -> is this relation symmetric?
--
-- Reads the compiled relation manifest, never a hand-kept list. A symmetric
-- assertion folds into ONE consensus cell oriented to subject = min(subject,
-- object) by hash bytes, so a read that probes subject_id alone sees such a
-- pair only from its lesser-hashed end. Any body that would otherwise hardcode
-- "the symmetric ones" resolves through here instead (§15, one body for one
-- truth): the manifest is where symmetry is declared, so the manifest is what
-- answers.
--
-- NULL for types absent from the static table (dynamic DEP_*/FEAT_*/EDEP_*
-- families). Callers COALESCE to false -- unknown symmetry must never widen a
-- read into the reverse direction.
CREATE OR REPLACE FUNCTION consensus.relation_is_symmetric(p_type_id bytea) RETURNS boolean
    LANGUAGE c IMMUTABLE STRICT PARALLEL SAFE AS 'laplace_substrate', 'pg_relation_is_symmetric';
-- Global serving order for consensus.top_relations(). relation_rank() is the
-- immutable manifest lookup; combining it with the stored Glicko conservative
-- estimate makes the exact leaderboard an index merge across physical leaves,
-- not one type-by-every-partition probe matrix.
CREATE INDEX IF NOT EXISTS consensus_edge_rank_btree ON consensus (
    (consensus.relation_rank(type_id)
        * ((rating - 2 * rd)::double precision)) DESC,
    witness_count DESC,
    type_id,
    subject_id,
    object_id
) WHERE object_id IS NOT NULL
    AND consensus.relation_rank(type_id) IS NOT NULL;
DROP FUNCTION IF EXISTS laplace.relation_canonical(bytea);
CREATE OR REPLACE FUNCTION consensus.relation_canonical(p_type_id bytea) RETURNS text
    LANGUAGE c IMMUTABLE STRICT PARALLEL SAFE AS 'laplace_substrate', 'pg_relation_canonical';
DROP FUNCTION IF EXISTS laplace.relation_rank_resolved(bytea);
CREATE OR REPLACE FUNCTION consensus.relation_rank_resolved(p_type_id bytea) RETURNS float8
    LANGUAGE c STABLE STRICT AS 'laplace_substrate', 'pg_relation_rank_resolved';
DROP FUNCTION IF EXISTS laplace.edge_rank(bytea, numeric);
CREATE OR REPLACE FUNCTION consensus.edge_rank(p_type bytea, p_eff_mu numeric)
    RETURNS double precision
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- The single salience-weighted edge ranking used by every consensus read:
    -- relation-type salience rank times the edge's confidence (eff_mu, scaled
    -- back to the /1e9 unit). Was copy-pasted verbatim into 8 ORDER BY clauses
    -- (consensus_out/in, completions, top_relations, consensus_out_readable,
    -- links, epistemic_status, consensus_walk_edges).
    --
    -- p_eff_mu is numeric, NOT double precision, on purpose: the literal 1e9 is
    -- a numeric constant, so the callers' original `consensus.eff_mu(...) / 1e9` was an
    -- EXACT numeric division; a float8 parameter would silently switch it to
    -- rounded float8 division and reorder rows that tie only in the ~15th digit
    -- (invisible on subject-filtered reads, but it reshuffles top_relations'
    -- whole-table LIMIT). Callers pass consensus.eff_mu(rating,rd) or a view's eff_mu_raw
    -- column -- both bigint, coerced exactly to numeric.
    --
    -- No SET search_path and NOT STRICT so it inlines into the caller's ORDER BY
    -- (a STRICT SQL function is not inlined when its args aren't provably
    -- non-null); NULL still propagates identically through relation_rank_resolved
    -- (itself STRICT) and the multiply, so dropping STRICT is semantically free.
    SELECT consensus.relation_rank_resolved(p_type) * (p_eff_mu / 1e9)
$$;
-- consensus.edges_raw() — THE consensus edge scan. Every other edge reader is a wrapper.
--
-- Six functions were the same scan with different axes hard-coded, and no caller
-- ever chose those axes — they inherited whichever function they happened to
-- reach for:
--
--   fn                              table       dir   rank       consensus.refuted
--   consensus_out                   consensus   out   consensus.edge_rank  INCLUDED
--   consensus_in                    consensus   in    consensus.edge_rank  INCLUDED
--   consensus_neighbors_directed    unrefuted   out   consensus.eff_mu     excluded
--   consensus_neighbors_undirected  unrefuted   both  consensus.eff_mu     excluded
--   explore_web_neighbors           consensus   both  consensus.eff_mu     INCLUDED
--   foundry_crawl_neighbors         consensus   out   consensus.eff_mu     INCLUDED
--
-- Four of the six return consensus.refuted edges. That is a semantic split — a consensus.refuted edge
-- is one the fold has rated BELOW neutral at its optimistic bound, i.e. the
-- substrate's own verdict is "this claim lost" — and it was distributed by
-- accident, not by design. consensus_out and consensus_in are the pair a new
-- caller reaches for first, and they are on the including side.
--
-- Now the axes are arguments with stated defaults, one implementation behind
-- them, and each historical function keeps its exact signature and output shape
-- as a thin wrapper pinning its own axes. Nothing changes for existing callers;
-- what changes is that the next reader does not have to diff six bodies to learn
-- which one excludes refutation.
--
-- RAW on purpose: ids and Glicko state, no labels. Labeling is a separate layer
-- (consensus.edges(), which wraps this and resolves in one realize_batch after the limit),
-- because the native walkers that consume edges want ids and would pay for text
-- they never realize.render.
DROP FUNCTION IF EXISTS laplace.edges_raw(bytea, text, bytea[], int, boolean, text);
-- BEGIN ATOMIC: GH #764. No SET search_path (#617/#860) — inlining into wrappers.
CREATE OR REPLACE FUNCTION consensus.edges_raw(
        p_subject   bytea,
        p_direction text    DEFAULT 'both',   -- 'out' | 'in' | 'both'
        p_types     bytea[] DEFAULT NULL,     -- NULL = every relation type
        p_limit     int     DEFAULT 40,       -- a QUERY limit over the ranking
        p_refuted   boolean DEFAULT false,    -- include edges the fold consensus.refuted
        p_rank      text    DEFAULT 'edge_rank')  -- 'edge_rank' | 'eff_mu'
    RETURNS TABLE(direction text, type_id bytea, neighbour_id bytea,
                  rating bigint, rd bigint, volatility bigint, witness_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT e.direction, e.type_id, e.neighbour_id,
           e.rating, e.rd, e.volatility, e.witness_count
    FROM (
        SELECT 'out'::text AS direction, c.type_id, c.object_id AS neighbour_id,
               c.rating, c.rd, c.volatility, c.witness_count
        FROM laplace.consensus c
        WHERE p_direction IN ('out', 'both')
          AND c.subject_id = p_subject
          AND c.object_id IS NOT NULL
          AND (p_types IS NULL OR c.type_id = ANY (p_types))
          AND (p_refuted OR NOT consensus.refuted(c.rating, c.rd))
        UNION ALL
        SELECT 'in'::text, c.type_id, c.subject_id,
               c.rating, c.rd, c.volatility, c.witness_count
        FROM laplace.consensus c
        WHERE p_direction IN ('in', 'both')
          AND c.object_id = p_subject
          -- SELF-EDGE, ONCE PER SCAN. An edge whose object IS its subject satisfies BOTH
          -- arms, so 'both' emitted it twice — identical in every column but `direction`.
          -- That is one row mirrored, not two observations, and it costs a slot in the
          -- LIMIT below: measured 2026-08-16 over twelve common nouns at p_limit=12, cat,
          -- green, house and run each spent 2 of 12 slots on the same mirrored self-edge,
          -- displacing real strands from a fixed-width beam.
          --
          -- Suppressed on the INBOUND arm because the outbound arm already emitted it and
          -- 'out' is the direction the core returns. Guarded on p_direction so an 'in'-only
          -- scan still yields it — there the outbound arm never ran, and dropping it would
          -- turn a duplicate into a silent omission.
          AND (p_direction = 'in' OR c.subject_id <> p_subject)
          AND (p_types IS NULL OR c.type_id = ANY (p_types))
          AND (p_refuted OR NOT consensus.refuted(c.rating, c.rd))
    ) e
    ORDER BY CASE WHEN p_rank = 'edge_rank'
                  THEN consensus.edge_rank(e.type_id, consensus.eff_mu(e.rating, e.rd))
                  ELSE (consensus.eff_mu(e.rating, e.rd))::float8 / 1e9
             END DESC,
             e.neighbour_id,
             e.type_id,
             CASE e.direction WHEN 'out' THEN 0 ELSE 1 END
    LIMIT p_limit;
END;
DROP FUNCTION IF EXISTS laplace.glicko2_neutral_mu();
CREATE OR REPLACE FUNCTION consensus.glicko2_neutral_mu() RETURNS bigint
    AS 'laplace_substrate', 'pg_laplace_glicko2_neutral_mu'
    LANGUAGE C IMMUTABLE        PARALLEL SAFE;
DROP FUNCTION IF EXISTS laplace.glicko2_initial_rd();
CREATE OR REPLACE FUNCTION consensus.glicko2_initial_rd() RETURNS bigint
    LANGUAGE sql IMMUTABLE        PARALLEL SAFE AS $$ SELECT 350000000000::bigint $$;
DROP FUNCTION IF EXISTS laplace.glicko2_initial_volatility();
CREATE OR REPLACE FUNCTION consensus.glicko2_initial_volatility() RETURNS bigint
    LANGUAGE sql IMMUTABLE        PARALLEL SAFE AS $$ SELECT 60000000::bigint $$;
DROP FUNCTION IF EXISTS laplace.glicko2_tau();
CREATE OR REPLACE FUNCTION consensus.glicko2_tau() RETURNS bigint
    LANGUAGE sql IMMUTABLE        PARALLEL SAFE AS $$ SELECT 500000000::bigint $$;
-- consensus.walk_edge_weight(rating, rd) -> float8
--
-- The signed Glicko-2 expected score around neutral: 2*E-1. Rating and RD are
-- the sufficient state produced by folding the complete observation history.
-- Applying witness_count/(witness_count+4) and exp(-rd/initial_rd) here used to
-- adjudicate the same evidence a second time with two non-Glicko transforms.
--
CREATE OR REPLACE FUNCTION consensus.walk_edge_weight(
        p_rating bigint, p_rd bigint)
    RETURNS double precision
    AS 'laplace_substrate', 'pg_laplace_walk_edge_weight'
    LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
-- Edge strength is the Glicko-2 expected score of this consensus state against
-- the certain neutral reference. Rating supplies the verdict; RD attenuates an
-- uncertain state toward 0.5 through Glicko's own g(phi) law. There is no
-- fitted divisor and no artificial floor.
--
-- The body is laplace_edge_strength() in spi_common.h:118, already shared by
-- foundry_crawl.c:233 and explore_web.c:237. This is only the SQL entry to it,
-- added for the same reason walk_edge_weight got one: while the formula was
-- reachable from C alone, any SQL surface that wanted the foundry's notion of
-- strength had to retype the algebra -- which is precisely how
-- consensus_adjacency ended up carrying a second, hand-typed copy of the
-- Glicko-complete formula that then had nothing binding it to the engine's.
-- One body, three callers, no restatement.
CREATE OR REPLACE FUNCTION consensus.edge_strength(p_rating bigint, p_rd bigint)
    RETURNS double precision
    AS 'laplace_substrate', 'pg_laplace_edge_strength'
    LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
-- OP4 WEIGHT -- the one edge-strength entry point (spec 37 §OP4, audit 38 §2).
--
-- The audit found SEVEN implementations carrying SIX semantics, and the reason
-- they multiplied is that they answer genuinely different questions. Collapsing
-- them to one formula would be wrong. Collapsing them to one ENTRY, with the
-- question named, is the fix: a caller must now say which weight it wants, and
-- every mode dispatches to the single existing body for that question rather
-- than to a retyped copy of it.
--
--   conservative  eff_mu in real units -- rating - 2*rd, the pessimistic bound.
--                 The RANKING key. Ordering only; it is not a sign or a gate
--                 (see mu/refuted.sql.in, which tests the OPTIMISTIC bound).
--   salience      relation-type rank x eff_mu -- what the consensus reads order
--                 by, so a strong edge of a weak relation type sorts below a
--                 weak edge of a strong one.
    --   complete      signed Glicko expectation around neutral. Rating/RD are
    --                 already the folded state of the observation population.
    --   strength      Glicko expected score against neutral, in [0, 1].
--
-- WHY p_mode IS AN ENUM AND NOT text. A text mode with a CASE would return NULL
-- for a typo, silently, and a NULL weight sorts as "no opinion" rather than as
-- an error -- the failure would surface as quietly wrong ORDER BY, which is the
-- hardest kind of defect to see in a ranked read. As an enum the typo is a type
-- error at parse time. Loud, and free at runtime.
--
-- NOT a replacement for the eff_mu index expressions. consensus_eff_mu_btree and
-- its siblings index literal (rating - 2*rd) and MUST keep doing so -- routing
-- them through a function would make the index expression non-matchable and cost
-- the index path (#860, the eff-mu-inlining-law). This entry is for BODIES.
--
-- No SET search_path and LANGUAGE sql so it inlines into the caller's ORDER BY.
-- Guarded rather than DROP TYPE ... CASCADE: a DROP would take consensus.weight
-- and every dependent body with it, mint a new OID, and re-create the exact
-- dependency breakage the purpose-schema move already hit on refuted(). There is
-- no CREATE TYPE IF NOT EXISTS, so the existence check is explicit. Adding a
-- value later is ALTER TYPE ... ADD VALUE, which is also non-destructive.
DO $weight_mode$
BEGIN
    IF to_regtype('consensus.weight_mode') IS NULL THEN
        CREATE TYPE consensus.weight_mode AS ENUM (
            'conservative', 'salience', 'complete', 'strength');
    END IF;
END
$weight_mode$;

-- A live pre-fold-law installation has this same public signature bound to the
-- retired three-argument walk_edge_weight(rating, rd, witnesses). CREATE OR
-- REPLACE cannot run after that base is dropped because the installed body pins
-- its OID through pg_depend. Drop the dependent while the old base still exists,
-- then recreate it immediately below against the two-argument folded-state law.
-- The signature itself has no live dependents (checked by the upgrade gate).
DROP FUNCTION IF EXISTS consensus.weight(
    bigint, bigint, consensus.weight_mode, bigint, bytea);

CREATE OR REPLACE FUNCTION consensus.weight(
        p_rating        bigint,
        p_rd            bigint,
        p_mode          consensus.weight_mode DEFAULT 'conservative',
        p_witness_count bigint DEFAULT NULL,
        p_type          bytea  DEFAULT NULL)
    RETURNS double precision
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT CASE p_mode
        WHEN 'conservative' THEN consensus.eff_mu(p_rating, p_rd)::float8 / 1e9
        WHEN 'salience'     THEN consensus.edge_rank(
                                     p_type, consensus.eff_mu(p_rating, p_rd)::numeric)
        WHEN 'complete'     THEN consensus.walk_edge_weight(p_rating, p_rd)
        WHEN 'strength'     THEN consensus.edge_strength(p_rating, p_rd)
    END;
END;
-- consensus.belief_logit(rating, rd) -- eff_mu expressed as log-odds. THE weight for any
-- ranked surface, and the only one.
--
-- eff_mu (rating - 2*rd) is a conservative BOUND in rating points, not a log-odds.
-- Exponentiating it directly ranks the same and normalises to nothing meaningful, because
-- the units are wrong: exp() of a rating point needs a divisor, and every divisor invented
-- for it is a dial. This converts the bound into Glicko-2's own scale instead, so exp() of
-- the result is a Bradley-Terry weight on belief.
--
-- NO DIAL IS INTRODUCED. 1500 comes from consensus.glicko2_neutral_mu(), the body the folder
-- already uses, and 400/ln(10) is Glicko-2's definitional rating scale -- the constant that
-- makes its underlying logistic a base-10 400-point curve. Neither is free to choose.
--
-- WHY NOT g(phi)*mu. Glicko-2's own attenuation applied to the RAW rating,
-- g(phi) = 1/sqrt(1 + 3*phi^2/pi^2) with phi = rd/(400/ln 10), was written here first and
-- then DELETED rather than kept beside this one. It penalises uncertainty by a different
-- law: eff_mu SUBTRACTS 2*rd without bound, g(phi) MULTIPLIES by a saturating factor in
-- (0,1]. Measured on one pair -- rating 2000/rd 100 gives eff_mu 1800 and g(phi)*mu 2.7434,
-- rating 2100/rd 200 gives eff_mu 1700 and 2.9159 -- the two order the same two edges
-- oppositely. A surface that ORDERS by one and WEIGHTS by the other has a top row that is
-- not its heaviest row, so "take the best" and "sample the distribution" return different
-- objects from one call. INVENTION §5 settles which survives: belief is rating - 2*rd and
-- all ranked reads order by it, so the weight moved onto belief rather than the order
-- moving off it.
--
-- It was deleted rather than left uncalled for two reasons. A correct-looking second weight
-- standing beside the real one is the trap cmake/toolchains/gcc-deterministic.cmake already
-- is in this tree -- authoritative name, defensible body, silently different answer. And an
-- uncalled function has no losing condition: nothing exercises it, so nothing can ever show
-- it wrong.
--
-- NOT a replacement for eff_mu. eff_mu stays the indexed ranking key (#860, the
-- eff-mu-inlining-law) and this is never an ORDER BY; it is strictly monotone in eff_mu, so
-- ordering by either gives the same sequence, and the indexes only match the literal form.
CREATE OR REPLACE FUNCTION consensus.belief_logit(p_rating bigint, p_rd bigint)
    RETURNS double precision
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    SELECT ((consensus.eff_mu(p_rating, p_rd) - consensus.glicko2_neutral_mu()) / 1e9)
         / (400 / ln(10));
END;
-- Plan Phase 8 (Build-A-Bear): re-fold laplace.attestations from ONLY the named sources
-- into a scoped consensus edge set — the "I know kung fu" package fold. The
-- caller materializes this as pg_temp.consensus, which shadows laplace.consensus
-- inside every plane function for that connection (pg_temp resolves first), so
-- the entire synthesis reads the scoped world with no plane changes.
--
-- EXACT refold (2026-07-29, graduated from the v1 neutral-opponent
-- approximation): evidence now persists the fold's exact inputs per row —
-- sum_score_fp1e9 (the total fold score, accumulated across merges) and
-- opponent_rd_fp1e9 (the per-deposit trust phi) — so the refold replays each
-- attestation as its own uniform-opponent period through the consensus_fold
-- aggregate: the SQL surface of the same native scalar the ingest fold runs
-- (glicko2_fold_uniform_period), seeded from the neutral prior. games =
-- observation_count; the score total and phi are the persisted values, no
-- outcome reconstruction and no invented opponent. Partial order within a cell
-- is (last_observed_at, id) — deterministic; the ingest's exact arrival order
-- is the one thing evidence does not record.
DROP FUNCTION IF EXISTS laplace.scoped_consensus(bytea[]);
CREATE OR REPLACE FUNCTION consensus.scoped_consensus(p_source_ids bytea[])
    RETURNS TABLE(id bytea, subject_id bytea, type_id bytea, object_id bytea,
                  rating bigint, rd bigint, volatility bigint, witness_count bigint,
                  last_observed_at timestamptz)
    LANGUAGE sql VOLATILE AS $$
    SELECT laplace.consensus_id(f.subject_id, f.type_id, f.object_id),
           f.subject_id, f.type_id, f.object_id,
           (f.acc).rating, (f.acc).rd, (f.acc).volatility,
           (f.acc).witness_count, f.last_ts
    FROM (
        SELECT a.subject_id, a.type_id, a.object_id,
               laplace.consensus_fold(false, NULL::bigint, NULL::bigint, NULL::bigint,
                              a.opponent_rating_fp1e9,
                              a.opponent_rd_fp1e9,
                              GREATEST(a.observation_count, 1),
                              a.sum_score_fp1e9,
                              consensus.glicko2_tau()
                              ORDER BY a.last_observed_at, a.id) AS acc,
               max(a.last_observed_at) AS last_ts
        FROM laplace.attestations a
        WHERE a.source_id = ANY(p_source_ids)
        GROUP BY a.subject_id, a.type_id, a.object_id
    ) f
$$;
DO $do$
DECLARE
    aggregate_exists boolean := to_regprocedure(
        'consensus_fold(boolean,bigint,bigint,bigint,bigint,bigint,bigint,bigint,bigint)') IS NOT NULL;
    legacy_aggregate_exists boolean := to_regprocedure(
        'consensus_fold(boolean,bigint,bigint,bigint,bigint,bigint,bigint,bigint)') IS NOT NULL;
    result_type_exists boolean := to_regtype('consensus_fold_result') IS NOT NULL;
BEGIN
    IF NOT result_type_exists THEN
        EXECUTE 'DROP FUNCTION IF EXISTS consensus_fold_final(internal)';
        EXECUTE $c$ CREATE TYPE consensus_fold_result AS (
            rating bigint, rd bigint, volatility bigint, witness_count bigint) $c$;
    END IF;
    EXECUTE $c$ CREATE OR REPLACE FUNCTION consensus_fold_step(
            internal, boolean, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint)
        RETURNS internal LANGUAGE C PARALLEL RESTRICTED
        AS 'laplace_substrate', 'pg_laplace_consensus_fold_step_v2' $c$;
    EXECUTE $c$ CREATE OR REPLACE FUNCTION consensus_fold_step(
            internal, boolean, bigint, bigint, bigint, bigint, bigint, bigint, bigint)
        RETURNS internal LANGUAGE C PARALLEL RESTRICTED
        AS 'laplace_substrate', 'pg_laplace_consensus_fold_step' $c$;
    EXECUTE $c$ CREATE OR REPLACE FUNCTION consensus_fold_final(internal)
        RETURNS consensus_fold_result LANGUAGE C PARALLEL RESTRICTED
        AS 'laplace_substrate', 'pg_laplace_consensus_fold_final' $c$;
    IF NOT aggregate_exists THEN
        EXECUTE $c$ CREATE AGGREGATE consensus_fold(
                boolean, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint) (
            SFUNC     = consensus_fold_step,
            STYPE     = internal,
            FINALFUNC = consensus_fold_final
        ) $c$;
    END IF;
    IF NOT legacy_aggregate_exists THEN
        EXECUTE $c$ CREATE AGGREGATE consensus_fold(
                boolean, bigint, bigint, bigint, bigint, bigint, bigint, bigint) (
            SFUNC     = consensus_fold_step,
            STYPE     = internal,
            FINALFUNC = consensus_fold_final
        ) $c$;
    END IF;
END $do$;
-- The inline consensus fold — identity-routed, dedup-first, native.
--
-- NATIVE (2026-07-21, GH #565): the body lives in C (src/fold_route.c).
-- Consensus is content: dedup it the way ingest dedups laplace.entities. The batch is
-- split by what it IS, per relation type. Phase 1 partitions the batch with
-- PostgreSQL's own HASH support function and reads each row from its exact leaf;
-- phase 3 sends matched rows through the primary-key conflict arbiter and novel rows
-- through target-free inserts. The historical MERGE survives only as the bounded
-- concurrent-insert collision fallback. Existing cells re-fold from stored state;
-- novel cells fold from the neutral prior.
--
-- History of the SQL forms this replaces (all measured, kept so nobody
-- re-tries them):
--  * Runtime-key MERGE: fanned out across ALL consensus leaves because type_id
--    arrived from the join (2026-07-16, the CILI 7-minute peg). This no longer
--    describes the native router: it embeds type_id as a plan literal, and PG18
--    prunes to the owning LIST partition before the matched/unmatched join.
--  * per-type loop re-unnesting the FULL arrays each iteration: O(2·N·T)
--    materializations (21s insert / 60s re-fold at N=200k,T=10).
--  * BATCH-ONCE temp table (2026-07-16): correct and O(N) — but still a fresh
--    CREATE TEMP TABLE + CREATE INDEX + ANALYZE on every call, and generic
--    per-type statements re-planned per call.
--
-- The native routing groups the batch by type in C and executes one SESSION-CACHED
-- prepared statements per type whose type_id is a LITERAL in the plan text (HTAB
-- of type -> SPI_keepplan'd plans in TopMemoryContext). The prior read groups
-- subjects by physical HASH remainder once and gives each exact leaf its own
-- indexed/hash-capable batch; matched persistence uses ON CONFLICT on the declared PK, and novel
-- persistence never reads the target. There is no temp table, per-batch ANALYZE, or
-- UPDATE-then-NOT-EXISTS double probe.
-- The function-local settings replan against the actual leaf batch and leave all
-- three join/access methods available. There is no parent Append below the type
-- partition and therefore no rows-times-eight probe shape: each subject appears
-- in exactly one statement against exactly one physical relation. PostgreSQL can
-- use indexed probes for a small leaf batch or scan that one owning leaf once for
-- a corpus-sized matched batch.
-- These settings restore the caller's values on return, including errors.
--
-- One implementation per fact, preserved:
--  * the Glicko fold runs the SAME core (glicko2_init + glicko2_fold_grouped_period)
--    the scalar laplace_glicko2_accumulate_period wraps — computed in one native
--    pass per type run for BOTH arms: matched cells fold from their stored prior
--    (read and row-locked by a per-type FOR UPDATE probe), novel cells from the
--    neutral prior; the rating period IS the batch. The scalar remains in the
--    collision MERGE only as the lazy MATCHED fallback for a cell inserted
--    concurrently between the prior read and phase-3 persistence;
--  * cell ids are computed in C through the SAME core hash the SQL
--    laplace.consensus_id() wraps — blake3(subject || type || COALESCE(object, 16 zero
--    bytes)) — byte-identical layout;
--  * the duplicate-cell contract check raises the same cardinality_violation.
--
-- NO mask queue here: the caller deposits highway bits INLINE for this same
-- delta (consensus.highway_mask_deposit); highway_mask_dirty is populated only by the
-- repair verbs, which need to CLEAR bits (per-source evict) — something an
-- OR-accumulate deposit cannot express.
--
-- Contract with the caller (ConsensusAccumulatingWriter) — unchanged:
--   * arrays are parallel and CLIENT-DEDUPED per call — one row per
--     (subject, type, object) cell;
--   * each cell carries exact grouped (opponent rating, phi, games, score sum)
--     rating-period inputs through the flat group arrays and offsets;
--   * rows arrive sorted by (type, subject, id) — partition-key order; the
--     router only needs same-type rows ADJACENT and remains correct (merely
--     one extra plan execution) if they are not.
DROP FUNCTION IF EXISTS laplace.consensus_upsert(bytea[], bytea[], bytea[], bigint[], bigint[], bigint[], timestamptz[]);
-- The 7-arg forms are DROPPED, not left alongside: adding a DEFAULTed parameter
-- via CREATE OR REPLACE would leave the old arity resident as a separate
-- overload, and a 7-argument call would then be ambiguous.
DROP FUNCTION IF EXISTS consensus.upsert(bytea[], bytea[], bytea[], bigint[], bigint[], bigint[], timestamptz[]);
DROP FUNCTION IF EXISTS consensus.upsert(bytea[], bytea[], bytea[], bigint[], bigint[], bigint[], timestamptz[], bigint[]);
DROP FUNCTION IF EXISTS consensus.upsert_type(bytea, bytea[], bytea[], bigint[], bigint[], bigint[], timestamptz[]);
DROP FUNCTION IF EXISTS consensus.upsert_type(bytea, bytea[], bytea[], bigint[], bigint[], bigint[], timestamptz[], bigint[]);
CREATE OR REPLACE FUNCTION consensus.upsert(
    p_subjects bytea[],
    p_types    bytea[],
    p_objects  bytea[],
    p_phis     bigint[],
    p_games    bigint[],
    p_sums     bigint[],
    p_ts       timestamptz[],
    -- The opponent each witness presents (GH #1321). DEFAULT NULL so every
    -- existing caller keeps folding against neutral, unchanged, until it starts
    -- passing attestations.opponent_rating_fp1e9.
    p_opp_ratings bigint[] DEFAULT NULL,
    -- Exact rating-period groups are flat arrays. offsets has one entry per
    -- cell plus a terminal entry; each cell owns [offsets[i], offsets[i+1]).
    -- Omitting all five preserves the historical one-opponent-per-cell API.
    p_period_offsets bigint[] DEFAULT NULL,
    p_period_opp_ratings bigint[] DEFAULT NULL,
    p_period_phis bigint[] DEFAULT NULL,
    p_period_games bigint[] DEFAULT NULL,
    p_period_sums bigint[] DEFAULT NULL)
    RETURNS bigint
    AS 'laplace_substrate', 'pg_laplace_consensus_upsert'
    LANGUAGE C VOLATILE
    SET plan_cache_mode = force_custom_plan
    SET enable_material = off
    SET enable_hashjoin = on
    SET enable_mergejoin = on
    SET enable_seqscan = on;

-- Direct routed form for first-party type lanes. The type is part of every cell
-- identity but is transmitted once per set operation, not once per row.
CREATE OR REPLACE FUNCTION consensus.upsert_type(
    p_type     bytea,
    p_subjects bytea[],
    p_objects  bytea[],
    p_phis     bigint[],
    p_games    bigint[],
    p_sums     bigint[],
    p_ts       timestamptz[],
    p_opp_ratings bigint[] DEFAULT NULL,
    p_period_offsets bigint[] DEFAULT NULL,
    p_period_opp_ratings bigint[] DEFAULT NULL,
    p_period_phis bigint[] DEFAULT NULL,
    p_period_games bigint[] DEFAULT NULL,
    p_period_sums bigint[] DEFAULT NULL)
    RETURNS bigint
    AS 'laplace_substrate', 'pg_laplace_consensus_upsert_type'
    LANGUAGE C VOLATILE
    SET plan_cache_mode = force_custom_plan
    SET enable_material = off
    SET enable_hashjoin = on
    SET enable_mergejoin = on
    SET enable_seqscan = on;

-- The physical owner of one consensus key, resolved by the same PostgreSQL
-- partition support function as the native ingest writer.  This is the single
-- routing authority for the rare non-ingest mutations (decay, source eviction):
-- callers mutate ONLY the returned leaf and never plan against the parent.
CREATE OR REPLACE FUNCTION consensus.partition_leaf(
    p_type bytea,
    p_subject bytea)
    RETURNS regclass
    AS 'laplace_substrate', 'pg_laplace_consensus_partition_leaf'
    LANGUAGE C STABLE STRICT PARALLEL RESTRICTED;
-- Routed attestation observation merge — the present-row half of the apply.
--
-- NATIVE (2026-07-21, GH #565): the body lives in C (src/fold_route.c). The
-- write lane's probe already proved every row here EXISTS; the only job is
-- observation_count accumulation + last_observed_at advance, routed to the
-- LIST(type_id) -> HASH(subject_id) leaves the caller already knows.
--
-- History of the SQL forms this replaces (all measured, kept so nobody
-- re-tries them):
--  * naive UPDATE ... FROM unnest(ids): no partition key -> Append-scans EVERY
--    leaf per chunk (measured 2026-07-19 on the OMW seed: ~10s per 32k chunk
--    flat, ~9 minutes of a 19-minute step).
--  * plpgsql loop with the type in a VARIABLE: an UPDATE's target result
--    relations are opened and locked at PLAN time, and a variable plans
--    generically -- every call opened all ~1,600 leaves (measured 2026-07-21:
--    one 32k chunk at 93.8% CPU for 58 minutes, 10.2 GB relcache RSS, zero
--    rows updated).
--  * plpgsql temp table + per-type EXECUTE format(%L): correct pruning at
--    last -- but a fresh temp table + CREATE INDEX + ANALYZE per call, and a
--    full re-plan of a partitioned UPDATE per type per chunk, forever.
--
-- The native routing groups the batch by type in C and executes a
-- SESSION-CACHED prepared plan per type whose type_id is a LITERAL in the plan
-- text (HTAB of type -> SPI_keepplan'd plan in TopMemoryContext): LIST pruning
-- once per (backend, type) and reused across every chunk and every apply,
-- HASH pruning per row, no temp table, no ANALYZE, no re-plan.
--
-- Contract with the caller (NpgsqlWorkingSetApply) — unchanged:
--   * arrays are parallel and CLIENT-DEDUPED per call — one row per
--     attestation id (a duplicate id would double-apply the UPDATE);
--   * every id was probe-verified present under the apply advisory lock, so the
--     one set-based MERGE intentionally owns only a MATCHED arm (there is no
--     row loop and no ON CONFLICT fallback);
--   * rows arrive sorted by (type, subject, id) — partition-key order, so
--     cross-writer lock acquisition stays globally ordered; the router only
--     needs same-type rows ADJACENT and remains correct (merely one extra
--     plan execution) if they are not.
--
-- Fold-input columns (2026-07-29, greenfield): sum_score_fp1e9 accumulates
-- ADDITIVELY alongside observation_count — evidence stays the exact record of
-- what was folded. opponent_rd_fp1e9 is deliberately NOT touched: it is the
-- per-deposit phi, a pure function of source trust x relation rank, and the
-- attestation identity pins (subject, type, object, source, context) — every
-- merge of the same row re-witnesses under the same source and relation, so
-- the incoming phi IS the stored phi; the merge keeps the existing value.
-- fold_replayable is monotone false: once any observation consumed a transient
-- calibration, the durable categorical sum can never become a refold input.
DROP FUNCTION IF EXISTS laplace.attestation_merge(bytea[], bytea[], bytea[], bigint[], bigint[], timestamptz[]);
DROP FUNCTION IF EXISTS consensus.attestation_merge(bytea[], bytea[], bytea[], bigint[], bigint[], timestamptz[]);
DROP FUNCTION IF EXISTS consensus.attestation_merge_type(bytea, bytea[], bytea[], bigint[], bigint[], timestamptz[]);
CREATE OR REPLACE FUNCTION consensus.attestation_merge(
    p_ids      bytea[],
    p_types    bytea[],
    p_subjects bytea[],
    p_games    bigint[],
    p_sums     bigint[],
    p_ts       timestamptz[],
    p_fold_replayable boolean[])
    RETURNS bigint
    AS 'laplace_substrate', 'pg_laplace_attestation_merge'
    LANGUAGE C VOLATILE;

-- First-party ingest owns type-major runs and uses this direct routed form.
-- Keeping type scalar avoids serializing/deconstructing 16 duplicate bytes per
-- row and lets native pass every value array directly to the cached MERGE plan.
CREATE OR REPLACE FUNCTION consensus.attestation_merge_type(
    p_type     bytea,
    p_ids      bytea[],
    p_subjects bytea[],
    p_games    bigint[],
    p_sums     bigint[],
    p_ts       timestamptz[],
    p_fold_replayable boolean[])
    RETURNS bigint
    AS 'laplace_substrate', 'pg_laplace_attestation_merge_type'
    LANGUAGE C VOLATILE;
CREATE OR REPLACE FUNCTION realize.canonical_id(p_name text) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT AS $$
    SELECT public.laplace_hash128_blake3(convert_to(p_name, 'UTF8'))
$$;
CREATE TABLE IF NOT EXISTS laplace.canonical_names (
    id   bytea PRIMARY KEY CHECK (octet_length(id) = 16),
    name text  NOT NULL
);

-- The reverse direction is a real query, and until 2026-08-23 it had no index.
--
-- id -> name is the primary key. name -> id had nothing, so every `WHERE name = ...`
-- or `name IN (...)` seq-scanned all 3,387,109 rows. Measured on the live substrate:
-- Parallel Seq Scan, 677,421 rows removed by filter, 50,638 buffers shared hit, which
-- made generation.separator_ids() cost 317 ms warm -- paid once per call by
-- generation.trajectory_continuations AND structural.geometry_successors_batch, so
-- once per generated token, for a set its own header calls "bounded by the alphabet,
-- not by the corpus".
--
-- NOT UNIQUE. The name -> id direction is not injective by construction: an entity's
-- id is the content hash of what it IS, and canonical_names records what a source
-- CALLS it, so two ids may legitimately carry one name (tests/sql/generation_corpus.sql
-- registers blake3('test/corpus/zs-category') under 'unicode/category/Zs/v1', which is
-- the attested-mapping law the separator lane depends on). A unique index would reject
-- that fixture and, worse, would make the constraint pass or fail on seed order.
CREATE INDEX IF NOT EXISTS canonical_names_name_btree
    ON laplace.canonical_names (name);
DROP FUNCTION IF EXISTS laplace.register_canonical(text);
CREATE OR REPLACE FUNCTION realize.register_canonical(p_name text) RETURNS bytea
    LANGUAGE sql AS $$
    INSERT INTO laplace.canonical_names (id, name)
    VALUES (realize.canonical_id(p_name), p_name)
    ON CONFLICT (id) DO NOTHING;
    SELECT realize.canonical_id(p_name)
$$;
CREATE OR REPLACE FUNCTION realize.codepoint_for_id(p_id bytea)
    RETURNS integer
    AS 'laplace_substrate', 'pg_laplace_codepoint_for_id'
    LANGUAGE C STABLE   STRICT  PARALLEL SAFE;
DROP FUNCTION IF EXISTS laplace.is_all_whitespace(text);
CREATE OR REPLACE FUNCTION realize.is_all_whitespace(p_text text)
    RETURNS boolean
    AS 'laplace_substrate', 'pg_laplace_is_all_whitespace'
    LANGUAGE C STABLE   STRICT  PARALLEL SAFE;
CREATE OR REPLACE FUNCTION realize.constituents(p_id bytea)
    RETURNS TABLE(ordinal integer, child_id bytea, run_length integer, flags bigint)
    LANGUAGE sql STABLE
    AS $$
    SELECT u.ordinal, u.entity_id, u.run_length, u.flags
    FROM (
        SELECT w.trajectory AS traj
        FROM laplace.v_word_points w
        WHERE w.id = p_id AND w.trajectory IS NOT NULL
        ORDER BY w.physicality_id
        LIMIT 1
    ) t
    CROSS JOIN LATERAL public.laplace_trajectory_constituents(t.traj) AS u
    ORDER BY 1
$$;
-- Native, level-synchronous constituent closure.  The C SRF selects one
-- deterministic type-1 manifest for every frontier node, expands each packed
-- RLE record as an ordered edge (retaining run_length and flags), and performs
-- no recursive SQL or per-node query loop.
DROP FUNCTION IF EXISTS laplace.constituents_closure(bytea[], integer);
CREATE OR REPLACE FUNCTION realize.constituents_closure(
    p_roots bytea[],
    p_max_depth integer DEFAULT 0
)
RETURNS TABLE(
    parent_id bytea,
    ordinal integer,
    child_id bytea,
    run_length integer,
    flags bigint
)
AS 'laplace_substrate', 'pg_laplace_constituents_closure'
LANGUAGE C STABLE PARALLEL RESTRICTED;
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.vertex_atom(bigint);
CREATE OR REPLACE FUNCTION realize.vertex_atom(p_flags bigint) RETURNS integer
    LANGUAGE sql IMMUTABLE        PARALLEL SAFE
BEGIN ATOMIC
    SELECT public.laplace_vertex_atom(p_flags);
END;
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.vertex_tier(bigint);
CREATE OR REPLACE FUNCTION realize.vertex_tier(p_flags bigint) RETURNS smallint
    LANGUAGE sql IMMUTABLE        PARALLEL SAFE
BEGIN ATOMIC
    SELECT public.laplace_vertex_tier(p_flags);
END;
-- Exact rendering follows the complete, cycle-safe constituent DAG. A positive
-- depth remains available when a caller explicitly requests a preview.
CREATE OR REPLACE FUNCTION realize.render_text(p_id bytea, p_max_depth integer DEFAULT 0)
    RETURNS text
    AS 'laplace_substrate', 'pg_laplace_render_text'
    LANGUAGE C STABLE;
CREATE OR REPLACE FUNCTION realize.render_text_fast(p_id bytea, p_max_depth integer DEFAULT 8)
    RETURNS text
    AS 'laplace_substrate', 'pg_laplace_render_text_fast'
    LANGUAGE C STABLE;
-- Same exact-render law as render_text: zero walks the complete cycle-safe DAG;
-- a positive depth is caller-owned preview policy, never an infrastructure cap.
CREATE OR REPLACE FUNCTION realize.render_text_batch(p_ids bytea[], p_max_depth integer DEFAULT 0)
    RETURNS text[]
    AS 'laplace_substrate', 'pg_laplace_render_text_batch'
    LANGUAGE C STABLE;
-- realize.realize() for N ids in one call: 6 batched SPI round-trips regardless of N
-- (5 candidate arms + ONE shared realize.render_text_batch at depth 24), positionally
-- aligned text[] out. Reproduces the scalar COALESCE ladder exactly
-- (resolve_name's lang-only branch -> realize.render -> translation -> canonical ->
-- gloss) and ABSTAINS with NULL — never hex. See src/realize_batch.c for the
-- parity notes. This is the shared labeling primitive the serving surface
-- calls AFTER its rank/LIMIT step (the librarian hands the survivor id-array
-- to the machine room).
DROP FUNCTION IF EXISTS laplace.realize_batch(bytea[], bytea);
CREATE OR REPLACE FUNCTION realize.batch(p_ids bytea[], p_lang bytea DEFAULT NULL)
    RETURNS text[]
    AS 'laplace_substrate', 'pg_laplace_realize_batch'
    LANGUAGE C STABLE;
-- Position-aligned, exact null-context implementation of realize.resolve_name.
-- The native core owns HAS_NAME/HAS_NAME_ALIAS and synset-lemma election once;
-- scalar wrappers and every display projection build on this fact.
CREATE OR REPLACE FUNCTION realize.resolve_name_batch(
    p_ids bytea[], p_lang bytea DEFAULT NULL)
    RETURNS text[]
    LANGUAGE C STABLE PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_resolve_name_batch';
-- Exact realize.render() ladder for an aligned id array. Graph/name work is
-- batched; only cheap codepoint and final text projection remain per element.
DROP FUNCTION IF EXISTS laplace.render_batch(bytea[]);
CREATE OR REPLACE FUNCTION realize.render_batch(p_ids bytea[])
    RETURNS text[]
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    WITH inp AS MATERIALIZED (
        SELECT u.id, u.ord
        FROM unnest(p_ids) WITH ORDINALITY AS u(id, ord)
    ), batches AS MATERIALIZED (
        SELECT realize.resolve_name_batch(p_ids) AS names,
               realize.render_text_batch(p_ids) AS bodies
    )
    SELECT COALESCE(array_agg(
               COALESCE(n.name,
                        chr(realize.codepoint_for_id(i.id)),
                        b.names[i.ord],
                        b.bodies[i.ord])
               ORDER BY i.ord), '{}'::text[])
    FROM inp i
    CROSS JOIN batches b
    LEFT JOIN laplace.canonical_names n ON n.id = i.id;
END;
-- Exact realize.label() cleanup/fallback over an aligned id array. Name and
-- render ladders execute once for the whole input; regex cleanup is text-only.
CREATE OR REPLACE FUNCTION realize.label_batch(p_ids bytea[])
    RETURNS text[]
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    WITH inp AS MATERIALIZED (
        SELECT u.id, u.ord
        FROM unnest(p_ids) WITH ORDINALITY AS u(id, ord)
    ), batches AS MATERIALIZED (
        SELECT realize.resolve_name_batch(p_ids) AS names,
               realize.render_batch(p_ids) AS rendered
    ), cleaned AS (
        SELECT i.id, i.ord, b.names[i.ord] AS name,
               regexp_replace(
               regexp_replace(
                   regexp_replace(
                       regexp_replace(
                           regexp_replace(
                               regexp_replace(
                                   regexp_replace(
                                       regexp_replace(b.rendered[i.ord],
                                           '^substrate/(?:type|relation|trust_class|source|entity)/(.*)/v1$', '\1'),
                                       '^substrate/pos/(?:probationary/[^/]+/)?(.+)/v1$', '\1'),
                                   '^source/file/(.+)/v1$', '\1'),
                               '^repo:(.+)/v1$', '\1'),
                           '^language:([a-z]{3})$', '\1'),
                       '^ud/feature/(.+)$', '\1'),
                   '^tiny-codes/concept/(.+)/v1$', '\1'),
               '^(i[0-9]+|[0-9]{6,}-[nvarspNVARSP])$', '') AS rendered
        FROM inp i CROSS JOIN batches b
    )
    SELECT COALESCE(array_agg(
               COALESCE(c.name, NULLIF(c.rendered, ''))
               ORDER BY c.ord), '{}'::text[])
    FROM cleaned c;
END;

CREATE OR REPLACE FUNCTION converse.label_or_hex_batch(p_ids bytea[])
    RETURNS text[]
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    SELECT COALESCE(array_agg(
               COALESCE(l.label, 'unrealized entity') ORDER BY l.ord),
               '{}'::text[])
    FROM unnest(realize.label_batch(p_ids)) WITH ORDINALITY AS l(label, ord);
END;
CREATE OR REPLACE FUNCTION lexical.type_label_batch(p_ids bytea[])
    RETURNS text[]
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    SELECT COALESCE(array_agg(lower(replace(u.s, '_', ' ')) ORDER BY u.ord),
                    '{}'::text[])
    FROM unnest(realize.render_batch(p_ids)) WITH ORDINALITY AS u(s, ord);
END;
CREATE OR REPLACE FUNCTION realize.render(p_id bytea) RETURNS text
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(
        (SELECT n.name FROM @extschema@.canonical_names n WHERE n.id = p_id),
        -- Perfcache-backed: authoritative for a valid tier-0 codepoint on its own
        -- (a hash128 match against the reverse index *is* the proof), independent
        -- of whether that codepoint has been given its own entities row yet. Do
        -- NOT gate this on an entities lookup -- that would defeat the whole point
        -- of having a perfcache and would misrender orphaned-but-valid tier-0 ids
        -- via the slower fallbacks below (or worse, as opaque hex).
        chr(realize.codepoint_for_id(p_id)),

        -- Name-edge resolution goes through the one shared primitive rather than a
        -- private HAS_NAME_ALIAS-only argmax: realize.resolve_name() consults HAS_NAME
        -- (primary) + HAS_NAME_ALIAS + the synset-lemma path as families and
        -- abstains (NULL) when there is no grounded name, letting the fallbacks
        -- below run. It is reached only after the canonical-name and codepoint
        -- fast paths above, so tier-0 glyph reconstruction is unchanged.
        realize.resolve_name(p_id),
        realize.render_text(p_id))
$$;
DROP FUNCTION IF EXISTS laplace.register_canonicals(text[]);
CREATE OR REPLACE FUNCTION realize.register_canonicals(p_names text[]) RETURNS bigint
    LANGUAGE sql AS $$
    WITH requested(name) AS MATERIALIZED (
        SELECT DISTINCT btrim(n)
        FROM unnest(COALESCE(p_names, ARRAY[]::text[])) AS names(n)
        WHERE n IS NOT NULL AND btrim(n) <> ''
    ), inserted AS (
        INSERT INTO laplace.canonical_names (id, name)
        SELECT realize.canonical_id(name), name
        FROM requested
        ORDER BY name
        ON CONFLICT (id) DO NOTHING
        RETURNING 1
    )
    SELECT count(*)::bigint FROM inserted
$$;
DROP FUNCTION IF EXISTS laplace.entity_facets(bytea);
DROP FUNCTION IF EXISTS ops.entity_facets(bytea);
CREATE OR REPLACE FUNCTION ops.entity_facets(p_id bytea)
    RETURNS TABLE(tier smallint, type_id bytea)
    LANGUAGE sql STABLE
    AS $$
    SELECT e.tier, e.type_id FROM laplace.entities e WHERE e.id = p_id
$$;

-- LIVE-UPGRADE DROP ORDER. These BEGIN-ATOMIC functions pin the exact OIDs of
-- bases that are recompiled later in manifest.upgrade:
--
--   consensus.browse_named_entities
--       -> structural.word_containers_containing_all
--       -> ops.entity_facets_batch
--       -> consensus.relation_family_ids
--
-- ops.entity_facets_batch is the first base encountered by the upgrade. Drop
-- the installed dependents here, in dependent-first order, so every later base
-- can be replaced with RESTRICT semantics intact. Their normal modules recreate
-- them later after all bases exist. Do not use CASCADE: an unlisted dependent is
-- a contract change that scripts/check-upgrade-drop-order.py must expose.
DROP FUNCTION IF EXISTS consensus.browse_named_entities(bytea[], bytea, int, int, int);
DROP FUNCTION IF EXISTS structural.word_containers_containing_all(bytea[], int);

-- Batch form for serving/browse paths.  One set read over surviving ids; callers
-- must not LATERAL-loop the scalar facet reader or hand-read laplace.entities.
DROP FUNCTION IF EXISTS ops.entity_facets_batch(bytea[]);
CREATE OR REPLACE FUNCTION ops.entity_facets_batch(p_ids bytea[])
    RETURNS TABLE(entity_id bytea, tier smallint, type_id bytea)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT e.id, e.tier, e.type_id
    FROM laplace.entities e
    WHERE e.id = ANY(COALESCE(p_ids, '{}'::bytea[]));
END;
DROP FUNCTION IF EXISTS laplace.entity_physicalities(bytea);
DROP FUNCTION IF EXISTS ops.entity_physicalities(bytea);
CREATE OR REPLACE FUNCTION ops.entity_physicalities(p_id bytea)
    RETURNS TABLE(type smallint, x double precision, y double precision,
                  z double precision, m double precision,
                  radius double precision, n_constituents integer,
                  hilbert_index bytea)
    LANGUAGE sql STABLE
    AS $$
    SELECT p.type, ST_X(p.coord), ST_Y(p.coord), ST_Z(p.coord), ST_M(p.coord),
           p.radius_origin, p.n_constituents, p.hilbert_index
    FROM laplace.physicalities p
    WHERE p.entity_id = p_id
    ORDER BY p.type, p.id
$$;
DROP FUNCTION IF EXISTS laplace.entity_physicality_coords(bytea[]);
DROP FUNCTION IF EXISTS ops.entity_physicality_coords(bytea[]);
CREATE OR REPLACE FUNCTION ops.entity_physicality_coords(p_ids bytea[])
    RETURNS TABLE(entity_id bytea, x double precision, y double precision,
                  z double precision, m double precision)
    LANGUAGE sql STABLE AS $$
    SELECT DISTINCT ON (w.id) w.id AS entity_id,
           ST_X(w.coord), ST_Y(w.coord), ST_Z(w.coord), ST_M(w.coord)
    FROM laplace.v_word_points w
    JOIN unnest(p_ids) AS u(id) ON u.id = w.id
    WHERE w.coord IS NOT NULL
    ORDER BY w.id, w.physicality_id
$$;
-- Declared unqualified, so it installed as laplace.attestations_out while every caller
-- asks for ops.attestations_out -- 42883 at runtime. See ops.evidence_receipt.
DROP FUNCTION IF EXISTS laplace.attestations_out(bytea, integer);
CREATE OR REPLACE FUNCTION ops.attestations_out(p_id bytea, p_limit integer DEFAULT 40)
    RETURNS TABLE(type_id bytea, object_id bytea, source_id bytea, context_id bytea,
                  outcome smallint, observation_count bigint)
    LANGUAGE sql STABLE
    AS $$
    SELECT a.type_id, a.object_id, a.source_id, a.context_id,
           a.outcome, a.observation_count
    FROM laplace.attestations a
    WHERE a.subject_id = p_id



    ORDER BY consensus.relation_rank_resolved(a.type_id) DESC, a.observation_count DESC, a.outcome DESC
    LIMIT p_limit
$$;
-- Declared unqualified, so it installed as laplace.attestations_in while every caller
-- asks for ops.attestations_in -- 42883 at runtime. See ops.evidence_receipt.
DROP FUNCTION IF EXISTS laplace.attestations_in(bytea, integer);
CREATE OR REPLACE FUNCTION ops.attestations_in(p_id bytea, p_limit integer DEFAULT 40)
    RETURNS TABLE(subject_id bytea, type_id bytea, source_id bytea, context_id bytea,
                  outcome smallint, observation_count bigint)
    LANGUAGE sql STABLE
    AS $$
    SELECT a.subject_id, a.type_id, a.source_id, a.context_id,
           a.outcome, a.observation_count
    FROM laplace.attestations a
    WHERE a.object_id = p_id

    ORDER BY consensus.relation_rank_resolved(a.type_id) DESC, a.observation_count DESC, a.outcome DESC
    LIMIT p_limit
$$;
DROP FUNCTION IF EXISTS laplace.top_relations(integer, bytea);
CREATE OR REPLACE FUNCTION consensus.top_relations(p_limit integer DEFAULT 50, p_type bytea DEFAULT NULL)
    RETURNS TABLE(subject_id bytea, type_id bytea, object_id bytea, eff_mu numeric, witnesses bigint)
-- No SET search_path — blocks inlining, costs the consensus index path. GH #860.
    LANGUAGE sql STABLE AS $$
    -- Exact global top-k over the index's identical immutable expression. The
    -- previous implementation took p_limit from each relation type, but the
    -- LATERAL type parameter could not prune the LIST(type_id) parent. At the
    -- measured foundation shape that became 231 types x 224 leaves = 51,744
    -- filtered index probes and held the warehouse request for ~33 seconds.
    --
    -- The manifest rank is the governed rank for stored relation types (and the
    -- only rank indexable without baking mutable consensus ancestry into an
    -- index). Ungoverned types have no leaderboard score and remain absent, as
    -- they were when relation_rank_resolved returned NULL.
    SELECT c.subject_id,
           c.type_id,
           c.object_id,
           consensus.eff_mu_display(c.rating, c.rd),
           c.witness_count
    FROM laplace.consensus c
    WHERE c.object_id IS NOT NULL
      AND consensus.relation_rank(c.type_id) IS NOT NULL
      AND (p_type IS NULL OR c.type_id = p_type)
    -- DESC, NOT "DESC NULLS LAST". The supporting index is declared DESC, which in
    -- PostgreSQL means NULLS FIRST, so this one keyword made it unusable: the sort
    -- orderings do not match and the planner falls back to scanning every partition.
    --
    -- Measured 2026-08-23 on the live substrate: this function seq-scanned all consensus
    -- partitions and top-N heapsorted 126,378,526 rows to return 10, while
    -- <partition>_expr_witness_count_type_id_subject_id_idx -- 14 GB across 192
    -- partitions, built for exactly this ORDER BY -- had ZERO scans since the database
    -- was created. Dropping the NULLS LAST turns it into an index scan returning one row
    -- per partition.
    --
    -- Nothing is lost by the change: the WHERE clause already excludes rows where
    -- relation_rank(type_id) IS NULL, and rating/rd are NOT NULL, so the sort expression
    -- cannot be NULL for any row this reaches. NULLS FIRST and NULLS LAST are the same
    -- order over a set with no nulls.
    ORDER BY (consensus.relation_rank(c.type_id)
                  * consensus.eff_mu(c.rating, c.rd)::double precision) DESC,
             c.witness_count DESC,
             c.type_id,
             c.subject_id,
             c.object_id
    LIMIT p_limit
$$;
DROP FUNCTION IF EXISTS laplace.completions(bytea, integer);
CREATE OR REPLACE FUNCTION consensus.completions(p_subject bytea, p_limit integer DEFAULT 40)
    RETURNS TABLE(object_id bytea, type_id bytea, eff_mu numeric, witnesses bigint)
-- No SET search_path — blocks inlining, costs the consensus index path. GH #860.
    LANGUAGE sql STABLE AS $$
    SELECT c.object_id, c.type_id, c.eff_mu, c.witness_count
    FROM laplace.v_consensus_resolved c
    WHERE c.subject_id = p_subject AND c.object_id IS NOT NULL
    ORDER BY consensus.edge_rank(c.type_id, c.eff_mu_raw) DESC
    LIMIT p_limit
$$;
-- Outbound edges of an entity. Thin wrapper over consensus.edges_raw(), which is the one
-- consensus scan; this pins the axes this signature has always had — outbound,
-- consensus.edge_rank ordering, and REFUTED EDGES INCLUDED. That last one is now visible
-- rather than implicit: pass through consensus.edges_raw(p_refuted => false) if you want
-- only claims the fold has not rated below neutral.
DROP FUNCTION IF EXISTS laplace.consensus_out(bytea, integer);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.consensus_out(p_id bytea, p_limit integer DEFAULT 40)
    RETURNS TABLE(type_id bytea, object_id bytea, rating bigint, rd bigint,
                  volatility bigint, witness_count bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT e.type_id, e.neighbour_id, e.rating, e.rd, e.volatility, e.witness_count
    FROM consensus.edges_raw(p_id, 'out', NULL, p_limit, true, 'edge_rank') e;
END;
DROP FUNCTION IF EXISTS laplace.consensus_by_ids(bytea[]);
CREATE OR REPLACE FUNCTION consensus.by_ids(p_ids bytea[])
    RETURNS TABLE(id bytea, eff_mu double precision, rd double precision,
                  witness_count double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Batch consensus lookup by primary id, returning the confidence axis the
    -- Chess lane needs. Replaces four hand-copied reads (LearnedPst,
    -- SubstrateStateValuer, SubstrateTurnHost, SubstrateRootBias) that each
    -- open-coded `(rating - 2*rd)::double precision` instead of consensus.eff_mu(); since
    -- consensus.eff_mu(r,d) IS rating - 2*rd the value is identical, but centralized on
    -- the canonical helper. No SET search_path so it inlines into the caller's
    -- FROM (the state-valuation path is hot).
    SELECT c.id, consensus.eff_mu(c.rating, c.rd)::double precision,
           c.rd::double precision, c.witness_count::double precision
    FROM laplace.consensus c
    WHERE c.id = ANY(p_ids)
$$;

DROP FUNCTION IF EXISTS laplace.consensus_by_ids(bytea[], bytea);
CREATE OR REPLACE FUNCTION consensus.by_ids(p_ids bytea[], p_type bytea)
    RETURNS TABLE(id bytea, eff_mu double precision, rd double precision,
                  witness_count double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Type-pruned batch lookup. consensus is LIST-partitioned by type_id, so the
    -- 1-arg form above Append-scans every relation-type partition per call — on
    -- the chess state-valuation path that is ~150 partition probes for ids that
    -- are all OUTCOME- or MOVE-typed. Callers that know the edge type (they
    -- built the ids via ConsensusKeys.EdgeId(subject, type, object)) pass it
    -- here and the scan prunes to the one partition that can hold the rows.
    SELECT c.id, consensus.eff_mu(c.rating, c.rd)::double precision,
           c.rd::double precision, c.witness_count::double precision
    FROM laplace.consensus c
    WHERE c.id = ANY(p_ids)
      AND c.type_id = p_type
$$;
-- Inbound edges of an entity. Thin wrapper over consensus.edges_raw(); pins inbound,
-- consensus.edge_rank ordering, consensus.refuted edges INCLUDED — the axes this signature has
-- always carried, now stated instead of inferred from the body.
DROP FUNCTION IF EXISTS laplace.consensus_in(bytea, integer);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.consensus_in(p_id bytea, p_limit integer DEFAULT 40)
    RETURNS TABLE(subject_id bytea, type_id bytea, rating bigint, rd bigint,
                  volatility bigint, witness_count bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT e.neighbour_id, e.type_id, e.rating, e.rd, e.volatility, e.witness_count
    FROM consensus.edges_raw(p_id, 'in', NULL, p_limit, true, 'edge_rank') e;
END;
DROP FUNCTION IF EXISTS laplace.classify_circuit(bytea[]);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.classify_circuit(p_pairs bytea[])
    RETURNS TABLE(subject_id bytea, object_id bytea, type_id bytea, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH pairs AS (
        SELECT substring(p FROM 1 FOR 16)  AS subj,
               substring(p FROM 17 FOR 16) AS obj
        FROM unnest(p_pairs) AS p
        WHERE octet_length(p) = 32
    ),
    ranked AS (
        SELECT pr.subj, pr.obj, c.type_id,
               consensus.eff_mu_display(c.rating, c.rd) AS emu,
               c.witness_count                AS w,
               row_number() OVER (
                   PARTITION BY pr.subj, pr.obj
                   ORDER BY consensus.eff_mu(c.rating, c.rd) DESC) AS rn
        FROM pairs pr
        JOIN laplace.consensus c
          ON c.subject_id = pr.subj AND c.object_id = pr.obj
    )
    SELECT subj, obj, type_id, emu, w
    FROM ranked
    WHERE rn = 1;
END;
-- Phase-5a candidate admission.  The caller supplies the complete selected
-- vocabulary and walks this stable keyset page-by-page; p_page_size is a wire
-- bound, never a ranked top-K or semantic threshold.
DROP FUNCTION IF EXISTS consensus.circuit_candidates(bytea[], bytea, bytea, bytea, integer);
CREATE OR REPLACE FUNCTION consensus.circuit_candidates(
    p_vocabulary bytea[], p_type_id bytea,
    p_after_subject bytea, p_after_object bytea, p_page_size integer)
    RETURNS TABLE(subject_id bytea, object_id bytea, type_id bytea, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH selected(id) AS MATERIALIZED (
        SELECT DISTINCT token_id
        FROM unnest(p_vocabulary) AS token_id
        WHERE octet_length(token_id) = 16
    )
    SELECT c.subject_id, c.object_id, c.type_id,
           consensus.eff_mu_display(c.rating, c.rd), c.witness_count
    FROM laplace.consensus c
    JOIN selected subject ON subject.id = c.subject_id
    JOIN selected object ON object.id = c.object_id
    WHERE c.type_id = p_type_id
      AND c.object_id IS NOT NULL
      AND (p_after_subject IS NULL
           OR (c.subject_id, c.object_id) > (p_after_subject, p_after_object))
    ORDER BY c.subject_id, c.object_id
    LIMIT p_page_size;
END;
-- Phase-5b OP3 nomination. Existing graph kinds bound the pair estate but do
-- not confirm p_target_type; two independent model witnesses must still agree
-- on that exact target kind before OP9. The complete selected vocabulary is
-- walked by endpoint keyset. p_page_size is only a wire/memory bound.
DROP FUNCTION IF EXISTS consensus.circuit_pair_proposals(bytea[], bytea, boolean, bytea, bytea, integer);
CREATE OR REPLACE FUNCTION consensus.circuit_pair_proposals(
    p_vocabulary bytea[], p_target_type bytea, p_target_symmetric boolean,
    p_after_subject bytea, p_after_object bytea, p_page_size integer)
    RETURNS TABLE(subject_id bytea, object_id bytea, basis_type_ids bytea[])
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH selected(id) AS MATERIALIZED (
        SELECT DISTINCT token_id
        FROM unnest(p_vocabulary) AS token_id
        WHERE octet_length(token_id) = 16
    ), nominated AS MATERIALIZED (
        SELECT CASE WHEN p_target_symmetric AND c.subject_id > c.object_id
                    THEN c.object_id ELSE c.subject_id END AS subject_id,
               CASE WHEN p_target_symmetric AND c.subject_id > c.object_id
                    THEN c.subject_id ELSE c.object_id END AS object_id,
               c.type_id AS basis_type_id
        FROM laplace.consensus c
        JOIN selected subject ON subject.id = c.subject_id
        JOIN selected object ON object.id = c.object_id
        WHERE c.object_id IS NOT NULL
          AND c.type_id <> p_target_type
          AND NOT EXISTS (
              SELECT 1
              FROM laplace.consensus existing
              WHERE existing.type_id = p_target_type
                AND (
                    (existing.subject_id = c.subject_id
                     AND existing.object_id = c.object_id)
                    OR (p_target_symmetric
                        AND existing.subject_id = c.object_id
                        AND existing.object_id = c.subject_id)))
    )
    SELECT n.subject_id, n.object_id,
           array_agg(DISTINCT n.basis_type_id ORDER BY n.basis_type_id)
    FROM nominated n
    WHERE p_after_subject IS NULL
       OR (n.subject_id, n.object_id) > (p_after_subject, p_after_object)
    GROUP BY n.subject_id, n.object_id
    ORDER BY n.subject_id, n.object_id
    LIMIT p_page_size;
END;
-- p_ordinal_continuity and p_use_geometry both default false for one reason:
-- laplace.physicalities is HASH(id) over 64 partitions, and both features join
-- it by entity_id, which cannot prune. Every probe fans out across all 64.
-- MEASURED live, 200-node frontier / 21,413 candidate edges: the batch edge
-- query costs 30,305ms with the coordinate joins and 408ms without.
-- See generate_walk.c above WALK_BATCH_QUERY.
DROP FUNCTION IF EXISTS laplace.walk_branches(bytea, bytea, int, int, bytea, bytea[], bool);
DROP FUNCTION IF EXISTS consensus.walk_branches(bytea, bytea, int, int, bytea, bytea[], bool);
CREATE OR REPLACE FUNCTION consensus.walk_branches(
    p_prompt              bytea,
    p_type                bytea    DEFAULT NULL,
    p_depth               int      DEFAULT 4,
    p_breadth             int      DEFAULT 5,
    p_intent_mask         bytea    DEFAULT NULL,
    p_topic_bias          bytea[]  DEFAULT NULL,
    p_ordinal_continuity  bool     DEFAULT false,
    p_use_geometry        bool     DEFAULT false)
    RETURNS TABLE(depth int, path bytea[], types bytea[], entity_id bytea,
                  eff_mu numeric, path_mu numeric, witnesses bigint)
    AS 'laplace_substrate', 'pg_laplace_walk_branches'
    LANGUAGE C STABLE;
DROP FUNCTION IF EXISTS laplace.walk_strongest(bytea, bytea, int);
CREATE OR REPLACE FUNCTION consensus.walk_strongest(
    p_prompt bytea, p_type bytea DEFAULT NULL, p_depth int DEFAULT NULL)
    RETURNS TABLE(step int, type_id bytea, entity_id bytea, eff_mu numeric)
    AS 'laplace_substrate', 'pg_laplace_walk_strongest'
    LANGUAGE C STABLE;
DROP FUNCTION IF EXISTS laplace.consensus_stats();
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.stats()
    RETURNS TABLE(evidence_rows bigint, consensus_rows bigint, dedup_ratio numeric,
                  avg_witnesses numeric, max_witnesses bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT a.cnt, c.cnt,
           round(a.cnt::numeric / NULLIF(c.cnt, 0), 3),
           c.avg_w, c.max_w
    FROM (SELECT count(*)::bigint AS cnt FROM laplace.attestations) a,
         (SELECT count(*)::bigint AS cnt,
                 round(avg(witness_count), 3) AS avg_w,
                 max(witness_count)::bigint AS max_w
          FROM laplace.consensus) c;
END;
DROP FUNCTION IF EXISTS laplace.chess_moves(bytea, integer);
CREATE OR REPLACE FUNCTION chess.moves(p_position bytea, p_limit integer DEFAULT 12)
    RETURNS TABLE(next_position bytea, eff_mu double precision, rd double precision,
                  witness_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Opening explorer over the rated MOVE web: every continuation the substrate has
    -- ever witnessed out of one position, ranked by the conservative estimate.
    --
    -- MEASURED 2026-08-21: the deployed pre-repair corpus was EMPTY because the typed-
    -- trajectory refactor stopped materializing this bounded cell. Current PGN/live/self-
    -- play record paths restore one position→position observation per witnessed ply;
    -- older corpora require the ChessTransitions reconstruction operation. The cell is bounded by deterministic
    -- legal transitions, while evidence contexts retain the contributing playings.
    --
    -- Do not reconstruct this index on a request by unpacking every complete game
    -- trajectory. The initial position occurs in roughly 1.64 million trajectories in
    -- the measured corpus; the exact keyed MOVE cells exist specifically so this read is
    -- proportional to legal continuations rather than historical games.
    -- Position ids are COMPOSED (ChessCompose merkle path), never
    -- realize.canonical_id(surface) — callers hold them from composing a board state or
    -- from a prior chess_moves step. Rides
    -- consensus_subject_type_eff_mu_btree (subject_id, type_id, rating-2*rd DESC
    -- WHERE object_id IS NOT NULL); consensus.eff_mu() inlines to that exact expression.
    -- LIMIT is the only cut — no floors, no thresholds.
    -- consensus.eff_mu/rd are returned in DISPLAY units (consensus.eff_mu_display's /1e9 round), never
    -- raw fp1e9; the ORDER BY stays on raw consensus.eff_mu() so the index expression matches.
    SELECT c.object_id,
           consensus.eff_mu_display(c.rating, c.rd)::double precision,
           round((c.rd / 1e9)::numeric, 3)::double precision,
           c.witness_count
    FROM laplace.consensus c
    WHERE c.subject_id = p_position
      AND c.type_id = laplace.relation_type_id('MOVE')
      AND c.object_id IS NOT NULL
    ORDER BY consensus.eff_mu(c.rating, c.rd) DESC
    LIMIT p_limit
$$;
-- The learned statistic keyed on the object the substrate actually stores.
-- A piece-square cell is a projection (a dot product over every arrival path);
-- a move is a lookup. 7,797 distinct tier-2 move entities cover 1.6M games, so
-- this folds unbounded testimony into a small bounded table. No replay: ordered
-- move ids are the record and ply parity is the mover.
-- p_games is REQUIRED to be bounded by default. The first cut shipped DEFAULT 0
-- (whole corpus), which folds ~135M trajectory constituents through SPI in one
-- call and does not return on a 1.6M-game corpus -- a query surface must not have
-- a hang as its default. This is a PASS, not a lookup: the statistic it produces
-- is 7,797 bounded rows and belongs materialized in laplace.consensus, read O(1)
-- thereafter, which is exactly what chess.moves already reads and what the rated
-- MOVE web was designed to hold. Materializing it is the follow-up; until then
-- callers must state how much testimony they are willing to pay for.
DROP FUNCTION IF EXISTS chess.learned_moves(integer);
CREATE OR REPLACE FUNCTION chess.learned_moves(p_games integer DEFAULT 20000)
    RETURNS TABLE(move_id bytea, plays bigint, mover_score double precision)
    LANGUAGE C STABLE PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_chess_learned_moves';
DROP FUNCTION IF EXISTS laplace.chess_player_moves(bytea, bytea, boolean, integer);
CREATE OR REPLACE FUNCTION chess.player_moves(
        p_position bytea, p_player bytea, p_as_white boolean,
        p_limit integer DEFAULT 12)
    RETURNS TABLE(next_position bytea, games bigint, score double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- The transition decomposer materializes every witnessed position --MOVE--> position
    -- with context_id = the playing event. Resolve this player's playing contexts first,
    -- then join those contexts to exact position evidence. This follows the indexed
    -- player -> playing -> transition route and never opens complete line trajectories.
    --
    -- One playing contributes at most once to the same successor even if another source has
    -- witnessed the identical transition. Colour and result are still joined on both the line
    -- and playing context, so a shared line cannot leak another playing's side or score.
    WITH rel AS MATERIALIZED (
        SELECT consensus.relation_family_ids('HAS_RESULT') AS result_types
    ),
    player_playings AS MATERIALIZED (
        SELECT h.subject_id AS line_id, h.context_id AS playing_id,
               max(h.observation_count)::bigint AS games
        FROM laplace.attestations h
        WHERE h.type_id = laplace.relation_type_id(
                  CASE WHEN p_as_white THEN 'HAS_WHITE' ELSE 'HAS_BLACK' END)
          AND h.object_id = p_player
          AND h.context_id IS NOT NULL
        GROUP BY h.subject_id, h.context_id
    ),
    player_steps AS MATERIALIZED (
        SELECT t.object_id AS next_position, pp.line_id, pp.playing_id, pp.games
        FROM player_playings pp
        JOIN laplace.attestations t ON t.context_id = pp.playing_id
        WHERE t.subject_id = p_position
          -- Keep the immutable family directly in the predicate so PostgreSQL prunes the
          -- LIST relation partitions before joining the player's playing contexts.
          AND t.type_id = ANY (consensus.relation_family_ids('MOVE'))
          AND t.object_id IS NOT NULL
        GROUP BY t.object_id, pp.line_id, pp.playing_id, pp.games
    ),
    results AS MATERIALIZED (
        SELECT ps.next_position, ps.line_id, ps.playing_id, ps.games,
               max(r.object_id) AS result_id
        FROM player_steps ps
        JOIN laplace.attestations r
          ON r.subject_id = ps.line_id
         AND r.context_id = ps.playing_id
        JOIN rel ON r.type_id = ANY (rel.result_types)
        GROUP BY ps.next_position, ps.line_id, ps.playing_id, ps.games
    ),
    scored_steps AS MATERIALIZED (
        SELECT r.next_position, r.games,
               chess.outcome(p_as_white, r.result_id)::double precision / 2.0 AS score
        FROM results r
        WHERE chess.outcome(p_as_white, r.result_id) IS NOT NULL
    )
    SELECT next_position,
           sum(games)::bigint AS games,
           (sum(score * games) / sum(games))::double precision AS score
    FROM scored_steps
    GROUP BY next_position
    ORDER BY games DESC
    LIMIT p_limit
$$;
DROP FUNCTION IF EXISTS laplace.consensus_stats_approx();
CREATE OR REPLACE FUNCTION consensus.stats_approx()
    RETURNS TABLE(evidence_rows bigint, consensus_rows bigint, dedup_ratio numeric,
                  avg_witnesses numeric, max_witnesses bigint)
    LANGUAGE sql STABLE AS $$
    WITH est AS (
        SELECT c.relname,
               GREATEST(c.reltuples, 0)::bigint AS est_rows
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        -- SCHEMA-QUALIFIED, never current_schema(). Under the deployed search_path
        -- ("$user", public) current_schema() is public, so this looked for
        -- attestations/consensus there, found neither, and returned a row of ALL
        -- NULLS in 1.8ms -- fast enough to pass a timing sweep while answering
        -- nothing. The only current_schema() call in the function surface.
        WHERE n.nspname = '@extschema@'
          AND c.relname IN ('attestations', 'consensus')
    )
    SELECT (SELECT est_rows FROM est WHERE relname = 'attestations'),
           (SELECT est_rows FROM est WHERE relname = 'consensus'),
           round((SELECT est_rows FROM est WHERE relname = 'attestations')::numeric
                 / NULLIF((SELECT est_rows FROM est WHERE relname = 'consensus'), 0), 3),
           NULL::numeric,
           NULL::bigint
$$;
-- Declared unqualified, so it installed as laplace.consensus_out_readable while every caller
-- asks for ops.consensus_out_readable -- 42883 at runtime. See ops.evidence_receipt.
DROP FUNCTION IF EXISTS laplace.consensus_out_readable(bytea, integer);
CREATE OR REPLACE FUNCTION ops.consensus_out_readable(p_id bytea, p_limit integer DEFAULT 40)
    RETURNS TABLE(type text, object text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE
    AS $$
    -- Rank + LIMIT on bare ids in the inner query, render only the survivors (the define/examples
    -- pattern). realize.render() is a heavy non-inlinable call; at the same level as ORDER BY..LIMIT it was
    -- projected over EVERY out-edge of the subject before the cut — thousands of renders to return 40.
    WITH ranked AS MATERIALIZED (
        SELECT c.type_id, c.object_id, c.eff_mu, c.witness_count,
               consensus.edge_rank(c.type_id, c.eff_mu_raw) AS er
        FROM laplace.v_consensus_resolved c
        WHERE c.subject_id = p_id
        ORDER BY er DESC
        LIMIT p_limit
    ), numbered AS MATERIALIZED (
      SELECT s.*, row_number() OVER (ORDER BY s.er DESC,s.type_id,s.object_id) AS rn FROM ranked s
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(type_id ORDER BY rn)) AS types,
             realize.render_batch(array_agg(object_id ORDER BY rn)) AS objects FROM numbered
    )
    SELECT b.types[s.rn], b.objects[s.rn], s.eff_mu, s.witness_count
    FROM numbered s CROSS JOIN batch b ORDER BY s.rn
$$;
-- BEGIN ATOMIC: GH #764.
-- Declared unqualified, so it installed as laplace.top_relations_readable while every caller
-- asks for ops.top_relations_readable -- 42883 at runtime. See ops.evidence_receipt.
DROP FUNCTION IF EXISTS laplace.top_relations_readable(integer, bytea);
CREATE OR REPLACE FUNCTION ops.top_relations_readable(p_limit integer DEFAULT 10, p_type bytea DEFAULT NULL)
    RETURNS TABLE(subject text, type text, object text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH raw AS MATERIALIZED (
      SELECT t.subject_id,t.type_id,t.object_id,t.eff_mu,t.witnesses,t.rn
      FROM consensus.top_relations(p_limit,p_type) WITH ORDINALITY
        AS t(subject_id,type_id,object_id,eff_mu,witnesses,rn)
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(subject_id ORDER BY rn)) AS subjects,
             realize.render_batch(array_agg(type_id ORDER BY rn)) AS types,
             realize.render_batch(array_agg(object_id ORDER BY rn)) AS objects FROM raw
    )
    SELECT b.subjects[t.rn],b.types[t.rn],b.objects[t.rn],t.eff_mu,t.witnesses
    FROM raw t CROSS JOIN batch b ORDER BY t.rn;
END;
DROP FUNCTION IF EXISTS laplace.attestation_response(bytea, bytea, bytea[], bytea, integer);
DROP FUNCTION IF EXISTS ops.attestation_response(bytea, bytea, bytea[], bytea, integer);
CREATE OR REPLACE FUNCTION ops.attestation_response(
    p_subject_id        bytea,
    p_relation_type_id  bytea,
    p_source_scope      bytea[]    DEFAULT NULL,
    p_context_id        bytea      DEFAULT NULL,
    p_top_k             integer    DEFAULT 32
)
RETURNS TABLE(
    object_id        bytea,
    combined_eff_mu  double precision,
    source_count     integer,
    rating_fp1e9     bigint,
    rd_fp1e9         bigint
)
LANGUAGE sql STABLE
    AS $$
    SELECT c.object_id,
           (consensus.eff_mu(c.rating, c.rd) / 1e9)::double precision,
           c.witness_count::integer,
           c.rating,
           c.rd
    FROM laplace.consensus c
    WHERE c.subject_id = p_subject_id
      AND c.type_id    = p_relation_type_id
      AND c.object_id IS NOT NULL
      AND (
            (p_source_scope IS NULL AND p_context_id IS NULL)
         OR EXISTS (
                SELECT 1 FROM laplace.attestations a
                WHERE a.subject_id = c.subject_id
                  AND a.type_id    = c.type_id
                  AND a.object_id IS NOT DISTINCT FROM c.object_id
                  AND (p_source_scope IS NULL OR a.source_id = ANY(p_source_scope))
                  AND (p_context_id   IS NULL OR a.context_id IS NOT DISTINCT FROM p_context_id)
            )
          )
    ORDER BY consensus.eff_mu(c.rating, c.rd) DESC
    LIMIT GREATEST(p_top_k, 0)
$$;
DROP FUNCTION IF EXISTS laplace.attestation_response_type(bytea, bytea, bytea[], bytea, integer);
DROP FUNCTION IF EXISTS ops.attestation_response_type(bytea, bytea, bytea[], bytea, integer);
CREATE OR REPLACE FUNCTION ops.attestation_response_type(
    p_subject_id   bytea,
    p_relation_type_id      bytea,
    p_source_scope bytea[]    DEFAULT NULL,
    p_context_id   bytea      DEFAULT NULL,
    p_top_k        integer    DEFAULT 32
)
RETURNS TABLE(
    object_id        bytea,
    combined_eff_mu  double precision,
    source_count     integer,
    rating_fp1e9     bigint,
    rd_fp1e9         bigint
)
LANGUAGE sql STABLE
    AS $$
    SELECT * FROM ops.attestation_response(p_subject_id, p_relation_type_id, p_source_scope, p_context_id, p_top_k)
$$;
DROP FUNCTION IF EXISTS laplace.attestation_unary_response(bytea, bytea, bytea[], bytea);
DROP FUNCTION IF EXISTS ops.attestation_unary_response(bytea, bytea, bytea[], bytea);
