-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.evidence_count(bytea, bytea, bytea);

CREATE OR REPLACE FUNCTION ops.evidence_count(
    p_type bytea DEFAULT NULL, p_source bytea DEFAULT NULL, p_object bytea DEFAULT NULL)
    RETURNS bigint
    LANGUAGE sql STABLE
BEGIN ATOMIC
    -- Branch on which optional filters are present so each present filter is a
    -- plain equality the planner can index (attestations_type_btree /
    -- _source_btree / _object_btree, bitmap-AND'd when several are set). The
    -- prior `(p_param IS NULL OR col = p_param)` conjunction is planned once
    -- with the params unbound, so the OR-with-NULL kept the index unusable and
    -- every call (including the per-ingest verify gate) seqscanned. Each CASE
    -- arm reproduces exactly the residual predicate the original conjunction
    -- reduces to for that NULL combination, so results are byte-identical.
    SELECT CASE
        WHEN p_type IS NULL AND p_source IS NULL AND p_object IS NULL
            THEN (SELECT count(*) FROM laplace.attestations)
        WHEN p_type IS NULL AND p_source IS NULL
            THEN (SELECT count(*) FROM laplace.attestations a WHERE a.object_id = p_object)
        WHEN p_type IS NULL AND p_object IS NULL
            THEN (SELECT count(*) FROM laplace.attestations a WHERE a.source_id = p_source)
        WHEN p_source IS NULL AND p_object IS NULL
            THEN (SELECT count(*) FROM laplace.attestations a WHERE a.type_id = p_type)
        WHEN p_type IS NULL
            THEN (SELECT count(*) FROM laplace.attestations a
                  WHERE a.source_id = p_source AND a.object_id = p_object)
        WHEN p_source IS NULL
            THEN (SELECT count(*) FROM laplace.attestations a
                  WHERE a.type_id = p_type AND a.object_id = p_object)
        WHEN p_object IS NULL
            THEN (SELECT count(*) FROM laplace.attestations a
                  WHERE a.type_id = p_type AND a.source_id = p_source)
        ELSE (SELECT count(*) FROM laplace.attestations a
              WHERE a.type_id = p_type AND a.source_id = p_source AND a.object_id = p_object)
    END;
END;
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.consensus_count(bytea);

CREATE OR REPLACE FUNCTION ops.consensus_count(p_type bytea DEFAULT NULL)
    RETURNS bigint
    LANGUAGE sql STABLE
BEGIN ATOMIC
    -- Branch on the optional filter so the provided-type path carries a plain
    -- equality (consensus_type_btree index-only count) instead of the
    -- `(p_type IS NULL OR type_id = p_type)` OR-form, which a non-inlined SQL
    -- function plans generically with p_type unbound and therefore cannot index
    -- -> full seqscan. Semantics identical: p_type NULL counts every row;
    -- p_type set counts exactly that type.
    SELECT CASE
        WHEN p_type IS NULL
            THEN (SELECT count(*) FROM laplace.consensus)
            ELSE (SELECT count(*) FROM laplace.consensus c WHERE c.type_id = p_type)
    END;
END;
-- String body (not BEGIN ATOMIC): depends on v_word_points which extension
-- upgrades recreate in the same script; parse-time resolution can miss mid-upgrade
-- the same way source_roster hit v_attestation_readable (GH #764).
DROP FUNCTION IF EXISTS laplace.content_count(bytea);

CREATE OR REPLACE FUNCTION ops.content_count(p_source bytea DEFAULT NULL)
    RETURNS bigint
    LANGUAGE sql STABLE
AS $$
    SELECT CASE
        WHEN p_source IS NULL THEN
            (SELECT count(*) FROM laplace.v_word_points)
        ELSE
            -- Dedup the source's subjects FIRST (single hash-aggregate pass), THEN probe
            -- v_word_points by id. The prior JOIN nested-looped every source attestation
            -- into laplace.physicalities and exploded.
            (SELECT count(*)
             FROM (SELECT DISTINCT a.subject_id
                   FROM laplace.attestations a
                   WHERE a.source_id = p_source) s
             WHERE EXISTS (SELECT 1 FROM laplace.v_word_points w
                           WHERE w.id = s.subject_id))
    END
$$;
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.multi_source_entity_count();

CREATE OR REPLACE FUNCTION ops.multi_source_entity_count()
    RETURNS bigint
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT count(*) FROM (
        SELECT a.subject_id FROM laplace.attestations a
        GROUP BY a.subject_id
        HAVING count(DISTINCT a.source_id) > 1) t;
END;
-- BEGIN ATOMIC: GH #764.
-- Census lives in ops (purpose), not the product/extension dump schema.
DROP FUNCTION IF EXISTS laplace.substrate_counts();

CREATE OR REPLACE FUNCTION ops.substrate_counts()
    RETURNS TABLE(metric text, value bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    -- Planner estimates (pg_class.reltuples), NOT count(*). Full scans on 100M+ unvacuumed
    -- tables hung every ingest tail. Read the LEAVES: a partitioned parent can retain
    -- reltuples=-1 even while its 64 children contain millions of rows. Clamping that parent
    -- value made a populated physicalities table appear as zero in the operator UI.
    --
    -- ANALYZE bounds estimate error; ops.evidence_count()/source_id() provide source precision.
    -- Metric keys are relation roles (entities/…); oids name current storage homes until
    -- the table cut. No install-time schema placeholder, no SET, no Brand.table metric labels.
    WITH targets(metric, relid, ordinal) AS (
        VALUES
            ('entities(ESTIMATE)'::text,      'laplace.entities'::regclass,      1),
            ('physicalities(ESTIMATE)'::text, 'laplace.physicalities'::regclass, 2),
            ('attestations(ESTIMATE)'::text,  'laplace.attestations'::regclass,  3),
            ('consensus(ESTIMATE)'::text,     'laplace.consensus'::regclass,     4)
    )
    SELECT t.metric, COALESCE(sum(GREATEST(c.reltuples, 0)::bigint), 0)::bigint
    FROM targets t
    CROSS JOIN LATERAL pg_partition_tree(t.relid) p
    JOIN pg_class c ON c.oid = p.relid
    WHERE p.isleaf
    GROUP BY t.metric, t.ordinal
    ORDER BY t.ordinal;
END;
-- ops.index_health — the invalid-index question as a permanent surface.
--
-- Born 2026-08-13: the cycle-shell incident left all 28 partitioned-parent
-- secondaries as empty invalid shells while every row count read green, and
-- the diagnosis was ad-hoc psql against pg_index — typed by hand, thrown
-- away, re-typed. A health question this load-bearing must be an installed
-- operation reachable from every surface (CLI, API, MCP `op`, psql), not a
-- query someone has to know to write. check-substrate-floor.sh calls this
-- operation rather than carrying a second pg_catalog implementation.
--
-- Returns one row per NON-VALID index in the extension's schemas (empty set =
-- healthy), plus leaf coverage for partitioned parents so a shell (leaves=0)
-- is distinguishable from a mid-build (indisvalid=false, leaves>0).
-- BEGIN ATOMIC per G12: pg_catalog relation OIDs are stable for the cluster's
-- life, and the regnamespace literals name schemas this extension guarantees.
DROP FUNCTION IF EXISTS ops.index_health();
-- schema_name is appended last, not inserted: it was added for ops.reindex_invalid,
-- which cannot issue REINDEX without it (an index name alone is ambiguous across
-- the four substrate schemas), and appending leaves any positional reader intact.
CREATE OR REPLACE FUNCTION ops.index_health()
    RETURNS TABLE(index_name text, table_name text, valid boolean,
                  is_partitioned_parent boolean, leaf_count bigint,
                  schema_name text)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT c.relname::text,
           t.relname::text,
           i.indisvalid,
           t.relkind = 'p',
           (SELECT count(*) FROM pg_catalog.pg_inherits h
             WHERE h.inhparent = i.indexrelid),
           t.relnamespace::regnamespace::text
    FROM pg_catalog.pg_index i
    JOIN pg_catalog.pg_class c ON c.oid = i.indexrelid
    JOIN pg_catalog.pg_class t ON t.oid = i.indrelid
    WHERE t.relnamespace IN ('laplace'::regnamespace, 'realize'::regnamespace,
                             'consensus'::regnamespace, 'generation'::regnamespace)
      AND NOT i.indisvalid
    ORDER BY t.relname, c.relname;
END;

COMMENT ON FUNCTION ops.index_health() IS
    'Every non-valid index in the substrate schemas (empty set = healthy). '
    'leaf_count 0 on a partitioned parent = the 2026-08-13 shell class: '
    'present in the catalog, unusable for reads, invisible to row counts.';
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.arena_counts();
CREATE OR REPLACE FUNCTION ops.arena_counts()
    RETURNS TABLE(type text, type_id bytea, relations bigint, witnesses bigint,
                  top_eff_mu numeric)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH raw AS MATERIALIZED (
      SELECT c.type_id, count(*) AS relations, sum(c.witness_count) AS witnesses,
             max(consensus.eff_mu_display(c.rating, c.rd)) AS top_eff_mu
    FROM @extschema@.consensus c
    GROUP BY c.type_id
    ), numbered AS MATERIALIZED (
      SELECT r.*, row_number() OVER (ORDER BY relations DESC, type_id) AS rn FROM raw r
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(type_id ORDER BY rn)) AS labels FROM numbered
    )
    SELECT b.labels[n.rn], n.type_id, n.relations, n.witnesses, n.top_eff_mu
    FROM numbered n CROSS JOIN batch b ORDER BY n.rn;
END;
DROP FUNCTION IF EXISTS laplace.source_counts();
CREATE OR REPLACE FUNCTION ops.source_counts()
    RETURNS TABLE(source text, source_id bytea, evidence bigint, content bigint)
    LANGUAGE sql STABLE
    AS $$



    WITH raw AS MATERIALIZED (
    SELECT COALESCE(ev.sid, ct.sid)                     AS source_id,
           COALESCE(ev.evidence, 0)                     AS evidence,
           COALESCE(ct.content, 0)                      AS content



    FROM (SELECT a.source_id AS sid, count(*) AS evidence
          FROM @extschema@.attestations a GROUP BY a.source_id) ev
    FULL JOIN (SELECT a.source_id AS sid, count(DISTINCT w.id) AS content
               FROM @extschema@.attestations a
               JOIN @extschema@.v_word_points w ON w.id = a.subject_id
               GROUP BY a.source_id) ct
      ON ev.sid = ct.sid
    ), numbered AS MATERIALIZED (
      SELECT r.*, row_number() OVER (ORDER BY evidence DESC NULLS LAST, source_id) AS rn FROM raw r
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(source_id ORDER BY rn)) AS labels FROM numbered
    )
    SELECT b.labels[n.rn], n.source_id, n.evidence, n.content
    FROM numbered n CROSS JOIN batch b ORDER BY n.rn
$$;
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.source_counts_approx();
CREATE OR REPLACE FUNCTION ops.source_counts_approx()
    RETURNS TABLE(source text, source_id bytea, evidence_approx bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    -- Issue 52: ops.source_counts() full-scans attestations twice (GROUP BY everything
    -- plus a count(DISTINCT) join) — minutes at 135M rows, killed the catalog
    -- endpoints. This is the planner-statistics form, the same sanctioned pattern
    -- as substrate_counts' reltuples estimates: per-source evidence share = MCV
    -- frequency x reltuples. ANALYZE freshness bounds the error; sources below the
    -- MCV cutoff don't appear (raise attestations.source_id statistics target if a
    -- long tail matters). Exact per-source numbers stay available through
    -- ops.evidence_count(NULL, source_id) — this function never replaces them.
    WITH st AS (
        SELECT s.most_common_vals::text::bytea[] AS vals,
               s.most_common_freqs               AS freqs
        FROM pg_stats s
        WHERE s.schemaname = '@extschema@'
          AND s.tablename  = 'attestations'
          AND s.attname    = 'source_id'
    ), rt AS (
        SELECT c.reltuples
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = '@extschema@' AND c.relname = 'attestations'
    )
    , raw AS MATERIALIZED (
      SELECT m.sid AS source_id, (m.freq * rt.reltuples)::bigint AS evidence_approx
      FROM st, rt, LATERAL unnest(st.vals, st.freqs) AS m(sid, freq)
    ), numbered AS MATERIALIZED (
      SELECT r.*, row_number() OVER (ORDER BY evidence_approx DESC, source_id) AS rn FROM raw r
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(source_id ORDER BY rn)) AS labels FROM numbered
    )
    SELECT b.labels[n.rn], n.source_id, n.evidence_approx
    FROM numbered n CROSS JOIN batch b ORDER BY n.rn;
END;
-- BEGIN ATOMIC: GH #764. Full scan — serving path should use entity_type_counts_approx.
DROP FUNCTION IF EXISTS laplace.entity_type_counts();
CREATE OR REPLACE FUNCTION ops.entity_type_counts()
    RETURNS TABLE(type text, type_id bytea, tier smallint, entities bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH raw AS MATERIALIZED (
      SELECT e.type_id, e.tier, count(*) AS entities
    FROM @extschema@.entities e
    GROUP BY e.type_id, e.tier
    ), numbered AS MATERIALIZED (
      SELECT r.*, row_number() OVER (ORDER BY entities DESC, type_id, tier) AS rn FROM raw r
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(type_id ORDER BY rn)) AS labels FROM numbered
    )
    SELECT b.labels[n.rn], n.type_id, n.tier, n.entities
    FROM numbered n CROSS JOIN batch b ORDER BY n.rn;
END;
-- BEGIN ATOMIC: GH #764.
-- Planner-statistics form of ops.entity_type_counts(MCV x reltuples).
DROP FUNCTION IF EXISTS laplace.entity_type_counts_approx();
CREATE OR REPLACE FUNCTION ops.entity_type_counts_approx()
    RETURNS TABLE(type text, type_id bytea, entities_approx bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH st AS (
        SELECT s.most_common_vals::text::bytea[] AS vals,
               s.most_common_freqs               AS freqs
        FROM pg_stats s
        WHERE s.schemaname = '@extschema@'
          AND s.tablename  = 'entities'
          AND s.attname    = 'type_id'
    ), rt AS (
        SELECT c.reltuples
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = '@extschema@' AND c.relname = 'entities'
    )
    , raw AS MATERIALIZED (
      SELECT m.tid AS type_id, (m.freq * rt.reltuples)::bigint AS entities_approx
      FROM st, rt, LATERAL unnest(st.vals, st.freqs) AS m(tid, freq)
    ), numbered AS MATERIALIZED (
      SELECT r.*, row_number() OVER (ORDER BY entities_approx DESC, type_id) AS rn FROM raw r
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(type_id ORDER BY rn)) AS labels FROM numbered
    )
    SELECT b.labels[n.rn], n.type_id, n.entities_approx
    FROM numbered n CROSS JOIN batch b ORDER BY n.rn;
END;
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.entity_count(bytea);
DROP FUNCTION IF EXISTS laplace.entity_counts_by_types(bytea[]);

CREATE OR REPLACE FUNCTION ops.entity_count(p_type bytea)
    RETURNS bigint
    LANGUAGE sql STABLE
BEGIN ATOMIC
    -- Scalar counterpart to ops.entity_type_counts(). That function aggregates every
    -- type in the substrate; a caller that wants one type's count should not pay
    -- a full GROUP BY over entities to read a single row. Here p_type arrives as
    -- a plain equality the planner can drive from the type_id index.
    --
    -- NULL p_type counts nothing, not everything: `type_id = NULL` matches no
    -- rows, and an unspecified type is not a wildcard. Callers that want the
    -- whole-table count already have ops.substrate_counts().
    SELECT count(*) FROM laplace.entities e WHERE e.type_id = p_type;
END;

CREATE OR REPLACE FUNCTION ops.entity_counts_by_types(p_types bytea[])
    RETURNS TABLE(type_id bytea, entities bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    -- Batch form: one round trip for N types, and every requested type comes back
    -- whether or not it has rows. A LEFT JOIN, not an inner one -- a type with no
    -- entities is a 0, and dropping it would make "absent from the result" and
    -- "count zero" the same answer, which is the tri-state collapse the read law
    -- names. Callers resolving names should aggregate ids and batch, not loop.
    SELECT t.type_id, count(e.id)
    FROM unnest(p_types) AS t(type_id)
    LEFT JOIN laplace.entities e ON e.type_id = t.type_id
    GROUP BY t.type_id;
END;
-- The RAW Glicko cell for one triple, and the batch form for many (GH #909).
--
-- consensus_by_ids answers the DISPLAY axis (consensus.eff_mu); this answers the bookkeeping
-- axis -- rating, rd, witness_count as stored. Feedback and fold-audit callers need
-- the untransformed numbers, and lacking an installed surface for that shape they
-- hand-wrote `SELECT rating, rd, witness_count FROM laplace.consensus WHERE id = ...`
-- against the table (NpgsqlConsensusCell.cs, whose own header records the gap and
-- calls itself the one sanctioned reader "until that lands"). This is that landing.
--
-- Keyed by primary id through laplace.consensus_id(), never a three-column triple scan: the
-- id IS blake3(subject || type || object), so the lookup is one index probe on the
-- PK and the partition keys come along in the same expression.
DROP FUNCTION IF EXISTS laplace.consensus_cell(bytea, bytea, bytea);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.cell(
    p_subject bytea, p_type bytea, p_object bytea)
    RETURNS TABLE(rating bigint, rd bigint, witness_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    -- The partition keys are in the parameter list; use them. laplace.consensus is
    -- LIST (type_id) over 208 named partitions plus a DEFAULT, each HASH (subject_id)
    -- over 8 -- 216 leaves. Filtering on c.id alone prunes NOTHING and touches every
    -- leaf; adding the two keys prunes to exactly one and hits the primary key
    -- (id, type_id, subject_id) directly. Same row, measured 97.1ms -> 20.2ms warm.
    SELECT c.rating, c.rd, c.witness_count
    FROM laplace.consensus c
    WHERE c.id = laplace.consensus_id(p_subject, p_type, p_object)
      AND c.type_id = p_type
      AND c.subject_id = p_subject;
END;

-- Batch pair scoring for ONE relation type over aligned subject/object arrays.
--
-- UNATTESTED SCORES 0 HERE, BY CONTRACT, and that is why this is not a call to
-- consensus.by_ids(GH #909 item 5): the caller ranks pairs and needs a dense
-- score vector aligned to its input, so a missing edge has to arrive as a number
-- rather than as an absent row. That collapses the tri-state ON PURPOSE and at the
-- caller's request -- it is a scoring surface, not a presence probe. Anything
-- asking whether an edge EXISTS must use consensus_cell or a presence probe, where
-- absent stays absent.
--
-- LEFT JOIN on the computed id, ordinal-aligned: one row out per row in, in input
-- order, so the caller indexes the result by position without a second pass.
DROP FUNCTION IF EXISTS laplace.consensus_pair_scores(bytea[], bytea, bytea[]);
CREATE OR REPLACE FUNCTION consensus.pair_scores(
    p_subjects bytea[], p_type bytea, p_objects bytea[])
    RETURNS TABLE(ord int, score float8)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT s.ord::int,
           COALESCE(consensus.eff_mu_display(c.rating, c.rd), 0)::float8
    FROM unnest(p_subjects) WITH ORDINALITY AS s(sid, ord)
    JOIN unnest(p_objects) WITH ORDINALITY AS o(oid, ord) USING (ord)
    LEFT JOIN laplace.consensus c
      ON c.id = laplace.consensus_id(s.sid, p_type, o.oid)
    ORDER BY s.ord;
END;

-- Trajectory count for a circuit-bearing entity type (GH #909, missing helper).
-- NpgsqlIngestOps joined laplace.physicalities x laplace.entities by hand for this because nothing
-- installed answered it. p_type is the entity type id; p_physicality_type selects
-- the physicality kind (3 = trajectory), named rather than left as a bare literal
-- at the call site.
DROP FUNCTION IF EXISTS laplace.entity_physicality_count(bytea, int);
CREATE OR REPLACE FUNCTION consensus.entity_physicality_count(
    p_type bytea, p_physicality_type int DEFAULT 3)
    RETURNS bigint
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT count(*)::bigint
    FROM laplace.physicalities p
    JOIN laplace.entities e ON e.id = p.entity_id
    WHERE p.type = p_physicality_type
      AND e.type_id = p_type;
END;
-- Ingest-fidelity eval scores, installed (GH #909 item 4).
--
-- Both bodies lived as CTE strings in C# (NpgsqlSubstrateReads), scanning consensus
-- directly and re-deriving a symmetric edge score with two correlated subselects per
-- row. They composed installed pieces, but the table reads, the per-row subselects
-- and the sampling rule were all defined client-side, where no gate sees them and
-- the definition of "how a plane scores a pair" can drift from the read path's.
--
-- SYMMETRIC BY CONSTRUCTION. A plane relation may be attested in either direction
-- for a given pair, so the score is the stronger of the two orientations; that is a
-- property of the eval, stated here once instead of copy-pasted into each caller.
-- Unattested reads 0 rather than absent: these feed a positives/negatives score
-- distribution where every sampled pair must contribute a number, the same
-- deliberate tri-state collapse consensus_pair_scores documents.
DROP FUNCTION IF EXISTS laplace.eval_pair_plane_score(bytea, bytea, bytea);
DROP FUNCTION IF EXISTS laplace.eval_ingest_fidelity_positives(text, text, int);
DROP FUNCTION IF EXISTS laplace.eval_ingest_fidelity_negatives(text, int);

CREATE OR REPLACE FUNCTION ops.eval_pair_plane_score(
    p_w1 bytea, p_w2 bytea, p_type bytea)
    RETURNS float8
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
    SELECT GREATEST(
        -- type_id and subject_id are the partition keys and both are in hand. Filtering
        -- on c.id alone prunes nothing across the 216 leaves; with them it is one leaf
        -- and the primary key (id, type_id, subject_id). Measured on consensus.cell,
        -- the same shape: 97.1ms -> 21.0ms. This runs once per evaluated pair.
        COALESCE((SELECT consensus.eff_mu_display(c.rating, c.rd)
                  FROM laplace.consensus c
                  WHERE c.id = laplace.consensus_id(p_w1, p_type, p_w2)
                    AND c.type_id = p_type AND c.subject_id = p_w1), 0),
        COALESCE((SELECT consensus.eff_mu_display(c.rating, c.rd)
                  FROM laplace.consensus c
                  WHERE c.id = laplace.consensus_id(p_w2, p_type, p_w1)
                    AND c.type_id = p_type AND c.subject_id = p_w2), 0))::float8
$$;

-- POSITIVES: pairs the ground-truth relation grounds together (two surfaces sharing
-- a sense), scored on the plane relation. p_relation names the plane; p_ground_truth
-- names the relation whose shared object makes two surfaces a true pair.
CREATE OR REPLACE FUNCTION ops.eval_ingest_fidelity_positives(
    p_relation text, p_ground_truth text, p_limit int DEFAULT 200)
    RETURNS TABLE(score float8)
    -- Sampling is intentionally fresh per call. random() changes on every call,
    -- so this wrapper must make the same promise rather than presenting planner-
    -- unsound transaction-constant behavior over a changing sample.
    LANGUAGE sql VOLATILE
    AS $$
    WITH vocab AS (
        SELECT subject_id AS id FROM consensus.subjects_of_type(p_relation)
    ),
    syn AS (
        SELECT c.subject_id AS w, c.object_id AS sense
        FROM laplace.consensus c
        WHERE c.type_id = laplace.relation_type_id(p_ground_truth)
          AND c.subject_id IN (SELECT id FROM vocab)
          AND c.object_id IS NOT NULL
    ),
    pairs AS (
        -- a.w < b.w gives each unordered pair once; the score is symmetric anyway,
        -- so the ordering here is deduplication and not a direction claim.
        SELECT DISTINCT a.w AS w1, b.w AS w2
        FROM syn a JOIN syn b ON a.sense = b.sense AND a.w < b.w
    )
    SELECT ops.eval_pair_plane_score(
               p.w1, p.w2, laplace.relation_type_id(p_relation))
    FROM (SELECT w1, w2 FROM pairs ORDER BY random() LIMIT p_limit) p
$$;

-- NEGATIVES: pairs drawn with no grounding relation between them, from the same
-- vocabulary, on the same plane -- the null distribution the positives are measured
-- against. The half-vocabulary offset pairs each sampled row with the one half a
-- shuffled vocabulary away, which draws unrelated pairs without ever asserting that
-- a pair is NOT related: an unattested edge is unattested, and scoring it 0 here is
-- the eval's convention, not a claim of refutation.
CREATE OR REPLACE FUNCTION ops.eval_ingest_fidelity_negatives(
    p_relation text, p_limit int DEFAULT 200)
    RETURNS TABLE(score float8)
    -- Both the shuffled vocabulary and final bounded sample use random(); preserve
    -- that deliberate per-call behavior with an explicit changing declaration.
    LANGUAGE sql VOLATILE
    AS $$
    WITH vocab AS (
        SELECT subject_id AS id FROM consensus.subjects_of_type(p_relation)
    ),
    samp AS (SELECT id, row_number() OVER (ORDER BY random()) AS rn FROM vocab),
    cnt  AS (SELECT count(*) AS c FROM samp),
    neg  AS (
        SELECT a.id AS w1, b.id AS w2
        FROM samp a JOIN samp b ON b.rn = a.rn + (SELECT c/2 FROM cnt)
    )
    SELECT ops.eval_pair_plane_score(
               p.w1, p.w2, laplace.relation_type_id(p_relation))
    FROM (SELECT w1, w2 FROM neg ORDER BY random() LIMIT p_limit) p
$$;
-- BEGIN ATOMIC: GH #764.
-- Partition skew detector via pg_class.reltuples / pg_partition_tree (no table scan).
DROP FUNCTION IF EXISTS laplace.partition_pressure(text);

CREATE OR REPLACE FUNCTION ops.partition_pressure(p_table text DEFAULT NULL)
    RETURNS TABLE(
        parent        text,
        partition     text,
        rows_approx   bigint,
        pct_of_parent numeric,
        total_bytes   bigint,
        total_size    text,
        bounds        text)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH parents AS (
        SELECT c.oid, c.relname
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'laplace'
          AND c.relkind = 'p'
          AND (p_table IS NULL OR c.relname = p_table)
          AND NOT EXISTS (SELECT 1 FROM pg_inherits i WHERE i.inhrelid = c.oid)
    ), leaves AS (
        SELECT p.relname AS parent, t.relid
        FROM parents p, LATERAL pg_partition_tree(p.oid) t
        WHERE t.isleaf
    ), sized AS (
        SELECT l.parent,
               c.relname::text                        AS partition,
               GREATEST(c.reltuples, 0)::bigint       AS rows_approx,
               pg_total_relation_size(l.relid)        AS total_bytes,
               pg_get_expr(c.relpartbound, c.oid)     AS bounds
        FROM leaves l
        JOIN pg_class c ON c.oid = l.relid
    )
    SELECT s.parent,
           s.partition,
           s.rows_approx,
           round(100.0 * s.rows_approx
                 / NULLIF(sum(s.rows_approx) OVER (PARTITION BY s.parent), 0), 2) AS pct_of_parent,
           s.total_bytes,
           pg_size_pretty(s.total_bytes)              AS total_size,
           s.bounds
    FROM sized s
    ORDER BY s.parent, s.rows_approx DESC;
END;
DROP FUNCTION IF EXISTS laplace.index_usage_report(bigint);
DROP FUNCTION IF EXISTS laplace.index_usage_detail(text, integer);

CREATE OR REPLACE FUNCTION ops.index_usage_report(p_min_bytes bigint DEFAULT 0)
    RETURNS TABLE(
        bucket      text,
        indexes     bigint,
        total_bytes bigint,
        total_size  text)
    LANGUAGE sql STABLE
    AS $$
    -- What the index set COSTS versus what anything has ever READ.
    --
    -- Every index is maintained on every insert. An index nothing reads is pure write
    -- amplification -- random read-modify-write into a structure that returns nothing --
    -- and there is no signal that it exists. MEASURED 2026-08-03, mid-ingest:
    --
    --   heap                                146 GB
    --   indexes                             178 GB   <- more index than data
    --     in use (>=100 lifetime scans)     114 GB across   928 indexes
    --     scanned <100x ever                 41 GB across 1,249 indexes
    --     never scanned                      23 GB across 1,726 indexes
    --
    -- 64 GB maintained on every write for fewer than 100 lifetime reads apiece. On
    -- physicalities_ba0 alone, two indexes served all 105M scans while six others totalling
    -- 10.8 GB had been scanned nine times between them -- including a 5,261 MB GIN over
    -- trajectory constituent ids (one entry per constituent per row, billions of entries;
    -- GIN insertion during bulk load is the random write behind 50 MB/s of WAL producing
    -- 2.5 MB/s of net data growth) with ONE lifetime scan.
    --
    -- READ THE COUNTS CORRECTLY. idx_scan is cumulative since the last stats reset, NOT
    -- since the index was built. pg_stat_database.stats_reset was NULL when the numbers
    -- above were taken, so they covered the database's whole life -- but this database is
    -- reseeded, and after a reseed every counter starts at zero. A zero here means "nothing
    -- has needed it since the last reset", which is not the same claim as "nothing needs
    -- it". Check the read surface before dropping anything: an index serving a quarterly
    -- report is indistinguishable here from an index serving nothing.
    --
    -- Statistics only (pg_stat_user_indexes + pg_relation_size). No scans.
    -- Companion: ops.index_usage_detail() for the per-index rows behind these buckets.
    WITH ix AS (
        SELECT s.indexrelname,
               s.idx_scan,
               pg_relation_size(s.indexrelid) AS bytes
        FROM pg_stat_user_indexes s
        WHERE s.schemaname = 'laplace'
          AND pg_relation_size(s.indexrelid) >= p_min_bytes
    )
    SELECT CASE
               WHEN ix.idx_scan = 0   THEN 'never scanned'
               WHEN ix.idx_scan < 100 THEN 'scanned <100x'
               ELSE                        'in use'
           END                          AS bucket,
           count(*)                     AS indexes,
           sum(ix.bytes)                AS total_bytes,
           pg_size_pretty(sum(ix.bytes)) AS total_size
    FROM ix
    GROUP BY 1
    ORDER BY sum(ix.bytes) DESC
$$;

CREATE OR REPLACE FUNCTION ops.index_usage_detail(p_table text DEFAULT NULL, p_limit integer DEFAULT 40)
    RETURNS TABLE(
        tbl         text,
        index_name  text,
        idx_scan    bigint,
        total_bytes bigint,
        total_size  text)
    LANGUAGE sql STABLE
    AS $$
    -- The per-index rows behind index_usage_report()'s buckets, biggest first. This is the
    -- form that names a specific drop candidate; the bucket form only sizes the problem.
    -- Same caveat: idx_scan is cumulative since the last stats reset, not since build.
    SELECT s.relname::text,
           s.indexrelname::text,
           s.idx_scan,
           pg_relation_size(s.indexrelid),
           pg_size_pretty(pg_relation_size(s.indexrelid))
    FROM pg_stat_user_indexes s
    WHERE s.schemaname = 'laplace'
      AND (p_table IS NULL OR s.relname = p_table)
    ORDER BY pg_relation_size(s.indexrelid) DESC
    LIMIT GREATEST(p_limit, 0)
$$;
CREATE OR REPLACE FUNCTION laplace.compositional_type_ids()
RETURNS bytea[]
LANGUAGE sql
IMMUTABLE
-- No SET search_path: every reference below is already schema-qualified (public.laplace_hash128_blake3),
-- and the clause would block Postgres from INLINING/constant-folding this into callers' predicates —
-- turning a compile-time-constant id set into 5 BLAKE3 hashes recomputed per entity row.
AS $$
    SELECT ARRAY[
        public.laplace_hash128_blake3('Codepoint'::bytea),
        public.laplace_hash128_blake3('Grapheme'::bytea),
        public.laplace_hash128_blake3('Word'::bytea),
        public.laplace_hash128_blake3('Sentence'::bytea),
        public.laplace_hash128_blake3('Document'::bytea)
    ];
$$;
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.consensus_tier_distribution();

CREATE OR REPLACE FUNCTION ops.consensus_tier_distribution()
    RETURNS TABLE(subject_tier smallint, relations bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT e.tier, count(*)
    FROM laplace.consensus c JOIN laplace.entities e ON e.id = c.subject_id
    WHERE c.object_id IS NOT NULL
      AND e.type_id = ANY(laplace.compositional_type_ids())
    GROUP BY e.tier ORDER BY e.tier;
END;
DROP FUNCTION IF EXISTS laplace.render_gaps(integer);
CREATE OR REPLACE FUNCTION realize.render_gaps(p_limit integer DEFAULT 50)
    RETURNS TABLE(id bytea, roles text, refs bigint)
    LANGUAGE sql STABLE
    AS $$
    WITH refs AS (
        SELECT c.type_id AS id, 'type' AS role FROM @extschema@.consensus c
        UNION ALL
        SELECT c.object_id, 'object' FROM @extschema@.consensus c WHERE c.object_id IS NOT NULL
        UNION ALL
        SELECT c.subject_id, 'subject' FROM @extschema@.consensus c
    ),
    agg AS (
        SELECT r.id, string_agg(DISTINCT r.role, ',' ORDER BY r.role) AS roles, count(*) AS refs
        FROM refs r GROUP BY r.id
    )
    SELECT a.id, a.roles, a.refs
    FROM agg a
    WHERE NOT EXISTS (SELECT 1 FROM @extschema@.canonical_names n WHERE n.id = a.id)
      AND realize.codepoint_for_id(a.id) IS NULL
      AND NOT EXISTS (SELECT 1 FROM @extschema@.v_word_points w
                      WHERE w.id = a.id AND w.trajectory IS NOT NULL)
    ORDER BY a.refs DESC
    LIMIT p_limit
$$;
-- CREATE OR REPLACE cannot widen a function's result set, so the upgrade path
-- has to drop first — adding `kind` below is exactly that change.
DROP FUNCTION IF EXISTS ops.api(text);

-- `kind` distinguishes a function from a procedure, and it is not cosmetic: a
-- procedure is invoked with CALL and a function with SELECT, so a caller that
-- cannot tell them apart issues the wrong statement and gets
-- "ops.evict_source(...) is a procedure" from the parser instead of running it.
-- pg_get_function_result already returns NULL for procedures, but inferring the
-- kind from a null return is reading a side effect; the column states it.
-- Appended last so existing named-column readers are unaffected.
CREATE OR REPLACE FUNCTION ops.api(p_like text DEFAULT NULL)
    RETURNS TABLE(name text, args text, returns text, kind text)
    LANGUAGE sql STABLE AS $$
    SELECT CASE WHEN n.nspname = 'laplace' THEN p.proname::text
                ELSE n.nspname || '.' || p.proname END,
           pg_get_function_arguments(p.oid),
           pg_get_function_result(p.oid),
           CASE p.prokind WHEN 'p' THEN 'procedure'
                          WHEN 'a' THEN 'aggregate'
                          WHEN 'w' THEN 'window'
                          ELSE 'function' END
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE (
            n.nspname = ANY (ARRAY[
                'laplace','consensus','converse','lexical','taxonomy',
                'generation','structural','chess','realize','ops'
            ])
            -- Load-bearing public C helpers agents must discover through the
            -- catalog rather than reimplementing them (GH #533).
            OR (n.nspname = 'public' AND p.proname = ANY (ARRAY[
                'laplace_frechet_4d',
                'laplace_hilbert_encode',
                'laplace_radius_origin',
                'laplace_hash128_blake3',
                'laplace_mantissa_unpack',
                'laplace_distance_4d',
                'laplace_angular_distance_4d',
                'laplace_direction_4d'
            ]))
          )
      AND (p_like IS NULL
           OR p.proname ILIKE '%'||p_like||'%'
           OR (n.nspname || '.' || p.proname) ILIKE '%'||p_like||'%')
    ORDER BY n.nspname, p.proname
$$;
-- NO `SET search_path` (GH #617 item 6). This is a labeling scalar called PER ROW in
-- every arrow realize.render and relation listing; the clause made each of those a full
-- non-inlined function execution for one string operation.
--
-- STRICT is KEPT (STABLE   STRICT  PARALLEL SAFE). It also blocks inlining, but here it is
-- load-bearing rather than incidental: realize.render(NULL) is the label of nothing, and the
-- callers -- realize_path, the walk responders -- COALESCE a NULL type_label to '?'
-- to mark an unrenderable relation. Dropping STRICT would push NULL through
-- replace()/lower() and still return NULL, so the value is unchanged, but the
-- declaration is what documents that a NULL type has no label rather than a blank
-- one. The search_path clause was the free half of this win; STRICT is not.
DROP FUNCTION IF EXISTS laplace.type_label(bytea);
CREATE OR REPLACE FUNCTION lexical.type_label(p_type bytea)
    RETURNS text
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE AS $$
    SELECT lower(replace(realize.render(p_type), '_', ' '))
$$;
