CREATE OR REPLACE FUNCTION laplace.word_id(p_text text)
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_word_id'
    LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;

-- Same native length-bearing UTF-8 identity operation, including U+0000 which
-- PostgreSQL text cannot transport. This is not a second content hash algorithm.
CREATE OR REPLACE FUNCTION laplace.content_id(p_utf8 bytea)
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_word_id'
    LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
-- Source admission and source readback share the native lossless grammar composer.
CREATE OR REPLACE FUNCTION laplace.grammar_source_id(p_utf8 bytea, p_modality text)
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_grammar_source_id'
    LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
-- Length-bearing UTF-8 assembly. Text renderers share this native batch kernel;
-- this surface additionally preserves Unicode NUL through PostgreSQL bytea.
CREATE OR REPLACE FUNCTION realize.render_bytes_batch(p_ids bytea[], p_max_depth integer DEFAULT 0)
    RETURNS bytea[]
    AS 'laplace_substrate', 'pg_laplace_render_bytes_batch'
    LANGUAGE C STABLE;

CREATE OR REPLACE FUNCTION realize.render_bytes(p_id bytea, p_max_depth integer DEFAULT 0)
    RETURNS bytea
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT (realize.render_bytes_batch(ARRAY[p_id], COALESCE(p_max_depth, 0)))[1];
END;
-- Exact canonical text-content reconstruction. The native renderer owns the complete,
-- cycle-safe constituent walk and returns NULL rather than partial text when any child cannot
-- be recovered. Re-resolving the assembled value through the canonical text identity surface
-- prevents a malformed or non-text composition from being presented as exact content.
--
-- The result is canonical UTF-8 content, not an original artifact byte stream. Recovering an
-- encoded file requires the format recipe and packaging state carried by its artifact trunk.
CREATE OR REPLACE FUNCTION realize.reconstruct_content(p_id bytea, p_modality text)
    RETURNS bytea
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH rendered AS MATERIALIZED (
        SELECT realize.render_bytes(p_id) AS body
    )
    SELECT CASE
        WHEN rendered.body IS NULL
          OR CASE WHEN p_modality IS NULL THEN laplace.content_id(rendered.body)
                  ELSE laplace.grammar_source_id(rendered.body, p_modality)
             END IS DISTINCT FROM p_id
            THEN NULL::bytea
        ELSE rendered.body
    END
    FROM rendered;
END;

CREATE OR REPLACE FUNCTION realize.reconstruct_content(p_id bytea)
    RETURNS bytea
    LANGUAGE sql STABLE STRICT
BEGIN ATOMIC
    SELECT realize.reconstruct_content(p_id, NULL::text);
END;

COMMENT ON FUNCTION realize.reconstruct_content(bytea, text) IS
    'Complete source UTF-8 verified by the declared native source grammar; NULL modality selects canonical text.';

COMMENT ON FUNCTION realize.reconstruct_content(bytea) IS
    'Complete canonical UTF-8 content for one text identity; NULL for absent, incomplete, cyclic, non-text, or identity-mismatched input.';
DROP FUNCTION IF EXISTS laplace.resolve_ref(text);
CREATE OR REPLACE FUNCTION converse.resolve_ref(p_ref text)
    RETURNS bytea
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Resolve a caller-supplied reference to an entity id: a 32-hex string is a
    -- literal content id (decode it); anything else is a surface to content-
    -- address via laplace.word_id. Centralizes the identical `WITH resolved AS (SELECT
    -- CASE WHEN @target ~ '^[0-9a-f]{32}$' ...)` CTE that EvidenceAsync and
    -- EmbeddingAsync each inlined. No SET search_path so it inlines.
    SELECT CASE
        WHEN p_ref ~ '^[0-9a-f]{32}$' THEN decode(p_ref, 'hex')
        ELSE laplace.word_id(p_ref)
    END
$$;
-- Native, batched replacement for the word_case_variant_ids -> word_case_map_surface
-- (x3) -> grapheme_case_target SQL fan-out, which turned one lexical lookup into
-- O(3 * graphemes) non-inlinable consensus LIMIT-1 subqueries plus O(graphemes)
-- realize.render_text calls on the hot lexical_peers -> senses/define/bubble_up path.
-- Output-identical by delegation: case-map selection stays in one batched
-- DISTINCT ON ... ORDER BY consensus.eff_mu DESC over laplace.v_consensus_unrefuted, rendering
-- stays realize.render_text, minting stays laplace.word_id, the existence gate
-- stays consensus.entity_exists; the C only walks the grapheme trajectory once and
-- reproduces word_case_map_surface's string assembly. See src/lexical_case.c.
DROP FUNCTION IF EXISTS laplace.word_case_variants(bytea);
CREATE OR REPLACE FUNCTION lexical.word_case_variants(p_word bytea)
    RETURNS bytea[]
    AS 'laplace_substrate', 'pg_laplace_word_case_variants'
    LANGUAGE C STABLE;

-- True set form. The scalar function batches the graphemes of one word; this
-- batches trajectory unpack, case-map lookup, realization, word-id construction,
-- and existence testing across the complete input frontier.
DROP FUNCTION IF EXISTS laplace.word_case_variants_batch(bytea[]);
CREATE OR REPLACE FUNCTION lexical.word_case_variants_batch(p_words bytea[])
    RETURNS TABLE(word_id bytea, variant_id bytea)
    AS 'laplace_substrate', 'pg_laplace_word_case_variants_batch'
    LANGUAGE C STABLE STRICT PARALLEL SAFE;
DROP FUNCTION IF EXISTS laplace.word_segment(text);
CREATE OR REPLACE FUNCTION converse.word_segment(p_text text)
    RETURNS TABLE(ord int, word text, id bytea)
    AS 'laplace_execution_2e9b3225dced6056', 'pg_laplace_word_segment'
    LANGUAGE C STABLE;
-- converse.word_segment_resolved — word_segment, with the substrate deciding
-- where a word ends inside a run the text gave no boundary for.
--
-- UAX#29 word break joins ALetter runs, so Latin, Cyrillic, Arabic and Hangul
-- words survive whole while 4.1 puts Han, Hiragana, Katakana, Thai, Lao and
-- Khmer segmentation explicitly out of scope. Measured live 2026-08-23:
-- 自転車 (167 edges), 北京 (93), ある (81), สวัสดี (27) and 氷河 (21) all exist
-- with rated evidence and converse.word_segment reaches none of them, emitting
-- 3, 2, 2, 4 and 2 fragments. Downstream then runs one rung lower for those
-- scripts: generation.trajectory_continuations for 氷 returns 20 of 20 non-word
-- entities, against 20 of 20 words for New.
--
-- Whitespace is a real boundary and is never crossed, so "hot dog" and
-- "New York" stay tier-3 compositions of two tier-2 words rather than becoming
-- word tokens. Only byte-contiguous runs are joined; the rule names no script.
--
-- Stores nothing. Adjacency remains a view over the trajectory per the
-- 2026-07-25 ruling in relation_types.toml. See src/content_resolve.c.
-- No DROP FUNCTION here. converse.prompt_words is BEGIN ATOMIC and references this
-- body, which records a hard catalog dependency, so a DROP on the upgrade path fails
-- against the caller installed by the previous version. The signature is new and never
-- changes under replace, so CREATE OR REPLACE alone is sufficient and idempotent.
CREATE OR REPLACE FUNCTION converse.word_segment_resolved(p_text text)
    RETURNS TABLE(ord int, word text, id bytea)
    AS 'laplace_execution_2e9b3225dced6056', 'pg_laplace_word_segment_resolved'
    LANGUAGE C STABLE;
-- realize.label — GH #862 / #860. A label is a rendering decision, so it lives with
-- the realize family. No SET (it invalidates plan caching and this is per-row on the
-- realize.render path); real schema names.
DROP FUNCTION IF EXISTS laplace.label(bytea);
CREATE OR REPLACE FUNCTION realize.label(p_id bytea)
    RETURNS text
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE AS $$
    -- A label is a NAME/surface, never a definition. Order: the entity's
    -- resolved name, else its own rendered+cleaned surface. An unresolved label
    -- abstains; a content hash is an internal identity handle, not a surface.
    -- The name lookup now goes through realize.resolve_name() -- the single, family-aware
    -- primitive that consults HAS_NAME (primary) + HAS_NAME_ALIAS + the
    -- synset-lemma path and abstains rather than guessing -- instead of this
    -- function's former HAS_NAME_ALIAS-only argmax, which ignored the primary
    -- HAS_NAME edge entirely. (The former HAS_DEFINITION fallback made every
    -- surface-less entity realize.render as its gloss, which polluted every consumer;
    -- that is gone.)
    SELECT COALESCE(
        realize.resolve_name(p_id),
        NULLIF(
            regexp_replace(
            regexp_replace(
                regexp_replace(
                    regexp_replace(
                        regexp_replace(
                            regexp_replace(
                                regexp_replace(
                                    regexp_replace(realize.render(p_id),
                                        '^substrate/(?:type|relation|trust_class|source|entity)/(.*)/v1$', '\1'),
                                    '^substrate/pos/(?:probationary/[^/]+/)?(.+)/v1$', '\1'),
                                '^source/file/(.+)/v1$', '\1'),
                            '^repo:(.+)/v1$', '\1'),
                        '^language:([a-z]{3})$', '\1'),
                    '^ud/feature/(.+)$', '\1'),
                '^tiny-codes/concept/(.+)/v1$', '\1'),
            '^(i[0-9]+|[0-9]{6,}-[nvarspNVARSP])$', ''),
            ''))
$$;

-- realize.display_label_batch — the FINAL bounded-display projection used by Explore.
--
-- This is intentionally NOT the semantic contract of realize.label(). `label` must abstain
-- when an entity has no name/surface. A product display still needs something intelligible
-- to paint after its candidate set has been elected. The display projection therefore adds
-- bounded, containment-owned previews and descriptive metadata while keeping identity in a
-- separate id column. It NEVER uses encode(id,'hex') as a human label.
--
-- GH #804: form is caller/containment-owned, not inferred from entity.type_id. Exact
-- self-rendering stops at sentence grain. Higher-tier text is previewed only when a
-- witnessed role proves textual containment (the governed HAS_DEFINITION family or
-- HasFileMetadata); opaque or non-text content falls through to a name, relation,
-- type/source description, or explicit "Unrealized entity" rather than being silently
-- projected through a text lens.
CREATE OR REPLACE FUNCTION realize.display_label_batch(p_ids bytea[])
    RETURNS TABLE(id bytea, label text, tier smallint)
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    WITH RECURSIVE inp AS MATERIALIZED (
        SELECT x.id, x.ord, e.tier, e.type_id, e.first_observed_by
        FROM unnest(p_ids) WITH ORDINALITY AS x(id, ord)
        LEFT JOIN laplace.entities e ON e.id = x.id
    ),
    names AS MATERIALIZED (
        SELECT realize.resolve_name_batch(p_ids) AS labels
    ),
    shallow_indexed AS MATERIALIZED (
        SELECT i.id, i.ord, i.id AS render_id,
               row_number() OVER (ORDER BY i.ord)::integer AS rn
        FROM inp i
        WHERE i.tier <= 3
    ),
    shallow_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(s.render_id ORDER BY s.rn), '{}'::bytea[]) AS ids
        FROM shallow_indexed s
    ),
    shallow_rendered AS MATERIALIZED (
        -- The candidate is already bounded to sentence-or-shallower grain. Render that
        -- elected content exactly; do not fit an arbitrary recursion depth to it.
        SELECT b.ids, realize.render_text_batch(b.ids) AS labels
        FROM shallow_batch b
    ),
    shallow AS MATERIALIZED (
        SELECT s.id, NULLIF(r.labels[s.rn], '') AS label
        FROM shallow_indexed s
        CROSS JOIN shallow_rendered r
    ),

    -- File metadata is a containment-proven textual envelope, not a guess about the file
    -- content's form. Render only the tiny metadata document and extract its filename.
    file_meta_choice AS MATERIALIZED (
        SELECT DISTINCT ON (i.id)
               i.id AS owner_id, i.ord, a.object_id AS metadata_id
        FROM inp i
        JOIN laplace.attestations a
          ON a.subject_id = i.id
         -- Exact parity with SubstrateCanonicalIds.OfVersioned("type","HasFileMetadata").
         -- Keep the key composition explicit by segment instead of reintroducing a raw
         -- legacy type-path literal into production SQL.
         AND a.type_id = realize.canonical_id(
             concat_ws('/', 'substrate', 'type', 'HasFileMetadata', 'v1'))
        WHERE a.object_id IS NOT NULL
        ORDER BY i.id, a.last_observed_at DESC, a.id
    ),
    file_meta_indexed AS MATERIALIZED (
        SELECT m.*, row_number() OVER (ORDER BY m.ord)::integer AS rn
        FROM file_meta_choice m
    ),
    file_meta_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(m.metadata_id ORDER BY m.rn), '{}'::bytea[]) AS ids
        FROM file_meta_indexed m
    ),
    file_meta_rendered AS MATERIALIZED (
        -- Metadata is already the tiny elected file envelope; exact rendering is both
        -- cheaper than rendering the file body and faithful to the Merkle content law.
        SELECT b.ids, realize.render_text_batch(b.ids) AS labels
        FROM file_meta_batch b
    ),
    file_meta_text AS MATERIALIZED (
        SELECT m.owner_id, r.labels[m.rn] AS txt
        FROM file_meta_indexed m
        CROSS JOIN file_meta_rendered r
    ),
    file_label AS MATERIALIZED (
        SELECT f.owner_id,
               NULLIF(substr(lines.line, length('name=') + 1), '') AS label
        FROM file_meta_text f
        CROSS JOIN LATERAL unnest(
            string_to_array(COALESCE(f.txt, ''), E'\n')) AS lines(line)
        WHERE lines.line LIKE 'name=%'
    ),

    -- The relation taxonomy, not this display function, owns the definition vocabulary.
    -- Use the already-installed family-members accessor rather than depending on the
    -- generated foldable helper: extension upgrades regenerate that helper later in the
    -- script, and a BEGIN ATOMIC dependency would otherwise make its DROP/replace fail.
    definition_types AS MATERIALIZED (
        SELECT COALESCE(array_agg(f.id), '{}'::bytea[]) AS ids
        FROM consensus.relation_family_members('HAS_DEFINITION') f
    ),

    -- A concept can own text through the governed definition family, and a definition
    -- content id can be recognized as text through the inverse containment edge. This is
    -- exactly the #804 caller/containment law: the role proves the projection;
    -- entity.type_id does not.
    definition_owned AS MATERIALIZED (
        SELECT DISTINCT ON (i.id)
               i.id AS owner_id, i.ord, a.object_id AS target_id
        FROM inp i
        CROSS JOIN definition_types d
        JOIN laplace.attestations a
          ON a.subject_id = i.id
         AND a.type_id = ANY(d.ids)
        WHERE a.object_id IS NOT NULL
        ORDER BY i.id, a.last_observed_at DESC, a.id
    ),
    definition_text AS MATERIALIZED (
        SELECT DISTINCT ON (i.id)
               i.id AS owner_id, i.ord, i.id AS target_id
        FROM inp i
        CROSS JOIN definition_types d
        JOIN laplace.attestations a
          ON a.object_id = i.id
         AND a.type_id = ANY(d.ids)
        ORDER BY i.id, a.last_observed_at DESC, a.id
    ),
    text_targets AS MATERIALIZED (
        SELECT * FROM definition_owned
        UNION ALL
        SELECT t.* FROM definition_text t
        WHERE NOT EXISTS (
            SELECT 1 FROM definition_owned o WHERE o.owner_id = t.owner_id)
    ),

    -- A high-tier textual preview follows ONE ordered trunk-to-leaf spine until it
    -- reaches sentence-or-shallower grain. It never expands siblings and never asks for
    -- a descendants closure. This matters for books/chapters as much as documents: a
    -- fixed one-level peek silently failed as soon as the first child was still tier > 3.
    preview_seed AS MATERIALIZED (
        SELECT p.owner_id, p.ord, p.target_id AS node_id, e.tier AS node_tier, 0 AS depth
        FROM text_targets p
        LEFT JOIN laplace.entities e ON e.id = p.target_id
    ),
    preview_spine(owner_id, ord, node_id, node_tier, depth) AS (
        SELECT s.owner_id, s.ord, s.node_id, s.node_tier, s.depth
        FROM preview_seed s
      UNION ALL
        SELECT s.owner_id,
               s.ord,
               head.child_id,
               head.child_tier,
               s.depth + 1
        FROM preview_spine s
        CROSS JOIN LATERAL (
            -- Decode exactly the first packed trajectory vertex. A display preview must
            -- not bulk-unpack siblings before the small graph label has elected any need
            -- for them.
            SELECT u.entity_id AS child_id,
                   ((u.flags >> 1) & 31)::smallint AS child_tier
            FROM laplace.v_word_points w
            CROSS JOIN LATERAL public.laplace_mantissa_unpack(
                public.ST_PointN(w.trajectory, 1)) u
            WHERE w.id = s.node_id
              AND w.trajectory IS NOT NULL
            ORDER BY w.physicality_id
            LIMIT 1
        ) head
        WHERE s.node_tier > 3
          AND s.depth < 32
    ),
    preview_render_ids AS MATERIALIZED (
        SELECT DISTINCT ON (p.owner_id)
               p.owner_id, p.ord, p.node_id AS render_id
        FROM preview_spine p
        WHERE p.node_tier <= 3
        ORDER BY p.owner_id, p.depth
    ),
    preview_indexed AS MATERIALIZED (
        SELECT p.owner_id, p.ord, p.render_id,
               row_number() OVER (ORDER BY p.ord)::integer AS rn
        FROM preview_render_ids p
        WHERE p.render_id IS NOT NULL
    ),
    preview_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(p.render_id ORDER BY p.rn), '{}'::bytea[]) AS ids
        FROM preview_indexed p
    ),
    preview_rendered AS MATERIALIZED (
        -- The expensive high-tier election has already collapsed each root to one
        -- sentence-or-shallower descendant. Render that elected descendant exactly.
        SELECT b.ids, realize.render_text_batch(b.ids) AS labels
        FROM preview_batch b
    ),
    preview AS MATERIALIZED (
        SELECT p.owner_id,
               NULLIF(regexp_replace(r.labels[p.rn], '[[:space:]]+', ' ', 'g'), '') AS label
        FROM preview_indexed p
        CROSS JOIN preview_rendered r
    ),

    -- Descriptive metadata is a fallback only; it never decides which projection runs.
    -- label_batch historically sat on top of render(), so reject anything that merely
    -- round-tripped a 128-bit identity handle. That rejection happens ONLY in metadata
    -- lanes: literal text whose actual contents are 32 hex characters remains literal text.
    type_indexed AS MATERIALIZED (
        SELECT d.type_id, row_number() OVER (ORDER BY d.type_id)::integer AS rn
        FROM (SELECT DISTINCT i.type_id FROM inp i WHERE i.type_id IS NOT NULL) d
    ),
    type_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(t.type_id ORDER BY t.rn), '{}'::bytea[]) AS ids
        FROM type_indexed t
    ),
    type_rendered AS MATERIALIZED (
        SELECT b.ids, realize.label_batch(b.ids) AS labels
        FROM type_batch b
    ),
    type_label AS MATERIALIZED (
        SELECT t.type_id,
               CASE
                   WHEN r.labels[t.rn] ~ '^[0-9A-Fa-f]{32}(…|\.\.\.)?$' THEN NULL
                   ELSE NULLIF(replace(r.labels[t.rn], '_', ' '), '')
               END AS label
        FROM type_indexed t
        CROSS JOIN type_rendered r
    ),
    source_indexed AS MATERIALIZED (
        SELECT d.source_id, row_number() OVER (ORDER BY d.source_id)::integer AS rn
        FROM (
            SELECT DISTINCT i.first_observed_by AS source_id
            FROM inp i
            WHERE i.first_observed_by IS NOT NULL
        ) d
    ),
    source_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(s.source_id ORDER BY s.rn), '{}'::bytea[]) AS ids
        FROM source_indexed s
    ),
    source_rendered AS MATERIALIZED (
        SELECT b.ids, realize.label_batch(b.ids) AS labels
        FROM source_batch b
    ),
    source_label AS MATERIALIZED (
        SELECT s.source_id,
               CASE
                   WHEN r.labels[s.rn] ~ '^[0-9A-Fa-f]{32}(…|\.\.\.)?$' THEN NULL
                   ELSE NULLIF(r.labels[s.rn], '')
               END AS label
        FROM source_indexed s
        CROSS JOIN source_rendered r
    )
    SELECT i.id,
           COALESCE(
               NULLIF(canonical.name, ''),
               CASE
                   WHEN names.labels[i.ord] ~ '^(i[0-9]+|[0-9]{6,}-[nvarspNVARSP]|[0-9A-Fa-f]{32}(…|\.\.\.)?)$'
                       THEN NULL
                   ELSE NULLIF(names.labels[i.ord], '')
               END,
               shallow.label,
               file_label.label,
               preview.label,
               NULLIF(consensus.relation_canonical(i.id), ''),
               NULLIF(concat_ws(' · ', type_label.label, source_label.label), ''),
               'Unrealized entity'),
           i.tier
    FROM inp i
    CROSS JOIN names
    LEFT JOIN shallow ON shallow.id = i.id
    LEFT JOIN file_label ON file_label.owner_id = i.id
    LEFT JOIN preview ON preview.owner_id = i.id
    LEFT JOIN type_label ON type_label.type_id = i.type_id
    LEFT JOIN source_label ON source_label.source_id = i.first_observed_by
    LEFT JOIN laplace.canonical_names canonical ON canonical.id = i.id
    ORDER BY i.ord;
END;
-- View still binds the flat name until its CREATE OR REPLACE later in the
-- install chain; drop it so the dual-name ban (#532) DROP can proceed.
DROP VIEW IF EXISTS laplace.v_attestation_readable;
DROP FUNCTION IF EXISTS laplace.label_or_hex(bytea);
CREATE OR REPLACE FUNCTION converse.label_or_hex(p_id bytea)
    RETURNS text
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    -- Legacy name retained for installed-call compatibility. Human-facing reads
    -- receive the entity's realized label or an honest abstention marker. A hash
    -- is identity metadata and must never be fabricated as display content.
    SELECT COALESCE(realize.label(p_id), 'unrealized entity')
$$;
-- Attestations with the four endpoint labels resolved once. The inspect
-- attestation family kept re-joining entities / calling label_or_hex per
-- column. label_or_hex owns the id-display decision (hex fallback); this view
-- does not invent a second renderer.
--
-- PERFORMANCE CONTRACT: each row pays up to five label_or_hex calls. Use ONLY
-- with a selective predicate and LIMIT (inspect/UI). Never as the base of a
-- bulk fold, ingest, or unbounded join — that turns a cheap scan into a render
-- storm.
CREATE OR REPLACE VIEW laplace.v_attestation_readable AS
SELECT a.id,
       a.subject_id,
       a.type_id,
       a.object_id,
       a.source_id,
       a.context_id,
       a.outcome,
       a.observation_count,
       a.sum_score_fp1e9,
       a.opponent_rd_fp1e9,
       a.last_observed_at,
       converse.label_or_hex(a.subject_id) AS subject_label,
       converse.label_or_hex(a.type_id)    AS type_label,
       converse.label_or_hex(a.object_id)  AS object_label,
       converse.label_or_hex(a.source_id)  AS source_label,
       converse.label_or_hex(a.context_id) AS context_label
FROM laplace.attestations a;
-- True when a rendered label is real content, not substrate scaffolding. The
-- associative band (7) carries mesh/structural edges alongside content concepts,
-- so the listing responders keep only labels that are NOT a bare ILI id
-- ("09411430-n"), a WordNet lexfile name ("noun.object", "adjs.pert"), or a
-- multi-word phrase (a space). This was the same regex triplet copy-pasted into
-- converse.chat() and converse.facts() -- and it had already drifted (chat dropped the
-- "adjs" lexfile case), the exact one-definition-per-fact hazard. One predicate,
-- both callers. IMMUTABLE (pure function of the input, no schema objects) so it
-- inlines into the WHERE and needs no search_path.
DROP FUNCTION IF EXISTS laplace.label_is_content(text);
CREATE OR REPLACE FUNCTION converse.label_is_content(p_label text)
    RETURNS boolean
    LANGUAGE sql IMMUTABLE AS $$
    SELECT p_label IS NOT NULL
       AND p_label !~ '^[0-9]{6,}-[nvasr]$'
       AND p_label !~ '^(noun|verb|adj|adv|adjs)\.'
       AND p_label !~ ' '
$$;
-- Roster staleness detector for the highway-axis partition layout.
--
-- consensus/attestations are LIST-partitioned on type_id; only relations flagged
-- `hot = true` in engine/manifest/relation_types.toml get dedicated HASH(subject_id)
-- x8 partitions, and everything else shares ONE default heap+btree. That roster is
-- a human judgement about traffic, and it goes stale silently: a new decomposer can
-- become the single largest writer in the database while every one of its rows piles
-- into the default, and nothing says so. That is exactly how Tatoeba's
-- HAS_EXTERNAL_ID / IS_TRANSLATION_OF reached 4.8M rows in consensus_rdefault
-- (5.2 GB, the largest consensus table) — discovered only by watching an ingest's
-- input rate decay from 8,190 to 5,093 rec/s under LWLock.BufferContent contention.
--
-- This names the offenders from planner statistics, not by scanning both DEFAULT
-- partitions after every ingest. ANALYZE is already part of the completion envelope;
-- MCV frequency x reltuples gives the crowding population without turning a diagnostic
-- into a second corpus pass. Relations below the MCV roster are, by definition, not the
-- dominant crowding population this operation is meant to find.
--
-- Not part of substrate_health(): that function gates IDENTITY law. This is
-- physical layout, a different claim on a different layer.
DROP FUNCTION IF EXISTS laplace.consensus_partition_pressure(bigint);
DROP FUNCTION IF EXISTS ops.consensus_partition_pressure(bigint);
DROP FUNCTION IF EXISTS ops.consensus_partition_pressure();
CREATE OR REPLACE FUNCTION ops.consensus_partition_pressure()
RETURNS TABLE(
    tbl         text,
    relation    text,
    type_id     bytea,
    rows        bigint,
    pct_of_default numeric
)
LANGUAGE sql
STABLE
    AS $$
    WITH targets(tbl, relname) AS (
        VALUES ('consensus'::text, 'consensus_rdefault'::text),
               ('attestations'::text, 'attestations_rdefault'::text)
    ),
    stats AS (
        SELECT t.tbl,
               c.reltuples,
               s.most_common_vals::text::bytea[] AS vals,
               s.most_common_freqs AS freqs
        FROM targets t
        JOIN pg_class c ON c.relname = t.relname
        JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = '@extschema@'
        JOIN pg_stats s ON s.schemaname = '@extschema@'
                       AND s.tablename = t.relname
                       AND s.attname = 'type_id'
    ), raw AS MATERIALIZED (
        SELECT st.tbl,
               m.type_id,
               (m.freq * st.reltuples)::bigint AS rows,
               round((100.0 * m.freq)::numeric, 2) AS pct_of_default
        FROM stats st,
             LATERAL unnest(st.vals, st.freqs) AS m(type_id, freq)
    ), numbered AS MATERIALIZED (
      SELECT raw.*,
             row_number() OVER (ORDER BY rows DESC, tbl, type_id) AS rn
      FROM raw
    ), batch AS MATERIALIZED (
      SELECT realize.label_batch(array_agg(type_id ORDER BY rn)) AS labels FROM numbered
    )
    SELECT
        agg.tbl,
        b.labels[agg.rn] AS relation,
        agg.type_id,
        agg.rows,
        agg.pct_of_default
      FROM numbered agg CROSS JOIN batch b
     ORDER BY agg.rn;
$$;
-- Canonical prompt identity is independent of whether or how often a case
-- variant has been witnessed. Evidence expansion belongs to typed routing.
CREATE OR REPLACE FUNCTION converse.prompt_tree(p_text text)
    RETURNS TABLE(root_id bytea, node_index int, parent_index int, tier smallint,
                  byte_offset int, byte_length int, id bytea, surface text)
    AS 'laplace_execution_2e9b3225dced6056', 'pg_laplace_prompt_tree'
    LANGUAGE C STABLE PARALLEL SAFE;

DROP FUNCTION IF EXISTS laplace.prompt_words(text);
CREATE OR REPLACE FUNCTION converse.prompt_words(p_text text)
    RETURNS TABLE(ord int, word text, id bytea)
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE
BEGIN ATOMIC
    SELECT s.ord, s.word, s.id
    FROM converse.word_segment_resolved(p_text) s
    ORDER BY s.ord;
END;
-- converse.attested_language_batch(ids[]) -> (id, lang): the primary language of EACH id,
-- in one pass. This is the canonical body; converse.attested_language(one) delegates here.
--
-- WHY IT EXISTS (§15). This argmax was written twice: once as the scalar
-- converse.attested_language, and once inline as taxonomy.bubble_up's `cand_lang` CTE --
-- identical predicate, identical GROUP BY, identical tie-break, two bodies free to
-- drift. bubble_up then ran BOTH per call: the scalar once for the term, the inline
-- copy once for the candidate set.
--
-- WHY IT IS A BATCH. laplace.attestations is LIST (type_id) and this predicate is on
-- subject_id, so nothing prunes and every call pays the partition set. Measured:
-- the scalar costs 71.6 ms warm, so a per-term loop over a token stream pays that
-- per token, while one batched probe covers every id at once. Under auto_explain on
-- compose_batch, the per-token form showed cand_lang at 32,438 ms over 728 loops.
--
-- The definition is unchanged from the scalar: argmax over SUM(sum_score_fp1e9) per
-- Language-typed context, ties on context_id. A row COUNT here would be the
-- frequency prior §7 forbids -- the weight is the fold's own adjudicated input, not
-- a tally. Contexts are not all languages (chess play and ordinals appear there
-- too), so the context entity is type-checked rather than assumed.
--
-- Ids with no Language-typed attestation return NO ROW, not a NULL row. Callers
-- LEFT JOIN and treat the absence as "no primary language", which is the same
-- structural answer the scalar's NULL carried.
-- DROP ORDER IS LOAD-BEARING (same law as metric_ladder.sql.in:41-42).
-- taxonomy.bubble_up_batch is BEGIN ATOMIC and calls BOTH this function and
-- consensus.relation_family_ids, so the live catalog pins both their OIDs in
-- pg_depend. On a live-DB `ALTER EXTENSION UPDATE` — where all three already
-- exist — the installed dependent RESTRICTs its bases and the drop below fails.
-- A fresh install never sees it, because nothing is installed to pin anything;
-- only the live catalog knows, which is what scripts/check-upgrade-drop-order.py
-- asks. This file is the FIRST of the two bases in manifest.upgrade (174, against
-- generated/relation_family_ids.sql.in at 219), and the gate takes the first drop
-- position for a name, so dropping the dependent here clears both hazards.
-- Its CREATE stays at 330, after both bases exist, which BEGIN ATOMIC requires.
DROP FUNCTION IF EXISTS taxonomy.bubble_up(bytea, bytea[], integer);
DROP FUNCTION IF EXISTS taxonomy.bubble_up_batch(bytea[], bytea[], integer);
DROP FUNCTION IF EXISTS converse.attested_language(bytea);
DROP FUNCTION IF EXISTS converse.attested_language_batch(bytea[]);
CREATE OR REPLACE FUNCTION converse.attested_language_batch(p_ids bytea[])
    RETURNS TABLE(id bytea, lang bytea)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT DISTINCT ON (a.subject_id) a.subject_id, a.context_id
    FROM laplace.attestations a
    JOIN laplace.entities e ON e.id = a.context_id
                           AND e.type_id = realize.canonical_id('Language')
    WHERE a.subject_id = ANY (p_ids)
    GROUP BY a.subject_id, a.context_id
    ORDER BY a.subject_id, SUM(a.sum_score_fp1e9) DESC, a.context_id;
END;
-- The language a surface's own testimony was made in, read from provenance.
--
-- Consensus excludes source and context from identity (INVENTION §5), so the fold
-- cannot answer this; the attestation layer keeps it. context_id carries the
-- language for the lexical sources, and the row carries the fold's own inputs, so
-- the answer is an argmax over adjudicated evidence weight -- a row COUNT would be
-- the frequency prior §7 forbids.
--
-- Distinct from converse.word_language, which is an argmax over HAS_LANGUAGE
-- ASSERTIONS about the word. That form does not discriminate: a loanword carries
-- those edges in many languages at once. This reads which language the testimony
-- ITSELF came from, which is the question a language-scoped read is asking.
--
-- The set function owns that definition. This scalar is only a one-element adapter;
-- keeping another GROUP BY/argmax here previously made the documented "delegates"
-- contract false and let the two answers drift.
CREATE OR REPLACE FUNCTION converse.attested_language(p_word bytea)
    RETURNS bytea
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE
BEGIN ATOMIC
    SELECT al.lang
    FROM converse.attested_language_batch(ARRAY[p_word]) al
    WHERE al.id = p_word;
END;
-- converse.word_language — GH #862 / #860. No SET (it invalidates plan caching and
-- blocks inlining, and this is a per-row call on the realize.render path), real schema names.
--
-- THE CANDIDATE SET IS THE BODY; THE ARGMAX IS A PROJECTION (2026-08-23).
--
-- word_language answers "which language is this word in" by taking the top HAS_LANGUAGE
-- edge. converse.prompt_state needs the question one step earlier -- WHICH LANGUAGES IS
-- THIS WORD ATTESTED IN -- so it can resolve the token against the prompt's own language
-- tally instead of against a global argmax. Written inline there, that would have been a
-- second copy of this predicate, free to drift from this one: the exact defect
-- attested_language_batch.sql.in was written to undo ("identical predicate, identical
-- GROUP BY, identical tie-break, two bodies free to drift").
--
-- So the set is the canonical body and the scalar delegates to it. One predicate, one
-- place that spells HAS_LANGUAGE, and callers take the projection they need.
--
-- WHY IT IS A BATCH: same reason as attested_language_batch. laplace.consensus is
-- LIST (type_id), this predicate is on subject_id, and a per-token loop pays the whole
-- partition set once per token.
--
-- The ORDER BY gains `lang` as a final tie-break. Without it two languages at equal
-- eff_mu -- which is not hypothetical, it is what `glacier` does across eng and fra --
-- resolve in whatever order the scan returns, and spec 05 requires the read path be
-- deterministic. Same winner as before wherever a winner existed.
DROP FUNCTION IF EXISTS laplace.word_language(bytea);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION converse.word_language_candidates_batch(p_words bytea[])
    RETURNS TABLE(word bytea, lang bytea, mu double precision)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT c.subject_id, c.object_id, consensus.eff_mu(c.rating, c.rd)
    FROM laplace.consensus c
    WHERE c.subject_id = ANY (p_words)
      AND c.type_id = laplace.relation_type_id('HAS_LANGUAGE')
      AND c.object_id IS NOT NULL;
END;

CREATE OR REPLACE FUNCTION converse.word_language(p_word bytea)
    RETURNS bytea
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE
BEGIN ATOMIC
    SELECT v.lang
    FROM converse.word_language_candidates_batch(ARRAY[p_word]) v
    ORDER BY v.mu DESC, v.lang
    LIMIT 1;
END;



DROP FUNCTION IF EXISTS laplace.synonyms(bytea, int);
CREATE OR REPLACE FUNCTION converse.synonyms(p_word bytea, p_limit int DEFAULT 10)
    RETURNS TABLE(synonym text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE
 AS $$
    -- Dedup and rank by member id, never by rendered surface: identical content
    -- always hashes to the same id, so two members that render alike are
    -- DISTINCT content (homographs) and must stay distinct rows. render_text
    -- runs above the sort, streaming off the ranked candidates only until
    -- p_limit rows survive the empty-surface filter.
    WITH src_lang AS (SELECT converse.word_language(p_word) AS id),
    agg AS (
        SELECT sm.member, max(sm.mu) AS mu, max(sm.witnesses) AS witnesses,
               max(sm.sense_mu) AS sense_mu
        FROM lexical.synset_members(p_word) sm
        WHERE sm.lang = (SELECT id FROM src_lang)
        GROUP BY sm.member
    )
    -- eff_mu is emitted DESCALED via the canonical law function (a.mu is already
    -- a raw ×1e9 eff_mu from synset_members; rd=0 => round(mu/1e9, 3)). Ordering
    -- above still runs on the raw mu, so ranking is unchanged. (Was the lone
    -- recall_*_response outlier leaking the raw fixed-point value.)
    SELECT r.txt AS synonym, consensus.eff_mu_display(a.mu, 0) AS eff_mu, a.witnesses
    FROM (
        SELECT member, mu, witnesses FROM agg
        ORDER BY sense_mu DESC NULLS LAST, mu DESC, witnesses DESC, member
    ) a
    CROSS JOIN LATERAL (SELECT realize.render_text(a.member) AS txt) r
    WHERE NULLIF(btrim(r.txt), '') IS NOT NULL
    LIMIT p_limit
$$;



DROP FUNCTION IF EXISTS laplace.translations(bytea, int);
CREATE OR REPLACE FUNCTION converse.translations(p_word bytea, p_limit int DEFAULT 24)
    RETURNS TABLE(translation text, language text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE
 AS $$
    -- Dedup and rank by (member, lang) id pair, never by rendered surface: the
    -- old DISTINCT ON (realize.render_text(member)) collapsed distinct translations --
    -- even across different languages -- whenever their surfaces coincided.
    -- render_text/label run above the sort, streaming off the ranked candidates
    -- only until p_limit rows survive the empty-surface filter.
    WITH src_langs AS (
        SELECT c.object_id AS id FROM laplace.consensus c
        WHERE c.subject_id = p_word AND c.type_id = laplace.relation_type_id('HAS_LANGUAGE')
    ),
    agg AS (
        SELECT sm.member, sm.lang, max(sm.mu) AS mu, max(sm.witnesses) AS witnesses,
               max(sm.sense_mu) AS sense_mu
        FROM lexical.synset_members(p_word) sm
        WHERE sm.lang IS NOT NULL
          AND sm.lang NOT IN (SELECT id FROM src_langs)
        GROUP BY sm.member, sm.lang
    )
    -- a.mu is fp1e9 (synset_members) — convert through the one display definition
    SELECT r.txt AS translation, realize.label(a.lang) AS language, consensus.eff_mu_display(a.mu), a.witnesses
    FROM (
        SELECT member, lang, mu, witnesses FROM agg
        ORDER BY sense_mu DESC NULLS LAST, mu DESC, witnesses DESC, lang, member
    ) a
    CROSS JOIN LATERAL (SELECT realize.render_text(a.member) AS txt) r
    WHERE NULLIF(btrim(r.txt), '') IS NOT NULL
    LIMIT p_limit
$$;



DROP FUNCTION IF EXISTS laplace.translate_to(bytea, text, int);
CREATE OR REPLACE FUNCTION converse.translate_to(p_word bytea, p_lang text DEFAULT NULL,
                                        p_limit int DEFAULT 24)
    RETURNS TABLE(translation text, language text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    -- Dedup and rank by (member, lang) id pair, never by rendered surface (the
    -- old GROUP BY realize.render_text(member) conflated homographs). The user-supplied
    -- language reference is text, so it is resolved at the INPUT boundary: each
    -- DISTINCT candidate language is matched once against the reference (by
    -- label or definition surface), instead of re-rendering per member row.
    -- render_text runs above the sort, streaming until p_limit rows survive.
    -- object_id IS NOT NULL is load-bearing, not defensive: src_langs feeds a
    -- NOT IN below, and SQL NOT IN against a set containing one NULL evaluates
    -- to NULL for every row, dropping the entire result. HAS_LANGUAGE is emitted
    -- unary (null object) in some paths, so a single such row silently zeroes
    -- every translate_to call while language_coverage — same synset_members
    -- source, no NOT IN — keeps working.
    WITH src_langs AS (
        SELECT c.object_id AS id FROM laplace.consensus c
        WHERE c.subject_id = p_word AND c.type_id = laplace.relation_type_id('HAS_LANGUAGE')
          AND c.object_id IS NOT NULL
    ),
    want AS (SELECT NULLIF(btrim(lower(COALESCE(p_lang, ''))), '') AS name),
    agg AS (
        SELECT sm.member, sm.lang, max(sm.mu) AS mu, max(sm.witnesses) AS witnesses,
               max(sm.sense_mu) AS sense_mu
        FROM lexical.synset_members(p_word) sm
        WHERE sm.lang IS NOT NULL
          AND sm.lang NOT IN (SELECT id FROM src_langs)
        GROUP BY sm.member, sm.lang
    ),
    -- Definition surfaces for the CANDIDATE languages, rendered ONCE in a fenced
    -- CTE. This used to sit inside the lang_match predicate as
    -- `lower(realize.render_text(d.object_id)) = w.name`, i.e. a render evaluated per
    -- probed edge purely to classify it -- the render-to-classify defect the read
    -- law names, in the one position the law calls out. Same accept set, rendered
    -- a bounded number of times.
    --
    -- eff_mu > 0 is the tri-state guard: the old EXISTS matched on bare row
    -- presence, so a HAS_DEFINITION edge the fold had REFUTED still admitted the
    -- language. consensus carries no outcome column; refutation is a non-positive
    -- fold, the same test the walk uses to dead-end an edge.
    lang_def_names AS MATERIALIZED (
        SELECT d.subject_id AS lang, lower(realize.render_text(d.object_id)) AS dname
        FROM laplace.consensus d, want w0
        WHERE w0.name IS NOT NULL
          AND d.subject_id IN (SELECT DISTINCT lang FROM agg)
          AND d.type_id = laplace.relation_type_id('HAS_DEFINITION')
          AND consensus.eff_mu(d.rating, d.rd) > 0
    ),
    lang_match AS (
        -- No-filter call (name IS NULL): pass every candidate language through with
        -- ZERO rendering — Postgres does not guarantee OR short-circuit, so the old
        -- single-WHERE shape could evaluate realize.label()/realize.render_text() even when no
        -- language filter was supplied (the common call).
        SELECT l.lang
        FROM (SELECT DISTINCT lang FROM agg) l, want w
        WHERE w.name IS NULL
        UNION ALL
        -- Named filter: label rendered ONCE per candidate language as a fenced
        -- projection (not re-evaluated inside a predicate); the definition-surface
        -- fallback renders only for languages whose label missed. Accept set is
        -- identical to the old matcher.
        SELECT s.lang
        FROM (
            SELECT l.lang, lower(realize.label(l.lang)) AS lbl
            FROM (SELECT DISTINCT lang FROM agg) l, want w0
            WHERE w0.name IS NOT NULL
        ) s, want w
        WHERE s.lbl = w.name
           OR s.lang IN (SELECT ld.lang FROM lang_def_names ld WHERE ld.dname = w.name)
    )
    -- a.mu is fp1e9 (synset_members) — convert through the one display definition
    SELECT r.txt AS translation, realize.label(a.lang) AS language, consensus.eff_mu_display(a.mu), a.witnesses
    FROM (
        SELECT member, lang, mu, witnesses FROM agg
        WHERE lang IN (SELECT lang FROM lang_match)
        ORDER BY sense_mu DESC NULLS LAST, mu DESC, witnesses DESC, lang, member
    ) a
    CROSS JOIN LATERAL (SELECT realize.render_text(a.member) AS txt) r
    WHERE NULLIF(btrim(r.txt), '') IS NOT NULL
    LIMIT p_limit
$$;



DROP FUNCTION IF EXISTS laplace.language_coverage(bytea, int);
CREATE OR REPLACE FUNCTION converse.language_coverage(p_word bytea, p_limit int DEFAULT 40)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    WITH langs AS (
        SELECT DISTINCT realize.label(sm.lang) AS code
        FROM lexical.synset_members(p_word) sm
        WHERE sm.lang IS NOT NULL
        UNION
        SELECT realize.label(converse.word_language(p_word))
    ),
    shown AS (SELECT code FROM langs WHERE code IS NOT NULL ORDER BY code LIMIT p_limit)
    SELECT COALESCE(realize.label(p_word), '?') || ' is witnessed across '
           || (SELECT count(*) FROM langs WHERE code IS NOT NULL)::text || ' languages: '
           || (SELECT string_agg(code, ', ' ORDER BY code) FROM shown)
           || CASE WHEN (SELECT count(*) FROM langs WHERE code IS NOT NULL) > p_limit
                   THEN ', …' ELSE '' END,
           NULL::numeric,
           (SELECT count(*) FROM langs WHERE code IS NOT NULL)::bigint
    WHERE (SELECT count(*) FROM langs WHERE code IS NOT NULL) > 0
$$;
DROP FUNCTION IF EXISTS laplace.hypernyms(bytea, int);
CREATE OR REPLACE FUNCTION converse.hypernyms(p_word bytea, p_depth int DEFAULT 8)
    RETURNS TABLE(depth int, hypernym text, gloss text)
    LANGUAGE C STABLE STRICT
    AS 'laplace_substrate', 'pg_laplace_hypernyms';
-- converse.resolve_last_word — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace.resolve_last_word(text);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION converse.resolve_last_word(p_phrase text)
    RETURNS bytea
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE
BEGIN ATOMIC
    SELECT pw.id FROM converse.prompt_words(p_phrase) pw
    WHERE pw.id IS NOT NULL
    ORDER BY pw.ord DESC
    LIMIT 1;
END;
DROP FUNCTION IF EXISTS laplace.resolve_phrase(text);
CREATE OR REPLACE FUNCTION converse.resolve_phrase(p_phrase text)
    RETURNS bytea
    AS 'laplace_execution_2e9b3225dced6056', 'pg_laplace_resolve_phrase'
    LANGUAGE C STABLE STRICT;
-- converse.resolve — THE one string→id gateway (Issue 46): every read surface
-- resolves text to a content root through THIS function. Single words resolve by
-- the perfcache-backed word law; multi-token text by the native phrase resolver
-- (both in-system — ids are never constructed outside the extension's native hash).
-- Callers that already hold an id keep it; callers that hold TEXT call converse.resolve().
-- One implementation per fact (Rule #6): laplace.word_id/resolve_phrase remain the
-- primitives, this is the one door in front of them.
--
-- GH #862 / #860: no SET, real schema names.
DROP FUNCTION IF EXISTS laplace.resolve(text);
CREATE OR REPLACE FUNCTION converse.resolve(p_text text)
    RETURNS bytea
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    SELECT CASE
        WHEN position(' ' IN btrim(p_text)) = 0
            THEN laplace.word_id(btrim(p_text))
        ELSE converse.resolve_phrase(p_text)
    END
$$;
-- converse.prompt_language(prompt): which language is this prompt written in.
--
-- NATIVE (src/prompt_language.c). The SQL body this replaces used
-- converse.prompt_state() as a table source -- a per-row set-returning function -- and
-- called consensus.eff_mu() per row over a partitioned consensus join. Extracting it
-- from converse.chat() made it callable; the native implementation removes that
-- per-row SQL shape.
--
-- THE TALLY, EXTRACTED. This computation already existed -- inline, in the
-- body of converse.chat() -- and was therefore callable by nothing. converse.converse(),
-- converse.walk(), converse.infer() and converse.prompt_coherence() all need it and none could
-- reach it. A canonical implementation with one inline caller is the drift
-- shape spec 37 section 0 names; this is the same defect one level down.
--
-- WHY A TALLY AND NOT converse.word_language() PER TOKEN. converse.word_language() is LIMIT 1 --
-- one language per word -- which discards the distribution and makes a token
-- shared across languages ("chat" English/French, "die" English/German, "a"
-- in a dozen) look monolingual. Summing consensus.eff_mu over EVERY HAS_LANGUAGE edge
-- carried by the prompt's laplace.entities lets genuinely ambiguous tokens contribute
-- to both tallies and be settled by the tokens that are decisive, which is how
-- a reader disambiguates too.
--
-- TIER-AGNOSTIC BY CONSTRUCTION: it tallies whatever the prompt resolved to,
-- so a sentence-root HAS_LANGUAGE counts alongside word-tier evidence rather
-- than being invisible to a word-only scan.
--
-- NO FLOOR AND NO MINIMUM MARGIN: the fold already carries confidence, ties
-- break on the id for determinism, and a prompt with no language evidence
-- returns NULL -- the honest answer when the prompt genuinely does not say.
--
-- Returns the ranked tally, not just the winner, because an elector wants to
-- BIAS toward a language rather than hard-filter to it: a genuinely
-- cross-lingual prompt must still work, and the substrate's identity law is
-- language-agnostic by construction.
DROP FUNCTION IF EXISTS laplace.prompt_language(text);
CREATE OR REPLACE FUNCTION converse.prompt_language(p_prompt text)
    RETURNS TABLE(lang_id bytea, mass numeric)
    AS 'laplace_substrate', 'pg_laplace_prompt_language'
    LANGUAGE C STABLE;

-- The winner alone, for callers that just want to pin a rendering language.
-- A wrapper, not a second ladder.
DROP FUNCTION IF EXISTS laplace.prompt_language(text);
DROP FUNCTION IF EXISTS laplace.prompt_language_top(text);
CREATE OR REPLACE FUNCTION converse.prompt_language_top(p_prompt text)
    RETURNS bytea
    LANGUAGE sql STABLE AS $$
    -- "The winner" is a claim about MASS, so rank on it rather than trusting the
    -- C SRF's emission order. A wrapper that depends on an unstated ordering is a
    -- second ladder in disguise -- it silently re-decides the election if the
    -- native side ever reorders its output.
    SELECT lang_id FROM converse.prompt_language(p_prompt)
    ORDER BY mass DESC, lang_id
    LIMIT 1
$$;
-- converse.prompt_state — GH #862 / #860. No SET, real schema names.
--
-- A TOKEN'S LANGUAGE IS DECIDED BY THE PROMPT, NOT BY THE TOKEN ALONE (2026-08-23).
--
-- converse.word_language is a per-token global argmax over HAS_LANGUAGE. On the
-- live substrate `glacier` carries language:fra at eff_mu 1476.46 and language:eng
-- at 1474.74 -- five witnesses each, a 1.7 gap on ~1476, which is a tie decided by
-- whichever corpus happened to attest one more strongly. So "What is a glacier?"
-- reported: What (none), is -> enm (Middle English), a -> eng, glacier -> fra.
--
-- That is not cosmetic. prompt_coherence.c ranks lang_agree ABOVE witness count on
-- purpose -- "a sense in a language the prompt is not written in is the wrong sense
-- however well attested it is" -- so tagging the one CONTENT word of an English
-- prompt as French demotes it through the very axis that exists to protect
-- addressing, and hands the election to the function words.
--
-- The prompt already elects its own languages: converse.prompt_language returns a
-- ranked mass tally over every token, and INVENTION §7's election law says the
-- discriminating information lives BETWEEN the prompt's tokens, never in one of
-- them. So a token's language is resolved AGAINST that tally: among the languages
-- the token is actually attested in, prefer the one the prompt as a whole supports,
-- ordered by the prompt's mass and then by the token's own eff_mu.
--
-- Falls back to the global argmax when a token shares no language with the prompt
-- (a loanword, a name, a single-token prompt) -- an unattested intersection is not
-- an answer, so the previous behaviour stands rather than returning NULL. That
-- keeps prompt_language's own law: it is "a RANKED TALLY, never a single winner and
-- never a filter predicate" (src/prompt_language.c) -- this reads it as a bias,
-- never as a filter.
--
-- Set-based: one tally, one join, no per-row scalar (G2, id space throughout).
DROP FUNCTION IF EXISTS laplace.prompt_state(text);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION converse.prompt_state(p_text text)
    RETURNS TABLE(ord int, word text, id bytea, language bytea)
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE
BEGIN ATOMIC
    WITH tokens AS MATERIALIZED (
        SELECT pw.ord, pw.word, pw.id
        FROM converse.prompt_words(p_text) pw
        WHERE pw.id IS NOT NULL
    ), tally AS MATERIALIZED (
        SELECT pl.lang_id, pl.mass FROM converse.prompt_language(p_text) pl
    ), candidates AS MATERIALIZED (
        SELECT v.word, v.lang, v.mu
        FROM converse.word_language_candidates_batch(
                 (SELECT array_agg(t.id) FROM tokens t)) v
    ), agreed AS MATERIALIZED (
        SELECT DISTINCT ON (t.ord) t.ord, v.lang AS language
        FROM tokens t
        JOIN candidates v ON v.word = t.id
        JOIN tally ON tally.lang_id = v.lang
        ORDER BY t.ord, tally.mass DESC, v.mu DESC, v.lang
    )
    SELECT t.ord, t.word, t.id,
           COALESCE(a.language, converse.word_language(t.id))
    FROM tokens t
    LEFT JOIN agreed a ON a.ord = t.ord
    ORDER BY t.ord;
END;
-- converse.prompt_coherence(prompt): joint orientation + sense resolution.
--
-- NATIVE (src/prompt_coherence.c). The SQL body this replaces hung converse.chat() for
-- every prompt -- >280s measured 2026-07-27 after the UD ingest -- and was taken
-- off the hot path in the same change that ported it. It was SQL doing what the
-- substrate law puts in C: set-returning functions as table sources (one
-- lexical.senses() per token, one bubble_up per candidate relation type), relation-name
-- identifiers split with string_to_array per row, and an O(n^2) join of 277-315
-- candidate senses against each other through an OR of both directions that no
-- consensus index can serve. Rewriting it as two indexed joins behind a
-- MATERIALIZED fence still measured 82s.
--
-- The C form is the same computation as a MEMBERSHIP SCAN: candidates fetched
-- once, then one indexed range read per direction with an O(1) hash probe per
-- edge. consensus.relation_rank and the canonical name come from the manifest in C
-- (laplace_relation_lookup), and the name's object token becomes a content id
-- through the same hash the substrate uses everywhere -- so no per-row SQL
-- function call survives anywhere in the read.
--
-- Returns, per prompt token, its best sense and the signals it was chosen by:
--   specificity  coherence / own rated mass. A candidate with no direct prompt
--                evidence reports zero; structural rarity is a separate
--                diagnostic and is never substituted into this differently
--                dimensioned scalar.
--   coherence    rated mass to the OTHER tokens' candidate senses
--   rel_mass     scale-free SHARE of the candidate's own witnessed mass carried in a
--                relation type another token NAMES (raw mass = rel_mass * total_mass;
--                "what are the X of Y" shape, where X is a relation not a peer)
--   total_mass   ALL rated mass on the candidate -- specificity's denominator,
--                exposed for the electors' inverse-mass fallback (below)
--
-- RANK ON SPECIFICITY, NEVER ON MASS. Every mass-shaped scalar tried here has
-- elected function words, because they are wired to everything: denote_mu picked
-- the article and TZAR, highway breadth tied "a" with "pawn", and raw coherence
-- put `is`/`of`/`was` first on every prompt measured. The share of a candidate's
-- own mass that reaches the rest of the prompt is scale-free and separates them
-- cleanly -- measured on "What is a pawn in chess?": total mass a = 4.28e16,
-- chess = 5.28e14, pawn = 2.63e13, and pawn/chess elect correctly.
--
-- THE SINGLE-CONTENT-WORD LIMIT (2026-08-01). A prompt with one content word
-- has no pair to cohere with: every candidate returns specificity 0 and the
-- election fell through to denote_mu, which favors function words -- "What is
-- a glacier?" elected the article (denote_mu 1169.7 vs 1082.3) and answered
-- about the letter A. total_mass (specificity's denominator, computed here all
-- along and discarded) is now a column; the INVERSE-mass election it was first
-- exposed for was REFUTED by measurement on the foundation-only seed (the
-- article's elected sense is LATIN SMALL LETTER A, 5.85e12 -- BELOW glacier,
-- dog and napoleon; the 4.28e16 article of the earlier notes was a UD-era
-- token, not a law), and mass DESC fails "parts of a car" (parts > car). The
-- The elector sites declared and pinned by ElectorArchitectureGateTests instead
-- break the all-silent case by ord DESC -- recency among sense-bearing candidates,
-- resolve_last_word's semantics restricted to tokens the graph holds senses for.
-- total_mass stays exposed: it is the signal that consensus.refuted the premise, and the
-- election diagnostic reads it.
DROP FUNCTION IF EXISTS laplace.prompt_coherence(text);
CREATE OR REPLACE FUNCTION converse.prompt_coherence(p_prompt text)
    RETURNS TABLE(ord int, tok bytea, synset_id bytea,
                  coherence double precision, denote_mu numeric, peers bigint,
                  rel_type_id bytea, rel_mass double precision,
                  specificity double precision, total_mass double precision)
-- witnesses + lang_agree ARE computed and ARE the comparator's new sort keys
-- (src/prompt_coherence.c), but they are NOT declared here yet, deliberately.
--
-- laplace_substrate is in shared_preload_libraries, so the postmaster pins the
-- image and every backend inherits it by fork; an installed .so is inert until
-- PostgreSQL restarts. Widening this TABLE without that restart puts a 12-column
-- descriptor in front of a 10-column C function, and tuplestore_putvalues then
-- reads two Datums past the end of its stack arrays -- an overread on the live
-- converse path, observed 2026-08-05 returning NULLs for both columns.
--
-- The C symbol-integrity gate does NOT catch this: every symbol resolves. Symbol
-- existence is not signature agreement, and nothing in the sync path compares
-- returned column counts across the image boundary.
--
-- Re-add both columns in the same change that bounces PostgreSQL. Until then the
-- keys still rank -- they live in the comparator, not in the output.
    AS 'laplace_substrate', 'pg_laplace_prompt_coherence'
    LANGUAGE C STABLE;
-- converse.elect — THE topic election. One implementation, one key order.
--
-- Spec 37's implementation law: "There is one canonical implementation per
-- operation fact. SQL references and native accelerators require parity tests.
-- Endpoint-specific helpers delegate to the same program. Installation cannot
-- arbitrarily select competing semantic bodies."
--
-- The election (OP6 STEER + OP7 SELECT over converse.prompt_coherence) was
-- implemented SIX times: converse.sql.in, converse_walk.sql.in, resolve_topic.sql.in,
-- infer.sql.in, orient_topic.sql.in, and mirrored a seventh time in Python at
-- scripts/eval-generation.py (_elector_key). They were kept in step only by
-- ElectorArchitectureGateTests asserting the six ORDER BY strings match each other
-- -- a gate that can prove they are IDENTICAL but never that they are RIGHT, and
-- whose own header records the drift it was written for: "The weighted order landed
-- in chat.sql.in ALONE, leaving the other four sites on the old keys."
--
-- W4 stated the consequence: "the gate is honest and the thing it guards is hollow."
--
-- This is the body. The key order is unchanged, verbatim, so this commit changes
-- WHERE the election lives and not WHAT it decides -- the two are separable and are
-- being separated deliberately. Changing the judgement (INVENTION §7: "no ranking
-- may be decided on a single-token scalar"; W15: "an election is convergence across
-- independent evidence classes, not an extremum on one axis") is the next change,
-- and after this one it is a single edit rather than six that can drift five ways.
--
-- Returns the elected row rather than one column, because the six sites want
-- different fields off the same decision: converse and converse_walk take
-- synset_id, resolve_topic takes tok, orient_topic takes the whole row, infer takes
-- the rank. One election, several projections.
-- No DROP FUNCTION here. converse(), converse_walk() and resolve_topic() reference
-- these bodies from BEGIN ATOMIC, which records a hard catalog dependency, so a
-- DROP on the upgrade path fails against the callers installed by the previous
-- version. The signatures are new and never change under replace, so CREATE OR
-- REPLACE alone is both sufficient and idempotent.
CREATE OR REPLACE FUNCTION converse.elect(p_prompt text)
    RETURNS TABLE(ord int, tok bytea, synset_id bytea,
                  coherence double precision, denote_mu numeric, peers bigint,
                  rel_type_id bytea, rel_mass double precision,
                  specificity double precision, total_mass double precision)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT y.ord, y.tok, y.synset_id, y.coherence, y.denote_mu, y.peers,
           y.rel_type_id, y.rel_mass, y.specificity, y.total_mass
    FROM converse.prompt_coherence(p_prompt) y
    ORDER BY y.specificity DESC NULLS LAST,
             y.rel_mass    DESC NULLS LAST,
             y.peers       DESC,
             y.ord         DESC,
             y.denote_mu   DESC NULLS LAST,
             y.synset_id
    LIMIT 1;
END;

-- The abstention gate resolve_topic applies, as its own delegating projection.
-- specificity is coherence over the candidate's own total mass, so it is 0 for
-- every token when no pair of tokens shares a rated edge -- an unseeded domain, not
-- a wrong answer. resolve_topic.sql.in: "Without the gate the tiebreaks alone would
-- decide the all-zero prompt ... an arbitrary token dressed up as a decision."
CREATE OR REPLACE FUNCTION converse.elect_topic(p_prompt text)
    RETURNS bytea
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT e.tok FROM converse.elect(p_prompt) e WHERE e.specificity > 0;
END;

-- Sense projection: the synset the elected token resolved to. No abstention gate --
-- converse() and converse_walk() have always taken the synset unconditionally and
-- handle NULL themselves.
CREATE OR REPLACE FUNCTION converse.elect_sense(p_prompt text)
    RETURNS bytea
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT e.synset_id FROM converse.elect(p_prompt) e;
END;
-- converse.first_placed_topic — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace.first_placed_topic(text);
CREATE OR REPLACE FUNCTION converse.first_placed_topic(p_text text)
    RETURNS bytea
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE AS $$
    SELECT w.id
    FROM laplace.v_word_points w
    JOIN converse.prompt_state(p_text) s ON w.id = s.id
    WHERE w.coord IS NOT NULL
    -- "first" is a claim about prompt order, so it has to be stated. Without this
    -- the LIMIT took an arbitrary placed token out of a multi-token prompt and the
    -- answer could change between identical calls. Same ranking the structural
    -- siblings use (structural_locale, structural_neighbors): prompt ordinal, then
    -- physicality_id to break the tie a repeated surface would otherwise leave open.
    ORDER BY s.ord, w.physicality_id
    LIMIT 1
$$;
DROP FUNCTION IF EXISTS laplace.realize_path(bytea[], bytea[], int[], bytea);
CREATE OR REPLACE FUNCTION realize.path(p_path bytea[], p_types bytea[], p_dirs int[],
                                        p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
    -- realize.label() before '?': an id with no realization in p_lang usually still has a
    -- name, and printing '?' for it threw that away. The walk responders open-coded
    -- this whole realize.render specifically because they needed the label tier
    -- (GH #906 item 2); with it here they can route through the one definition.
    -- Strictly additive -- the only rows this changes are the ones that used to
    -- print '?'.
    WITH batch AS MATERIALIZED (
      SELECT realize.batch(p_path,p_lang) AS realized,
             realize.label_batch(p_path) AS labels,
             lexical.type_label_batch(p_types) AS types
    ),
    node AS (
      SELECT i,
             -- AN ILI ID IS AN IDENTIFIER WEARING CONTENT'S CLOTHES. The COALESCE above
             -- reached realize.label() only when realize.batch ABSTAINED, and its contract
             -- is to abstain with NULL — so the ladder was sound for the case it was written
             -- for. A synset is not that case: CILI's canonical name for one IS the
             -- Interlingual Index id, so the canonical arm returns a real, non-NULL
             -- realization, COALESCE takes it, and the label tier is never consulted.
             --
             -- MEASURED 2026-08-16 on synset f59f0970 (cat): realize.batch returns 'i46593'
             -- where realize.label_batch returns 'cat', and its IS_A object realizes as
             -- 'i46591' against the label 'feline'. Every chain consensus.relate_path
             -- returned was therefore unreadable — 'i37666 —is a→ i37665 —is a→ i37650' for
             -- house/building, on both the old and the rewritten body.
             --
             -- Matched by SHAPE, not by source: ^i[0-9]+$ is the ILI form and is not a word
             -- in any language this renders. The realization still wins wherever it is
             -- anything else, and '?' is still the floor when both tiers abstain. The right
             -- place to stop this is ingest — an ILI id should not be deposited as a
             -- canonical name — but that is a re-ingest, and this function must not print an
             -- identifier at a reader in the meantime.
             CASE WHEN b.realized[i] ~ '^i[0-9]+$' AND b.labels[i] IS NOT NULL
                  THEN b.labels[i]
                  ELSE COALESCE(b.realized[i], b.labels[i], '?')
             END AS nm,
             b.types AS types
      FROM batch b CROSS JOIN generate_subscripts(p_path, 1) AS i
    )
    SELECT string_agg(
               CASE WHEN n.i = 1
                    THEN n.nm
                    ELSE CASE WHEN p_dirs[n.i-1] = -1
                              THEN ' ←' || COALESCE(n.types[n.i-1], '?') || '— '
                              ELSE ' —' || COALESCE(n.types[n.i-1], '?') || '→ '
                         END || n.nm
               END, '' ORDER BY n.i)
    FROM node n
$$;
-- realize.path (3-arg) — GH #862 / #860. Thin wrapper: the directed 4-arg form is
-- the single implementation; forward-only rendering is the NULL-dirs case
-- (p_dirs[i-1] = -1 is NULL for a NULL array, so every connector takes the forward
-- arrow — identical output to the old copy-pasted 3-arg body).
--
-- No SET: it blocks inlining, and a wrapper that cannot inline is a whole extra
-- function execution to forward three arguments.
DROP FUNCTION IF EXISTS laplace.realize_path(bytea[], bytea[], bytea);
CREATE OR REPLACE FUNCTION realize.path(p_path bytea[], p_types bytea[],
                                        p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT realize.path(p_path, p_types, NULL::int[], p_lang)
$$;
DROP FUNCTION IF EXISTS laplace.isa_path(bytea, bytea, int);
CREATE OR REPLACE FUNCTION converse.isa_path(p_x bytea, p_y bytea, p_depth int DEFAULT 8)
    RETURNS TABLE(path bytea[], types bytea[], path_mu numeric)
    LANGUAGE C STABLE STRICT PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_isa_path';
-- converse.epistemic_status_core — the VERDICT rule alone, numeric end to end.
-- Split out 2026-08-21: ops.entity_record needs four counts, but the only surface
-- carrying the rule also rendered + realized up to p_limit object texts
-- (render_text_batch AND realize.batch) that a counter throws away. MEASURED on a
-- hot entity (Carlsen, limit 500): 1,984 ms through the rendering wrapper, 308 ms
-- through this core — identical counts (8/0/0/317). One rule, two consumers:
-- epistemic_status adds the text; counters stop paying for it.
DROP FUNCTION IF EXISTS converse.epistemic_status_core(bytea, int);
CREATE OR REPLACE FUNCTION converse.epistemic_status_core(p_word bytea, p_limit int DEFAULT 30)
    RETURNS TABLE(type_id bytea, object_id bytea, status text, rating bigint,
                  rd bigint, volatility bigint, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH subj(id) AS (SELECT p_word UNION SELECT sn.synset_id FROM lexical.senses(p_word) sn),
         rels AS (
            SELECT c.type_id, c.object_id, c.rating, c.rd, c.volatility, c.witness_count
            FROM laplace.consensus c JOIN subj s ON c.subject_id = s.id
            WHERE c.object_id IS NOT NULL
              AND c.type_id NOT IN (laplace.relation_type_id('HAS_SENSE'),
                                    laplace.relation_type_id('IS_SENSE_OF'),
                                    laplace.relation_type_id('HAS_LANGUAGE'))
            ORDER BY consensus.edge_rank(c.type_id, consensus.eff_mu(c.rating, c.rd)) DESC
            LIMIT p_limit)
    SELECT r.type_id, r.object_id,
           CASE WHEN consensus.refuted(r.rating, r.rd) THEN 'refuted'
                WHEN consensus.eff_mu(r.rating, r.rd) > consensus.glicko2_neutral_mu() THEN 'confirmed'
                WHEN r.volatility::numeric > consensus.glicko2_initial_volatility() * 1.5 THEN 'contested'
                ELSE 'thin' END,
           r.rating, r.rd, r.volatility, r.witness_count
    FROM rels r
    ORDER BY consensus.edge_rank(r.type_id, consensus.eff_mu(r.rating, r.rd)) DESC;
END;

-- converse.epistemic_status — GH #862 / #860. No SET, real schema names.
-- The verdict rule lives in epistemic_status_core; this wrapper ADDS the rendered
-- fact text and type labels for surfaces that show them.
DROP FUNCTION IF EXISTS laplace.epistemic_status(bytea, bytea, int);
CREATE OR REPLACE FUNCTION converse.epistemic_status(p_word bytea, p_lang bytea DEFAULT NULL,
                                            p_limit int DEFAULT 30)
    RETURNS TABLE(type text, fact text, status text, mu numeric,
                  volatility numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH rels AS MATERIALIZED (
            SELECT * FROM converse.epistemic_status_core(p_word, p_limit)),
         lang(id) AS (SELECT COALESCE(p_lang, converse.word_language(p_word))),
         object_ids AS MATERIALIZED (
            SELECT array_agg(DISTINCT object_id ORDER BY object_id) AS a FROM rels),
         rendered AS (
            SELECT i.id,NULLIF(i.rendered,'') AS rendered,i.realized
            FROM object_ids,
              LATERAL ROWS FROM (
                unnest(object_ids.a),
                unnest(realize.render_text_batch(object_ids.a)),
                unnest(realize.batch(object_ids.a,(SELECT id FROM lang)))
              ) i(id, rendered, realized)
         ),
         type_ids AS MATERIALIZED (
            SELECT array_agg(DISTINCT type_id ORDER BY type_id) AS a FROM rels),
         type_labels AS (
            SELECT i.id,i.type_label
            FROM type_ids,
              LATERAL ROWS FROM (
                unnest(type_ids.a),
                unnest(lexical.type_label_batch(type_ids.a))
              ) i(id, type_label)
         )
    SELECT td.type_label,
           COALESCE(rd.rendered, rd.realized),
           r.status,
           consensus.eff_mu_display(r.rating, r.rd),
           round(r.volatility / 1e9, 4), r.witnesses
    FROM rels r
    LEFT JOIN rendered rd ON rd.id = r.object_id
    LEFT JOIN type_labels td ON td.id = r.type_id
    ORDER BY consensus.edge_rank(r.type_id, consensus.eff_mu(r.rating, r.rd)) DESC
$$;
DROP FUNCTION IF EXISTS laplace.contrast(bytea, bytea, bytea, int);
CREATE OR REPLACE FUNCTION converse.contrast(p_x bytea, p_y bytea, p_lang bytea DEFAULT NULL,
                                    p_limit int DEFAULT 80)
    RETURNS TABLE(holder text, type text, fact text, mu numeric)
    LANGUAGE C STABLE PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_contrast';
-- The structural read entry point.
--
-- The caller names the shape of the read and passes resolved content ids; the
-- substrate never guesses either from the surface form of a question. This is
-- what replaced parse_ask() and the English pattern ladder behind it.
--
--   p_intent       one of converse.query_shapes().shape
--   p_topic        subject id (converse.resolve_ref accepts a word or an id hex)
--   p_topic2       object id, for the two-topic shapes (is_a, reason)
--   p_type_name    canonical relation type, for the related / related_in shapes
--   p_lang         target language, for the translate shape
--   p_context_ids  other resolved ids, used to disambiguate a sense
DROP FUNCTION IF EXISTS laplace.recall_intent(text, bytea, bytea, text, text, bytea[]);
CREATE OR REPLACE FUNCTION converse.recall_intent(
        p_intent text,
        p_topic bytea,
        p_topic2 bytea DEFAULT NULL,
        p_type_name text DEFAULT NULL,
        p_lang text DEFAULT NULL,
        p_context_ids bytea[] DEFAULT NULL)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE C STABLE
    AS 'laplace_substrate', 'pg_laplace_recall_intent';
-- The read shapes a caller may ask for, and what each one needs.
--
-- Published so a client builds its controls from the substrate instead of
-- hardcoding a menu. Every shape is named for the structure it reads, not for
-- an English phrasing that would select it.
DROP FUNCTION IF EXISTS laplace.query_shapes();
CREATE OR REPLACE FUNCTION converse.query_shapes()
    RETURNS TABLE(shape text, summary text, needs_topic2 boolean,
                  needs_type boolean, accepts_lang boolean)
    LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    VALUES
      ('define',      'witnessed glosses, disambiguated by context ids', false, false, false),
      ('what_is',     'gloss plus the IS_A ladder upward',               false, false, false),
      ('describe',    'salient facts across the content bands',          false, false, false),
      ('synonyms',    'equivalence-band surfaces',                       false, false, false),
      ('translate',   'cross-lingual surfaces through the ILI hub',      false, false, true),
      ('languages',   'which languages witness this concept',            false, false, false),
      ('examples',    'witnessed usage examples',                        false, false, false),
      ('related',     'outgoing edges of one relation type',             false, true,  false),
      ('related_in',  'incoming edges of one relation type',             false, true,  false),
      ('is_a',        'witnessed IS_A chain between two topics',         true,  false, false),
      ('reason',      'how two topics relate, with a verdict',           true,  false, false),
      ('walk',        'chat: steered seed-responsive generation over witnessed text (unsteered fallback); recall_intent: greedy strongest-edge chain', false, false, false),
      ('complete',    'COMPLETES_TO beam from the topic',                false, false, false),
      ('fallback',    'gloss, then the strongest chain',                 false, false, false)
$$;
-- The salience bands: the lens vocabulary.
--
-- A band is a set of relation types sharing a read-time rank, addressed by one
-- precomputed highway mask. Selecting bands is how a caller narrows a read
-- without naming a single relation and without naming a language.
--
-- Two functions, because they cost different amounts. converse.relation_band_catalog()
-- is the NAMING — IMMUTABLE, no table access, safe to JOIN inside any read.
-- converse.relation_bands() adds LIVE consensus counts, which is a full aggregate over
-- the consensus tree (measured 1.34s at 5.66M rows), so it belongs in a catalog
-- call a client makes once and caches — never in a per-query join.
DROP FUNCTION IF EXISTS laplace.relation_band_catalog();
CREATE OR REPLACE FUNCTION converse.relation_band_catalog()
    RETURNS TABLE(band integer, name text, rank double precision)
    LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    VALUES
      (0,  'mandate',              1.00::double precision),
      (1,  'definitional',         0.97),
      (2,  'taxonomic',            0.90),
      (3,  'equivalence',          0.82),
      (4,  'partitive',            0.73),
      (5,  'causal',               0.64),
      (6,  'oppositional',         0.45),
      (7,  'associative',          0.36),
      (8,  'tensor_calculation',   0.27),
      (9,  'lexical_glue',         0.18),
      (10, 'scalar_valued',        0.12),
      (11, 'standards_structural', 0.08),
      (12, 'probationary',         0.05)
$$;

DROP FUNCTION IF EXISTS laplace.relation_bands();
CREATE OR REPLACE FUNCTION converse.relation_bands()
    RETURNS TABLE(band integer, name text, rank double precision,
                  relation_types bigint, consensus_rows bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH live AS (
        SELECT consensus.relation_highway_band(c.type_id) AS band,
               c.type_id,
               count(*) AS rows
        FROM laplace.consensus c
        GROUP BY 1, 2
    )
    SELECT b.band,
           b.name,
           b.rank,
           count(live.type_id)::bigint,
           COALESCE(sum(live.rows), 0)::bigint
    FROM converse.relation_band_catalog() b
    LEFT JOIN live ON live.band = b.band
    GROUP BY b.band, b.name, b.rank
    ORDER BY b.band
$$;
-- converse.resolve_topic(phrase, context): the topic a prompt is about.
--
-- ONE ELECTION, ONE KEY ORDER. converse.chat(), converse.converse() and converse.walk() all orient
-- through converse.prompt_coherence() on the identical sort key, with the stated invariant
-- that the three "cannot disagree about what a prompt is about". resolve_topic is
-- the FOURTH orientation path -- it is what converse.recall() resolves through (recall.c
-- spi_resolve_topic) -- and it disagreed with all three. The elector was already
-- built, compiled and correct; converse.recall() just never called it.
--
-- WHAT ACTUALLY DECIDED THE TOPIC, measured: not converse.resolve_last_word() but
-- converse.resolve_phrase(). That function is a longest-span-first, LEFTMOST-wins span
-- resolver (content_resolve.c: `for L = n..1` outer, i ascending inner, first
-- stored span wins) -- so on any prompt where no long span is stored it descends
-- to single words and returns the leftmost one that happens to be a stored
-- entity. `converse.resolve_phrase('What is a pawn in chess?')` = `What`;
-- `converse.resolve_phrase('what is rain')` = `what`. resolve_last_word was almost never
-- reached, and on that same question returns `QUESTION MARK`.
--
-- So the election cannot sit behind resolve_phrase -- that is where it was first
-- placed, and it was dead code for every multi-word prompt containing any known
-- word, which is all of them. It has to come first.
--
-- ORDER OF RESOLUTION, and why:
--   1. the specificity election -- the same call and the same key order as
--      converse.chat()/converse.converse()/converse.walk(), so all four now agree by construction.
--   2. converse.resolve_phrase() -- reached only when the election is silent. This is NOT
--      a demotion: measured, the election is silent on exactly the inputs that
--      ARE an entity ('pawn', 'ice cream', 'New York', 'carbon dioxide' all
--      return specificity 0 with no peers), because a phrase that resolves whole
--      has no token pair to be coherent across. Identity still wins where
--      identity exists; the election only speaks when there are competing tokens.
--   3. converse.resolve_last_word() -- unchanged, and still the last resort.
--
-- WHY specificity > 0 GATES THE ELECTION: specificity is coherence over the
-- candidate's own total mass, so it is 0 for every token when no pair of tokens
-- shares a rated edge -- an unseeded domain, not a wrong answer. Measured:
-- 'will it rain in nashville in the next seven days' returns specificity 0 for
-- ALL nine candidate tokens (the graph holds no edge among rain/nashville/
-- weather -- no such source is seeded), while 'What is a pawn in chess?' returns
-- pawn 0.0441, chess 0.0363, and 0 for a/in. Without the gate the tiebreaks
-- alone would decide the all-zero prompt, and they rank `next` (denote_mu
-- 1391.2) above `rain` (1169.7), with `in` and `will` tied against it -- an
-- arbitrary token dressed up as a decision. With the gate, a no-signal prompt
-- falls through unchanged and the election only ever fires when the graph
-- actually said something.
--
-- The honest consequence, stated so nobody re-derives it as a bug: 'what is
-- rain' still resolves to `what`, because rain's domain is unseeded and the
-- election has nothing to say. That is a seeding gap, not a defect in this
-- body, and it resolves itself the moment a source rates an edge on rain.
--
-- NOT PARALLEL SAFE: converse.prompt_coherence() is `LANGUAGE C STABLE` with no parallel
-- marking, so this body cannot claim more than its callee. recall.c invokes this
-- as a single scalar SPI select, where parallelism was never in play.
DROP FUNCTION IF EXISTS laplace.resolve_topic(text, bytea);
CREATE OR REPLACE FUNCTION converse.resolve_topic(p_phrase text, p_context bytea)
    RETURNS bytea
    LANGUAGE sql STABLE AS $$
    SELECT CASE
        WHEN p_phrase IS NULL OR btrim(p_phrase) = '' THEN p_context
        -- Literal content id (incl. a FEN rewritten to hex by the app resolve
        -- hook, GH #575). Same arm resolve_ref already has — without it a
        -- hex prompt falls through to resolve_phrase and hashes the digits.
        -- Case-insensitive: pasted ids arrive uppercase too, and decode()
        -- accepts either; a lowercase-only class silently hashed A-F pastes.
        WHEN btrim(p_phrase) ~ '^[0-9a-fA-F]{32}$' THEN decode(btrim(p_phrase), 'hex')
        WHEN p_context IS NOT NULL
             AND btrim(lower(p_phrase), ' ?.!') ~ '^(it|its|that|this|they|their|them|those|these|one|he|she|him|her)$'
            THEN p_context
        ELSE COALESCE(
            -- Delegates to converse.elect_topic -- the ONE election body, which
            -- carries this site's `specificity > 0` abstention gate (spec 37).
            converse.elect_topic(p_phrase),
            converse.resolve_phrase(p_phrase),
            converse.resolve_last_word(p_phrase))
    END
$$;
DROP FUNCTION IF EXISTS laplace.recall(text, bytea);
CREATE OR REPLACE FUNCTION converse.recall(p_prompt text, p_context bytea DEFAULT NULL)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE C STABLE
    AS 'laplace_substrate', 'pg_laplace_recall';
-- converse.witness_precedes_chain(text, source): deposit a text's consecutive-token PRECEDES
-- bigrams as laplace.attestations under a source -- the OODA ACT/OBSERVE deposit. This is how a
-- prompt becomes witnessed content and a response becomes a first-class witness: the
-- generated text's own edges fold into the SAME consensus the next walk reads
-- (evaluation IS ingestion). Self-signals are outranked by design (Response/UserPrompt
-- trust classes), so self-witnessing cannot outshout curated sources.
--
-- ONE batched fold through the ingest spine (consensus_upsert) instead of the old
-- per-bigram laplace_witness loop (2 statements per pair, per chat turn). Repeated
-- bigrams in one chain aggregate into ONE (games, sum) cell -- the rating period IS
-- the chain, exactly how the writer spine folds duplicates (its client-dedup
-- contract); arrays arrive sorted (type, subject, id) per that contract. Same cells,
-- same outcomes (score 1e9 per game -- a win, as the loop scored), same witness
-- counts. One deliberate spine alignment: laplace_witness seeded a NOVEL cell at
-- neutral WITHOUT folding its first game (the first outcome was dropped);
-- consensus_upsert's novel arm folds every game -- no signal is discarded.
DROP FUNCTION IF EXISTS laplace.witness_precedes_chain(text, bytea);
CREATE OR REPLACE FUNCTION converse.witness_precedes_chain(p_text text, p_source bytea)
    RETURNS int
    LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    r_prec bytea := laplace.relation_type_id('PRECEDES');
    ids    bytea[];
    n      int;
    subs   bytea[];
    objs   bytea[];
    games  bigint[];
    sums   bigint[];
BEGIN
    SELECT array_agg(id ORDER BY ord) INTO ids
    FROM converse.prompt_state(p_text) WHERE id IS NOT NULL;
    n := COALESCE(array_length(ids, 1), 0);
    IF n < 2 THEN RETURN 0; END IF;

    SELECT array_agg(d.s               ORDER BY d.s, d.cid),
           array_agg(d.o               ORDER BY d.s, d.cid),
           array_agg(d.g               ORDER BY d.s, d.cid),
           array_agg(d.g * 1000000000  ORDER BY d.s, d.cid)
      INTO subs, objs, games, sums
    FROM (
        SELECT p.s, p.o, count(*)::bigint AS g,
               laplace.consensus_id(p.s, r_prec, p.o) AS cid
        FROM (SELECT ids[i] AS s, ids[i + 1] AS o
              FROM generate_series(1, n - 1) i) p
        GROUP BY p.s, p.o
    ) d;

    PERFORM consensus.upsert(
        subs,
        array_fill(r_prec, ARRAY[cardinality(subs)]),
        objs,
        array_fill(consensus.glicko2_initial_rd(), ARRAY[cardinality(subs)]),
        games,
        sums,
        array_fill(now(), ARRAY[cardinality(subs)]));

    RETURN n - 1;
END;
$$;
-- converse.non_kin_assoc_types(): the relation types that ride the ASSOCIATIVE salience band
-- but do not mean "semantically related to".
--
-- Bands rank IMPORTANCE; families say what a relation MEANS. Conversational
-- rendering needs the second, and reading the band raw conflates them. After the
-- wiktionary seed the associative band carries etymology, usage examples, register
-- labels and lexicographer categories next to genuine kin, which rendered:
--
--   "Hound is related to trace and hound and hounden and *hund and *hundaz
--    and archaic and hund."
--
-- `*hund` / `*hundaz` are reconstructed proto-Germanic forms and `archaic` is a
-- register label. Etymology is DESCENT, an example is USAGE, a register is a
-- USAGE CONDITION, a lexfile is a CATALOGUE BUCKET -- none of them is kinship.
--
-- Whole families are excluded, not individual types: HAS_ETYMOLOGY is a family_root
-- whose children (ETYMOLOGICALLY_DERIVED_FROM, ETYMOLOGICALLY_RELATED_TO) must go
-- with it, and per the decomposer law declaring a family member pulls its ancestors.
-- Naming the roots keeps this correct when a new child is added to the manifest --
-- the exclusion follows automatically instead of silently regressing.
--
-- Resolved through consensus.relation_family_members(), so an unknown or unseeded name
-- contributes nothing rather than raising. Returns ids only: this is consumed inside
-- WHERE clauses in hash space, never rendered.
-- converse.non_kin_assoc_types — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace.non_kin_assoc_types();
CREATE OR REPLACE FUNCTION converse.non_kin_assoc_types()
    RETURNS TABLE(id bytea)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT DISTINCT m.id
    FROM unnest(ARRAY[
             'HAS_ETYMOLOGY',        -- + ETYMOLOGICALLY_DERIVED_FROM / _RELATED_TO
             'HAS_EXAMPLE',          -- usage, surfaced by the examples shape instead
             'HAS_USAGE_REGISTER',   -- "archaic", "colloquial"
             'HAS_LEX_CATEGORY'      -- "noun.object", a catalogue bucket
         ]) AS fam(name)
    CROSS JOIN LATERAL consensus.relation_family_members(fam.name) AS m(id)
$$;
-- converse.facts(syn, lang): the walk-driven fact set behind converse.about() --
-- one row per attested fact family, each carrying its provenance (consensus.eff_mu,
-- witnesses) and, for walk-built rows, the literal path/types so a caller can
-- drill to the exact consensus edges that produced the sentence.
--
-- Fact families, by salience band (the governed language-agnostic ladder):
--   definition  band 1 top edge                      "X is <gloss>."
--   taxonomy    MULTI-HOP native beam walk up the    "X is a kind of A, which is
--               topic's strongest taxonomic relation  a kind of B."
--   parts       band 4 ranked listing                "X has parts such as a, b."
--   kin         band 7 ranked listing                "X is related to a and b."
--   web         strongest unfiltered chain           "X -IS_A-> A -HAS_PART-> b"
--
-- The taxonomy row is the beam engine (walk_branches: Glicko-complete signed
-- weight, partition-pruned by a CONCRETE relation type) -- the topic's own
-- strongest band-2 edge picks that type, so no relation name is hardcoded and
-- the partition-pruning law from recall_walk_response.sql.in holds. The web row
-- uses walk_strongest, the correct engine for the type-unfiltered case. The
-- listing rows are 1-hop by nature (a parts inventory IS its ranked edges).
-- Their capacity is caller-owned; NULL requests the complete ranked family.
-- consensus.eff_mu for a chain = the weakest edge on it (a chain is only as certain as
-- its loosest strand).
DROP FUNCTION IF EXISTS laplace.converse_facts(bytea, bytea);
CREATE OR REPLACE FUNCTION converse.facts(p_syn bytea,
                                          p_lang bytea,
                                          p_part_limit int,
                                          p_kin_limit int)
    RETURNS TABLE(fact_kind text, sentence text, eff_mu numeric, witnesses bigint,
                  path bytea[], types bytea[])
    LANGUAGE plpgsql STABLE AS $$
DECLARE
    b_def  int := 1;   -- definitional band (gloss)
    b_tax  int := 2;   -- taxonomic band (is-a / hypernym)
    b_part int := 4;   -- partitive band (parts)
    b_assoc int := 7;  -- associative band (related)
    -- Band -> relation-type ids, resolved ONCE per call. The predicates below used
    -- `consensus.relation_highway_band(c.type_id) = b_*` directly against consensus, which is
    -- LIST-partitioned by type_id over ~48M rows: a function on the partition key
    -- prunes nothing, indexes nothing, and runs per edge scanned. The band is a
    -- property of ~221 relation types, so it is resolved here and each read becomes
    -- an indexed (subject_id, type_id) probe against a bound array.
    t_def   bytea[];
    t_part  bytea[];
    t_assoc bytea[];
    v_lbl    text;
    tax_type bytea;
BEGIN
    t_def   := laplace.relation_band_types(b_def);
    t_part  := laplace.relation_band_types(b_part);
    t_assoc := laplace.relation_band_types(b_assoc);
    IF p_syn IS NULL THEN
        RETURN;
    END IF;
    IF p_part_limit < 0 OR p_kin_limit < 0 THEN
        RAISE EXCEPTION 'converse.facts: listing limits must be >= 0 or NULL for all rows';
    END IF;

    v_lbl := COALESCE(realize.realize(p_syn, p_lang), realize.label(p_syn));

    -- definition: highest consensus.eff_mu edge in the definitional band.
    -- RANK IN ID SPACE, RENDER THE WINNER. The ordering key is eff_mu, not the
    -- rendered text, so nothing needs a surface to decide -- but realize.render_text sat in
    -- the target list, so it ran for EVERY definitional candidate and one survived
    -- the LIMIT. Each call opens its own SPI connection and walks
    -- realize.constituents_closure. Measured on the glacier synset, this arm was 199 ms of
    -- converse.facts' 868 ms. Same fix as realize._defines (b9cd34df).
    --
    -- object_id closes the ORDER BY: without it a tie is broken by plan order, which
    -- is not reproducible.
    RETURN QUERY
    WITH best AS (
        SELECT c.subject_id, c.object_id, c.type_id, c.rating, c.rd, c.witness_count
        FROM laplace.consensus c
        WHERE c.subject_id = p_syn AND c.type_id = ANY (t_def)
        ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id
        LIMIT 1)
    SELECT 'definition'::text,
           initcap(v_lbl) || ' is ' || realize.render_text(b.object_id) || '.',
           consensus.eff_mu_display(b.rating, b.rd),
           b.witness_count::bigint,
           ARRAY[b.subject_id, b.object_id],
           ARRAY[b.type_id]
    FROM best b;

    -- taxonomy: multi-hop beam walk up the topic's strongest HYPERNYMY relation.
    -- FAMILY, not band. The taxonomic BAND ranks importance and contains more than
    -- hypernymy -- MEMBER_OF_VERBNET_CLASS is its own family_root at taxonomic rank,
    -- so a band-2 pick rendered class membership through the "is a kind of" frame:
    -- "Hound is a kind of Cotheme", "a kind of bully-59.5" (observed after the
    -- wiktionary seed). Bands say how much a relation matters; families say what it
    -- MEANS, and only the IS_A family means hypernymy.
    SELECT c.type_id INTO tax_type
    FROM laplace.consensus c
    WHERE c.subject_id = p_syn
      -- Folded: IMMUTABLE and manifest-generated, so this prunes at plan time.
      AND c.type_id = ANY (consensus.relation_family_ids('IS_A'))
    ORDER BY consensus.eff_mu(c.rating, c.rd) DESC
    LIMIT 1;
    -- NO band fallback. An earlier revision fell back to the taxonomic BAND when the
    -- topic had no IS_A-family edge, "so it still says something rather than going
    -- silent" -- which reintroduced the exact defect: the fallback picked
    -- MEMBER_OF_VERBNET_CLASS and rendered "Bait is a kind of butter-9.9".
    -- Abstention is a real answer here. A concept with no witnessed hypernymy has no
    -- hypernym to report, and emitting a class id inside the "is a kind of" frame is
    -- a false statement, not a graceful degradation. tax_type stays NULL and the
    -- taxonomy row is simply omitted.
    IF tax_type IS NOT NULL THEN
        RETURN QUERY
        WITH branches AS (
            SELECT * FROM consensus.walk_branches(p_syn, tax_type, 4, 3)
        ),
        winner AS (
            -- Deepest chain first: the beam never walks a consensus.refuted or
            -- non-positive edge, so every placed node sits on a confirmed
            -- chain and depth IS ancestry. Average per-hop confidence only
            -- breaks ties between equally deep chains (an avg-first order
            -- degenerates to depth 1 whenever edge strength declines with
            -- distance, which taxonomies always do).
            SELECT * FROM branches w
            ORDER BY w.depth DESC, (w.path_mu / GREATEST(w.depth, 1)::numeric) DESC
            LIMIT 1
        ),
        steps AS (
            -- RENDER THE LADDER, DO NOT RECITE IT. Selecting the deepest chain is
            -- correct for ancestry and wrong for a reply: every hop repeats the
            -- frame, so a depth-4 winner renders "X is a kind of A, which is a kind
            -- of B, which is a kind of C, which is a kind of D." Measured on the
            -- live substrate, 'What is a dog?' rendered four nested frames before
            -- its kin list. Ancestry beyond the first two hops is available through
            -- the returned `path` column, which is the machine-readable answer and
            -- is unbounded; the SENTENCE stops where a person stops reading.
            SELECT i, w.path[i + 1] AS entity_id
            FROM winner w, generate_series(1, LEAST(w.depth, 2)) AS i
        ), ids AS MATERIALIZED (
            SELECT array_agg(entity_id ORDER BY i) AS a FROM steps
        ), labels AS MATERIALIZED (
            SELECT realize.batch(a,p_lang) AS realized,
                   realize.label_batch(a) AS fallback FROM ids
        )
        SELECT 'taxonomy'::text,
               initcap(v_lbl)
                 || string_agg(CASE WHEN s.i = 1 THEN ' is a kind of '
                                    ELSE ', which is a kind of ' END
                               || COALESCE(l.realized[s.i], l.fallback[s.i]),
                               '' ORDER BY s.i)
                 || '.',
               min(b.eff_mu),
               (SELECT w.witnesses FROM winner w),
               (SELECT w.path  FROM winner w),
               (SELECT w.types FROM winner w)
        FROM steps s CROSS JOIN labels l
        JOIN branches b ON b.entity_id = s.entity_id AND b.depth = s.i
        HAVING count(*) > 0;
    END IF;

    -- parts: partitive-band ranked listing (1-hop by nature).
    -- Rank in id space, then ONE realize.batch over survivors — not per-edge
    -- realize.realize() ahead of LIMIT (#903; same pattern chat.sql.in band lens).
    RETURN QUERY
    WITH ranked AS MATERIALIZED (
        SELECT c.object_id AS nid,
               consensus.eff_mu(c.rating, c.rd) AS mu,
               consensus.eff_mu_display(c.rating, c.rd) AS mu_disp,
               c.witness_count AS wc,
               row_number() OVER (
                   ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id) AS ix
        FROM laplace.consensus c
        WHERE c.subject_id = p_syn AND c.type_id = ANY (t_part)
        ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id
        LIMIT p_part_limit
    ),
    lbl AS MATERIALIZED (
        SELECT realize.batch(array_agg(r.nid ORDER BY r.ix), p_lang) AS l
        FROM ranked r
    )
    SELECT 'parts'::text,
           initcap(v_lbl) || ' has parts such as '
             || string_agg(lbl.l[r.ix], ', ' ORDER BY r.mu DESC) || '.',
           min(r.mu_disp),
           sum(r.wc)::bigint,
           NULL::bytea[], NULL::bytea[]
    FROM ranked r CROSS JOIN lbl
    WHERE lbl.l[r.ix] IS NOT NULL
    HAVING count(*) > 0;

    -- kin: associative-band ranked listing, MINUS the associative families that are
    -- not semantic relatedness. The band is a salience rank, and after the wiktionary
    -- seed it carries HAS_ETYMOLOGY (+ its ETYMOLOGICALLY_* children), HAS_EXAMPLE,
    -- HAS_USAGE_REGISTER and HAS_LEX_CATEGORY alongside real kin -- which rendered
    -- "Hound is related to trace and hounden and *hund and *hundaz and archaic":
    -- proto-form reconstructions and register labels presented as things a dog is
    -- related to. Etymology is descent, not relatedness; an example is usage, not kin.
    --
    -- Excluded in ID SPACE, before anything is rendered. The old `label_is_content`
    -- filter ran on the RENDERED string to drop bare ILI ids and lexfile names --
    -- a stoplist in disguise, and a realize.render call in the middle of a hash-space
    -- operation. Selecting families up front removes the reason it existed; it is
    -- retained only as a last-resort guard at the point of rendering.
    -- Rank in id space, exclude non-kin families in id space, then ONE
    -- realize.batch — label_is_content stays a last-resort guard on survivors (#903).
    RETURN QUERY
    WITH ranked AS MATERIALIZED (
        SELECT c.object_id AS nid,
               consensus.eff_mu(c.rating, c.rd) AS mu,
               consensus.eff_mu_display(c.rating, c.rd) AS mu_disp,
               c.witness_count AS wc,
               row_number() OVER (
                   ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id) AS ix
        FROM laplace.consensus c
        WHERE c.subject_id = p_syn
          AND c.type_id = ANY (t_assoc)
          AND c.type_id NOT IN (SELECT id FROM converse.non_kin_assoc_types())
        ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id
        LIMIT p_kin_limit
    ),
    lbl AS MATERIALIZED (
        SELECT realize.batch(array_agg(r.nid ORDER BY r.ix), p_lang) AS l
        FROM ranked r
    )
    SELECT 'kin'::text,
           initcap(v_lbl) || ' is related to '
             || string_agg(lbl.l[r.ix], ' and ' ORDER BY r.mu DESC) || '.',
           min(r.mu_disp),
           sum(r.wc)::bigint,
           NULL::bytea[], NULL::bytea[]
    FROM ranked r CROSS JOIN lbl
    WHERE converse.label_is_content(lbl.l[r.ix])
    HAVING count(*) > 0;

    -- web: the strongest chain across ALL relations -- the explicit
    -- pull-one-strand answer, rendered with its relation arrows.
    RETURN QUERY
    -- Third hand-rolled arrow realize.render, now the installed one (GH #906 item 2).
    -- walk_strongest walks forward, so every direction is 1. This also unifies the
    -- glyphs: this copy drew ASCII ' -type-> ' where realize_path and both walk
    -- responders draw ' —type→ ', so one substrate spoke two arrow dialects
    -- depending on which surface answered.
    SELECT 'web'::text,
           realize.path(
               p_syn || array_agg(g.entity_id ORDER BY g.step),
               array_agg(g.type_id ORDER BY g.step),
               array_fill(1, ARRAY[count(*)::int]),
               p_lang),
           min(g.eff_mu),
           NULL::bigint,
           NULL::bytea[], NULL::bytea[]
    FROM consensus.walk_strongest(p_syn, NULL, 5) g
    HAVING count(*) > 0;
END;
$$;

-- Existing surface: exact adapter to the capacity-aware implementation.
-- CONVERSATIONAL PRESENTATION BOUND (2026-08-23).
--
-- This two-argument form is the CALLER-facing surface: converse.chat and the
-- endpoints reach it, and what it returns is read by a person. It passed NULL for
-- both listing limits, and NULL means "all rows" in the four-argument form -- so a
-- reply carried every associative edge the band holds. Measured on the live
-- substrate: converse.chat('What is a dog?') emitted a single sentence of roughly
-- 1,500 surfaces joined by " and " -- every pronoun in every language the
-- substrate has ever witnessed -- and 'The opposite of hot is' did the same with
-- the letter inventory.
--
-- The bound is PRESENTATION POLICY, not a ranking knob and not an infrastructure
-- cap: the four-argument form still takes NULL for "all rows", which is what the
-- analysis surfaces, receipts and the eval harness use. This mirrors
-- realize.render_text's own rule -- "zero walks the complete cycle-safe DAG; a
-- positive depth is caller-owned preview policy, never an infrastructure cap".
--
-- 8 is the established conversational fan for this schema
-- (converse.session_trajectory(p_session, p_k int DEFAULT 8)); it is reused rather
-- than a second invented number.
--
-- The SIGNATURE IS UNCHANGED on purpose. Adding a defaulted third parameter here
-- made converse.facts(syn) ambiguous against the four-argument form on an UPGRADED
-- database, where the old two-argument function still exists: PostgreSQL reported
-- "function converse.facts(bytea) is not unique" and every caller broke. A fresh
-- install would not have shown it. Callers that want a different bound already
-- have the four-argument form.
CREATE OR REPLACE FUNCTION converse.facts(p_syn bytea, p_lang bytea DEFAULT NULL)
    RETURNS TABLE(fact_kind text, sentence text, eff_mu numeric, witnesses bigint,
                  path bytea[], types bytea[])
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT * FROM converse.facts(p_syn, p_lang, 8, 8);
END;
-- converse.about(syn, lang): the REALIZE half of converse.converse() -- weave prose for an
-- ALREADY-RESOLVED topic synset. Internal seam so callers that have already
-- oriented (converse.chat() resolves its topic once per turn) do not pay converse.converse()'s
-- prompt re-segmentation + band-mass re-orientation just to describe a synset
-- they hold in hand.
--
-- The facts come from converse.facts() -- the walk-driven fact engine (native
-- beam walk for the taxonomy chain, ranked consensus for the listings), each
-- row carrying provenance (consensus.eff_mu, witnesses, path). This wrapper is prose-only:
-- callers that want the provenance columns query converse_facts directly. The
-- 'web' arrow-chain row is a drill-down surface, not prose -- excluded here.
DROP FUNCTION IF EXISTS laplace.converse_about(bytea, bytea);
CREATE OR REPLACE FUNCTION converse.about(p_syn bytea,
                                          p_lang bytea,
                                          p_part_limit int,
                                          p_kin_limit int)
    RETURNS text
    LANGUAGE plpgsql STABLE AS $$
DECLARE
    prose text;
    lbl   text;
BEGIN
    IF p_syn IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT string_agg(f.sentence, ' ' ORDER BY f.ord)
      INTO prose
    FROM converse.facts(p_syn, p_lang, p_part_limit, p_kin_limit)
         WITH ORDINALITY AS f(fact_kind, sentence, eff_mu, witnesses, path, types, ord)
    WHERE f.fact_kind <> 'web';

    IF prose IS NULL THEN
        lbl := realize.realize(p_syn, p_lang);
        IF lbl IS NOT NULL THEN
            prose := 'The concept ' || lbl || ' is one I hold.';
        END IF;
    END IF;

    RETURN btrim(COALESCE(prose, ''));
END;
$$;

-- Existing prose surface preserves dependency identity while delegating to
-- the one capacity-aware implementation. Omitted listing capacities are exact.
CREATE OR REPLACE FUNCTION converse.about(p_syn bytea, p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT converse.about(p_syn, p_lang, NULL, NULL);
END;
-- converse.converse(prompt [, lang]): the fused OODA walk as a deterministic narrative.
--
-- Relation selection is gated by SALIENCE BAND (the governed highway structure),
-- not hardcoded English relation names: band 1 = definitional (the gloss),
-- 2 = taxonomic (is-a), 4 = partitive (parts), 7 = associative (kin). A band is
-- the language-agnostic family -- taxonomic catches every subsumption relation, not
-- just IS_A -- and it is the same 13-band ladder the manifest governs and the highway
-- perfcache bit-packs. (Native per-entity highway_mask AND is the intended fast path
-- once the highway perfcache + laplace.entities.highway_mask are built; here we gate by
-- consensus.relation_highway_band on the read side, which is band-correct and works today.)
--
-- ORIENT here, REALIZE in converse.about(): callers that already resolved a topic
-- (converse.chat() orients once per turn) call converse_about directly and skip the
-- re-segmentation.
--
-- ONE ELECTION, and it is converse.chat()'s. This function used to carry a private copy of
-- the pre-specificity ranking -- copy-pasted verbatim into converse.walk() as well
-- -- long after converse.chat() replaced it. Since converse.chat() falls back to converse.converse() on three
-- paths, the ranking converse.chat() abandoned was still reachable from converse.chat(). It carried
-- five separate defects in one expression:
--
--   1. lower(realize.realize(x.syn, p_lang)) = x.surface -- CASE-FOLDING AS A HACK.
--      "King" and "king" are DIFFERENT CONTENT, so different ids, and the substrate
--      already attests the link both ways: K --HAS_LOWERCASE_MAPPING--> k and
--      k --HAS_UPPERCASE_MAPPING--> K, governed in relation_types.toml, resolved
--      natively and batched by lexical.word_case_variants(src/lexical_case.c). Calling
--      lower() throws those attested edges away and re-derives a worse answer in
--      string space -- the identity law inverted, at a per-row cost.
--   2. TWO renders per candidate (realize of the synset, realize.render_text of the token)
--      inside the ranking, i.e. rendering before the operation is finished.
--   3. A string EQUALITY as the primary sort key, in a substrate whose identity law
--      is language-agnostic: a synset whose label differs from the surface
--      (car -> "auto") scores false and loses to an incidental token.
--   4. char_length(surface) as the final tiebreak -- ranking concepts by how long
--      their spelling is.
--   5. A correlated count(*) over consensus per candidate for band_mass: 29.6s for
--      ONE candidate on the seeded corpus, and taxonomy.top_synset() per token on top of it
--      (73s -- it is bubble_up per constituent).
--
-- All five are gone. converse.prompt_coherence() is native, id-space end to end, and elects
-- on SPECIFICITY (coherence / the candidate's own total rated mass) exactly as
-- converse.chat() does -- same function, same key order, so the two can no longer disagree
-- about what a prompt is about.
DROP FUNCTION IF EXISTS laplace.converse(text, bytea);
CREATE OR REPLACE FUNCTION converse.converse(p_prompt text, p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE plpgsql STABLE AS $$
DECLARE
    syn bytea;
BEGIN
    -- ORIENT: the same native election converse.chat() runs. Key order is converse.chat()'s,
    -- verbatim. Each signal is an explicit ordered dimension; unlike the retired
    -- specificity*denote_mu product, no unit conversion or weighting constant can
    -- silently change the election as the seed grows.
    -- Delegates to converse.elect_sense -- the ONE election body (spec 37: "one
    -- canonical implementation per operation fact"). The key order used to be
    -- inlined here and in four other files; identical copies are still copies.
    syn := converse.elect_sense(p_prompt);

    IF syn IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN converse.about(syn, p_lang);
END;
$$;
-- The converse_walk WALK phase: steered trigram->bigram backoff over a
-- weighted token stream, natively (steered_walk.c). Pure computation over the
-- arguments — deterministic per rng seed, no catalog access.
DROP FUNCTION IF EXISTS laplace.steered_walk_raw(bytea[], int8[], bytea[], bytea[], int, int, int8);
CREATE OR REPLACE FUNCTION converse.steered_walk_raw(
    p_stream   bytea[],
    p_weights  int8[],
    p_core_seq bytea[],
    p_starts   bytea[],
    p_steps    int,
    p_minlen   int,
    p_rng      int8)
    RETURNS bytea[]
    AS 'laplace_substrate', 'pg_laplace_steered_walk'
    LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
-- converse.walk(prompt, steps, seed): the FUSED free-form walk.
--
-- Sequence PROPOSES, meaning STEERS -- now with real semantic steering:
--   ORIENT  -> the prompt's richest concept synset (as converse.converse()).
--   GATHER  -> ordered token trajectories of the concept's own attested sentence
--              (weight 50, the seed) plus the tier-3 sentences that contain the
--              topic word (weight 40). Drawn from physicality trajectories =
--              precedes/follows/co-occurrence. Each token carries its source's
--              topic weight, so the corpus knows what is central vs peripheral.
--              Set-based: realize.render_text runs once per DISTINCT token id to drop
--              whitespace realize.constituents(the old loop rendered every occurrence
--              of every token of every sentence).
--   WALK    -> converse.steered_walk_raw(steered_walk.c): trigram->bigram backoff over
--              the restricted stream, SEEDED from the core concept's own
--              sentence and STEERED by topic weight (RNG breaks ties), with the
--              anti-repeat guard forcing novel recombination at shared n-gram
--              pivots. Ends at a sentence boundary once it has said enough.
--              Grounded only in attested token order; deterministic per seed.
--   REALIZE -> realize.render_text of the emitted token ids.
CREATE OR REPLACE FUNCTION generation.walk_batch(p_prompt text,
                                                  p_steps int,
                                                  p_seeds bigint[],
                                                  p_corpus_limit int)
    RETURNS TABLE(seed bigint, reply text)
    LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    -- Only the definitional band survives here: it selects the concept's own gloss
    -- as the GATHER seed below. The taxonomic/partitive/associative constants went
    -- with the orientation block that used them for band-mass. They were magic
    -- integers duplicated across this file, converse.converse() and converse.facts() anyway
    -- -- converse.relation_band_catalog() is the published surface for band identity.
    b_def  int := 1;   -- definitional band (gloss)
    -- Resolved once (see converse_facts): a function on consensus.type_id is a
    -- function on the partition key, so it prunes nothing and runs per edge.
    t_def  bytea[];
    SENT   bytea := '\x00';
    MINLEN int := 5;
    syn    bytea;
    topic_word bytea;   -- the tier-2 word whose usage lives in the tier above
    stream bytea[];
    w      bigint[];    -- per-token topic weight, aligned to stream
    starts bytea[];     -- starts of CORE sentences (on-topic seed)
    core_seq bytea[];   -- longest CORE gloss (deterministic seed)
    n      int;
BEGIN
    t_def := laplace.relation_band_types(b_def);
    -- ORIENT: the same native election converse.chat() and converse.converse() run — one election,
    -- one key order, so the three cannot disagree about what a prompt is about.
    -- prompt_coherence returns the elected TOKEN alongside its synset, which is
    -- what this lane needs for the tier fan-out below, so both come off one call.
    --
    -- This replaces a verbatim copy of converse.converse()'s pre-specificity ranking. Its
    -- primary sort key was lower(realize.realize(x.syn)) = x.surface -- case-folding used
    -- as an identity test. "King" and "king" are different content and therefore
    -- different ids, and the substrate already attests the link both ways
    -- (K --HAS_LOWERCASE_MAPPING--> k, k --HAS_UPPERCASE_MAPPING--> K, resolved
    -- natively by word_case_variants); lower() discards those edges to re-derive a
    -- worse answer in string space, per row. The rest of that block was two renders
    -- per candidate, a char_length tiebreak, a 29.6s correlated band-mass count and
    -- a 73s top_synset per token. See converse.sql.in for the full ledger.
    -- Delegates to converse.elect -- the ONE election body (spec 37).
    SELECT e.tok, e.synset_id INTO topic_word, syn FROM converse.elect(p_prompt) e;
    IF syn IS NULL THEN
        RETURN QUERY
        SELECT s.seed, NULL::text
        FROM unnest(p_seeds) WITH ORDINALITY AS s(seed, ord)
        ORDER BY s.ord;
        RETURN;
    END IF;

    -- GATHER: the concept's own gloss (tier-1 definition, the seed) PLUS the
    -- TIER FAN-OUT -- a word's usage lives in the tier above it, so pull the
    -- tier-3 sentences that contain the topic word as a constituent (dense real
    -- usage) via the realize.constituents index. This is the corpus, not just the gloss.
    -- Word-level tokens only: the inter-word whitespace realize.constituents are
    -- dropped, else (word,space) bigrams match every boundary and the walk
    -- jumps (e.g. "a"+space -> "creek" from "...than a creek").
    -- The corpus is ranked by the WEB, not by storage order. containers_of walks
    -- the trajectory constituent index, which is GEOMETRY -- identity and
    -- retrieval, never semantics. What a candidate sentence is WORTH is the
    -- Glicko fold's answer, and it is already on the edge that attests it.
    --
    -- The old ORDER BY was `is_core DESC, gid`: content-hash order. MEASURED on
    -- 'water', of the 400 tier-3 containers returned, 398 are the object of a
    -- HAS_DEFINITION consensus edge whose consensus.eff_mu spans 1.17e12 to 1.46e12 -- a
    -- 25% spread, witness_count up to 4. The signal was sitting on 99.5% of the
    -- candidates and the corpus that decides what this engine SAYS was picked by
    -- hash instead.
    --
    -- Rank on the INBOUND edge (c.object_id = the sentence). A usage sentence is
    -- rated by what attests it -- HAS_DEFINITION, HAS_EXAMPLE -- not by anything
    -- it asserts itself; probing c.subject_id finds almost nothing (4 of 400) and
    -- is the wrong direction. LEFT JOIN so an unrated candidate still competes at
    -- the neutral prior rather than being silently dropped: absence of evidence is
    -- not evidence of worthlessness, and dropping it would be an
    -- operator-invented floor.
    --
    -- Corpus capacity is caller-owned. NULL means the complete indexed
    -- container population; zero means no usage containers. There is no
    -- hidden upstream 400-row subset followed by a second 160-row cut.
    WITH gids AS (
        -- DISTINCT: a gloss reachable through two def-band relation types
        -- contributes its token stream once, not twice.
        -- THE STEER IS THE VERDICT. wt was 50 for the core gloss and 40 for a
        -- containing sentence -- two hand-set numbers whose 1.25 ratio disappears
        -- inside sw_score's `weight * (rng % 100000)`, so the stream was effectively
        -- unsteered while the adjudicated belief sat one column over, computed for
        -- the ORDER BY and then discarded. wt is that belief now; eff_mu and the
        -- weight array are both bigint at the same fp scale, so nothing is rescaled.
        -- GREATEST(.,0) keeps a refuted source from flipping sw_score's sign instead
        -- of merely ranking last. The SENT boundary's weight 0 is set in `seq`.
        --
        -- GROUP BY gid, not DISTINCT (gid, wt, is_core): a gloss reachable through
        -- two def-band relation types, or present in both arms, produced two rows
        -- under DISTINCT and contributed its token stream twice -- the exact thing
        -- the comment above forbids.
        SELECT g.gid, MAX(g.wt) AS wt, bool_or(g.is_core) AS is_core FROM (
            SELECT c.object_id AS gid,
                   GREATEST(consensus.eff_mu(c.rating, c.rd), 0) AS wt, true AS is_core,
                   consensus.eff_mu(c.rating, c.rd) AS mu
            FROM laplace.consensus c
            WHERE c.subject_id = syn AND c.type_id = ANY (t_def)
            UNION ALL
            SELECT co.entity_id,
                   GREATEST(COALESCE(MAX(consensus.eff_mu(k.rating, k.rd)),
                                     consensus.glicko2_neutral_mu()), 0),
                   false,
                   COALESCE(MAX(consensus.eff_mu(k.rating, k.rd)), consensus.glicko2_neutral_mu())
            FROM structural.containers_of(topic_word, 1, p_corpus_limit) co
            LEFT JOIN laplace.consensus k ON k.object_id = co.entity_id
            WHERE co.tier = 3
            GROUP BY co.entity_id
        ) g
        GROUP BY g.gid
    ),
    toks AS (
        -- The WHOLE attested constituent sequence, at whatever tier the content
        -- decomposed into. NO ctier filter: tier is a FLOOR, never an identity,
        -- so selecting the walk's alphabet by tier is a tokenizer -- the fixed
        -- vocabulary assumption this engine exists to replace.
        --
        -- What the filter discarded, MEASURED over 12 containers of 'water':
        --   ctier 0 : 164 realize.constituents,  12 distinct  <- the separators
        --   ctier 2 : 144 realize.constituents,  94 distinct  <- the words
        -- The separators were in the trajectory all along, in attested order.
        -- Dropping them is why REALIZE had to invent a ' ', false for every script
        -- that does not space its words.
        --
        -- The letter-by-letter worry the old comment recorded is real but narrow:
        -- a ONE-WORD gloss, where the tier-is-a-floor collapse makes the gloss root
        -- its own word, so unpacking reaches that word's codepoints. 12 distinct
        -- tier-0 ids across 12 sentences is punctuation, not spelling -- a word is
        -- a single tier-2 id. The cnt >= 2 guard below already drops the degenerate
        -- one-word case, and that is what actually handled it.
        SELECT g.gid, g.wt, g.is_core, u.entity_id, u.ord
        FROM gids g
        CROSS JOIN LATERAL generation.trajectory_unpacked_points(g.gid)
             WITH ORDINALITY AS u(entity_id, run_length, ctier, ord)
    ),
    -- The whitespace classification that sat here is GONE. It rendered every
    -- DISTINCT token to text to ask "is this blank" -- MEASURED on 'water' (1,645
    -- distinct tokens over 400 containers) at 29,899ms of a 48,435ms
    -- converse_walk, 18ms per token, purely to answer a predicate.
    --
    -- Against this stream it was a NO-OP as well as a cost: `toks` restricts to
    -- u.ctier = 2, and separator tokens live below tier 2, so the set it filtered
    -- could not contain one. Removing it left the emitted token sequence
    -- byte-identical and cut converse_walk 39,588ms -> 27,760ms.
    --
    -- The general form of the mistake is rendering an entity to text in order to
    -- classify it. corpus_whitespace_vocab_indices had the same shape and reading
    -- the attested HAS_GENERAL_CATEGORY instead measured 22.6ms against 29,899ms
    -- with zero disagreement (#688/#689). Nothing here needs to classify at all,
    -- so this just goes.
    kept AS MATERIALIZED (
        SELECT q.* FROM (
            SELECT t.gid, t.wt, t.is_core, t.entity_id,
                   row_number() OVER (PARTITION BY t.gid ORDER BY t.ord) AS rn,
                   count(*)    OVER (PARTITION BY t.gid) AS cnt
            FROM toks t
        ) q
        WHERE q.cnt >= 2
    ),
    -- QUERY x KEY. The query is the oriented topic `syn`; the key is a stream token;
    -- the score is the adjudicated belief on the edge BETWEEN them, either direction.
    -- A per-source prior cannot express this: it gives every token of a sentence the
    -- same weight regardless of the prompt, so it is a single-token scalar, which
    -- INVENTION §7 forbids as a ranking key. Edge-conditioned, the same token scores
    -- differently under a different topic -- which is what makes it attention rather
    -- than a frequency prior.
    --
    -- = ANY(array), never a join: laplace.consensus is LIST(type_id) with hash
    -- sub-partitions and this constrains neither side's partition key, so a join
    -- plans as a full index-only scan of every partition.
    tokset AS MATERIALIZED (
        SELECT DISTINCT k.entity_id AS id FROM kept k
    ),
    qk AS MATERIALIZED (
        SELECT e.id, MAX(e.mu) AS mu FROM (
            SELECT c.object_id AS id, consensus.eff_mu(c.rating, c.rd) AS mu
            FROM laplace.consensus c
            WHERE c.subject_id = syn
              AND c.object_id = ANY (ARRAY(SELECT t.id FROM tokset t))
            UNION ALL
            SELECT c.subject_id, consensus.eff_mu(c.rating, c.rd)
            FROM laplace.consensus c
            WHERE c.object_id = syn
              AND c.subject_id = ANY (ARRAY(SELECT t.id FROM tokset t))
        ) e
        GROUP BY e.id
    ),
    seq AS MATERIALIZED (
        -- Each sentence's tokens in order, then one SENT boundary (weight 0)
        -- ordered past every real token of its sentence. Weight is the query-key
        -- belief where the topic and the token are bound by testimony, and falls back
        -- to the source's own belief where they are not -- absence of a direct edge is
        -- not evidence of worthlessness, and dropping to zero there would be an
        -- operator-invented floor.
        -- NO FALLBACK. A token the topic has no attested relation to weighs zero,
        -- because that is what the substrate says about it: absence is provable and
        -- first-class (§8), not a gap to be filled with the source's prior. Filling it
        -- was manufacturing a score no witness deposited, and it is also what made the
        -- steer unable to matter -- every token arrived pre-scored whether or not any
        -- testimony bound it to this prompt.
        --
        -- A stream that goes quiet under this is ABSTAINING, which is the lawful
        -- answer here ("Abstain = zero rows, never fabricate"), not a failure to be
        -- engineered around by widening the neighbourhood until something scores.
        SELECT k.gid, k.is_core, GREATEST(COALESCE(q.mu, 0), 0) AS wt, k.entity_id AS id, k.rn
        FROM kept k LEFT JOIN qk q ON q.id = k.entity_id
        UNION ALL
        SELECT DISTINCT k.gid, k.is_core, 0::bigint, SENT, 2147483647::bigint
        FROM kept k
    )
    SELECT (SELECT array_agg(s.id ORDER BY s.is_core DESC, s.gid, s.rn) FROM seq s),
           (SELECT array_agg(s.wt ORDER BY s.is_core DESC, s.gid, s.rn) FROM seq s),
           -- Core starts when the gloss survives; otherwise the fall-through
           -- the toks comment promises: a one-word gloss (an OMW/Wiktionary
           -- translation like "roi") leaves no core rows, and the walk seeds
           -- from the on-topic tier-3 usage sentences instead of going dark.
           COALESCE(
               (SELECT array_agg(k.entity_id ORDER BY k.gid) FROM kept k
                 WHERE k.is_core AND k.rn = 1),
               (SELECT array_agg(k.entity_id ORDER BY k.gid) FROM kept k
                 WHERE k.rn = 1)),
           (SELECT array_agg(k.entity_id ORDER BY k.rn) FROM kept k
             WHERE k.is_core AND k.gid = (
                 SELECT k2.gid FROM kept k2 WHERE k2.is_core
                 GROUP BY k2.gid ORDER BY max(k2.cnt) DESC, k2.gid LIMIT 1))
    INTO stream, w, starts, core_seq;

    n := COALESCE(array_length(stream,1), 0);
    IF n < 3 OR starts IS NULL THEN
        RETURN QUERY
        SELECT s.seed, NULL::text
        FROM unnest(p_seeds) WITH ORDINALITY AS s(seed, ord)
        ORDER BY s.ord;
        RETURN;
    END IF;

    -- SEED + WALK runs natively over every requested seed after the prompt's
    -- orientation and corpus plan have been built ONCE. generation.probe used
    -- to call converse.walk once per seed, rebuilding everything above for an
    -- input that only changes the final RNG. This batch is the one implementation;
    -- converse.walk below is its scalar compatibility wrapper.
    --
    -- REALIZE is also one batch over the union of emitted ids. No punctuation
    -- scrub and no whitespace normalization. The old tail ran
    -- regexp_replace('\s*[();:]\s*') then regexp_replace('\s+') because REALIZE
    -- had just wedged a ' ' between every token, orphaning the brackets the gloss
    -- actually attested. With separators carried through, the spacing IS the
    -- corpus's -- scrubbing it overwrites testimony with a rule, and a
    -- hardcoded-ASCII one ([();:] says nothing about U+3001, U+060C or U+0E5A).
    RETURN QUERY
    WITH emitted AS MATERIALIZED (
        SELECT s.ord, s.seed,
               converse.steered_walk_raw(
                   stream, w, COALESCE(core_seq, ARRAY[]::bytea[]), starts,
                   p_steps, MINLEN,
                   abs(COALESCE(s.seed,
                       ('x'||substr(md5(p_prompt),1,8))::bit(32)::bigint)) % 2147483647
               ) AS ids
        FROM unnest(p_seeds) WITH ORDINALITY AS s(seed, ord)
    ),
    ids AS MATERIALIZED (
        SELECT array_agg(DISTINCT u.id) AS a
        FROM emitted e
        CROSS JOIN LATERAL unnest(e.ids) AS u(id)
    ),
    realized AS MATERIALIZED (
        SELECT i.a, realize.render_text_batch(i.a) AS txt
        FROM ids i
    ),
    labels AS MATERIALIZED (
        SELECT (r.a)[k] AS id, (r.txt)[k] AS txt
        FROM realized r
        CROSS JOIN LATERAL generate_subscripts(r.a, 1) AS k
    )
    SELECT e.seed,
           CASE WHEN count(u.id) = 0 THEN NULL::text
                ELSE btrim(string_agg(COALESCE(l.txt, ''), '' ORDER BY u.ord))
           END AS reply
    FROM emitted e
    LEFT JOIN LATERAL unnest(e.ids) WITH ORDINALITY AS u(id, ord) ON true
    LEFT JOIN labels l ON l.id = u.id
    GROUP BY e.ord, e.seed
    ORDER BY e.ord;
END;
$$;

-- Existing three-argument surface: an ordinal-preserving adapter to the one
-- implementation. Omission requests the complete corpus rather than choosing
-- a hidden server-side subset.
CREATE OR REPLACE FUNCTION generation.walk_batch(p_prompt text,
                                                  p_steps int,
                                                  p_seeds bigint[])
    RETURNS TABLE(seed bigint, reply text)
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT b.seed, b.reply
    FROM generation.walk_batch(p_prompt, p_steps, p_seeds, NULL) b;
END;

DROP FUNCTION IF EXISTS laplace.converse_walk(text, int, bigint);
CREATE OR REPLACE FUNCTION converse.walk(p_prompt text,
                                         p_steps int,
                                         p_seed bigint,
                                         p_corpus_limit int)
    RETURNS text
    LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    out_text text;
BEGIN
    SELECT b.reply INTO out_text
    FROM generation.walk_batch(
        p_prompt, p_steps, ARRAY[p_seed]::bigint[], p_corpus_limit) b
    LIMIT 1;
    RETURN out_text;
END;
$$;

-- Scalar compatibility surface. All semantics live in the capacity-aware
-- overload; omitted capacity means exact/unbounded.
CREATE OR REPLACE FUNCTION converse.walk(p_prompt text, p_steps int DEFAULT 40,
                                         p_seed bigint DEFAULT NULL)
    RETURNS text
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT converse.walk(p_prompt, p_steps, p_seed, NULL);
END;
-- converse.compose(prompt, steps, lang, seed): S7 -- the walk frontier steers emission.
--
-- THE STAGE THIS ADDS. converse_walk already does "sequence proposes, meaning
-- steers", but its steer is a CONSTANT: every token of the topic's own gloss gets
-- weight 50, every token of a containing sentence gets 40, forever. That is a
-- provenance weight (which source did this token come from), not a semantic one --
-- it says nothing about whether a token is on-topic for THIS turn. The walker is
-- therefore unsteered in the only sense that matters, and the result is retrieval:
-- measured 2026-07-25, converse.walk('dog') returned the same byte-identical
-- sequence for seeds 7 and 991, i.e. it replays one attested sentence rather than
-- recombining. That constant IS the missing forward pass, and it is one array.
--
-- Here the weight vector is derived from the SEMANTIC FRONTIER instead: walk the
-- topic's consensus neighbourhood, and weight each stream token by how strongly the
-- concept it belongs to sits in that frontier. Sequence still proposes (the native
-- trigram->bigram backoff is untouched); meaning now actually steers, per emitted
-- step, against evidence computed for this turn.
--
-- WHY A SEPARATE FUNCTION. converse_walk stays exactly as it is. This is additive so
-- it can be measured against the incumbent on the same prompts and seeds before
-- anything is rewired. Editing the live path first is what shipped a regression
-- earlier in this session; the lesson is cheap to apply.
--
-- CONCEPT vs SURFACE (spec 36 §3.1). The frontier is concept-level and language-free.
-- Realization picks surfaces at the very end, honouring p_lang -- an ILI is an
-- equivalence class spanning every language that witnesses it, so nothing but the
-- final realize.render decides which member is emitted.
--
-- SCALING. consensus.eff_mu arrives in the fold's internal units (~1e12) and steered_walk_raw
-- wants an int8 weight multiplied by a 0..100000 hash. The /1e10 below is a UNITS
-- CONVERSION chosen so frontier salience lands in the same order of magnitude as the
-- existing provenance weights (40-50), not a tuning knob and not a floor -- it
-- rescales every candidate identically and changes no ordering. Non-frontier tokens
-- keep their provenance weight and stay eligible: weight 0 would exclude them
-- outright, since the native score is multiplicative.
--
-- NOT YET MEASURED. Written against the same stream/weights contract converse_walk
-- uses, but its output has NOT been compared to the incumbent. The gate is: does it
-- produce DIFFERENT text for different seeds (recombination rather than replay), and
-- does that text stay on topic. Do not wire this into converse.chat() until that run exists.
-- Signature change (p_ctx added): the 4-arg form must not survive as a second
-- overload or every 4-arg call site becomes "function is not unique".
CREATE OR REPLACE FUNCTION generation.compose_batch(p_prompt text,
                                                     p_steps int,
                                                     p_lang bytea,
                                                     p_seeds bigint[],
                                                     p_ctx bytea[] DEFAULT NULL)
    RETURNS TABLE(seed bigint, reply text)
    LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    b_def  int := 1;
    -- Resolved once (see converse_facts): a function on consensus.type_id is a
    -- function on the partition key, so it prunes nothing and runs per edge.
    t_def  bytea[];
    -- Content bands 1,2,4,7. A local, not a CTE column: relation_band_types is
    -- STABLE so it cannot fold at plan time, but a plpgsql local binds as a
    -- parameter and `type_id = ANY($n)` prunes the LIST partitions at execution.
    -- Read back from a CTE column it is a per-row variable and prunes nothing.
    t_band bytea[];
    -- Separator set as a LOCAL, for the same reason as t_band. generation.separator_ids()
    -- is STABLE, and measured with EXPLAIN it is NOT hoisted to an InitPlan: it lands
    -- in the Filter expression and is evaluated PER ROW. At 10.3 ms a call that is
    -- catastrophic over a token stream. A plpgsql local binds once as a parameter.
    t_sep  bytea[];
    SENT   bytea := '\x00';
    MINLEN int := 5;
    syn    bytea;
    topic_word bytea;
    prompt_ids bytea[];
    stream bytea[];
    w      bigint[];
    starts bytea[];
    core_seq bytea[];
    n      int;
BEGIN
    t_def  := laplace.relation_band_types(b_def);
    t_band := laplace.relation_band_types(ARRAY[1,2,4,7]);
    t_sep  := generation.separator_ids();
    -- Carry the prompt's witnessed identities into the source scan.  Array
    -- containment is set membership only; the returned physicality retains the
    -- ordered trajectory used below.  No separator/whitespace assumption is
    -- made here, and no direct edge is invented between co-constituents.
    SELECT array_agg(DISTINCT p.id ORDER BY p.id) INTO prompt_ids
    FROM converse.prompt_words(p_prompt) p
    WHERE p.id IS NOT NULL;
    -- ORIENT. Same hash-space signal converse.chat() uses: how strongly the token denotes the
    -- sense, then highway-mask breadth. No realize.realize(), no surface comparison.
    -- Two levels: breadth picks WHICH TOKEN, denote_mu picks WHICH SENSE of it.
    -- Ranking every (token, sense) pair by breadth selects obscure/slang senses that
    -- happen to be wired into more relation types -- it resolved `dog` to SIRE, which
    -- made this function seed from the wrong gloss entirely and rendered the whole
    -- steer comparison meaningless. Mirrors converse.chat()'s orientation exactly.
    SELECT y.tok, y.syn INTO topic_word, syn
    FROM (
        SELECT DISTINCT ON (x.tok)
               x.tok, x.syn, x.denote_mu, x.tok_breadth
        FROM (
            SELECT p.id AS tok, s.synset_id AS syn, s.eff_mu AS denote_mu,
                   max(consensus.highway_popcount(e.highway_mask))
                       OVER (PARTITION BY p.id) AS tok_breadth
            FROM converse.prompt_state(p_prompt) p
            CROSS JOIN LATERAL lexical.senses(p.id) s
            LEFT JOIN laplace.entities e ON e.id = s.synset_id
            WHERE p.id IS NOT NULL AND s.synset_id IS NOT NULL
        ) x
        ORDER BY x.tok, x.denote_mu DESC NULLS LAST, x.syn
    ) y
    ORDER BY y.tok_breadth DESC NULLS LAST, y.denote_mu DESC NULLS LAST, y.syn
    LIMIT 1;
    IF syn IS NULL THEN
        RETURN QUERY
        SELECT s.seed, NULL::text
        FROM unnest(p_seeds) WITH ORDINALITY AS s(seed, ord)
        ORDER BY s.ord;
        RETURN;
    END IF;

    WITH
    -- FRONTIER: the topic's consensus neighbourhood, both directions, over the
    -- content bands. This is the turn's semantic plan -- concept-level, language-free.
    frontier AS MATERIALIZED (
        SELECT c.object_id AS cid, consensus.eff_mu(c.rating, c.rd) AS mu
        FROM laplace.consensus c
        WHERE c.subject_id = syn AND c.type_id = ANY (t_band)
        UNION ALL
        SELECT c.subject_id, consensus.eff_mu(c.rating, c.rd)
        FROM laplace.consensus c
        WHERE c.object_id = syn AND c.type_id = ANY (t_band)
        UNION ALL
        SELECT syn, (SELECT max(consensus.eff_mu(c2.rating, c2.rd)) FROM laplace.consensus c2
                     WHERE c2.subject_id = syn)
        -- BIOGRAPHY ARMS (R7 slice 2, GH #759): the session's recent topics
        -- join the turn's frontier with RECENCY-DECAYED weight — attention
        -- over context in the Q slot, not just in orientation. p_ctx arrives
        -- most-recent-first (converse.chat() passes session_trajectory order), and
        -- ordinality IS the recency distance: /2 per step back, so the last
        -- turn's topic steers at half the live topic's scale and a topic
        -- four turns back is a whisper. Same bands, same fold-produced mu,
        -- same frontier_agg merge (max keeps the strongest claim on a
        -- concept two topics share). NULL/empty ctx contributes zero rows —
        -- a fresh session composes exactly as before this change. The live
        -- topic is excluded HERE, where syn is known — converse.chat() filters its
        -- own carried topic, but this function re-elects syn independently,
        -- and a caller whose ctx happens to contain the elected topic would
        -- double-count it at full-plus-decayed weight (Copilot, PR #896).
        UNION ALL
        SELECT c.object_id, consensus.eff_mu(c.rating, c.rd) / (2 ^ x.dist)
        FROM unnest(COALESCE(p_ctx, ARRAY[]::bytea[])) WITH ORDINALITY x(cid, dist)
        JOIN laplace.consensus c ON c.subject_id = x.cid
                        AND c.type_id = ANY (t_band)
        WHERE x.cid <> syn
        UNION ALL
        SELECT c.subject_id, consensus.eff_mu(c.rating, c.rd) / (2 ^ x.dist)
        FROM unnest(COALESCE(p_ctx, ARRAY[]::bytea[])) WITH ORDINALITY x(cid, dist)
        JOIN laplace.consensus c ON c.object_id = x.cid
                        AND c.type_id = ANY (t_band)
        WHERE x.cid <> syn
        UNION ALL
        SELECT x.cid, (SELECT max(consensus.eff_mu(c2.rating, c2.rd)) FROM laplace.consensus c2
                       WHERE c2.subject_id = x.cid) / (2 ^ x.dist)
        FROM unnest(COALESCE(p_ctx, ARRAY[]::bytea[])) WITH ORDINALITY x(cid, dist)
        WHERE x.cid <> syn
    ),
    -- The frontier is concepts and — since the concept-stream change — so is
    -- the stream: steering matches DIRECTLY in concept space (GH #751, slot
    -- map: the stream is language-free). The old frontier_words projection
    -- down to surface members is gone with the word-level stream it served.
    frontier_agg AS MATERIALIZED (
        SELECT f.cid, max(f.mu) AS mu FROM frontier f GROUP BY f.cid
    ),
    context_gids AS MATERIALIZED (
        SELECT co.entity_id AS gid
        FROM structural.containers_containing_all(prompt_ids) co
    ),
    gids AS (
        SELECT DISTINCT g.gid, g.wt, g.is_core FROM (
            -- A witnessed composition of multiple prompt identities is the
            -- backbone.  Definitions remain in the stream as supporting
            -- evidence.  When no shared composition exists, the definition is
            -- the backbone exactly as before.  The native walker otherwise
            -- always seeds from core_seq and merely having a definition makes
            -- every contextual start unreachable.
            SELECT c.object_id AS gid,
                   CASE WHEN EXISTS (SELECT 1 FROM context_gids)
                        THEN 40 ELSE 50 END::bigint AS wt,
                   NOT EXISTS (SELECT 1 FROM context_gids) AS is_core
            FROM laplace.consensus c
            WHERE c.subject_id = syn AND c.type_id = ANY (t_def)
            UNION ALL
            SELECT cg.gid, 50, true
            FROM context_gids cg
        ) g
    ),
    toks AS (
        SELECT g.gid, g.wt, g.is_core, u.entity_id, u.ord
        FROM gids g
        CROSS JOIN LATERAL generation.trajectory_unpacked_points(g.gid)
             WITH ORDINALITY AS u(entity_id, run_length, ctier, ord)
        -- ctier = 2 IS A KNOWN-LOSSY FILTER THAT STILL HAS NO REPLACEMENT. Do not
        -- remove it without reading this.
        --
        -- It is lossy because tier is a floor: laplace.word_id('a'),
        -- word_id('I') and word_id('狼') are all tier 0 and typed Codepoint, so this
        -- drops single-character words. Measured: 'a' occurs 152 times inside
        -- sentence trajectories and every occurrence is discarded here.
        --
        -- It cannot simply be deleted. A tier-3 container's constituents are NOT all
        -- words: measured on the containers of 'dog', Word x255, Codepoint x15,
        -- POS x6. generation.separator_ids() removes only Zs/Zl/Zp/Cc, not punctuation
        -- (Po) or digits (Nd). Removing the filter and relying on the separator set
        -- was tried and measured: generation.compose_batch went 81,701 ms -> 316,998 ms and
        -- emitted "year action MIDDLE DOT year active verb counterfactual in COLON"
        -- -- raw codepoint names in the stream.
        --
        -- And no read-side test can fix it, because laplace.word_id('a') IS the codepoint
        -- entity: same content, same hash, one entity, one type. The packed vertex
        -- tier does not disambiguate either -- measured, it equals the entities floor
        -- on all 3,642 points sampled. The fix belongs at INGEST: the trajectory
        -- vertex would have to record the constituent's segmentation ROLE at that
        -- position, which it currently does not.
        WHERE u.ctier = 2
    ),
    -- Whitespace-ness through the ONE installed definition, on the fast renderer.
    -- The inline `~ '^\s*$'` was a second definition of "is whitespace" living in
    -- a read path, and it rendered to depth 64 to answer a question about the
    -- first character.
    --
    -- CLASSIFIED BY ID. Rendering every distinct token to text to ask one boolean,
    -- then discarding the text, is the read-side law inverted -- generation.separator_ids()'s
    -- own comment states it: "classification is an indexed read on the id; the
    -- realize.render is the cost. NO RENDER FALLBACK."
    --
    -- The previous comment here rejected the id form on the grounds that Unicode
    -- general category is attested on CODEPOINTS while toks holds words, so every
    -- probe would miss. That is true of a per-token HAS_GENERAL_CATEGORY probe and
    -- NOT true of generation.separator_ids(), which is the closed separator set including
    -- compositions (composition lifts the property, §3 Merkle). Measured over 362
    -- real trajectory tokens: render-side and id-side agree on every one, 0
    -- disagreements. separator_ids() is 10.3 ms for the whole set.
    --
    -- realize.is_all_whitespace is NOT an English/ASCII assumption -- it is
    -- pg_laplace_is_all_whitespace in perfcache.c, an O(1) read of the compiled UCD
    -- record. The defect was only that it takes TEXT, so the caller had to render to
    -- reach it. Classifying by id skips the render, not a bad classifier.
    ws AS MATERIALIZED (
        SELECT DISTINCT t.entity_id AS id,
               t.entity_id = ANY (t_sep) AS is_ws
        FROM toks t
    ),
    kept AS MATERIALIZED (
        SELECT q.* FROM (
            SELECT t.gid, t.wt, t.is_core, t.entity_id,
                   row_number() OVER (PARTITION BY t.gid ORDER BY t.ord) AS rn,
                   count(*)    OVER (PARTITION BY t.gid) AS cnt
            FROM toks t JOIN ws ON ws.id = t.entity_id
            WHERE NOT ws.is_ws
        ) q WHERE q.cnt >= 2
    ),
    -- CONCEPT STREAM (GH #751; slot map: Embed is per-tier, the stream is
    -- language-free). Each distinct kept word maps to its best sense; words
    -- with no sense (numbers, names, glue) keep their surface id, so
    -- realization still has something to print. Election context is the
    -- token alone — EVIDENCE BEFORE ADJUDICATED STRENGTH, mirroring
    -- lexical.senses()'s own ORDER BY (witnesses, then consensus.eff_mu; the urine-over-water
    -- election in senses.sql.in is why strength alone mis-elects on
    -- one-witness exact ties). Contextual salience is Phase 3 (R3).
    -- lexical.senses() per DISTINCT token rides the same documented tolerance as
    -- the orientation above, until the C port (#757). The payoff is the
    -- LM-Head slot: realize.realize(concept, p_lang) finally gets to choose the
    -- language member instead of parroting the witness's surface — p_lang
    -- bites.
    kept_ids AS MATERIALIZED (
        SELECT DISTINCT k.entity_id AS id FROM kept k
    ),
    -- ONE election for every kept token, not one election per token.
    --
    -- This was a scalar subquery calling lexical.senses(d.id) per distinct token, which
    -- re-ran taxonomy.bubble_up's whole CTE cascade each time. Measured under
    -- auto_explain on compose_batch('what is a wolf', 12): CTE Scan `scoped`
    -- 51,351 ms over 798 loops, `cand_lang` 32,438 ms over 728 loops, `family_out`
    -- 15,358 ms over 2,394 loops -- 51.4 s of a 52.2 s statement, to elect senses
    -- for ~266 distinct tokens. The per-token work is small; the repetition was the
    -- cost. cand_lang collapses hardest: attestations cannot prune on subject_id, so
    -- the scalar form paid the full partition set once PER TOKEN.
    --
    -- Same ordering keys lexical.senses applied (witnesses, then base_eff_mu), and no k --
    -- bubble_up_batch's p_k defaults to NULL, so the election sees every candidate
    -- instead of a per-token prefix of one ordering.
    sense_pick AS MATERIALIZED (
        SELECT DISTINCT ON (b.term) b.term, b.synset_id
        FROM taxonomy.bubble_up_batch(ARRAY(SELECT id FROM kept_ids)) b
        ORDER BY b.term, b.witnesses DESC, b.base_eff_mu DESC NULLS LAST, b.synset_id
    ),
    concept_map AS MATERIALIZED (
        -- Tokens with no sense (numbers, names, glue) keep their surface id, so
        -- realization still has something to print.
        SELECT k.id AS wid, COALESCE(sp.synset_id, k.id) AS cid
        FROM kept_ids k
        LEFT JOIN sense_pick sp ON sp.term = k.id
    ),
    seq AS MATERIALIZED (
        -- THE STEER. Provenance weight (which source) PLUS frontier salience
        -- (how on-topic this turn) — matched in concept space, no surface
        -- projection. An off-frontier token stays eligible; a token whose
        -- concept the frontier actually holds pulls harder.
        SELECT k.gid, k.is_core,
               k.wt + COALESCE((fa.mu / 1e10)::bigint, 0) AS wt,
               cm.cid AS id, k.rn
        FROM kept k
        JOIN concept_map cm ON cm.wid = k.entity_id
        LEFT JOIN frontier_agg fa ON fa.cid = cm.cid
        UNION ALL
        SELECT DISTINCT k.gid, k.is_core, 0::bigint, SENT, 2147483647::bigint
        FROM kept k
    )
    SELECT (SELECT array_agg(s.id ORDER BY s.is_core DESC, s.gid, s.rn) FROM seq s),
           (SELECT array_agg(s.wt ORDER BY s.is_core DESC, s.gid, s.rn) FROM seq s),
           -- STARTS: first token of EVERY kept gid, core first. The
           -- core-only version made single-gloss topics deterministic replays:
           -- starts_n == 1, so the seed's start pick had nothing to choose and
           -- the walk replayed the one gloss chain byte-identically for every
           -- seed (GH #751 — 'dog'/'water'/'king' measured variance 1/3, while
           -- multi-anchor prompts recombined fine). Usage-sentence starts were
           -- already sanctioned as this column's own no-core fallback; widening
           -- makes them unconditional, which is what "recombination rather
           -- than replay" requires. Acceptance: the W5 lane detector printed by
           -- every deploy flips variance 1/3 -> 3/3 on the probe topics.
           (SELECT array_agg(k1.cid ORDER BY k1.is_core DESC, k1.gid)
            FROM (SELECT cm.cid, k0.is_core, k0.gid
                  FROM kept k0 JOIN concept_map cm ON cm.wid = k0.entity_id
                  WHERE k0.rn = 1
                  ORDER BY k0.is_core DESC, k0.gid) k1),
           (SELECT array_agg(cm.cid ORDER BY k.rn)
              FROM kept k JOIN concept_map cm ON cm.wid = k.entity_id
             WHERE k.is_core AND k.gid = (
                 SELECT k2.gid FROM kept k2 WHERE k2.is_core
                 GROUP BY k2.gid ORDER BY max(k2.cnt) DESC, k2.gid LIMIT 1))
    INTO stream, w, starts, core_seq;

    n := COALESCE(array_length(stream,1), 0);
    IF n < 3 OR starts IS NULL THEN
        RETURN QUERY
        SELECT s.seed, NULL::text
        FROM unnest(p_seeds) WITH ORDINALITY AS s(seed, ord)
        ORDER BY s.ord;
        RETURN;
    END IF;

    -- WALK every seed after the semantic frontier and concept stream have been
    -- built ONCE. Only RNG varies at this stage. Realization is then one batch
    -- over the union of every emitted id, not a per-seed replay of the same
    -- catalog work.
    --
    -- REALIZE last, and only here. p_lang selects which member of each concept's
    -- surface family is emitted; everything above ran in ids.
    -- BATCHED, over the DISTINCT emitted ids, re-expanded in emission order --
    -- the form converse_walk already carries and MEASURED at ~15.8x on 1,645
    -- tokens (1,895ms scalar against 15.6ms batched, comment at converse_walk
    -- :210-217). This lane was written after that fix and never given it, while
    -- being the one wired into converse.chat()'s walk shape.
    --
    -- BOTH ladders batch, because both are needed and they answer different
    -- questions: resolve_name_batch LABELS a concept in p_lang, while
    -- render_text_batch reconstructs content bytes for stream ids which did not
    -- resolve to a concept.  This stream is explicitly concept-first (concept_map
    -- above), so using realize.batch here was the wrong contract: realize.batch is
    -- content-first to keep ':' from becoming 'COLON', and therefore rendered OMW
    -- concept content such as `i88813` before consulting its English member
    -- `captain`.  The operation already knows whether it needs a label or a value;
    -- preserve that type information instead of asking one generic fallback ladder
    -- to guess.  COALESCE below remains label first, content second.
    --
    -- string_agg now carries ORDER BY gg.o. The scalar form had none: unnest WITH
    -- ORDINALITY names the position but does not oblige the aggregate to use it,
    -- so token order in a generated sentence rested on the executor happening to
    -- feed rows in scan order.
    RETURN QUERY
    WITH emitted AS MATERIALIZED (
        SELECT s.ord, s.seed,
               converse.steered_walk_raw(
                   stream, w, COALESCE(core_seq, ARRAY[]::bytea[]), starts,
                   p_steps, MINLEN,
                   abs(COALESCE(s.seed,
                       ('x'||substr(md5(p_prompt),1,8))::bit(32)::bigint)) % 2147483647
               ) AS ids
        FROM unnest(p_seeds) WITH ORDINALITY AS s(seed, ord)
    ),
    ids AS MATERIALIZED (
        SELECT array_agg(DISTINCT u.id) AS a
        FROM emitted e
        CROSS JOIN LATERAL unnest(e.ids) AS u(id)
    ),
    realized AS MATERIALIZED (
        SELECT i.a,
               realize.resolve_name_batch(i.a, p_lang) AS lbl,
               realize.render_text_batch(i.a) AS txt
        FROM ids i
    ),
    labels AS MATERIALIZED (
        SELECT (r.a)[k] AS id, (r.lbl)[k] AS lbl, (r.txt)[k] AS txt
        FROM realized r
        CROSS JOIN LATERAL generate_subscripts(r.a, 1) AS k
    )
    SELECT e.seed,
           CASE count(u.id)
               WHEN 0 THEN NULL::text
               WHEN 1 THEN max(l.txt)
               ELSE btrim(regexp_replace(
                        regexp_replace(
                            string_agg(COALESCE(l.lbl, l.txt, ''), ' ' ORDER BY u.ord),
                            '\s*[();:]\s*', ' ', 'g'),
                        '\s+', ' ', 'g'))
           END AS reply
    FROM emitted e
    LEFT JOIN LATERAL unnest(e.ids) WITH ORDINALITY AS u(id, ord) ON true
    LEFT JOIN labels l ON l.id = u.id
    GROUP BY e.ord, e.seed
    ORDER BY e.ord;
END;
$$;

DROP FUNCTION IF EXISTS laplace.converse_compose(text, int, bytea, bigint, bytea[]);
CREATE OR REPLACE FUNCTION converse.compose(p_prompt text,
                                            p_steps int DEFAULT 40,
                                            p_lang bytea DEFAULT NULL,
                                            p_seed bigint DEFAULT NULL,
                                            p_ctx bytea[] DEFAULT NULL)
    RETURNS text
    LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    out_text text;
BEGIN
    SELECT b.reply INTO out_text
    FROM generation.compose_batch(
        p_prompt, p_steps, p_lang, ARRAY[p_seed]::bigint[], p_ctx) b
    LIMIT 1;
    RETURN out_text;
END;
$$;
-- The W5 seed-variance probe as an installed surface: run both generation
-- lanes (incumbent converse_walk, challenger converse_compose) over a prompt
-- and a seed set, one row per (lane, seed). This is the measurement
-- converse_compose's header gates wiring on — "different text for different
-- seeds (recombination rather than replay), on topic" — made repeatable per
-- seed wave instead of living as ad-hoc operator SQL. Distinctness is then
-- count(DISTINCT reply) per lane over this table; topicality is read against
-- the topic's own consensus by the caller.
DROP FUNCTION IF EXISTS laplace.generation_probe(text, bigint[], int, bytea);
CREATE OR REPLACE FUNCTION generation.probe(p_prompt text,
                                            p_seeds bigint[],
                                            p_steps int DEFAULT 30,
                                            p_lang bytea DEFAULT NULL)
    RETURNS TABLE(lane text, seed bigint, reply text)
    LANGUAGE sql VOLATILE AS $$
    SELECT 'walk', b.seed, b.reply
    FROM generation.walk_batch(p_prompt, p_steps, p_seeds) b
    UNION ALL
    SELECT 'compose', b.seed, b.reply
    FROM generation.compose_batch(p_prompt, p_steps, p_lang, p_seeds) b
$$;
-- converse.tiered(topic, lang, steps): compose a reply by walking the SENTENCE
-- tier, steered by the Glicko tuple. The replacement for word-level n-grams.
--
-- WHAT WAS WRONG WITH THE OLD PATH. converse_walk gathers <=160 sentences, then
-- at converse_walk.sql.in:93 filters `u.ctier = 2` -- every trajectory is
-- flattened to word tokens -- concatenates them into `stream bytea[]` plus a
-- scalar `w bigint[]` (topic weight 50/40/0), and hands both to
-- steered_walk_raw for trigram->bigram backoff. Once you are inside those two
-- flat arrays there is no relation type, no consensus.eff_mu/rd/witness_count, no highway
-- band, no tier, no geometry and no provenance. That is a Markov chain using
-- the substrate as a word list; the tier ladder and the rating math -- the whole
-- invention -- are discarded before the walk begins.
--
-- WHAT THIS DOES INSTEAD. The tier ladder says a word's usage lives in the tier
-- above it. So walk THERE:
--
--   UNITS    tier-3/4 sentences the topic is actually attested in -- its gloss
--            (definitional band), its HAS_EXAMPLE usages. Each unit carries the
--            full signed weight the walker ranks by everywhere else:
--            consensus.relation_rank x consensus.eff_mu x witness saturation. A consensus.refuted
--            edge goes negative and drops out on its own -- no floor.
--   CONCEPTS each unit's tier-2 realize.constituents lifted to their synsets. The tier
--            ladder is USED here (3 -> 2 -> concept), not collapsed to 2.
--   STEER    the next unit is the one whose concepts carry the most rated
--            consensus mass to the concepts already said. The graph does the
--            sequencing, at sentence grain, through the same consensus.eff_mu the rest of
--            the engine reads. This is "sequence proposes, meaning steers" with
--            the steering actually live per step rather than computed once.
--   REALIZE  each chosen unit renders VERBATIM. It is attested content and the
--            trajectory is exactly invertible, so a composed reply is a sequence
--            of things witnesses actually said -- every clause traceable to its
--            witnesses, which is what makes the reply explainable rather than
--            merely fluent.
--
-- Recombination happens at the sentence pivot instead of the trigram pivot. No
-- floors, no top-k beyond query LIMITs, no stoplist, no surface compare, no
-- language assumption: units are chosen by rating and by graph adjacency.
--
-- STATUS: RUN on the deployed extension, 2026-07-26, topic = pawn:
--   "it can be promoted to a more powerful piece if it reaches the 8th rank.
--    change a pawn for a better piece by advancing it to the eighth row, or
--    change a checker piece for a more valuable piece by moving it to the row
--    closest to your opponent. (chess) the least powerful piece."
-- Four separately-witnessed clauses, stepped by concept adjacency, on topic.
-- Wired into converse.chat() on the strength of that run. Two defects it exposed are
-- fixed below: subsumed-unit repetition and missing clause termination.
--
-- LANGUAGE: gated below by a constituent tally, since the sentence root carries
-- no HAS_LANGUAGE but the word tier carries 6.7M. Corrects an earlier note here
-- that claimed no read-side work could fix language mixing -- it can, one tier
-- down. Residual leak (shared scientific Latin) documented at the gate.
--
-- READ-ONLY (#878): no CREATE TEMP / CREATE INDEX. Working set lives in plpgsql
-- arrays so the MCP op lane (SQLSTATE 25006) and any read-only connection can
-- call this. Algorithm identical; only the scratch storage moved.
DROP FUNCTION IF EXISTS laplace.converse_tiered(bytea, bytea, int, int);
CREATE OR REPLACE FUNCTION converse.tiered(p_topic bytea,
                                           p_lang  bytea DEFAULT NULL,
                                           p_steps int DEFAULT 4,
                                           p_pool  int DEFAULT NULL)
    RETURNS text
    LANGUAGE plpgsql STABLE AS $$
-- NO NEUTRAL SUBTRACTION. consensus_adjacency's export weight uses
-- (consensus.eff_mu - neutral) so consensus.refuted edges sign-flip, and copying that here was a bug
-- caught before it shipped: consensus.eff_mu arrives in the fold's INTERNAL units (~1e12,
-- so Glicko 1500 is 1.5e12), and consensus.eff_mu = rating - 2*rd puts every honestly
-- weakly-witnessed edge BELOW neutral. Measured on pawn: the whole gloss family
-- sits at 1.17e12-1.37e12, i.e. Glicko 1170-1370. Subtracting neutral and
-- keeping w > 0 would have dropped every unit and fallen back to template prose
-- forever, silently. Rank by the walker's signed Glicko expectation of the
-- folded rating/RD state instead; no second witness saturation or RD decay is
-- applied after the fold.
DECLARE
    said     bytea[] := ARRAY[]::bytea[];   -- units already emitted, in order
    seen     bytea[] := ARRAY[]::bytea[];   -- concepts already said
    cur      bytea;
    parts    text[]  := ARRAY[]::text[];
    s        text;
    i        int;
    v_syn    bytea;
    u_id     bytea[];
    u_w      float8[];
    c_unit   bytea[];
    c_concept bytea[];
    said_realized text[];
    said_rendered text[];
BEGIN
    IF p_topic IS NULL THEN RETURN NULL; END IF;
    IF p_steps IS NULL THEN
        RAISE EXCEPTION 'converse.tiered: steps must not be NULL';
    END IF;
    IF p_steps < 0 OR p_pool < 0 THEN
        RAISE EXCEPTION 'converse.tiered: steps and pool must be >= 0 or NULL for the complete pool';
    END IF;
    IF p_steps = 0 OR p_pool = 0 THEN RETURN NULL; END IF;

    -- Topic may arrive as a word id (chat/MCP). Gloss/example edges hang on the
    -- synset; walking the word as subject empties the unit pool and degenerates
    -- to topic-echo (#878). Elect the best sense when one exists.
    SELECT s.synset_id INTO v_syn
    FROM lexical.senses(p_topic) s
    ORDER BY s.witnesses DESC, s.eff_mu DESC NULLS LAST, s.synset_id
    LIMIT 1;
    IF v_syn IS NOT NULL THEN
        p_topic := v_syn;
    END IF;

    -- UNITS + their weight. The topic's own attested sentences (gloss, examples).
    -- REMOVED: a structural.containers_of() arm over every sense-subject of the topic
    -- ("sentences the topic appears in"). Measured 2026-07-27, topic = dog:
    -- that arm alone ran >100s and never returned. The asserted arm costs 0.03s
    -- and is not short of material (45 tier-3 sentences for dog).
    SELECT coalesce(array_agg(x.id ORDER BY x.w DESC, x.id), ARRAY[]::bytea[]),
           coalesce(array_agg(x.w  ORDER BY x.w DESC, x.id), ARRAY[]::float8[])
    INTO u_id, u_w
    FROM (
        SELECT u.id, max(u.w) AS w
        FROM (
            SELECT c.object_id AS id,
                   consensus.relation_rank_resolved(c.type_id)
                     * consensus.eff_mu(c.rating, c.rd)::float8
                     * (c.witness_count::float8 / (1.0 + c.witness_count)) AS w
            FROM laplace.consensus c
            JOIN laplace.entities e ON e.id = c.object_id AND e.tier >= 3
            WHERE c.subject_id = p_topic
        ) u
        WHERE u.w > 0
        GROUP BY u.id
    ) x;

    IF coalesce(array_length(u_id, 1), 0) = 0 THEN RETURN NULL; END IF;

    -- An explicit caller pool cuts the rated order before the concept lift;
    -- NULL retains the complete population.
    IF p_pool IS NOT NULL AND array_length(u_id, 1) > p_pool THEN
        u_id := u_id[1:p_pool];
        u_w  := u_w[1:p_pool];
    END IF;

    -- CONCEPTS per unit: tier-2 realize.constituents lifted to synsets. SET-BASED,
    -- NOT PER WORD (taxonomy.top_synset per row hung at 73s for 48 dog units).
    -- Fence HAS_SENSE family once (incl. dynamic children via relation_in_family).
    SELECT coalesce(array_agg(q.unit ORDER BY q.unit, q.concept), ARRAY[]::bytea[]),
           coalesce(array_agg(q.concept ORDER BY q.unit, q.concept), ARRAY[]::bytea[])
    INTO c_unit, c_concept
    FROM (
        SELECT DISTINCT ON (p.id, tp.entity_id) p.id AS unit, sc.object_id AS concept
        FROM unnest(u_id) AS p(id)
        CROSS JOIN LATERAL generation.trajectory_unpacked_points(p.id) tp
        JOIN laplace.consensus sc ON sc.subject_id = tp.entity_id
        JOIN (
            SELECT e.id
            FROM laplace.entities e
            WHERE e.type_id = laplace.entity_type_id('RelationType')
              AND consensus.relation_in_family(e.id, 'HAS_SENSE')
        ) fam ON fam.id = sc.type_id
        WHERE tp.ctier = 2
        ORDER BY p.id, tp.entity_id, consensus.eff_mu(sc.rating, sc.rd) DESC, sc.object_id
    ) q;

    -- ANSWER IN THE LANGUAGE THAT WAS ASKED. Kept in HASH SPACE.
    -- A unit with no language evidence at all is KEPT, not dropped.
    -- Units with a winning language vote in another language drop; units with
    -- no language evidence stay (absence is not evidence of a foreign language).
    IF p_lang IS NOT NULL AND coalesce(array_length(c_unit, 1), 0) > 0 THEN
        SELECT coalesce(array_agg(u ORDER BY ord), ARRAY[]::bytea[]),
               coalesce(array_agg(w ORDER BY ord), ARRAY[]::float8[])
        INTO u_id, u_w
        FROM (
            SELECT u, w, ord
            FROM unnest(u_id, u_w) WITH ORDINALITY AS x(u, w, ord)
            WHERE NOT EXISTS (
                SELECT 1
                FROM (
                    SELECT DISTINCT ON (t.unit) t.unit, t.lg
                    FROM (
                        SELECT k.unit, lc.object_id AS lg, count(*) AS votes
                        FROM unnest(c_unit, c_concept) AS k(unit, concept)
                        JOIN laplace.consensus lc ON lc.subject_id = k.concept
                                         AND lc.type_id = laplace.relation_type_id('HAS_LANGUAGE')
                        GROUP BY k.unit, lc.object_id
                    ) t
                    ORDER BY t.unit, t.votes DESC, t.lg
                ) foreign_top
                WHERE foreign_top.unit = x.u AND foreign_top.lg <> p_lang
            )
        ) kept;

        SELECT coalesce(array_agg(cu ORDER BY cu, cc), ARRAY[]::bytea[]),
               coalesce(array_agg(cc ORDER BY cu, cc), ARRAY[]::bytea[])
        INTO c_unit, c_concept
        FROM unnest(c_unit, c_concept) AS k(cu, cc)
        WHERE cu = ANY (u_id);
    END IF;

    IF coalesce(array_length(u_id, 1), 0) = 0 THEN RETURN NULL; END IF;

    -- OPEN on the best-rated unit (arrays already ordered by w DESC, id).
    cur := u_id[1];

    FOR i IN 1..p_steps LOOP
        EXIT WHEN cur IS NULL;
        said := said || cur;
        seen := seen || ARRAY(
            SELECT cc FROM unnest(c_unit, c_concept) AS k(cu, cc) WHERE cu = cur);

        -- STEER BY SHARED CONCEPTS (intersection), edge mass as tiebreak.
        -- Two direction-pinned reads UNION ALL — never an OR join (#871 / #878).
        SELECT n.unit INTO cur
        FROM (
            SELECT k.unit,
                   count(*) AS shared,
                   COALESCE((
                       SELECT sum(consensus.relation_rank_resolved(c.type_id)
                                  * consensus.eff_mu(c.rating, c.rd)::float8)
                       FROM laplace.consensus c
                       WHERE c.subject_id = ANY (ARRAY(
                                 SELECT cc FROM unnest(c_unit, c_concept) AS x(cu, cc)
                                 WHERE cu = k.unit))
                         AND c.object_id = ANY(seen)
                   ), 0)
                   + COALESCE((
                       SELECT sum(consensus.relation_rank_resolved(c.type_id)
                                  * consensus.eff_mu(c.rating, c.rd)::float8)
                       FROM laplace.consensus c
                       WHERE c.object_id = ANY (ARRAY(
                                 SELECT cc FROM unnest(c_unit, c_concept) AS x(cu, cc)
                                 WHERE cu = k.unit))
                         AND c.subject_id = ANY(seen)
                   ), 0) AS pull
            FROM unnest(c_unit, c_concept) AS k(unit, concept)
            WHERE NOT (k.unit = ANY(said))
              AND k.concept = ANY(seen)
              AND EXISTS (
                  SELECT 1 FROM unnest(c_unit, c_concept) AS nk(unit, concept)
                   WHERE nk.unit = k.unit AND NOT (nk.concept = ANY(seen)))
            GROUP BY k.unit
        ) n
        JOIN LATERAL (
            SELECT u_w[array_position(u_id, n.unit)] AS w
        ) u ON true
        ORDER BY n.shared DESC, n.pull DESC, u.w DESC NULLS LAST, n.unit
        LIMIT 1;
    END LOOP;

    -- REALIZE verbatim, in walk order. Terminate each unit that does not already
    -- end in punctuation (clause seam, not content rewrite).
    said_realized := realize.batch(said, p_lang);
    said_rendered := realize.render_text_batch(said);
    FOR i IN 1..COALESCE(array_length(said, 1), 0) LOOP
        s := btrim(COALESCE(said_realized[i], said_rendered[i]));
        IF s IS NOT NULL AND s <> '' THEN
            IF s !~ '[.!?;:,]$' THEN s := s || '.'; END IF;
            parts := parts || s;
        END IF;
    END LOOP;

    IF array_length(parts, 1) IS NULL THEN RETURN NULL; END IF;
    RETURN btrim(regexp_replace(array_to_string(parts, ' '), '\s+', ' ', 'g'));
END;
$$;
-- converse.chat_scaffold — per-language connective templates for converse.chat.
--
-- GH #901: converse.chat()'s render side was gluing realized labels with hardcoded English
-- connectives while the parse side and language tally were language-agnostic.
-- A Bulgarian prompt correctly resolved lang, then wrapped Bulgarian labels in
-- English scaffolding — the 2026-07-25 Bulgarian-dog defect one layer down.
--
-- This is the minimal per-language template table (keyed on the resolved lang
-- id). English and Bulgarian ship as first citizens (the two languages that
-- exposed the defect). Every other lang falls back to a typographic form that
-- carries no English verbs: "Topic: labels." That is honest S9 fallback, not a
-- pretend translation. Connectives-as-realized-entities through consensus remains
-- the longer inventively-correct path; this stops the lie now.
--
-- p_key is a fixed slot name (parts / kinds / related / core / no_edges / no_type /
-- no_forward / band). p_topic and p_labels / p_extra fill the slots. Missing
-- pieces yield NULL so the caller can decide, not empty-string silence.
DROP FUNCTION IF EXISTS laplace.chat_scaffold(bytea, text, text, text, text);
CREATE OR REPLACE FUNCTION converse.chat_scaffold(
        p_lang   bytea,
        p_key    text,
        p_topic  text DEFAULT NULL,
        p_labels text DEFAULT NULL,
        p_extra  text DEFAULT NULL)
    RETURNS text
    LANGUAGE plpgsql STABLE PARALLEL SAFE AS $$
DECLARE
    en bytea := realize.canonical_id('language:eng');
    bg bytea := realize.canonical_id('language:bul');
    t  text := COALESCE(p_topic, '');
    l  text := COALESCE(p_labels, '');
    x  text := COALESCE(p_extra, '');
BEGIN
    IF p_key IS NULL THEN RETURN NULL; END IF;

    -- English (explicit eng id, or NULL lang — today's chat leaves lang NULL when
    -- the prompt carries no HAS_LANGUAGE evidence; English templates remain the
    -- S9 default for that case, matching prior behaviour).
    IF p_lang IS NULL OR p_lang = en THEN
        RETURN CASE p_key
            WHEN 'parts'      THEN initcap(t) || ' has parts such as ' || l || '.'
            WHEN 'kinds'      THEN 'Kinds of ' || t || ' include ' || l || '.'
            WHEN 'related'    THEN initcap(t) || ' is related to ' || l || '.'
            WHEN 'core'       THEN 'That is the core of what I hold about ' || t || '.'
            WHEN 'no_edges'   THEN 'I hold no witnessed edges for ' || t || ' in the selected bands yet.'
            WHEN 'no_type'    THEN 'I hold no witnessed ' || lower(x) || ' for ' || t || ' yet.'
            WHEN 'no_forward' THEN CASE WHEN t = ''
                                   THEN 'No witnessed continuation was selected in this forward pass.'
                                   ELSE 'No witnessed continuation was selected for ' || t || ' in this forward pass.'
                               END
            WHEN 'band'       THEN x || ': ' || l || '.'
            ELSE NULL
        END;
    END IF;

    IF p_lang = bg THEN
        RETURN CASE p_key
            WHEN 'parts'      THEN initcap(t) || ' има части като ' || l || '.'
            WHEN 'kinds'      THEN 'Видове ' || t || ' включват ' || l || '.'
            WHEN 'related'    THEN initcap(t) || ' е свързано с ' || l || '.'
            WHEN 'core'       THEN 'Това е същността на това, което знам за ' || t || '.'
            WHEN 'no_edges'   THEN 'Нямам засвидетелствани връзки за ' || t || ' в избраните ленти още.'
            WHEN 'no_type'    THEN 'Нямам засвидетелствано ' || lower(x) || ' за ' || t || ' още.'
            WHEN 'no_forward' THEN CASE WHEN t = ''
                                   THEN 'Няма избрано засвидетелствано продължение в този ход.'
                                   ELSE 'Няма избрано засвидетелствано продължение за ' || t || ' в този ход.'
                               END
            WHEN 'band'       THEN x || ': ' || l || '.'
            ELSE NULL
        END;
    END IF;

    -- Other languages: no English verbs. Band name (still English from the
    -- catalog) is omitted so the line is not a mixed-language lie. An empty
    -- forward pass uses a language-neutral absence marker instead of pretending
    -- a translation exists. The topic arrived from the selected realization;
    -- do not add a second case-folding policy merely to decorate an abstention.
    RETURN CASE p_key
        WHEN 'parts'      THEN initcap(t) || ': ' || l || '.'
        WHEN 'kinds'      THEN initcap(t) || ': ' || l || '.'
        WHEN 'related'    THEN initcap(t) || ': ' || l || '.'
        WHEN 'core'       THEN initcap(t) || '.'
        WHEN 'no_edges'   THEN initcap(t) || '.'
        WHEN 'no_type'    THEN initcap(t) || '.'
        WHEN 'no_forward' THEN CASE WHEN t = '' THEN '∅' ELSE t || ': ∅' END
        WHEN 'band'       THEN l || '.'
        ELSE NULL
    END;
END;
$$;
CREATE UNLOGGED TABLE IF NOT EXISTS converse.session_topics (
    session_id  bytea       NOT NULL,
    ord         integer     NOT NULL,
    prompt      text        NOT NULL,
    resolved_id bytea,
    asked_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (session_id, ord)
);
-- ORIENT_TOPIC: elect the prompt's candidate concepts under the operator's
-- primary language without turning that preference into an absolute gate.
--
-- The primary language is a request prior.  If it admits no candidate, the
-- prompt's own language tally gets one pass; if that also admits nothing, the
-- operation widens to the language-neutral candidate set.  The receipt travels
-- with every returned candidate so callers can distinguish an ordinary
-- primary-language resolution from a widened turn.
CREATE OR REPLACE FUNCTION converse.orient_topic(
        p_prompt text,
        p_primary_language bytea DEFAULT NULL)
    RETURNS TABLE(
        rank int,
        synset_id bytea,
        candidate_language bytea,
        primary_language bytea,
        prompt_language bytea,
        effective_language bytea,
        widened boolean)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    -- prompt_coherence can return several candidate senses. Language lookup is
    -- deliberately relation-in/relation-out: laplace.consensus is LIST-partitioned
    -- by relation type, and calling converse.word_language() once per candidate
    -- repays that partition traversal once per row. The canonical batch surface
    -- exists specifically to collapse those probes into one HAS_LANGUAGE scan.
    WITH raw_candidates AS MATERIALIZED (
        SELECT y.synset_id,
               y.denote_mu,
               y.specificity,
               y.rel_mass,
               y.peers,
               y.ord
        FROM converse.prompt_coherence(p_prompt) y
        WHERE y.synset_id IS NOT NULL
    ),
    candidate_ids AS MATERIALIZED (
        SELECT array_agg(DISTINCT r.synset_id ORDER BY r.synset_id) AS ids
        FROM raw_candidates r
    ),
    language_ranked AS MATERIALIZED (
        SELECT l.word,
               l.lang,
               row_number() OVER (
                   PARTITION BY l.word
                   ORDER BY l.mu DESC, l.lang) AS rn
        FROM candidate_ids i
        CROSS JOIN LATERAL converse.word_language_candidates_batch(i.ids) l
    ),
    candidates AS MATERIALIZED (
        SELECT r.synset_id,
               l.lang,
               r.denote_mu,
               r.specificity,
               r.rel_mass,
               r.peers,
               r.ord
        FROM raw_candidates r
        LEFT JOIN language_ranked l
          ON l.word = r.synset_id
         AND l.rn = 1
    ),
    primary_check AS (
        SELECT EXISTS (
                   SELECT 1
                   FROM candidates c
                   WHERE p_primary_language IS NOT NULL
                     AND c.lang = p_primary_language
               ) AS available
    ),
    observed AS MATERIALIZED (
        -- The operator prior is the fast path.  Prompt-language inference is a
        -- fallback probe, not work every successful primary-language turn pays.
        SELECT CASE
                   WHEN p_primary_language IS NULL OR NOT p.available
                   THEN converse.prompt_language_top(p_prompt)
                   ELSE NULL::bytea
               END AS lang
        FROM primary_check p
    ),
    availability AS (
        SELECT o.lang AS observed_language,
               EXISTS (
                   SELECT 1
                   FROM candidates c
                   WHERE o.lang IS NULL OR c.lang IS NULL OR c.lang = o.lang
               ) AS observed_available
        FROM observed o
    ),
    decision AS (
        SELECT a.*, p.available AS primary_available,
               CASE
                   WHEN p_primary_language IS NULL THEN 0
                   WHEN p.available THEN 0
                   WHEN a.observed_language IS NULL
                     OR a.observed_language = p_primary_language THEN 0
                   WHEN a.observed_available THEN 1
                   ELSE 2
               END AS mode,
               CASE
                   WHEN p_primary_language IS NULL THEN a.observed_language
                   WHEN p.available THEN p_primary_language
                   WHEN a.observed_language IS NULL
                     OR a.observed_language = p_primary_language THEN p_primary_language
                   ELSE a.observed_language
               END AS effective_language
        FROM availability a
        CROSS JOIN primary_check p
    ),
    selected AS (
        SELECT c.*, d.observed_language, d.effective_language, d.mode
        FROM candidates c
        CROSS JOIN decision d
        WHERE d.mode = 2
           OR d.effective_language IS NULL
           OR c.lang IS NULL
           OR c.lang = d.effective_language
    )
    SELECT row_number() OVER (ORDER BY
               y.specificity DESC NULLS LAST,
               y.rel_mass DESC NULLS LAST,
               y.peers DESC,
               y.ord DESC,
               y.denote_mu DESC NULLS LAST,
               y.synset_id)::int,
           y.synset_id,
           y.lang,
           p_primary_language,
           y.observed_language,
           y.effective_language,
           y.mode <> 0
    FROM selected y;
END;
-- converse.chat(prompt, session, lang, shape, bands, topic, topic2, type_name, elaborate)
-- A conversational turn: a THIN orchestrator over the existing intent machinery.
--
--   ORIENT  the topic is the prompt token whose synset carries the most
--           content-band consensus mass -- a measurement over the graph, not a
--           parse. An explicit p_topic from the caller wins outright.
--   SHAPE   the caller names the read (converse.query_shapes()); nothing is
--           inferred from how the prompt is phrased.
--   LENS    p_bands selects salience bands. One band-parameterized read now
--           covers what used to be three hardcoded English branches
--           (parts / kinds / causes) and covers the other ten bands with it.
--   CARRY   session is metadata: a turn with no resolvable topic carries the
--           session's last resolved topic. p_elaborate advances through
--           non-empty fact layers.
--   CLOSE   happens at the FRONTEND, not here: every caller (MCP chat tool, HTTP
--           TurnWitness, CLI chat) deposits the prompt (UserPrompt) and response
--           (Response) through the writer spine -- full content mint + evidence +
--           inline fold, proper trust classes. SQL converse.chat() stays read-side; its only
--           write is session_topics app-state.
--
-- The English pattern ladder this function used to run on (parse_ask, plus five
-- inline regexes over the prompt) is gone from the PARSE side. It answered only
-- English, in a substrate whose identity law is language-agnostic by construction.
--
-- RENDER-SIDE CONNECTIVES (GH #901): every English glue string that used to
-- live inline here now goes through converse.chat_scaffold(lang, key, …) — a
-- per-language template table keyed on the resolved lang id. English and
-- Bulgarian ship; other langs get a typographic form with no English verbs.
-- Connectives-as-realized-entities through consensus remains the longer path;
-- the scaffold stops the mixed-language lie the 2026-07-25 Bulgarian-dog
-- incident exposed one layer down from the language tally below.
DROP FUNCTION IF EXISTS laplace.chat(text, bytea, bytea, text, int[], bytea, bytea, text, boolean);
CREATE OR REPLACE FUNCTION converse.chat(p_prompt text,
                                p_session bytea DEFAULT NULL,
                                p_lang bytea DEFAULT NULL,
                                p_shape text DEFAULT NULL,
                                p_bands int[] DEFAULT NULL,
                                p_topic bytea DEFAULT NULL,
                                p_topic2 bytea DEFAULT NULL,
                                p_type_name text DEFAULT NULL,
                                p_elaborate boolean DEFAULT false)
    RETURNS text
    LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    topic bytea; topic2 bytea;
    ctx_arr bytea[];  -- biography for the walk branch (session_trajectory, recent-first)
    cands bytea[];   -- topic orientation, ranked, computed ONCE per turn
    oriented_lang bytea;
    xl    text;
    depth int;
    layers text[]; s text;
    resolved bytea;
    shape text := NULLIF(btrim(COALESCE(p_shape, '')), '');
    lang  bytea := p_lang;
    out   text := '';
BEGIN
    -- Natural turns enter forward_text with the canonical prompt root. Explicit
    -- query shapes remain typed inspection requests; they do not interpret chat.
    IF shape IS NULL THEN
        SELECT array_agg(laplace.word_id(t.prompt) ORDER BY t.ord) INTO ctx_arr
        FROM converse.session_topics t WHERE t.session_id = p_session;
        SELECT string_agg(g.entity, '' ORDER BY g.step) INTO out
        FROM generation.forward_text(
            p_prompt, 40, 5, 0.6, 10,
            laplace.hash128_lo(laplace.word_id(p_prompt)),
            2, 8, ctx_arr) g;
        IF p_session IS NOT NULL THEN
            PERFORM generation.session_record_prompt(
                p_session, p_prompt, laplace.word_id(p_prompt));
        END IF;
        RETURN out;
    END IF;

    -- ANSWER IN THE LANGUAGE THAT WAS ASKED. A concept's surfaces are a FAMILY
    -- spanning every language that witnesses it, and realize.realize(id, NULL) is free to
    -- pick any member -- so with no language pinned, an English prompt can be
    -- answered from a Bulgarian surface. Observed 2026-07-25: converse.walk('dog')
    -- returned a fluent Bulgarian description of a dog. The mesh working exactly as
    -- designed, surfacing at the wrong moment.
    --
    -- Language is not concept identity.  It is request orientation: the operator's
    -- primary language is tried first, prompt evidence may temporarily redirect a
    -- turn that otherwise resolves nothing, and realization receives the effective
    -- language only after concept election.  ORIENT_TOPIC below owns that decision
    -- and exposes whether it widened; this function does not mutate an operator
    -- profile because one quotation or code-switch is not a durable preference.
    -- TOPIC = rank-1 of converse.prompt_coherence (native). Keys, in order:
    -- contextual/structural specificity, relation-directed mass, peer support,
    -- folded evidence, ord DESC (recency among sense-bearing tokens when those
    -- keys are silent), synset_id. Each signal is an explicit dimension.
    -- Entirely in ids — no render/label mid-election. cands kept for topic2.
    --
    -- Dead forms (names only; post-mortems in git / GH #902): surface match
    -- (pre-2026-07-25), denote_mu-first, breadth-first (2026-07-25),
    -- breadth+denote_mu (2026-07-26), raw coherence, inverse own-mass (2026-08-01).
    IF p_topic IS NOT NULL THEN
        topic := p_topic;
        lang := COALESCE(lang, converse.prompt_language_top(p_prompt));
    ELSE
        -- ORIENT_TOPIC owns the language prior, prompt-language fallback and
        -- election order (coherence * witnessed mass, then total tie-breaks).
        -- It evaluates prompt_coherence once and returns the
        -- effective realization language as an execution receipt.  A primary
        -- language that finds nothing widens this turn; it does not silently
        -- rewrite the operator's profile.
        SELECT array_agg(o.synset_id ORDER BY o.rank),
               (array_agg(o.effective_language ORDER BY o.rank))[1]
          INTO cands, oriented_lang
        FROM converse.orient_topic(p_prompt, p_lang) o;
        lang := COALESCE(oriented_lang, p_lang);
        topic := cands[1];
        -- Nothing in this turn resolved: read the session's BIOGRAPHY, not one
        -- carried id (R7 / GH #759 slice 1). generation.session_last_resolved() answered
        -- "what did the last turn resolve"; the discourse question is "which of
        -- the topics this session has witnessed is THIS turn about", and that is
        -- an attention read — the turn's token senses are the query, the
        -- session's trajectory topics are the keys, rated consensus mass between
        -- them is the score. Both directions, written as two correlated indexed
        -- probes per trajectory row (k <= 8) rather than an OR join; the senses
        -- are collected ONCE. sum() over zero rows is NULL — an unwired topic is
        -- unranked evidence, not evidence of zero — and COALESCE enters only in
        -- the ORDER BY, where ranking needs a total order. With no adjacency
        -- anywhere the ordering degrades to last_ord DESC, which is exactly
        -- session_last_resolved's semantics: recency is the fallback, no longer
        -- the whole read.
        IF topic IS NULL AND p_session IS NOT NULL THEN
            -- The query set is TOKEN IDS PLUS THEIR SENSES, not senses alone. In
            -- the regime where this branch fires (topic NULL), no prompt token
            -- resolved a sense — a senses-only key set is provably empty exactly
            -- when this code runs. The token ids themselves still carry edges: the
            -- measured data-starved case (lexical.senses('животно') = 0) has the word
            -- wired to its synset by OMW's word->synset IS_SYNONYM_OF, and that
            -- edge is precisely what links an unsensed surface to a discourse
            -- topic. Senses stay in the set for the day partial resolution makes
            -- this branch reachable with them present.
            -- prompt_words, not prompt_state: this branch only needs the token ids,
            -- and prompt_state pays a converse.word_language() consensus read per token for
            -- a column nothing here reads (Copilot, PR #893).
            WITH ptok AS MATERIALIZED (
                SELECT p.id FROM converse.prompt_words(p_prompt) p WHERE p.id IS NOT NULL
            ),
            psense AS MATERIALIZED (
                SELECT DISTINCT x.sid FROM (
                    SELECT t.id AS sid FROM ptok t
                    UNION ALL
                    SELECT s.synset_id FROM ptok t
                    CROSS JOIN LATERAL lexical.senses(t.id) s
                    WHERE s.synset_id IS NOT NULL
                ) x
            ),
            adj AS (
                SELECT st.topic_id, st.last_ord,
                       (SELECT sum(consensus.eff_mu(c.rating, c.rd))
                        FROM psense ps
                        JOIN laplace.consensus c ON c.subject_id = st.topic_id
                                        AND c.object_id = ps.sid) AS m_out,
                       (SELECT sum(consensus.eff_mu(c.rating, c.rd))
                        FROM psense ps
                        JOIN laplace.consensus c ON c.object_id = st.topic_id
                                        AND c.subject_id = ps.sid) AS m_in
                FROM converse.session_trajectory(p_session, 8) st
            )
            SELECT a.topic_id INTO topic
            FROM adj a
            ORDER BY (COALESCE(a.m_out, 0) + COALESCE(a.m_in, 0)) DESC,
                     a.last_ord DESC
            LIMIT 1;
        END IF;
    END IF;

    IF topic IS NULL THEN
        IF shape IS NULL THEN
            SELECT array_agg(st.topic_id ORDER BY st.last_ord DESC) INTO ctx_arr
              FROM converse.session_trajectory(p_session, 8) st;
            SELECT string_agg(g.entity, '' ORDER BY g.step) INTO out
              FROM generation.forward_text(
                    p_prompt, 40, 5, 0.6, 10,
                    hashtextextended(COALESCE(p_session::text, '') || p_prompt, 0),
                    2, 8, ctx_arr) g;
        ELSE
            out := converse.converse(p_prompt);
        END IF;
    ELSE
        resolved := topic;  xl := realize.realize(topic, lang);
        topic2 := p_topic2;

        -- Second topic for the two-topic shapes: the caller's, else the next
        -- ranked candidate that is not the first. Reuses the ranking already
        -- computed above rather than re-segmenting the same input.
        IF topic2 IS NULL AND shape IN ('reason', 'is_a') AND cands IS NOT NULL THEN
            SELECT u.syn INTO topic2
            FROM unnest(cands) WITH ORDINALITY u(syn, ord)
            WHERE u.syn <> topic
            ORDER BY u.ord
            LIMIT 1;
        END IF;

        IF p_elaborate AND p_session IS NOT NULL THEN
            -- ELABORATE: advance through NON-EMPTY fact layers by prior mentions.
            -- Built ON the band-lens pattern below, not beside it. Four defects the
            -- scalar form carried, all fixed here and none of them a law change:
            --   * (c.rating-2*c.rd) open-coded three times -- a SECOND definition of
            --     edge strength inside a function whose other branches call consensus.eff_mu().
            --     If consensus.eff_mu's definition moves, this branch silently diverges.
            --   * realize.realize() PER ROW before the cut, in the same file whose band lens
            --     measures that at ~7 ms/id against ~0.3 ms/id batched.
            --   * bare band literals 4/2/7 -- converse.relation_band_catalog() rows restated
            --     as magic numbers.
            --   * the associative band read RAW, without converse.non_kin_assoc_types(): the
            --     etymology/usage/register families converse_facts excludes in id
            --     space were being rendered as things the topic "is related to".
            -- A dead `LIMIT 3` on a single-row aggregate is dropped with them.
            WITH bands AS (
                SELECT b.band,
                       CASE b.name WHEN 'partitive'   THEN 1
                                   WHEN 'taxonomic'   THEN 2
                                   WHEN 'associative' THEN 3 END AS layer
                FROM converse.relation_band_catalog() b
                WHERE b.name IN ('partitive', 'taxonomic', 'associative')
            ),
            sel AS MATERIALIZED (
                -- Types resolved ONCE, structural families removed in ID SPACE.
                -- consensus.relation_highway_band() is a C STABLE call; in the edge predicate
                -- it runs per EDGE and makes the scan unsargable.
                SELECT e.id AS type_id, bd.layer
                FROM laplace.entities e
                JOIN bands bd ON bd.band = consensus.relation_highway_band(e.id)
                WHERE e.type_id = laplace.entity_type_id('RelationType')
                  AND e.id NOT IN (SELECT id FROM converse.non_kin_assoc_types())
            ),
            edges AS MATERIALIZED (
                -- parts and kin read forward (topic -> object); kinds reads backward,
                -- because the kinds OF a topic are the subjects whose hypernym it is.
                SELECT s.layer, c.object_id AS nid, consensus.eff_mu(c.rating, c.rd) AS m
                FROM sel s
                JOIN laplace.consensus c ON c.type_id = s.type_id AND c.subject_id = topic
                WHERE s.layer IN (1, 3) AND c.object_id IS NOT NULL
                UNION ALL
                SELECT s.layer, c.subject_id, consensus.eff_mu(c.rating, c.rd)
                FROM sel s
                JOIN laplace.consensus c ON c.type_id = s.type_id AND c.object_id = topic
                WHERE s.layer = 2
            ),
            ranked AS MATERIALIZED (
                SELECT layer, nid, m,
                       row_number() OVER (PARTITION BY layer ORDER BY m DESC, nid) AS rn
                FROM edges
            ),
            -- MATERIALIZED and TOTALLY ORDERED: `ix` indexes the realize_batch array
            -- and this CTE is read twice, so an unfenced re-evaluation in a different
            -- physical order would pair every label with the wrong edge.
            ord AS MATERIALIZED (
                SELECT layer, nid, m,
                       row_number() OVER (ORDER BY layer, m DESC, nid) AS ix
                FROM ranked
                WHERE rn <= CASE layer WHEN 1 THEN 6 ELSE 8 END  -- caps as before
            ),
            lbl AS MATERIALIZED (
                SELECT realize.batch(array_agg(o.nid ORDER BY o.ix), lang) AS l
                FROM ord o
            )
            SELECT array_agg(q.line ORDER BY q.layer) INTO layers FROM (
                SELECT o.layer,
                       converse.chat_scaffold(
                           lang,
                           CASE o.layer WHEN 1 THEN 'parts' WHEN 2 THEN 'kinds' ELSE 'related' END,
                           xl,
                           string_agg(lbl.l[o.ix],
                                      CASE WHEN o.layer = 3 THEN ' and ' ELSE ', ' END
                                      ORDER BY o.m DESC)) AS line
                FROM ord o
                CROSS JOIN lbl
                WHERE lbl.l[o.ix] IS NOT NULL
                  -- last-resort realize.render guard, kin layer only (as converse_facts keeps it)
                  AND (o.layer <> 3 OR converse.label_is_content(lbl.l[o.ix]))
                GROUP BY o.layer
            ) q;
            layers := COALESCE(layers, ARRAY[]::text[]);
            SELECT count(*) INTO depth FROM converse.session_topics t
              WHERE t.session_id=p_session AND t.resolved_id=topic;
            out := CASE WHEN depth BETWEEN 1 AND COALESCE(array_length(layers,1),0)
                        THEN layers[depth]
                        ELSE converse.chat_scaffold(lang, 'core', xl) END;

        ELSIF p_bands IS NOT NULL AND array_length(p_bands, 1) > 0 THEN
            -- BAND LENS: every edge of the topic inside the selected bands, both
            -- directions, ranked by consensus.eff_mu. This one read replaces the former
            -- parts / kinds / causes English branches and generalizes to all 13.
            -- HASH SPACE, THEN ONE realize_batch. This used to call realize.realize() PER
            -- ROW on both arms of the UNION, before any filter or limit, so a
            -- high-degree topic paid a scalar realize.render for every edge it has.
            -- Measured 2026-07-28 on the foundation substrate: the scalar ladder
            -- runs ~7 ms/id, one batched call ~0.3 ms/id -- and the densest
            -- subject here carries 6,687 edges. Same rows, same order, same
            -- grouping; the labels are resolved once over the collected ids and
            -- joined back by ordinal (realize_batch is position-aligned, pinned by
            -- tests/sql/realize_ladder_parity.sql).
            WITH sel AS MATERIALIZED (
                -- The band's relation types, resolved ONCE. consensus.relation_highway_band()
                -- is a C STABLE call; evaluating it in the edge predicate ran it per
                -- EDGE and made the scan unsargable. There are ~189 governed types,
                -- so resolving the set up front turns the filter into an indexed
                -- (subject_id, type_id) probe — the same move consensus.band_edges
                -- makes natively.
                -- Structural families are excluded HERE, in id space, before a
                -- single edge is read -- not by filtering rendered strings after.
                -- The associative band carries etymology, usage examples, register
                -- labels and lexfile categories next to real kin, which is what put
                -- "06831177-n, noun.communication, 05593148-n" in a band listing.
                -- converse_facts already resolved this the right way
                -- (non_kin_assoc_types, whole families via consensus.relation_family_members)
                -- and kept label_is_content only as a last-resort realize.render guard; the
                -- lens was still reading the band raw.
                SELECT e.id AS type_id, consensus.relation_highway_band(e.id) AS band
                FROM laplace.entities e
                WHERE e.type_id = laplace.entity_type_id('RelationType')
                  AND consensus.relation_highway_band(e.id) = ANY(p_bands)
                  AND e.id NOT IN (SELECT id FROM converse.non_kin_assoc_types())
            ),
            edges AS MATERIALIZED (
                SELECT s.band, c.object_id AS nid, consensus.eff_mu(c.rating, c.rd) AS m
                FROM sel s
                JOIN laplace.consensus c ON c.type_id = s.type_id AND c.subject_id = topic
                WHERE c.object_id IS NOT NULL
                UNION ALL
                SELECT s.band, c.subject_id, consensus.eff_mu(c.rating, c.rd)
                FROM sel s
                JOIN laplace.consensus c ON c.type_id = s.type_id AND c.object_id = topic
            ),
            -- MATERIALIZED and TOTALLY ORDERED, both load-bearing. `ord` indexes the
            -- realize_batch array, and this CTE is read twice below; an unfenced CTE
            -- with `row_number() OVER ()` (no ORDER BY) can be re-evaluated in a
            -- different physical order per scan, which would silently pair every
            -- label with the wrong edge.
            -- RANK, CAP, THEN LABEL. Batching made the uncapped lens fast; it did
            -- not make it sane -- the densest subject here carries 6,687 edges, and
            -- rendering 6,687 surfaces into one prose line is not an answer. The
            -- cap is a per-band query LIMIT over an consensus.eff_mu ranking (rn <= 12), the
            -- only kind of top-k the substrate permits: it truncates the READ, not
            -- the fold, and nothing about what the sources assert changes.
            ranked AS MATERIALIZED (
                SELECT band, nid, m,
                       row_number() OVER (PARTITION BY band ORDER BY m DESC, nid) AS rn
                FROM edges
            ),
            ord AS MATERIALIZED (
                SELECT band, nid, m,
                       row_number() OVER (ORDER BY band, m DESC, nid) AS ix
                FROM ranked
                WHERE rn <= 12
            ),
            lbl AS MATERIALIZED (
                SELECT realize.batch(array_agg(o.nid ORDER BY o.ix), lang) AS l
                FROM ord o
            )
            SELECT string_agg(q.line, ' ') INTO out FROM (
                SELECT converse.chat_scaffold(
                           lang, 'band', xl,
                           string_agg(lbl.l[o.ix], ', ' ORDER BY o.m DESC),
                           b.name) AS line,
                       b.band
                FROM ord o
                JOIN converse.relation_band_catalog() b ON b.band = o.band
                CROSS JOIN lbl
                WHERE lbl.l[o.ix] IS NOT NULL
                GROUP BY b.band, b.name
                ORDER BY b.band
            ) q;
            IF out IS NULL OR out = '' THEN
                out := converse.chat_scaffold(lang, 'no_edges', xl);
            END IF;

        ELSIF shape = 'reason' AND topic2 IS NOT NULL THEN
            SELECT string_agg(reply, ' ') INTO out
              FROM converse.recall_relation_summary_response(topic, topic2);

        ELSIF shape IN ('related','related_in') AND p_type_name IS NOT NULL THEN
            SELECT string_agg(reply, ' ') INTO out
              FROM converse.recall_intent(shape, topic, NULL, p_type_name);
            IF out IS NULL OR out = '' THEN
                out := converse.chat_scaffold(lang, 'no_type', xl, NULL, p_type_name);
            END IF;

        ELSIF shape IS NOT NULL AND shape NOT IN ('describe','fallback','walk','what_is') THEN
            -- Any other published shape answers through the shared responder family.
            SELECT string_agg(reply, ' ') INTO out
              FROM converse.recall_intent(shape, topic, topic2, p_type_name);

        ELSIF shape IS NULL THEN
            -- The default speaking path is the canonical dynamic pass. Every
            -- prompt constituent and its witnessed sense enters a native
            -- both-direction hop/fan-out route; exact trajectories propose;
            -- rated consensus steers; each selected constituent advances the
            -- live frontier before the next proposal. Static recall/templates
            -- remain explicit named shapes only.
            SELECT array_agg(st.topic_id ORDER BY st.last_ord DESC) INTO ctx_arr
              FROM converse.session_trajectory(p_session, 8) st;
            SELECT string_agg(g.entity, '' ORDER BY g.step) INTO out
              FROM generation.forward_text(
                    p_prompt, 40, 5, 0.6, 10,
                    hashtextextended(COALESCE(p_session::text, '') || p_prompt, 0),
                    2, 8, ctx_arr) g;

        ELSIF shape = 'walk' THEN
            -- Phase 2 wiring (#751, after PR #884): converse_compose is the
            -- steered lane -- sequence proposes, the turn's semantic frontier
            -- steers, and since #884 the seed picks the entry into the core
            -- backbone, so it recombines instead of replaying. It realizes
            -- LAST, honoring p_lang, which converse_walk cannot (no lang on
            -- its signature -- the measured cross-language splice).
            --
            -- SEED: session-derived, never NULL. Session id + prompt hashed
            -- with the session's topic-turn count as the hash seed: asking
            -- again in the same session moves the walk; the same first ask in
            -- a fresh session is reproducible.
            --
            -- FALLBACK: compose returns NULL when the topic yields no stream
            -- (n < 3) or no starts -- the unsteered walker still answers
            -- there, and empty output falls through to the shared prose
            -- fallback below either way.
            --
            -- NO TIMEOUT GUARD, deliberately. A SET LOCAL budget needs an
            -- exception handler to degrade, and PostgreSQL reports a
            -- statement_timeout and a client cancel with the same condition
            -- (query_canceled / 57014) -- a handler that catches our budget
            -- also eats the caller's Ctrl-C and makes converse.chat() un-cancellable
            -- for the duration. A caller naming `walk` is asking for the
            -- generator and can bound it with their own statement_timeout.
            -- max(ord) is the turn counter session_record_prompt maintains:
            -- PK-indexed, no full per-session count, no bigint->int narrowing.
            SELECT COALESCE(max(t.ord), 0) INTO depth FROM converse.session_topics t
              WHERE t.session_id = p_session;
            -- BIOGRAPHY (R7 slice 2): recent session topics ride into the
            -- compose frontier with recency decay — the turn's own topic is
            -- already the frontier seed, so it is excluded here. Most-recent
            -- first: session_trajectory's order IS the decay ordinality.
            -- No session (or no history) passes NULL, which composes exactly
            -- as a fresh turn.
            SELECT array_agg(st.topic_id ORDER BY st.last_ord DESC) INTO ctx_arr
              FROM converse.session_trajectory(p_session, 4) st
             WHERE st.topic_id <> topic;
            out := converse.compose(
                p_prompt, 40, lang,
                hashtextextended(COALESCE(p_session::text, '') || p_prompt,
                                 COALESCE(depth, 0)),
                ctx_arr);
            IF out IS NULL OR out = '' THEN
                out := converse.walk(p_prompt, 40, NULL);
            END IF;

        ELSE
            -- describe / what_is / fallback and the no-shape default.
            -- (`walk` has its own branch above.)
            --
            -- SENTENCE-TIER COMPOSITION FIRST. converse_about's template prose
            -- is the S9 FALLBACK (spec 36) and must never be the success path;
            -- it also mangles clause-shaped glosses, since "X is " || gloss
            -- yields "Pawn is it can be promoted to a more powerful piece if it
            -- reaches the 8th rank." (observed live 2026-07-26).
            --
            -- converse.tiered() is NOT called from the hot path. Measured
            -- 2026-08-05 (GH #878): the 2026-07-27 hangs are FIXED (ceef97d
            -- landed; dog 3.7s, pawn 1.4s), but content REGRESSED to a
            -- degenerate topic echo ("dog. dog. dog. dog." — including pawn,
            -- its one historically verified topic). Its former temp-table
            -- implementation has since been replaced by PL/pgSQL arrays and is
            -- read-only-safe; content quality, not transaction mode, is why it
            -- remains off this hot path.
            --
            -- converse_about is the pre-existing path and is fast and correct-ish
            -- ("Dog is a member of the genus Canis (probably descended from the
            -- common wolf)..."), so it carries the describe shape until the
            -- sentence-tier composer is fast enough to sit in front of it.
            out := CASE WHEN xl IS NOT NULL THEN converse.about(topic, lang)
                        ELSE converse.converse(p_prompt) END;
        END IF;

        IF (out IS NULL OR out = '') AND shape IS NOT NULL THEN
            out := CASE WHEN xl IS NOT NULL THEN converse.about(topic, lang)
                        ELSE converse.converse(p_prompt) END;
        END IF;
    END IF;

    -- An empty dynamic pass is an absence of an admissible continuation, not a
    -- request to resurrect the retired static/template success path. Keep the
    -- dynamic route authoritative and make its WHY-NOT visible instead of
    -- returning NULL/empty text. `xl` is the one elected-topic realization
    -- already computed above. If it is NULL, do not perform a second scalar
    -- realization, do not leak the canonical hash, and let the scaffold emit the
    -- explicit topic-neutral abstention for this forward pass.
    IF (out IS NULL OR btrim(out) = '') AND shape IS NULL THEN
        out := converse.chat_scaffold(lang, 'no_forward', xl);
    END IF;

    -- RECORD session carry; the OODA close (turn witnessing) is the caller's duty.
    IF p_session IS NOT NULL THEN
        PERFORM generation.session_record_prompt(p_session, p_prompt, resolved);
    END IF;

    RETURN btrim(out);
END;
$$;
-- session_trajectory: the session's discourse biography as a first-class read
-- (R7 / GH #759, slot map: "Attention over context" — the context window is
-- biography, not one carried topic id).
--
-- Provenance-scoped by construction: rows come only from THIS session's
-- session_topics (the turn ladder — ord is the turn ordinal within the
-- session; user/tenant scoping arrives when those identifiers exist, #791).
-- Distinct resolved topics, most recent first, each carrying the evidence a
-- discourse read ranks by: how often the session returned to the topic
-- (mentions) and when it last did (last_ord). The PK (session_id, ord) makes
-- this an indexed scan of one session's rows — no cross-session read exists
-- here at all.
--
-- Deliberately NOT a ranking. Recency-primary and evidence-primary disagree
-- about real discourse ("a digression then 'anyway...'"), so this surface
-- returns the trajectory and the CALLER declares the ordering its read needs
-- — converse.chat()'s carry ranks by consensus adjacency to the current turn first,
-- falling back to recency, which keeps session_last_resolved's semantics as
-- the zero-evidence case.
DROP FUNCTION IF EXISTS laplace.session_trajectory(bytea, int);
CREATE OR REPLACE FUNCTION converse.session_trajectory(p_session bytea, p_k int DEFAULT 8)
    RETURNS TABLE(topic_id bytea, last_ord int, mentions bigint)
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    SELECT t.resolved_id, max(t.ord), count(*)
    FROM converse.session_topics t
    WHERE t.session_id = p_session AND t.resolved_id IS NOT NULL
    GROUP BY t.resolved_id
    ORDER BY max(t.ord) DESC
    LIMIT p_k
$$;
DROP FUNCTION IF EXISTS laplace.recall_session(text, bytea);
CREATE OR REPLACE FUNCTION converse.recall_session(p_prompt text, p_session bytea DEFAULT NULL)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE C VOLATILE
    AS 'laplace_substrate', 'pg_laplace_recall_session';
-- session_turns: exact prior-turn recall FROM THE SESSION TRAJECTORY (spec 34
-- acceptance: "Exact prior-turn recall comes from the session trajectory") — the
-- geometric read the agent-trace lane finally makes possible. The session entity's
-- Content physicality holds the ordered, versioned turn manifest; this realizes it
-- back: ordinal, turn id, role and model (via the HAS_ROLE / AUTHORED_BY consensus
-- edges, names resolved through IS_INSTANCE_OF), the turn's witnessed EVENT time
-- (APPEARS_IN evidence under this session's context — the log's clock, not ingest
-- time), and the realized surface.
--
-- Unlike converse.session_trajectory (a topic-cache projection, explicitly an
-- invalidatable accelerator), this reads the substrate's own order authority. A
-- session with no deposited trajectory returns zero rows — absence is unknown,
-- never an empty fabrication.
--
-- RANK THEN LABEL (ISA gate G2, Rule #3): ids are selected and LIMITed first, then
-- resolved through exactly two realize.render_batch calls — one positionally aligned
-- to the surviving turns, one over the DISTINCT role/model name ids (a handful of
-- entities across any session). No per-row scalar realization anywhere.
--
-- Validated against real agent-log sessions in a laplace_d_agents isolate
-- (claude-code / codex / antigravity / copilot / cursor / gemini corpora);
-- regress coverage rides the next extension install (the isolate cannot install a
-- branch extension over the shared cluster's copy).
DROP FUNCTION IF EXISTS converse.session_turns(bytea, int);
CREATE OR REPLACE FUNCTION converse.session_turns(p_session bytea, p_limit int DEFAULT NULL)
    RETURNS TABLE(ordinal int, turn_id bytea, role text, model text,
                  observed_at timestamptz, surface text)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
WITH traj AS MATERIALIZED (
    SELECT t.ordinal + rs.i - 1 AS ordinal, t.entity_id AS turn_id
    FROM laplace.physicalities p
    CROSS JOIN LATERAL public.laplace_trajectory_constituents(p.trajectory) t
    CROSS JOIN LATERAL generate_series(1, GREATEST(t.run_length, 1)) rs(i)
    WHERE p.entity_id = p_session AND p.type = 1
    ORDER BY t.ordinal
    LIMIT COALESCE(p_limit, 2147483647)
), picked AS MATERIALIZED (
    SELECT tr.ordinal,
           tr.turn_id,
           row_number() OVER (ORDER BY tr.ordinal) AS rn,
           (SELECT n.object_id
              FROM laplace.consensus r
              JOIN laplace.consensus n
                ON n.subject_id = r.object_id
               AND n.type_id = realize.canonical_id('IS_INSTANCE_OF')
             WHERE r.subject_id = tr.turn_id
               AND r.type_id = realize.canonical_id('HAS_ROLE')
             ORDER BY consensus.eff_mu(r.rating, r.rd) DESC,
                      consensus.eff_mu(n.rating, n.rd) DESC
             LIMIT 1) AS role_name_id,
           (SELECT n.object_id
              FROM laplace.consensus r
              JOIN laplace.consensus n
                ON n.subject_id = r.object_id
               AND n.type_id = realize.canonical_id('IS_INSTANCE_OF')
             WHERE r.subject_id = tr.turn_id
               AND r.type_id = realize.canonical_id('AUTHORED_BY')
             ORDER BY consensus.eff_mu(r.rating, r.rd) DESC,
                      consensus.eff_mu(n.rating, n.rd) DESC
             LIMIT 1) AS model_name_id,
           (SELECT max(a.last_observed_at)
              FROM laplace.attestations a
             WHERE a.subject_id = tr.turn_id
               AND a.context_id = p_session
               AND a.type_id = realize.canonical_id('APPEARS_IN')) AS observed_at
    FROM traj tr
), surfaces AS MATERIALIZED (
    SELECT s.pos, s.txt
    FROM (SELECT array_agg(pk.turn_id ORDER BY pk.rn) AS ids FROM picked pk) a
    CROSS JOIN LATERAL unnest(realize.render_batch(a.ids))
        WITH ORDINALITY AS s(txt, pos)
), names AS MATERIALIZED (
    SELECT n.id, n.txt
    FROM (
        SELECT array_agg(DISTINCT u.id) AS ids
        FROM (SELECT pk.role_name_id AS id FROM picked pk WHERE pk.role_name_id IS NOT NULL
              UNION
              SELECT pk.model_name_id FROM picked pk WHERE pk.model_name_id IS NOT NULL) u
    ) a
    CROSS JOIN LATERAL unnest(a.ids, realize.render_batch(a.ids)) AS n(id, txt)
)
SELECT pk.ordinal,
       pk.turn_id,
       rn_role.txt,
       rn_model.txt,
       pk.observed_at,
       sf.txt
FROM picked pk
LEFT JOIN surfaces sf ON sf.pos = pk.rn
LEFT JOIN names rn_role ON rn_role.id = pk.role_name_id
LEFT JOIN names rn_model ON rn_model.id = pk.model_name_id
ORDER BY pk.ordinal;
END;
-- Shape axis: Frechet over REALIZED curves (entity_curve), never packed
-- laplace.physicalities.trajectory (Rule #3 / Issue 51).
-- structural.neighbors — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace.structural_neighbors(text, integer);
CREATE OR REPLACE FUNCTION structural.neighbors(p_word text, p_k integer DEFAULT 10)
    RETURNS TABLE(neighbor text, geodesic double precision, frechet double precision)
    LANGUAGE plpgsql STABLE AS $sn$
DECLARE
    v_id    bytea;
    v_coord geometry;
    v_curve geometry;
BEGIN
    SELECT w.id, w.coord, structural.entity_curve(w.id)
      INTO v_id, v_coord, v_curve
    FROM laplace.v_word_points w
    JOIN converse.prompt_state(p_word) s ON w.id = s.id
    WHERE w.coord IS NOT NULL
    ORDER BY s.ord, w.physicality_id
    LIMIT 1;
    IF v_id IS NULL OR public.laplace_direction_4d(v_coord) IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH nearest AS (
        SELECT w.id AS entity_id, w.coord,
               public.laplace_angular_distance_4d(w.coord, v_coord) AS geo
        FROM laplace.v_word_points w
        WHERE w.id <> v_id
          AND public.laplace_direction_4d(w.coord) IS NOT NULL
        ORDER BY public.laplace_direction_4d(w.coord)
                 <<->> public.laplace_direction_4d(v_coord)
        LIMIT p_k),
    -- Resolve via the full mesh in ONE realize_batch over the <= p_k survivors
    -- (was: scalar realize per neighbour). Hubs surface as their real word;
    -- only truly unlabelable nodes drop (abstention, no hex here by design).
    ordered AS (
        SELECT t.*, row_number() OVER (ORDER BY t.geo) AS ord
        FROM nearest t
    ),
    curves AS (
        SELECT o.entity_id, o.geo, o.ord, structural.entity_curve(o.entity_id) AS curve
        FROM ordered o
    ),
    labels AS (
        SELECT realize.batch(array_agg(c.entity_id ORDER BY c.ord)) AS l
        FROM curves c
    )
    SELECT r.lbl, r.geo, r.frechet FROM (
        SELECT labels.l[c.ord] AS lbl, c.geo, c.ord,
               CASE WHEN c.curve IS NOT NULL AND v_curve IS NOT NULL
                    THEN public.laplace_frechet_4d(c.curve, v_curve) END AS frechet
        FROM curves c, labels
    ) r
    WHERE r.lbl IS NOT NULL AND r.lbl <> ''
    ORDER BY r.ord;
END;
$sn$;
-- Entity-id keyed structural KNN with S³ coords (explore glome overlay).
-- Unlike structural.neighbors(text), does not re-resolve via prompt_state.
--
-- Shape axis: Frechet over REALIZED curves (entity_curve), never packed
-- laplace.physicalities.trajectory (Rule #3 / Issue 51).
-- GH #862 / #860: structural.neighbors_of, no SET, real schema names.
DROP FUNCTION IF EXISTS laplace.structural_neighbors_of(bytea, integer);
CREATE OR REPLACE FUNCTION structural.neighbors_of(
    p_id bytea,
    p_k  integer DEFAULT 10)
    RETURNS TABLE(
        neighbor_id bytea,
        neighbor    text,
        x           double precision,
        y           double precision,
        z           double precision,
        m           double precision,
        radius      double precision,
        geodesic    double precision,
        frechet     double precision)
    LANGUAGE plpgsql STABLE
    AS $sn$
DECLARE
    v_coord geometry;
    v_curve geometry;
BEGIN
    SELECT a.coord, structural.entity_curve(p_id)
      INTO v_coord, v_curve
    FROM structural.word_anchor(p_id) a;
    IF v_coord IS NULL OR public.laplace_direction_4d(v_coord) IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH nearest AS (
        SELECT w.id AS entity_id, w.coord, w.radius_origin,
               public.laplace_angular_distance_4d(w.coord, v_coord) AS geo
        FROM laplace.v_word_points w
        WHERE w.id <> p_id
          AND public.laplace_direction_4d(w.coord) IS NOT NULL
        ORDER BY public.laplace_direction_4d(w.coord)
                 <<->> public.laplace_direction_4d(v_coord)
        LIMIT p_k),
    ordered AS (
        SELECT n.*, row_number() OVER (ORDER BY n.geo) AS ord
        FROM nearest n
    ),
    curves AS (
        -- Cache realized curves once per survivor (never rebuild inside Frechet).
        SELECT o.entity_id, o.coord, o.radius_origin, o.geo, o.ord,
               structural.entity_curve(o.entity_id) AS curve
        FROM ordered o
    ),
    labels AS (
        -- Full-mesh resolution via ONE realize_batch over the <= p_k survivors
        -- (was: scalar realize per neighbour): synset/ILI hubs resolve through
        -- the name/synset-lemma/translation arms to the real word. Unresolved
        -- identities receive an honest marker rather than fabricated content.
        SELECT realize.batch(array_agg(c.entity_id ORDER BY c.ord)) AS l
        FROM curves c
    )
    SELECT c.entity_id,
           COALESCE(NULLIF(labels.l[c.ord], ''), 'Unrealized entity'),
           ST_X(c.coord), ST_Y(c.coord), ST_Z(c.coord), ST_M(c.coord),
           c.radius_origin,
           c.geo,
           CASE WHEN c.curve IS NOT NULL AND v_curve IS NOT NULL
                THEN public.laplace_frechet_4d(c.curve, v_curve) END
    FROM curves c, labels
    ORDER BY c.ord;
END;
$sn$;
-- structural.locale — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace.structural_locale(text, double precision);
CREATE OR REPLACE FUNCTION structural.locale(p_word text, p_near double precision DEFAULT 0.05)
    RETURNS TABLE(nearest double precision, within_near bigint,
                  within_2x bigint, within_5x bigint, isolated boolean)
    LANGUAGE plpgsql STABLE AS $sl$
DECLARE
    v_id        bytea;
    v_coord     geometry;
    v_direction geometry;
    v_nearest   double precision;
    v_max_angle double precision;
    v_chord     double precision;
BEGIN
    IF p_near < 0 THEN
        RAISE EXCEPTION 'structural.locale: p_near must be non-negative (got %)', p_near
            USING ERRCODE = '22023';
    END IF;

    SELECT w.id, w.coord INTO v_id, v_coord
    FROM laplace.v_word_points w
    JOIN converse.prompt_state(p_word) s ON w.id = s.id
    WHERE w.coord IS NOT NULL
    ORDER BY s.ord, w.physicality_id
    LIMIT 1;
    IF v_id IS NULL THEN RETURN; END IF;

    v_direction := public.laplace_direction_4d(v_coord);
    IF v_direction IS NULL THEN RETURN; END IF;
    v_max_angle := LEAST(pi(), 5 * p_near);
    -- On S3, unit chord = sqrt(2 - 2*cos(angle)). The direction GiST can
    -- reject everything outside this exact angular radius with an n-D box;
    -- laplace_angular_distance_4d below removes the box's corner false positives.
    v_chord := sqrt(GREATEST(0, 2 - 2 * cos(v_max_angle)));

    -- Exact nearest neighbour: unit-chord order is strictly monotone with angle.
    -- No fixed prefix is involved, and excluding entity_id removes all duplicate
    -- physical realizations of the anchor before LIMIT.
    SELECT public.laplace_angular_distance_4d(p.coord, v_coord)
      INTO v_nearest
    FROM laplace.physicalities p
    WHERE p.type = 1
      AND p.entity_id <> v_id
      AND public.laplace_direction_4d(p.coord) IS NOT NULL
    ORDER BY public.laplace_direction_4d(p.coord) <<->> v_direction,
             p.entity_id, p.id
    LIMIT 1;

    RETURN QUERY
    WITH within_max AS MATERIALIZED (
        SELECT p.entity_id,
               min(public.laplace_angular_distance_4d(p.coord, v_coord)) AS d
        FROM laplace.physicalities p
        WHERE p.type = 1
          AND p.entity_id <> v_id
          AND public.laplace_direction_4d(p.coord) IS NOT NULL
          AND public.laplace_direction_4d(p.coord) &&&
              public.ST_Expand(v_direction, v_chord, v_chord, v_chord, v_chord)
          AND public.laplace_angular_distance_4d(p.coord, v_coord) <= v_max_angle
        GROUP BY p.entity_id)
    SELECT v_nearest,
           count(*) FILTER (WHERE d <= p_near),
           count(*) FILTER (WHERE d <= 2 * p_near),
           count(*) FILTER (WHERE d <= 5 * p_near),
           COALESCE(v_nearest > p_near, true)
    FROM within_max;
END;
$sl$;
-- Every witnessed edge of a word, ranked by the salience-weighted readout.
--
-- RELATION LABELS RESOLVE PER DISTINCT TYPE, NOT PER ROW — a correctness/shape
-- fix, NOT a speedup. Be clear about that, because the first version of this
-- comment claimed a speedup it does not deliver.
--
-- A relation type comes from a governed vocabulary of ~189, so one subject's
-- edges span a handful — eight on `Self_motion`, the densest word in the
-- substrate (6,687 edges). Calling realize.label() per ROW asked the same question 836
-- times over on average. Fencing the distinct types turns 6,687 calls into 8, and
-- the plan confirms it: `CTE rel` executes in 4.9 ms for 8 rows.
--
-- IT DID NOT MAKE converse.links() FASTER. Measured 2026-07-28, three runs each:
--   before  140.9 s
--   after   147.0 / 148.4 / 146.7 s
--
-- The reason is a mis-measurement worth recording. Timing each arm ALONE gave
-- realize.label(type_id) 75.9 s and realize.label(object_id) 42.3 s, which looks additive against
-- a 140.9 s total. It is not: both arms call resolve_name, which reads the same
-- consensus pages, so whichever ran second found them warm. Removing the type arm
-- freed almost no I/O — the object arm still faults the same pages in. Per-arm
-- timings taken in isolation cannot be attributed to a combined query.
--
-- What the plan actually shows: 88.7 M shared buffer hits, essentially all of it
-- in the projection, i.e. realize.label(object_id) at ~22 ms and ~13 k buffers PER CALL.
-- Those 6,686 ids are nearly all distinct, so deduping cannot help — that arm
-- needs a BATCHED label, which does not exist. realize.batch() is batched but is a
-- DIFFERENT ladder: it abstains with NULL where realize.label() falls back to a cleaned
-- realize.render and finally to hex, so substituting it changes what every caller
-- receives. A label_batch() in C beside realize_batch is the real fix and is not
-- in this change.
--
-- Semantics here are unchanged by construction: same function, same argument,
-- same COALESCE(NULLIF(consensus.relation_canonical, ''), label) ladder. Only the number of
-- evaluations changes.
DROP FUNCTION IF EXISTS laplace.links(text);
CREATE OR REPLACE FUNCTION converse.links(p_word text)
    RETURNS TABLE(relation text, target text, strength double precision)
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
    WITH base AS MATERIALIZED (
        SELECT c.type_id, c.object_id,
               consensus.eff_mu(c.rating, c.rd) AS emu
        FROM laplace.consensus c
        WHERE c.subject_id = laplace.word_id(p_word)
    ),
    ids AS MATERIALIZED (
        SELECT COALESCE(array_agg(DISTINCT x.id ORDER BY x.id), '{}'::bytea[]) AS a
        FROM (SELECT type_id AS id FROM base UNION SELECT object_id FROM base) x
    ), labels AS MATERIALIZED (
        SELECT i.id, i.txt
        FROM ids b,
             LATERAL ROWS FROM (
                 unnest(b.a), unnest(realize.label_batch(b.a))
             ) AS i(id, txt)
    ), rel AS MATERIALIZED (
        SELECT t.type_id,
               COALESCE(NULLIF(consensus.relation_canonical(t.type_id), ''), l.txt) AS relation
        FROM (SELECT DISTINCT b.type_id FROM base b) t
        JOIN labels l ON l.id = t.type_id
    )
    SELECT r.relation,
           l.txt AS target,
           (b.emu)::float8 / 1e9 AS strength
    FROM base b
    JOIN rel r ON r.type_id = b.type_id
    JOIN labels l ON l.id = b.object_id
    ORDER BY consensus.edge_rank(b.type_id, b.emu) DESC,
             strength DESC, r.relation
$$;
DROP FUNCTION IF EXISTS laplace.attention(bytea, int);
CREATE OR REPLACE FUNCTION converse.attention(p_word bytea, p_k int DEFAULT 12)
    RETURNS TABLE(neighbor text, relation text, attention double precision,
                  geodesic double precision)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    WITH qcoord AS (
        SELECT coord FROM laplace.v_word_points WHERE id = p_word LIMIT 1),
    edges AS (
        SELECT c.object_id AS nb, c.type_id, consensus.eff_mu(c.rating, c.rd) AS mu
        FROM laplace.consensus c
        WHERE c.subject_id = p_word AND c.object_id IS NOT NULL
          AND c.type_id NOT IN (laplace.relation_type_id('HAS_LANGUAGE'),
                                laplace.relation_type_id('HAS_SENSE'), laplace.relation_type_id('IS_SENSE_OF'),
                                laplace.relation_type_id('PRECEDES'), laplace.relation_type_id('FOLLOWS'),
                                laplace.relation_type_id('HAS_POS'), laplace.relation_type_id('HAS_XPOS'),
                                laplace.relation_type_id('HAS_FEATURE'), laplace.relation_type_id('HAS_LEX_CATEGORY'),
                                laplace.relation_type_id('HAS_NAME_ALIAS'), laplace.relation_type_id('IS_LEMMA_OF'),
                                laplace.relation_type_id('HAS_LANGUAGE_SCOPE'), laplace.relation_type_id('HAS_LANGUAGE_TYPE'))
        UNION ALL
        SELECT sm.member, laplace.relation_type_id('IS_SYNONYM_OF'), sm.mu
        FROM lexical.synset_members(p_word) sm
    ),
    best AS (
        SELECT nb, (array_agg(type_id ORDER BY mu DESC))[1] AS type_id, max(mu) AS mu
        FROM edges WHERE nb <> p_word GROUP BY nb)
    SELECT l.txt AS neighbor, lexical.type_label(r.type_id) AS relation,
           r.attention, r.geodesic
    FROM (
        SELECT b.nb, b.type_id, (b.mu::double precision / 1e9) AS attention,
               CASE WHEN qc.coord IS NOT NULL AND w.coord IS NOT NULL
                    THEN laplace_angular_distance_4d(w.coord, qc.coord) END AS geodesic
        FROM best b
        LEFT JOIN laplace.v_word_points w ON w.id = b.nb
        CROSS JOIN qcoord qc
        ORDER BY attention DESC NULLS LAST, geodesic NULLS LAST
    ) r
    CROSS JOIN LATERAL (SELECT realize.label(r.nb) AS txt) l
    WHERE NULLIF(btrim(l.txt), '') IS NOT NULL
    LIMIT p_k
$$;
-- converse.correlate — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace.correlate(text[]);
CREATE OR REPLACE FUNCTION converse.correlate(p_words text[])
    RETURNS TABLE(relation text, target text, words text[], strength double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Group on ids, not rendered strings: content-addressing means one id = one
    -- content, but one surface string can cover many ids (homographs), so the
    -- old GROUP BY realize.label(type)/realize.label(object) both conflated distinct targets
    -- that happen to share a surface AND rendered a label for every consensus
    -- edge of every input word. Aggregate per (type_id, object_id), then realize.render
    -- exactly once per output row at the boundary.
    WITH v AS (SELECT w AS word, laplace.word_id(w) AS id
               FROM unnest(p_words) AS w WHERE laplace.word_id(w) IS NOT NULL),
    g AS MATERIALIZED (
        SELECT c.type_id, c.object_id,
               array_agg(DISTINCT v.word ORDER BY v.word) AS words,
               count(DISTINCT v.word) AS nwords,
               (max(consensus.eff_mu(c.rating, c.rd)))::float8 / 1e9 AS strength
        FROM v JOIN laplace.consensus c ON c.subject_id = v.id
        GROUP BY c.type_id, c.object_id),
    ids AS MATERIALIZED (
      SELECT array_agg(DISTINCT id ORDER BY id) AS a
      FROM (SELECT type_id AS id FROM g UNION SELECT object_id FROM g) x
    ), labels AS MATERIALIZED (
      SELECT i.id, i.txt FROM ids,
        LATERAL ROWS FROM (
          unnest(ids.a), unnest(realize.label_batch(ids.a))
        ) i(id,txt)
    )
    SELECT COALESCE(NULLIF(consensus.relation_canonical(g.type_id), ''), rt.txt) AS relation,
           ro.txt AS target, g.words, g.strength
    FROM g JOIN labels rt ON rt.id=g.type_id JOIN labels ro ON ro.id=g.object_id
    ORDER BY g.nwords DESC, g.strength DESC, 1
$$;
