DROP FUNCTION IF EXISTS laplace.astar_path(bytea, bytea[], int, bytea[], bool, bool);
CREATE OR REPLACE FUNCTION converse.astar_path(
    p_start bytea, p_goals bytea[], p_max_depth int DEFAULT NULL,
    p_types bytea[] DEFAULT NULL, p_directed bool DEFAULT false,
    p_use_geometry bool DEFAULT false)
    RETURNS TABLE(step int, entity_id bytea, g double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Default traversal vocabulary is DECLARED: engine/manifest/relation_types.toml
    -- [[set]] PATH_TRAVERSABLE (= PATH_UPWARD u PATH_LATERAL), emitted IMMUTABLE by
    -- codegen so the array folds at plan time. These 13 names were hand-listed here AND
    -- in consensus.relate_path's two arms -- one walk vocabulary, spelled twice, in two
    -- files, with nothing keeping them in step.
    SELECT * FROM converse.astar_path_raw(p_start, p_goals,
        COALESCE(p_types, consensus.relation_set_ids('PATH_TRAVERSABLE')),
        p_max_depth, p_directed, p_use_geometry)
$$;
DROP FUNCTION IF EXISTS laplace.cascade(text, text, int);
CREATE OR REPLACE FUNCTION converse.cascade(p_x text, p_y text, p_max_depth int DEFAULT NULL)
    RETURNS TABLE(chain text, cost double precision)
    LANGUAGE C STABLE STRICT PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_cascade';
DROP FUNCTION IF EXISTS laplace.word_curve(bytea);
CREATE OR REPLACE FUNCTION structural.word_curve(p_word bytea) RETURNS geometry
    LANGUAGE sql STABLE AS $$
    SELECT public.ST_MakeLine(p.coord ORDER BY c.ordinal)
    FROM realize.constituents(p_word) c
    JOIN laplace.physicalities p
      ON p.entity_id = c.child_id AND p.type = 1 AND p.coord IS NOT NULL
$$;
DROP FUNCTION IF EXISTS laplace.word_shape_distance(text, text);
CREATE OR REPLACE FUNCTION structural.word_shape_distance(p_a text, p_b text) RETURNS double precision
    LANGUAGE sql STABLE
 AS $$
    SELECT public.laplace_frechet_4d(structural.word_curve(laplace.word_id(p_a)), structural.word_curve(laplace.word_id(p_b)))
$$;
DROP FUNCTION IF EXISTS laplace.anagrams_of(text);
CREATE OR REPLACE FUNCTION structural.anagrams_of(p_word text)
    RETURNS TABLE(word text, entity_id bytea)
    LANGUAGE sql STABLE
 AS $$
    WITH raw AS MATERIALIZED (
        SELECT DISTINCT w2.id AS entity_id
        FROM laplace.v_word_points w1
        JOIN laplace.v_word_points w2 ON w2.hilbert_index = w1.hilbert_index
        WHERE w1.id = laplace.word_id(p_word)
          AND w2.type_id = realize.canonical_id('Word')
          AND w2.id <> w1.id
    ), numbered AS MATERIALIZED (
      SELECT d.*, row_number() OVER (ORDER BY d.entity_id) AS rn FROM raw d
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(entity_id ORDER BY rn)) AS labels FROM numbered
    )
    SELECT b.labels[d.rn], d.entity_id FROM numbered d CROSS JOIN batch b ORDER BY d.rn
$$;
-- The reverse of realize.constituents(): given an entity, walk UP the composition
-- hierarchy and return every higher-tier entity whose trajectory contains it
-- (directly at hop=1, or transitively through intermediate tiers at hop>1),
-- e.g. structural.containers_of(laplace.word_id('chess'), 2) returns the sentences containing
-- "chess" (hop 1) and the documents containing those sentences (hop 2).
--
-- Native C owns frontier expansion and deduplication. Each hop uses one fixed
-- typed overlap query over the complete frontier. The caller's result bound is
-- passed into that query. Its retained plan avoids repeated partition planning.
DROP FUNCTION IF EXISTS laplace.containers_of(bytea, int, int);
CREATE OR REPLACE FUNCTION structural.containers_of(
    p_entity   bytea,
    p_max_hops int   DEFAULT 1,
    p_limit    int   DEFAULT 1000)
    RETURNS TABLE(entity_id bytea, tier smallint, type_id bytea, hops int)
    AS 'laplace_substrate', 'pg_laplace_containers_of'
    LANGUAGE C STABLE;

-- Set containment is a different operation from frontier expansion.  Given
-- multiple identities, return compositions whose one witnessed trajectory
-- contains every identity.  This preserves the composition hop: `Captain` and
-- `Ahab` remain constituents of the returned sentence; this function does not
-- fabricate a direct semantic edge between them.
DROP FUNCTION IF EXISTS laplace.containers_containing_all(bytea[]);
CREATE OR REPLACE FUNCTION structural.containers_containing_all(p_members bytea[])
    RETURNS TABLE(entity_id bytea)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT DISTINCT ON (p.entity_id) p.entity_id
    FROM laplace.physicalities p
    WHERE cardinality(p_members) > 0
      AND p.type = 1
      AND p.trajectory IS NOT NULL
      AND public.laplace_trajectory_constituent_ids(p.trajectory) @> p_members
    ORDER BY p.entity_id, p.id;
END;

-- Browser/name discovery reuses the exact same indexed trajectory law over the
-- word-point surface, but accepts the decomposer's word identities as input.
-- They are lowered here to the tier-0 constituent floor using the canonical
-- closure/facet operators; no UI tokenizer and no English-only character logic.
DROP FUNCTION IF EXISTS structural.word_containers_containing_all(bytea[], int);
CREATE OR REPLACE FUNCTION structural.word_containers_containing_all(
    p_members bytea[],
    p_capacity int DEFAULT 2048)
    RETURNS TABLE(entity_id bytea, candidate_count bigint, truncated boolean)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH closure AS MATERIALIZED (
        SELECT DISTINCT c.child_id AS id
        FROM realize.constituents_closure(COALESCE(p_members, '{}'::bytea[]), 0) c
        UNION
        SELECT DISTINCT x.id
        FROM unnest(COALESCE(p_members, '{}'::bytea[])) AS x(id)
    ), closure_ids AS MATERIALIZED (
        SELECT COALESCE(array_agg(c.id ORDER BY c.id), '{}'::bytea[]) AS ids
        FROM closure c
    ), floor_ids AS MATERIALIZED (
        SELECT COALESCE(array_agg(f.entity_id ORDER BY f.entity_id), '{}'::bytea[]) AS ids
        FROM closure_ids x, ops.entity_facets_batch(x.ids) f
        WHERE f.tier = 0
    ), bounded AS MATERIALIZED (
        SELECT w.id
        FROM floor_ids f
        JOIN laplace.v_word_points w
          ON cardinality(f.ids) > 0
         AND w.trajectory IS NOT NULL
         AND public.laplace_trajectory_constituent_ids(w.trajectory) @> f.ids
        ORDER BY w.id
        LIMIT GREATEST(COALESCE(p_capacity, 0), 0) + 1
    ), stats AS MATERIALIZED (
        SELECT LEAST(count(*), GREATEST(COALESCE(p_capacity, 0), 0))::bigint AS n,
               count(*) > GREATEST(COALESCE(p_capacity, 0), 0) AS clipped
        FROM bounded
    )
    SELECT b.id, s.n, s.clipped
    FROM bounded b CROSS JOIN stats s
    ORDER BY b.id
    LIMIT GREATEST(COALESCE(p_capacity, 0), 0);
END;
-- Retire the short-lived structural Browse alias. The reusable Browse operation is
-- consensus.browse_named_entities(...), which owns the name-family/standing fold and
-- calls the sanctioned structural containment operator internally. Keeping a second
-- SQL wrapper here made extension installation order semantically significant because
-- this manifest entry precedes consensus/edges.sql.in on both fresh install and upgrade.
-- Product callers use the canonical consensus operation directly instead.
DROP FUNCTION IF EXISTS structural.browse_named_entities(bytea[], bytea, int, int, int);
-- The geometry-native continuation operator: for a content point, the next (or
-- previous) CONTENT constituent in every trajectory that contains it, aggregated
-- by frequency. Reads the ordered sequence straight from the content-addressed
-- geometry (a single-key GIN reverse probe + the central separator alphabet) --
-- no PRECEDES attestation, no gen_corpus flat corpus.
-- Native because the walk (find the point, skip separators, take the neighbour,
-- aggregate) is pointer/loop work SQL cannot do at scale; see geometry_successors.c.
--
-- p_backward flips the walk. The trajectory holds the EXACT ordered sequence of
-- everything ingested, so "what precedes x" is exactly as answerable as "what
-- follows x" -- same containment query, same separator set, same aggregation.
-- Asking the question is always legal; what is banned is MATERIALISING the answer
-- as stored PRECEDES rows when the geometry already holds it losslessly.
-- Multi-root form for sequence-projection expansion.  One GIN overlap probe reads every
-- trajectory containing ANY requested point, then native code preserves the
-- scalar contract independently for each root: first occurrence per physical
-- observation, first non-separator within p_window, top p_limit successors.
-- This is the set operator; callers with an array must not invoke the scalar
-- function row by row and rescan the same corpus for every frontier member.
-- "Successor" is not a direct substrate relationship: this operation projects
-- a container's ordered constituents into a text-generation stream. Structural
-- inference retains the point -> container -> constituent hop via containers_of().
DROP FUNCTION IF EXISTS laplace.geometry_successors_batch(bytea[], int, int, boolean);
CREATE OR REPLACE FUNCTION structural.geometry_successors_batch(
        p_points   bytea[],
        p_limit    int DEFAULT 20,
        p_window   int DEFAULT 8,
        p_backward boolean DEFAULT false)
    RETURNS TABLE(point_id bytea, successor_id bytea, seen bigint)
    AS 'laplace_substrate', 'pg_laplace_geometry_successors_batch'
    LANGUAGE C STABLE;

-- Retired with the chess request-time trajectory scan. Leaving either typed
-- wrapper installed would preserve an unused public execution path whose only
-- caller unpacked historical projection trajectories instead of reading exact
-- MOVE evidence.
DROP FUNCTION IF EXISTS structural.geometry_successors_typed(
    bytea, int, int, boolean, smallint);
DROP FUNCTION IF EXISTS structural.geometry_successors_batch_typed(
    bytea[], int, int, boolean, smallint);

DROP FUNCTION IF EXISTS laplace.geometry_successors(bytea, int, int, boolean);
CREATE OR REPLACE FUNCTION structural.geometry_successors(
        p_point    bytea,
        p_limit    int DEFAULT 20,
        p_window   int DEFAULT 8,
        p_backward boolean DEFAULT false)
    RETURNS TABLE(successor_id bytea, seen bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    -- Scalar is an adapter over the one set-native implementation. The former
    -- scalar C entry point owned a separate single-key SPI plan and duplicated
    -- the complete trajectory walk; callers now share batch semantics exactly.
    SELECT b.successor_id, b.seen
    FROM structural.geometry_successors_batch(
        ARRAY[p_point]::bytea[], p_limit, p_window, p_backward) b
    ORDER BY b.seen DESC, b.successor_id;
END;

-- Named mirror: "what comes before x", read from the same sequence.
DROP FUNCTION IF EXISTS laplace.geometry_predecessors(bytea, int, int);
CREATE OR REPLACE FUNCTION structural.geometry_predecessors(
        p_point  bytea,
        p_limit  int DEFAULT 20,
        p_window int DEFAULT 8)
    RETURNS TABLE(predecessor_id bytea, seen bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT successor_id, seen FROM structural.geometry_successors(p_point, p_limit, p_window, true)
$$;

-- Both directions at once, for the symmetric questions (shared-usage overlap,
-- domain co-occurrence) that must not be silently halved to fit a one-way walk.
DROP FUNCTION IF EXISTS laplace.geometry_neighbours(bytea, int, int);
CREATE OR REPLACE FUNCTION structural.geometry_neighbours(
        p_point  bytea,
        p_limit  int DEFAULT 20,
        p_window int DEFAULT 8)
    RETURNS TABLE(neighbour_id bytea, seen bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT n.id, sum(n.seen)::bigint
    FROM (
        SELECT successor_id AS id, seen FROM structural.geometry_successors(p_point, p_limit, p_window, false)
        UNION ALL
        SELECT successor_id AS id, seen FROM structural.geometry_successors(p_point, p_limit, p_window, true)
    ) n
    GROUP BY n.id
    ORDER BY 2 DESC
$$;
DROP FUNCTION IF EXISTS laplace.collocates(text, int);
CREATE OR REPLACE FUNCTION structural.collocates(p_word text, p_limit int DEFAULT 12)
    RETURNS TABLE(next_word text, mu numeric, witnesses bigint)
    LANGUAGE sql STABLE
 AS $$
    -- Rank + LIMIT on ids first, realize.render the ≤p_limit survivors (define/examples pattern) —
    -- realize.render() was projected over every PRECEDES edge of the word before the cut.
    -- Pillar 5 (2026-07-20): collocates are read from the GEOMETRY --
    -- geometry_successors returns the next content constituent in every
    -- trajectory containing the word, aggregated by observed frequency. There is
    -- no rated PRECEDES edge to read any more (Pillar 3a, e5e1b42), so `mu` is
    -- NULL: observed frequency is the signal, and inventing a rating here would
    -- fabricate a number the substrate never adjudicated.
    WITH raw AS MATERIALIZED (
        SELECT gs.successor_id, gs.seen
        FROM structural.geometry_successors(laplace.word_id(p_word), p_limit, 8) gs
        ORDER BY gs.seen DESC
        LIMIT p_limit
    ), numbered AS MATERIALIZED (
      SELECT s.*, row_number() OVER (ORDER BY s.seen DESC,s.successor_id) AS rn FROM raw s
    ), batch AS MATERIALIZED (
      SELECT realize.render_batch(array_agg(successor_id ORDER BY rn)) AS labels FROM numbered
    )
    SELECT b.labels[s.rn],NULL::numeric,s.seen FROM numbered s CROSS JOIN batch b ORDER BY s.rn
$$;
DROP FUNCTION IF EXISTS laplace.entity_curve(bytea);
CREATE OR REPLACE FUNCTION structural.entity_curve(p_entity bytea, p_type smallint) RETURNS geometry
    LANGUAGE sql STABLE
 AS $$
    SELECT public.ST_MakeLine(p.coord ORDER BY c.ordinal)
    FROM generation.trajectory_unpacked_points(p_entity, p_type)
         WITH ORDINALITY AS c(child_id, run_length, ctier, ordinal)
    JOIN laplace.physicalities p
      ON p.entity_id = c.child_id AND p.type = 1 AND p.coord IS NOT NULL
$$;

-- Content-lane default, BEGIN ATOMIC so the delegation records pg_depend (GH #764).
CREATE OR REPLACE FUNCTION structural.entity_curve(p_entity bytea) RETURNS geometry
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT structural.entity_curve(p_entity, 1::smallint);
END;
-- explore_anchor_neighbors: neighbour search from a COMPUTED anchor geometry,
-- not a stored one. When a word (or any content) is typed but never witnessed,
-- its content hash resolves to an id with no laplace.entities/laplace.physicalities row
-- (exists = false) -- yet its geometry is fully determined: HashComposer pins
-- every codepoint on S3 from the t0 perfcache and composes the parent coord and
-- trajectory in-process. The endpoint hands that computed anchor here as bound
-- parameters (centroid coord + optional trajectory WKT), so the KNN runs on a
-- real index-ordered scan (bound param, GiST-eligible -- unlike a correlated
-- subquery anchor) instead of returning nothing for want of a stored row.
--
-- Two axes, deliberately different notions of "near" (both returned so the UI
-- can navigate either way):
--   geodesic -- nearest witnessed content of ANY tier by the anchor centroid on
--     the glome. Positional/content proximity; centroids commute, so it mixes
--     tiers/modalities. Fast: index-ordered coord <<->> prefilter.
--   shape    -- nearest witnessed WORDS by REALIZED curve shape (Frechet over
--     entity_curve = ST_MakeLine(child.coord ORDER BY ordinal)). p_traj_wkt from
--     ExploreDecomposeService is already a realized LINESTRING ZM of child
--     coords; candidates must use entity_curve, never packed
--     laplace.physicalities.trajectory (Rule #3 / Issue 51).
DROP FUNCTION IF EXISTS laplace.explore_anchor_neighbors(float8, float8, float8, float8, text, integer, integer, float8);
CREATE OR REPLACE FUNCTION structural.explore_anchor_neighbors(
    p_cx float8, p_cy float8, p_cz float8, p_cm float8,
    p_traj_wkt   text    DEFAULT NULL,
    p_geodesic_k integer DEFAULT 12,
    p_frechet_k  integer DEFAULT 12,
    p_frechet_max float8  DEFAULT 0.08)
RETURNS TABLE(
    axis        text,
    entity_id   bytea,
    label       text,
    tier        smallint,
    geodesic    float8,
    frechet     float8)
LANGUAGE plpgsql STABLE PARALLEL SAFE
 AS $$
DECLARE
    v_anchor geometry := public.ST_SetSRID(
        public.ST_MakePoint(p_cx, p_cy, p_cz, p_cm), 0);
    v_traj   geometry := CASE
        WHEN p_traj_wkt IS NULL OR p_traj_wkt = '' THEN NULL
        ELSE public.ST_SetSRID(public.ST_GeomFromText(p_traj_wkt), 0)
    END;
BEGIN
    -- Geodesic: exact angular KNN on unit directions, then label the caller-sized
    -- result once. Chord order on S3 is angular order; no candidate multiplier.
    RETURN QUERY
    WITH g AS (
        SELECT w.id AS entity_id,
               public.laplace_angular_distance_4d(w.coord, v_anchor) AS geo
        FROM laplace.v_word_points w
        WHERE public.laplace_direction_4d(w.coord) IS NOT NULL
          AND public.laplace_direction_4d(v_anchor) IS NOT NULL
        ORDER BY public.laplace_direction_4d(w.coord)
                 <<->> public.laplace_direction_4d(v_anchor)
        LIMIT p_geodesic_k
    ), numbered AS MATERIALIZED (
        SELECT g.*, row_number() OVER (ORDER BY g.geo, g.entity_id) AS rn FROM g
    ), ids AS MATERIALIZED (
        SELECT array_agg(numbered.entity_id ORDER BY numbered.rn) AS a FROM numbered
    ), display AS MATERIALIZED (
        SELECT realize.render_text_batch(a) AS rendered,
               realize.label_batch(a) AS labels
        FROM ids
    )
    SELECT 'geodesic'::text,
           n.entity_id,
           COALESCE(NULLIF(d.rendered[n.rn], ''), d.labels[n.rn]),
           (SELECT min(e.tier) FROM laplace.entities e WHERE e.id = n.entity_id),
           n.geo,
           NULL::float8
    FROM numbered n CROSS JOIN display d
    ORDER BY n.geo;

    -- Shape: p_frechet_k is the exact coordinate-nearest candidate/output
    -- budget. Frechet filters that declared population; there is no hidden
    -- 500-row workload behind a request for fewer rows.
    IF v_traj IS NOT NULL THEN
        RETURN QUERY
        WITH pre AS (
            SELECT w.id AS entity_id
            FROM laplace.v_word_points w
            WHERE w.tier = 2 AND w.trajectory IS NOT NULL
            ORDER BY w.coord <<->> v_anchor
            LIMIT p_frechet_k
        ),
        f AS (
            SELECT c.entity_id,
                   public.laplace_frechet_4d(c.curve, v_traj) AS fr
            FROM (
                SELECT pre.entity_id, structural.entity_curve(pre.entity_id) AS curve
                FROM pre
            ) c
            WHERE c.curve IS NOT NULL
        ), survivors AS MATERIALIZED (
            SELECT f.entity_id, f.fr
            FROM f
            WHERE f.fr IS NOT NULL AND f.fr <= p_frechet_max
            ORDER BY f.fr, f.entity_id
        ), numbered AS MATERIALIZED (
            SELECT s.*, row_number() OVER (ORDER BY s.fr, s.entity_id) AS rn FROM survivors s
        ), ids AS MATERIALIZED (
            SELECT array_agg(numbered.entity_id ORDER BY numbered.rn) AS a FROM numbered
        ), display AS MATERIALIZED (
            SELECT realize.render_text_batch(a) AS rendered,
                   realize.label_batch(a) AS labels
            FROM ids
        )
        SELECT 'shape'::text,
               f.entity_id,
               COALESCE(NULLIF(d.rendered[f.rn], ''), d.labels[f.rn]),
               2::smallint,
               NULL::float8,
               f.fr
        FROM numbered f CROSS JOIN display d
        ORDER BY f.fr
        ;
    END IF;
END;
$$;
DROP FUNCTION IF EXISTS laplace.nearest_neighbors_4d(text, integer);
CREATE OR REPLACE FUNCTION structural.nearest_neighbors_4d(p_word text, p_k integer DEFAULT 10)
    RETURNS TABLE(neighbor text, geodesic double precision, frechet double precision)
    LANGUAGE sql STABLE
 AS $$
    SELECT neighbor, geodesic, frechet FROM structural.neighbors(p_word, p_k)
$$;
DROP FUNCTION IF EXISTS laplace.consensus_export_relations(bytea);
CREATE OR REPLACE FUNCTION structural.consensus_export_relations(p_type_id bytea)
    RETURNS TABLE(subject_id bytea, object_id bytea, rating bigint, witness_count bigint)
    LANGUAGE sql STABLE
 AS $$
    SELECT c.subject_id, c.object_id, c.rating, c.witness_count
    FROM laplace.consensus c
    WHERE c.type_id = p_type_id AND c.object_id IS NOT NULL
$$;
DROP FUNCTION IF EXISTS laplace.consensus_export_unary(bytea);
CREATE OR REPLACE FUNCTION structural.consensus_export_unary(p_type_id bytea)
    RETURNS TABLE(subject_id bytea, rating bigint, witness_count bigint)
    LANGUAGE sql STABLE
 AS $$
    SELECT c.subject_id, c.rating, c.witness_count
    FROM laplace.consensus c
    WHERE c.type_id = p_type_id AND c.object_id IS NULL
$$;
DROP FUNCTION IF EXISTS laplace.consensus_export_relations_mu(bytea);
CREATE OR REPLACE FUNCTION structural.consensus_export_relations_mu(p_type_id bytea)
    RETURNS TABLE(subject_id bytea, object_id bytea, eff_mu_fp bigint)
    LANGUAGE sql STABLE
 AS $$
    SELECT c.subject_id, c.object_id, consensus.eff_mu(c.rating, c.rd)
    FROM laplace.consensus c
    WHERE c.type_id = p_type_id AND c.object_id IS NOT NULL
$$;
DROP FUNCTION IF EXISTS laplace.model_recipes();
CREATE OR REPLACE FUNCTION structural.model_recipes()
    RETURNS TABLE(recipe_id bytea, recipe_json text, first_observed_by bytea)
    LANGUAGE sql STABLE
 AS $$
    SELECT e.id, cn.name, e.first_observed_by
    FROM laplace.entities e
    JOIN laplace.canonical_names cn ON cn.id = e.id
    WHERE e.type_id = realize.canonical_id('Model_Recipe')
$$;
-- Semantic firmware for compiling operator utterances into installed read
-- programs.  These ids are FrameNet frame entities already witnessed by lexical
-- surfaces across languages; they are not English prompt strings.  A surface
-- reaches a row through its EVOKES_FRAME testimony, so another language executes
-- the same program when its own surface evokes the same frame.
--
-- Keep this as data with an operation identity and an explicit operand role.  A
-- strcmp/regex ladder in an endpoint would erase the evidence path and make the
-- SQL and UI compilers drift again.
CREATE OR REPLACE FUNCTION converse.operation_frame_routes()
    RETURNS TABLE(frame_id bytea, operation_id bytea, shape text, role text)
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
BEGIN ATOMIC
    VALUES
      (laplace.word_id('People'),
       realize.canonical_id('operation/what_is/v1'), 'what_is'::text, 'request'::text),
      (laplace.word_id('Entity'),
       realize.canonical_id('operation/what_is/v1'), 'what_is'::text, 'request'::text),
      (laplace.word_id('Representing'),
       realize.canonical_id('operation/what_is/v1'), 'what_is'::text, 'binder'::text),
      (laplace.word_id('Existence'),
       realize.canonical_id('operation/what_is/v1'), 'what_is'::text, 'binder'::text);
END;
-- Compile an operator utterance into an installed operation plus typed operands.
-- This is deliberately an abstaining compiler: if the substrate does not witness
-- both a request cue and the operation's binder, it emits no program rather than
-- guessing from punctuation or an English surface pattern.
--
-- Stages are visible in the return receipt:
--   RESOLVE  prompt_words, once
--   ORIENT   operator/prompt language receipt
--   ROUTE    case-family surfaces -> EVOKES_FRAME -> operation_frame_routes
--   COMPOSE  ordered request, binder and operand identity arrays
--
-- Case widening is attested identity traversal, not lower(text).  The native set
-- function shares trajectory unpack, case maps, rendering and existence checks
-- across the whole prompt.  Consensus is then read once for every variant.
CREATE OR REPLACE FUNCTION converse.compile_prompt(
        p_prompt text,
        p_primary_language bytea DEFAULT NULL)
    RETURNS TABLE(
        operation_id bytea,
        shape text,
        request_ids bytea[],
        binder_ids bytea[],
        operand_ids bytea[],
        route_mu numeric,
        primary_language bytea,
        prompt_language bytea,
        effective_language bytea,
        widened boolean)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
WITH words AS MATERIALIZED (
    SELECT p.ord, p.id
    FROM converse.prompt_words(p_prompt) p
    WHERE p.id IS NOT NULL
),
variants AS MATERIALIZED (
    SELECT v.word_id, v.variant_id
    FROM lexical.word_case_variants_batch(
        ARRAY(SELECT w.id FROM words w ORDER BY w.ord)) v
),
route_nodes AS MATERIALIZED (
    SELECT v.word_id, v.variant_id AS node_id
    FROM variants v
    UNION
    SELECT v.word_id, n.subject_id
    FROM variants v
    JOIN laplace.consensus n
     ON n.object_id = v.variant_id
     AND n.type_id = ANY (consensus.relation_set_ids('NAME_ALIAS_EDGE'))
),
route_evidence AS MATERIALIZED (
    SELECT v.word_id,
           r.operation_id,
           r.shape,
           r.role,
           max(consensus.eff_mu(c.rating, c.rd)) AS mu
    FROM route_nodes v
    JOIN laplace.consensus c
      ON c.subject_id = v.node_id
     AND c.type_id = ANY (consensus.relation_family_ids('EVOKES_FRAME'))
    JOIN converse.operation_frame_routes() r ON r.frame_id = c.object_id
    GROUP BY v.word_id, r.operation_id, r.shape, r.role
),
programs AS MATERIALIZED (
    SELECT r.operation_id, r.shape, sum(r.mu) AS route_mu
    FROM route_evidence r
    GROUP BY r.operation_id, r.shape
    HAVING bool_or(r.role = 'request') AND bool_or(r.role = 'binder')
),
chosen AS MATERIALIZED (
    SELECT p.operation_id, p.shape, p.route_mu
    FROM programs p
    ORDER BY p.route_mu DESC, p.operation_id
    LIMIT 1
),
roles AS MATERIALIZED (
    SELECT DISTINCT r.word_id, r.role
    FROM route_evidence r
    JOIN chosen c USING (operation_id, shape)
),
-- Punctuation and other ungrounded atoms are not operands.  A lexicalized word
-- is one with a witnessed HAS_SENSE-family edge through any attested case form.
-- Articles remain part of the operand composition ("a dog" is not rewritten to
-- "dog"); firmware may later interpret that composition without an English
-- stop-word list.
lexicalized AS MATERIALIZED (
    SELECT DISTINCT v.word_id
    FROM variants v
    JOIN laplace.consensus c ON c.subject_id = v.variant_id
    WHERE c.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
),
plang AS MATERIALIZED (
    SELECT converse.prompt_language_top(p_prompt) AS id
)
SELECT c.operation_id,
       c.shape,
       ARRAY(SELECT w.id FROM words w
             JOIN roles r ON r.word_id = w.id AND r.role = 'request'
             ORDER BY w.ord),
       ARRAY(SELECT w.id FROM words w
             JOIN roles r ON r.word_id = w.id AND r.role = 'binder'
             ORDER BY w.ord),
       ARRAY(SELECT w.id FROM words w
             JOIN lexicalized l ON l.word_id = w.id
             WHERE NOT EXISTS (SELECT 1 FROM roles r WHERE r.word_id = w.id)
             ORDER BY w.ord),
       c.route_mu,
       p_primary_language,
       p.id,
       COALESCE(p.id, p_primary_language),
       p_primary_language IS NOT NULL
         AND p.id IS NOT NULL
         AND p.id <> p_primary_language
FROM chosen c
CROSS JOIN plang p
WHERE EXISTS (SELECT 1 FROM lexicalized l
              WHERE NOT EXISTS (SELECT 1 FROM roles r WHERE r.word_id = l.word_id));
END;
-- Thin wrapper over the native lexical.word_case_variants(src/lexical_case.c). The old
-- SQL body composed word_case_map_surface x3 (each a per-grapheme
-- grapheme_case_target consensus subquery + realize.render_text) -- the RBAR that
-- lexical_peers -> senses/define/bubble_up amplified. The native function does
-- the identical selection/realize.render/mint/exist steps in a fixed handful of batched
-- SPI round trips. Kept as a wrapper so lexical_peers and callers are unchanged.
DROP FUNCTION IF EXISTS laplace.word_case_variant_ids(bytea);
CREATE OR REPLACE FUNCTION lexical.word_case_variant_ids(p_word bytea)
    RETURNS bytea[]
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    SELECT lexical.word_case_variants(p_word)
$$;
-- Retired: the SQL word-case surface chain
--   word_case_class_surface(word) -> word_case_map_surface(word, map)
--     -> grapheme_case_target(grapheme, map)
-- is fully superseded by the native, batched lexical.word_case_variants(src/lexical_case.c),
-- which is what word_case_variant_ids -> lexical_peers and every live caller now use.
-- The old chain fanned one lexical lookup into O(3 * graphemes) non-inlinable
-- consensus LIMIT-1 subqueries plus O(graphemes) realize.render_text SPI calls (the RBAR on
-- the hot senses/define/bubble_up path). All three were dead in the call graph after
-- the native migration; dropped rather than left as slow, unreachable code.
DROP FUNCTION IF EXISTS laplace.word_case_class_surface(bytea);
DROP FUNCTION IF EXISTS laplace.word_case_map_surface(bytea, text);
DROP FUNCTION IF EXISTS laplace.grapheme_case_target(bytea, text);
-- Retired: the English prompt router.
--   parse_ask(prompt) -> (ask_kind, phrase, phrase2, type_name)   [pg_laplace_parse_ask]
-- The ~30-pattern English regex ladder that guessed a read intent and a relation
-- type from the surface form of a prompt is gone; converse.recall_intent() takes the shape
-- and the resolved ids as arguments instead. The C symbol pg_laplace_parse_ask no
-- longer exists in the .so, so on the UPGRADE path (which only CREATE-OR-REPLACEs
-- the manifest files and never drops what left it) the old catalog row would
-- linger bound to a missing symbol — an orphan that errors on every call. A fresh
-- CREATE EXTENSION never had it; this DROP makes the upgraded catalog match.
DROP FUNCTION IF EXISTS laplace.parse_ask(text);
-- Retired: the SQL-level word_shape_peers() is fully superseded by
-- lexical.word_shape_peers_fast() (native SPI, recall.c), which is what lexical.lexical_peers()
-- and every live caller uses. The SQL version's `nearest` CTE also carried the
-- known seq-scan defect (coord passed as a CTE column reference instead of a
-- genuine bound parameter defeats the GiST KNN index -- .scratchpad/02 Issue 33),
-- so it was both dead and slow. Dropped rather than fixed.
DROP FUNCTION IF EXISTS laplace.word_shape_peers(bytea, double precision);
-- Native replacement for word_shape_peers()'s KNN stage (see recall.c:
-- word_shape_peers_fast_impl for the full rationale). The original CTE-based
-- query's `ORDER BY p2.coord <<->> me.coord LIMIT 500`, with me.coord as a
-- correlated CTE reference rather than a bound parameter, was not eligible
-- for GiST KNN index-ordered scanning and fell back to a ~785K-row hash
-- join + top-N heapsort. This does the same job as two explicitly sequenced
-- SPI calls (fetch the anchor point, then a genuine bound-parameter KNN
-- scan), restoring real index usage.
DROP FUNCTION IF EXISTS laplace.word_shape_peers_fast(bytea, double precision);
CREATE OR REPLACE FUNCTION lexical.word_shape_peers_fast(p_word bytea, p_frechet_max double precision DEFAULT 0.02)
    RETURNS bytea[]
    AS 'laplace_substrate', 'pg_laplace_word_shape_peers_fast'
    LANGUAGE C STABLE STRICT;
-- lexical.lexical_peers[_batch] — GH #862 / #860.  The batch function owns the
-- semantic body; the scalar is a one-element adapter.  One row per input keeps
-- duplicate inputs and their order while still letting callers unnest each peer
-- set after one database call.
DROP FUNCTION IF EXISTS laplace.lexical_peers(bytea);
CREATE OR REPLACE FUNCTION lexical.lexical_peers_batch(p_words bytea[])
    RETURNS TABLE(input_ordinal bigint, word_id bytea, peers bytea[])
    AS 'laplace_substrate', 'pg_laplace_lexical_peers_batch'
    LANGUAGE C STABLE STRICT PARALLEL SAFE;

CREATE OR REPLACE FUNCTION lexical.lexical_peers(p_word bytea)
    RETURNS bytea[]
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    SELECT b.peers
    FROM lexical.lexical_peers_batch(ARRAY[p_word]) b
    WHERE b.input_ordinal = 1;
END;
-- senses: HAS_SENSE-family read (R2). Prefer bubble_up for top-k + domain;
-- this keeps the classic (sense, synset, consensus.eff_mu, witnesses) shape for lexical.define().
-- No SET search_path and no STRICT so it inlines into callers (both block
-- inlining; #617). NULL-safety is preserved without STRICT: taxonomy.bubble_up(NULL)
-- yields zero rows (lexical_peers is STRICT -> NULL array -> empty unnest).
-- lexical.senses — GH #862. Every call site moves in this same commit; a rename
-- with a live caller is a tree that does not install.
DROP FUNCTION IF EXISTS laplace.senses(bytea);
CREATE OR REPLACE FUNCTION lexical.senses(p_word bytea)
    RETURNS TABLE(sense_id bytea, synset_id bytea, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
    -- ROWS is the STRUCTURAL bound below, not an estimate: bubble_up is called with
    -- p_k = 64, so this cannot return more. Undeclared, Postgres assumes 1000 for a
    -- set-returning function -- 15.6x high on the bias-expansion path, where the
    -- estimate decides join order. 239 of the 244 set-returning functions in this
    -- surface still ship that default; each needs a measured cardinality or a bound
    -- like this one, never a guessed number.
    ROWS 64
    AS $$
    SELECT b.sense_id, b.synset_id, b.base_eff_mu, b.witnesses
    FROM taxonomy.bubble_up(p_word, NULL::bytea[], 64) b
    -- EVIDENCE BEFORE ADJUDICATED STRENGTH — see the matching note in
    -- bubble_up.sql.in. This ORDER BY is the one that decides what callers see:
    -- bubble_up's own ordering only selects which 64 candidates survive its
    -- LIMIT, and this re-sorts them.
    --
    -- Measured on the foundation ladder before the change,
    -- lexical.senses(laplace.word_id('water')):
    --     urine   1 witness   1169.73   <- elected
    --     water   1 witness   1169.73
    --     water   1 witness   1169.73
    --     water   2 witnesses 1168.45
    --     water   2 witnesses 1165.57
    -- Three senses tie exactly at the top on one witness each, so the id memcmp
    -- decided, and it chose urine over water for the word "water". Senses with
    -- twice the evidence sat below, losing by 1.28 on a quantity whose
    -- uncertainty term exceeds its signal — W16 3.2 measured mean
    -- |rating - neutral| 192.85 against mean rd 262.24 across 447,145 consensus
    -- rows, so 2*rd runs ~2.7x the signal and consensus.eff_mu sorts substantially by how
    -- little rd has shrunk.
    ORDER BY b.witnesses DESC, b.score DESC
$$;
-- Declared UNQUALIFIED until 2026-08-10, so it installed wherever search_path
-- pointed -- laplace.evidence_receipt -- while every caller and all three of its
-- siblings in this directory (ops.entity_facets, ops.evidence_count,
-- ops.entity_physicalities) use ops. NpgsqlSubstrateReads.EvidenceReceiptAsync
-- asked for ops.evidence_receipt, got 42883, and because SubstrateClient.Explore
-- fans the nine entity reads through one Task.WhenAll, that single missing
-- function failed the WHOLE Explore entity page as "Explore entity query failed."
DROP FUNCTION IF EXISTS laplace.evidence_receipt(bytea, integer);
CREATE OR REPLACE FUNCTION ops.evidence_receipt(p_id bytea, p_limit integer DEFAULT 25)
    RETURNS TABLE(
        type_id bytea,
        object_id bytea,
        type_label text,
        object_label text,
        eff_mu numeric,
        witness_count bigint,
        source_labels text)
    LANGUAGE sql STABLE
    AS $$
    WITH subj(id) AS (
        SELECT p_id
        UNION
        SELECT sn.synset_id FROM lexical.senses(p_id) sn
    ), feat_dynamic AS MATERIALIZED (
        -- Dynamic HAS_FEATURE children fenced once; consensus.relation_in_family() never
        -- inlines (SET search_path), so calling it per attestation row ran its
        -- EXISTS probe per row. Same truth table: static family via the C check
        -- below, dynamic membership via this set.
        SELECT c.subject_id AS id FROM laplace.consensus c
        WHERE c.type_id = laplace.relation_type_id('IS_A')
          AND c.object_id = laplace.relation_type_id('HAS_FEATURE')
    ), filtered AS MATERIALIZED (
        -- Fenced: without the fence the downstream LIMIT flips the planner into
        -- a cheap-startup nested loop that seq-scans EVERY attestations partition
        -- once per subj id (measured 2026-07-23 on the live 133.5M-row table:
        -- >180s for the "run" hub vs 991ms for this same CTE planned standalone).
        SELECT a.type_id, a.object_id, a.source_id,
               sum(a.observation_count) AS obs
        FROM laplace.attestations a
        WHERE a.subject_id IN (SELECT id FROM subj)
          AND a.object_id IS NOT NULL
          AND EXISTS (
              SELECT 1 FROM laplace.entities et
              WHERE et.id = a.type_id AND et.type_id = laplace.entity_type_id('RelationType'))
          AND a.type_id <> ALL (consensus.relation_family_ids('HAS_POS'))
          AND a.type_id <> ALL (consensus.relation_family_ids('HAS_FEATURE'))
          AND a.type_id NOT IN (SELECT id FROM feat_dynamic)
          AND -- The exclusion set is DECLARED: engine/manifest/relation_types.toml [[set]]
          -- NON_SALIENT_STRUCTURAL. It was a byte-identical 16-name NOT IN list here AND
          -- in the sibling function -- one judgement about what is not a content fact,
          -- kept in two files with nothing holding them in step. `<> ALL` matches the two
          -- family exclusions above and is exactly equivalent to NOT IN here: type_id is
          -- NOT NULL on both laplace.consensus and laplace.attestations (catalog-verified).
          a.type_id <> ALL (consensus.relation_set_ids('NON_SALIENT_STRUCTURAL'))
          -- UNDECLARED VOCABULARY, kept inline deliberately: CO_OCCURS_WITH and
          -- OCCURS_IN_CONTEXT are in neither the manifest's canonicals nor its
          -- aliases, though both exist as live RelationType entities. Codegen
          -- REFUSES a set naming them (an undeclared member would emit NULL and
          -- silently match nothing), and inventing a bit/rank/symmetry for them
          -- is an operator decision. Row counts are deliberately NOT cited as the reason
          -- either way: spec 36's CORRECTION 2026-07-25 retracts exactly that move for this
          -- family of relations ("a low PRECEDES count is not a status signal -- do not cite
          -- it"), because sequence lives in the trajectory and these are views of it.
          AND a.type_id NOT IN (
                laplace.relation_type_id('CO_OCCURS_WITH'),
                laplace.relation_type_id('OCCURS_IN_CONTEXT'))
          AND NOT EXISTS (
              SELECT 1 FROM laplace.entities et
              WHERE et.id = a.object_id AND et.type_id = laplace.entity_type_id('RelationType'))
          AND NOT (
              a.type_id = laplace.relation_type_id('IS_SYNONYM_OF')
              AND a.object_id IN (SELECT id FROM subj))
        GROUP BY a.type_id, a.object_id, a.source_id
    ), src_ids AS MATERIALIZED (
        SELECT array_agg(DISTINCT f.source_id ORDER BY f.source_id) AS a FROM filtered f
    ), src_labels AS MATERIALIZED (
        -- Label each DISTINCT source ONCE (sources number in the dozens), fenced
        -- so realize.render() cannot be pushed back down to run per (type, object, source)
        -- group (~3,129 renders for one entity before this map existed). The
        -- string_agg below keeps the exact DISTINCT + ORDER BY label semantics of
        -- the old inline expression, so output is byte-identical.
        SELECT i.id AS source_id,
               regexp_replace(i.txt,
                   '^substrate/source/([^/]+)(?:/v[0-9]+)?$', '\1') AS label
        FROM src_ids,
          LATERAL ROWS FROM (
            unnest(src_ids.a), unnest(realize.render_batch(src_ids.a))
          ) i(id,txt)
    ), folded AS (
        SELECT f.type_id, f.object_id,
               sum(f.obs) AS witness_count,
               string_agg(DISTINCT sl.label, ', ' ORDER BY sl.label) AS source_labels
        FROM filtered f
        JOIN src_labels sl ON sl.source_id = f.source_id
        GROUP BY f.type_id, f.object_id
    ), best AS MATERIALIZED (
        -- One subject-side indexed scan replaces the old per-folded-row LATERAL
        -- probe. The lateral shape re-probed consensus once per folded group
        -- (~19.7k groups for a hub word), each probe Append-planned across the
        -- type partitions — measured >120s for "run"; this whole set is ~22k rows
        -- and aggregates in well under a second. DISTINCT ON keeps the exact
        -- "single best row by eff_mu" semantics of the old ORDER BY ... LIMIT 1.
        SELECT DISTINCT ON (c.type_id, c.object_id)
               c.type_id, c.object_id,
               consensus.eff_mu(c.rating, c.rd) AS mu_raw,
               consensus.eff_mu_display(c.rating, c.rd) AS mu_disp
        FROM laplace.consensus c
        WHERE c.subject_id IN (SELECT id FROM subj)
          AND c.object_id IS NOT NULL
        ORDER BY c.type_id, c.object_id, consensus.eff_mu(c.rating, c.rd) DESC
    ), ranked AS (
        -- Issue 52: rank BEFORE labeling. The old shape labeled every folded claim
        -- (type_label + _realize_synset_lemma/render_text, ~6ms/row — 3,129 labels
        -- to return 3 rows, >25s cold) and only then ordered/limited. Ranking needs
        -- only the consensus join, so it runs first over everything. Labels are
        -- total below: unrenderable ids receive deterministic hash labels rather
        -- than disappearing. The requested head is therefore exact; the old
        -- `3x+8` over-fetch was an unsupported probability bet.
        SELECT fo.type_id, fo.object_id, fo.witness_count, fo.source_labels,
               COALESCE(b.mu_raw, 0)  AS mu_raw,
               COALESCE(b.mu_disp, 0) AS eff_mu_disp
        FROM folded fo
        LEFT JOIN best b
               ON b.type_id = fo.type_id AND b.object_id = fo.object_id
        WHERE fo.source_labels IS NOT NULL AND fo.source_labels <> ''
        ORDER BY consensus.edge_rank(fo.type_id, COALESCE(b.mu_raw, 0)) DESC,
                 fo.witness_count DESC,
                 fo.type_id,
                 fo.object_id
        LIMIT GREATEST(p_limit, 0)
    ), ordered AS (
        SELECT rk.*, row_number() OVER (
                   ORDER BY consensus.edge_rank(rk.type_id, rk.mu_raw) DESC,
                            rk.witness_count DESC) AS ord
        FROM ranked rk
    ), labels AS MATERIALIZED (
        -- MATERIALIZED is load-bearing: this is a single-row realize_batch over
        -- the whole `ordered` window. Un-fenced, PG inlines it into the final
        -- `labeled` join, and because the labels array is subscripted by o.ord
        -- the planner re-evaluates the entire array_agg + realize_batch ONCE PER
        -- OUTPUT ROW (128 loops × ~160ms = 20s for the "run" hub; measured
        -- 2026-07-24 — the exact regression that reappeared after an upstream
        -- cardinality-estimate shift flipped the inlining decision). Fenced, it
        -- runs exactly once. Output is byte-identical (proven run/emperor/king,
        -- both EXCEPT directions empty).
        -- Full-mesh labels via ONE realize.batch(was: a shorter hand-rolled
        -- synset-lemma -> render -> HEX ladder per row). Gains the
        -- HAS_NAME/translation/canonical/gloss arms; hex stays the genuine
        -- last resort so every claim still shows. Approved behavior change.
        SELECT realize.batch(array_agg(o.object_id ORDER BY o.ord),
                             converse.word_language(p_id)) AS l,
               lexical.type_label_batch(array_agg(o.type_id ORDER BY o.ord)) AS types
        FROM ordered o
    ), labeled AS (
        SELECT o.type_id, o.object_id, o.witness_count, o.source_labels,
               o.mu_raw, o.eff_mu_disp,
               COALESCE(NULLIF(labels.types[o.ord], ''),
                        consensus.relation_canonical(o.type_id),
                        'Unrealized relation') AS rel,
               COALESCE(NULLIF(labels.l[o.ord], ''),
                        'Unrealized entity') AS obj
        FROM ordered o, labels
    )
    SELECT lb.type_id, lb.object_id, lb.rel, lb.obj,
           lb.eff_mu_disp,
           lb.witness_count,
           lb.source_labels
    FROM labeled lb
    ORDER BY consensus.edge_rank(lb.type_id, lb.mu_raw) DESC,
             lb.witness_count DESC,
             lb.type_id,
             lb.object_id
    LIMIT GREATEST(p_limit, 0)
$$;
DROP FUNCTION IF EXISTS laplace.consensus_out_labeled(bytea, integer);
DROP FUNCTION IF EXISTS ops.consensus_out_labeled(bytea, integer);
CREATE OR REPLACE FUNCTION ops.consensus_out_labeled(p_id bytea, p_limit integer DEFAULT 40)
    RETURNS TABLE(
        type_id bytea,
        object_id bytea,
        type_label text,
        object_label text,
        eff_mu numeric,
        witnesses bigint)
    LANGUAGE sql STABLE
    AS $$
    WITH subj(id) AS (
        SELECT p_id
        UNION
        SELECT sn.synset_id FROM lexical.senses(p_id) sn
    ),
    ranked AS (
        SELECT c.type_id, c.object_id, c.eff_mu, c.witness_count,
               consensus.edge_rank(c.type_id, c.eff_mu_raw) AS rnk
        FROM laplace.v_consensus_resolved c
        WHERE c.subject_id IN (SELECT id FROM subj)
          AND c.object_id IS NOT NULL
        ORDER BY consensus.edge_rank(c.type_id, c.eff_mu_raw) DESC
        LIMIT GREATEST(p_limit, 0)
    )
    , ordered AS (
        SELECT r.*, row_number() OVER (ORDER BY r.rnk DESC) AS ord
        FROM ranked r
    ), labels AS (
        SELECT realize.batch(array_agg(o.object_id ORDER BY o.ord),
                             converse.word_language(p_id)) AS l,
               lexical.type_label_batch(array_agg(o.type_id ORDER BY o.ord)) AS types
        FROM ordered o
    )
    SELECT o.type_id, o.object_id,
           labels.types[o.ord],
           COALESCE(NULLIF(labels.l[o.ord], ''),
                    'Unrealized entity'),
           o.eff_mu,
           o.witness_count
    FROM ordered o, labels
    ORDER BY o.ord
$$;
-- lexical.senses(word, context[]): the senses of a word, ranked BY CONTEXT.
--
-- PRIOR VERSION WAS INERT ON REAL DATA. Its only lane boosted a synset by summing
-- consensus.eff_mu over consensus rows where `subject_id = ANY(p_context)` (or object_id),
-- i.e. it required a DIRECT edge from a context entity to the synset. p_context
-- carries WORD laplace.entities and words reach synsets through HAS_SENSE -> IS_SENSE_OF,
-- so on a real corpus that join almost never matches and every boost was 0.
-- Verified 2026-07-25: opposite contexts ({animal,pet,bark} vs
-- {sausage,roll,beef}) returned byte-identical rankings AND byte-identical scores
-- for `dog`. One lane, and it was the wrong shape for the topology.
--
-- The first fix replaced that lane with three synset-to-synset lanes and DELETED
-- it. That was over-correction and it regressed the converse regress test, whose
-- fixture wires a direct w_h --CAUSES--> synset1 edge and asserts context flips the
-- resolved sense. "Usually absent" is not "never evidence": where a direct edge is
-- attested it is the strongest available statement that a context term bears on a
-- sense. It is restored below as a fourth lane. Adding lanes is the fix; removing
-- the one that existed was not.
--
-- Five lanes now, all in ID SPACE (no realize/realize.render/label anywhere -- rendering is
-- the caller's final step, never a mid-operation string compare):
--
--   USAGE   the candidate synset OWNS a gloss or example whose word realize.constituents
--           include a context token. Sense-resolution here is by OWNERSHIP, not
--           per-token tagging: a gloss/example hangs off exactly one synset, so a
--           word occurring inside it is already sense-resolved on the owning side.
--           This is the lane that actually discriminates.
--   FRAME   a context sense EVOKES_FRAME F and the candidate corresponds to F.
--           Frames unify across languages, so this lane is language-agnostic.
--   DOMAIN  candidate HAS_DOMAIN_TOPIC D and a context token is (or senses to) D
--           (GH #785 discourse prior — e.g. pawn+chess).
--   DIRECT  a context ENTITY has an attested edge straight to a candidate synset.
--           Usually absent on real data, but where present it is the strongest
--           statement that a context term bears on a sense.
--   TAXON   candidate and a context SENSE meet within one hop over the content
--           bands -- the synset-to-synset comparison the old version was reaching
--           for and getting wrong.
--
-- Every lane is weighted by the consensus.eff_mu of the edges carrying it: trust enters
-- through the rating math, never through an operator-chosen constant. No floors,
-- no caps, no top-k -- ORDER BY only, LIMIT is the caller's.
--
-- Returns the same columns as before so existing callers are unaffected. With an
-- empty/NULL context every lane contributes nothing and the ordering degenerates to
-- the sense prior, which is the documented no-context behaviour.
-- NO `SET search_path` (GH #860). The clause blocks SQL inlining -- the planner
-- keeps the function as an opaque `Function Scan` rather than pulling the body into
-- the caller and pushing predicates through to the index. The 1-arg `lexical.senses()` this
-- overload sits beside dropped the clause under #617 and inlines to an index scan;
-- this overload is on the same read path and was still paying it. Every reference is
-- `@extschema@.`-qualified instead, which is what the clause was doing and costs
-- nothing at plan time.
DROP FUNCTION IF EXISTS laplace.senses(bytea, bytea[]);
CREATE OR REPLACE FUNCTION lexical.senses(p_word bytea, p_context bytea[])
    RETURNS TABLE(sense_id bytea, synset_id bytea, eff_mu numeric, witnesses bigint,
                  score numeric)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH ctx AS MATERIALIZED (
        SELECT DISTINCT t AS id
        FROM unnest(COALESCE(p_context, ARRAY[]::bytea[])) AS t
        WHERE t IS NOT NULL AND t <> p_word
    ),
    -- Context words resolved to their own senses: the comparison is synset<->synset.
    --
    -- ONE batch election, not a LATERAL per context id. lexical.senses is a SQL wrapper
    -- over taxonomy.bubble_up, so a LATERAL inlined bubble_up's whole CTE cascade --
    -- and every consensus reference in it -- once PER context id. Each unprunable
    -- reference to consensus contributes 216 scan nodes to the plan, which is why this
    -- function measured 699.8 ms PLANNING against 288.1 ms executing.
    -- taxonomy.bubble_up_batch elects for the whole context set in one instance.
    --
    -- Same rows: bubble_up_batch is byte-identical to per-term bubble_up untruncated
    -- (1,012 rows, EXCEPT ALL empty both directions), and only synset_id is taken here.
    ctx_syn AS MATERIALIZED (
        SELECT DISTINCT b.synset_id AS sid
        FROM taxonomy.bubble_up_batch(ARRAY(SELECT id FROM ctx)) b
        WHERE b.synset_id IS NOT NULL
    ),
    cand AS MATERIALIZED (
        SELECT s.sense_id, COALESCE(ss.object_id, s.sense_id) AS synset_id,
               s.rating, s.rd, s.witness_count AS w1,
               COALESCE(ss.witness_count, 0) AS w2
        FROM @extschema@.v_word_senses s
        LEFT JOIN @extschema@.consensus ss ON ss.subject_id = s.sense_id
                         AND ss.type_id = @extschema@.relation_type_id('IS_SENSE_OF')
        WHERE s.word_id = ANY(lexical.lexical_peers(p_word))
    ),
    candidate_nodes AS (
        SELECT c.synset_id AS sid, c.synset_id AS node_id FROM cand c
        UNION
        SELECT c.synset_id, c.sense_id FROM cand c
    ),
    -- USAGE: candidate owns a sentence (gloss band 1 / example band 7) whose
    -- word-tier realize.constituents include a context token.
    own_sent AS (
        SELECT DISTINCT n.sid, c.object_id AS gid,
               consensus.eff_mu(c.rating, c.rd) AS w
        FROM candidate_nodes n
        JOIN @extschema@.consensus c ON c.subject_id = n.node_id
        WHERE consensus.relation_highway_band(c.type_id) IN (1, 7)
    ),
    lane_usage AS (
        SELECT os.sid, sum(os.w) AS boost
        FROM own_sent os
        CROSS JOIN LATERAL generation.trajectory_unpacked_points(os.gid)
             WITH ORDINALITY AS u(entity_id, run_length, ctier, ord)
        WHERE u.ctier = 2 AND u.entity_id IN (SELECT id FROM ctx)
        GROUP BY os.sid
    ),
    -- FRAME: shared frame between a context sense and the candidate.
    ctx_frame AS (
        SELECT DISTINCT c.object_id AS fid, consensus.eff_mu(c.rating, c.rd) AS w
        FROM ctx_syn s
        JOIN @extschema@.consensus c ON c.subject_id = s.sid
        WHERE c.type_id = ANY (consensus.relation_family_ids('EVOKES_FRAME'))
    ),
    lane_frame AS (
        SELECT c.subject_id AS sid, sum(cf.w) AS boost
        FROM @extschema@.consensus c
        JOIN ctx_frame cf ON cf.fid = c.object_id
        WHERE c.subject_id IN (SELECT synset_id FROM cand)
          AND c.type_id = ANY (consensus.relation_family_ids('EVOKES_FRAME'))
        GROUP BY c.subject_id
    ),
    -- TAXON: candidate meets a context sense within one hop, either direction.
    lane_taxon AS (
        SELECT x.sid, sum(x.w) AS boost FROM (
            SELECT c.subject_id AS sid, consensus.eff_mu(c.rating, c.rd) AS w
            FROM @extschema@.consensus c
            WHERE c.subject_id IN (SELECT synset_id FROM cand)
              AND c.object_id IN (SELECT sid FROM ctx_syn)
              AND consensus.relation_highway_band(c.type_id) IN (2, 4, 7)
            UNION ALL
            SELECT c.object_id, consensus.eff_mu(c.rating, c.rd)
            FROM @extschema@.consensus c
            WHERE c.object_id IN (SELECT synset_id FROM cand)
              AND c.subject_id IN (SELECT sid FROM ctx_syn)
              AND consensus.relation_highway_band(c.type_id) IN (2, 4, 7)
        ) x
        GROUP BY x.sid
    ),
    -- DOMAIN (GH #785): a candidate synset HAS_DOMAIN_TOPIC D and a context
    -- token is (or senses to) D. "pawn" + "chess" elects the chess-piece sense
    -- because WordNet attached HAS_DOMAIN_TOPIC→chess; the USAGE lane also
    -- catches "(chess) the least powerful piece" in the gloss, but domain is
    -- the explicit discourse prior and works when the gloss spelling differs
    -- from the prompt token. Weighted by the domain edge's consensus.eff_mu.
    lane_domain AS (
        SELECT c.subject_id AS sid, sum(consensus.eff_mu(c.rating, c.rd)) AS boost
        FROM @extschema@.consensus c
        WHERE c.subject_id IN (SELECT synset_id FROM cand)
          AND c.type_id = consensus.relation_type_resolve('HAS_DOMAIN_TOPIC')
          AND (c.object_id IN (SELECT id FROM ctx)
               OR c.object_id IN (SELECT sid FROM ctx_syn))
        GROUP BY c.subject_id
    ),
    -- DIRECT: a context ENTITY has an attested edge to a candidate synset, either
    -- direction, any relation. This is the lane the previous implementation had, and
    -- dropping it was a regression -- the converse regress fixture wires
    -- w_h --CAUSES--> synset1 and asserts that context flips the resolved sense to
    -- synset1, which stopped happening.
    --
    -- Removing it was over-correction. The earlier finding stands: this lane alone is
    -- INERT ON REAL DATA, because words reach synsets through HAS_SENSE ->
    -- IS_SENSE_OF and almost never carry a direct edge to one -- which is why opposite
    -- contexts ({animal,pet,bark} vs {sausage,roll,beef}) scored byte-identically for
    -- `dog`. But "usually absent" is not "never evidence". Where a direct edge IS
    -- attested it is the strongest possible statement that a context term bears on a
    -- sense, and discarding it to make room for the other three lanes threw away
    -- signal rather than adding to it.
    --
    -- Deliberately unbanded: the other lanes gate on content bands because they
    -- traverse to reach the candidate, and untyped traversal drifts. A direct edge
    -- does not traverse -- the context term names the sense outright -- so gating it
    -- by band would discard exactly the causal/oppositional evidence the fixture
    -- carries.
    lane_direct AS (
        SELECT x.sid, sum(x.w) AS boost FROM (
            SELECT c.object_id AS sid, consensus.eff_mu(c.rating, c.rd) AS w
            FROM @extschema@.consensus c
            WHERE c.subject_id IN (SELECT id FROM ctx)
              AND c.object_id IN (SELECT synset_id FROM cand)
            UNION ALL
            SELECT c.subject_id, consensus.eff_mu(c.rating, c.rd)
            FROM @extschema@.consensus c
            WHERE c.object_id IN (SELECT id FROM ctx)
              AND c.subject_id IN (SELECT synset_id FROM cand)
        ) x
        GROUP BY x.sid
    )
    SELECT cand.sense_id,
           cand.synset_id,
           consensus.eff_mu_display(cand.rating, cand.rd),
           (cand.w1 + cand.w2)::bigint,
           round(((consensus.eff_mu(cand.rating, cand.rd)
                   + COALESCE(lu.boost, 0)
                   + COALESCE(lf.boost, 0)
                   + COALESCE(lt.boost, 0)
                   + COALESCE(ldo.boost, 0)
                   + COALESCE(ld.boost, 0)) / 1e9)::numeric, 3)
    FROM cand
    LEFT JOIN lane_usage  lu  ON lu.sid  = cand.synset_id
    LEFT JOIN lane_frame  lf  ON lf.sid  = cand.synset_id
    LEFT JOIN lane_taxon  lt  ON lt.sid  = cand.synset_id
    LEFT JOIN lane_domain ldo ON ldo.sid = cand.synset_id
    LEFT JOIN lane_direct ld  ON ld.sid  = cand.synset_id
    ORDER BY 5 DESC
$$;
-- NO `SET search_path` (GH #860). The clause makes a SQL function non-inlinable:
-- the planner keeps it as an opaque `Function Scan` instead of pulling the body
-- into the caller and pushing predicates through to the index. Measured on the
-- foundation seed 2026-08-04, the SET-carrying siblings planned as one opaque line
-- where `lexical.senses()` -- which dropped the clause under #617 -- inlined to an
-- `Index Scan using entities_t2_h0_type_id_idx`. `define` sits on the read path,
-- so it pays that on every call.
--
-- Every reference is `@extschema@.`-qualified instead. That is what the clause was
-- actually doing here, and qualification does it at parse time for free. This is the
-- same trade recorded by `drop_retired_eff_mu`.
DROP FUNCTION IF EXISTS laplace.define(bytea, int);
CREATE OR REPLACE FUNCTION lexical.define(p_word bytea, p_limit int DEFAULT 5)
    RETURNS TABLE(definition text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    WITH picked AS MATERIALIZED (
        SELECT u.object_id, u.eff_mu, u.witnesses, u.sense_rank
        FROM (
            SELECT g.object_id AS object_id,
                   consensus.eff_mu_display(g.rating, g.rd) AS eff_mu,
                   g.witness_count AS witnesses,
                   sn.eff_mu AS sense_rank
            FROM lexical.senses(p_word) sn
            JOIN @extschema@.consensus g
              ON g.subject_id = ANY (ARRAY[sn.sense_id, sn.synset_id])
                            AND g.type_id = @extschema@.relation_type_id('HAS_DEFINITION')
            UNION ALL
            SELECT g.object_id,
                   consensus.eff_mu_display(g.rating, g.rd),
                   g.witness_count,
                   NULL::numeric
            FROM unnest(lexical.lexical_peers(p_word)) AS peer(id)
            JOIN @extschema@.consensus g ON g.subject_id = peer.id
                            AND g.type_id = @extschema@.relation_type_id('HAS_DEFINITION')
        ) u
        ORDER BY COALESCE(u.sense_rank, 0) + u.eff_mu DESC
        LIMIT p_limit
    ), numbered AS MATERIALIZED (
      SELECT d.*, row_number() OVER (ORDER BY COALESCE(d.sense_rank,0)+d.eff_mu DESC, d.object_id) AS rn FROM picked d
    ), batch AS MATERIALIZED (
      SELECT realize.render_text_batch(array_agg(object_id ORDER BY rn)) AS txt FROM numbered
    )
    SELECT b.txt[d.rn], d.eff_mu, d.witnesses FROM numbered d CROSS JOIN batch b ORDER BY d.rn
$$;
DROP FUNCTION IF EXISTS laplace.define(bytea, bytea[], int);
CREATE OR REPLACE FUNCTION lexical.define(p_word bytea, p_context bytea[], p_limit int DEFAULT 5)
    RETURNS TABLE(definition text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH picked AS MATERIALIZED (
        SELECT u.object_id, u.eff_mu, u.witnesses, u.sense_rank
        FROM (
            SELECT g.object_id AS object_id,
                   consensus.eff_mu_display(g.rating, g.rd) AS eff_mu,
                   g.witness_count AS witnesses,
                   sn.score AS sense_rank
            FROM lexical.senses(p_word, p_context) sn
            JOIN laplace.consensus g
              ON g.subject_id = ANY (ARRAY[sn.sense_id, sn.synset_id])
                            AND g.type_id = laplace.relation_type_id('HAS_DEFINITION')
            UNION ALL
            SELECT g.object_id,
                   consensus.eff_mu_display(g.rating, g.rd),
                   g.witness_count,
                   NULL::numeric
            FROM unnest(lexical.lexical_peers(p_word)) AS peer(id)
            JOIN laplace.consensus g ON g.subject_id = peer.id
                            AND g.type_id = laplace.relation_type_id('HAS_DEFINITION')
        ) u
        ORDER BY COALESCE(u.sense_rank, 0) + u.eff_mu DESC
        LIMIT p_limit
    ), numbered AS MATERIALIZED (
      SELECT d.*, row_number() OVER (ORDER BY COALESCE(d.sense_rank,0)+d.eff_mu DESC, d.object_id) AS rn FROM picked d
    ), batch AS MATERIALIZED (
      SELECT realize.render_text_batch(array_agg(object_id ORDER BY rn)) AS txt FROM numbered
    )
    SELECT b.txt[d.rn], d.eff_mu, d.witnesses FROM numbered d CROSS JOIN batch b ORDER BY d.rn
$$;
DROP FUNCTION IF EXISTS laplace.examples(bytea, int);
CREATE OR REPLACE FUNCTION lexical.examples(p_word bytea, p_limit int DEFAULT 5)
    RETURNS TABLE(example text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    WITH picked AS MATERIALIZED (
        SELECT g.object_id AS object_id,
               consensus.eff_mu_display(g.rating, g.rd) AS eff_mu,
               g.witness_count AS witnesses,
               sn.eff_mu AS sense_rank
        FROM lexical.senses(p_word) sn
        JOIN laplace.consensus g
          ON g.subject_id = ANY (ARRAY[sn.sense_id, sn.synset_id])
                        AND g.type_id = laplace.relation_type_id('HAS_EXAMPLE')
        ORDER BY sn.eff_mu + consensus.eff_mu_display(g.rating, g.rd) DESC
        LIMIT p_limit
    ), numbered AS MATERIALIZED (
      SELECT x.*, row_number() OVER (ORDER BY x.sense_rank+x.eff_mu DESC, x.object_id) AS rn FROM picked x
    ), batch AS MATERIALIZED (
      SELECT realize.render_text_batch(array_agg(object_id ORDER BY rn)) AS txt FROM numbered
    )
    SELECT b.txt[x.rn], x.eff_mu, x.witnesses FROM numbered x CROSS JOIN batch b ORDER BY x.rn
$$;
DROP FUNCTION IF EXISTS laplace.synset_members(bytea);
CREATE OR REPLACE FUNCTION lexical.synset_members(p_word bytea)
    RETURNS TABLE(member bytea, lang bytea, mu bigint, witnesses bigint, sense_mu numeric)
    LANGUAGE sql STABLE   STRICT  PARALLEL SAFE AS $$
    WITH syn AS (
        SELECT s.synset_id AS id, max(s.eff_mu) AS sense_mu
        FROM lexical.senses(p_word) s
        -- Instance synsets (proper nouns) are excluded, but only on a STANDING
        -- instance edge. Bare row presence also excluded synsets whose
        -- IS_INSTANCE_OF was witnessed and REFUTED -- the fold said "not an
        -- instance" and the filter read that as "is an instance". consensus has no
        -- outcome column; refutation is a non-positive consensus.eff_mu, the same test the
        -- walk uses to dead-end an edge. An absent edge still excludes nothing.
        WHERE NOT EXISTS (
            SELECT 1 FROM laplace.consensus i
            WHERE i.subject_id = s.synset_id
              AND i.type_id = laplace.relation_type_id('IS_INSTANCE_OF')
              AND consensus.eff_mu(i.rating, i.rd) > 0)
        GROUP BY s.synset_id
    ),
    members AS (
        -- Exact WordNet membership: lemma -> sense -> synset. The data-file shortcut
        -- was removed because it duplicated the index.sense observation and erased the
        -- lexical-sense identity. HAS_SENSE-family matching keeps aliases governed.
        SELECT hs.subject_id AS w, hs.rating, hs.rd, hs.witness_count, syn.sense_mu
        FROM syn
        JOIN laplace.consensus so
          ON so.object_id = syn.id
         AND so.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
         AND consensus.relation_canonical(so.type_id) = 'IS_SENSE_OF'
        JOIN laplace.consensus hs
          ON hs.object_id = so.subject_id
         AND hs.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
         AND consensus.relation_canonical(hs.type_id) = 'HAS_SENSE'
        UNION ALL
        -- OMW and other resources without a source sense key may still make a direct
        -- lexical membership assertion. Keep that distinct source shape readable.
        SELECT c.object_id AS w, c.rating, c.rd, c.witness_count, syn.sense_mu
        FROM laplace.consensus c JOIN syn ON c.subject_id = syn.id
        WHERE c.type_id = laplace.relation_type_id('IS_SYNONYM_OF') AND c.object_id IS NOT NULL
        UNION ALL
        SELECT c.subject_id AS w, c.rating, c.rd, c.witness_count, syn.sense_mu
        FROM laplace.consensus c JOIN syn ON c.object_id = syn.id
        WHERE c.type_id = laplace.relation_type_id('IS_SYNONYM_OF')
    ),
    -- MATERIALIZED is load-bearing: it forces lexical.lexical_peers(a ~75ms native-KNN
    -- call) to run ONCE per synset_members call. The bare
    -- `<> ALL(lexical.lexical_peers(p_word))` filter form was pushed into the members
    -- index scans and re-executed PER ROW (STABLE fns are never constant-folded;
    -- a plain one-row subselect gets pulled up and re-pushed identically):
    -- measured 65.3s of converse.translate_to('water')'s 68.6s (2026-07-05, 14.9M
    -- laplace.physicalities). `= ANY` callers (senses) are immune only because an
    -- indexed ANY becomes the index condition itself, which forces one-shot
    -- evaluation of the array.
    peers AS MATERIALIZED (
        SELECT lexical.lexical_peers(p_word) AS arr
    ),
    agg AS (
        SELECT m.w,
               max(consensus.eff_mu(m.rating, m.rd)) AS mu,
               sum(m.witness_count)::bigint AS witnesses,
               max(m.sense_mu) AS sense_mu
        FROM members m, peers px
        WHERE m.w <> ALL(px.arr)
        GROUP BY m.w
    )
    SELECT a.w, hl.object_id AS lang, a.mu::bigint, a.witnesses, a.sense_mu
    FROM agg a
    LEFT JOIN laplace.consensus hl
      ON hl.subject_id = a.w AND hl.type_id = laplace.relation_type_id('HAS_LANGUAGE')
$$;
DROP FUNCTION IF EXISTS laplace.concept_ref(text);
CREATE OR REPLACE FUNCTION lexical.concept_ref(p_ref text)
    RETURNS bytea
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    -- Resolve an external concept identifier to its content-addressed anchor
    -- entity, so callers can link things by ILI / WordNet synset key / frame
    -- name. Every shape is keyed off the SAME content hash the ingest
    -- decomposers used (laplace.word_id = laplace_content_root_id), so the anchor id is
    -- reconstructed, never resolved by rendered surface:
    --   * ILI id       'i68021'       -> the synset entity IS that hash
    --   * WordNet key   '05510358-n'  -> that hash is the offset-pos key
    --                                    entity; the synset (ILI) anchor is the
    --                                    HAS_SYNSET_KEY subject pointing at it
    --   * frame / other 'Self_motion' -> the category entity IS that hash
    -- Returns NULL when the identifier is empty or the key has no ILI mapping.
    WITH norm AS (SELECT NULLIF(btrim(p_ref), '') AS r)
    SELECT CASE
        WHEN (SELECT r FROM norm) IS NULL THEN NULL
        WHEN (SELECT r FROM norm) ~ '^[0-9]{8}-[nvasr]$'
            -- Ranked, not arbitrary: nothing forbids two anchors claiming one
            -- offset-pos key (a partial or double seed produces exactly that), and
            -- unordered this returned whichever the index reached first. Strongest
            -- standing claim wins; the id breaks the tie so the answer is stable.
            THEN (SELECT c.subject_id FROM laplace.consensus c
                  WHERE c.object_id = laplace.word_id((SELECT r FROM norm))
                    AND c.type_id = laplace.relation_type_id('HAS_SYNSET_KEY')
                    -- Standing claim only: a fully-refuted HAS_SYNSET_KEY is not
                    -- a mapping (Copilot #918). Non-positive eff_mu ⇒ NULL.
                    AND consensus.eff_mu(c.rating, c.rd) > 0
                  ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.subject_id
                  LIMIT 1)
        ELSE laplace.word_id((SELECT r FROM norm))
    END
$$;
DROP FUNCTION IF EXISTS laplace.concept_members(bytea);
CREATE OR REPLACE FUNCTION lexical.concept_members(p_concept bytea)
    RETURNS TABLE(member bytea, kind text, mu numeric, witnesses bigint)
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    -- Every entity linked to an anchor (a synset/ILI concept or a FrameNet
    -- frame), pivoting only on ids. Three content-addressed bridge kinds:
    --   synonym : member --IS_SYNONYM_OF--> synset
    --   sense   : member --HAS_SENSE--> sense --IS_SENSE_OF--> synset
    --   frame   : member --EVOKES_FRAME--> frame
    -- Because the pivot is the anchor id, membership crosses language and
    -- surface for free (an English and a French lemma on the same ILI-seeded
    -- synset are both members). Pure id logic -- no realize.render_text/label here; the
    -- caller renders survivors at the display boundary.
    SELECT c.subject_id, 'synonym'::text, consensus.eff_mu_display(c.rating, c.rd), c.witness_count
    FROM laplace.v_consensus_unrefuted c
    WHERE c.object_id = p_concept AND c.type_id = laplace.relation_type_id('IS_SYNONYM_OF')
    UNION ALL
    SELECT hs.subject_id, 'sense'::text, consensus.eff_mu_display(hs.rating, hs.rd), hs.witness_count
    FROM laplace.v_consensus_unrefuted so
    JOIN laplace.v_consensus_unrefuted hs ON hs.object_id = so.subject_id
                     AND hs.type_id = laplace.relation_type_id('HAS_SENSE')
    WHERE so.object_id = p_concept AND so.type_id = laplace.relation_type_id('IS_SENSE_OF')
    UNION ALL
    -- A source-owned lexical member (for example VerbNet_Member) carries
    -- EVOKES_FRAME at its natural grain and exposes its surface through
    -- HAS_NAME_ALIAS. Preserve the public surface-member contract without
    -- requiring a duplicate surface->frame testimony edge.
    SELECT COALESCE(n.object_id, c.subject_id), 'frame'::text,
           consensus.eff_mu_display(c.rating, c.rd), c.witness_count
    FROM laplace.v_consensus_unrefuted c
    LEFT JOIN laplace.v_consensus_unrefuted n
     ON n.subject_id = c.subject_id
     AND n.type_id = ANY (consensus.relation_set_ids('NAME_ALIAS_EDGE'))
    WHERE c.object_id = p_concept AND c.type_id = laplace.relation_type_id('EVOKES_FRAME')
$$;
DROP FUNCTION IF EXISTS laplace.concept_peers(bytea, int);
CREATE OR REPLACE FUNCTION lexical.concept_peers(p_word bytea, p_limit int DEFAULT 24)
    RETURNS TABLE(peer text, kind text, strength double precision)
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    -- Words related to p_word through a shared content-addressed anchor -- a
    -- synset/ILI concept or a FrameNet frame. Surface- and language-independent
    -- because the bridge is the anchor id, not any rendered string: two words
    -- link iff they attach to the same anchor entity. Ranking is pure id/mu;
    -- realize.label() runs once per surviving row, past the LIMIT, at the boundary.
    WITH me AS (SELECT lexical.lexical_peers(p_word) AS ids),
    self AS (SELECT unnest(ids) AS id FROM me),
    -- Source-owned lexical entries carry their semantic edges; the queried
    -- content surface reaches those entries through the inverse alias edge.
    semantic_self AS (
        SELECT id FROM self
        UNION
        SELECT n.subject_id
        FROM self s
        JOIN laplace.v_consensus_unrefuted n
          ON n.object_id = s.id
         AND n.type_id = ANY (consensus.relation_set_ids('NAME_ALIAS_EDGE'))
    ),
    anchors AS (
        SELECT DISTINCT c.object_id AS anchor
        FROM semantic_self s JOIN laplace.v_consensus_unrefuted c ON c.subject_id = s.id
        WHERE c.type_id IN (laplace.relation_type_id('IS_SYNONYM_OF'), laplace.relation_type_id('EVOKES_FRAME'))
          AND c.object_id IS NOT NULL
        UNION
        SELECT DISTINCT so.object_id
        FROM self s
        JOIN laplace.v_consensus_unrefuted hs ON hs.subject_id = s.id AND hs.type_id = laplace.relation_type_id('HAS_SENSE')
        JOIN laplace.v_consensus_unrefuted so ON so.subject_id = hs.object_id
                         AND so.type_id = laplace.relation_type_id('IS_SENSE_OF')
    ),
    -- Set-based member expansion: one reverse-edge join per bridge kind over
    -- ALL anchors at once (consensus_object_type_btree — every join here is
    -- object_id = anchor AND type_id = literal, the composite's exact shape;
    -- the single-column consensus_object_btree was retired 2026-08-13 as its
    -- strict prefix), replacing the per-anchor
    -- lexical.concept_members() CROSS JOIN LATERAL that re-ran the same three lookups
    -- 181x for one word (measured 55s -> sub-second). Same three bridges.
    members AS (
        SELECT c.subject_id AS member, 'synonym'::text AS kind, consensus.eff_mu_display(c.rating, c.rd) AS mu
        FROM anchors a JOIN laplace.v_consensus_unrefuted c ON c.object_id = a.anchor
                          AND c.type_id = laplace.relation_type_id('IS_SYNONYM_OF')
        UNION ALL
        SELECT hs.subject_id, 'sense'::text, consensus.eff_mu_display(hs.rating, hs.rd)
        FROM anchors a JOIN laplace.v_consensus_unrefuted so ON so.object_id = a.anchor
                          AND so.type_id = laplace.relation_type_id('IS_SENSE_OF')
                       JOIN laplace.v_consensus_unrefuted hs ON hs.object_id = so.subject_id
                          AND hs.type_id = laplace.relation_type_id('HAS_SENSE')
        UNION ALL
        SELECT COALESCE(n.object_id, c.subject_id), 'frame'::text,
               consensus.eff_mu_display(c.rating, c.rd)
        FROM anchors a JOIN laplace.v_consensus_unrefuted c ON c.object_id = a.anchor
                          AND c.type_id = laplace.relation_type_id('EVOKES_FRAME')
        LEFT JOIN laplace.v_consensus_unrefuted n ON n.subject_id = c.subject_id
                          AND n.type_id = ANY (consensus.relation_set_ids('NAME_ALIAS_EDGE'))
    ),
    peers AS (
        SELECT m.member, m.kind, max(m.mu) AS mu
        FROM members m
        WHERE m.member <> ALL (SELECT id FROM self)
        GROUP BY m.member, m.kind
    ),
    -- Top-mu PER kind, not global: FrameNet frames have huge, high-mu
    -- membership that otherwise buries the synonym/sense peers a caller
    -- actually wants. row_number() per kind surfaces the best of each bridge.
    ranked AS (
        SELECT member, kind, mu,
               row_number() OVER (PARTITION BY kind ORDER BY mu DESC NULLS LAST, member) AS rk
        FROM peers
    ), survivors AS MATERIALIZED (
        SELECT * FROM ranked WHERE rk <= p_limit
    ), ids AS MATERIALIZED (
        SELECT COALESCE(array_agg(DISTINCT member ORDER BY member), '{}'::bytea[]) AS a FROM survivors
    ), labels AS MATERIALIZED (
        SELECT i.id, i.txt
        FROM ids,
             LATERAL ROWS FROM (
                 unnest(ids.a), unnest(realize.label_batch(ids.a))
             ) AS i(id, txt)
    )
    SELECT l.txt AS peer, r.kind, (r.mu::double precision) AS strength
    FROM survivors r JOIN labels l ON l.id = r.member
    WHERE NULLIF(btrim(l.txt), '') IS NOT NULL
    ORDER BY r.kind, r.mu DESC NULLS LAST, l.txt
$$;
CREATE OR REPLACE FUNCTION laplace.fake_tier_band_count()
RETURNS bigint
LANGUAGE sql
STABLE
    AS $$
    SELECT count(*)::bigint FROM laplace.entities WHERE tier IN (247, 248, 250);
$$;
-- Violations of the identity law, as the law actually states it.
--
-- Identical content has one id across tiers and sources. Tier is a floor rather than
-- an input to the content hash (docs/specs/05_Substrate_Invariants.txt).
--
-- This function checked ONE thing: that tier fell in 0..255. That is a column
-- range check, not the identity law. It returned zero rows on a substrate holding
-- 5,063 entities stored at TWO tiers each — 10,126 rows for 5,063 entities — and
-- so reported clean while the law was broken. A detector that cannot fail is
-- worse than no detector: it is a green light over the exact thing it is named
-- for.
--
-- The checks now:
--
--   multi_tier_entity      one content id with rows at more than one tier. The id
--                          is correct (content-addressed, tier never in the hash);
--                          the DUPLICATION is the violation. Observed as 2+3
--                          pairs: SemLink staged concept identifiers at word tier
--                          while PropBank/VerbNet/FrameNet staged the same
--                          identifiers at sentence tier, so one entity ended up
--                          with two rows carrying two different decompositions
--                          (mince.01 as m|i|n|c|e|.|0|1 and as mince|.|01).
--
--   ambiguous_physicality  one (entity_id, type, id) carrying MORE THAN ONE
--                          distinct trajectory. A physicality id must be a
--                          function of what it holds; when it is not, any
--                          DISTINCT ON over that key is settled by the query
--                          PLAN. Not hypothetical: it made constituents_closure
--                          return an 8-point decomposition for an id alone and a
--                          3-point one for the same id inside a 500-id batch, so
--                          render_text_batch produced different text depending on
--                          what else was in the array, and every realize_batch
--                          consumer inherited it.
--
--   dangling_entity_type   an entities.type_id with no entities row of its own.
--                          Nothing can render or describe such a type, so every
--                          entity wearing it is untypeable at read time. Four of
--                          them type 16,063 entities here, and none is a named
--                          constant — 958 string literals across Decomposers and
--                          Substrate hash to none of them, so the ids are computed
--                          from data at runtime and the type entity is simply
--                          never minted.
--
--   tier_out_of_range      the original range check, kept.
--
-- Reports ids, not counts, so a caller can act on them. Deliberately unbounded: a
-- violation list that silently truncates is the same failure as a detector that
-- cannot fail.
CREATE OR REPLACE FUNCTION laplace.identity_law_violations()
RETURNS TABLE(id bytea, tier smallint, reason text)
LANGUAGE sql
STABLE
    AS $$
    SELECT e.id, e.tier, 'tier_out_of_range'::text
    FROM laplace.entities e
    WHERE e.tier < 0 OR e.tier >= 256

    UNION ALL

    -- Same content id stored at more than one tier: one entity, N rows.
    SELECT e.id, e.tier, 'multi_tier_entity'::text
    FROM laplace.entities e
    JOIN (SELECT d.id FROM laplace.entities d
          GROUP BY d.id HAVING count(*) > 1) dup ON dup.id = e.id

    UNION ALL

    -- One physicality key holding more than one distinct trajectory, so the key
    -- does not determine its content and reads over it are plan-dependent.
    SELECT p.entity_id, NULL::smallint, 'ambiguous_physicality'::text
    FROM (SELECT ph.entity_id, ph.type, ph.id
          FROM laplace.physicalities ph
          WHERE ph.trajectory IS NOT NULL
          GROUP BY ph.entity_id, ph.type, ph.id
          HAVING count(DISTINCT public.ST_AsBinary(ph.trajectory)) > 1) p

    UNION ALL

    -- A type_id in use that was never minted as an entity: unrenderable by
    -- construction. Reported once per dangling TYPE, not once per entity wearing
    -- it, so the row count stays proportional to the defect rather than to the
    -- corpus.
    SELECT DISTINCT e.type_id, NULL::smallint, 'dangling_entity_type'::text
    FROM laplace.entities e
    WHERE NOT EXISTS (SELECT 1 FROM laplace.entities t WHERE t.id = e.type_id)
$$;
-- BEGIN ATOMIC: GH #764. No SET search_path — keeps `= ANY(...)` inlinable.
-- Identity helpers stay in the extension schema (laplace); purpose_schemas notes
-- the family has not moved yet. Signature unchanged, so CREATE OR REPLACE alone
-- suffices — the pre-qualification DROP went with the other ten in #1004.
CREATE OR REPLACE FUNCTION laplace.is_compositional_type(p_type_id bytea)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
BEGIN ATOMIC
    SELECT p_type_id = ANY(laplace.compositional_type_ids());
END;
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION laplace.compositional_tier_distribution()
RETURNS TABLE(tier smallint, n bigint)
LANGUAGE sql
STABLE
BEGIN ATOMIC
    -- `= ANY(compositional_type_ids())` (not the is_compositional_type() wrapper): the array
    -- evaluates ONCE and entities_type_btree serves the membership probe, instead of a per-row
    -- function call that recomputes 5 BLAKE3 hashes for every entity row (100M+).
    SELECT e.tier, count(*)::bigint
    FROM laplace.entities e
    WHERE e.type_id = ANY(laplace.compositional_type_ids())
    GROUP BY e.tier
    ORDER BY e.tier;
END;
-- substrate_health() is called on the SEED and CI paths (db-reset, qa-isolated,
-- decomposer-gate-check.py, substrate-audit.sql, the MCP health tool). It must stay
-- cheap, and for one commit it was not: #721/#722 gave identity_law_violations() its
-- real body -- a GROUP BY over every entity, a NOT EXISTS over every entity, and
-- count(DISTINCT ST_AsBinary(trajectory)) over every physicality, which serialises
-- every trajectory to binary and hash-aggregates on it. substrate_health() counted
-- that. A leaf function changed cost class and its callers were never read.
--
-- The audit itself is correct and stays exactly as it is. What was wrong is running a
-- full-corpus audit inside a health check on a table that grows all through an ingest.
--
-- So the deep pass is OPT-IN. Default is the cheap check; identity_violations comes
-- back NULL, not 0, because "not checked" and "checked, none found" are different
-- claims and collapsing them is how the detector became a green light in the first
-- place. deep_checked says which one you got.
DROP FUNCTION IF EXISTS laplace.substrate_health();
DROP FUNCTION IF EXISTS laplace.substrate_health(boolean);

CREATE OR REPLACE FUNCTION laplace.substrate_health(p_deep boolean DEFAULT false)
RETURNS TABLE(
    ok boolean,
    fake_tier_bands bigint,
    identity_violations bigint,
    bootstrap_entities bigint,
    deep_checked boolean
)
LANGUAGE sql
STABLE
    AS $$
    -- Each verification scan runs exactly once: the planner does not
    -- common-subexpression-eliminate independent scalar subqueries in one
    -- targetlist, so deriving `ok` from the scanned columns (not re-invoking
    -- the scans inside the boolean) halves the entities passes per call.
    WITH scans AS (
        SELECT
            laplace.fake_tier_band_count() AS fake_tier_bands,
            CASE WHEN p_deep
                 THEN (SELECT count(*) FROM laplace.identity_law_violations())
            END AS identity_violations,
            (SELECT count(*) FROM laplace.entities) AS bootstrap_entities,
            EXISTS (
                SELECT 1 FROM laplace.entities
                WHERE id = public.laplace_hash128_blake3('substrate/source/SubstrateCanonical/v1'::bytea)
            ) AS canonical_source_present
    )
    SELECT
        -- A NULL identity_violations must never read as "clean": IS NOT DISTINCT FROM 0
        -- would do exactly that. Unchecked contributes nothing to ok, and deep_checked
        -- tells the caller the verdict is partial.
        (s.fake_tier_bands = 0
         AND s.canonical_source_present
         AND (NOT p_deep OR s.identity_violations = 0)) AS ok,
        s.fake_tier_bands,
        s.identity_violations,
        s.bootstrap_entities,
        p_deep AS deep_checked
    FROM scans s;
$$;
-- Leading 64 bits of a content id as bigint. One shared lo64 helper so seed /
-- advisory-lock / walk RNG sites do not open-code encode+bit casts (GH #468).
-- BEGIN ATOMIC: body is parsed at create time so pg_depend records the call
-- graph (GH #764 beachhead — string bodies record zero deps).
CREATE OR REPLACE FUNCTION laplace.hash128_lo(p_id bytea)
    RETURNS bigint
    LANGUAGE sql
    IMMUTABLE
    STRICT
    PARALLEL SAFE
BEGIN ATOMIC
    SELECT ('x' || encode(substring(p_id FOR 8), 'hex'))::bit(64)::bigint;
END;
-- Configured tier-0 atom window N (GH #813). Never a SQL literal — the C
-- binding reads LAPLACE_PERFCACHE_RECORD_COUNT from the perfcache format header.
-- No DROP: atom_census() BEGIN ATOMIC depends on this; DROP would fail the
-- extension upgrade (GH #764). CREATE OR REPLACE is enough for the C binding.
CREATE OR REPLACE FUNCTION laplace.atom_window()
    RETURNS bigint
    LANGUAGE C
    IMMUTABLE
    PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_atom_window';
-- Tier-0 invariant as an operation (GH #813 first job).
-- atom_window comes from the format constant; tier0_count from entity_count.
-- over_window > 0 means non-atoms were minted at the atom layer.
-- unresolvable_ids stays 0 here — a full codepoint_for_id sweep is O(window)
-- and is a follow-on when a gate needs the NULL-label count.
-- BEGIN ATOMIC: GH #764 beachhead.
CREATE OR REPLACE FUNCTION laplace.atom_census()
    RETURNS TABLE(
        tier0_count bigint,
        atom_window bigint,
        over_window bigint,
        unresolvable_ids bigint)
    LANGUAGE sql
    STABLE
BEGIN ATOMIC
    WITH w AS (SELECT laplace.atom_window() AS n),
         t AS (SELECT ops.entity_count(laplace.entity_type_id('Codepoint')) AS n)
    SELECT t.n,
           w.n,
           greatest(0, t.n - w.n),
           0::bigint
    FROM w, t;
END;
-- What shape did this lane write? (GH #813). Counts entities first-observed by
-- the source, grouped by tier — the cheap index path on first_observed_by, not
-- a join across attestations. Answers the chess-vs-vocabulary tier-2 question
-- without hand-rolled GROUP BY. BEGIN ATOMIC: GH #764 beachhead.
DROP FUNCTION IF EXISTS laplace.source_tier_census(bytea);

CREATE OR REPLACE FUNCTION ops.source_tier_census(p_source bytea)
    RETURNS TABLE(tier smallint, entities bigint)
    LANGUAGE sql
    STABLE
    PARALLEL SAFE
BEGIN ATOMIC
    SELECT e.tier, count(*)::bigint
    FROM laplace.entities e
    WHERE e.first_observed_by = p_source
    GROUP BY e.tier
    ORDER BY e.tier;
END;
-- Ranked surface sample for a source×tier (GH #813). Census answers "how many";
-- this answers "what do they look like?" — observation_count from that source's
-- attestations (fold input), not LIMIT-without-ORDER over entities.
--
-- Filter at the requested source×tier grain BEFORE ranking. The former plan took
-- an invented max(limit×200, 4000) attestation head, then discarded subjects that
-- did not belong to the source/tier. Besides doing unrelated work, it could still
-- underfill whenever valid rows fell outside that guess. The source index drives the
-- evidence side and entity identity decides admission before the exact aggregate.
-- Labels still run once over the final caller-sized set.
-- BEGIN ATOMIC: GH #764 beachhead.
DROP FUNCTION IF EXISTS laplace.surface_sample(bytea, smallint, int);

CREATE OR REPLACE FUNCTION ops.surface_sample(
        p_source bytea,
        p_tier smallint,
        p_limit int DEFAULT 20)
    RETURNS TABLE(
        entity_id bytea,
        surface text,
        type_name text,
        observations bigint)
    LANGUAGE sql
    STABLE
BEGIN ATOMIC
    WITH kept AS (
        SELECT a.subject_id AS id,
               e.type_id,
               sum(a.observation_count)::bigint AS observations
        FROM laplace.attestations a
        JOIN laplace.entities e
          ON e.id = a.subject_id
         AND e.tier = p_tier
         AND e.first_observed_by = p_source
        WHERE a.source_id = p_source
          AND consensus.relation_canonical(a.subject_id) IS NULL
        GROUP BY a.subject_id, e.type_id
        ORDER BY sum(a.observation_count) DESC, a.subject_id
        LIMIT p_limit
    ), numbered AS (
        SELECT k.*, row_number() OVER (ORDER BY k.observations DESC, k.id) AS ix
        FROM kept k
    ),
    ids AS (
        SELECT array_agg(v.id ORDER BY v.ord) AS a
        FROM (
            SELECT k.id, k.ix * 2 - 1 AS ord FROM numbered k
            UNION ALL
            SELECT k.type_id, k.ix * 2 FROM numbered k
        ) v
    ),
    lbl AS (
        SELECT realize.batch(i.a, NULL) AS l FROM ids i
    )
    SELECT k.id,
           COALESCE(NULLIF(lbl.l[k.ix * 2 - 1], ''), 'Unrealized entity'),
           COALESCE(NULLIF(lbl.l[k.ix * 2], ''), 'Unrealized type'),
           k.observations
    FROM numbered k CROSS JOIN lbl
    ORDER BY k.observations DESC, k.id;
END;
DO $idem$ BEGIN
    CREATE TYPE intent_preflight_result AS (
        entity_exists bytea,
        phys_exists   bytea,
        att_exists    bytea
    );
EXCEPTION WHEN duplicate_object THEN NULL;
END $idem$;
CREATE OR REPLACE FUNCTION laplace.intent_preflight(
    entity_ids bytea[],
    phys_ids   bytea[],
    att_ids    bytea[])
    RETURNS intent_preflight_result
    AS 'laplace_substrate', 'pg_laplace_intent_preflight'
    LANGUAGE C STABLE;
DO $do$
DECLARE
    obj text;
BEGIN
    FOREACH obj IN ARRAY ARRAY[
        'TABLE laplace.content_pairs',
        'PROCEDURE laplace.rebuild_content_index(int)',
        'PROCEDURE laplace.rebuild_content_index_deep()',
        'PROCEDURE laplace.rebuild_content_pairs(int)']
    LOOP
        BEGIN
            EXECUTE format('ALTER EXTENSION %I DROP %s', 'laplace_substrate', obj);
        EXCEPTION WHEN OTHERS THEN
            NULL;  
        END;
    END LOOP;
    EXECUTE 'DROP TABLE IF EXISTS laplace.content_pairs';
    EXECUTE 'DROP TABLE IF EXISTS laplace.content_index';
    EXECUTE 'DROP TABLE IF EXISTS laplace.constituency_edge';
    EXECUTE 'DROP PROCEDURE IF EXISTS laplace.rebuild_content_index(int)';
    EXECUTE 'DROP PROCEDURE IF EXISTS laplace.rebuild_content_index_deep()';
    EXECUTE 'DROP PROCEDURE IF EXISTS laplace.rebuild_content_pairs(int)';
    
    
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.entity_trajectory_plane(bytea[], int, int)';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.cooccurrence_scan(int, bytea[])';
END $do$;

-- 2026-07-29: the generation corpus cache and its pair tables are RETIRED.
-- gen_corpus rebuilt the trajectories into a per-backend RAM suffix array from a
-- 97M-row scan (46 min before generation.generate() emitted a token); trajectory_pairs
-- persisted the same statistics to disk behind a corpus fingerprint. Both were
-- second bodies for what laplace.physicalities.trajectory holds exactly-invertibly.
-- Replaced by generation.trajectory_continuations() (S6, path-bounded), generation.steer_candidates()
-- (S7), and relation_plane's inline export-time aggregation.
DO $do$
DECLARE
    obj text;
BEGIN
    FOREACH obj IN ARRAY ARRAY[
        'TABLE laplace.trajectory_pairs',
        'TABLE laplace.trajectory_pairs_meta',
        'FUNCTION laplace.cooccurrence_scan(int)',
        'FUNCTION laplace.cooccurrence_scan(int, bytea[])',
        'FUNCTION laplace.trajectory_cooccurrence(int)',
        'FUNCTION laplace.trajectory_cooccurrence_by_stride(int)',
        'FUNCTION laplace.trajectory_pairs_ensure(int)',
        'FUNCTION laplace.trajectory_pairs_plane(bytea[], int)',
        'FUNCTION laplace.stream_reset()',
        'FUNCTION laplace.stream_stats()',
        'FUNCTION laplace.corpus_sentence_constituents(text, int)',
        'FUNCTION laplace.corpus_sentence_constituents_since(text, int, timestamptz)']
    LOOP
        BEGIN
            EXECUTE format('ALTER EXTENSION %I DROP %s', 'laplace_substrate', obj);
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END LOOP;
    EXECUTE 'DROP TABLE IF EXISTS laplace.trajectory_pairs';
    EXECUTE 'DROP TABLE IF EXISTS laplace.trajectory_pairs_meta';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.cooccurrence_scan(int)';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.cooccurrence_scan(int, bytea[])';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.trajectory_cooccurrence(int)';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.trajectory_cooccurrence_by_stride(int)';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.trajectory_pairs_ensure(int)';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.trajectory_pairs_plane(bytea[], int)';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.stream_reset()';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.stream_stats()';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.corpus_sentence_constituents(text, int)';
    EXECUTE 'DROP FUNCTION IF EXISTS laplace.corpus_sentence_constituents_since(text, int, timestamptz)';
END $do$;
-- 2026-07-09 vocab pushdown: the foundry read every consensus row of a type
-- over the wire so the client could keep the ~1% whose endpoints are in the
-- synthesis vocab (12 relation heads = 27.5M rows scanned, 358K kept, 550s of a
-- 608s synthesis). p_vocab probes consensus_type_subject_btree instead; the type
-- id is resolved into a local FIRST (a variable is a bound parameter and
-- therefore an index condition — Rule #4; a function call in the qual is
-- not, lesson L12).
DROP FUNCTION IF EXISTS laplace.relation_plane(text, text, int, bytea[]);
CREATE OR REPLACE FUNCTION generation.relation_plane(p_family text, p_name text, p_arg int DEFAULT NULL,
        p_vocab bytea[] DEFAULT NULL)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    g int;
    v_type bytea;
BEGIN
    IF p_family = 'consensus' THEN
        v_type := laplace.relation_type_id(p_name);
        IF p_vocab IS NULL THEN
            RETURN QUERY
            SELECT c.subject_id, c.object_id,
                   consensus.walk_edge_weight(c.rating, c.rd)
            FROM laplace.consensus c
            WHERE c.type_id = v_type AND c.object_id IS NOT NULL;
        ELSE
            RETURN QUERY
            WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u)
            SELECT c.subject_id, c.object_id,
                   consensus.walk_edge_weight(c.rating, c.rd)
            FROM v
            JOIN laplace.consensus c ON c.type_id = v_type AND c.subject_id = v.id
            JOIN v vo ON vo.id = c.object_id
            WHERE c.object_id IS NOT NULL;
        END IF;
        RETURN;
    END IF;

    IF p_family <> 'traj' THEN
        RAISE EXCEPTION 'relation_plane: unknown family % (consensus | traj)', p_family;
    END IF;

    g := CASE p_name
             WHEN 'next'   THEN 1
             WHEN 'gap'    THEN COALESCE(p_arg, 1)
             WHEN 'window' THEN COALESCE(p_arg, 4)
             ELSE NULL
         END;
    IF g IS NULL THEN
        RAISE EXCEPTION 'relation_plane: unknown traj plane % (next | gap | window)', p_name;
    END IF;

    -- Pairs are computed HERE, at export time, from the trajectories themselves.
    -- The pour is corpus-bounded by definition — it renders the whole consensus —
    -- so a full aggregation inside it is honest cost. What was NOT honest was a
    -- maintained trajectory_pairs cache with a corpus fingerprint and rebuild
    -- guards: a second materialization of what laplace.physicalities.trajectory holds
    -- exactly-invertibly (§15 — a second body is a future divergence; §9 — the
    -- trajectory IS the sequence). gen_corpus and trajectory_pairs are deleted;
    -- this inline scan is the one remaining whole-corpus reader, and it lives on
    -- the export path where whole-corpus is the contract.
    --
    -- next/gap = pairs at exactly stride g; window = all strides 1..g. One body,
    -- bounded by (lo, hi). subject_total matches the retired semantics: per
    -- (subject, exact gap) for next/gap, per subject across the window for
    -- window. Separators are excluded through generation.separator_ids() — one body for
    -- that fact too — so pairs count CONTENT adjacency, as the corpus stream did.
    RETURN QUERY
    WITH bounds AS (
        SELECT CASE WHEN p_name = 'window' THEN 1 ELSE g END AS lo, g AS hi
    ),
    sepset AS MATERIALIZED (
        SELECT COALESCE(generation.separator_ids(), ARRAY[]::bytea[]) AS ids
    ),
    seq AS (
        SELECT w.id AS root, c.ordinal + rs.i - 1 AS ordinal, c.entity_id AS tok
        FROM laplace.v_word_points w
        CROSS JOIN LATERAL public.laplace_trajectory_constituents(w.trajectory) c
        CROSS JOIN LATERAL generate_series(1, GREATEST(c.run_length, 1)) rs(i)
        WHERE w.type_id IN (realize.canonical_id('Sentence'), realize.canonical_id('Document'))
          AND w.trajectory IS NOT NULL
    ),
    content AS (
        SELECT s.root, s.tok,
               row_number() OVER (PARTITION BY s.root ORDER BY s.ordinal) AS cord
        FROM seq s CROSS JOIN sepset x
        WHERE NOT (s.tok OPERATOR(pg_catalog.=) ANY (x.ids))
    ),
    pairs AS (
        SELECT a.tok AS s, b.tok AS o, count(*) AS cnt
        FROM content a
        JOIN bounds ON true
        JOIN content b ON b.root = a.root
                      AND b.cord BETWEEN a.cord + bounds.lo AND a.cord + bounds.hi
        GROUP BY a.tok, b.tok
    ),
    tot AS (
        SELECT p.s, sum(p.cnt) AS subject_total FROM pairs p GROUP BY p.s
    )
    SELECT p.s, p.o, p.cnt::double precision / t.subject_total
    FROM pairs p JOIN tot t ON t.s = p.s;
END;
$$;
DROP FUNCTION IF EXISTS laplace.entity_relation_plane(bytea[], text[], int);
CREATE OR REPLACE FUNCTION generation.entity_relation_plane(
        p_vocab bytea[], p_rel_names text[], p_degree_cap int DEFAULT 48)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
         t(tid) AS (SELECT laplace.relation_type_id(n) FROM unnest(p_rel_names) AS n),
         edges AS (
             -- P5 Glicko-complete weight (doc 14 M5): already neutral-centered
             -- (signed) directly from the folded Glicko state.
             SELECT c.subject_id, c.object_id,
                    consensus.walk_edge_weight(c.rating, c.rd) AS w
             FROM v
             JOIN laplace.consensus c ON c.subject_id = v.id
             JOIN t           ON t.tid = c.type_id
             JOIN v vo        ON vo.id = c.object_id

         ),
         capped AS (
             SELECT e.subject_id, e.object_id, e.w,
                    row_number() OVER (PARTITION BY e.subject_id
                                       ORDER BY abs(e.w) DESC, e.object_id) AS rn
             FROM edges e
         )
    SELECT c.subject_id, c.object_id, c.w FROM capped c WHERE c.rn <= p_degree_cap
$$;
DROP FUNCTION IF EXISTS laplace.consensus_layer_plane(bytea[], float8, float8, int);
CREATE OR REPLACE FUNCTION generation.consensus_layer_plane(
        p_vocab bytea[], p_rank_lo float8, p_rank_hi float8, p_degree_cap int DEFAULT 48)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision, layer_rank double precision)
    LANGUAGE sql STABLE PARALLEL RESTRICTED  AS $$
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
         -- MATERIALIZED is load-bearing here: edges is referenced twice below
         -- (rk's DISTINCT type_id scan and ranked's join), so the fence avoids
         -- re-executing the v->consensus->v join. Do not strip.
         edges AS MATERIALIZED (
             SELECT c.subject_id, c.object_id, c.rating, c.rd, c.type_id
             FROM v
             JOIN laplace.consensus c ON c.subject_id = v.id
             JOIN v vo        ON vo.id = c.object_id
         ),
         rk AS (
             SELECT d.type_id, r.rank
             FROM (SELECT DISTINCT type_id FROM edges) d
             CROSS JOIN LATERAL consensus.relation_rank_resolved(d.type_id) AS r(rank)
             WHERE r.rank IS NOT NULL AND r.rank BETWEEN p_rank_lo AND p_rank_hi
         ),
         -- Signed Glicko expectation of the folded rating/RD.
         ranked AS (
             SELECT e.subject_id, e.object_id,
                    consensus.walk_edge_weight(e.rating, e.rd) AS w,
                    rk.rank AS rk
             FROM edges e JOIN rk ON rk.type_id = e.type_id
         ),
         capped AS (
             SELECT r.subject_id, r.object_id, r.w, r.rk,
                    row_number() OVER (PARTITION BY r.subject_id ORDER BY r.rk * abs(r.w) DESC, r.object_id) AS rn
             FROM ranked r
         )
    SELECT c.subject_id, c.object_id, c.w, c.rk FROM capped c WHERE c.rn <= p_degree_cap
$$;
DROP FUNCTION IF EXISTS laplace.consensus_layer_plane_masked(bytea[], bytea, int);
CREATE OR REPLACE FUNCTION generation.consensus_layer_plane_masked(
        p_vocab bytea[], p_band_mask bytea, p_degree_cap int DEFAULT 48)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision, layer_rank double precision)
    LANGUAGE sql STABLE PARALLEL RESTRICTED AS $$
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
         band_types AS (
             SELECT t.id, consensus.relation_rank_resolved(t.id) AS rank
             FROM unnest(consensus.relation_mask_types(p_band_mask)) AS t(id)
         ),
         edges AS (
             SELECT c.subject_id, c.object_id, c.rating, c.rd, c.type_id,
                    bt.rank
             FROM v
             JOIN laplace.consensus c ON c.subject_id = v.id
             JOIN v vo        ON vo.id = c.object_id
             JOIN band_types bt ON bt.id = c.type_id
             WHERE bt.rank IS NOT NULL
         ),
         -- Signed Glicko expectation of the folded rating/RD.
         ranked AS (
             SELECT e.subject_id, e.object_id,
                    consensus.walk_edge_weight(e.rating, e.rd) AS w,
                    e.rank AS rk
             FROM edges e
         ),
         capped AS (
             SELECT r.subject_id, r.object_id, r.w, r.rk,
                    row_number() OVER (PARTITION BY r.subject_id ORDER BY r.rk * abs(r.w) DESC, r.object_id) AS rn
             FROM ranked r
         )
    SELECT c.subject_id, c.object_id, c.w, c.rk FROM capped c WHERE c.rn <= p_degree_cap
$$;
DROP FUNCTION IF EXISTS laplace.consensus_type_plane(bytea[], int, bytea[]);
CREATE OR REPLACE FUNCTION generation.consensus_type_plane(
        p_vocab bytea[], p_degree_cap int DEFAULT 48, p_types bytea[] DEFAULT NULL)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision,
                  type_id bytea, layer_rank double precision)
    LANGUAGE sql STABLE PARALLEL RESTRICTED AS $$
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
         -- MATERIALIZED is load-bearing here: edges is referenced twice below
         -- (rk's DISTINCT type_id scan and ranked's join), so the fence avoids
         -- re-executing the v->consensus->v join. Do not strip.
         edges AS MATERIALIZED (
             SELECT c.subject_id, c.object_id, c.rating, c.rd, c.type_id
             FROM v
             JOIN laplace.consensus c ON c.subject_id = v.id
             JOIN v vo        ON vo.id = c.object_id
             WHERE (p_types IS NULL OR c.type_id = ANY(p_types))
         ),
         rk AS (
             SELECT d.type_id, r.rank
             FROM (SELECT DISTINCT type_id FROM edges) d
             CROSS JOIN LATERAL consensus.relation_rank_resolved(d.type_id) AS r(rank)
             WHERE r.rank IS NOT NULL
         ),
         -- Signed Glicko expectation of the folded rating/RD. Refuted edges go
         -- NEGATIVE (operator planes are sign-safe; the basis union clamps
         -- client-side via FoundryExport.PositivePart).
         ranked AS (
             SELECT e.subject_id, e.object_id,
                    consensus.walk_edge_weight(e.rating, e.rd) AS w,
                    e.type_id, rk.rank AS rk
             FROM edges e JOIN rk ON rk.type_id = e.type_id
         ),
         capped AS (
             SELECT r.subject_id, r.object_id, r.w, r.type_id, r.rk,
                    row_number() OVER (PARTITION BY r.subject_id, r.type_id
                                       ORDER BY abs(r.w) DESC, r.object_id) AS rn
             FROM ranked r
         )
    SELECT c.subject_id, c.object_id, c.w, c.type_id, c.rk
    FROM capped c WHERE c.rn <= p_degree_cap
$$;
-- 2026-07-09: `edges` must be MATERIALIZED. Inlined, the planner pushes the
-- rank filter into the consensus scan and evaluates relation_rank_resolved
-- (~27µs/call) on all 124M rows — 255-368s measured, in either function
-- language. Fenced, the vocab probe takes the indexed nestloop.
-- 2026-07-17: rank per DISTINCT type_id (≤189 governed types) instead of per
-- edge row (~369k calls ≈ 10s measured), same rk CTE as
-- consensus_layer_plane/consensus_type_plane. edges is referenced twice below
-- (rk's DISTINCT scan and summed's join) — the fence stays load-bearing.
DROP FUNCTION IF EXISTS laplace.consensus_adjacency(bytea[], int);
CREATE OR REPLACE FUNCTION generation.consensus_adjacency(
        p_vocab bytea[], p_degree_cap int DEFAULT 64)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE plpgsql STABLE PARALLEL RESTRICTED AS $$
BEGIN
    RETURN QUERY
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
         edges AS MATERIALIZED (
             SELECT c.subject_id, c.object_id, c.rating, c.rd, c.type_id
             FROM v
             JOIN laplace.consensus c ON c.subject_id = v.id
             JOIN v vo        ON vo.id = c.object_id
             WHERE c.object_id IS NOT NULL
         ),
         rk AS (
             SELECT d.type_id, r.rank
             FROM (SELECT DISTINCT type_id FROM edges) d
             CROSS JOIN LATERAL consensus.relation_rank_resolved(d.type_id) AS r(rank)
             WHERE r.rank IS NOT NULL
         ),
         -- Signed Glicko expectation of the folded state. Positivity is NOT
         -- clamped here — the basis union
         -- clamps client-side (FoundryExport.PositivePart); the unary operator
         -- plane keeps refutation as negative weight.
         --
         -- Rating/RD already summarize the complete witness history, so no
         -- second witness saturation or RD-decay parameter is applied here.
         summed AS (
             SELECT e.subject_id, e.object_id,
                    sum(rk.rank
                        * consensus.walk_edge_weight(e.rating, e.rd)) AS w
             FROM edges e
             JOIN rk ON rk.type_id = e.type_id
             GROUP BY e.subject_id, e.object_id
         ),
         capped AS (
             SELECT s.subject_id, s.object_id, s.w,
                    row_number() OVER (PARTITION BY s.subject_id ORDER BY abs(s.w) DESC, s.object_id) AS rn
             FROM summed s
             WHERE s.w <> 0
         )
    SELECT c.subject_id, c.object_id, c.w FROM capped c WHERE c.rn <= p_degree_cap;
END;
$$;
DROP FUNCTION IF EXISTS laplace.foundry_vocab(int);
DROP FUNCTION IF EXISTS generation.foundry_vocab(int);
CREATE OR REPLACE FUNCTION generation.foundry_vocab(
        p_size int, p_trajs int DEFAULT NULL)
    RETURNS TABLE(entity_id bytea, surface text, weight bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Pillar 5 (2026-07-20): seed frequency comes from the GEOMETRY, not from
    -- PRECEDES out-degree. Identical shape to corpus_word_vocab, which is already the
    -- geometry-native vocabulary source.
    --
    -- `d` is DOCUMENT frequency, not corpus frequency. This comment used to claim the
    -- latter, and it cannot be: ids are content hashes, physicality identity is
    -- (entity_id, type) with no laplace.source_id column, so a sentence occurring a million times
    -- is ONE row with ONE trajectory. `d` counts the distinct compositions a word appears
    -- in. True occurrence mass lives in testimony (laplace.attestations.observation_count folded
    -- into consensus.witness_count), and the text lane deliberately emits none, so there
    -- is nothing else to read -- this is the only frequency signal that exists. Rank
    -- accordingly, and do not describe it as corpus frequency again.
    --
    -- Role by TYPE, not tier, throughout. `tier = 2` was never "word": bootstrap mints
    -- relation types, trust classes, POS tags, sources and languages at tier 2 as well,
    -- so the seed vocabulary was admitting them; and single-grapheme words collapse to
    -- tier 0, so it dropped 'a' and 'I'. type_id is stamped at compose time and indexed.
    WITH traj AS (
        SELECT w.id AS entity_id, w.trajectory
        FROM laplace.v_word_points w
        WHERE w.type_id IN (realize.canonical_id('Sentence'), realize.canonical_id('Document'))
          AND w.trajectory IS NOT NULL
        -- Optional input work budget is explicit. NULL means the complete corpus;
        -- a caller asking for a sample owns and can report that truncation.
        ORDER BY w.id, w.physicality_id
        LIMIT p_trajs
    ),
    freq AS (
        SELECT tc.entity_id AS id, sum(GREATEST(tc.run_length, 1)) AS d
        FROM traj CROSS JOIN LATERAL laplace_trajectory_constituents(traj.trajectory) tc
        JOIN laplace.entities ew ON ew.id = tc.entity_id AND ew.type_id = realize.canonical_id('Word')
        GROUP BY tc.entity_id
    ),
    seeds AS (
        SELECT f.id, f.d
        FROM freq f JOIN laplace.entities e ON e.id = f.id AND e.type_id = realize.canonical_id('Word')
        ORDER BY f.d DESC LIMIT p_size
    ),
    closure AS (
        SELECT DISTINCT c.object_id AS id
        FROM laplace.consensus c
        JOIN seeds s ON s.id = c.subject_id
        JOIN laplace.entities e ON e.id = c.object_id AND e.type_id = realize.canonical_id('Word')
        WHERE c.object_id IS NOT NULL
          AND c.type_id IN (
              laplace.relation_type_id('IS_A'), laplace.relation_type_id('IS_SYNONYM_OF'),
              laplace.relation_type_id('RELATED_TO'), laplace.relation_type_id('HAS_PART'),
              laplace.relation_type_id('DERIVATIONALLY_RELATED'), laplace.relation_type_id('IS_COORDINATE_TERM_WITH'))
    ),
    ids AS (SELECT id FROM seeds UNION SELECT id FROM closure),
    
    
    
    
    
    
    ranked AS MATERIALIZED (
        SELECT i.id, COALESCE(f.d, 0) AS d,
               row_number() OVER (ORDER BY COALESCE(f.d, 0) DESC, i.id) AS rn
        FROM ids i LEFT JOIN freq f ON f.id = i.id
    ),
    pages AS MATERIALIZED (
        SELECT ((rn - 1) / GREATEST(p_size, 1)) AS page,
               array_agg(id ORDER BY rn) AS ids
        FROM ranked
        WHERE p_size > 0
        GROUP BY ((rn - 1) / GREATEST(p_size, 1))
    ),
    named AS (
        
        
        SELECT u.id, u.s, r.d
        FROM pages p
        CROSS JOIN LATERAL unnest(p.ids, realize.render_text_batch(p.ids))
             WITH ORDINALITY AS u(id, s, ord)
        JOIN ranked r ON r.id = u.id
    ),
    clean AS (
        SELECT DISTINCT ON (n.s) n.id, n.s, n.d
        FROM named n
        WHERE n.s IS NOT NULL AND btrim(n.s) <> '' AND NOT realize.is_all_whitespace(n.s)
          AND position(' ' IN n.s) = 0
        ORDER BY n.s, n.d DESC, n.id
    )
    SELECT c.id, c.s, c.d
    FROM clean c
    ORDER BY c.d DESC, c.id
    LIMIT GREATEST(p_size, 0)
$$;
DROP FUNCTION IF EXISTS laplace.grapheme_floor_vocab(int, int);
CREATE OR REPLACE FUNCTION generation.grapheme_floor_vocab(p_size int DEFAULT 512, p_words int DEFAULT 50000)
    RETURNS TABLE(entity_id bytea, surface text, weight bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    
    
    
    
    WITH t AS (
        SELECT w.trajectory
        FROM laplace.v_word_points w
        WHERE w.type_id = realize.canonical_id('Word')
          AND w.trajectory IS NOT NULL
        ORDER BY w.id LIMIT p_words
    ),
    g AS (
        SELECT tc.entity_id, tc.run_length
        FROM t CROSS JOIN LATERAL laplace_trajectory_constituents(t.trajectory) tc
    ),
    agg AS (
        
        
        SELECT g.entity_id, sum(GREATEST(g.run_length,1))::bigint AS cnt
        FROM g JOIN laplace.entities e ON e.id = g.entity_id AND e.type_id IN (realize.canonical_id('Codepoint'), realize.canonical_id('Grapheme'))
        GROUP BY g.entity_id
    ),
    named AS MATERIALIZED (
        SELECT a.entity_id, a.cnt
        FROM agg a
        ORDER BY a.cnt DESC, a.entity_id
    ), ids AS MATERIALIZED (
        SELECT array_agg(entity_id ORDER BY cnt DESC, entity_id) AS a FROM named
    ), rendered AS MATERIALIZED (
        SELECT i.id, i.s
        FROM ids,
             LATERAL ROWS FROM (
                 unnest(ids.a), unnest(realize.render_text_batch(ids.a))
             ) AS i(id, s)
    )
    SELECT n.entity_id, r.s, n.cnt
    FROM named n JOIN rendered r ON r.id = n.entity_id
    WHERE char_length(r.s) = 1 AND NOT realize.is_all_whitespace(r.s)
    ORDER BY n.cnt DESC, n.entity_id
    LIMIT GREATEST(p_size, 0)
$$;
DROP FUNCTION IF EXISTS laplace.grapheme_order(bytea[], int, int);
CREATE OR REPLACE FUNCTION generation.grapheme_order(p_vocab bytea[], p_words int DEFAULT 50000, p_gap int DEFAULT 1)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    
    
    
    
    
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
    t AS (
        
        
        
        
        -- Role by TYPE, not tier. `tier = 2` was never "word": bootstrap mints relation
        -- types, trust classes, POS tags, sources and languages at tier 2 too, so this
        -- was spelling out the grapheme runs of RelationType and Language laplace.entities. It
        -- also missed single-grapheme words, which collapse to tier 0.
        --
        -- Ranked by length rather than content hash (an arbitrary LIMIT is a missing
        -- ranking); DISTINCT ON dropped, since (entity_id, type) is already unique.
        SELECT w.id AS wid, w.trajectory
        FROM laplace.v_word_points w
        WHERE w.type_id = realize.canonical_id('Word')
          AND w.trajectory IS NOT NULL
        -- Sampling is by content hash, which is ARBITRARY -- an arbitrary LIMIT without
        -- an ordering is a missing ranking. The honest ranking is by trajectory length,
        -- but MEASURED 2026-08-01 that plans as a seq scan of every physicality partition
        -- plus a full sort (no index serves n_constituents), so it trades an arbitrary
        -- sample for an unusable one. Left arbitrary DELIBERATELY until an index exists
        -- that ingest is willing to pay for; the defect is recorded, not hidden.
        ORDER BY w.id, w.physicality_id
        LIMIT p_words
    ),
    g AS (
        
        
        
        
        SELECT t.wid, tc.ordinal AS ord, gs.i AS sub, tc.entity_id AS ch
        FROM t CROSS JOIN LATERAL laplace_trajectory_constituents(t.trajectory) tc
        CROSS JOIN LATERAL generate_series(1, GREATEST(tc.run_length, 1)) gs(i)
    ),
    bg AS (
        SELECT ch AS cur, lead(ch, p_gap) OVER (PARTITION BY wid ORDER BY ord, sub) AS nxt FROM g
    ),
    cnt AS (
        SELECT cur, nxt, count(*)::float8 AS c
        FROM bg WHERE nxt IS NOT NULL GROUP BY cur, nxt
    )
    SELECT b.cur, b.nxt, b.c
    FROM cnt b
    JOIN v vs ON vs.id = b.cur
    JOIN v vo ON vo.id = b.nxt
$$;
-- generation.separator_ids() -> every entity id that is a sequence separator rather than content.
--
-- ONE BODY FOR ONE TRUTH (§15). The category-name literals were previously typed
-- inline in corpus_whitespace_vocab_indices; a second call site copying them is the
-- divergence this law exists to prevent. Every caller resolves through here.
--
-- TWO TIERS, ONE RULE. A separator is an atom whose Unicode general category says
-- so, OR a grapheme cluster composed entirely of such atoms. The second arm is not
-- a special case: UAX#29 GB3 makes CR+LF a single grapheme, so the cluster is a
-- first-class entity at tier 1 and can never carry a category attestation of its
-- own -- categories are atom-level facts. Composition lifts the property (§3,
-- composition is Merkle), so bool_and over the realize.constituents IS the definition.
--
-- Measured on the foundation substrate 2026-07-29: 84 atoms + 1 grapheme (CRLF)
-- = 85 ids, 1.2 s for the whole set. Bounded by the alphabet, not by the corpus --
-- the same class of lookup as laplace.relation_type_id(), and explicitly NOT a corpus
-- cache. Nothing here scans ingested content.
--
-- NO RENDER FALLBACK. An earlier shape reached for realize.is_all_whitespace(render_text_
-- fast(...)) whenever a token had no category attestation. That was compensating
-- for the grapheme arm being missing, and it hid the reason: composites are
-- unattested BY CONSTRUCTION, not by incomplete seeding. Rendering to classify is
-- also the read-side law inverted -- classification is an indexed read on the id;
-- the realize.render is the cost.
--
-- SCRIPT HONESTY: Zs/Zl/Zp/Cc are the Unicode separator and control categories.
-- For a script that does not delimit with separator characters (Han, Thai,
-- Japanese) the set is simply empty for its atoms and the sequence is
-- content-contiguous -- the correct answer, not a silent failure.
DROP FUNCTION IF EXISTS laplace.separator_ids();
CREATE OR REPLACE FUNCTION generation.separator_ids()
    RETURNS bytea[]
    LANGUAGE sql STABLE AS $$
    -- THE CLUSTER ARM IS A HASH, NOT A SEARCH.
    --
    -- A separator-only grapheme cluster is alphabet-bounded, so it does not have to
    -- be DISCOVERED. Entity identity is content-addressed: laplace.word_id(text) is a
    -- BLAKE3 hash of the CONTENT, at every tier -- laplace.word_id(chr(32)) IS the space
    -- atom's id, verified byte-for-byte. CR+LF is not a special case: it is a
    -- composition of two codepoints, hashed exactly as 'as' is, and composition lifts
    -- the separator property (§3, composition is Merkle -- the bool_and this body used
    -- to compute WAS that definition). UAX#29 GB3 is only what makes CR+LF the one
    -- such composition that is a single grapheme cluster, so it is the one the corpus
    -- carries: laplace.word_id(chr(13)||chr(10)) = cafeb486a01baa2c1ee30a8b78e2ff4d,
    -- verified equal to the single non-atom id the previous body returned.
    --
    -- The previous body found that one id by scanning EVERY tier-1 entity with a
    -- trajectory and testing bool_and over its constituents. Measured: atoms arm
    -- 58 ms, whole function 9,450 ms warm -- the entire cost was rediscovering a
    -- constant. Its own comment already claimed the set was "bounded by the alphabet,
    -- not by the corpus"; it was not, and now it is.
    --
    -- STATED DIFFERENCE: the hash is unconditional, so CRLF is returned whether or not
    -- that cluster has been ingested yet. Callers use this set for MEMBERSHIP
    -- (id = ANY(separator_ids())), where an id no entity carries simply never matches.
    -- Bounded by construction is the property the callers need.
    --
    -- Approaches measured and rejected: a first-constituent index pre-filter returns
    -- 599,753 rows (a leading separator is common); structural.containers_of over the 84
    -- atoms costs 25.7 s and truncates at its 1,000-row cap.
    -- THE CATEGORY LOOKUP STAYS A NAME LOOKUP. Separator-ness is an ATTESTED fact
    -- resolved through laplace.canonical_names, never a derived hash: the id of a
    -- category entity is NOT required to equal blake3 of its name, and
    -- tests/sql/generation_corpus.sql proves it by minting
    -- blake3('test/corpus/zs-category') and registering it under the name
    -- 'unicode/category/Zs/v1'. Rewriting this filter as `object_id IN
    -- (realize.canonical_id(...))` passes on production data -- where the convention
    -- does hold, verified for 200,000 of 200,000 sampled rows -- and silently stops
    -- honouring the attested mapping. That regress test caught exactly that.
    --
    -- The cost was never this join; it was that canonical_names had ONE index, on id,
    -- so `name IN (...)` seq-scanned 3,387,109 rows (measured 2026-08-23: Parallel Seq
    -- Scan, 677,421 rows removed by filter, 50,638 buffers, 317 ms warm) on EVERY
    -- generation.trajectory_continuations and structural.geometry_successors_batch
    -- call -- once per generated token. canonical_names_name_btree fixes it at the
    -- table, for every caller, with the semantics untouched.
    WITH atoms AS (
        SELECT DISTINCT a.subject_id AS id
        FROM laplace.attestations a
        JOIN laplace.canonical_names cn ON cn.id = a.object_id
        WHERE a.type_id = laplace.relation_type_id('HAS_GENERAL_CATEGORY')
          AND cn.name IN ('unicode/category/Zs/v1',
                          'unicode/category/Zl/v1',
                          'unicode/category/Zp/v1',
                          'unicode/category/Cc/v1')
    )
    SELECT array_agg(id) FROM (
        SELECT id FROM atoms
        UNION
        SELECT laplace.word_id(chr(13) || chr(10))
    ) s
$$;
-- Witnessed adjacency over UNICODE ENTITIES: one row per (x, what sits between, y,
-- the composition that witnessed it).
--
-- NOTHING IS DELETED. An earlier form of this function removed separator entities
-- before the window. That hardcodes a Latin-script assumption: SPACE is an entity
-- like any other, it is not a delimiter to be stripped, and stripping it destroys
-- real content -- 'hot-tempered' is HYPHEN-MINUS between hot and tempered, and
-- 'hot, ' is COMMA then SPACE. What sits between is carried in sep_id, which is
-- what generation.trajectory_continuations already does. For a script that does not
-- delimit, sep_id is simply NULL and the pair is direct; no branch, no special case.
--
-- Order is fetched from the TRAJECTORY, never from an edge: text emits no PRECEDES
-- attestations, and PRECEDES is populated only by model ingestion.
--
-- IDS, NOT CONTENT. laplace_trajectory_constituent_ids returns the ordered id array
-- and is what physicalities_constituents_gin indexes, so a caller can select
-- trajectories by containment BEFORE any of this runs -- measured, the 346
-- trajectories containing both 'hot' and 'dog' come back in 1.6s by @> against 57s
-- for the unpack path. Positional access is array indexing; the row explosion is
-- only for the pairs actually emitted.
--
-- A sequence is itself an entity. 'hot dog' is ebffb84ed9cbad9821843b7c1b7ff0c2 at
-- tier 3, composing exactly [hot, SPACE, dog], with 904 consensus edges of its own;
-- 'hotdog' is different bytes and therefore a different id. Counting adjacency is
-- the weakest way to ask a question the merkle DAG answers by hash, so treat this
-- as a floor and prefer the composition where one exists.
DROP FUNCTION IF EXISTS generation.word_adjacency(bytea[], int, int);
CREATE OR REPLACE FUNCTION generation.word_adjacency(p_vocab bytea[], p_trajs int DEFAULT 100000,
                                                    p_gap int DEFAULT 1)
    RETURNS TABLE(subject_id bytea, sep_id bytea, object_id bytea, witness_id bytea)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
    sep AS MATERIALIZED (
        SELECT COALESCE(generation.separator_ids(), '{}'::bytea[]) AS ids
    ),
    -- SELECTED BY CONTENT, NOT BY SLICE. The previous form took p_trajs trajectories
    -- in content-hash order -- an arbitrary sample, which this file's ancestor
    -- recorded as a deliberate defect. Measured: 20,000 arbitrary trajectories yield
    -- ZERO 'hot SPACE dog' pairs in 65s, while the trajectories that actually contain
    -- both ids yield 35 in 13s. physicalities_constituents_gin indexes exactly this
    -- array, so containment is an index probe and the sample is no longer a guess.
    -- p_trajs remains a bound on how many witnesses are read, not a lottery.
    t AS (
        SELECT p.entity_id AS sid, public.laplace_trajectory_constituent_ids(p.trajectory) AS cids
        FROM laplace.physicalities p
        WHERE p.type = 1 AND p.trajectory IS NOT NULL
          AND public.laplace_trajectory_constituent_ids(p.trajectory) && p_vocab
        LIMIT p_trajs
    ),
    pos AS (
        SELECT t.sid, t.cids, i
        FROM t CROSS JOIN LATERAL generate_series(1, cardinality(t.cids) - p_gap) AS i
    )
    -- Direct adjacency at the requested gap, whatever the constituents are.
    SELECT p.cids[i], NULL::bytea, p.cids[i + p_gap], p.sid
    FROM pos p JOIN v vs ON vs.id = p.cids[i] JOIN v vo ON vo.id = p.cids[i + p_gap]
    UNION ALL
    -- Across an intervening constituent, carrying it. Emitted only when that
    -- constituent is a separator, so this cannot invent an adjacency between two
    -- words that had a third WORD between them.
    SELECT p.cids[i], p.cids[i + p_gap], p.cids[i + p_gap + 1], p.sid
    FROM pos p CROSS JOIN sep
    JOIN v vs ON vs.id = p.cids[i]
    JOIN v vo ON vo.id = p.cids[i + p_gap + 1]
    WHERE p.cids[i + p_gap] = ANY (sep.ids);
END;
-- Word adjacency DERIVED from sentence/document trajectories. Witnessed order lives in
-- the trajectory (Pillar 3a: text emits no PRECEDES laplace.attestations); this is the calculated
-- view over it.
--
-- The weight is a DOCUMENT frequency, not a corpus frequency: ids are content hashes and
-- physicality identity is (entity_id, type), so a sentence occurring a million times is
-- ONE row with ONE trajectory. count(*) here is "in how many distinct compositions is this
-- pair adjacent", never "how many times did it occur". Callers needing occurrence mass
-- must use testimony (laplace.attestations.observation_count / consensus.witness_count), which the
-- text lane deliberately does not emit. Do not relabel this as corpus frequency.
DROP FUNCTION IF EXISTS laplace.word_order(bytea[], int, int);
CREATE OR REPLACE FUNCTION generation.word_order(p_vocab bytea[], p_trajs int DEFAULT 100000, p_gap int DEFAULT 1)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- COUNT is one valuation of generation.word_adjacency, which owns the extraction.
    -- The continuation lane values the same rows by the adjudicated standing of the
    -- witnessing composition instead; keeping one extraction body is what stops the
    -- counter and the belief reader from drifting (§15).
    -- sep_id is dropped HERE, at the count, not at the extraction: what sits
    -- between two entities is real content and word_adjacency carries it. A caller
    -- that needs it reads word_adjacency directly.
    SELECT a.subject_id, a.object_id, count(*)::float8
    FROM generation.word_adjacency(p_vocab, p_trajs, p_gap) a
    GROUP BY a.subject_id, a.object_id
$$;
-- Plan Phase 4 (doc 18 §3): tier-3 sentence adjacency DERIVED from tier-4
-- document trajectories. Witnessed order lives in the trajectory (doc 14 C3
-- correction: no sentence-tier PRECEDES exists in consensus); this is the
-- calculated view over it — word_order one tier up. Document realize.constituents are
-- sentences by construction (same convention as corpus_sentence_constituents_since).
DROP FUNCTION IF EXISTS laplace.sentence_order(int, int);
CREATE OR REPLACE FUNCTION generation.sentence_order(p_docs int DEFAULT 100000, p_gap int DEFAULT 1)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH t AS (
        -- Role by TYPE, not tier: `tier = 4` misses a single-sentence document, and tier
        -- is a containment floor rather than a kind. Ranked by trajectory length instead
        -- of by content hash -- ordering by p.id sampled arbitrarily. DISTINCT ON dropped:
        -- physicality identity is (entity_id, type), so type = 1 already yields one row.
        SELECT w.id AS did, w.trajectory
        FROM laplace.v_word_points w
        WHERE w.type_id = realize.canonical_id('Document')
          AND w.trajectory IS NOT NULL
        -- Sampling is by content hash, which is ARBITRARY -- an arbitrary LIMIT without
        -- an ordering is a missing ranking. The honest ranking is by trajectory length,
        -- but MEASURED 2026-08-01 that plans as a seq scan of every physicality partition
        -- plus a full sort (no index serves n_constituents), so it trades an arbitrary
        -- sample for an unusable one. Left arbitrary DELIBERATELY until an index exists
        -- that ingest is willing to pay for; the defect is recorded, not hidden.
        ORDER BY w.id, w.physicality_id
        LIMIT p_docs
    ),
    g AS (
        SELECT t.did, tc.ordinal + rs.i - 1 AS ord, tc.entity_id AS sid
        FROM t CROSS JOIN LATERAL laplace_trajectory_constituents(t.trajectory) tc
        CROSS JOIN LATERAL generate_series(1, GREATEST(tc.run_length, 1)) rs(i)
    ),
    bg AS (
        SELECT sid AS cur, lead(sid, p_gap) OVER (PARTITION BY did ORDER BY ord) AS nxt FROM g
    ),
    cnt AS (
        -- `cur <> nxt` dropped self-adjacent pairs, which are witnessed data (a document
        -- may genuinely repeat a sentence) and which grapheme_order has always kept. The
        -- filter was an inconsistency inside one family, not a rule; consumers that cannot
        -- take a self-loop drop it at their own layer. Same change as word_order.
        SELECT cur, nxt, count(*)::float8 AS c
        FROM bg WHERE nxt IS NOT NULL GROUP BY cur, nxt
    )
    SELECT cur, nxt, c FROM cnt
$$;
-- Plan Phase 4 (doc 18 §3 L-real / doc 14 C3): the DIALOGUE/discourse plane at
-- word granularity — for each consecutive sentence pair in a tier-4 document
-- trajectory, bridge last-in-vocab-word(s_i) -> first-in-vocab-word(s_{i+1}).
-- Composes with the tier-2 continuation plane in the lm_head so the synthesized
-- model can cross a sentence boundary instead of speaking document-internal
-- word adjacency only.
DROP FUNCTION IF EXISTS laplace.sentence_order_word_bridge(bytea[], int);
CREATE OR REPLACE FUNCTION generation.sentence_order_word_bridge(p_vocab bytea[], p_docs int DEFAULT 100000)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
    t AS (
        SELECT DISTINCT ON (w.id) w.id AS did, w.trajectory
        FROM laplace.v_word_points w
        WHERE w.type_id = realize.canonical_id('Document')
          AND w.trajectory IS NOT NULL
        ORDER BY w.id, w.physicality_id LIMIT p_docs
    ),
    g AS (
        SELECT t.did, tc.ordinal + rs.i - 1 AS ord, tc.entity_id AS sid
        FROM t CROSS JOIN LATERAL laplace_trajectory_constituents(t.trajectory) tc
        CROSS JOIN LATERAL generate_series(1, GREATEST(tc.run_length, 1)) rs(i)
    ),
    pairs AS (
        SELECT sid AS cur, lead(sid) OVER (PARTITION BY did ORDER BY ord) AS nxt FROM g
    ),
    live AS (
        SELECT DISTINCT sid FROM (
            SELECT cur AS sid FROM pairs WHERE nxt IS NOT NULL
            UNION ALL
            SELECT nxt FROM pairs WHERE nxt IS NOT NULL
        ) u
    ),
    sent_traj AS (
        SELECT DISTINCT ON (w.id) w.id AS sid, w.trajectory
        FROM laplace.v_word_points w
        JOIN live s ON s.sid = w.id
        WHERE w.trajectory IS NOT NULL
        ORDER BY w.id, w.physicality_id
    ),
    words AS (
        -- in-vocab join doubles as the content filter (whitespace/punctuation
        -- realize.constituents are not vocab laplace.entities)
        SELECT st.sid, tc.ordinal + rs.i - 1 AS ord, tc.entity_id AS wid
        FROM sent_traj st CROSS JOIN LATERAL laplace_trajectory_constituents(st.trajectory) tc
        CROSS JOIN LATERAL generate_series(1, GREATEST(tc.run_length, 1)) rs(i)
        JOIN v ON v.id = tc.entity_id
    ),
    lastw  AS (SELECT DISTINCT ON (sid) sid, wid FROM words ORDER BY sid, ord DESC),
    firstw AS (SELECT DISTINCT ON (sid) sid, wid FROM words ORDER BY sid, ord ASC),
    bridged AS (
        SELECT lw.wid AS cur, fw.wid AS nxt
        FROM pairs pr
        JOIN lastw lw  ON lw.sid = pr.cur
        JOIN firstw fw ON fw.sid = pr.nxt
        WHERE pr.nxt IS NOT NULL
    ),
    cnt AS (
        SELECT cur, nxt, count(*)::float8 AS c
        FROM bridged WHERE cur <> nxt GROUP BY cur, nxt
    )
    SELECT cur, nxt, c FROM cnt
$$;
-- Plan Phase 5 (doc 14 P7): per-entity 128-bit hilbert key for the foundry's
-- static content positional encoding. hilbert_index is big-endian packed
-- (lexicographic byte order = hilbert curve order), so the leading bytes are
-- the coarsest content-locality signal.
DROP FUNCTION IF EXISTS laplace.entity_hilbert_keys(bytea[]);
CREATE OR REPLACE FUNCTION generation.entity_hilbert_keys(p_vocab bytea[])
    RETURNS TABLE(entity_id bytea, hilbert_index bytea)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT DISTINCT ON (w.id) w.id, w.hilbert_index
    FROM laplace.v_word_points w
    JOIN unnest(p_vocab) AS u(id) ON u.id = w.id
    WHERE w.hilbert_index IS NOT NULL
    ORDER BY w.id, w.physicality_id
$$;
-- Plan Phase 6 (doc 14 P2): per-entity 256-bit relation-membership mask for the
-- foundry's content-dependent FFN gate — which relation families a token
-- participates in is a genuine step function of content, synthesized, not learned.
DROP FUNCTION IF EXISTS laplace.entity_highway_masks(bytea[]);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION generation.entity_highway_masks(p_vocab bytea[])
    RETURNS TABLE(entity_id bytea, highway_mask bytea)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT e.id, e.highway_mask
    FROM laplace.entities e
    WHERE e.id = ANY (p_vocab)
      AND e.highway_mask IS NOT NULL;
END;
-- Finish-line Phase 3 (the conditional theorem, doc 14 §6b): the smoothed
-- row-normalized LOG-CONDITIONAL of continuation evidence. A trained LM's
-- logits are log P(y|prefix); the synthesis must factor THIS table, not affinity —
-- P(y|x) = P(x,y)/P(x), and the division is what lets content words win their
-- slots (glue has high joint AND high marginal; content is concentrated).
--
-- Counts fuse the two continuation witnesses at word grain:
--   corpus order  : generation.word_order(tier>2 trajectory adjacency, punctuation
--                   included once vocab admits it)
--   discourse     : generation.sentence_order_word_bridge(sentence-boundary pairs)
--
-- Pillar 5 (2026-07-20): the PRECEDES-consensus leg is GONE. Text never should
-- have materialized word adjacency as laplace.attestations(Pillar 3a, e5e1b42) -- the
-- trajectory already holds the ordered sequence losslessly, and word_order
-- reads it via laplace_trajectory_constituents. Keeping a PRECEDES leg here is
-- what forced every text lane to keep emitting the redundant edges; both legs
-- above are geometry-derived, so the same knowledge arrives without them.
-- Emitted w = log((c(x,y) + k) / (c(x) + k*V)) — add-k smoothing over the
-- vocab, so each row is a proper (log) conditional distribution up to the
-- unseen-mass remainder. NEGATIVE values are expected and meaningful.
DROP FUNCTION IF EXISTS laplace.continuation_conditional_plane(bytea[], int, double precision, int);
CREATE OR REPLACE FUNCTION generation.continuation_conditional_plane(
        p_vocab bytea[], p_trajs int DEFAULT 200000, p_smooth_k double precision DEFAULT 0.5,
        p_degree_cap int DEFAULT 512)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
    vsize AS (SELECT count(*)::float8 AS n FROM v),
    corpus_pairs AS (
        SELECT subject_id AS x, object_id AS y, w AS c
        FROM generation.word_order(p_vocab, p_trajs, 1)
    ),
    bridge_pairs AS (
        SELECT subject_id AS x, object_id AS y, w AS c
        FROM generation.sentence_order_word_bridge(p_vocab, p_trajs)
    ),
    fused AS (
        SELECT x, y, sum(c) AS c
        FROM (
            SELECT * FROM corpus_pairs
            UNION ALL SELECT * FROM bridge_pairs
        ) u
        GROUP BY x, y
    ),
    marginals AS (
        SELECT x, sum(c) AS cx FROM fused GROUP BY x
    ),
    conditional AS (
        SELECT f.x, f.y,
               ln((f.c + p_smooth_k) / (m.cx + p_smooth_k * vs.n)) AS w,
               row_number() OVER (PARTITION BY f.x ORDER BY f.c DESC, f.y) AS rn
        FROM fused f
        JOIN marginals m ON m.x = f.x
        CROSS JOIN vsize vs
    )
    SELECT c.x, c.y, c.w FROM conditional c WHERE c.rn <= p_degree_cap
    UNION ALL
    -- per-row UNSEEN default as a NULL-object row: log(k / (cx + k*V)).
    -- The densifier MUST use this for absent pairs — zero (= log 1) would rank
    -- every unseen continuation above every seen one.
    SELECT m.x, NULL::bytea, ln(p_smooth_k / (m.cx + p_smooth_k * vs.n))
    FROM marginals m CROSS JOIN vsize vs
$$;
-- Finish-line Phase 4 v1 (the syntax organ): class-transition log-conditionals,
-- P(class(y) | class(x)), from evidence the substrate ALREADY holds — each
-- word's dominant HAS_POS (max consensus.eff_mu across ConceptNet/OMW/Wiktionary/WordNet
-- witnesses) joined onto the fused continuation counts. Composed into the
-- lm_head as a log-linear correction, this is what shifts the conditional's
-- support by grammatical slot (determiner→noun, clause→boundary) — the thing
-- retrieval alone cannot do. v2 upgrades the class inventory to UD deprel.
--
-- Returns WORD-pair corrections: (x, y, log P̂(class(y)|class(x))) for vocab
-- pairs whose classes are known — directly summable with the conditional plane.
DROP FUNCTION IF EXISTS laplace.pos_transition_plane(bytea[], int, double precision, int);
CREATE OR REPLACE FUNCTION generation.pos_transition_plane(
        p_vocab bytea[], p_trajs int DEFAULT 200000, p_smooth_k double precision DEFAULT 0.5,
        p_degree_cap int DEFAULT 512)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
    -- dominant POS per vocab word: strongest unrefuted HAS_POS object
    word_pos AS (
        SELECT DISTINCT ON (c.subject_id)
               c.subject_id AS wid, c.object_id AS pos
        FROM v
        JOIN laplace.v_consensus_unrefuted c ON c.subject_id = v.id
            AND c.type_id = laplace.relation_type_id('HAS_POS')
            AND c.object_id IS NOT NULL
        ORDER BY c.subject_id, consensus.eff_mu(c.rating, c.rd) DESC
    ),
    nclasses AS (SELECT count(DISTINCT pos)::float8 AS n FROM word_pos),
    -- fused word-adjacency counts (same evidence as the conditional plane)
    -- Pillar 5 (2026-07-20): PRECEDES-consensus leg removed; word_order already
    -- reads the ordered sequence from laplace.physicalities.trajectory via
    -- laplace_trajectory_constituents (Pillar 3a, e5e1b42).
    pairs AS (
        SELECT subject_id AS x, object_id AS y, w AS c
        FROM generation.word_order(p_vocab, p_trajs, 1)
    ),
    class_pairs AS (
        SELECT wx.pos AS px, wy.pos AS py, sum(p.c) AS c
        FROM pairs p
        JOIN word_pos wx ON wx.wid = p.x
        JOIN word_pos wy ON wy.wid = p.y
        GROUP BY wx.pos, wy.pos
    ),
    class_marginals AS (
        SELECT px, sum(c) AS cx FROM class_pairs GROUP BY px
    ),
    class_conditional AS (
        SELECT cp.px, cp.py,
               ln((cp.c + p_smooth_k) / (cm.cx + p_smooth_k * nc.n)) AS w
        FROM class_pairs cp
        JOIN class_marginals cm ON cm.px = cp.px
        CROSS JOIN nclasses nc
    ),
    -- project class corrections back onto word pairs (only where classes known)
    word_corrections AS (
        SELECT wx.wid AS x, wy.wid AS y, cc.w,
               row_number() OVER (PARTITION BY wx.wid ORDER BY cc.w DESC, wy.wid) AS rn
        FROM word_pos wx
        JOIN class_conditional cc ON cc.px = wx.pos
        JOIN word_pos wy ON wy.pos = cc.py
    )
    SELECT wc.x, wc.y, wc.w FROM word_corrections wc WHERE wc.rn <= p_degree_cap
$$;
-- Finish-line Phase 4 v1b (the syntax organ, lm_head composition path): the
-- pos_transition_plane word-pair projection caps at 512 arbitrary-tiebreak
-- rows per word — wrong grain for a floor correction. The lm_head wants the
-- ~18x18 CLASS table + each vocab word's dominant class; the dense compose
-- M[x,y] += gain * T[class(x),class(y)] happens client-side over the full
-- V x V table (SQL returns the small fact tables; C# orchestrates).
DROP FUNCTION IF EXISTS laplace.vocab_dominant_pos(bytea[]);
CREATE OR REPLACE FUNCTION generation.vocab_dominant_pos(p_vocab bytea[])
    RETURNS TABLE(word_id bytea, pos_id bytea)
    LANGUAGE plpgsql STABLE PARALLEL RESTRICTED AS $$
DECLARE
    v_type bytea;
BEGIN
    v_type := laplace.relation_type_id('HAS_POS');
    RETURN QUERY
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
    direct AS (
        SELECT DISTINCT ON (c.subject_id) c.subject_id AS wid, c.object_id AS pos
        FROM v
        JOIN laplace.v_consensus_unrefuted c ON c.subject_id = v.id
            AND c.type_id = v_type
        WHERE c.object_id IS NOT NULL
        ORDER BY c.subject_id, consensus.eff_mu(c.rating, c.rd) DESC
    ),
    -- CASE-VARIANT ASYMMETRY, resolved through the ATTESTED case surface.
    -- 'ALL' may carry no HAS_POS witness while 'all' does. They are different
    -- content and therefore different ids -- that is the identity law, not a
    -- defect -- and the substrate already holds the link: HAS_UPPERCASE_MAPPING /
    -- HAS_LOWERCASE_MAPPING / HAS_TITLECASE_MAPPING are governed in
    -- relation_types.toml, witnessed per codepoint from UnicodeData.txt fields
    -- 12/13/14, and composed to word grain natively and batched by
    -- lexical.word_case_variants(src/lexical_case.c), which also gates on entity_exists.
    --
    -- This previously read `laplace.word_id(lower(realize.render(vv.id)))`: realize.render the id back to
    -- text, case-fold the text, then MINT AN ID FROM THE FOLDED STRING. Not a
    -- lookup -- a fabrication. It leaves hash space mid-operation, discards the
    -- attested edges, and laplace.word_id() mints unconditionally, so an unwitnessed fold
    -- yields a well-formed id for content that may have no entity at all (the
    -- `m.fid IS NOT NULL` guard cannot catch that; laplace.word_id is never null). The
    -- result feeds pos_transition_plane and therefore the exported model's POS
    -- shaping, so a fabricated identity here becomes a weight.
    --
    -- Any attested variant is admissible, not just the lowercase one: the
    -- asymmetry runs both ways ('all' -> 'All' when only the title form is
    -- witnessed). Ties break on consensus.eff_mu then id, so the choice stays deterministic.
    missing AS (
        SELECT vv.id, unnest(lexical.word_case_variants(vv.id)) AS fid
        FROM v vv
        WHERE NOT EXISTS (SELECT 1 FROM direct d WHERE d.wid = vv.id)
    ),
    folded AS (
        SELECT DISTINCT ON (m.id) m.id AS wid, c.object_id AS pos
        FROM missing m
        JOIN laplace.v_consensus_unrefuted c ON c.subject_id = m.fid
            AND c.type_id = v_type
        WHERE c.object_id IS NOT NULL AND m.fid IS NOT NULL AND m.fid <> m.id
        ORDER BY m.id, consensus.eff_mu(c.rating, c.rd) DESC, m.fid
    )
    SELECT d.wid, d.pos FROM direct d
    UNION ALL
    SELECT f.wid, f.pos FROM folded f;
END;
$$;

-- Class-transition log-conditionals P^(class(y) | class(x)) from the same
-- fused continuation evidence as the conditional plane (word_order trajectory
-- adjacency), aggregated to the dominant-POS classes.
--
-- Pillar 5 (2026-07-20): PRECEDES-consensus leg removed. word_order reads the
-- ordered sequence straight from laplace.physicalities.trajectory via
-- laplace_trajectory_constituents, which is the same knowledge PRECEDES
-- materialized as redundant laplace.attestations(Pillar 3a, e5e1b42).
DROP FUNCTION IF EXISTS laplace.pos_class_transitions(bytea[], int, double precision);
CREATE OR REPLACE FUNCTION generation.pos_class_transitions(
        p_vocab bytea[], p_trajs int DEFAULT 200000, p_smooth_k double precision DEFAULT 0.5)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE plpgsql STABLE PARALLEL RESTRICTED AS $$
BEGIN
    RETURN QUERY
    WITH v(id) AS (SELECT DISTINCT u FROM unnest(p_vocab) AS u),
    word_pos AS MATERIALIZED (
        SELECT wp.word_id AS wid, wp.pos_id AS pos FROM generation.vocab_dominant_pos(p_vocab) wp
    ),
    nclasses AS (SELECT count(DISTINCT pos)::float8 AS n FROM word_pos),
    pairs AS (
        SELECT wo.subject_id AS x, wo.object_id AS y, wo.w AS c
        FROM generation.word_order(p_vocab, p_trajs, 1) wo
    ),
    class_pairs AS (
        SELECT wx.pos AS px, wy.pos AS py, sum(p.c) AS c
        FROM pairs p
        JOIN word_pos wx ON wx.wid = p.x
        JOIN word_pos wy ON wy.wid = p.y
        GROUP BY wx.pos, wy.pos
    ),
    class_marginals AS (
        SELECT cp.px, sum(cp.c) AS cx FROM class_pairs cp GROUP BY cp.px
    )
    SELECT cp.px, cp.py,
           ln((cp.c + p_smooth_k) / (cm.cx + p_smooth_k * nc.n))
    FROM class_pairs cp
    JOIN class_marginals cm ON cm.px = cp.px
    CROSS JOIN nclasses nc;
END;
$$;
DROP FUNCTION IF EXISTS laplace.corpus_word_vocab(int, int);
CREATE OR REPLACE FUNCTION generation.corpus_word_vocab(p_size int, p_trajs int DEFAULT 400000)
    RETURNS TABLE(surface text, weight bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH t AS (
        SELECT DISTINCT ON (w.id) w.id AS entity_id, w.trajectory
        FROM laplace.v_word_points w
        WHERE w.type_id IN (realize.canonical_id('Sentence'), realize.canonical_id('Document'))
          AND w.trajectory IS NOT NULL
        ORDER BY w.id, w.physicality_id LIMIT p_trajs
    ),
    w AS MATERIALIZED (
        SELECT tc.entity_id AS id, sum(GREATEST(tc.run_length, 1)) AS c
        FROM t CROSS JOIN LATERAL laplace_trajectory_constituents(t.trajectory) tc
        JOIN laplace.entities e ON e.id = tc.entity_id AND e.type_id = realize.canonical_id('Word')
        GROUP BY tc.entity_id
    ),
    
    
    
    -- Rank the complete candidate population, then render in caller-sized pages.
    -- The old `p_size * 4` head could underfill whenever lexical validity was
    -- below 25% in that prefix. Page width is a memory bound derived from the
    -- requested result cardinality; it does not remove candidates.
    ranked AS MATERIALIZED (
        SELECT id, c, row_number() OVER (ORDER BY c DESC, id) AS rn
        FROM w
    ), pages AS MATERIALIZED (
        SELECT ((rn - 1) / GREATEST(p_size, 1)) AS page,
               array_agg(id ORDER BY rn) AS ids
        FROM ranked
        WHERE p_size > 0
        GROUP BY ((rn - 1) / GREATEST(p_size, 1))
    ),
    rendered AS MATERIALIZED (
        SELECT i.id, i.s
        FROM pages p,
             LATERAL ROWS FROM (
                 unnest(p.ids), unnest(realize.render_text_batch(p.ids))
             ) AS i(id, s)
    )
    SELECT xr.s, xw.c
    FROM ranked xw
    JOIN rendered xr ON xr.id = xw.id
    WHERE xr.s ~ '^[A-Za-z][A-Za-z''.-]*$'
    ORDER BY xw.c DESC, xw.id
    LIMIT GREATEST(p_size, 0)
$$;
-- Pairwise metric edges over a vocab. frechet/hausdorff use REALIZED curves
-- (entity_curve), never packed laplace.physicalities.trajectory (Rule #3 / Issue 51).
-- Curves are built once per vocab id in CTE `v`.
DROP FUNCTION IF EXISTS laplace.metric_edges(bytea[], text, int, int);
CREATE OR REPLACE FUNCTION generation.metric_edges(
        p_vocab bytea[], p_metric text DEFAULT 'frechet', p_k int DEFAULT 16, p_probe int DEFAULT 64)
    RETURNS TABLE(subject_id bytea, object_id bytea, w double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH v AS (
        SELECT DISTINCT ON (w.id) w.id, w.coord, structural.entity_curve(w.id) AS curve
        FROM laplace.v_word_points w
        JOIN unnest(p_vocab) AS u(id) ON u.id = w.id
        ORDER BY w.id, w.physicality_id
    ),
    cand AS (
        SELECT a.id AS aid, b.id AS bid, a.curve AS ac, b.curve AS bc,
               laplace_angular_distance_4d(a.coord, b.coord) AS ang
        FROM v a JOIN v b ON a.id <> b.id
    ),
    pruned AS (
        SELECT aid, bid, ac, bc, ang,
               row_number() OVER (PARTITION BY aid ORDER BY ang) AS rn
        FROM cand
    ),
    refined AS (
        SELECT aid, bid,
            CASE p_metric
                WHEN 'angular'   THEN ang
                WHEN 'frechet'   THEN coalesce(laplace_frechet_4d(ac, bc), ang)
                WHEN 'hausdorff' THEN coalesce(laplace_hausdorff_4d(ac, bc), ang)
                ELSE ang
            END AS d
        FROM pruned
        WHERE rn <= GREATEST(p_probe, p_k)
    ),
    topk AS (
        SELECT aid, bid, d,
               row_number() OVER (PARTITION BY aid ORDER BY d) AS rn
        FROM refined
    )
    SELECT aid, bid, d FROM topk WHERE rn <= p_k
$$;
DROP FUNCTION IF EXISTS laplace.foundry_crawl(bytea[], int, int, int, bytea[]);
CREATE OR REPLACE FUNCTION generation.foundry_crawl(
        p_seeds bytea[], p_budget int DEFAULT 32000, p_hops int DEFAULT 3, p_fanout int DEFAULT 64,
        p_rel_types bytea[] DEFAULT NULL)
    RETURNS TABLE(entity_id bytea, weight bigint)
    AS 'laplace_substrate', 'pg_laplace_foundry_crawl'
    LANGUAGE C VOLATILE;
DROP FUNCTION IF EXISTS laplace.foundry_vocab_crawl(text[], int, int, int, float8);
CREATE OR REPLACE FUNCTION generation.foundry_vocab_crawl(
        p_seeds text[], p_max int DEFAULT 32000, p_hops int DEFAULT 3, p_fanout int DEFAULT 64,
        p_rank_floor float8 DEFAULT 0.5)
    RETURNS TABLE(entity_id bytea, surface text, weight bigint)
    LANGUAGE sql VOLATILE AS $$
    WITH seed_ids AS (
        SELECT coalesce(array_agg(wid), '{}'::bytea[]) AS ids
        FROM (SELECT laplace.word_id(s) AS wid FROM unnest(p_seeds) AS s) q
        WHERE wid IS NOT NULL
    ),
    
    
    
    
    
    
    
    
    rel_types AS (



        SELECT array_agg(e.id) AS ids
        FROM laplace.entities e
        WHERE e.type_id = realize.canonical_id('RelationType')
          AND consensus.relation_rank_resolved(e.id) >= p_rank_floor
    ),
    crawled AS (
        SELECT c.entity_id, c.weight,
               row_number() OVER (ORDER BY c.weight DESC, c.entity_id) AS rn
        FROM seed_ids si, rel_types rt
        CROSS JOIN LATERAL generation.foundry_crawl(si.ids, p_max, p_hops, p_fanout, rt.ids) c
    ),
    
    
    
    
    
    -- Pillar 5 (2026-07-20): sequence proposals come from geometry_successors --
    -- the next content constituent in the text projection of every trajectory --
    -- not from PRECEDES consensus, which merely materialized the same sequence
    -- the trajectory already holds (Pillar 3a, e5e1b42). Weight is observed
    -- frequency (seen), not consensus.eff_mu, because there is no rated edge to read.
    -- This is proposal evidence, not a direct semantic edge: the underlying
    -- structural path remains point -> containing composition -> constituent.
    order1 AS (
        SELECT gs.point_id,
               gs.successor_id AS entity_id,
               gs.seen::numeric AS w,
               row_number() OVER (PARTITION BY gs.point_id ORDER BY gs.seen DESC, gs.successor_id) AS rn
        FROM seed_ids si
        CROSS JOIN LATERAL structural.geometry_successors_batch(si.ids, p_fanout, 8, false) gs
        JOIN laplace.entities e ON e.id = gs.successor_id AND e.type_id = realize.canonical_id('Word')
    ),
    order1_cut AS (
        SELECT point_id, entity_id, w, w::bigint AS weight
        FROM order1 WHERE rn <= p_fanout
    ),
    order2 AS (
        SELECT tc.object_id AS entity_id,
               (o.w * tc.weight::numeric)::bigint AS weight,
               row_number() OVER (ORDER BY o.w * tc.weight DESC, tc.object_id) AS rn
        FROM order1_cut o
        CROSS JOIN LATERAL generation.trajectory_continuations(
            ARRAY[o.point_id, o.entity_id], p_fanout) tc
        JOIN laplace.entities e ON e.id = tc.object_id AND e.type_id = realize.canonical_id('Word')
    ),
    order2_cut AS (
        SELECT entity_id, weight FROM order2 WHERE rn <= p_max
    ),
    order_lemma AS (
        SELECT c.object_id AS entity_id, o.weight
        FROM (SELECT entity_id, max(weight) AS weight FROM (
                  SELECT entity_id, weight FROM order1_cut
                  UNION ALL SELECT entity_id, weight FROM order2_cut
              ) u GROUP BY entity_id) o
        JOIN laplace.v_consensus_unrefuted c ON c.subject_id = o.entity_id
            AND c.type_id = laplace.relation_type_id('IS_LEMMA_OF')
            AND c.object_id IS NOT NULL
        JOIN laplace.entities e ON e.id = c.object_id AND e.type_id = realize.canonical_id('Word')
    ),
    order_closure AS (
        SELECT entity_id, max(weight) AS weight,
               row_number() OVER (ORDER BY max(weight) DESC, entity_id) AS rn
        FROM (
            SELECT entity_id, weight FROM order1_cut
            UNION ALL SELECT entity_id, weight FROM order2_cut
            UNION ALL SELECT entity_id, weight FROM order_lemma
        ) u
        GROUP BY entity_id
    ),
    
    
    
    
    
    
    
    -- The scaffold is contextual vocabulary, so discover it from trajectories
    -- containing at least one requested seed.  The previous global branch sorted
    -- by content hash, cut at 400,000 trajectories regardless of p_max, and only
    -- then unpacked them: a 100-token request took 126.9 seconds while returning
    -- 57 rows.  Overlap is the GIN-served reduction boundary; ordinal unpack and
    -- frequency aggregation happen only over the matching physical observations.
    --
    -- No parent-entity type join belongs before that boundary.  It scanned 10.6M
    -- Sentence/Document entity rows to validate 13,457 already-matched trajectories
    -- in the measured `king` probe.  A word's own grapheme trajectory cannot contain
    -- its word id, so seed overlap already selects compositions in which the word
    -- participates.  The final rendered-content predicates below reject separators
    -- and non-token surfaces after aggregation, over the reduced ID set.
    scaffold_traj AS MATERIALIZED (
        SELECT DISTINCT ON (p.entity_id) p.entity_id, p.trajectory
        FROM seed_ids s, laplace.physicalities p
        WHERE p.type = 1
          AND p.trajectory IS NOT NULL
          AND public.laplace_trajectory_constituent_ids(p.trajectory) && s.ids
        ORDER BY p.entity_id, p.id
    ),
    scaffold AS (
        SELECT tc.entity_id AS entity_id,
               sum(GREATEST(tc.run_length, 1))::bigint AS weight,
               row_number() OVER (ORDER BY sum(GREATEST(tc.run_length, 1)) DESC, tc.entity_id) AS rn
        FROM scaffold_traj t
        CROSS JOIN LATERAL public.laplace_trajectory_constituents(t.trajectory) tc
        GROUP BY tc.entity_id
    ),
    picked AS (
        SELECT entity_id, weight, 2 AS pri FROM order_closure WHERE rn <= p_max / 4
        UNION ALL
        SELECT entity_id, weight, 1 AS pri FROM crawled  WHERE rn <= p_max - p_max / 2
        UNION ALL
        SELECT entity_id, weight, 0 AS pri FROM scaffold WHERE rn <= p_max / 4
    ),
    uniq AS (
        SELECT DISTINCT ON (entity_id) entity_id, weight, pri
        FROM picked ORDER BY entity_id, pri DESC, weight DESC
    ),
    ids_arr AS (
        SELECT array_agg(entity_id ORDER BY pri DESC, weight DESC) AS ids,
               array_agg(weight     ORDER BY pri DESC, weight DESC) AS ws,
               array_agg(pri        ORDER BY pri DESC, weight DESC) AS prs
        FROM uniq
    ),
    rendered AS (
        SELECT u.entity_id, u.s, a.ws[u.ord::int] AS weight, a.prs[u.ord::int] AS pri
        FROM ids_arr a
        CROSS JOIN LATERAL unnest(a.ids, realize.render_text_batch(a.ids))
                   WITH ORDINALITY AS u(entity_id, s, ord)
        WHERE a.ids IS NOT NULL AND cardinality(a.ids) > 0
    ),
    clean AS (
        SELECT DISTINCT ON (n.s) n.entity_id, n.s, n.weight, n.pri
        FROM rendered n
        WHERE n.s IS NOT NULL AND btrim(n.s) <> '' AND NOT realize.is_all_whitespace(n.s)
          AND position(' ' IN n.s) = 0 AND char_length(n.s) <= 40
          -- 2026-07-09 (finish-line Phase 2): the old `~ '[[:alpha:]]'` gate made
          -- punctuation and numerals unrepresentable — no synthesized model could emit
          -- a sentence boundary. Non-whitespace is content; only ILI ids stay out.
          AND n.s !~ '^i[0-9]+$'
        ORDER BY n.s, n.pri DESC, n.weight DESC
    )
    SELECT c.entity_id, c.s, c.weight FROM clean c ORDER BY c.pri DESC, c.weight DESC LIMIT p_max
$$;
DROP FUNCTION IF EXISTS laplace.walk_continuations(bytea[], int, int, float8, int, bigint);
CREATE OR REPLACE FUNCTION generation.forward_walk_continuations(
        p_ctx bytea[], p_steps int, p_max_stride int,
        p_spread float8, p_top_k int, p_seed bigint, p_frontier bytea[],
        p_relation_types bytea[])
    RETURNS TABLE(step int, entity bytea, stride_used int, sep_entity bytea)
    AS 'laplace_execution_2e9b3225dced6056', 'pg_laplace_walk_continuations'
    LANGUAGE C VOLATILE;

CREATE OR REPLACE FUNCTION generation.forward_walk_continuations(
        p_ctx bytea[], p_steps int DEFAULT 24, p_max_stride int DEFAULT 5,
        p_spread float8 DEFAULT 0.7, p_top_k int DEFAULT 10,
        p_seed bigint DEFAULT NULL, p_frontier bytea[] DEFAULT NULL)
    RETURNS TABLE(step int, entity bytea, stride_used int, sep_entity bytea)
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT * FROM generation.forward_walk_continuations(
        p_ctx, p_steps, p_max_stride, p_spread, p_top_k, p_seed, p_frontier, NULL);
END;

-- Compatibility surface: preserve the installed parameter name `p_breadth` so
-- CREATE OR REPLACE remains upgrade-safe for callers that bind by name. The
-- canonical routed operator names the same operand `p_top_k`; this wrapper only
-- translates the legacy API spelling and does not own a second implementation.
CREATE OR REPLACE FUNCTION generation.walk_continuations(
        p_ctx bytea[], p_steps int DEFAULT 24, p_max_stride int DEFAULT 5,
        p_spread float8 DEFAULT 0.7, p_breadth int DEFAULT 10,
        p_seed bigint DEFAULT NULL)
    RETURNS TABLE(step int, entity bytea, stride_used int, sep_entity bytea)
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT * FROM generation.forward_walk_continuations(
        p_ctx, p_steps, p_max_stride, p_spread, p_breadth, p_seed, NULL);
END;
-- generation.trajectory_continuations(ctx, topk) -> what followed this exact context, counted.
-- NULL topk returns the complete successor set; zero returns no rows.  Callers that
-- need a bounded presentation choose that bound explicitly after any downstream
-- steering, rather than losing candidates to a guessed pre-steering cutoff.
--
-- The substrate-native replacement for GenCorpus and its RAM suffix array. Same
-- operation continuations_collect performed -- find every position where the last
-- k content realize.constituents match, take what came next, count it -- scoped by an
-- index probe on the context's LAST token instead of a binary search over a
-- 97,111,658-row flattened copy of the corpus.
--
-- WHY THE CACHE WAS NEVER NEEDED: the trajectory already IS the ordered sequence
-- (§9 -- stored trajectories carry constituent identity). GenCorpus rebuilt that
-- ordering into a flat int32 stream, per backend, from a full-corpus scan --
-- measured 46 minutes for one generation.generate() call, and the same timeout at steps=1,
-- so the cost was never the walk. §7 requires cost bounded by the path, not by
-- corpus size; a per-backend whole-corpus build cannot satisfy that at any size.
--
-- SEPARATORS ARE NOT CONTEXT. The corpus stream was content-only with the
-- following separator carried beside it (GenCorpus.sep_after), so matching must
-- happen over content positions or " the king" and "the king" become different
-- contexts.
--
-- ONLY TIER 0 CAN BE A SEPARATOR, and that is the narrowing that makes this cheap.
-- Measured on this substrate: a tier-3 sentence trajectory holds tier-2 words
-- beside tier-0 atoms, because a single-character token collapses to the
-- character's own id (§3, single-child collapse). Words are never separators, so
-- classification touches only the tier-0 realize.constituents. It cannot be decided by
-- tier ALONE -- `a` and `I` are single-grapheme words that collapse to tier 0 too
-- -- so the UCD attestation still decides, via generation.separator_ids(), which owns
-- that fact for every caller.
--
-- The frame offset is a parameter, so one body serves every backoff order rather
-- than five hand-written arms.
DROP FUNCTION IF EXISTS laplace.trajectory_continuations(bytea[], int);
CREATE OR REPLACE FUNCTION generation.trajectory_continuations(
        p_ctx bytea[], p_topk int DEFAULT NULL)
    RETURNS TABLE(object_id bytea, sep_id bytea, weight bigint)
    AS 'laplace_execution_2e9b3225dced6056', 'pg_laplace_trajectory_continuations'
    LANGUAGE C STABLE;
-- generation.steer_candidates(candidates, frontier) -> S7 STEER (docs/specs/36 §3).
--
-- Re-rank S6's proposed continuations by rated consensus mass reaching the LIVE
-- frontier from S4. The frontier argument is what makes it S7 rather than a
-- prior: it is passed per emitted token, so a candidate's score depends on where
-- the walk currently stands, not on which source sentence it was gathered from.
--
-- Returns a row for EVERY candidate, including unreachable ones (steer 0.0,
-- edges 0). edges = 0 is "no attested path to the frontier"; edges > 0 with
-- steer = 0.0 is "attested and adjudicated to neutral". The caller must not
-- collapse them -- that distinction is what tells a walk to back off rather than
-- dead-end.
--
-- steer is COVERAGE-WEIGHTED, not a bare edge sum. Mass folds per DISTINCT
-- frontier member, then coverage rides as a multiplier: sum * (1 + ln(covered)).
-- A bare sum ranks by "reaches anything in the frontier"; a composed prefix
-- means "sits where the frontier overlaps". For "the capital of france is",
-- `Lyon` (one strong edge to `france`, sum 10, covered 1) scores 10 while
-- `Paris` (moderate edges to `france` AND `capital`, sum 8, covered 2) scores
-- 8 * 1.69 = 13.5 -- breadth wins without rescaling either candidate's mass.
--
-- The SUM carries through unscaled on purpose: the caller combines as
-- eff = weight * steer (trajectory_generate.c), so squashing steer through a
-- concave curve would hand the ranking to sequence weight -- a global weakening
-- of steering disguised as a coverage fix. Refuted totals are never amplified.
--
-- covered is the DISTINCT frontier members reached -- not edges, which counts
-- five edges into `france` alone the same as edges spread across the frontier.
-- Refuted (negative) member mass bypasses log1p and stays linear so it can sink
-- a candidate instead of being squashed toward zero.
--
-- Native batch consensus access uses the active PostgreSQL snapshot.
DROP FUNCTION IF EXISTS laplace.steer_candidates(bytea[], bytea[], float8);
CREATE OR REPLACE FUNCTION generation.steer_candidates(
        p_candidates bytea[], p_frontier bytea[], p_relation_types bytea[])
    RETURNS TABLE(candidate bytea, steer float8, edges bigint, covered bigint)
    AS 'laplace_execution_2e9b3225dced6056', 'pg_laplace_steer_candidates'
    LANGUAGE C VOLATILE;

CREATE OR REPLACE FUNCTION generation.steer_candidates(
        p_candidates bytea[], p_frontier bytea[])
    RETURNS TABLE(candidate bytea, steer float8, edges bigint, covered bigint)
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT * FROM generation.steer_candidates(p_candidates, p_frontier, NULL);
END;
DROP FUNCTION IF EXISTS laplace.variant_walk(bytea, float8, int, int);
CREATE OR REPLACE FUNCTION generation.variant_walk(p_id bytea, p_swap float8 DEFAULT 0.3,
                          p_k int DEFAULT 6, p_depth int DEFAULT 4)
    RETURNS text
    AS 'laplace_substrate', 'pg_laplace_variant_walk'
    LANGUAGE C VOLATILE;
DROP FUNCTION IF EXISTS laplace.respell_variant(text, text, float8, int, int);
CREATE OR REPLACE FUNCTION generation.respell_variant(p_node_type text, p_modality text DEFAULT 'c-sharp',
                     p_substitution_rate float8 DEFAULT 0.3, p_k int DEFAULT 6, p_depth int DEFAULT 4)
    RETURNS text
    AS 'laplace_substrate', 'pg_laplace_respell_variant'
    LANGUAGE C VOLATILE;
DROP FUNCTION IF EXISTS laplace.recall_trajectories(text, int);
CREATE OR REPLACE FUNCTION generation.recall_trajectories(p_word text, p_limit int DEFAULT 6)
    RETURNS TABLE(answer text)
    LANGUAGE sql STABLE AS $$
  WITH wid AS (SELECT laplace.word_id(p_word) AS id),
  ids AS (
    SELECT w.id AS entity_id, abs(w.n_constituents - 7) AS rank_distance
    FROM wid
    JOIN laplace.v_word_points w
      ON w.trajectory IS NOT NULL
     AND w.type_id = realize.canonical_id('Sentence')
     AND public.laplace_trajectory_constituent_ids(w.trajectory) @> ARRAY[wid.id]
    ORDER BY rank_distance, w.id
    LIMIT p_limit
  ), batch AS MATERIALIZED (
    SELECT array_agg(entity_id ORDER BY rank_distance, entity_id) AS a FROM ids
  )
  SELECT left(replace(t.s, chr(10), ' '), 180)
  FROM batch,
       LATERAL unnest(realize.render_text_batch(batch.a)) WITH ORDINALITY AS t(s, ord)
  ORDER BY t.ord
$$;
-- Rule #8 retirement: the write protocol verifies claimed-novel ids
-- in-transaction and bulk-COPYs directly (NpgsqlWorkingSetApply); the period
-- fold runs client-side in ConsensusAccumulatingWriter against the same native
-- glicko-2. The server-side apply/fold entry points below have no callers and
-- are dropped on upgrade.
DROP FUNCTION IF EXISTS laplace.laplace_apply_batch(text);
DROP FUNCTION IF EXISTS laplace.consensus_fold_partition_incremental(text, boolean);
DROP FUNCTION IF EXISTS laplace._apply_batch_merge_entities(regclass);
DROP FUNCTION IF EXISTS laplace._apply_batch_merge_physicalities(regclass);
DROP FUNCTION IF EXISTS laplace._apply_batch_merge_attestations(regclass);
-- No SET search_path so it inlines into callers (#617) — walk_strongest
-- executes this once per walk step (generate_walk.c edge_plan); non-inlined,
-- each step paid a full function execution. walk_branches batches natively
-- and does not use this function.
DROP FUNCTION IF EXISTS laplace.consensus_walk_edges(bytea, bytea, int, bytea[]);
CREATE OR REPLACE FUNCTION consensus.walk_edges(
    p_subject  bytea,
    p_type     bytea DEFAULT NULL,
    p_limit    int   DEFAULT 40,
    p_exclude  bytea[] DEFAULT '{}')
    RETURNS TABLE(object_id bytea, type_id bytea, rating bigint, rd bigint, witness_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT c.object_id, c.type_id, c.rating, c.rd, c.witness_count
    FROM laplace.v_consensus_unrefuted c
    LEFT JOIN laplace.entities et
           ON et.id = c.object_id
          AND et.type_id = laplace.entity_type_id('RelationType')
    WHERE c.subject_id = p_subject
      AND c.object_id IS NOT NULL
      AND (p_type IS NULL OR c.type_id = p_type)
      AND NOT (c.object_id = ANY (COALESCE(p_exclude, '{}'::bytea[])))
      AND et.id IS NULL
    ORDER BY consensus.edge_rank(c.type_id, consensus.eff_mu(c.rating, c.rd)) DESC
    LIMIT p_limit
$$;
-- Outbound neighbours of one type set, unrefuted, consensus.eff_mu order. Thin wrapper over
-- consensus.edges_raw() with those axes pinned.
DROP FUNCTION IF EXISTS laplace.consensus_neighbors_directed(bytea, bytea[], int);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.neighbors_directed(
    p_subject bytea, p_types bytea[], p_limit int)
    RETURNS TABLE(nbr bytea, rating bigint, rd bigint, witness_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT e.neighbour_id, e.rating, e.rd, e.witness_count
    FROM consensus.edges_raw(p_subject, 'out', p_types, p_limit, false, 'eff_mu') e;
END;
-- Neighbours in BOTH directions of one type set, unrefuted, consensus.eff_mu order. Thin
-- wrapper over consensus.edges_raw(); the UNION ALL it used to hand-roll is that function.
DROP FUNCTION IF EXISTS laplace.consensus_neighbors_undirected(bytea, bytea[], int);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.neighbors_undirected(
    p_subject bytea, p_types bytea[], p_limit int)
    RETURNS TABLE(nbr bytea, rating bigint, rd bigint, witness_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT e.neighbour_id, e.rating, e.rd, e.witness_count
    FROM consensus.edges_raw(p_subject, 'both', p_types, p_limit, false, 'eff_mu') e;
END;
-- Outbound neighbours with their tier, for the foundry vocab crawl. Thin wrapper
-- over consensus.edges_raw(); pins outbound, consensus.eff_mu order and consensus.refuted edges INCLUDED — the
-- axes this lane has always used. The tier join is this caller's own need, so it
-- stays here rather than widening the core.
DROP FUNCTION IF EXISTS laplace.foundry_crawl_neighbors(bytea, int, bytea[]);
DROP FUNCTION IF EXISTS laplace.foundry_crawl_neighbors(bytea[], int, bytea[]);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.foundry_crawl_neighbors(
    p_subjects bytea[],
    p_limit    int,
    p_types    bytea[] DEFAULT NULL)
    RETURNS TABLE(frontier_id bytea, object_id bytea, tier smallint,
                  rating bigint, rd bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH ranked AS (
        SELECT c.subject_id AS frontier_id,
               c.object_id,
               c.rating,
               c.rd,
               row_number() OVER (
                   PARTITION BY c.subject_id
                   ORDER BY consensus.eff_mu(c.rating, c.rd) DESC,
                            c.object_id,
                            c.type_id) AS rn
        FROM laplace.consensus c
        WHERE p_limit > 0
          AND c.subject_id = ANY (p_subjects)
          AND c.object_id IS NOT NULL
          AND (p_types IS NULL OR c.type_id = ANY (p_types))
    )
    SELECT r.frontier_id, r.object_id, e.tier, r.rating, r.rd
    FROM ranked r
    JOIN laplace.entities e ON e.id = r.object_id
    WHERE r.rn <= p_limit
    ORDER BY r.frontier_id, r.rn;
END;

CREATE OR REPLACE FUNCTION consensus.foundry_crawl_neighbors(
    p_subject bytea,
    p_limit   int,
    p_types   bytea[] DEFAULT NULL)
    RETURNS TABLE(object_id bytea, tier smallint, rating bigint, rd bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT n.object_id, n.tier, n.rating, n.rd
    FROM consensus.foundry_crawl_neighbors(ARRAY[p_subject], p_limit, p_types) n;
END;
-- Highway coordinates of a relation type: its bit position in the 256-bit
-- mask and its salience-band index. NULL for ungoverned (non-canonical) ids —
-- an ungoverned type showing up here is a manifest-registration gap, the
-- exact bug class that left chess/model planes maskless.
-- STRICT: a NULL type id has no highway bit. Without it, a NULL bytea reaches the C
-- (which PG_GETARG_BYTEA_Ps arg 0 unconditionally) and segfaults the backend — as it did
-- when highway_mask_refresh's COALESCE(..., consensus.relation_highway_bit(fam.object_id)) passed a
-- LEFT-JOIN-miss NULL on the fold path (crash-recovery, whole cluster down). STRICT makes
-- NULL input return NULL without entering the C, which is the correct semantics anyway.
DROP FUNCTION IF EXISTS laplace.relation_highway_bit(bytea);
CREATE OR REPLACE FUNCTION consensus.relation_highway_bit(p_type_id bytea)
    RETURNS int
    AS 'laplace_substrate', 'pg_laplace_relation_highway_bit'
    LANGUAGE C STABLE STRICT;

DROP FUNCTION IF EXISTS laplace.relation_highway_band(bytea);
CREATE OR REPLACE FUNCTION consensus.relation_highway_band(p_type_id bytea)
    RETURNS int
    AS 'laplace_substrate', 'pg_laplace_relation_highway_band'
    LANGUAGE C STABLE STRICT;
-- Set bit positions of a highway mask as int4[] — the indexable form. GIN over
-- this expression serves bit-overlap plane queries (bits && band-bits) with
-- posting lists built for duplicate-heavy keys, replacing the pathological
-- hash-on-66-distinct-values indexes removed in Issue 36.
DROP FUNCTION IF EXISTS laplace.laplace_highway_mask_bits(mask bytea);
CREATE OR REPLACE FUNCTION consensus.highway_mask_bits(mask bytea)
    RETURNS int[]
    AS 'laplace_substrate', 'pg_laplace_highway_mask_bits'
    LANGUAGE C IMMUTABLE;
-- Resolve a highway mask to the relation types whose governed highway bit is
-- present in that mask.  Highway membership is a property of the relation
-- vocabulary/perfcache, not of an entity's accumulated incident-edge mask.
--
-- Static governed relations resolve directly.  Dynamic relation types (FEAT_*,
-- DEP_*, ...) inherit their family root's bit through the governed upward set,
-- exactly as the
-- deposit path does.  This examines the small RelationType roster once and
-- returns ids that large consensus reads can use with = ANY(...).
CREATE OR REPLACE FUNCTION consensus.relation_mask_types(p_mask bytea)
    RETURNS bytea[]
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    WITH wanted(bits) AS (
        SELECT consensus.highway_mask_bits(p_mask)
    ), resolved AS (
        SELECT DISTINCT et.id
        FROM laplace.entities et
        LEFT JOIN laplace.consensus fam
          ON fam.subject_id = et.id
         AND fam.type_id = ANY (consensus.relation_set_ids('PATH_UPWARD'))
        CROSS JOIN wanted w
        WHERE et.type_id = laplace.entity_type_id('RelationType')
          AND COALESCE(consensus.relation_highway_bit(et.id),
                       consensus.relation_highway_bit(fam.object_id)) = ANY (w.bits)
    )
    SELECT COALESCE(array_agg(id), '{}'::bytea[]) FROM resolved;
END;
