DROP FUNCTION IF EXISTS laplace.explore_web(bytea, int, int, int);
DROP FUNCTION IF EXISTS consensus.explore_web(bytea, int, int, int);
CREATE OR REPLACE FUNCTION consensus.explore_web(
    p_seeds bytea[],
    p_hops int DEFAULT 2,
    p_fanout int DEFAULT 10,
    p_max_nodes int DEFAULT NULL)
    RETURNS TABLE(
        source_id bytea,
        type_id bytea,
        object_id bytea,
        hop smallint,
        rating bigint,
        rd bigint,
        witness_count bigint)
    AS 'laplace_execution_2e9b3225dced6056', 'pg_laplace_explore_web'
    LANGUAGE C STABLE;

-- Scalar convenience delegates to the canonical multi-seed crawl. It is not a
-- second traversal implementation.
CREATE OR REPLACE FUNCTION consensus.explore_web(
    p_seed bytea,
    p_hops int DEFAULT 2,
    p_fanout int DEFAULT 10,
    p_max_nodes int DEFAULT NULL)
    RETURNS TABLE(
        source_id bytea,
        type_id bytea,
        object_id bytea,
        hop smallint,
        rating bigint,
        rd bigint,
        witness_count bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT * FROM consensus.explore_web(
        ARRAY[p_seed], p_hops, p_fanout, p_max_nodes);
END;
-- The bounded receipt for ROUTE/SCAN. It exposes the exact typed consensus
-- edges admitted by the same crawl used to build the forward frontier. Resolved
-- prompt ids are the operand: text decomposition/coherence belongs to the caller
-- that owns the forward pass, not to a nested routing helper.
CREATE OR REPLACE FUNCTION generation.forward_route_trace_ids(
        p_seeds bytea[],
        p_hops int DEFAULT 2,
        p_fanout int DEFAULT 8,
        p_max_nodes int DEFAULT NULL)
    RETURNS TABLE(source_id bytea, type_id bytea, object_id bytea,
                  hop smallint, rating bigint, rd bigint,
                  witness_count bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
SELECT w.source_id, w.type_id, w.object_id, w.hop,
       w.rating, w.rd, w.witness_count
FROM consensus.explore_web(
    COALESCE(p_seeds, '{}'::bytea[]),
    p_hops, p_fanout, p_max_nodes) w
ORDER BY w.hop, w.source_id, w.type_id, w.object_id;
END;

-- ID-facing semantic frontier. The prompt's resolved constituents/senses are
-- already an operand here, so ROUTE/SCAN is one consensus.explore_web traversal.
-- The seeds themselves stay at hop zero; every routed endpoint carries the hop
-- reported by the same trace receipt above. A NULL node budget delegates exact
-- capacity to consensus.explore_web rather than inventing a second cap.
CREATE OR REPLACE FUNCTION generation.forward_frontier_ids(
        p_seeds bytea[],
        p_hops int DEFAULT 2,
        p_fanout int DEFAULT 8,
        p_max_nodes int DEFAULT NULL)
    RETURNS TABLE(entity bytea, hop smallint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
WITH seeds AS MATERIALIZED (
    SELECT DISTINCT u.entity
    FROM unnest(COALESCE(p_seeds, '{}'::bytea[])) u(entity)
    WHERE u.entity IS NOT NULL
), routed AS MATERIALIZED (
    SELECT w.*
    FROM generation.forward_route_trace_ids(
        COALESCE(p_seeds, '{}'::bytea[]), p_hops, p_fanout, p_max_nodes) w
), nodes AS (
    SELECT s.entity, 0::smallint AS hop FROM seeds s
    UNION ALL
    SELECT r.source_id, r.hop FROM routed r
    UNION ALL
    SELECT r.object_id, r.hop FROM routed r
)
SELECT n.entity, min(n.hop)::smallint AS hop
FROM nodes n
GROUP BY n.entity
ORDER BY min(n.hop), n.entity;
END;
DROP FUNCTION IF EXISTS laplace.walk_text(text, int, int, float8, int, bigint);
CREATE OR REPLACE FUNCTION generation.forward_text(
        p_prompt text, p_steps int DEFAULT 24, p_max_stride int DEFAULT 5,
        p_spread float8 DEFAULT 0.7, p_top_k int DEFAULT 10,
        p_seed bigint DEFAULT NULL, p_hops int DEFAULT 2,
        p_fanout int DEFAULT 8, p_prior_frontier bytea[] DEFAULT NULL)
    RETURNS TABLE(step int, entity text, stride_used int)
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    -- The observation root and its complete canonical tree precede routing.
    -- No case-popularity substitution, named-English relation extraction or
    -- dictionary-membership filter is allowed to change this operand.
    WITH observation AS MATERIALIZED (
        SELECT * FROM converse.prompt_tree(p_prompt)
    ), ctx AS MATERIALIZED (
        SELECT array_agg(p.id ORDER BY p.byte_offset, p.node_index) AS ids
        FROM observation p
        WHERE p.tier = 2
    ), seed_array AS MATERIALIZED (
        SELECT ARRAY(
            SELECT n.id FROM (
                SELECT p.root_id AS id FROM observation p
                UNION
                SELECT p.id FROM observation p
            ) n ORDER BY n.id) AS ids
    ), frontier AS MATERIALIZED (
        SELECT array_agg(x.entity ORDER BY x.hop, x.entity) AS ids
        FROM (
            SELECT f.entity, f.hop
            FROM seed_array s
            CROSS JOIN LATERAL generation.forward_frontier_ids(
                s.ids, p_hops, p_fanout, NULL) f
            UNION
            SELECT p.entity, 0::smallint
            FROM unnest(COALESCE(p_prior_frontier, '{}'::bytea[])) p(entity)
            WHERE p.entity IS NOT NULL
        ) x
    ), walked AS MATERIALIZED (
        SELECT g.*
        FROM ctx CROSS JOIN frontier,
             generation.forward_walk_continuations(
                 ctx.ids, p_steps, p_max_stride, p_spread, p_top_k,
                 COALESCE(
                     p_seed,
                     laplace.hash128_lo(public.laplace_hash128_blake3(
                         convert_to(p_prompt, 'UTF8')))),
                 frontier.ids,
                 NULL::bytea[]) g
        WHERE ctx.ids IS NOT NULL
    ), ids AS MATERIALIZED (
        SELECT array_agg(entity ORDER BY step) AS entities,
               array_agg(sep_entity ORDER BY step) AS separators
        FROM walked
    ), txt AS MATERIALIZED (
        SELECT realize.render_text_batch(entities) AS entities,
               realize.render_text_batch(separators) AS separators
        FROM ids
    )
    SELECT w.step,
           t.entities[rn] || COALESCE(t.separators[rn], ''),
           w.stride_used
    FROM (SELECT w.*, row_number() OVER (ORDER BY step) AS rn FROM walked w) w
    CROSS JOIN txt t;
END;

-- Compatibility surface: preserve the installed `p_breadth` name for named
-- callers and extension upgrades. The canonical operator owns the semantic name
-- `p_top_k`; this wrapper translates only the legacy API spelling.
CREATE OR REPLACE FUNCTION generation.walk_text(
        p_prompt text, p_steps int DEFAULT 24, p_max_stride int DEFAULT 5,
        p_spread float8 DEFAULT 0.7, p_breadth int DEFAULT 10,
        p_seed bigint DEFAULT NULL)
    RETURNS TABLE(step int, entity text, stride_used int)
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT * FROM generation.forward_text(
        p_prompt, p_steps, p_max_stride, p_spread, p_breadth, p_seed, 2, 8, NULL);
END;

-- Upgrade retirement. These text routing surfaces had no callers outside the
-- recursive chain removed above. They must be dropped only AFTER forward_text is
-- rebound to forward_frontier_ids: BEGIN ATOMIC records pg_depend, so dropping
-- them earlier would make an in-place extension upgrade fail under RESTRICT.
DROP FUNCTION IF EXISTS generation.forward_frontier(text, integer, integer, integer);
DROP FUNCTION IF EXISTS generation.forward_route_trace(text, integer, integer, integer);
DROP FUNCTION IF EXISTS laplace.generate(text, int, int, float8, int, bigint);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION generation.generate(
        p_prompt text, p_steps int DEFAULT 40, p_max_stride int DEFAULT 5,
        p_spread float8 DEFAULT 0.7, p_breadth int DEFAULT 12,
        p_seed bigint DEFAULT NULL)
    RETURNS text
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT btrim(string_agg(entity, '' ORDER BY step))
    FROM generation.walk_text(p_prompt, p_steps, p_max_stride, p_spread, p_breadth, p_seed);
END;
DROP FUNCTION IF EXISTS laplace.continue_text(text, int, int, double precision, int, text[], double precision, boolean);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION generation.continue_text(
        p_prompt text, p_steps int DEFAULT 16, p_window int DEFAULT 3,
        p_spread double precision DEFAULT 0.6, p_breadth int DEFAULT 8,
        p_stop text[] DEFAULT '{}', p_boost double precision DEFAULT 0,
        p_require_pos boolean DEFAULT true)
    RETURNS TABLE(step int, entity text, mu numeric)
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT g.step, g.entity, NULL::numeric AS mu
    FROM generation.walk_text(p_prompt, p_steps, p_window, p_spread, p_breadth) g;
END;
-- The single strongest unrefuted edge between two ids, either way round.
--
-- No SET search_path so it inlines into callers (#617) — graph_cascade
-- executes this once per step; non-inlined, each step paid a full function
-- execution.
--
-- BOTH is two direction-pinned reads unioned, never an OR predicate (GH #871,
-- spec 37 OP5). The old body
-- asked for
--     (subject_id = p_from AND object_id = p_to)
--  OR (subject_id = p_to   AND object_id = p_from)
-- in one WHERE. A disjunction is not an index qual: the planner's only options
-- are a BitmapOr of two scans it must then sort in full, or a seq scan — the
-- shape spec 37 blames for the 280s hang. Neither can walk
-- consensus_subject_eff_mu_btree (subject_id, (rating - 2*rd) DESC) in order and
-- stop at the first row.
--
-- Split into two arms, each arm is a single subject_id equality against that
-- index, ordered by the index's own second column, LIMIT 1 — so each stops at
-- its first match. The outer LIMIT 1 then picks between at most two rows, which
-- is the same answer: the maximum over a union is the maximum of the per-arm
-- maxima. This is exactly the UNION ALL shape consensus.edges_raw() uses for 'both'; the
-- reason this body cannot simply delegate to edges_raw is that edges_raw takes
-- no neighbour filter, so it would apply its cap to the whole fan-out of p_from
-- before p_to could be selected out of it.
DROP FUNCTION IF EXISTS laplace.consensus_step_edge(bytea, bytea);
CREATE OR REPLACE FUNCTION consensus.step_edge(
    p_from bytea,
    p_to   bytea)
    RETURNS TABLE(type_id bytea, subject_id bytea, rating bigint, rd bigint, witness_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
    -- STRUCTURAL bound, not an estimate: the body ends in LIMIT 1, so this
    -- returns at most one row. Undeclared, Postgres assumes 1000 -- a 1000x
    -- overestimate on the inner side of any join, which is what makes scanning
    -- look cheaper than probing.
    ROWS 1 AS $$
    SELECT e.type_id, e.subject_id, e.rating, e.rd, e.witness_count
    FROM (
        (SELECT c.type_id, c.subject_id, c.rating, c.rd, c.witness_count
         FROM laplace.v_consensus_unrefuted c
         WHERE c.subject_id = p_from
           AND c.object_id = p_to
           -- Explicit IS NOT NULL so the planner can match the partial
           -- consensus_subject_eff_mu_btree (WHERE object_id IS NOT NULL).
           AND c.object_id IS NOT NULL
         ORDER BY consensus.eff_mu(c.rating, c.rd) DESC
         LIMIT 1)
        UNION ALL
        (SELECT c.type_id, c.subject_id, c.rating, c.rd, c.witness_count
         FROM laplace.v_consensus_unrefuted c
         WHERE c.subject_id = p_to
           AND c.object_id = p_from
           AND c.object_id IS NOT NULL
         ORDER BY consensus.eff_mu(c.rating, c.rd) DESC
         LIMIT 1)
    ) e
    ORDER BY consensus.eff_mu(e.rating, e.rd) DESC
    LIMIT 1
$$;
-- NEITHER `SET search_path` NOR `STRICT` (GH #617 item 5). Both block SQL inlining,
-- and this runs PER ROW inside lexical_case.c's COALESCE unnest query and
-- WitnessedWordsAsync's WHERE -- so each row paid a full function execution instead
-- of the body being folded into the caller's plan.
--
-- Dropping STRICT is safe here because the body is already null-safe and gives the
-- same answer: `e.id = NULL` matches nothing, EXISTS over that is false, and
-- realize.codepoint_for_id(NULL) is NULL, so a NULL argument returns false either way --
-- where STRICT short-circuited to NULL. That is a change from NULL to false on a
-- NULL input, and it is the correct one: "does this id exist" for a non-existent id
-- is false. No caller passes NULL expecting to distinguish those; the presence
-- probes pass ids they just computed.
DROP FUNCTION IF EXISTS laplace.entity_exists(bytea);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION consensus.entity_exists(p_id bytea)
    RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    -- A valid tier-0 codepoint is real via the perfcache alone (see realize.codepoint_for_id());
    -- it must resolve true here even before/without its own laplace.entities row being written,
    -- so callers can't mistake "orphaned tier-0" for "genuinely missing".
    SELECT EXISTS (SELECT 1 FROM laplace.entities e WHERE e.id = p_id)
        OR realize.codepoint_for_id(p_id) IS NOT NULL;
END;
-- realize._synset_lemma — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace._realize_synset_lemma(bytea, bytea);
CREATE OR REPLACE FUNCTION realize._synset_lemma(p_id bytea, p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- RANK FIRST, THEN RENDER ONCE FOR ALL CANDIDATES.
    -- The `s <> ''` filter means an unrenderable candidate must fall through to the
    -- next, so the surface cannot be dropped from the decision -- but it does not have
    -- to be produced one candidate at a time. realize.render_text_batch runs ONE
    -- constituents closure over every id (generate_walk.c fetch_constituents_closure
    -- with n_roots); the scalar form ran one closure per candidate. Measured on 40 ids,
    -- identical md5: 487 ms per-row, 106 ms batched.
    -- Ranked in full, not capped: the render filter can reject any prefix, and a LIMIT
    -- here would turn "unrenderable" into "no name".
    WITH ranked AS MATERIALIZED (
        SELECT hs.subject_id AS id,
               row_number() OVER (ORDER BY (lang.object_id IS NOT NULL) DESC,
                        consensus.eff_mu(hs.rating, hs.rd) DESC, hs.subject_id) AS rn
        FROM laplace.v_consensus_unrefuted io
        JOIN laplace.consensus hs ON hs.object_id = io.subject_id
          AND hs.type_id = laplace.relation_type_id('HAS_SENSE')
        LEFT JOIN laplace.consensus lang ON lang.subject_id = hs.subject_id
          AND lang.type_id = laplace.relation_type_id('HAS_LANGUAGE')
          AND lang.object_id = p_lang
        WHERE io.object_id = p_id
          AND io.type_id = laplace.relation_type_id('IS_SENSE_OF')
    ),
    lbl AS MATERIALIZED (
        SELECT realize.render_text_batch(array_agg(r.id ORDER BY r.rn)) AS s
        FROM ranked r
    )
    SELECT l.s[r.rn]
    FROM ranked r CROSS JOIN lbl l
    WHERE l.s[r.rn] IS NOT NULL AND l.s[r.rn] <> ''
    ORDER BY r.rn
    LIMIT 1
$$;
-- realize._translation — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace._realize_translation(bytea, bytea);
CREATE OR REPLACE FUNCTION realize._translation(p_id bytea, p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- RANK FIRST, THEN RENDER ONCE FOR ALL CANDIDATES.
    -- The `s <> ''` filter means an unrenderable candidate must fall through to the
    -- next, so the surface cannot be dropped from the decision -- but it does not have
    -- to be produced one candidate at a time. realize.render_text_batch runs ONE
    -- constituents closure over every id (generate_walk.c fetch_constituents_closure
    -- with n_roots); the scalar form ran one closure per candidate. Measured on 40 ids,
    -- identical md5: 487 ms per-row, 106 ms batched.
    -- Ranked in full, not capped: the render filter can reject any prefix, and a LIMIT
    -- here would turn "unrenderable" into "no name".
    WITH ranked AS MATERIALIZED (
        SELECT m.object_id AS id,
               row_number() OVER (ORDER BY (lang.object_id IS NOT NULL) DESC,
                        consensus.eff_mu(m.rating, m.rd) DESC, m.object_id) AS rn
        FROM laplace.v_consensus_unrefuted m
        LEFT JOIN laplace.consensus lang ON lang.subject_id = m.object_id
          AND lang.type_id = laplace.relation_type_id('HAS_LANGUAGE')
          AND lang.object_id = p_lang
        WHERE m.subject_id = p_id
          AND m.type_id = laplace.relation_type_id('IS_TRANSLATION_OF')
    ),
    lbl AS MATERIALIZED (
        SELECT realize.render_text_batch(array_agg(r.id ORDER BY r.rn)) AS s
        FROM ranked r
    )
    SELECT l.s[r.rn]
    FROM ranked r CROSS JOIN lbl l
    WHERE l.s[r.rn] IS NOT NULL AND l.s[r.rn] <> ''
    ORDER BY r.rn
    LIMIT 1
$$;
-- realize._has_name — GH #862 / #860. No SET (this is on the per-row label path),
-- real schema names.
DROP FUNCTION IF EXISTS laplace._realize_has_name(bytea, bytea);
CREATE OR REPLACE FUNCTION realize._has_name(p_id bytea, p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- RANK FIRST, THEN RENDER ONCE FOR ALL CANDIDATES.
    -- The `s <> ''` filter means an unrenderable candidate must fall through to the
    -- next, so the surface cannot be dropped from the decision -- but it does not have
    -- to be produced one candidate at a time. realize.render_text_batch runs ONE
    -- constituents closure over every id (generate_walk.c fetch_constituents_closure
    -- with n_roots); the scalar form ran one closure per candidate. Measured on 40 ids,
    -- identical md5: 487 ms per-row, 106 ms batched.
    -- Ranked in full, not capped: the render filter can reject any prefix, and a LIMIT
    -- here would turn "unrenderable" into "no name".
    WITH ranked AS MATERIALIZED (
        SELECT nm.object_id AS id,
               row_number() OVER (ORDER BY (lang.object_id IS NOT NULL) DESC,
                        (nm.type_id = laplace.relation_type_id('HAS_NAME')) DESC,
                        consensus.eff_mu(nm.rating, nm.rd) DESC, nm.object_id) AS rn
        FROM laplace.v_consensus_unrefuted nm
        LEFT JOIN laplace.consensus lang ON lang.subject_id = nm.object_id
          AND lang.type_id = laplace.relation_type_id('HAS_LANGUAGE')
          AND lang.object_id = p_lang
        WHERE nm.subject_id = p_id
          AND nm.type_id IN (laplace.relation_type_id('HAS_NAME'),
                             laplace.relation_type_id('HAS_NAME_ALIAS'))
    ),
    lbl AS MATERIALIZED (
        SELECT realize.render_text_batch(array_agg(r.id ORDER BY r.rn)) AS s
        FROM ranked r
    )
    SELECT l.s[r.rn]
    FROM ranked r CROSS JOIN lbl l
    WHERE l.s[r.rn] IS NOT NULL AND l.s[r.rn] <> ''
    ORDER BY r.rn
    LIMIT 1
$$;
-- realize._canonical — GH #862 / #860. No SET (blocks plan caching and inlining;
-- this runs per row inside realize's COALESCE), real schema names.
DROP FUNCTION IF EXISTS laplace._realize_canonical(bytea);
CREATE OR REPLACE FUNCTION realize._canonical(p_id bytea)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE STRICT AS $$
    SELECT regexp_replace(n.name, '^substrate/[a-z_]+/(.+)/v1$', '\1')
    FROM laplace.canonical_names n
    WHERE n.id = p_id AND n.name LIKE 'substrate/%'
$$;
-- realize._defines — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace._realize_defines(bytea);
CREATE OR REPLACE FUNCTION realize._defines(p_id bytea)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE STRICT AS $$
    -- RANK IN ID SPACE, RENDER THE WINNER. The ordering key is eff_mu, not the
    -- rendered text, so nothing needs a surface to decide. Rendering in the target
    -- list made realize.render_text run for EVERY candidate and kept one: each call opens
    -- its own SPI connection and walks realize.constituents_closure, the largest single
    -- line item in the system (1,496,183 calls, 19.6 hours cumulative).
    SELECT realize.render_text(
        (SELECT g.object_id
         FROM laplace.v_consensus_unrefuted g
         WHERE g.subject_id = p_id
           AND g.type_id = laplace.relation_type_id('HAS_DEFINITION')
         -- object_id CLOSES the order: without it a tie is broken by plan order,
         -- which is not reproducible. Matches Q_DEFINES in realize_batch.c.
         ORDER BY consensus.eff_mu(g.rating, g.rd) DESC, g.object_id
         LIMIT 1), 24)
$$;
DROP FUNCTION IF EXISTS laplace.resolve_name(bytea, bytea, bytea[]);
CREATE OR REPLACE FUNCTION realize.resolve_name(
    p_id bytea,
    p_lang bytea DEFAULT NULL,
    p_context bytea[] DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    -- No SET search_path (GH #860): it invalidates plan caching and blocks inlining,
    -- and this is on the per-row label path. Real schema names instead.
    AS $$
    -- The one referentially-correct name primitive. Three call sites (label,
    -- realize.render, realize) used to each resolve a name a different way and disagree:
    -- label saw only HAS_NAME_ALIAS, realize.render saw canonical->codepoint->ALIAS,
    -- realize walked the synset lemma. None consulted HAS_NAME (the PRIMARY,
    -- authoritative name), none took a domain context, and every one ended in a
    -- context-blind `ORDER BY consensus.eff_mu DESC LIMIT 1` global-popularity argmax whose
    -- final fallback fabricated hex styled as a label. This unifies all three:
    --
    --   * NAME edges consulted as families -- HAS_NAME (primary, preferred) and
    --     HAS_NAME_ALIAS, unioned via consensus.relation_type_in_family() so members roll in
    --     without editing this site. They are distinct family roots (there is no
    --     single "name" root), so both are consulted.
    --   * the synset-lemma path, walked via the HAS_SENSE family_root (IS_SENSE_OF
    --     and IS_SYNONYM_OF roll up to HAS_SENSE) rather than one hardcoded edge --
    --     the same rollup taxonomy.bubble_up() and the sense-selection walks already use.
    --   * ABSTENTION: when nothing crosses a grounded threshold (an actual,
    --     renderable name), return NULL. Never fabricate `<hex>...` as if it were a
    --     label. converse.label_or_hex() is the place that decides to show a raw id; a name
    --     resolver's job is to say "no name" honestly.
    --
    -- With no domain context this reduces EXACTLY to the existing, tested
    -- resolvers (_realize_has_name then _realize_synset_lemma), so the wrappers
    -- that delegate here stay behaviour-identical wherever no HAS_NAME edge exists.
    SELECT CASE
        WHEN p_context IS NULL OR cardinality(p_context) = 0 THEN
            -- realize._canonical last, and only last: its own comment says it runs
            -- inside realize's COALESCE, but nothing called it from here. It reads
            -- laplace.canonical_names and matches ONLY the substrate/<kind>/<name>/v1
            -- form -- 274 of the registry's 10,253 rows -- so it cannot leak the other
            -- 9,979, which are internal keys ('language:len', 'iso639-1:eo') rather
            -- than names. An entity with no attested name and no substrate canonical
            -- form still returns NULL, which is the structural answer (§7: "no gloss
            -- witnessed yet" is an answer, not a failure), not a hex address.
            COALESCE(realize._has_name(p_id, p_lang),
                     realize._synset_lemma(p_id, p_lang),
                     realize._canonical(p_id))
        ELSE (
            -- Context-conditioned selection. Same lang-pref-then-consensus.eff_mu shape as
            -- the null-context helpers, plus a domain boost for name candidates
            -- whose surface entity co-occurs (as subject OR object of any
            -- unrefuted edge) with the supplied context ids -- the set-based
            -- co-occurrence scoring lexical.senses(word, context) already uses. Language
            -- preference stays AHEAD of the boost so a domain hint never overrides
            -- the caller's requested language; the boost only breaks ties the old
            -- global argmax broke blindly by popularity.
            -- FAMILY TYPE IDS ARE CALLED INLINE IN EVERY PREDICATE. NEVER HOISTED.
            --
            -- consensus is LIST-partitioned by type_id. consensus.relation_family_ids is
            -- IMMUTABLE and generated from the manifest, so an inline call folds to a
            -- literal bytea[] before planning and the LIST partitions prune. The same
            -- value read from a CTE column is a per-row variable: nothing prunes, every
            -- leaf is Seq Scanned, and the join degrades to a disk sort. Measured on one
            -- synset, identical 475-row result: hoisted into a CTE, 4,477,851 buffers and
            -- a 1,086,552 kB external merge; called inline, 8,965 buffers and 114.8 ms.
            --
            -- The predicate this replaced -- consensus.relation_type_in_family(hs.type_id,
            -- 'HAS_SENSE') -- is a function call ON the partition key, which prunes no
            -- better than the CTE column and runs once per edge on top.
            WITH ctx AS (
                SELECT id, sum(boost) AS boost FROM (
                    SELECT c.object_id AS id, sum(consensus.eff_mu(c.rating, c.rd)) AS boost
                    FROM laplace.v_consensus_unrefuted c
                    WHERE c.subject_id = ANY (p_context)
                    GROUP BY c.object_id
                    UNION ALL
                    SELECT c.subject_id AS id, sum(consensus.eff_mu(c.rating, c.rd)) AS boost
                    FROM laplace.v_consensus_unrefuted c
                    WHERE c.object_id = ANY (p_context)
                    GROUP BY c.subject_id
                ) t GROUP BY id
            ),
            -- CANDIDATES IN ID SPACE. No realize.render here: aggregate ids, then
            -- render the selected batch (GH #906/#907).
            --
            -- MEASURED 2026-08-07 via pg_stat_statements on the foundation seed: this
            -- branch was 24,511 calls at a 2,380 ms mean, and the `realize.render_text(...)`
            -- inside it was a separate 24,512 calls at 2,372 ms -- i.e. essentially the
            -- ENTIRE cost of resolving a name was rendering candidates that were then
            -- discarded. realize.render_text is a scalar: each call opens its own SPI connection
            -- and runs its own constituents_closure recursion, and that recursion is the
            -- single largest line item in the whole system (1,496,183 calls, 19.6 hours
            -- cumulative). A name with 40 candidates paid 40 closure walks to return one
            -- string.
            --
            -- realize.render_text_batch runs ONE closure over every id at once -- the native
            -- batch path already does exactly that (generate_walk.c fetch_constituents_
            -- closure with n_roots), it was simply never reached from here.
            cand AS MATERIALIZED (
                -- HAS_NAME (primary) + HAS_NAME_ALIAS, as families.
                SELECT nm.object_id AS name_id,
                       nm.type_id = ANY (consensus.relation_family_ids('HAS_NAME')) AS prim,
                       (lang.object_id IS NOT NULL) AS lp,
                       consensus.eff_mu(nm.rating, nm.rd) AS mu
                FROM laplace.v_consensus_unrefuted nm
                LEFT JOIN laplace.consensus lang ON lang.subject_id = nm.object_id
                     AND lang.type_id = laplace.relation_type_id('HAS_LANGUAGE')
                     AND lang.object_id = p_lang
                WHERE nm.subject_id = p_id
                  AND nm.type_id = ANY (consensus.relation_family_ids('HAS_NAME')
                                        || consensus.relation_family_ids('HAS_NAME_ALIAS'))
                UNION ALL
                -- synset lemma: word --[HAS_SENSE family]--> sense
                --                    --[IS_SENSE_OF -> HAS_SENSE]--> p_id
                SELECT hs.subject_id AS name_id,
                       false AS prim,
                       (lang.object_id IS NOT NULL) AS lp,
                       consensus.eff_mu(hs.rating, hs.rd) AS mu
                FROM laplace.v_consensus_unrefuted io
                JOIN laplace.consensus hs ON hs.object_id = io.subject_id
                     AND hs.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
                LEFT JOIN laplace.consensus lang ON lang.subject_id = hs.subject_id
                     AND lang.type_id = laplace.relation_type_id('HAS_LANGUAGE')
                     AND lang.object_id = p_lang
                WHERE io.object_id = p_id
                  AND io.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
            ),
            -- RANK FIRST, THEN RENDER. The ordering keys are all fold-side, so the
            -- winner is decided in id space and only the survivors are realized.
            -- Ranked in full (not capped) because the realize.render filter below can reject
            -- any prefix of them: an id with no renderable surface must fall through
            -- to the next candidate, and a LIMIT here would turn "unrenderable" into
            -- "no name" -- an abstention this function is explicit about not faking.
            ranked AS MATERIALIZED (
                SELECT c.name_id,
                       row_number() OVER (
                           ORDER BY c.lp DESC,
                                    (ctx.boost IS NOT NULL) DESC,
                                    c.prim DESC,
                                    COALESCE(ctx.boost, 0) DESC,
                                    c.mu DESC,
                                    c.name_id) AS rn
                FROM cand c
                LEFT JOIN ctx ON ctx.id = c.name_id
            ),
            -- ONE closure walk for every candidate, position-aligned (the alignment is
            -- pinned by tests/sql/realize_ladder_parity.sql).
            lbl AS MATERIALIZED (
                SELECT realize.render_text_batch(array_agg(r.name_id ORDER BY r.rn)) AS s
                FROM ranked r
            )
            SELECT l.s[r.rn]
            FROM ranked r CROSS JOIN lbl l
            WHERE l.s[r.rn] IS NOT NULL AND l.s[r.rn] <> ''
            ORDER BY r.rn
            LIMIT 1
        )
    END
$$;
-- NO `SET search_path` (GH #860, #617 item 6). realize.realize() is the per-row labeling
-- scalar of the entire read path -- every arrow realize.render, every relation listing,
-- every reply. The clause made SQL inlining impossible, so each row paid a full
-- function execution for what is a COALESCE over four cheap resolvers.
--
-- GH #862: realize.realize, with its five resolvers as same-schema siblings.
DROP FUNCTION IF EXISTS laplace.realize(bytea, bytea);
CREATE OR REPLACE FUNCTION realize.realize(p_id bytea, p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- realize.resolve_name() is the single, referentially-correct name primitive: it
    -- folds the former realize._has_name(HAS_NAME primary + HAS_NAME_ALIAS) and
    -- _realize_synset_lemma into one family-aware, abstaining resolver. It replaces
    -- the two separate arms this function used to run (synset-lemma first, HAS_NAME
    -- buried after translation); now the authoritative NAME wins ahead of a
    -- rendered self or a translation guess. The remaining arms stay as realize's
    -- own display fallbacks (raw realize.render, translation, canonical id, gloss).
    -- CONTENT BEFORE NAME. render_text is the VALUE an entity carries; resolve_name is
    -- the LABEL for it. An entity that has content must emit the content -- the name
    -- is metadata about it, not a substitute for it.
    --
    -- resolve_name used to come first, so any entity carrying a HAS_NAME edge emitted
    -- its name instead of itself. Unicode codepoints all carry one: measured over the
    -- 224 distinct constituents of 40 tier-3 containers, ALL 224 render and only 16
    -- carry a name -- and every one of those 16 is the label losing to the content:
    --   COLON / ':'   COMMA / ','   AMPERSAND / '&'   APOSTROPHE / '   DIGIT ONE / '1'
    --   HYPHEN-MINUS / '-'   LATIN CAPITAL LETTER X / 'X'
    -- Not one case where the name was the better emission. Downstream this is what put
    -- "year action MIDDLE DOT year active verb counterfactual in COLON" into a reply.
    --
    -- Reordering cannot lose a name, because every entity whose name IS the right
    -- answer has nothing to render and falls through the NULLIF: measured, a Language
    -- entity renders NULL and names 'English', a RelationType renders and names NULL,
    -- while the wolf synset renders 'wolf' and names NULL.
    SELECT COALESCE(
        NULLIF(realize.render_text(p_id), ''),
        realize.resolve_name(p_id, p_lang),
        realize._translation(p_id, p_lang),
        realize._canonical(p_id),
        realize._defines(p_id))
$$;
DROP FUNCTION IF EXISTS laplace.shared_objects(bytea[], bytea, int);
CREATE OR REPLACE FUNCTION consensus.shared_objects(p_subjects bytea[], p_type bytea DEFAULT NULL,
                                     p_limit int DEFAULT 40)
    RETURNS TABLE(object_id bytea, support int, total_mu numeric)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- consensus.eff_mu_display, not the scale-and-round open-coded. Its own header says
    -- "same rounding, same scale, one definition file -- never re-derived inline",
    -- and this was the inline re-derivation: if the fold's fp1e9 scale or the
    -- display precision ever moves, one copy moves and the other silently reports
    -- a different number for the same edges.
    SELECT c.object_id,
           count(DISTINCT c.subject_id)::int,
           -- ::bigint because sum() over bigint returns numeric and the display
           -- overloads take bigint. The sum of integers IS an integer, so the cast
           -- is lossless; it is the type, not the value, being restated.
           consensus.eff_mu_display(sum(consensus.eff_mu(c.rating, c.rd))::bigint)
    FROM laplace.v_consensus_unrefuted c
    WHERE c.subject_id = ANY (p_subjects)
      AND c.object_id IS NOT NULL
      AND (p_type IS NULL OR c.type_id = p_type)
    GROUP BY c.object_id
    ORDER BY count(DISTINCT c.subject_id) DESC,
             sum(consensus.eff_mu(c.rating, c.rd)) DESC
    LIMIT p_limit
$$;
-- consensus.edges(subject, ...) — THE edge read. One operation, both directions, labeled.
--
-- Before this there were ten ways to ask "what is this connected to", and they
-- disagreed on four independent axes, so every caller picked one at random or
-- hand-wrote a consensus scan:
--
--   consensus_subject_edges        raw table, outbound only, unlabeled
--   consensus_neighbors_directed   unrefuted view, outbound, types[] required
--   consensus_walk_edges           unrefuted, outbound, exclude[], RelationType antijoin
--   consensus_step_edge            unrefuted, both, but ONE edge between two ids
--   explore_web_neighbors          RAW consensus (consensus.refuted included), both
--   foundry_crawl_neighbors        RAW consensus (consensus.refuted included), outbound
--   related / related_in           unrefuted, one direction each, senses-expanded
--   related_objects                unrefuted, outbound, relation BY NAME
--
-- The axes: which table (consensus vs laplace.v_consensus_unrefuted vs
-- laplace.v_consensus_resolved), which direction, which ranking (raw consensus.eff_mu vs consensus.edge_rank
-- vs none), and whether consensus.refuted edges are included. consensus_subject_edges and
-- the two crawl feeders return consensus.refuted edges; their siblings do not. That is a
-- semantic difference, not a stylistic one, and it was never a caller's choice —
-- it was an accident of which function got reached for.
--
-- Here every axis is an explicit argument with a stated default:
--   p_direction  'out' | 'in' | 'both'      (default 'both')
--   p_types      NULL = every relation type (default NULL)
--   p_refuted    false = exclude consensus.refuted(default false)
--   p_limit      a QUERY limit over an consensus.eff_mu ranking, never a floor
--
-- Ranking is consensus.edge_rank(relation salience x consensus.eff_mu), the readout law the serving
-- surface already uses. Labels resolve in ONE realize_batch after the limit, per
-- the rank-then-label rule — never a scalar realize per row.
DROP FUNCTION IF EXISTS laplace.edges(bytea, text, bytea[], int, boolean, bytea);
CREATE OR REPLACE FUNCTION consensus.edges(
        p_subject   bytea,
        p_direction text    DEFAULT 'both',
        p_types     bytea[] DEFAULT NULL,
        p_limit     int     DEFAULT 40,
        p_refuted   boolean DEFAULT false,
        p_lang      bytea   DEFAULT NULL)
    RETURNS TABLE(direction text, relation text, neighbour_id bytea,
                  neighbour text, eff_mu numeric, witnesses bigint)
-- No SET search_path — it blocks inlining and this body wraps consensus.edges_raw(), the
-- one consensus scan. Every reference is @extschema@-qualified instead. GH #860.
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH ranked AS MATERIALIZED (
        SELECT e.direction AS dir,e.type_id,e.neighbour_id AS nid,
               e.rating,e.rd,e.witness_count,e.ord
        FROM consensus.edges_raw(p_subject,p_direction,p_types,p_limit,p_refuted,'edge_rank')
             WITH ORDINALITY
             AS e(direction,type_id,neighbour_id,rating,rd,volatility,witness_count,ord)
    ),
    ids AS MATERIALIZED (
        SELECT array_agg(DISTINCT id ORDER BY id) AS a
        FROM (SELECT type_id AS id FROM ranked UNION SELECT nid FROM ranked) x
    ), labels AS MATERIALIZED (
        SELECT i.id,i.txt FROM ids,
          LATERAL ROWS FROM (
            unnest(ids.a), unnest(realize.label_batch(ids.a))
          ) i(id,txt)
    ), rel AS MATERIALIZED (
        SELECT t.type_id,
               COALESCE(NULLIF(consensus.relation_canonical(t.type_id), ''),
                        l.txt) AS relation
        FROM (SELECT DISTINCT k.type_id FROM ranked k) t
        JOIN labels l ON l.id=t.type_id
    ),
    lbl AS MATERIALIZED (
        SELECT realize.batch(array_agg(k.nid ORDER BY k.ord), p_lang) AS l
        FROM ranked k
    )
    SELECT k.dir, rel.relation, k.nid,
           COALESCE(lbl.l[k.ord], nl.txt),
           consensus.eff_mu_display(k.rating, k.rd),
           k.witness_count
    FROM ranked k
    JOIN rel ON rel.type_id = k.type_id
    JOIN labels nl ON nl.id=k.nid
    CROSS JOIN lbl
    ORDER BY k.ord
$$;

DROP FUNCTION IF EXISTS laplace.edges(text, text, int, boolean);
CREATE OR REPLACE FUNCTION consensus.edges(
        p_word      text,
        p_direction text    DEFAULT 'both',
        p_limit     int     DEFAULT 40,
        p_refuted   boolean DEFAULT false)
    RETURNS TABLE(direction text, relation text, neighbour_id bytea,
                  neighbour text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT e.direction, e.relation, e.neighbour_id, e.neighbour, e.eff_mu, e.witnesses
    FROM consensus.edges(@extschema@.word_id(p_word), p_direction, NULL::bytea[],
                           p_limit, p_refuted,
                           converse.word_language(laplace.word_id(p_word))) e
$$;

-- Generic Browse NAME lane. Structural candidate generation stays behind the
-- sanctioned trajectory-containment boundary; all relation-family/Glicko access
-- stays here in the consensus boundary. The result is still canonical ids and
-- typed standing state; rendering happens after page selection.
DROP FUNCTION IF EXISTS consensus.browse_named_entities(bytea[], bytea, int, int, int);
CREATE OR REPLACE FUNCTION consensus.browse_named_entities(
    p_members bytea[],
    p_exact bytea DEFAULT NULL,
    p_offset int DEFAULT 0,
    p_limit int DEFAULT 40,
    p_capacity int DEFAULT 2048)
    RETURNS TABLE(
        entity_id bytea,
        tier smallint,
        type_id bytea,
        matched_name_id bytea,
        match_kind text,
        rating numeric,
        rd numeric,
        eff_mu numeric,
        witness_count bigint,
        candidate_name_count bigint,
        candidate_truncated boolean,
        matched_entity_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH names AS MATERIALIZED (
        SELECT c.entity_id AS name_id, c.candidate_count, c.truncated
        FROM structural.word_containers_containing_all(p_members, p_capacity) c
    ), name_stats AS MATERIALIZED (
        SELECT COALESCE(max(candidate_count), 0)::bigint AS candidate_count,
               COALESCE(bool_or(truncated), false) AS truncated
        FROM names
    ), named AS MATERIALIZED (
        SELECT c.subject_id AS entity_id,
               c.object_id AS matched_name_id,
               'name'::text AS match_kind,
               round((c.rating / 1e9)::numeric, 3) AS rating,
               round((c.rd / 1e9)::numeric, 3) AS rd,
               consensus.eff_mu_display(c.rating, c.rd) AS eff_mu,
               c.witness_count,
               row_number() OVER (
                   PARTITION BY c.subject_id
                   ORDER BY consensus.eff_mu(c.rating, c.rd) DESC,
                            c.witness_count DESC,
                            c.object_id) AS name_rank
        FROM names n
        JOIN laplace.consensus c ON c.object_id = n.name_id
        WHERE c.type_id = ANY (
                consensus.relation_family_ids('HAS_NAME')
                || consensus.relation_family_ids('HAS_NAME_ALIAS'))
          AND NOT consensus.refuted(c.rating, c.rd)
    ), direct AS MATERIALIZED (
        SELECT p_exact AS entity_id,
               p_exact AS matched_name_id,
               'surface'::text AS match_kind,
               NULL::numeric AS rating,
               NULL::numeric AS rd,
               NULL::numeric AS eff_mu,
               0::bigint AS witness_count,
               1::bigint AS name_rank
        WHERE p_exact IS NOT NULL AND consensus.entity_exists(p_exact)
    ), combined AS MATERIALIZED (
        SELECT entity_id, matched_name_id, match_kind, rating, rd, eff_mu, witness_count, 0 AS priority
        FROM named WHERE name_rank = 1
        UNION ALL
        SELECT entity_id, matched_name_id, match_kind, rating, rd, eff_mu, witness_count, 1 AS priority
        FROM direct
    ), dedup AS MATERIALIZED (
        SELECT x.entity_id, x.matched_name_id, x.match_kind, x.rating, x.rd, x.eff_mu,
               x.witness_count, x.priority
        FROM (
            SELECT c.*,
                   row_number() OVER (
                       PARTITION BY c.entity_id
                       ORDER BY c.priority, c.eff_mu DESC NULLS LAST,
                                c.witness_count DESC, c.matched_name_id) AS rn
            FROM combined c
        ) x
        WHERE x.rn = 1
    ), ranked AS MATERIALIZED (
        SELECT d.*,
               count(*) OVER ()::bigint AS matched_entity_count,
               row_number() OVER (
                   ORDER BY d.priority, d.eff_mu DESC NULLS LAST,
                            d.witness_count DESC, d.entity_id) AS ord
        FROM dedup d
    ), page AS MATERIALIZED (
        SELECT r.*
        FROM ranked r
        WHERE r.ord > GREATEST(COALESCE(p_offset, 0), 0)
          AND r.ord <= GREATEST(COALESCE(p_offset, 0), 0) + GREATEST(COALESCE(p_limit, 0), 0)
    ), ids AS MATERIALIZED (
        SELECT COALESCE(array_agg(p.entity_id ORDER BY p.ord), '{}'::bytea[]) AS ids
        FROM page p
    ), facets AS MATERIALIZED (
        SELECT f.entity_id, f.tier, f.type_id
        FROM ids i, ops.entity_facets_batch(i.ids) f
    )
    SELECT p.entity_id, f.tier, f.type_id, p.matched_name_id, p.match_kind,
           p.rating, p.rd, p.eff_mu, p.witness_count,
           s.candidate_count, s.truncated, p.matched_entity_count
    FROM page p
    JOIN facets f ON f.entity_id = p.entity_id
    CROSS JOIN name_stats s
    ORDER BY p.ord;
END;
DROP FUNCTION IF EXISTS laplace.related(bytea, bytea, bytea, int);
CREATE OR REPLACE FUNCTION consensus.related(p_word bytea, p_type bytea, p_lang bytea DEFAULT NULL,
                                   p_limit int DEFAULT 10)
    RETURNS TABLE(fact text, eff_mu numeric, witnesses bigint)
-- No SET search_path — blocks inlining, costs the consensus index path. GH #860.
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH subj(id) AS (
        SELECT p_word UNION SELECT sn.synset_id FROM lexical.senses(p_word) sn
    ), top AS (
        SELECT cc.object_id, cc.rating, cc.rd, cc.witness_count
        FROM subj s CROSS JOIN LATERAL (
            SELECT c.object_id, c.rating, c.rd, c.witness_count
            FROM laplace.v_consensus_unrefuted c
            WHERE c.subject_id = s.id AND c.type_id = p_type
              AND c.object_id IS NOT NULL
            ORDER BY consensus.eff_mu(c.rating, c.rd) DESC LIMIT p_limit
        ) cc
    ), ranked AS (
        -- rank + LIMIT on ids BEFORE labeling (was: scalar realize per row over
        -- the num_senses x p_limit pool, labeling more rows than returned).
        SELECT t.object_id, t.rating, t.rd, t.witness_count,
               row_number() OVER (ORDER BY consensus.eff_mu(t.rating, t.rd) DESC) AS ord
        FROM top t
        ORDER BY consensus.eff_mu(t.rating, t.rd) DESC
        LIMIT p_limit
    ), labels AS (
        -- ONE realize_batch over exactly the returned rows, position-aligned.
        SELECT realize.batch(array_agg(r.object_id ORDER BY r.ord),
                             COALESCE(p_lang, converse.word_language(p_word))) AS l
        FROM ranked r
    )
    SELECT labels.l[r.ord], consensus.eff_mu_display(r.rating, r.rd), r.witness_count
    FROM ranked r, labels
    ORDER BY r.ord
$$;
DROP FUNCTION IF EXISTS laplace.related_in(bytea, bytea, bytea, int);
CREATE OR REPLACE FUNCTION consensus.related_in(p_word bytea, p_type bytea, p_lang bytea DEFAULT NULL,
                                      p_limit int DEFAULT 10)
    RETURNS TABLE(fact text, eff_mu numeric, witnesses bigint)
-- No SET search_path — blocks inlining, costs the consensus index path. GH #860.
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH subj(id) AS (
        SELECT p_word UNION SELECT sn.synset_id FROM lexical.senses(p_word) sn
    ), top AS (
        SELECT cc.subject_id, cc.rating, cc.rd, cc.witness_count
        FROM subj s CROSS JOIN LATERAL (
            SELECT c.subject_id, c.rating, c.rd, c.witness_count
            FROM laplace.v_consensus_unrefuted c
            WHERE c.object_id = s.id AND c.type_id = p_type
            ORDER BY consensus.eff_mu(c.rating, c.rd) DESC LIMIT p_limit
        ) cc
    ), ranked AS (
        -- rank + LIMIT on ids BEFORE labeling (was: scalar realize per row over
        -- the num_senses x p_limit pool, labeling more rows than returned).
        SELECT t.subject_id, t.rating, t.rd, t.witness_count,
               row_number() OVER (ORDER BY consensus.eff_mu(t.rating, t.rd) DESC) AS ord
        FROM top t
        ORDER BY consensus.eff_mu(t.rating, t.rd) DESC
        LIMIT p_limit
    ), labels AS (
        -- ONE realize_batch over exactly the returned rows, position-aligned.
        SELECT realize.batch(array_agg(r.subject_id ORDER BY r.ord),
                             COALESCE(p_lang, converse.word_language(p_word))) AS l
        FROM ranked r
    )
    SELECT labels.l[r.ord], consensus.eff_mu_display(r.rating, r.rd), r.witness_count
    FROM ranked r, labels
    ORDER BY r.ord
$$;
-- The relation-select primitive, addressed BY RELATION NAME: a caller that knows
-- it wants HAS_DEFINITION says so in text and never open-codes the scan. One
-- implementation per fact (06 Rule #6) — a relation-name typo (the
-- DEFINES/HAS_DEFINITION bug) can only exist in the CALLER's name argument.
--
-- The name resolution is all this adds. The scan underneath is consensus.edges_raw() —
-- the one consensus scan — with the axes this signature has always pinned:
-- outbound, one relation type, unrefuted, consensus.eff_mu order, p_limit as a query
-- limit. The body used to hand-roll that scan and open-code `rating - 2*rd`
-- instead of consensus.eff_mu(); the two are the same expression, now stated once.
--
-- Two deliberate changes came with the delegation:
--   * ties on consensus.eff_mu now break on neighbour_id, so the cap is deterministic
--     rather than plan-dependent.
--   * edges_raw's outbound arm requires object_id IS NOT NULL, so a unary
--     attestation of p_relation can no longer surface here as a row whose
--     object_id is NULL. This function returns objects; a NULL one was never an
--     answer a caller could use.
--
-- No SET search_path and no STRICT — either blocks inlining and costs the
-- consensus index path (#617, #860). NULL-safety without STRICT: a NULL
-- p_subject matches no subject_id, and laplace.relation_type_id(NULL) matches no
-- type_id, so both still return zero rows.
DROP FUNCTION IF EXISTS laplace.related_objects(bytea, text, int);
CREATE OR REPLACE FUNCTION consensus.related_objects(
        p_subject bytea, p_relation text, p_limit int DEFAULT 8)
    RETURNS TABLE(object_id bytea, eff_mu bigint, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT e.neighbour_id,
           consensus.eff_mu(e.rating, e.rd) AS eff_mu,
           e.witness_count                    AS witnesses
    FROM consensus.edges_raw(p_subject, 'out',
                               ARRAY[laplace.relation_type_id(p_relation)],
                               p_limit, false, 'eff_mu') e
$$;
DROP FUNCTION IF EXISTS laplace.salient_facts(bytea, bytea, int);
CREATE OR REPLACE FUNCTION consensus.salient_facts(p_word bytea, p_lang bytea DEFAULT NULL,
                                    p_limit int DEFAULT 24)
    RETURNS TABLE(type text, fact text, eff_mu numeric, witnesses bigint)
-- No SET search_path — blocks inlining, costs the consensus index path. The
-- workaround below (fencing relation_in_family ONCE because its own SET clause
-- makes it uninlinable) is the same defect one level down. GH #860.
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH reltypes AS MATERIALIZED (
        SELECT id FROM laplace.entities
        WHERE type_id = laplace.entity_type_id('RelationType')
    ), feat_dynamic AS MATERIALIZED (
        -- Dynamic HAS_FEATURE children (FEAT_case, FEAT_number, ...) carry an
        -- IS_A -> family-root edge in consensus (RelationTypeRegistry.SeedDynamic).
        -- Fenced ONCE here: the SQL wrapper consensus.relation_in_family() carries a SET
        -- search_path clause, so the planner can never inline it and its EXISTS
        -- probe would run per candidate row. (relation_type_in_family below is the
        -- C IMMUTABLE static check — cheap per row, unaffected.) Same truth table:
        -- static family via the C check, dynamic membership via this set.
        SELECT c.subject_id AS id FROM laplace.consensus c
        WHERE c.type_id = laplace.relation_type_id('IS_A')
          AND c.object_id = laplace.relation_type_id('HAS_FEATURE')
    ), lang AS (
        -- Resolved ONCE, not per candidate row. When p_lang is supplied COALESCE
        -- short-circuits and converse.word_language() is never evaluated.
        SELECT COALESCE(p_lang, converse.word_language(p_word)) AS l
    ), subj(id) AS (
        SELECT p_word UNION SELECT sn.synset_id FROM lexical.senses(p_word) sn
    ), top AS (
        SELECT cc.type_id, cc.object_id, cc.rating, cc.rd, cc.witness_count
        FROM subj s CROSS JOIN LATERAL (
            SELECT c.type_id, c.object_id, c.rating, c.rd, c.witness_count
            FROM laplace.v_consensus_unrefuted c
            LEFT JOIN reltypes obj_rt ON obj_rt.id = c.object_id
            WHERE c.subject_id = s.id AND c.object_id IS NOT NULL
              -- = ANY(ARRAY(SELECT ...)), not IN (SELECT ...): the array form is an
              -- InitPlan, bound BEFORE the scan, so type_id can prune the LIST
              -- partitions at run time. The semi-join form leaves the partition key a
              -- per-row comparison and prunes nothing. Semantics are identical --
              -- reltypes is a data read (every RelationType entity), so it stays a
              -- subquery; only the binding changes.
              AND c.type_id = ANY (ARRAY(SELECT id FROM reltypes))
              AND c.type_id <> ALL (consensus.relation_family_ids('HAS_POS'))
              AND c.type_id <> ALL (consensus.relation_family_ids('HAS_FEATURE'))
              AND c.type_id NOT IN (SELECT id FROM feat_dynamic)
              AND -- The exclusion set is DECLARED: engine/manifest/relation_types.toml [[set]]
          -- NON_SALIENT_STRUCTURAL. It was a byte-identical 16-name NOT IN list here AND
          -- in the sibling function -- one judgement about what is not a content fact,
          -- kept in two files with nothing holding them in step. `<> ALL` matches the two
          -- family exclusions above and is exactly equivalent to NOT IN here: type_id is
          -- NOT NULL on both laplace.consensus and laplace.attestations (catalog-verified).
          c.type_id <> ALL (consensus.relation_set_ids('NON_SALIENT_STRUCTURAL'))
          -- UNDECLARED VOCABULARY, kept inline deliberately: CO_OCCURS_WITH and
          -- OCCURS_IN_CONTEXT are in neither the manifest's canonicals nor its
          -- aliases, though both exist as live RelationType entities. Codegen
          -- REFUSES a set naming them (an undeclared member would emit NULL and
          -- silently match nothing), and inventing a bit/rank/symmetry for them
          -- is an operator decision. Row counts are deliberately NOT cited as the reason
          -- either way: spec 36's CORRECTION 2026-07-25 retracts exactly that move for this
          -- family of relations ("a low PRECEDES count is not a status signal -- do not cite
          -- it"), because sequence lives in the trajectory and these are views of it.
          AND c.type_id NOT IN (
                laplace.relation_type_id('CO_OCCURS_WITH'),
                laplace.relation_type_id('OCCURS_IN_CONTEXT'))
              AND obj_rt.id IS NULL
            ORDER BY consensus.eff_mu(c.rating, c.rd) DESC,
                     c.type_id, c.object_id
            LIMIT GREATEST(p_limit, 0)
        ) cc
    ), ranked AS (
        -- Rank BEFORE labeling (mirrors evidence_receipt's Issue 52). The old
        -- shape ran realize.realize() + type_label over EVERY row of `top` (dog: 413
        -- rows across 10 subjects) only to ORDER/LIMIT to p_limit afterwards --
        -- ~1.5ms/realize.render x 413 dominated the call (~575ms warm on real data).
        -- Ranking needs only the consensus.eff_mu already in `top`, so it runs first over
        -- everything. Labeling is total below: an unrenderable entity/relation
        -- receives a deterministic hash label instead of making a ranked fact
        -- disappear. Therefore the exact p_limit head is sufficient; the old
        -- `3x + 8` pool was neither a correctness proof nor a caller contract.
        SELECT t.type_id, t.object_id, t.rating, t.rd, t.witness_count,
               consensus.eff_mu(t.rating, t.rd) AS sort_mu
        FROM top t
        ORDER BY consensus.eff_mu(t.rating, t.rd) DESC,
                 t.type_id, t.object_id
        LIMIT GREATEST(p_limit, 0)
    )
    , ordered AS (
        SELECT r.*, row_number() OVER (ORDER BY r.sort_mu DESC) AS ord
        FROM ranked r
    ), labels AS (
        -- ONE realize_batch over the ranked pool (was: scalar realize per row).
        SELECT realize.batch(array_agg(o.object_id ORDER BY o.ord),
                             (SELECT l FROM lang)) AS l,
               lexical.type_label_batch(array_agg(o.type_id ORDER BY o.ord)) AS types
        FROM ordered o
    )
    SELECT d.type, d.fact, d.eff_mu, d.witnesses FROM (
        SELECT COALESCE(NULLIF(labels.types[o.ord], ''),
                        consensus.relation_canonical(o.type_id),
                        'Unrealized relation') AS type,
               COALESCE(NULLIF(labels.l[o.ord], ''),
                        'Unrealized entity') AS fact,
               consensus.eff_mu_display(o.rating, o.rd) AS eff_mu, o.witness_count AS witnesses,
               o.sort_mu
        FROM ordered o, labels
    ) d
    ORDER BY d.sort_mu DESC
    LIMIT GREATEST(p_limit, 0)
$$;
-- consensus.belief_distribution(subject, relation, k) -- the normalised
-- distribution over what a subject couples to under one relation.
--
-- This is the surface a softmax output layer approximates, answered from
-- adjudicated evidence instead of from a dot product. generation.adjudicated_row
-- (model/model_consensus.sql.in) already answers the RANKING half exactly and
-- says so in its comment; the PROBABILITY half had no body anywhere in the tree.
-- consensus.weight()'s four modes are all per-edge scalars -- conservative,
-- salience, complete, strength -- and none normalises over a candidate set;
-- consensus.edge_strength is a per-edge logistic against neutral, which squashes
-- but does not sum to one. The only normalised conditional that existed,
-- generation.continuation_conditional_plane, is built from trajectory counts at
-- export and never touches laplace.consensus.
--
-- WHAT p IS, EXACTLY. It is this object's share of the attested candidate set for
-- (subject, relation) -- NOT a probability that the claim is true. Normalisation
-- runs over the FULL set and p_k truncates only the output, so it is not a
-- shortlist artifact; but ingesting one more witnessed object for the same subject
-- and relation changes every other p. A distribution over what has been attested is
-- the only thing evidence supports, and it is not a distribution over what is so.
-- subject_id + type_id prunes laplace.consensus to one measured leaf, so the full
-- set is one index range and the window has nothing to fan
-- out over.
--
-- ORDER AND MASS ARE THE SAME OBJECT. INVENTION §5: belief is rating - 2*rd and "all
-- ranked reads order by it." An earlier revision obeyed that in the ORDER BY while
-- weighting with consensus.glicko2_logit, which penalises rd by a different law --
-- and the two disagree on real pairs, so the top row was not the heaviest row and
-- "take the best" and "sample p" returned different objects from one call. Both are
-- now consensus.belief_logit: eff_mu on Glicko-2's own scale. p descending and eff_mu
-- descending are therefore the same order by construction, not by coincidence.
--
-- ABSTENTION IS THE POINT. No candidates -> no rows. A softmax cannot express
-- "couples to nothing under this relation"; it sums to 1 over whatever vector it
-- was handed, which is why a model fabricates a capital for a country it has no
-- edge for. The empty set is the honest answer and this returns it.
--
-- Refuted edges are NOT filtered. A refutation drives rating below neutral, so
-- its logit is negative and exp() suppresses it to near zero without a gate --
-- and the mass stays visible in the output rather than being silently removed.
CREATE OR REPLACE FUNCTION consensus.belief_distribution(
        p_subject  bytea,
        p_relation text,
        p_k        integer DEFAULT 20)
    RETURNS TABLE(object_id bytea, p double precision, logit double precision,
                  eff_mu numeric, rd bigint, witness_count bigint)
-- No SET search_path — blocks inlining, costs the consensus index path. GH #860.
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH cand AS (
        SELECT c.object_id AS oid,
               consensus.belief_logit(c.rating, c.rd) AS lg,
               consensus.eff_mu_display(c.rating, c.rd) AS emu,
               consensus.eff_mu(c.rating, c.rd) AS emu_raw,
               c.rd AS crd,
               c.witness_count AS wc
        FROM laplace.consensus c
        WHERE c.subject_id = p_subject
          AND c.type_id    = laplace.relation_type_id(p_relation)
          AND c.object_id IS NOT NULL
    ),
    -- max-shift before exp(): the standard overflow guard, not a temperature.
    -- It cancels in the ratio, so p is unchanged by it.
    shifted AS (
        SELECT oid, lg, emu, emu_raw, crd, wc, exp(lg - max(lg) OVER ()) AS w FROM cand
    )
    SELECT oid, w / sum(w) OVER (), lg, emu, crd, wc
    FROM shifted
    ORDER BY emu_raw DESC, oid
    LIMIT p_k;
END;

COMMENT ON FUNCTION consensus.belief_distribution(bytea, text, integer) IS
    'Bradley-Terry share of the attested candidate set for one subject under one '
    'relation, from Glicko-2 log-odds with RD folded in. Not a probability of truth: '
    'a new witnessed object changes every other p. Ordered by eff_mu per INVENTION '
    'section 5; empty when the subject couples to nothing.';
-- consensus.set_members(subject, relation) -- the members of a set-valued attribute,
-- read from the bundle composition instead of from a fan of edges.
--
-- Replaces the N-row fan. Through a bundle, a morphological analysis is one consensus row
-- (carrying the rating, rd and witness_count OF THE ANALYSIS) plus its packed members.
--
-- ord is the canonical position -- ascending by member id, the order StageCollection
-- sorts into before the merkle. It is NOT a sequence. A set whose members carried
-- order would be a trajectory of PhysicalityType.Content, not PhysicalityType.Set.
--
-- The physicalities join is by entity_id while the table is HASH (id), so it probes
-- physicalities_entity_btree across all 64 leaves. That reverse-key cost is bounded
-- here because the consensus side has already
-- pruned to one leaf on (subject_id, type_id) and yields at most a handful of bundles.
CREATE OR REPLACE FUNCTION consensus.set_members(p_subject bytea, p_relation text)
    RETURNS TABLE(bundle_id bytea, member_id bytea, ord bigint,
                  eff_mu numeric, rd bigint, witness_count bigint)
-- No SET search_path — blocks inlining, costs the consensus index path. GH #860.
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT c.object_id, m.id, m.ord,
           consensus.eff_mu_display(c.rating, c.rd), c.rd, c.witness_count
    FROM laplace.consensus c
    JOIN laplace.physicalities p
      ON p.entity_id = c.object_id AND p.type = 5 AND p.trajectory IS NOT NULL
    CROSS JOIN LATERAL unnest(public.laplace_trajectory_constituent_ids(p.trajectory))
         WITH ORDINALITY AS m(id, ord)
    WHERE c.subject_id = p_subject
      AND c.type_id    = laplace.relation_type_id(p_relation)
    ORDER BY c.object_id, m.ord;
END;

COMMENT ON FUNCTION consensus.set_members(bytea, text) IS
    'Members of a set-valued attribute, from the bundle composition. ord is canonical '
    '(ascending by member id), never a sequence.';
-- consensus.subjects_with(relation, members) -- every subject whose set-valued
-- attribute CONTAINS all of p_members.
--
-- This is the read the edge fan cannot serve. "Which forms are nominative AND singular
-- AND masculine" otherwise requires one self-join arm per tag. Against bundles it is one
-- GIN containment probe (physicalities_set_constituents_gin), then one reverse-edge read.
--
-- The bundle ids arrive as an InitPlan-bound ARRAY(SELECT ...), NOT as a CTE column
-- joined to consensus. Measurements at two independent sites show that
-- the array form binds before the scan and emits a ScalarArrayOp, the CTE column is a
-- per-row variable the planner cannot bind and costs 4x. The contents are data-dependent
-- so the manifest-folded form is unavailable; ARRAY(SELECT ...) is the correct middle
-- rung of that ladder.
--
-- p_relation is required for the same reason: object_id prunes NEITHER partition level
-- (the hash key is subject_id), so a reverse read without type_id pays all 216 leaves.
-- With it, 8.
CREATE OR REPLACE FUNCTION consensus.subjects_with(
        p_relation text, p_members bytea[], p_limit integer DEFAULT 100)
    RETURNS TABLE(subject_id bytea, bundle_id bytea,
                  eff_mu numeric, rd bigint, witness_count bigint)
-- No SET search_path — blocks inlining, costs the consensus index path. GH #860.
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT c.subject_id, c.object_id,
           consensus.eff_mu_display(c.rating, c.rd), c.rd, c.witness_count
    FROM laplace.consensus c
    WHERE c.type_id = laplace.relation_type_id(p_relation)
      AND c.object_id = ANY (ARRAY(
              SELECT p.entity_id
              FROM laplace.physicalities p
              WHERE p.type = 5
                AND p.trajectory IS NOT NULL
                AND public.laplace_trajectory_constituent_ids(p.trajectory) @> p_members))
    ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.subject_id
    LIMIT p_limit;
END;

COMMENT ON FUNCTION consensus.subjects_with(text, bytea[], integer) IS
    'Subjects whose set-valued attribute contains every member given. One GIN '
    'containment probe over the bundles, then one type-pruned reverse-edge read.';
-- consensus.usage_overlap — GH #862 / #860. No SET (it invalidates plan caching and
-- blocks inlining), real schema names, no build-time placeholder.
DROP FUNCTION IF EXISTS laplace.usage_overlap(bytea, bytea);
CREATE OR REPLACE FUNCTION consensus.usage_overlap(p_x bytea, p_y bytea)
    RETURNS bigint
    LANGUAGE sql STABLE PARALLEL SAFE STRICT AS $$
    -- Pillar 5 (2026-07-20): shared-usage is read from the GEOMETRY. The usage
    -- neighbourhood of a point is the adjacent content constituent in every
    -- trajectory containing it -- the same knowledge PRECEDES materialised as
    -- redundant laplace.attestations(Pillar 3a, e5e1b42). BIDIRECTIONAL, as the
    -- consensus form was: the trajectory holds the exact sequence, so both
    -- directions are readable and the measure is never truncated to fit the walk.
    WITH xn(n) AS (
        SELECT neighbour_id FROM structural.geometry_neighbours(p_x, 200, 8)
    ), yn(n) AS (
        SELECT neighbour_id FROM structural.geometry_neighbours(p_y, 200, 8)
    )
    SELECT count(*)::bigint FROM xn JOIN yn USING (n)
$$;
-- Native path election. The C implementation expands each taxonomy frontier in
-- one batched SPI call per depth, deduplicates by node at minimum depth, and
-- retains the widest bottleneck on same-depth rediscovery. Every lexical sense
-- seeds both arms with its attested sense mu. The lateral plane is two batched
-- scans over the same installed taxonomy edge surface, one per orientation.
-- Relation membership remains owned by the manifest-generated
-- consensus.relation_set_ids operation; no relation roster is duplicated here
-- or in C.
DROP FUNCTION IF EXISTS laplace.relate_path_raw(bytea, bytea, int);
CREATE OR REPLACE FUNCTION consensus.relate_path_raw(
        p_x bytea,
        p_y bytea,
        p_depth int DEFAULT 7)
    RETURNS TABLE(nodes bytea[], types bytea[], dirs int[],
                  path_mu numeric, plane_type bytea)
    LANGUAGE C STABLE STRICT PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_relate_path_raw';

-- Rendering is deliberately outside the search and runs once, after native
-- election. There is no session SET clause: the body is fully qualified and
-- remains eligible for SQL inlining.
DROP FUNCTION IF EXISTS laplace.relate_path(bytea, bytea, int);
CREATE OR REPLACE FUNCTION consensus.relate_path(
        p_x bytea,
        p_y bytea,
        p_depth int DEFAULT 7)
    RETURNS TABLE(chain text, path_mu numeric, plane text)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT realize.path(r.nodes, r.types, r.dirs,
                        COALESCE(converse.word_language(p_x),
                                 converse.word_language(p_y))) AS chain,
           r.path_mu,
           CASE WHEN r.plane_type IS NULL THEN 'taxonomy'
                ELSE lexical.type_label(r.plane_type) END AS plane
    FROM consensus.relate_path_raw(p_x, p_y, p_depth) r;
END;
-- consensus.relation_summary — GH #862 / #860. No SET, real schema names.
DROP FUNCTION IF EXISTS laplace.relation_summary(bytea, bytea);
CREATE OR REPLACE FUNCTION consensus.relation_summary(p_x bytea, p_y bytea)
    RETURNS TABLE(relation text, plane text, mu numeric, usage bigint,
                  geodesic double precision, verdict text)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT r.chain, r.plane, r.path_mu, COALESCE(u.n, 0), g.geo,
           concat_ws('',
             CASE WHEN r.chain IS NOT NULL THEN 'related via ' || r.plane
                  ELSE 'no witnessed conceptual path' END,
             CASE WHEN COALESCE(u.n, 0) > 0 THEN '; shared usage (' || u.n || ')'
                  ELSE '' END)
    FROM (SELECT 1) one
    -- No LIMIT: relate_path already picks its single winner on (len, mu) before it
    -- renders anything, so it returns at most one row. The LIMIT that used to sit
    -- here read as a guard over an unordered pick and would have silently masked a
    -- real regression if that internal ranking were ever dropped.
    LEFT JOIN LATERAL (SELECT * FROM consensus.relate_path(p_x, p_y)) r ON true
    LEFT JOIN LATERAL (SELECT consensus.usage_overlap(p_x, p_y) AS n) u ON true
    LEFT JOIN LATERAL (
        SELECT public.laplace_angular_distance_4d(
            (SELECT coord FROM laplace.v_word_points WHERE id = p_x AND coord IS NOT NULL LIMIT 1),
            (SELECT coord FROM laplace.v_word_points WHERE id = p_y AND coord IS NOT NULL LIMIT 1)) AS geo) g ON true
$$;
-- consensus.gaps — GH #862 / #860. No SET (it invalidates plan caching and blocks
-- inlining), real schema names, no build-time placeholder.
DROP FUNCTION IF EXISTS laplace.gaps(bytea);
CREATE OR REPLACE FUNCTION consensus.gaps(p_word bytea)
    RETURNS TABLE(missing_arena text)
    LANGUAGE sql STABLE PARALLEL SAFE STRICT AS $$
    WITH subj(id) AS (
        SELECT p_word UNION SELECT sn.synset_id FROM lexical.senses(p_word) sn
    ), expected(name) AS (SELECT unnest(ARRAY[
        'IS_A','HAS_PART','HAS_MEMBER','CAUSES','USED_FOR','IS_ANTONYM_OF',
        'IS_SIMILAR_TO','HAS_ATTRIBUTE','DERIVATIONALLY_RELATED']))
    -- A SYMMETRIC ARENA IS NOT A GAP WHEN THE EVIDENCE SITS ON THE OTHER END.
    --
    -- IS_ANTONYM_OF, IS_SIMILAR_TO and DERIVATIONALLY_RELATED are symmetric, so
    -- their evidence folds into ONE cell oriented to subject = min(subject,
    -- object) by hash bytes. Probing subject_id alone therefore reported the
    -- arena "missing" for every word that happens to be the greater-hashed
    -- endpoint -- manufacturing an absence out of a byte comparison. Spec 05 is
    -- explicit that absence of a row is UNKNOWN, and this function's whole
    -- output is a claim about absence, so a false negative here is the one
    -- failure it cannot afford.
    --
    -- Two arms rather than an OR-join: each stays indexable
    -- (consensus_subject_type_btree / consensus_object_type_btree), and the
    -- symmetry test is a function of e.name, so it is evaluated once per
    -- expected arena rather than once per consensus row. Asymmetric arenas keep
    -- the forward-only semantics -- IS_A up is not IS_A down.
    SELECT e.name FROM expected e
    WHERE NOT EXISTS (
        SELECT 1 FROM laplace.v_consensus_unrefuted c JOIN subj s ON c.subject_id = s.id
        WHERE c.type_id = laplace.relation_type_id(e.name)
        UNION ALL
        SELECT 1 FROM laplace.v_consensus_unrefuted c JOIN subj s ON c.object_id = s.id
        WHERE c.type_id = laplace.relation_type_id(e.name)
          AND COALESCE(consensus.relation_is_symmetric(
                           laplace.relation_type_id(e.name)), false))
$$;
-- taxonomy.bubble_up_batch(terms[], domain_context[], k): bubble_up for a SET of terms
-- in one pass. Same election, same ordering, same output columns, plus the term.
--
-- WHY THIS EXISTS. taxonomy.bubble_up takes ONE term, so every caller that needs senses
-- for a token stream calls it per token and re-runs the entire CTE cascade each
-- time. Measured under auto_explain on generation.compose_batch('what is a wolf', 12):
-- CTE Scan `scoped` 51,351 ms over 798 loops, `cand_lang` 32,438 ms over 728 loops,
-- `family_out` 15,358 ms over 2,394 loops -- 51.4 s of a 52.2 s statement, to elect
-- senses for ~266 distinct tokens. The work per token is small; the repetition is
-- the cost.
--
-- WHAT ACTUALLY COLLAPSES. cand_lang is the clearest case: the scalar form issues one
-- attestations probe per term, and attestations cannot prune on subject_id, so each
-- probe pays the full partition set. Batched, every candidate synset of every term
-- is resolved by ONE probe. term_lang and peers stay per-term (they are per-term
-- facts) but run as one set-based pass instead of N statements.
--
-- ORDERING IS PER TERM. row_number() OVER (PARTITION BY term ORDER BY the complete
-- evidence order) applies an explicit p_k independently to each term. This file owns
-- that order; the scalar is only a one-element adapter and cannot drift from it.
DROP FUNCTION IF EXISTS taxonomy.bubble_up_batch(bytea[], bytea[], integer);
CREATE OR REPLACE FUNCTION taxonomy.bubble_up_batch(
    p_terms bytea[],
    p_domain_context bytea[] DEFAULT NULL,
    -- NULL = no truncation. See the note above `ordered`: a default number here
    -- would cut the candidate field before the election.
    p_k integer DEFAULT NULL
)
RETURNS TABLE(
    term bytea,
    sense_id bytea,
    synset_id bytea,
    via_relation text,
    score numeric,
    base_eff_mu numeric,
    domain_hits bigint,
    witnesses bigint
)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
WITH terms AS (
    SELECT DISTINCT t AS term
    FROM unnest(COALESCE(p_terms, ARRAY[]::bytea[])) AS t
    WHERE t IS NOT NULL
),
direct_terms AS MATERIALIZED (
    SELECT DISTINCT t.term
    FROM terms t
    JOIN laplace.consensus c ON c.subject_id = t.term
    WHERE c.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
),
unresolved AS MATERIALIZED (
    SELECT t.term FROM terms t
    LEFT JOIN direct_terms d USING (term)
    WHERE d.term IS NULL
),
peers AS MATERIALIZED (
    -- Exact identity is the fast path. Only terms with no witnessed sense enter
    -- orthographic widening, and all of those widen in one native pass.
    SELECT d.term, d.term AS id FROM direct_terms d
    UNION ALL
    SELECT v.word_id, v.variant_id
    FROM lexical.word_case_variants_batch(
        ARRAY(SELECT u.term FROM unresolved u ORDER BY u.term)) v
),
family_out AS (
    SELECT p.term,
           c.object_id AS target_id,
           consensus.relation_canonical(c.type_id) AS via_relation,
           consensus.eff_mu_display(c.rating, c.rd) AS base_eff_mu,
           c.witness_count AS witnesses,
           c.rating,
           c.rd
    FROM peers p
    JOIN laplace.consensus c ON c.subject_id = p.id
    -- Inline, not a CTE column: IMMUTABLE + constant arg folds to a literal bytea[]
    -- before planning, so the LIST partitions prune. See realize.resolve_name.
    WHERE c.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
),
resolved AS (
    
    SELECT fo.term,
           fo.target_id AS sense_id,
           COALESCE(ss.object_id, fo.target_id) AS synset_id,
           fo.via_relation,
           fo.base_eff_mu,
           (fo.witnesses + COALESCE(ss.witness_count, 0))::bigint AS witnesses,
           fo.rating,
           fo.rd
    FROM family_out fo
    LEFT JOIN laplace.consensus ss
      ON ss.subject_id = fo.target_id
     AND ss.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
     AND consensus.relation_canonical(ss.type_id) = 'IS_SENSE_OF'
    WHERE fo.via_relation = 'HAS_SENSE'

    UNION ALL

    
    SELECT fo.term, fo.target_id, fo.target_id, fo.via_relation,
           fo.base_eff_mu, fo.witnesses, fo.rating, fo.rd
    FROM family_out fo
    WHERE fo.via_relation = 'IS_SYNONYM_OF'

    UNION ALL

    
    SELECT fo.term, fo.target_id, fo.target_id, fo.via_relation,
           fo.base_eff_mu, fo.witnesses, fo.rating, fo.rd
    FROM family_out fo
    WHERE fo.via_relation = 'IS_SENSE_OF'
),
-- An explicitly empty context lets an owning caller perform language election
-- after receiving the complete candidate field. NULL retains automatic language
-- scoping for scalar and ordinary batch callers; a nonempty context still applies
-- both language and domain constraints.
language_filter AS MATERIALIZED (
    SELECT p_domain_context IS NULL OR cardinality(p_domain_context) > 0 AS requested
),
-- Per-term fact, set-based pass. Language is a CONSTRAINT on which surface the
-- input denotes, never a score -- a boolean
-- "has an edge to the query language" does not discriminate.
term_lang AS MATERIALIZED (
    SELECT al.id AS term, al.lang AS id
    FROM converse.attested_language_batch(ARRAY(SELECT term FROM terms)) al
    CROSS JOIN language_filter lf
    WHERE lf.requested
),
-- ONE probe for EVERY candidate synset of EVERY term, through the canonical body
-- (§15: this argmax used to be inlined here AND written again as the scalar
-- converse.attested_language). attestations cannot prune on
-- subject_id, so the scalar form paid the full partition set once per term; this
-- pays it once for the whole batch.
-- = ANY(ARRAY(SELECT ...)), NOT A JOIN. This one is scale-dependent and the small-set
-- measurement gives the WRONG answer.
--
-- Standalone on 1,362 candidate synsets, identical 844 rows:
--   JOIN on a.subject_id      413 ms
--   = ANY(ARRAY(SELECT ...))  587 ms
--   IN (SELECT ...) semi-join 1,145 ms
-- so the join looks best. At real scale it is not. Measured under auto_explain on
-- generation.compose_batch('what is a wolf', 12), same output both ways:
--   array form   cand_lang  30,623 ms,   Index probes    18,555 loops
--   join form    cand_lang 150,653 ms,   Index probes 1,076,788 loops
-- The join becomes a nested loop issuing one probe per candidate; the array form is
-- ONE bounded ScalarArrayOp per partition however many ids it carries. laplace.attestations
-- is LIST (type_id) and this predicate is on subject_id, so nothing prunes and the
-- probe count is what decides.
--
-- Routing the same set through converse.attested_language_batch as an ARGUMENT is worse
-- again -- the set must materialise as one Datum before the call, and the whole
-- bubble_up_batch went 3,155 -> 4,950 ms. attested_language_batch stays canonical for
-- callers that already hold an array (term_lang below); this site holds a relation
-- and binds it as an InitPlan.
-- MEMBERSHIP, NOT ARGMAX. A SYNSET IS NOT IN ONE LANGUAGE. This was DISTINCT ON
-- (subject_id) ... ORDER BY SUM(sum_score_fp1e9) DESC -- one winning language per
-- synset -- and `scoped` then required cl.lang = tl.id. A synset is an interlingual
-- concept whose lemmas are deposited in every language OMW carries, so collapsing it
-- to its highest-scoring language and testing EQUALITY drops it for every other
-- language that attests it.
--
-- It fails hardest on the best data, which is why it stayed invisible: the more
-- translations a concept has, the smaller any one language's share of the score sum,
-- so a well-attested synset is MORE likely to argmax away from the query language.
-- An inverted quality filter.
--
-- MEASURED 2026-08-16. WordNet's dog#n#1 (02084071-n, synset 7c313cf0) carries
-- attestations in 229 distinct languages and argmaxes to BULGARIAN. The English
-- surface `dog` holds an unrefuted IS_SYNONYM_OF edge to it at eff_mu 1502.2, and
-- lexical.senses('dog') still returned five senses -- dog->stop (the pawl),
-- dog->support (andiron), hound->villain, dog->fellow, frank->sausage -- with the
-- canine sense absent. consensus.relate_path could then only answer cat/dog through
-- 'guy —is a→ man —is a→ male ←is a— fellow ←is a— dog'.
--
-- The three branches are unchanged in intent -- no term language, or no language on
-- the candidate, or the languages agree. Only the last one moves, from "the synset's
-- ONE language IS this" to "the synset ATTESTS this". Language stays a constraint and
-- never becomes a score, which is what the note above requires.
--
-- Both probes keep the = ANY(ARRAY(SELECT ...)) form the header measured: one bounded
-- ScalarArrayOp per partition, never a per-candidate nested loop. cand_lang_hit is
-- additionally bounded to the languages the terms actually use (at most one per term),
-- so it reads far less than the old argmax, which had to aggregate every language on
-- every candidate to find a maximum. The entities join is unnecessary there -- those
-- ids come from term_lang and are Language entities by construction.
cand_lang_hit AS MATERIALIZED (
    SELECT DISTINCT a.subject_id AS id, a.context_id AS lang
    FROM laplace.attestations a
        CROSS JOIN language_filter lf
    WHERE a.subject_id = ANY (ARRAY(SELECT DISTINCT r.synset_id FROM resolved r))
      AND a.context_id = ANY (ARRAY(SELECT tl.id FROM term_lang tl WHERE tl.id IS NOT NULL))
            AND lf.requested
),
cand_lang_any AS MATERIALIZED (
    SELECT DISTINCT a.subject_id AS id
    FROM laplace.attestations a
    JOIN laplace.entities e ON e.id = a.context_id
                           AND e.type_id = realize.canonical_id('Language')
        CROSS JOIN language_filter lf
    WHERE a.subject_id = ANY (ARRAY(SELECT DISTINCT r.synset_id FROM resolved r))
            AND lf.requested
),
scoped AS (
    SELECT r.* FROM resolved r
    LEFT JOIN term_lang tl ON tl.term = r.term
        CROSS JOIN language_filter lf
        WHERE NOT lf.requested
             OR tl.id IS NULL
       OR NOT EXISTS (SELECT 1 FROM cand_lang_any ca WHERE ca.id = r.synset_id)
       OR EXISTS (SELECT 1 FROM cand_lang_hit ch
                   WHERE ch.id = r.synset_id AND ch.lang = tl.id)
),
domain AS (
    SELECT DISTINCT d AS id
    FROM unnest(COALESCE(p_domain_context, ARRAY[]::bytea[])) AS d
    WHERE d IS NOT NULL
),
-- Feeds domain_scores ONLY. The cardinality gate keeps the geometry_neighbours
-- lateral from ever being evaluated on the no-domain path.
-- Keyed by synset, not by term: a synset's domain hits do not depend on which
-- term reached it.
members AS (
    SELECT r.synset_id, m.object_id AS member_id
    FROM scoped r
    JOIN laplace.consensus m ON m.subject_id = r.synset_id
    WHERE m.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
      AND COALESCE(cardinality(p_domain_context), 0) > 0
    UNION
    SELECT r.synset_id, m.subject_id AS member_id
    FROM scoped r
    JOIN laplace.consensus m ON m.object_id = r.synset_id
    WHERE m.type_id = ANY (consensus.relation_family_ids('HAS_SENSE'))
      AND COALESCE(cardinality(p_domain_context), 0) > 0
),
domain_scores AS (
    SELECT m.synset_id, count(*)::bigint AS domain_hits
    FROM members m
    JOIN domain d ON true
    JOIN LATERAL structural.geometry_neighbours(m.member_id, 200, 8) gn
      ON gn.neighbour_id = d.id
    GROUP BY m.synset_id
),
ranked AS (
    SELECT DISTINCT ON (r.term, r.synset_id)
           r.term,
           r.sense_id,
           r.synset_id,
           r.via_relation,
           r.base_eff_mu,
           COALESCE(ds.domain_hits, 0)::bigint AS domain_hits,
           r.witnesses,
           (r.base_eff_mu * (1::numeric + ln(1::numeric + COALESCE(ds.domain_hits, 0)))) AS score,
           consensus.eff_mu(r.rating, r.rd) AS rank_key
    FROM scoped r
    LEFT JOIN domain_scores ds ON ds.synset_id = r.synset_id
    ORDER BY r.term, r.synset_id, consensus.eff_mu(r.rating, r.rd) DESC
),
-- p_k DEFAULTS TO NULL, MEANING NO TRUNCATION.
--
-- Bounding a candidate set is legitimate -- spec 36 makes SCAN "discover bounded
-- candidates" a stage of the canonical program. What this default avoids is
-- narrower: a bound applied PER TERM, in isolation, before any joint election
-- across the prompt's terms. §7's election law puts the discriminating
-- information in the graph BETWEEN tokens, so a per-term prefix can remove the
-- candidate that the joint evidence would have selected, and no downstream
-- re-rank can recover it (spec 36: STEER reranks proposals, it does not
-- regenerate them). That is the same shape §9b records in prompt_coherence,
-- which collapses each token to one sense before the seat.
--
-- The scalar form's LIMIT 64 is not load-bearing: lexical.senses passes 64 and then
-- RE-SORTS the survivors on different keys, so the 64 only bounds rows. Measured
-- over 20 terms, one term carries 135 senses, so k=64 drops 71 of them, and with
-- no final tiebreak WHICH 71 is not reproducible -- 33 of 835 rows differed
-- between two equally valid cuts. Untruncated, the scalar and batch forms are
-- byte-identical over 1,012 rows.
--
-- The parameter stays so an explicit caller bound remains expressible; it is
-- simply never defaulted to a number. row_number carries the total order
-- (synset_id closes it) so a caller that does pass k gets a repeatable cut.
ordered AS (
    SELECT rk.*,
           row_number() OVER (PARTITION BY rk.term
                              ORDER BY rk.witnesses DESC, rk.score DESC,
                                       rk.rank_key DESC, rk.synset_id) AS rn
    FROM ranked rk
)
-- QUALIFIED, not bare: under BEGIN ATOMIC the RETURNS TABLE names are in scope,
-- so an unqualified `term` is ambiguous against the output parameter and the
-- function fails to create.
SELECT o.term, o.sense_id, o.synset_id, o.via_relation, o.score, o.base_eff_mu,
       o.domain_hits, o.witnesses
FROM ordered o
WHERE p_k IS NULL OR o.rn <= p_k
ORDER BY o.term, o.rn;
END;
-- Scalar adapter over the one set implementation. Selection, language scoping,
-- domain geometry, ranking, ordering, and explicit truncation all belong to
-- bubble_up_batch; duplicating that CTE cascade here made two definitions of one
-- operation and paid the scalar partition fanout again.
DROP FUNCTION IF EXISTS laplace.bubble_up(bytea, bytea[], integer);
CREATE OR REPLACE FUNCTION taxonomy.bubble_up(
    p_term bytea,
    p_domain_context bytea[] DEFAULT NULL,
    p_k integer DEFAULT NULL
)
RETURNS TABLE(
    sense_id bytea,
    synset_id bytea,
    via_relation text,
    score numeric,
    base_eff_mu numeric,
    domain_hits bigint,
    witnesses bigint
)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT b.sense_id, b.synset_id, b.via_relation, b.score, b.base_eff_mu,
           b.domain_hits, b.witnesses
    FROM taxonomy.bubble_up_batch(
        ARRAY[p_term], p_domain_context, p_k)
        WITH ORDINALITY AS b(
            term, sense_id, synset_id, via_relation, score, base_eff_mu,
            domain_hits, witnesses, ord)
    WHERE b.term = p_term
    ORDER BY b.ord;
END;
-- taxonomy.retrieve_grounded: case/variant fan-out → bubble_up frontier → definitions.
-- Formal R0/R2 tool ISA entry; abstains with 0 rows when ungrounded.
--
-- GH #862 / #860. No SET search_path -- it blocks plan caching and SQL inlining, so
-- the body was re-planned on every call. No @extschema@ either: the control file
-- pins schema = 'laplace' with relocatable = false, so the placeholder has exactly
-- one possible expansion. Real schema names throughout.
DROP FUNCTION IF EXISTS laplace.retrieve_grounded(text, bytea[], integer);
CREATE OR REPLACE FUNCTION taxonomy.retrieve_grounded(
    p_term text,
    p_domain_context bytea[] DEFAULT NULL,
    p_k integer DEFAULT 5
)
RETURNS TABLE(
    entity_id bytea,
    surface text,
    synset_id bytea,
    definition text,
    score numeric,
    witnesses bigint
)
LANGUAGE sql STABLE PARALLEL SAFE AS $$
WITH term AS (
    SELECT laplace.word_id(p_term) AS id
),
frontier AS (
    SELECT b.sense_id,
           b.synset_id,
           b.score,
           b.witnesses
    FROM term t
    CROSS JOIN LATERAL taxonomy.bubble_up(t.id, p_domain_context, p_k) b
    WHERE t.id IS NOT NULL
),
glossed AS MATERIALIZED (
    SELECT f.sense_id AS entity_id,
           f.synset_id,
           f.score,
           f.witnesses,
           (
               SELECT g.object_id
               FROM laplace.consensus g
               WHERE g.subject_id = f.synset_id
                 AND g.type_id = laplace.relation_type_id('HAS_DEFINITION')
               ORDER BY consensus.eff_mu(g.rating, g.rd) DESC
               LIMIT 1
           ) AS definition_id
    FROM frontier f
), numbered AS MATERIALIZED (
    SELECT g.*, row_number() OVER (ORDER BY score DESC NULLS LAST,entity_id) AS rn FROM glossed g
), batches AS MATERIALIZED (
    SELECT realize.render_text_batch(array_agg(entity_id ORDER BY rn)) AS surfaces,
           realize.render_text_batch(array_agg(definition_id ORDER BY rn)) AS definitions
    FROM numbered
)
SELECT entity_id,
       COALESCE(NULLIF(b.surfaces[g.rn], ''), p_term) AS surface,
       synset_id,
       b.definitions[g.rn],
       score,
       witnesses
FROM numbered g CROSS JOIN batches b
ORDER BY g.rn
$$;
-- taxonomy.top_synset — GH #862, first family migrated out of the flat namespace.
--
-- The schema says what this DOES (hierarchy traversal, spec 37 TRAVERSE) instead of
-- what project owns it. Cross-schema calls must qualify, so correctness is enforced
-- by structure rather than by a SET clause repeated in 186 files -- and the SET is
-- gone here, which is what lets the plan cache.
--
-- The old taxonomy.top_synset is dropped rather than left as a shim: two names for
-- one function is the dual-definition defect (GH #532), and a caller still on the
-- old name should fail loudly at install rather than silently diverge later.
DROP FUNCTION IF EXISTS laplace.top_synset(bytea);
CREATE OR REPLACE FUNCTION taxonomy.top_synset(p_word bytea)
    RETURNS bytea
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    -- p_k = 1 IS the cap, and bubble_up ranks before it cuts. The LIMIT 1 that used
    -- to sit here added nothing and read as a safeguard over an unordered pick,
    -- which is the opposite of what this call does.
    SELECT b.synset_id
    FROM taxonomy.bubble_up(p_word, NULL::bytea[], 1) b
$$;
-- taxonomy.synset_gloss — GH #862 / #860.
--
-- No SET search_path (it blocks plan caching and inlining), and no install-time schema placeholder:
-- the control file pins schema = 'laplace' with relocatable = false, so that
-- placeholder has exactly one possible expansion. Real schema names, written out.
DROP FUNCTION IF EXISTS laplace.synset_gloss(bytea);
CREATE OR REPLACE FUNCTION taxonomy.synset_gloss(p_synset bytea)
    RETURNS text
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    -- ONE BODY (§15). This was byte-identical to realize._defines apart from the
    -- parameter name -- same relation, same ordering, same LIMIT -- two definitions
    -- free to drift. realize._defines ranks in id space and renders the winner once.
    SELECT realize._defines(p_synset)
$$;
-- taxonomy.consensus_taxonomy_edges — GH #862. Real schema names, no install-time
-- schema placeholder (schema = 'laplace', relocatable = false: one possible expansion).
DROP FUNCTION IF EXISTS laplace.consensus_taxonomy_edges(bytea, bytea[]);
CREATE OR REPLACE FUNCTION taxonomy.consensus_taxonomy_edges(p_subject bytea, p_types bytea[])
    RETURNS TABLE(object_id bytea, type_id bytea, rating bigint, rd bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- No SET search_path so it inlines into the caller's FROM (the
    -- consensus_by_ids precedent). This is the edge truth table under the
    -- level-batched taxonomy walk: non-inlined, each LATERAL row paid a full
    -- function execution (~16k per hub matchup ≈ 10s); inlined, a whole
    -- frontier level plans as one join. Verified live 2026-07-24: the inlined
    -- shape returns emperor's 8,225-node closure instantly with an identical
    -- node set, and completes run's 11,924-node closure where the non-inlined
    -- form timed out.
    SELECT c.object_id, c.type_id, c.rating, c.rd
    FROM laplace.v_consensus_unrefuted c
    WHERE c.subject_id = p_subject
      AND c.type_id = ANY (p_types)
      AND c.object_id IS NOT NULL
      AND NOT EXISTS (
          SELECT 1 FROM laplace.entities et
          WHERE et.id = c.object_id
            AND et.type_id = laplace.entity_type_id('RelationType'))
$$;
-- taxonomy.translation_sources — GH #862 / #860.
--
-- No SET search_path (it blocks plan caching and inlining), and no placeholder:
-- the control file pins schema = 'laplace' with relocatable = false, so that
-- placeholder has exactly one possible expansion and the indirection buys nothing
-- but noise. Real schema names, written out.
DROP FUNCTION IF EXISTS laplace.translation_sources(bytea);
CREATE OR REPLACE FUNCTION taxonomy.translation_sources(p_object bytea)
    RETURNS TABLE(subject_id bytea)
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    SELECT c.subject_id
    FROM laplace.v_consensus_unrefuted c
    WHERE c.type_id = laplace.relation_type_id('IS_TRANSLATION_OF')
      AND c.object_id = p_object
$$;
-- No SET search_path and no STRICT so it inlines into callers (#617; the
-- consensus_by_ids precedent). NULL-safety without STRICT: subject_id = NULL
-- matches no rows.
DROP FUNCTION IF EXISTS laplace.consensus_subject_edges(bytea);
CREATE OR REPLACE FUNCTION converse.consensus_subject_edges(p_subject bytea)
    RETURNS TABLE(type_id bytea, object_id bytea, rating bigint, rd bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT c.type_id, c.object_id, c.rating, c.rd
    FROM laplace.v_consensus_unrefuted c
    WHERE c.subject_id = p_subject
      AND c.object_id IS NOT NULL
$$;
DROP FUNCTION IF EXISTS laplace.physicality_count(bytea);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION converse.physicality_count(p_entity bytea)
    RETURNS bigint
    LANGUAGE sql STABLE PARALLEL SAFE STRICT
BEGIN ATOMIC
    SELECT count(*)::bigint FROM laplace.physicalities pp WHERE pp.entity_id = p_entity;
END;
DROP FUNCTION IF EXISTS laplace.consensus_peer(bytea, int);
CREATE OR REPLACE FUNCTION generation.consensus_peer(p_id bytea, p_k int DEFAULT 6)
    RETURNS bytea
    LANGUAGE plpgsql STABLE PARALLEL RESTRICTED
 AS $$
DECLARE
    v_result bytea;
    v_type   bytea;
    v_coord  geometry;
    v_curve  geometry;
BEGIN
    -- Relational election: laplace.entities of p_id's own type that share p_id's
    -- (relation, partner) edges, scored by min-shared confidence. Reads through
    -- laplace.v_consensus_unrefuted(was two inline `NOT consensus.refuted` base-table scans). The
    -- winner is the top-p_k by score, then one picked by the deterministic
    -- hash tie-break -- identical to the old UNION's hash pick over `elected`.
    --
    -- p_id's own edge set is read BOTH ways as two direction-pinned arms unioned,
    -- never as `subject_id = p_id OR object_id = p_id` (GH #871, spec 37 OP5).
    -- That disjunction spans two different leading
    -- columns, so it is not an index qual on either consensus_subject_type_btree
    -- or consensus_object_type_btree: the planner's only options are a BitmapOr
    -- across both or a scan, which is the shape spec 37 blames for the 280s hang.
    -- Split, each arm is a plain equality the matching index serves directly.
    --
    -- The arms reproduce the CASE the OR needed: the outbound arm is the rows
    -- where p_id is the subject (partner = object_id, as_subject = true), the
    -- inbound arm the rows where it is the object. `subject_id IS DISTINCT FROM
    -- p_id` on the inbound arm keeps a self-loop (subject = object = p_id) a
    -- single row exactly as the CASE did, instead of one per arm. The inbound arm
    -- needs no `object_id IS NOT NULL` -- its own equality already proves it.
    -- The PEER join is split the same way, and for the same reason (GH #908/#871).
    -- It used to carry the direction as a boolean and re-disjoin on it:
    --   ((as_subject AND c2.object_id = partner AND ...)
    --     OR (NOT as_subject AND c2.subject_id = partner AND ...))
    -- which is the identical defect the p_id arms above avoid, one level down --
    -- the two branches lead with different columns, so neither index serves the
    -- qual and the planner is back to BitmapOr or a scan. Carrying the flag into a
    -- CASE for the laplace.entities join spread it further. Split, each arm is a plain
    -- equality on its own leading column and the flag disappears entirely.
    SELECT z.id INTO v_result
    FROM (
        SELECT x.id, sum(arms.contrib) AS score
        FROM (
            -- OUTBOUND: p_id -> partner. A peer is another SUBJECT asserting the
            -- same (relation, object).
            SELECT c2.subject_id AS peer,
                   LEAST(m.mu, consensus.eff_mu(c2.rating, c2.rd)) AS contrib
            FROM (
                SELECT c.type_id AS rel, c.object_id AS partner,
                       consensus.eff_mu(c.rating, c.rd) AS mu
                FROM laplace.v_consensus_unrefuted c
                WHERE c.subject_id = p_id
                  AND c.object_id IS NOT NULL
            ) m
            JOIN laplace.v_consensus_unrefuted c2
              ON c2.type_id = m.rel
             AND c2.object_id = m.partner
             AND c2.subject_id <> p_id
            UNION ALL
            -- INBOUND: partner -> p_id. A peer is another OBJECT the same subject
            -- asserts under that relation. `subject_id IS DISTINCT FROM p_id`
            -- keeps a self-loop one row, exactly as the CASE did.
            SELECT c2.object_id AS peer,
                   LEAST(m.mu, consensus.eff_mu(c2.rating, c2.rd))
            FROM (
                SELECT c.type_id AS rel, c.subject_id AS partner,
                       consensus.eff_mu(c.rating, c.rd) AS mu
                FROM laplace.v_consensus_unrefuted c
                WHERE c.object_id = p_id
                  AND c.subject_id IS DISTINCT FROM p_id
            ) m
            JOIN laplace.v_consensus_unrefuted c2
              ON c2.type_id = m.rel
             AND c2.subject_id = m.partner
             AND c2.object_id <> p_id
        ) arms
        JOIN laplace.entities x ON x.id = arms.peer
        JOIN laplace.entities self ON self.id = p_id AND x.type_id = self.type_id
        GROUP BY x.id
        ORDER BY score DESC
        LIMIT GREATEST(p_k, 0)
    ) z
    ORDER BY public.laplace_hash128_blake3(z.id || p_id)
    LIMIT 1;

    IF v_result IS NOT NULL THEN
        RETURN v_result;
    END IF;

    -- Geometric fallback -- only reached when the relational election is empty.
    -- As a single SQL statement this KNN was planned (and could run) on every
    -- call even when `elected` had rows, and its `me.coord` was a correlated
    -- FROM-subquery reference that could not drive the coord GiST index. Fetch
    -- the anchor into locals first so the ordering operand is a genuine bound
    -- parameter, and gate the whole branch behind the election miss.
    -- Shape rank uses REALIZED curves (entity_curve), never packed trajectory
    -- (Rule #3 / Issue 51). p_k is the declared admission/election budget for
    -- both paths. The old fixed 48-row KNN pool silently changed the meaning and
    -- work of the same call regardless of p_k.
    SELECT a.type_id, a.coord, structural.entity_curve(p_id)
      INTO v_type, v_coord, v_curve
    FROM structural.word_anchor(p_id) a;
    IF v_coord IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT z.id INTO v_result
    FROM (
        SELECT knn.id
        FROM (
            SELECT w.id, structural.entity_curve(w.id) AS curve
            FROM laplace.v_word_points w
            WHERE w.type_id = v_type AND w.id <> p_id AND w.trajectory IS NOT NULL
            ORDER BY w.coord <<->> v_coord
            LIMIT GREATEST(p_k, 0)
        ) knn
        WHERE knn.curve IS NOT NULL AND v_curve IS NOT NULL
        ORDER BY public.laplace_frechet_4d(knn.curve, v_curve) ASC
        LIMIT GREATEST(p_k, 0)
    ) z
    ORDER BY public.laplace_hash128_blake3(z.id || p_id)
    LIMIT 1;

    RETURN v_result;
END;
$$;
DROP FUNCTION IF EXISTS laplace.trajectory_unpacked_points(bytea);
CREATE OR REPLACE FUNCTION generation.trajectory_unpacked_points(p_entity bytea, p_type smallint)
    RETURNS TABLE(entity_id bytea, run_length int, ctier int)
    LANGUAGE sql STABLE PARALLEL SAFE
    -- MEASURED, not guessed. One call returns the points of ONE trajectory:
    -- mean 5.93, max 15 over 500 sampled type=1 trajectories, and 3.47 actual
    -- per loop in situ under auto_explain in compose_batch. Undeclared, Postgres
    -- assumes 1000 -- ~170x high -- and that estimate is what pushed this body's
    -- plan over parallel_setup_cost and gave every call its own Gather Merge.
    -- Only 6 set-returning functions in this surface declare a real ROWS; the
    -- rest ship the 1000 default and mis-plan their callers the same way.
    ROWS 6
 AS $$
    -- THE PHYSICALITIES LOOKUP IS FENCED IN A CTE, NOT JOINED INTO THE UNPACK.
    --
    -- physicalities is HASH (id) and this lookup is by entity_id -- an independent
    -- content hash, not derivable from entity_id -- so its 64-way Append cannot prune.
    -- Joined directly into the unpack, that Append multiplies against ST_DumpPoints'
    -- declared 1000 rows (procost 5000): the body planned at cost 983,329, over
    -- parallel_setup_cost, so EVERY call paid Gather Merge worker startup to return a
    -- measured 3.47 rows.
    --
    -- MATERIALIZED here is an optimisation fence, not a value carrier: the Append runs
    -- once and the 1000-row estimate multiplies against its result instead of against
    -- 64 partitions. (Reading a bound ARRAY back from a CTE column is the opposite
    -- case and is forbidden -- it makes a constant into a per-row variable and kills
    -- pruning. See realize.resolve_name.)
    --   joined            cost 983,329, Gather Merge, 37.7 ms/call
    --   fenced            cost   8,012, no Gather,     6.2 ms/call
    --
    -- ORDER BY u.ordinal is the contract: every caller applies WITH ORDINALITY and
    -- takes the position as the sequence. It is not decoration. The geometry
    -- binding expands RLE with the core prefix-sum kernel, so callers never use
    -- a stored geometry vertex as a logical constituent position.
    WITH traj AS MATERIALIZED (
        SELECT p.trajectory
        FROM laplace.physicalities p
        WHERE p.entity_id = p_entity AND p.type = p_type AND p.trajectory IS NOT NULL
    )
    -- ctier COMES OUT OF THE VERTEX, NOT OUT OF A LOOKUP.
    --
    -- The tier is bit-packed into each vertex's flags at pack time --
    -- laplace_vertex_flags(tier, has_atom, atom), decoded by realize.vertex_tier,
    -- and laplace_mantissa_unpack already returns those flags. The
    -- previous body discarded them and recomputed the value with a correlated
    -- `SELECT min(e.tier) FROM laplace.entities` PER POINT, plus a
    -- realize.codepoint_for_id fallback.
    --
    -- Output-identical, verified over 3,005 constituent points of tier-3 containers:
    -- the stored tier and the entities floor agree on every one (0<->0, 2<->2).
    --
    -- IT IS A FLOOR, AND IT CANNOT BE ANYTHING ELSE. Level is a property of the
    -- (container, position) pair, not of the entity: the DAG is content-addressed and
    -- recursive, so the same content recurs at many levels and dedupes trunk-down.
    -- Ingest the verses, then the whole bible, and the verses resolve to the ids
    -- already recorded -- now sitting one level deeper. entities.tier is one scalar per
    -- entity, so it can only ever be the minimum over every container that content
    -- has ever appeared in.
    --
    -- Measured consequence: the word 'a' occurs 152 times inside sentence
    -- trajectories carrying tier 0, because laplace.word_id('a') IS the codepoint entity --
    -- same content, same hash, one entity. No tier test and no type test separates
    -- "a used as a word" from "a the codepoint". Only the CONTAINER's tier says which
    -- level a constituent sits at, so callers must not filter on ctier to mean
    -- "is a word" (see converse_compose).
    SELECT u.entity_id,
           1::int AS run_length,
           realize.vertex_tier(u.flags)::int AS ctier
    FROM traj,
    LATERAL public.laplace_trajectory_expanded_constituents(traj.trajectory) u
    ORDER BY u.ordinal
$$;

-- Content-lane default. BEGIN ATOMIC, not a string body: the delegation is parsed at
-- CREATE time and recorded in pg_depend, so the two-argument core cannot be dropped or
-- have its signature changed out from under this wrapper (GH #764). Columns are
-- qualified through the alias because RETURNS TABLE names are parameters in scope here.
CREATE OR REPLACE FUNCTION generation.trajectory_unpacked_points(p_entity bytea)
    RETURNS TABLE(entity_id bytea, run_length int, ctier int)
    LANGUAGE sql STABLE PARALLEL SAFE ROWS 6
BEGIN ATOMIC
    SELECT t.entity_id, t.run_length, t.ctier
    FROM generation.trajectory_unpacked_points(p_entity, 1::smallint) AS t;
END;
-- Compile and execute the composition-backed WHAT_IS program.  This is a
-- high-level surface over the explicit recall_intent ISA, not a replacement for
-- it: callers that already possess an opcode and operands keep calling the
-- explicit surface; natural operator utterances pass through this compiler.
--
-- The WHAT_IS transformation changes interrogative order into a declarative
-- sequence: request + binder + operand ("who is Captain Ahab") becomes
-- operand + binder (Captain,Ahab,is).  SCAN first reduces the physicality set by
-- GIN containment.  Only those survivors are unpacked to verify ordered
-- adjacency and a witnessed continuation.  A question carrying the request cue
-- is excluded from the answer set.  No row cap or manufactured score is used;
-- shortest attested closure is merely the deterministic output ordering.
CREATE OR REPLACE FUNCTION converse.execute_prompt(
        p_prompt text,
        p_primary_language bytea DEFAULT NULL)
    RETURNS TABLE(
        rank bigint,
        reply text,
        operation_id bytea,
        shape text,
        container_id bytea,
        route_mu numeric,
        primary_language bytea,
        prompt_language bytea,
        effective_language bytea,
        widened boolean)
    LANGUAGE sql STABLE
BEGIN ATOMIC
WITH program AS MATERIALIZED (
    SELECT * FROM converse.compile_prompt(p_prompt, p_primary_language)
    WHERE shape = 'what_is'
),
needle AS MATERIALIZED (
    SELECT p.*, p.operand_ids || p.binder_ids AS ids
    FROM program p
    WHERE cardinality(p.operand_ids) > 0 AND cardinality(p.binder_ids) > 0
),
containers AS MATERIALIZED (
    SELECT c.entity_id
    FROM needle n
    CROSS JOIN LATERAL structural.containers_containing_all(n.ids) c
),
separators AS MATERIALIZED (
    SELECT generation.separator_ids() AS ids
),
sequences AS MATERIALIZED (
    SELECT c.entity_id,
           array_agg(u.entity_id ORDER BY u.ord)
             FILTER (WHERE NOT u.entity_id = ANY (s.ids)) AS ids
    FROM containers c
    CROSS JOIN LATERAL generation.trajectory_unpacked_points(c.entity_id)
         WITH ORDINALITY AS u(entity_id, run_length, ctier, ord)
    CROSS JOIN separators s
    GROUP BY c.entity_id
),
matched AS MATERIALIZED (
    SELECT DISTINCT q.entity_id, cardinality(q.ids) - cardinality(n.ids) AS extra
    FROM sequences q
    CROSS JOIN needle n
    WHERE q.ids[1 : cardinality(n.ids)] = n.ids
      -- WHAT_IS asks for a predication whose subject is the operand.  A mere
      -- mid-sentence mention ("know if a dog is happy") is usage evidence, not
      -- a definition.  Keep this as a structural position test; do not replace
      -- it with a rendered-text prefix or a language-specific pattern.
      -- The declarative prefix must have an observed continuation.  This removes
      -- truncated fragments such as the five-point "Captain Ahab is" rows.
      AND cardinality(n.ids) < cardinality(q.ids)
      -- Do not answer by replaying the interrogative itself.
      AND NOT q.ids && n.request_ids
),
ordered AS MATERIALIZED (
    SELECT row_number() OVER (ORDER BY m.extra, m.entity_id) AS rank,
           m.entity_id
    FROM matched m
),
rendered AS MATERIALIZED (
    SELECT realize.render_text_batch(
               ARRAY(SELECT o.entity_id FROM ordered o ORDER BY o.rank)) AS labels
),
answers AS (
    SELECT o.rank, r.labels[o.rank] AS reply, o.entity_id
    FROM ordered o CROSS JOIN rendered r
)
SELECT a.rank,
       a.reply,
       n.operation_id,
       n.shape,
       a.entity_id,
       n.route_mu,
       n.primary_language,
       n.prompt_language,
       n.effective_language,
       n.widened
FROM answers a
CROSS JOIN needle n
WHERE a.reply IS NOT NULL AND a.reply <> ''
ORDER BY a.rank;
END;
DROP FUNCTION IF EXISTS laplace.entity_tier_of(bytea);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION generation.entity_tier_of(p_entity bytea)
    RETURNS int
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    -- Fall back to the perfcache-backed codepoint lookup before giving up: a valid
    -- tier-0 codepoint is tier 0 whether or not it has been given its own laplace.entities
    -- row yet. Only genuinely unresolvable ids (neither a real row nor a valid
    -- codepoint) should surface as NULL here.
    SELECT COALESCE(
        (SELECT tier FROM laplace.entities WHERE id = p_entity),
        CASE WHEN realize.codepoint_for_id(p_entity) IS NOT NULL THEN 0 END
    );
END;
DROP FUNCTION IF EXISTS laplace.entity_has_trajectory(bytea);
CREATE OR REPLACE FUNCTION generation.entity_has_trajectory(p_entity bytea)
    RETURNS boolean
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    SELECT EXISTS (
        SELECT 1 FROM laplace.v_word_points w
        WHERE w.id = p_entity AND w.trajectory IS NOT NULL
    )
$$;
DROP FUNCTION IF EXISTS laplace.respell_variant_seed(text, text);
CREATE OR REPLACE FUNCTION generation.respell_variant_seed(p_modality text, p_node_type text)
    RETURNS bytea
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT e.id
    FROM laplace.canonical_names n
    JOIN laplace.entities e ON e.type_id = n.id
    JOIN laplace.v_word_points w ON w.id = e.id AND w.trajectory IS NOT NULL
    WHERE n.name = 'substrate/type/grammar/' || p_modality || '/' || p_node_type || '/v1'
    ORDER BY public.laplace_hash128_blake3(e.id || convert_to(p_modality || '/' || p_node_type, 'UTF8'))
    LIMIT 1
$$;
-- COMPLETES_TO successors as a sampling floor for the dry generator. Thin
-- wrapper over consensus.edges_raw() — the one consensus scan — with this lane's axes
-- pinned: outbound, one relation type, unrefuted, consensus.eff_mu order. The weight
-- projection is this caller's own need and stays here.
--
-- The hand-rolled scan this replaced was edges_raw's 'out' arm verbatim
-- (subject equality, type equality, object_id IS NOT NULL, NOT consensus.refuted,
-- consensus.eff_mu DESC, LIMIT) — one axis set out of the six the core already takes as
-- arguments. Ordering is unchanged except that edges_raw breaks consensus.eff_mu ties on
-- neighbour_id, so the cap is now deterministic instead of plan-dependent.
--
-- No SET search_path: it blocks inlining, which is what makes the wrapper free
-- (#617, #860). Every reference is schema-qualified instead.
DROP FUNCTION IF EXISTS laplace.walk_completes_floor(bytea, int);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION generation.walk_completes_floor(p_subject bytea, p_limit int)
    RETURNS TABLE(object_id bytea, weight bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT e.neighbour_id,
           GREATEST(consensus.eff_mu(e.rating, e.rd) / 1000000000, 1)::int8 AS weight
    FROM consensus.edges_raw(p_subject, 'out',
                               ARRAY[laplace.relation_type_id('COMPLETES_TO')],
                               p_limit, false, 'eff_mu') e;
END;
DROP FUNCTION IF EXISTS laplace.session_last_resolved(bytea);
-- BEGIN ATOMIC: GH #764.
CREATE OR REPLACE FUNCTION generation.session_last_resolved(p_session bytea)
    RETURNS bytea
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
BEGIN ATOMIC
    SELECT t.resolved_id
    FROM converse.session_topics t
    WHERE t.session_id = p_session AND t.resolved_id IS NOT NULL
    ORDER BY t.ord DESC
    LIMIT 1;
END;
DROP FUNCTION IF EXISTS laplace.session_record_prompt(bytea, text, bytea);
CREATE OR REPLACE FUNCTION generation.session_record_prompt(
        p_session bytea, p_prompt text, p_resolved bytea DEFAULT NULL)
    RETURNS void
    LANGUAGE plpgsql VOLATILE
 AS $$
BEGIN
    -- GH #911 item 2. `COALESCE((SELECT max(ord) ...), 0) + 1` was an unlocked
    -- read-modify-write: two concurrent turns on one session read the same max and
    -- both claim the same ord -- duplicate ordinals, or a unique violation
    -- depending on the key. Latent while one frontend owns a session, live the day
    -- two share it.
    --
    -- Serialized on the SESSION, not the table, and not with row locks. Row locks
    -- cannot fix this case: the race that matters is two FIRST turns, where there
    -- are no rows to lock and `FOR UPDATE` protects nothing (it is also illegal
    -- beside an aggregate). A transaction-scoped advisory lock keyed on the
    -- session id covers the empty case and every later one, and releases at commit
    -- or abort without an unlock path to leak.
    --
    -- The key is the leading 64 bits of the session id. The id is a BLAKE3 content
    -- hash, so its high bits are already uniformly distributed -- no hashtext
    -- round trip, and a collision costs two unrelated sessions a brief wait, never
    -- a wrong ord.
    PERFORM pg_advisory_xact_lock(laplace.hash128_lo(p_session));

    INSERT INTO converse.session_topics (session_id, ord, prompt, resolved_id)
    VALUES (
        p_session,
        COALESCE((SELECT max(t.ord) FROM converse.session_topics t WHERE t.session_id = p_session), 0) + 1,
        p_prompt,
        p_resolved
    );
END;
$$;
DROP FUNCTION IF EXISTS laplace.recall_context_exclude(text, bytea);
CREATE OR REPLACE FUNCTION converse.recall_context_exclude(p_prompt text, p_topic bytea)
    RETURNS bytea[]
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT COALESCE(array_agg(ps.id), ARRAY[]::bytea[])
    FROM converse.prompt_state(p_prompt) ps
    WHERE ps.id <> p_topic
$$;
-- Witnessed glosses for a topic, sense-disambiguated by the other content ids
-- the caller resolved. Takes ids, not prompt text: what disambiguates a sense is
-- the company it keeps in the substrate, not the sentence it arrived in.
DROP FUNCTION IF EXISTS laplace.recall_define_response(bytea, bytea[]);
CREATE OR REPLACE FUNCTION converse.recall_define_response(p_topic bytea, p_context_ids bytea[] DEFAULT NULL)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT d.definition, d.eff_mu, d.witnesses
    FROM converse.define_fast(p_topic, COALESCE(p_context_ids, ARRAY[]::bytea[])) d
$$;
-- Gloss plus the IS_A ladder upward. Context ids disambiguate the sense.
DROP FUNCTION IF EXISTS laplace.recall_what_is_response(bytea, bytea[]);
CREATE OR REPLACE FUNCTION converse.recall_what_is_response(p_topic bytea, p_context_ids bytea[] DEFAULT NULL)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    WITH topic AS MATERIALIZED (SELECT realize.label(p_topic) AS label)
    SELECT t.label || ': ' || d.definition, d.eff_mu, d.witnesses
    FROM converse.define_fast(p_topic, COALESCE(p_context_ids, ARRAY[]::bytea[]), 3) d
    CROSS JOIN topic t
    UNION ALL
    SELECT repeat('  ', h.depth) || E'→ is ' || COALESCE(h.hypernym, '?')
           || COALESCE(': ' || h.gloss, ''), NULL::numeric, NULL::bigint
    FROM converse.hypernyms(p_topic, 6) h
    WHERE h.depth > 0
$$;
DROP FUNCTION IF EXISTS laplace.recall_translate_response(bytea, text);
CREATE OR REPLACE FUNCTION converse.recall_translate_response(p_topic bytea, p_lang text DEFAULT NULL)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT t.translation || ' [' || COALESCE(t.language, '?') || ']', t.eff_mu, t.witnesses
    FROM converse.translate_to(p_topic, p_lang) t
$$;
DROP FUNCTION IF EXISTS laplace.recall_languages_response(bytea);
CREATE OR REPLACE FUNCTION converse.recall_languages_response(p_topic bytea)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT lc.reply, lc.eff_mu, lc.witnesses
    FROM converse.language_coverage(p_topic) lc
$$;
DROP FUNCTION IF EXISTS laplace.recall_synonyms_response(bytea);
CREATE OR REPLACE FUNCTION converse.recall_synonyms_response(p_topic bytea)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT s.synonym, s.eff_mu, s.witnesses FROM converse.synonyms(p_topic) s
$$;
DROP FUNCTION IF EXISTS laplace.recall_examples_response(bytea);
CREATE OR REPLACE FUNCTION converse.recall_examples_response(p_topic bytea)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH topic AS MATERIALIZED (SELECT realize.label(p_topic) AS label)
    SELECT replace(e.example, '%s', t.label), e.eff_mu, e.witnesses
    FROM lexical.examples(p_topic) e CROSS JOIN topic t
$$;
DROP FUNCTION IF EXISTS laplace.recall_describe_response(bytea);
CREATE OR REPLACE FUNCTION converse.recall_describe_response(p_topic bytea)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT d.type || ': ' || COALESCE(d.fact, '?'), d.eff_mu, d.witnesses
    FROM consensus.salient_facts(p_topic, converse.word_language(p_topic)) d
$$;
-- Commonsense-interaction realizer: given an event/concept, surface what the substrate
-- knows it ELICITS — intents, wants, reactions, effects, causes — from the ATOMIC-2020
-- and ConceptNet commonsense relations folded into consensus. This is the "what does
-- this situation lead to" query, the reasoning primitive under grounded conversation:
-- one pull on an event knot returns the taut strands (Glicko-ranked) that answer
-- "and then what / and so others feel". Each relation type maps to a natural connective
-- so the folded edge reads as an inference, not a table row.
DROP FUNCTION IF EXISTS laplace.recall_interaction_response(bytea, int);
CREATE OR REPLACE FUNCTION converse.recall_interaction_response(p_topic bytea, p_limit int DEFAULT 8)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    WITH kinds(type_id, phrase) AS (
        VALUES
            (laplace.relation_type_id('X_INTENT'),         'intends'),
            (laplace.relation_type_id('X_WANT'),           'then wants'),
            (laplace.relation_type_id('X_NEED'),           'first needs'),
            (laplace.relation_type_id('X_REACT'),          'feels'),
            (laplace.relation_type_id('X_EFFECT'),         'then'),
            (laplace.relation_type_id('O_WANT'),           'others then want'),
            (laplace.relation_type_id('O_REACT'),          'others feel'),
            (laplace.relation_type_id('O_EFFECT'),         'for others,'),
            (laplace.relation_type_id('CAUSES'),           'causes'),
            (laplace.relation_type_id('CAUSES_DESIRE'),    'causes a desire for'),
            (laplace.relation_type_id('MOTIVATED_BY_GOAL'),'is motivated by'),
            (laplace.relation_type_id('HAS_PREREQUISITE'), 'requires'),
            (laplace.relation_type_id('HAS_SUBEVENT'),     'involves'),
            (laplace.relation_type_id('OBSTRUCTED_BY'),    'is hindered by')
    ),
    -- consensus.edge_rank folds relation salience into the consensus.eff_mu ordering so mandate-band
    -- relations outrank probationary ones.
    facts AS (
        SELECT k.phrase,
               c.object_id,
               consensus.edge_rank(c.type_id, consensus.eff_mu(c.rating, c.rd)) AS rank,
               consensus.eff_mu(c.rating, c.rd) AS mu,
               c.witness_count AS witnesses
        FROM laplace.v_consensus_unrefuted c
        JOIN kinds k ON k.type_id = c.type_id
        WHERE c.subject_id = p_topic AND c.object_id IS NOT NULL
    ),
    -- Rank BEFORE rendering (Issue-52 pattern): the old shape ran realize.render_text over
    -- the topic's FULL commonsense fan-out and only then ORDER/LIMIT'd to p_limit.
    -- Ranking needs only ids + rank/mu already in `facts`; realize.render_text runs over
    -- exactly the p_limit survivors. Output-identical (no post-realize.render filtering).
    ranked AS MATERIALIZED (
        SELECT f.phrase, f.object_id, f.rank, f.mu, f.witnesses
        FROM facts f
        ORDER BY f.rank DESC, f.mu DESC
        LIMIT p_limit
    ), numbered AS MATERIALIZED (
        SELECT r.*, row_number() OVER (ORDER BY r.rank DESC,r.mu DESC,r.object_id) AS rn FROM ranked r
    ), batch AS MATERIALIZED (
        SELECT realize.label(p_topic) AS topic,
               realize.render_text_batch(array_agg(object_id ORDER BY rn)) AS objects
        FROM numbered
    )
    SELECT b.topic || ' — ' || r.phrase || ' ' || b.objects[r.rn] AS reply,
           r.mu AS eff_mu,
           r.witnesses
    FROM numbered r CROSS JOIN batch b
    ORDER BY r.rn
$$;
DROP FUNCTION IF EXISTS laplace.recall_related_response(bytea, text);
CREATE OR REPLACE FUNCTION converse.recall_related_response(p_topic bytea, p_type_name text)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    -- A witnessed relation does not disappear because either endpoint lacks an
    -- eligible surface realization. Preserve the semantic row and render an
    -- explicit abstention marker; never turn NULL realization into a blank reply
    -- and never substitute the internal content hash as prose.
    WITH topic AS MATERIALIZED (SELECT converse.label_or_hex(p_topic) AS label)
    SELECT replace(COALESCE(NULLIF(f.fact, ''), 'unrealized entity'), '%s', t.label),
           f.eff_mu, f.witnesses
    FROM consensus.related(p_topic, laplace.relation_type_id(p_type_name), converse.word_language(p_topic)) f
    CROSS JOIN topic t
$$;
DROP FUNCTION IF EXISTS laplace.recall_related_in_response(bytea, text);
CREATE OR REPLACE FUNCTION converse.recall_related_in_response(p_topic bytea, p_type_name text)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT f.fact, f.eff_mu, f.witnesses
    FROM consensus.related_in(p_topic, laplace.relation_type_id(p_type_name), converse.word_language(p_topic)) f
$$;
DROP FUNCTION IF EXISTS laplace.recall_relation_summary_response(bytea, bytea);
CREATE OR REPLACE FUNCTION converse.recall_relation_summary_response(p_topic bytea, p_topic2 bytea)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT CASE WHEN rs.relation IS NOT NULL
                THEN rs.relation || '  [' || rs.verdict || ']'
                ELSE rs.verdict END,
           rs.mu, rs.usage
    FROM consensus.relation_summary(p_topic, p_topic2) rs
$$;
-- THE walk responder. recall_walk_response's walk_reply branch used to carry a
-- byte-for-byte second copy of this body (GH #906 item 1) -- same walk_strongest
-- call, same arrow realize.render, same min(consensus.eff_mu) -- differing only in depth and in how
-- the arrow character was spelled (E'→' against a literal). Two maintained
-- copies of one realize.render; the depth is now the parameter that separated them.
--
-- The realize.render itself goes through realize.path(GH #906 item 2) instead of a third
-- hand-rolled arrow join. walk_strongest walks forward, so every direction is 1.
DROP FUNCTION IF EXISTS laplace.recall_fallback_walk(bytea, int);
CREATE OR REPLACE FUNCTION converse.recall_fallback_walk(p_topic bytea, p_depth int DEFAULT 6)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT realize.path(
               p_topic || array_agg(g.entity_id ORDER BY g.step),
               array_agg(g.type_id ORDER BY g.step),
               array_fill(1, ARRAY[count(*)::int]),
               converse.word_language(p_topic)),
           min(g.eff_mu),
           NULL::bigint
    FROM consensus.walk_strongest(p_topic, NULL::bytea, p_depth) g
    HAVING count(*) > 0
$$;
-- doc 15 Phase 3C / doc 22 Phase E: 'complete' mode (has a type filter,
-- COMPLETES_TO) routes through walk_branches -- the enriched native beam
-- engine (Glicko-complete edge weight, highway-mask gating capability,
-- S3/hilbert/trajectory-ordinal geometry terms). Plain 'walk' mode (NO
-- type filter) stays on walk_strongest, unchanged from before this pass.
--
-- Why the split: consensus is LIST-partitioned by relation type (hot
-- relations further HASH x8). walk_branches' per-level batch query has no
-- type predicate to prune on when p_type is NULL, so an unrestricted call
-- forces an Append scan across every relation-type partition (~200+ leaves)
-- -- measured live via EXPLAIN ANALYZE, and caught in regress turning a
-- sub-second converse.sql assertion into 24s. 'complete' mode's COMPLETES_TO
-- filter keeps walk_branches on the fast, partition-pruned path; plain
-- 'walk' has no filter to give it, so it stays on consensus.walk_strongest(proven
-- fast for the genuinely-unrestricted case via the original baseline) until
-- a bounded default relation set or a type-agnostic index makes the
-- unfiltered case safe for the beam engine too.
--
-- 'complete' mode's winner selection is path_mu/depth (average per-hop
-- confidence), NOT raw depth or raw cumulative path_mu -- also caught live:
-- ORDER BY depth DESC alone picks whichever branch happened to reach
-- deepest, which beam search can do via a structurally-well-attested but
-- narratively-irrelevant detour (e.g. cross-reference/sense-link chains
-- with real witness weight but no gloss), producing a technically
-- high-scoring but unreadable raw-hex-id reply. Averaging normalizes for
-- path length, so a short high-confidence chain beats a long chain diluted
-- by merely-adequate hops.
DROP FUNCTION IF EXISTS laplace.recall_walk_response(bytea, text);
CREATE OR REPLACE FUNCTION converse.recall_walk_response(p_topic bytea, p_mode text)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    WITH complete_branches AS (
        SELECT * FROM consensus.walk_branches(p_topic, laplace.relation_type_id('COMPLETES_TO'), 8, 5)
        WHERE p_mode = 'complete'
    ),
    complete_winner AS (
        SELECT * FROM complete_branches
        ORDER BY (path_mu / GREATEST(depth, 1)::numeric) DESC, depth DESC
        LIMIT 1
    ),
    complete_steps AS (
        SELECT i, w.path[i + 1] AS entity_id, w.types[i] AS type_id
        FROM complete_winner w, generate_series(1, w.depth) AS i
    ),
    complete_ids AS MATERIALIZED (
        SELECT ARRAY[p_topic] || COALESCE(array_agg(entity_id ORDER BY i),'{}'::bytea[]) AS entities,
               COALESCE(array_agg(type_id ORDER BY i),'{}'::bytea[]) AS types
        FROM complete_steps
    ), complete_labels AS MATERIALIZED (
        SELECT realize.batch(entities, converse.word_language(p_topic)) AS realized,
               realize.label_batch(entities) AS fallback,
               lexical.type_label_batch(types) AS types
        FROM complete_ids
    ),
    complete_reply AS (
        SELECT COALESCE(l.realized[1],l.fallback[1])
               || string_agg(' —' || COALESCE(l.types[s.i], '?') || E'→ '
                             || COALESCE(l.realized[s.i+1],l.fallback[s.i+1]), '' ORDER BY s.i) AS reply,
               min(b.eff_mu) AS eff_mu,
               (SELECT w.witnesses FROM complete_winner w) AS witnesses
        FROM complete_steps s CROSS JOIN complete_labels l
        JOIN complete_branches b ON b.entity_id = s.entity_id AND b.depth = s.i
        GROUP BY l.realized, l.fallback, l.types
        HAVING count(*) > 0
    ),
    -- ONE responder, called at this branch's depth. This block used to be a
    -- byte-for-byte copy of recall_fallback_walk differing only in depth and in
    -- how '→' was spelled (GH #906 item 1). The gate stays a short-circuit: the
    -- LATERAL is not evaluated at all when the mode is 'complete'.
    walk_reply AS (
        SELECT r.reply, r.eff_mu, r.witnesses
        FROM (SELECT 1 WHERE p_mode <> 'complete') gate
        CROSS JOIN LATERAL converse.recall_fallback_walk(p_topic, 8) r
    )
    SELECT * FROM complete_reply
    UNION ALL
    SELECT * FROM walk_reply
$$;
-- Native replacement for the lexical.define()/lexical.senses()/lexical.lexical_peers() SQL composition
-- chain (see recall.c:define_fast_impl for the full rationale) -- that chain
-- measured at 48+ seconds / 2.27M shared-buffer hits for a single word because
-- every function in it uses a CTE, which blocks PostgreSQL's SQL-function
-- inlining for set-returning functions, turning nested calls into opaque
-- black boxes with zero cross-function optimization. This does the same job
-- as a small, fixed number of explicitly sequenced native SPI calls instead.
DROP FUNCTION IF EXISTS laplace.define_fast(bytea, bytea[], int);
CREATE OR REPLACE FUNCTION converse.define_fast(p_word bytea, p_context bytea[] DEFAULT NULL, p_limit int DEFAULT 5)
    RETURNS TABLE(definition text, eff_mu numeric, witnesses bigint)
    AS 'laplace_substrate', 'pg_laplace_define_fast'
    LANGUAGE C STABLE;
-- Labelled gloss, the default answer when the caller named no read shape.
-- Restored SET-free after an empty-file SET-strip accident left the live
-- function stranded with proconfig (GH #860 residual / schema-repair).
DROP FUNCTION IF EXISTS laplace.recall_fallback_gloss(bytea, bytea[]);
CREATE OR REPLACE FUNCTION converse.recall_fallback_gloss(
        p_topic bytea, p_context_ids bytea[] DEFAULT NULL)
    RETURNS TABLE(reply text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql
    STABLE
    PARALLEL SAFE
AS $$
    -- Identity existing without an eligible human realization is UNKNOWN
    -- presentation state, not an empty answer and not permission to print the
    -- content hash. label_or_hex is the compatibility-named shared display
    -- projection; it now returns the explicit abstention marker, never hex.
    WITH topic AS MATERIALIZED (SELECT converse.label_or_hex(p_topic) AS label)
    SELECT t.label || ': ' || d.definition, d.eff_mu, d.witnesses
    FROM converse.define_fast(p_topic, COALESCE(p_context_ids, ARRAY[]::bytea[]), 3) d
    CROSS JOIN topic t
$$;
DROP FUNCTION IF EXISTS laplace.recall_is_a_yes_reply(bytea[], bytea[], bytea);
CREATE OR REPLACE FUNCTION converse.recall_is_a_yes_reply(
        p_path bytea[], p_types bytea[], p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT 'Yes — ' || realize.path(p_path, p_types, p_lang)
$$;
DROP FUNCTION IF EXISTS laplace.recall_is_a_no_reply(bytea, bytea, bytea);
CREATE OR REPLACE FUNCTION converse.recall_is_a_no_reply(p_from bytea, p_to bytea, p_lang bytea DEFAULT NULL)
    RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT 'No witnessed IS_A path from "'
           || COALESCE(realize.realize(p_from, p_lang), realize.label(p_from))
           || '" to "'
           || COALESCE(realize.realize(p_to, p_lang), realize.label(p_to)) || '".'
$$;
-- Staleness signature for the generation corpus (called on EVERY walk/continuation
-- request via corpus_ensure): must be O(1), never a corpus scan.
--
-- rows   = number of trajectory rows AT the maximum observed_at (top-key range scan)
-- max_us = maximum observed_at in microseconds (backward index-only scan)
--
-- Both legs are served by physicalities_traj_probe (partial btree on observed_at
-- WHERE type = 1 AND trajectory IS NOT NULL). The pair changes whenever rows are
-- appended at-or-after the current max — the append-only substrate's normal write
-- path, including same-timestamp batch inserts (the pg_regress generation_corpus
-- case). Rows backdated strictly BELOW the current max are the one blind spot;
-- stream_reset() is the manual override for that pathological case.
--
-- The previous body computed count(*) over ALL trajectory rows (parallel scan of
-- ~3.4M index entries, plan cost ~26k) on every call; this body plans at cost <5.
-- Total corpus size for display lives in stream_stats(), not here.
DROP FUNCTION IF EXISTS laplace.corpus_trajectory_probe();
CREATE OR REPLACE FUNCTION generation.corpus_trajectory_probe()
    RETURNS TABLE(rows bigint, max_us bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    WITH m AS (
        SELECT max(observed_at) AS max_at
        FROM laplace.physicalities
        WHERE type = 1 AND trajectory IS NOT NULL
    )
    SELECT COALESCE((SELECT count(*)
                     FROM laplace.physicalities p
                     WHERE p.type = 1 AND p.trajectory IS NOT NULL
                       AND p.observed_at = (SELECT max_at FROM m)), 0)::int8,
           COALESCE((SELECT (extract(epoch FROM max_at) * 1000000)::int8 FROM m), 0)
$$;
-- generation.corpus_whitespace_vocab_indices(vocab) -> the positions that are separators.
--
-- Answered from what the substrate ATTESTS, not by rendering each id to text and
-- inspecting the string. The Unicode seed already deposits
-- HAS_GENERAL_CATEGORY on every codepoint, so "is this a separator" is an indexed
-- consensus read on the id itself: category Zs / Zl / Zp is the separator class,
-- Cc covers the control characters (tab, newline) that word-break treats the same
-- way.
--
-- The old body ran render_text_fast + is_all_whitespace per id. is_all_whitespace
-- takes TEXT, so every caller had to realize an entity before it could ask -- and
-- that realization was the entire cost, not the test. MEASURED on 1,645 distinct
-- tokens from 400 'water' containers:
--
--   realize.render_text per row + '^\s*$'          29,899 ms
--   this function, previous body           35,232 ms
--   the category join below                    33.7 ms
--
-- 887x, and correct in scripts the regex never described: U+3000 IDEOGRAPHIC
-- SPACE, U+00A0, U+202F and every future separator carry their category from the
-- UCD rather than from a list maintained here. The four hardcoded codepoints in
-- laplace_codepoint_is_whitespace (0009/00A0/2007/202F) are exactly the symptom of
-- a classifier that could not see the attestation.
--
-- is_all_whitespace itself stays: content_witness_batch.c classifies raw span
-- BYTES during ingest, where the text is already in hand and no entity exists yet
-- to carry an attestation. That is the one caller for which text is the right
-- input.
--
-- UNATTESTED IS NOT "NOT A SEPARATOR". The COALESCE is load-bearing. An id with no
-- HAS_GENERAL_CATEGORY attestation is unattested, and answering false there is a
-- silently wrong result on an unseeded substrate. The generation_corpus regress
-- fixture is exactly that: synthetic content, zero Unicode layer, so the
-- attestation-only body classified nothing and the test read 10 word-stride
-- positions where it wanted 6 -- it broke main on merge. bool_or over zero rows is
-- NULL, which is precisely the distinction between "attested as not a separator"
-- and "never attested", so the text test runs ONLY for ids the substrate cannot
-- answer for. Seeded, that is no ids and the fallback costs nothing; unseeded, it
-- is exactly the pre-existing behaviour.
-- ONE SET-BASED PASS, NOT A LATERAL PER CANDIDATE.
--
-- The previous body ran the category probe as a LEFT JOIN LATERAL correlated on
-- v.id, so the whole subquery executed once PER VOCAB ENTRY. Worse, both partition
-- keys arrived column-valued: `a.subject_id = v.id` is a column reference, and
-- `a.type_id = laplace.relation_type_id(...)` is a STABLE call the planner will not fold to
-- a literal. laplace.attestations is LIST(type_id) -> HASH(subject_id), and neither level
-- can prune against a value that is not bound at plan time -- which is exactly
-- FAILED FORM (2) recorded in probes/attestations_present_ordinals.sql.in, where
-- the same shape Append-scanned every leaf.
--
-- MEASURED 2026-08-07 on the foundation seed: structural.geometry_successors('king') took
-- 8,148 ms, of which its containment+unpack query is 40 ms. The remaining ~8.1 s
-- was this function, called once with the batch of 26,047 unpacked candidates. The
-- foundry vocab crawl calls geometry_successors ~50 times (once per seed, then once
-- per surviving order-1 row), so a 10-seed crawl spent over ten minutes here and
-- never reached tensor synthesis at all.
--
-- The fix is the idiom the sibling probes already prove:
--   * bind the type_id ONCE into a plpgsql variable, so the LIST parent prunes at
--     plan time to the single HAS_GENERAL_CATEGORY partition;
--   * probe with `subject_id = ANY(p_vocab)`, which becomes the index condition
--     itself and prunes the HASH sublevel per element -- one descent per id;
--   * GROUP BY subject_id once, then LEFT JOIN the result back to the ordinals.
--
-- The tri-state is preserved exactly. bool_or over zero rows is NULL, an id absent
-- from the aggregate is also NULL, and both fall through to the text test -- so an
-- unattested id is still never answered "not a separator" from silence. On a seeded
-- substrate that fallback covers no ids and costs nothing; on the generation_corpus
-- fixture (synthetic content, zero Unicode layer) it is the whole answer, which is
-- the case that broke main on merge and is why the COALESCE is load-bearing.
DROP FUNCTION IF EXISTS laplace.corpus_whitespace_vocab_indices(bytea[]);
CREATE OR REPLACE FUNCTION generation.corpus_whitespace_vocab_indices(p_vocab bytea[])
    RETURNS TABLE(vocab_idx int)
    LANGUAGE plpgsql STABLE PARALLEL SAFE AS $$
DECLARE
    v_type bytea := laplace.relation_type_id('HAS_GENERAL_CATEGORY');
BEGIN
    RETURN QUERY
    WITH cat AS MATERIALIZED (
        SELECT a.subject_id AS id,
               bool_or(cn.name IN ('unicode/category/Zs/v1',
                                   'unicode/category/Zl/v1',
                                   'unicode/category/Zp/v1',
                                   'unicode/category/Cc/v1')) AS is_sep
        FROM laplace.attestations a
        JOIN laplace.canonical_names cn ON cn.id = a.object_id
        WHERE a.type_id = v_type              -- bound literal -> LIST prune at plan time
          AND a.subject_id = ANY (p_vocab)    -- index condition -> HASH prune per id
        GROUP BY a.subject_id
    ), missing AS MATERIALIZED (
        SELECT COALESCE(array_agg(DISTINCT v.id ORDER BY v.id), '{}'::bytea[]) AS ids
        FROM unnest(p_vocab) v(id) LEFT JOIN cat ON cat.id = v.id
        WHERE cat.id IS NULL
    ), rendered AS MATERIALIZED (
        SELECT i.id, i.s
        FROM missing m,
             LATERAL ROWS FROM (
                 unnest(m.ids), unnest(realize.render_text_batch(m.ids))
             ) AS i(id, s)
    )
    SELECT (v.ord::int4 - 1)
    FROM unnest(p_vocab) WITH ORDINALITY v(id, ord)
    LEFT JOIN cat ON cat.id = v.id
    LEFT JOIN rendered r ON r.id = v.id
    WHERE COALESCE(cat.is_sep, realize.is_all_whitespace(r.s));
END;
$$;
DROP FUNCTION IF EXISTS laplace.entity_physicality_coord(bytea);
CREATE OR REPLACE FUNCTION structural.entity_physicality_coord(p_entity bytea)
    RETURNS geometry
    LANGUAGE sql STABLE STRICT PARALLEL SAFE AS $$
    SELECT w.coord
    FROM laplace.v_word_points w
    WHERE w.id = p_entity AND w.coord IS NOT NULL
    LIMIT 1
$$;
-- entity_container_degree: how many higher-tier laplace.entities contain each id.
--
-- This is inverse-document-frequency derived from the substrate's own structure
-- rather than from a word list. A token that appears inside almost every
-- trajectory carries almost no information about which trajectory you meant; a
-- token that appears inside sixteen of them carries a great deal. That is true
-- in any language and any modality, because containment is a property of the
-- composition hierarchy, not of English.
--
-- MEASURED 2026-08-04 on the foundation ladder (1-hop, cap 20000):
--     a 20000+ | the 20000+ | of 20000+ | water 4629 | hot 1040
--     glacier 83 | pawn 23 | france 16
-- The separation is total and needs no stop list. Compare the alternatives that
-- were measured and REJECTED on the same set:
--   * highway popcount  — 'a' scores 19, the HIGHEST in the set, because the
--     tier-0 floor participates in every band. Degree, not specificity.
--   * total_mass        — elects 'chess' over 'pawn'; rewards volume.
--   * ord DESC          — an SVO word-order prior. Wrong for SOV, VSO, a chess
--     position, or an image, in a substrate that is modality-agnostic.
--
-- p_cap is a symptom, not a dial to retune. structural.containers_of ENUMERATES
-- rows to produce a COUNT, so every cap trades separation against latency: a cap
-- low enough to be fast reports the same degree for an ordinary content word as
-- for a pure function word, and a cap high enough to separate them puts a
-- multi-second call under converse.resolve — converse.election_token_profile and
-- prompt_coherence.c:351 both call this on the resolve path. The fix is a
-- maintained or index-only count that never materialises the container rows.
--
-- icf is a PER-TOKEN SCALAR. INVENTION §7 forbids deciding a ranking on one, and
-- #861 requires a key combining what the fold produces per edge. This is an input
-- to an election, never the election.
--
-- Set-based over the whole id array in one call: per-row resolution of this is
-- the read-path defect the architecture rules name explicitly.
DROP FUNCTION IF EXISTS laplace.entity_container_degree(bytea[], integer);
CREATE OR REPLACE FUNCTION structural.entity_container_degree(
    p_ids bytea[],
    p_cap integer DEFAULT NULL)
    RETURNS TABLE(entity_id bytea, degree bigint, icf double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT t.id,
           COALESCE(c.n, 0)::bigint,
           
           (ln(2.0) / ln(2.0 + COALESCE(c.n, 0)::double precision))::double precision
    -- COUNTED, NOT MATERIALISED. Probe physicalities directly: v_word_points joins
    -- every GIN hit to entities, but neither the entity row nor any entity column
    -- contributes to this count. The predicates below exactly match the partial
    -- physicalities_constituents_gin definition, so the posting-list scan remains
    -- indexable without thousands of unnecessary entity lookups.
    --
    -- NULL means exact. A caller may request an explicitly censored diagnostic by
    -- passing p_cap, but the default operation no longer silently reports
    -- min(true_degree, 8192) as if it were the degree.
    FROM unnest(p_ids) AS t(id)
    LEFT JOIN LATERAL (
        SELECT count(*) AS n
        FROM (SELECT 1
              FROM laplace.physicalities p
              WHERE p.type = 1
                AND p.trajectory IS NOT NULL
                AND public.laplace_trajectory_constituent_ids(p.trajectory) @> ARRAY[t.id]
              LIMIT p_cap) z
    ) c ON true
    GROUP BY t.id, c.n
$$;
-- Does this highway mask share any set bit with the band/relation mask?
-- Native (highway_mask.c): the prior SQL body ran a per-row bytea AND through
-- the SQL executor for what is four uint64 AND/OR ops. NULL on either side
-- returns false (unchanged WHERE semantics); length mismatch is an error,
-- matching the old `&` operator behavior.
DROP FUNCTION IF EXISTS laplace.laplace_highway_match(mask bytea, band_mask bytea);
CREATE OR REPLACE FUNCTION consensus.highway_match(mask bytea, band_mask bytea)
    RETURNS boolean
    AS 'laplace_substrate', 'pg_laplace_highway_match'
    LANGUAGE C IMMUTABLE;
-- Number of set bits in a highway mask. Native (highway_mask.c): the prior
-- SQL body implemented POPCNT as get_byte -> bit(8)::text -> replace ->
-- length inside a generate_series loop; this is hardware popcount over
-- uint64 chunks. NULL returns 0 (matches the old COALESCE).
DROP VIEW IF EXISTS laplace.v_entities_highway;
DROP FUNCTION IF EXISTS laplace.laplace_highway_popcount(mask bytea);
CREATE OR REPLACE FUNCTION consensus.highway_popcount(mask bytea)
    RETURNS integer
    AS 'laplace_substrate', 'pg_laplace_highway_popcount'
    LANGUAGE C IMMUTABLE;
-- The 256-bit mask OR-ing every relation bit in the given salience band
-- (band indices come from the manifest's rank ladder; see highway_manifest.h).
-- Requires laplace_substrate.highway_perfcache_path to be configured.
DROP FUNCTION IF EXISTS laplace.laplace_highway_band_mask(int);
CREATE OR REPLACE FUNCTION consensus.highway_band_mask(p_band int)
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_highway_band_mask'
    LANGUAGE C STABLE;
-- Plane selection: every unrefuted consensus edge whose relation type belongs
-- to the given salience band, strongest (eff_mu) first. This is the primitive
-- the foundry/synthesis and band-scoped readers should use instead of hand-rolled
-- rank-threshold scans.
--
-- Native (highway_mask.c): the band's relation-type id set is computed
-- entirely in memory from the highway perfcache (bit -> canonical -> type id,
-- zero DB round trips), then ONE indexed query fetches the edges
-- (consensus_type_btree for the ANY() filter, the eff_mu expression index for
-- ordering) — the define_fast pattern.
-- NO DROP. `DROP FUNCTION IF EXISTS consensus.band_edges(int, bigint, bigint)`
-- stood here and broke EVERY extension upgrade (2026-08-11 06:38, migrate phase):
--
--   ERROR: cannot drop function consensus.band_edges(integer,bigint,bigint)
--          because other objects depend on it
--   DETAIL: function ops.band_leaders(integer[],integer) depends on it
--
-- ops.band_leaders is `LANGUAGE sql STABLE BEGIN ATOMIC`, and an ATOMIC body is
-- parsed at CREATE time and records a real pg_depend edge on everything it
-- references (that is the whole point of the form, and why the G12 gate — string
-- SQL bodies, GH #764 — pushes toward it). So converting a caller to ATOMIC
-- retroactively turns any DROP of its callees into an upgrade-blocking error,
-- and the manifest installs band_edges before band_leaders — the dependent from
-- the PREVIOUS install is still present when the DROP runs.
--
-- The DROP was redundant anyway: name, argument types and return type are all
-- unchanged, so CREATE OR REPLACE alone does the job. A DROP is only load-bearing
-- when the signature or return type CHANGES; this one bought nothing and cost the
-- whole deploy. Same class as #1004, which removed ten of these under identity/.
CREATE OR REPLACE FUNCTION consensus.band_edges(
    p_band       int,
    p_min_eff_mu bigint DEFAULT NULL,
    p_limit      bigint DEFAULT 1000)
    RETURNS TABLE(
        subject_id    bytea,
        type_id       bytea,
        object_id     bytea,
        rating        bigint,
        rd            bigint,
        witness_count bigint,
        eff_mu        bigint)
    AS 'laplace_substrate', 'pg_laplace_consensus_band_edges'
    LANGUAGE C STABLE;
-- The live scoreboard read: running totals plus the ingest heartbeat, cheap
-- enough to poll every few seconds (estimate counts + a PK scan of the tiny
-- flush journal + one pg_stat_activity pass). Consolidated from the API's
-- inline C# SQL — the HTTP /v1/pulse and any MCP caller read THIS.
DROP FUNCTION IF EXISTS laplace.substrate_pulse();

CREATE OR REPLACE FUNCTION ops.substrate_pulse()
    RETURNS TABLE(entities bigint, attestations bigint, consensus bigint,
                  physicalities bigint, last_flush_at timestamptz,
                  flushes_last_min bigint, folding boolean)
    LANGUAGE sql STABLE
    AS $$
    SELECT
      (SELECT value FROM ops.substrate_counts() WHERE metric = 'entities(ESTIMATE)'),
      (SELECT value FROM ops.substrate_counts() WHERE metric = 'attestations(ESTIMATE)'),
      (SELECT value FROM ops.substrate_counts() WHERE metric = 'consensus(ESTIMATE)'),
      (SELECT value FROM ops.substrate_counts() WHERE metric = 'physicalities(ESTIMATE)'),
      (SELECT max(applied_at) FROM laplace.ingest_flush_journal),
      (SELECT count(*) FROM laplace.ingest_flush_journal
        WHERE applied_at > now() - interval '60 seconds'),
      -- Folding = rows landed recently OR a fold/apply backend is active. The
      -- journal alone under-reports a slow-flush ingest mid-working-set.
      -- pg_backend_pid() is excluded: this query's own text contains the
      -- pattern strings and would otherwise match itself forever.
      (SELECT (SELECT max(applied_at) FROM laplace.ingest_flush_journal) > now() - interval '20 seconds')
        OR EXISTS (
          SELECT 1 FROM pg_stat_activity a
          WHERE a.datname = current_database()
            AND a.state = 'active'
            AND a.pid <> pg_backend_pid()
            AND a.query ILIKE ANY (ARRAY['%attestation_merge%', '%consensus_upsert%', '%COPY %laplace.%']))
$$;
-- Ingest run history, newest first: the answer to "did that ingest finish,
-- and if not, how far did it get?". A 'running' row whose process is gone is
-- a cut-off run; seed verification passes on the latest row for a source
-- being ok/skipped-complete with evidence persisted.
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.ingest_runs(int);

CREATE OR REPLACE FUNCTION ops.ingest_runs(p_limit int DEFAULT 20)
    RETURNS SETOF laplace.ingest_run_journal
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT *
    FROM laplace.ingest_run_journal
    ORDER BY started_at DESC
    LIMIT greatest(p_limit, 0);
END;
-- Physical artifact inventory and admitted-file lifecycle for one ingest run.
-- Actionable admitted states sort first; explicit non-selected dispositions remain
-- readable after completed files instead of disappearing during source selection.
DROP FUNCTION IF EXISTS laplace.ingest_files(uuid, int);

CREATE OR REPLACE FUNCTION ops.ingest_files(p_run_id uuid, p_limit int DEFAULT 200)
    RETURNS SETOF laplace.ingest_file_journal
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT *
    FROM laplace.ingest_file_journal
    WHERE run_id = p_run_id
    ORDER BY
        CASE status
            WHEN 'running' THEN 0
            WHEN 'composed' THEN 1
            WHEN 'inventoried' THEN 2
            WHEN 'failed' THEN 3
            WHEN 'cancelled' THEN 4
            WHEN 'not-selected' THEN 6
            ELSE 5
        END,
        COALESCE(ended_at, started_at) DESC,
        file_label
    LIMIT greatest(p_limit, 0);
END;
-- Honest per-modality resident counts. Evidence modalities use the fast approx
-- catalog (~200ms) — never the unbounded exact aggregate. Documents ride the
-- document entity type with ~zero attestations (GH #660), so they are counted
-- structurally via entity_count, not by attestation source. Chess arrived as
-- ChessAnalysis/ChessPgn/ChessOpenings; OMW meshes languages through the ILI
-- hub; models count on their plane relation until a checkpoint ingests.
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.modality_counts();

CREATE OR REPLACE FUNCTION ops.modality_counts()
    RETURNS TABLE(
        text_evidence bigint,
        chess bigint,
        models bigint,
        multilingual bigint,
        documents bigint)
    LANGUAGE sql
    STABLE
BEGIN ATOMIC
    WITH s AS (SELECT source, evidence_approx FROM ops.source_counts_approx()),
    parts AS (
      SELECT
        COALESCE((SELECT sum(evidence_approx) FROM s), 0)::bigint AS total,
        COALESCE((SELECT sum(evidence_approx) FROM s WHERE source ILIKE '%chess%'), 0)::bigint AS chess,
        (SELECT count(*) FROM laplace.consensus c
           WHERE c.type_id = laplace.relation_type_id('ATTENDS'))::bigint AS models,
        COALESCE((SELECT sum(evidence_approx) FROM s
           WHERE source ILIKE '%OMWDecomposer%' OR source ILIKE '%tatoeba%'), 0)::bigint AS multilingual,
        COALESCE(ops.entity_count(laplace.entity_type_id('Document')), 0)::bigint AS documents)
    SELECT greatest(0, p.total - p.chess - p.models - p.multilingual),
           p.chess, p.models, p.multilingual, p.documents
    FROM parts p;
END;
-- A source's roster: a bounded SAMPLE of what this witness asserts, fully
-- labeled. By id (the per-leaf source_id indexes make it ~1s cold); "top"
-- would demand an unbounded sort over millions of rows — a sample is the
-- honest bounded read.
--
-- String body on purpose (not BEGIN ATOMIC): extension upgrades recreate
-- v_attestation_readable in the same script; parse-time resolution fails with
-- "relation does not exist" mid-upgrade (GH #764).
DROP FUNCTION IF EXISTS laplace.source_roster(bytea, int);

CREATE OR REPLACE FUNCTION ops.source_roster(p_source bytea, p_limit int DEFAULT 40)
    RETURNS TABLE(subject_id bytea, subject text, relation text,
                  object_id bytea, object text, observations bigint)
    LANGUAGE sql STABLE
AS $$
    SELECT a.subject_id, a.subject_label,
           consensus.relation_canonical(a.type_id),
           a.object_id, a.object_label,
           a.observation_count
    FROM laplace.v_attestation_readable a
    WHERE a.source_id = p_source
      -- Every source bootstraps the shared relation law first. Those rows have
      -- relation-type subjects and otherwise consume the whole bounded sample,
      -- making every source appear to hold the same content.
      AND consensus.relation_canonical(a.subject_id) IS NULL
    LIMIT p_limit
$$;
-- Positive control for the roster's bootstrap filter (#760): does this source
-- carry its relation-law bootstrap rows? The writer emits name-alias rows
-- whose subjects are relation-type ids. The law relation arrives as an id
-- parameter — vocabulary is the caller's declaration (G3: no relation-name
-- literals in SQL bodies) — so the probe prunes to that type's partition and
-- walks only the source's rows there; EXISTS short-circuits on the first
-- bootstrap row; no renders, no per-row scan of content partitions.
DROP FUNCTION IF EXISTS laplace.source_bootstrap_present(bytea);
DROP FUNCTION IF EXISTS laplace.source_bootstrap_present(bytea, bytea);

CREATE OR REPLACE FUNCTION ops.source_bootstrap_present(p_source bytea, p_law_type bytea)
    RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM laplace.attestations
        WHERE type_id = p_law_type
          AND source_id = p_source
          AND consensus.relation_canonical(subject_id) IS NOT NULL)
$$;
-- Drive an orphaned journal row terminal: the typed form of the checkpoint
-- ops step ("mark a true orphan failed/cancelled — never leave 'running'
-- forever"). SQL cannot verify process liveness: the CALLER owes the check
-- that no live ingest owns the run (no active backend, no Laplace.Cli you did
-- not start) before closing. Refuses rows not currently 'running' and
-- statuses outside the cut-off terminal vocabulary.
DROP FUNCTION IF EXISTS laplace.ingest_run_close(uuid, text);
CREATE OR REPLACE FUNCTION ops.ingest_run_close(p_run_id uuid, p_status text DEFAULT 'cancelled')
    RETURNS laplace.ingest_run_journal
    LANGUAGE plpgsql VOLATILE
    AS $$
DECLARE
    r laplace.ingest_run_journal%ROWTYPE;
BEGIN
    IF p_status NOT IN ('failed', 'cancelled') THEN
        RAISE EXCEPTION 'ingest_run_close: % is not a cut-off terminal status (failed|cancelled)', p_status;
    END IF;
    UPDATE laplace.ingest_run_journal
       SET status = p_status, ended_at = now()
     WHERE run_id = p_run_id AND status = 'running'
    RETURNING * INTO r;
    IF r.run_id IS NULL THEN
        RAISE EXCEPTION 'ingest_run_close: run % has no row in status=running', p_run_id;
    END IF;
    RETURN r;
END $$;
-- ops.source_status(): is this source ingested, and how do you know?
--
-- WHY THIS EXISTS. There was no standardized answer to the most basic operational
-- question in the system, so every caller assembled one, and every assembly was wrong in
-- a different way. The source inventory therefore comes from the substrate itself, while
-- the journal remains authority for the most recent operation and its measured health.
--
-- Throughput is the same rule: UI/API/MCP/CLI and CI must not independently parse logs
-- and invent different answers. The latest clean run carrying a throughput verdict is
-- projected alongside the latest run status. A later marker skip may be the latest run
-- while the previous real run remains the relevant throughput observation; an
-- `unmeasured` clean run is itself a verdict and must remain visible rather than exposing
-- an older green comparison.
DROP FUNCTION IF EXISTS ops.source_status(text);
DROP FUNCTION IF EXISTS laplace.source_status(text);

CREATE OR REPLACE FUNCTION ops.source_status(p_source text DEFAULT NULL)
    RETURNS TABLE(source                         text,
                  source_id                      bytea,
                  ingested                       boolean,
                  known                          boolean,
                  evidence_approx                bigint,
                  has_entities                   boolean,
                  last_run_status                text,
                  last_run_at                    timestamptz,
                  throughput_status              text,
                  throughput_compared            boolean,
                  throughput_rows_per_s          double precision,
                  throughput_baseline_rows_per_s double precision,
                  throughput_slowdown_ratio      double precision)
    LANGUAGE sql STABLE
    AS $$
WITH by_evidence AS (
    SELECT s.source_id, s.evidence_approx
    FROM ops.source_counts_approx() s
),
-- Journal is ops metadata: authoritative about the LAST RUN, never about substrate
-- existence. Keep this separate from by_throughput because a marker skip must not erase
-- the last real throughput verdict.
by_journal AS (
    SELECT DISTINCT ON (j.source_name)
           j.source_name, j.source_id, j.status, j.started_at
    FROM @extschema@.ingest_run_journal j
    ORDER BY j.source_name, j.started_at DESC
),
by_throughput AS (
    SELECT DISTINCT ON (j.source_name)
           j.source_name, j.source_id,
           j.throughput_status,
           j.throughput_compared,
           j.throughput_rows_per_s,
           j.throughput_baseline_rows_per_s,
           j.throughput_slowdown_ratio
    FROM @extschema@.ingest_run_journal j
    WHERE j.status = 'ok'
      AND j.throughput_status <> 'not-measured'
    ORDER BY j.source_name, j.started_at DESC
),
ids AS (
    SELECT source_id FROM by_evidence
    UNION SELECT source_id FROM by_journal WHERE source_id IS NOT NULL
),
rolled AS (
    SELECT i.source_id,
           -- EXACT FOR THE TAIL, ESTIMATE FOR THE HEAD. ops.source_counts_approx()
           -- derives evidence from planner MCV statistics. The estimator can miss a
           -- small source, so count only that tail exactly instead of scanning the head.
           COALESCE(ev.evidence_approx,
                    (SELECT count(*) FROM @extschema@.attestations a
                      WHERE a.source_id = i.source_id))             AS evidence_approx,
           EXISTS (SELECT 1 FROM @extschema@.entities e
                   WHERE e.first_observed_by = i.source_id)        AS has_entities,
           jr.source_name                                          AS journal_name,
           jr.status                                               AS last_run_status,
           jr.started_at                                           AS last_run_at,
           tp.throughput_status,
           COALESCE(tp.throughput_compared, false)                 AS throughput_compared,
           tp.throughput_rows_per_s,
           tp.throughput_baseline_rows_per_s,
           tp.throughput_slowdown_ratio
    FROM ids i
    LEFT JOIN by_evidence   ev ON ev.source_id = i.source_id
    LEFT JOIN by_journal    jr ON jr.source_id = i.source_id
    LEFT JOIN by_throughput tp ON tp.source_id = i.source_id
), rolled_numbered AS MATERIALIZED (
    SELECT r.*, row_number() OVER (ORDER BY r.source_id) AS rn FROM rolled r
), rendered AS MATERIALIZED (
    SELECT realize.render_batch(array_agg(source_id ORDER BY rn)) AS labels
    FROM rolled_numbered
),
matched AS (
    SELECT COALESCE(
               r.journal_name,
               regexp_replace(
                   x.labels[r.rn], '^substrate/source/(.+)/v1$', '\1')) AS source,
           r.source_id,
           (r.evidence_approx > 0 OR r.has_entities)                AS ingested,
           true                                                     AS known,
           r.evidence_approx,
           r.has_entities,
           r.last_run_status,
           r.last_run_at,
           r.throughput_status,
           r.throughput_compared,
           r.throughput_rows_per_s,
           r.throughput_baseline_rows_per_s,
           r.throughput_slowdown_ratio
    -- The journal's recorded name beats realize.render(). A carried sub-source such as
    -- PredicateMatrix has no independent run row, so strip only the governed source
    -- envelope from its rendered identity rather than exposing
    -- "substrate/source/PredicateMatrixDecomposer/v1" as the operator label.
    FROM rolled_numbered r CROSS JOIN rendered x
    WHERE p_source IS NULL
       OR r.journal_name = p_source
       OR r.source_id = @extschema@.source_id(p_source)
)
SELECT * FROM matched
UNION ALL
-- A named query always returns one row: absence must not be overloaded with a typo.
SELECT p_source,
       @extschema@.source_id(p_source),
       false,
       EXISTS (SELECT 1 FROM @extschema@.entities e
               WHERE e.id = @extschema@.source_id(p_source)),
       0::bigint,
       false,
       NULL::text,
       NULL::timestamptz,
       NULL::text,
       false,
       NULL::double precision,
       NULL::double precision,
       NULL::double precision
WHERE p_source IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM matched)
ORDER BY evidence_approx DESC, source_id
$$;
-- A node's position in the semantic mesh. IDs are selected and ranked first;
-- every display label is resolved in one position-aligned batch at the edge.
DROP FUNCTION IF EXISTS laplace.mesh_position(bytea);
DROP FUNCTION IF EXISTS structural.mesh_position(bytea);
CREATE OR REPLACE FUNCTION structural.mesh_position(
    p_id bytea,
    p_relation_limit integer DEFAULT NULL,
    p_member_limit integer DEFAULT NULL)
    RETURNS TABLE(dir text, id bytea, label text, relation text,
                  hub_type text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE AS $$
    WITH self_hub AS MATERIALIZED (
        SELECT (SELECT t.object_id
                FROM laplace.consensus t
                WHERE t.subject_id=p_id AND t.type_id=laplace.relation_type_id('IS_TYPED_AS')
                ORDER BY consensus.eff_mu(t.rating,t.rd) DESC, t.object_id LIMIT 1) AS object_id
    ), up_subjects AS MATERIALIZED (
        SELECT p_id AS id
        UNION
        SELECT n.subject_id
        FROM laplace.consensus n
        WHERE n.object_id = p_id
          AND n.type_id = ANY (consensus.relation_set_ids('NAME_ALIAS_EDGE'))
    ), sense_rows AS MATERIALIZED (
        SELECT s.synset_id AS id, s.eff_mu, s.witnesses,
               row_number() OVER (ORDER BY s.eff_mu DESC NULLS LAST, s.synset_id) AS ord
        FROM lexical.senses(p_id) s
        WHERE NOT EXISTS (
          SELECT 1 FROM laplace.consensus t
          WHERE t.subject_id=p_id AND t.type_id=laplace.relation_type_id('IS_TYPED_AS')
            AND consensus.eff_mu(t.rating,t.rd)>0)
    ), up_rows AS MATERIALIZED (
        SELECT c.object_id AS id, c.type_id,
               (SELECT t.object_id FROM laplace.consensus t
                WHERE t.subject_id=c.object_id
                  AND t.type_id=laplace.relation_type_id('IS_TYPED_AS')
                ORDER BY consensus.eff_mu(t.rating,t.rd) DESC, t.object_id LIMIT 1) AS hub_id,
               consensus.eff_mu_display(c.rating,c.rd) AS eff_mu, c.witness_count,
               row_number() OVER (ORDER BY consensus.eff_mu_display(c.rating,c.rd) DESC NULLS LAST,
                                           c.object_id) AS ord
        FROM up_subjects s
        JOIN laplace.consensus c ON c.subject_id=s.id
        WHERE c.type_id IN (laplace.relation_type_id('IS_SENSE_OF'),
                            laplace.relation_type_id('HAS_SENSE'),
                            laplace.relation_type_id('EVOKES_FRAME'),
                            laplace.relation_type_id('MEMBER_OF_VERBNET_CLASS'),
                            laplace.relation_type_id('IS_INSTANCE_OF'),
                            laplace.relation_type_id('IS_A'),
                            laplace.relation_type_id('CORRESPONDS_TO'),
                            laplace.relation_type_id('HAS_SEMANTIC_ROLE'))
        ORDER BY eff_mu DESC NULLS LAST, c.object_id
        LIMIT GREATEST(p_relation_limit, 0)
    ), down_rows AS MATERIALIZED (
        SELECT m.member AS id, m.kind, m.mu, m.witnesses,
               row_number() OVER (ORDER BY m.mu DESC NULLS LAST, m.member) AS ord
        FROM lexical.concept_members(p_id) m
        ORDER BY m.mu DESC NULLS LAST, m.member
        LIMIT GREATEST(p_member_limit, 0)
    ), raw AS MATERIALIZED (
        SELECT 0 AS branch, 0::bigint AS ord, 'self'::text AS dir, p_id AS id,
               NULL::text AS relation, h.object_id AS hub_id, NULL::text AS hub_literal,
               NULL::numeric AS eff_mu, NULL::bigint AS witnesses FROM self_hub h
        UNION ALL
        SELECT 1, s.ord, 'up', s.id, 'has sense', NULL, 'WordNet_Synset', s.eff_mu, s.witnesses
        FROM sense_rows s
        UNION ALL
        SELECT 2, u.ord, 'up', u.id, consensus.relation_canonical(u.type_id),
               u.hub_id, NULL, u.eff_mu, u.witness_count FROM up_rows u
        UNION ALL
        SELECT 3, d.ord, 'down', d.id, d.kind, NULL, NULL, d.mu, d.witnesses FROM down_rows d
    ), ids AS MATERIALIZED (
        SELECT array_agg(DISTINCT id ORDER BY id) AS a
        FROM (SELECT id FROM raw UNION SELECT hub_id FROM raw WHERE hub_id IS NOT NULL) x
    ), labels AS MATERIALIZED (
        SELECT i.id, i.txt FROM ids,
          LATERAL ROWS FROM (
            unnest(ids.a), unnest(realize.label_batch(ids.a))
          ) i(id, txt)
    )
    SELECT r.dir, r.id, n.txt, r.relation,
           COALESCE(r.hub_literal, h.txt), r.eff_mu, r.witnesses
    FROM raw r JOIN labels n ON n.id=r.id LEFT JOIN labels h ON h.id=r.hub_id
    ORDER BY r.branch, r.ord
$$;
-- The IS_A tree around a topic: dir='self' the root (a bare surface hops to
-- its top synset — taxonomy lives on concepts, not spellings), dir='up' the
-- parent chain to the root, dir='child' the strongest sub-kinds.
DROP FUNCTION IF EXISTS laplace.taxonomy_tree(bytea);
DROP FUNCTION IF EXISTS taxonomy.tree(bytea);
CREATE OR REPLACE FUNCTION taxonomy.tree(
    p_id bytea,
    p_depth integer DEFAULT NULL,
    p_child_limit integer DEFAULT NULL)
    RETURNS TABLE(dir text, ord int, id bytea, label text, eff_mu numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH root AS MATERIALIZED (
        SELECT COALESCE(taxonomy.top_synset(p_id), p_id) AS id
    ), raw AS MATERIALIZED (
      SELECT 'self'::text AS dir, 0 AS ord, root.id, NULL::numeric AS eff_mu FROM root
      UNION ALL
      SELECT 'up', w.step, w.entity_id, w.eff_mu
      FROM root, consensus.walk_strongest(
          root.id, laplace.relation_type_id('IS_A'), p_depth) w
      UNION ALL
      (SELECT 'child',
            row_number() OVER (ORDER BY consensus.eff_mu_display(c.rating, c.rd) DESC)::int,
            c.subject_id,
            consensus.eff_mu_display(c.rating, c.rd)
       FROM root JOIN laplace.consensus c
         ON c.object_id = root.id AND c.type_id = laplace.relation_type_id('IS_A')
       ORDER BY consensus.eff_mu_display(c.rating, c.rd) DESC
       LIMIT GREATEST(p_child_limit, 0))
    ), ids AS MATERIALIZED (
      SELECT array_agg(DISTINCT id ORDER BY id) AS a FROM raw
    ), labels AS MATERIALIZED (
      SELECT i.id, i.txt FROM ids,
        LATERAL ROWS FROM (
          unnest(ids.a), unnest(realize.label_batch(ids.a))
        ) i(id, txt)
    )
    SELECT r.dir, r.ord, r.id, l.txt, r.eff_mu
    FROM raw r JOIN labels l ON l.id=r.id
    ORDER BY CASE r.dir WHEN 'self' THEN 0 WHEN 'up' THEN 1 ELSE 2 END, r.ord
$$;
-- Per-band leaderboards: the strongest consensus edges in each salience band,
-- fully labeled — consensus.band_edges(native top-k by mu) with the labels
-- applied only to the survivors. BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.band_leaders(int[], int);
CREATE OR REPLACE FUNCTION ops.band_leaders(p_bands int[] DEFAULT ARRAY[1,2,4,5], p_per int DEFAULT 5)
    RETURNS TABLE(band int, subject_id bytea, subject text, relation text,
                  object_id bytea, object text, eff_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH raw AS MATERIALIZED (
      SELECT b.band, e.subject_id, e.type_id, e.object_id, e.rating, e.rd, e.witness_count
      FROM unnest(p_bands) AS b(band)
      CROSS JOIN LATERAL consensus.band_edges(b.band, NULL, p_per) e
    ), ids AS MATERIALIZED (
      SELECT array_agg(DISTINCT id ORDER BY id) AS a
      FROM (SELECT subject_id AS id FROM raw UNION SELECT object_id FROM raw) x
    ), labels AS MATERIALIZED (
      SELECT i.id, i.txt FROM ids,
        LATERAL ROWS FROM (
          unnest(ids.a), unnest(realize.label_batch(ids.a))
        ) i(id, txt)
    )
    SELECT e.band, e.subject_id, s.txt,
           consensus.relation_canonical(e.type_id),
           e.object_id, o.txt,
           consensus.eff_mu_display(e.rating, e.rd), e.witness_count
    FROM raw e JOIN labels s ON s.id=e.subject_id JOIN labels o ON o.id=e.object_id;
END;
-- An entity's verdict record: its edges grouped by the canonical epistemic_status
-- verdict rule — confirmed / contested / refuted / thin. The rule lives in
-- converse.epistemic_status_core; this only counts, and no client re-derives it
-- from raw mu. Counts read the CORE, not the rendering wrapper: the wrapper also
-- renders + realizes up to 500 object texts a counter throws away — MEASURED
-- 2026-08-21 on a hot entity: 1,984 ms wrapped, 308 ms core, identical counts.
DROP FUNCTION IF EXISTS laplace.entity_record(bytea);

CREATE OR REPLACE FUNCTION ops.entity_record(p_id bytea)
    RETURNS TABLE(confirmed bigint, contested bigint, refuted bigint, thin bigint)
    LANGUAGE sql STABLE
    AS $$
    SELECT count(*) FILTER (WHERE s.status = 'confirmed'),
           count(*) FILTER (WHERE s.status = 'contested'),
           count(*) FILTER (WHERE s.status = 'refuted'),
           count(*) FILTER (WHERE s.status = 'thin')
    FROM converse.epistemic_status_core(p_id, 500) s
$$;
-- Whether the highway perfcache blob is loaded (laplace_substrate.highway_perfcache_path
-- GUC configured and mmap'd). Read paths error with a hint when it is missing;
-- write paths (highway_mask_refresh) use this to degrade to a no-op instead of
-- faulting the ingest fold.
DROP FUNCTION IF EXISTS laplace.laplace_highway_ready();
CREATE OR REPLACE FUNCTION consensus.highway_ready()
    RETURNS boolean
    LANGUAGE C STABLE PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_highway_ready';
-- Whether the chess compose-floor blob is loaded
-- (laplace_substrate.chess_position_perfcache_path GUC configured and mmap'd).
-- Tier-1 piece×square vocab + catalog tier-2 positions (GH #822 / spec 33).
-- Tier 0 remains codepoints (laplace_t0_perfcache).
DROP FUNCTION IF EXISTS laplace.laplace_chess_position_ready();
CREATE OR REPLACE FUNCTION chess.position_ready()
    RETURNS boolean
    LANGUAGE C STABLE PARALLEL SAFE
    AS 'laplace_substrate', 'pg_laplace_chess_position_ready';
-- Inverse of laplace_highway_mask_bits: build a 32-byte mask from bit positions.
-- Native C (pg_laplace_highway_mask_from_bits in highway_mask.c): bit numbering
-- is byte b/8, LSB-first within the byte (mask[b>>3] |= 1 << (b&7)) — the same
-- memcpy-identity contract highway_mask.c documents and extracts via ctz, and
-- byte-identical to the prior plpgsql set_bit() loop. NULL input, or a mask that
-- ends up with no bits set (empty/all-out-of-range array), returns NULL — the
-- any_set contract highway_mask_refresh relies on every fold epoch. Round trip
-- consensus.highway_mask_bits(mask_from_bits(x)) = sorted(x) is a regression.
-- Bit VALUES still come only from consensus.relation_highway_bit(the perfcache); this
-- function never assigns meaning to a position.
DROP FUNCTION IF EXISTS laplace.laplace_highway_mask_from_bits(int[]);
CREATE OR REPLACE FUNCTION consensus.highway_mask_from_bits(p_bits int[])
    RETURNS bytea
    AS 'laplace_substrate', 'pg_laplace_highway_mask_from_bits'
    LANGUAGE C IMMUTABLE PARALLEL SAFE;
-- Recompute entities.highway_mask for the given entity ids from their CONSENSUS
-- participation (subject or object) — the one derivation of the relation-membership
-- mask, matching the foundry's authoritative fallback (FoundryExport
-- FillHighwayMasksAsync): OR of the relation bits over every distinct governed
-- relation type the entity has edges under. Recompute-not-accumulate: idempotent,
-- self-healing, no drift. Entities whose every edge type is ungoverned keep NULL.
-- Called per fold epoch by the ingest spine (every decomposer rides it) and by
-- highway_mask_rebuild for full population. No-ops with a warning when the highway
-- perfcache is not configured (hart-server before its blob deploys) so the fold
-- never faults on mask maintenance.
DROP FUNCTION IF EXISTS laplace.highway_mask_refresh(bytea[]);
CREATE OR REPLACE FUNCTION consensus.highway_mask_refresh(p_ids bytea[])
    RETURNS bigint
    LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    updated bigint;
BEGIN
    IF NOT consensus.highway_ready() THEN
        RAISE WARNING 'highway_mask_refresh: highway perfcache not configured — masks not refreshed (set laplace_substrate.highway_perfcache_path)';
        RETURN 0;
    END IF;

    WITH t AS (SELECT DISTINCT u.id FROM unnest(p_ids) AS u(id)),
    tp AS (
        SELECT t.id, c.type_id FROM t JOIN laplace.consensus c ON c.subject_id = t.id
        GROUP BY t.id, c.type_id
        UNION
        SELECT t.id, c.type_id FROM t JOIN laplace.consensus c ON c.object_id = t.id
        GROUP BY t.id, c.type_id
    ),
    bits AS (
        -- A DYNAMIC relation (EDEP_nsubj, DEP_obj, FEAT_case, ... minted at ingest) has NO
        -- highway bit of its own — bits are codegen-assigned to the static governed set only.
        -- So it contributes its FAMILY ROOT's bit: SeedDynamic emits `<child> IS_A <root>`, and
        -- the root (ENHANCED_DEPENDS_ON, DEPENDS_ON, HAS_FEATURE, ...) is static and has a bit.
        -- Without this the entire UD dependency/feature layer is invisible to mask-gated walks.
        SELECT q.id, q.bit
        FROM (
            SELECT tp.id,
                   COALESCE(consensus.relation_highway_bit(tp.type_id),
                            consensus.relation_highway_bit(fam.object_id)) AS bit
            FROM tp
            LEFT JOIN laplace.consensus fam
              ON fam.subject_id = tp.type_id
             AND fam.type_id = laplace.relation_type_id('IS_A')
        ) q
        WHERE q.bit IS NOT NULL
    ),
    m AS (
        SELECT bits.id, consensus.highway_mask_from_bits(array_agg(DISTINCT bits.bit)) AS mask
        FROM bits GROUP BY bits.id
    ),
    upd AS (
        UPDATE laplace.entities e SET highway_mask = m.mask
        FROM m
        WHERE e.id = m.id AND m.mask IS DISTINCT FROM e.highway_mask
        RETURNING 1
    )
    SELECT count(*) INTO updated FROM upd;
    RETURN updated;
END $$;
-- Drain the mask refresh queue: recompute highway_mask for exactly the entities whose
-- consensus participation changed, then forget them. Narrower than
-- highway_mask_rebuild (full pass over every entity).
--
-- NOT ON THE INGEST PATH (2026-07-21). Ingest deposits masks inline via
-- highway_mask_deposit and neither queues nor drains. This is the REPAIR verb for the
-- one thing deposit cannot do: deposit only OR-accumulates bits ON, so a mutation that
-- must turn bits OFF -- per-source eviction removing an entity's last governed edge --
-- queues the affected entities into laplace.highway_mask_dirty and calls this, because
-- highway_mask_refresh recomputes from scratch and can therefore clear.
--
-- Batched with a COMMIT per batch so a long drain never holds one transaction open, and
-- so an interrupted drain keeps its progress: rows are deleted only after their masks
-- are written, making the whole procedure resumable and idempotent. Re-running it after
-- a crash re-refreshes at most one batch that was already correct — highway_mask_refresh
-- is recompute-not-accumulate, so that is a no-op, never drift.
--
-- Emits LOG (not NOTICE) progress: NOTICE is client-only and with log_min_messages at
-- its WARNING default it reaches the server log never, which is what made the old full
-- rebuild look like a dead stall for minutes at a time.
--
-- No SET clause: a PL/pgSQL procedure carrying one is barred from transaction control
-- (COMMIT), so references are schema-qualified instead.
DROP PROCEDURE IF EXISTS highway_mask_drain(int);
CREATE OR REPLACE PROCEDURE laplace.highway_mask_drain(p_batch int DEFAULT 100000)
    LANGUAGE plpgsql AS $$
DECLARE
    ids     bytea[];
    n       bigint;
    total   bigint := 0;
    drained bigint := 0;
    queued  bigint;
    t0      timestamptz := clock_timestamp();
BEGIN
    SELECT count(*) INTO queued FROM laplace.highway_mask_dirty;
    IF queued = 0 THEN
        RETURN;
    END IF;
    RAISE LOG 'highway_mask_drain: start — % entities queued', queued;

    LOOP
        SELECT array_agg(d.id) INTO ids
        FROM (SELECT id FROM laplace.highway_mask_dirty LIMIT p_batch) d;
        EXIT WHEN ids IS NULL;

        n := consensus.highway_mask_refresh(ids);
        DELETE FROM laplace.highway_mask_dirty WHERE id = ANY(ids);

        total   := total + n;
        drained := drained + cardinality(ids);
        RAISE LOG 'highway_mask_drain: % masks written / % of % drained (% percent) — %s elapsed',
            total, drained, queued,
            round(100.0 * drained / NULLIF(queued, 0), 1),
            round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
        COMMIT;
    END LOOP;

    RAISE LOG 'highway_mask_drain: done — % masks written / % entities in %s',
        total, drained, round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
END $$;
-- Deposit highway-mask bits for the (entity, relation-type) pairs an epoch's
-- edges actually touched — the fold KNOWS every pair in RAM, so the mask is
-- populated at deposit time with ZERO consensus re-reads. This replaces the
-- per-epoch highway_mask_refresh recompute, whose object-side join probed every
-- consensus leaf per touched entity (measured: 75s of a 118s fold).
-- OR-accumulate is correct at ingest: edges are only ever ADDED, so bits only
-- ever turn on; idempotent and chunk-order-free. On a greenfield seed this
-- deposit IS the population — highway_mask_refresh/rebuild are legacy repair
-- verbs for pre-deposit databases and retire once no such DB exists.
--
-- Deposits are entity-sharded BEFORE this function is called. Every entity has
-- one stable writer lane for the run, so concurrent ingest calls are row-disjoint.
-- The former global advisory lock survived that writer correction and silently
-- collapsed the topology-derived mask fanout back to one connection.
--
-- External/online writers can still overlap an ingest. Their safety boundary is
-- deterministic target-row acquisition below: every statement locks `(id,tier)`
-- in bytewise order before the set UPDATE. Two overlapping writers therefore
-- cannot acquire the same rows in opposite order; disjoint ingest shards never
-- wait on each other and no process-global mutex remains.
--
-- History of the earlier shapes, retained so none are repeated:
--
--   bd10fcf  moved the deposit server-side and CONCURRENT → AB/BA deadlocks
--            between fold lanes on shared entity rows (hot words appear in
--            every delta), 10/10 whole-batch retries lost.
--   #729     ordered the locks WITHIN one statement → still deadlocked: the
--            transaction ran a SEQUENCE of chunk statements holding prior
--            chunks' locks.
--   #732/#733 sorted the pairs client-side and committed per chunk → deadlock
--            gone, replaced by a MEASURED 6.4 ms/row FOR NO KEY UPDATE tax
--            (EXPLAIN ANALYZE: 84 ms to find+sort 5,000 rows, 32,039 ms in
--            LockRows) — concurrent lockers minting multixacts per tuple.
--            Fold masks/s: 3,305 (crashing run) → 333 (correct, convoyed).
--   #1112    sharded the lock — hash entities into N buckets, take each chunk's
--            buckets in ASCENDING order. Deadlock-free by the ordered-resource
--            argument, and unlike #729 the ordering is over a bounded set so it
--            survives the sequence of chunk statements; unlike #732/#733 it mints
--            no multixacts. BENCHED, NOT SHIPPED, and it is a dead end: MEASURED
--            2026-08-16, 8 workers x 12 chunks x 70% overlap, 4,000 real row
--            updates, identical to the installed form on every axis —
--            0 deadlocks / 78% lock_wait / 11-12 ms deposit delta, both, twice.
--            The reason is arithmetic: a 500-entity chunk touches 16/16 shards,
--            64/64, 223/256, 399/1024, 475/4096. Hashing entities AFTER the chunk
--            is formed scatters them across every bucket, so "take only the shards
--            you need" is "take them all" plus N acquisitions. Sharding can only
--            pay if the WORK is partitioned shard-locally when the chunk is BUILT,
--            which is a writer change (ConsensusAccumulatingWriter), not a lock
--            change. scripts/tests/highway-deposit-concurrency.sh is the bench;
--            a fifth attempt must beat 0 deadlocks at 78% before it ships.
--
-- #1183 supplied the missing writer change identified above: work is now
-- partitioned shard-locally when the chunk is built. Retaining a global lock
-- after that change was pure serialization, not a correctness mechanism.
DROP FUNCTION IF EXISTS laplace.highway_mask_deposit(bytea[], bytea[]);
CREATE OR REPLACE FUNCTION consensus.highway_mask_deposit(p_entity_ids bytea[], p_type_ids bytea[])
    RETURNS bigint
    AS 'laplace_substrate', 'pg_laplace_highway_mask_deposit'
    LANGUAGE C VOLATILE;
-- Model-factor query surface (campaign doc 26 item B, v1): SQL over the factor
-- trajectories the model lane deposits. Loops live in C (model_factor.c);
-- trajectory layout is the FactorTrajectory law. Tokens returned are WORD
-- ENTITIES — joinable against consensus/senses/anything in the web. v1 reads
-- the PostGIS varlena with a linear header scan (~450 ms/call); the factor
-- perfcache blob turns both into pointer arithmetic.

-- The model's own coupling q(A)·k(B) in one circuit, by lookup.
DROP FUNCTION IF EXISTS laplace.model_pair_score(bytea, bytea, bytea, bytea);
CREATE OR REPLACE FUNCTION generation.model_pair_score(
    p_q_slice bytea,
    p_k_slice bytea,
    p_tok_a   bytea,
    p_tok_b   bytea)
    RETURNS float8
    AS 'laplace_substrate', 'pg_laplace_model_pair_score'
    -- STRICT is load-bearing, not decoration: these C entry points dereference
    -- their slice arguments without a null check, so a NULL reaching them
    -- segfaults the backend and takes the whole cluster into recovery. Callers
    -- routinely produce NULL by construction — a scalar subquery over a slice
    -- directory returns NULL when the model deposited no slices at that plane.
    LANGUAGE C STABLE STRICT;

-- One token's attention row in one circuit: k strongest partners, native scan.
DROP FUNCTION IF EXISTS laplace.model_row_topk(bytea, bytea, bytea, int);
CREATE OR REPLACE FUNCTION generation.model_row_topk(
    p_q_slice bytea,
    p_k_slice bytea,
    p_tok     bytea,
    p_k       int DEFAULT 20)
    RETURNS TABLE(token bytea, score float8)
    AS 'laplace_substrate', 'pg_laplace_model_row_topk'
    -- STRICT: see model_pair_score. On a set-returning function this yields the
    -- empty set for a NULL slice instead of a crash.
    LANGUAGE C STABLE STRICT ROWS 20;

-- Circuit navigation by anatomy. Order disambiguates layer vs head via
-- PRECEDES laplace.attestations whose CONTEXT is the coordinate (text-lane structure
-- law); a single-constituent coordinate collapses to the plane anchor (emb).
-- Uses attestations_relation_btree + consensus_object_type_btree.
DROP FUNCTION IF EXISTS laplace.model_circuit_slices(text, int, int);
CREATE OR REPLACE FUNCTION generation.model_circuit_slices(
    p_plane text,
    p_layer int DEFAULT NULL,
    p_head  int DEFAULT NULL)
    RETURNS TABLE(slice_id bytea, coord_id bytea)
    LANGUAGE sql STABLE ROWS 1
    AS $fn$
    WITH anchor AS (
        SELECT realize.canonical_id('substrate/entity/model/plane/' || p_plane || '/v1') AS id
    ),
    coord AS (
        SELECT CASE WHEN p_layer IS NULL THEN a.id ELSE lh.ctx END AS id
        FROM anchor a
        LEFT JOIN LATERAL (
            SELECT p1.context_id AS ctx
            FROM laplace.attestations p1
            WHERE p1.type_id = laplace.relation_type_id('PRECEDES')
              AND p1.subject_id = a.id
              AND p1.object_id = laplace.word_id(p_layer::text)
              AND (p_head IS NULL OR EXISTS (
                    SELECT 1 FROM laplace.attestations p2
                    WHERE p2.type_id = p1.type_id
                      AND p2.context_id = p1.context_id
                      AND p2.subject_id = laplace.word_id(p_layer::text)
                      AND p2.object_id = laplace.word_id(p_head::text)))
              AND (p_head IS NOT NULL OR NOT EXISTS (
                    SELECT 1 FROM laplace.attestations p3
                    WHERE p3.type_id = p1.type_id
                      AND p3.context_id = p1.context_id
                      AND p3.subject_id = laplace.word_id(p_layer::text)))
            -- (plane, layer, head) is expected to name ONE context, but nothing in
            -- the schema enforces it, and a partial or double model ingest produces
            -- two. Unordered the LIMIT returned whichever row the scan reached
            -- first, so the same call could answer differently across runs. The id
            -- is not a ranking -- it is the tie-break that makes the pick stable.
            ORDER BY p1.context_id
            LIMIT 1
        ) lh ON p_layer IS NOT NULL
        WHERE p_layer IS NULL OR lh.ctx IS NOT NULL
    )
    SELECT s.subject_id, coord.id
    FROM coord
    JOIN laplace.consensus s
      ON s.object_id = coord.id
     AND s.type_id = laplace.relation_type_id('APPEARS_IN')
    $fn$;

-- Gravity decomposition: dot = |q|·|k|·cosθ — mass × mass × alignment.
-- Norms come from self-scores; no extra native surface needed.
DROP FUNCTION IF EXISTS laplace.model_pair_cos(bytea, bytea, bytea, bytea, float8, float8, float8, float8);
CREATE OR REPLACE FUNCTION generation.model_pair_cos(
    p_q bytea, p_k bytea, p_a bytea, p_b bytea,
    OUT raw_dot float8, OUT cos_theta float8, OUT mass_q float8, OUT mass_k float8)
    LANGUAGE plpgsql STABLE AS $fn$
BEGIN
    raw_dot := generation.model_pair_score(p_q, p_k, p_a, p_b);
    mass_q  := sqrt(generation.model_pair_score(p_q, p_q, p_a, p_a));
    mass_k  := sqrt(generation.model_pair_score(p_k, p_k, p_b, p_b));
    cos_theta := raw_dot / NULLIF(mass_q * mass_k, 0);
END $fn$;

-- model_forward v0 (doc 26 B/D, first increment): the linearized single-token
-- forward as an indexed read. Native residual+unembed loop
-- (pg_laplace_model_forward); loops live in C. NO cross-position attention yet
-- — this composes emb + every layer's MLP write-vector for the token and
-- unembeds through the completion plane. Slices are content-addressed per
-- model, so the directory is resolved by source: the slice deposited BY this
-- source at each shared coordinate.
DROP FUNCTION IF EXISTS laplace.pg_laplace_model_forward(bytea, bytea[], bytea, bytea, int);
CREATE OR REPLACE FUNCTION generation.pg_laplace_model_forward(
    p_emb_slice  bytea,
    p_mlp_slices bytea[],
    p_lm_slice   bytea,
    p_tok        bytea,
    p_k          int)
    RETURNS TABLE(token bytea, score float8)
    AS 'laplace_substrate', 'pg_laplace_model_forward'
    -- STRICT: see model_pair_score. model_forward below feeds this from three
    -- scalar subqueries over the slice directory; a model with no APPEARS_IN
    -- rows makes all three NULL, which crashed the cluster before this.
    LANGUAGE C STABLE STRICT ROWS 20;

-- The everyday entry: forward a WORD through a MODEL (by source id) to its k
-- strongest next tokens, word laplace.entities out (joinable against the web).
--   SELECT realize.render_text(token), score FROM generation.model_forward(:src, 'France', 10);
DROP FUNCTION IF EXISTS laplace.model_forward(bytea, text, int);
CREATE OR REPLACE FUNCTION generation.model_forward(
    p_source bytea,
    p_word   text,
    p_k      int DEFAULT 20)
    RETURNS TABLE(token bytea, score float8)
    LANGUAGE plpgsql STABLE ROWS 20
    AS $fn$
DECLARE
    -- Hoisted: relation_type_id is STABLE, and the body referenced APPEARS_IN at
    -- five separate call sites (the guard plus emb/lm/mlp slice resolution). One
    -- resolution per call instead of five, and the vocabulary name is written once
    -- rather than repeated -- which is what G3 is counting.
    v_appears_in bytea := laplace.relation_type_id('APPEARS_IN');
BEGIN
    -- Slice resolution below keys ENTIRELY on APPEARS_IN. A model whose ingest
    -- deposited no APPEARS_IN rows resolves all three planes to NULL, and STRICT
    -- then makes this return the empty set — indistinguishable from "this word
    -- has no continuation". Name the real cause instead: the checkpoint is
    -- recorded but has no circuit anatomy, which is a missing pass, not a query bug.
    -- The default LAPLACE_MODEL_PLANES=structure pass records vocab, merges,
    -- TOKEN_MAPS_TO and CONTAINS/PRECEDES but emits NO APPEARS_IN; only the
    -- factors pass (ModelTokenEdgeETL.EmitFactorTrajectories, gated on RunFactors)
    -- deposits the slices this reads. So the remedy is the second pass, not a re-record.
    IF NOT EXISTS (SELECT 1 FROM laplace.attestations a
                   WHERE a.type_id = v_appears_in
                     AND a.source_id = p_source) THEN
        RAISE EXCEPTION
            'model % has no APPEARS_IN circuit slices — the checkpoint is recorded '
            'but its circuit anatomy was never deposited, so there is nothing to '
            'forward through. Run the analyzer pass over the recorded model: '
            'LAPLACE_MODEL_PLANES=factors laplace ingest model <snapshot-dir>',
            encode(p_source, 'hex')
            USING ERRCODE = 'no_data_found';
    END IF;

    RETURN QUERY
    WITH src_slice AS (
        -- The slice this source deposited at a given plane coordinate.
        SELECT s.slice_id, s.coord_id
        FROM generation.model_circuit_slices('emb') s
        WHERE EXISTS (SELECT 1 FROM laplace.attestations a
                      WHERE a.subject_id = s.slice_id
                        AND a.type_id = v_appears_in
                        AND a.source_id = p_source)
    ),
    -- One slice per (source, plane) is the ingest convention, not a constraint the
    -- schema holds; a re-ingest or a partial model seed leaves two. ORDER BY makes
    -- the pick reproducible instead of scan-order dependent. Same for lm below.
    emb AS (SELECT slice_id FROM src_slice ORDER BY slice_id LIMIT 1),
    lm AS (
        SELECT s.slice_id
        FROM generation.model_circuit_slices('lm') s
        WHERE EXISTS (SELECT 1 FROM laplace.attestations a
                      WHERE a.subject_id = s.slice_id
                        AND a.type_id = v_appears_in
                        AND a.source_id = p_source)
        ORDER BY s.slice_id
        LIMIT 1
    ),
    mlp AS (
        -- Every MLP write-vector slice this source deposited. The residual is a
        -- commutative sum over layers, so order is irrelevant; the slices are
        -- the source-deposited APPEARS_IN subjects at every coordinate that
        -- CONTAINS the mlp plane anchor (the per-layer mlp circuits).
        SELECT DISTINCT s.subject_id AS slice_id
        FROM laplace.attestations coord_has_plane
        JOIN laplace.consensus s
          ON s.object_id = coord_has_plane.subject_id
         AND s.type_id = v_appears_in
        WHERE coord_has_plane.type_id = laplace.relation_type_id('CONTAINS')
          AND coord_has_plane.object_id =
              realize.canonical_id('substrate/entity/model/plane/mlp/v1')
          AND EXISTS (SELECT 1 FROM laplace.attestations a
                      WHERE a.subject_id = s.subject_id
                        AND a.type_id = v_appears_in
                        AND a.source_id = p_source)
    )
    SELECT f.token, f.score
    FROM generation.pg_laplace_model_forward(
        (SELECT slice_id FROM emb),
        (SELECT array_agg(slice_id) FROM mlp),
        (SELECT slice_id FROM lm),
        laplace.word_id(p_word),
        p_k) f;
END $fn$;
-- Returns word laplace.entities + text, ready to JOIN against senses/consensus/web:
--   SELECT r.*, c.rating FROM generation.model_attention_row(2,9,'king',10) r
--   LEFT JOIN laplace.consensus c ON c.subject_id = r.token AND ...
DROP FUNCTION IF EXISTS laplace.model_attention_row(int, int, text, int);
CREATE OR REPLACE FUNCTION generation.model_attention_row(
    p_layer int,
    p_head  int,
    p_word  text,
    p_k     int DEFAULT 20)
    RETURNS TABLE(partner text, token bytea, score float8)
    LANGUAGE sql STABLE ROWS 20
    AS $fn$
    WITH ranked AS MATERIALIZED (
      SELECT t.token, t.score
      FROM generation.model_circuit_slices('qproj', p_layer, p_head) q,
         generation.model_circuit_slices('kproj', p_layer, p_head) k,
         LATERAL generation.model_row_topk(q.slice_id, k.slice_id, laplace.word_id(p_word), p_k) t
    ), ids AS MATERIALIZED (SELECT array_agg(token) AS a FROM ranked),
    rendered AS MATERIALIZED (
      SELECT i.id, i.txt
      FROM ids,
           LATERAL ROWS FROM (
             unnest(ids.a), unnest(realize.render_text_batch(ids.a))
           ) AS i(id, txt)
    )
    SELECT s.txt, t.token, t.score FROM ranked t JOIN rendered s ON s.id = t.token
    $fn$;
-- The model operator set, sourced from EVIDENCE rather than from stored floats.
--
-- WHY THIS FILE EXISTS. Every function in model_factor.sql.in reads the factor
-- trajectories: generation.model_pair_score and generation.model_row_topk take
-- p_q_slice/p_k_slice and scan a PostGIS varlena (~450 ms/call), and
-- generation.model_forward raises no_data_found telling the operator to run
-- LAPLACE_MODEL_PLANES=factors. That is the pass docs/plan/MODEL_INGESTION_DESIGN.md
-- Phase 7 deletes -- "No floats retained. No trajectories. Payload contribution:
-- 0 bytes." When it lands, that entire query surface stops answering, and nothing
-- replaced it.
--
-- These are the replacements. Same questions, different source:
--
--   question                        model_factor.sql.in        here
--   ------------------------------  -------------------------  --------------------
--   coupling of A,B in one circuit   scan two float slices      one attestations row
--   top-k partners in one circuit    native varlena top-k       index scan
--   what does the substrate believe  (not expressible)          consensus.eff_mu
--   next-token ranking               unembed through a slice    index scan
--
-- WHERE THE COORDINATE LIVES. laplace.consensus carries no context_id and no
-- source_id -- it is the FOLD, with the circuit coordinate folded out. So a
-- per-circuit read cannot come from consensus at any price; it must go through
-- laplace.attestations, which carries both. That split is the design rather than
-- a limitation: attestations are per-witness testimony (this model, this head),
-- consensus is what survived adjudication across all of them.
--
-- THE PROPERTY THE FLOAT SURFACE CANNOT HAVE. eff_mu = rating - 2*rd is a
-- conservative lower bound and is freely <= 0. An unattested pair returns NO ROW,
-- not an epsilon. A dense float tile has no way to express that: softmax is
-- nonzero for every input, so the "this pair couples with nothing" answer does
-- not exist in the representation. Here it is the absence of a row, which is also
-- why these are index probes instead of scans.

-- generation.circuit_coord -- resolve (plane, layer, head) to its context id.
--
-- Lifted out of generation.model_circuit_slices, whose coordinate resolution is
-- slice-free (plane anchor + PRECEDES attestations) while its final join is not.
-- The resolution survives Phase 7; the join does not. Everything below scopes by
-- this.
--
-- The ORDER BY is the tie-break, not a ranking: (plane, layer, head) is expected
-- to name one context and nothing in the schema enforces it, so a partial or
-- double ingest produces two and an unordered LIMIT would answer differently
-- across runs.
-- p_structure_relation is a parameter rather than a literal inside the
-- relation_type_id() call: G3 counts relation vocabulary spelled into the call
-- site, and the remedy used elsewhere in this directory is to name it once. Here
-- it is named once AND made overridable, which is the stricter form -- the
-- ordering relation that encodes circuit anatomy is a property of the ingest that
-- wrote it, not a constant of the substrate.
-- Dependents first: circuit_coupling/row/matrix are BEGIN ATOMIC and pin
-- circuit_coord's OID, so on a live upgrade the base cannot drop while they
-- stand (same RESTRICT shape metric_ladder hit; d1fa0245).
DROP FUNCTION IF EXISTS generation.circuit_coupling(bytea, bytea, text, integer, integer, text);
DROP FUNCTION IF EXISTS generation.circuit_row(bytea, text, integer, integer, integer, text);
DROP FUNCTION IF EXISTS generation.circuit_matrix(text, integer, integer, integer, text);
DROP FUNCTION IF EXISTS generation.circuit_coord(text, integer, integer);
DROP FUNCTION IF EXISTS generation.circuit_coord(text, integer, integer, text);
CREATE OR REPLACE FUNCTION generation.circuit_coord(
    p_plane text,
    p_layer integer DEFAULT NULL,
    p_head  integer DEFAULT NULL,
    p_structure_relation text DEFAULT 'PRECEDES')
RETURNS bytea
LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH anchor AS (
        SELECT realize.canonical_id('substrate/entity/model/plane/' || p_plane || '/v1') AS id
    ),
    resolved AS (
        SELECT CASE WHEN p_layer IS NULL THEN a.id ELSE lh.ctx END AS id
        FROM anchor a
        LEFT JOIN LATERAL (
            SELECT p1.context_id AS ctx
            FROM laplace.attestations p1
            WHERE p1.type_id = laplace.relation_type_id(p_structure_relation)
              AND p1.subject_id = a.id
              AND p1.object_id = laplace.word_id(p_layer::text)
              AND (p_head IS NULL OR EXISTS (
                    SELECT 1 FROM laplace.attestations p2
                    WHERE p2.type_id = p1.type_id
                      AND p2.context_id = p1.context_id
                      AND p2.subject_id = laplace.word_id(p_layer::text)
                      AND p2.object_id = laplace.word_id(p_head::text)))
              AND (p_head IS NOT NULL OR NOT EXISTS (
                    SELECT 1 FROM laplace.attestations p3
                    WHERE p3.type_id = p1.type_id
                      AND p3.context_id = p1.context_id
                      AND p3.subject_id = laplace.word_id(p_layer::text)))
            ORDER BY p1.context_id
            LIMIT 1
        ) lh ON p_layer IS NOT NULL
        WHERE p_layer IS NULL OR lh.ctx IS NOT NULL
    )
    SELECT resolved.id FROM resolved;
END;

COMMENT ON FUNCTION generation.circuit_coord(text, integer, integer, text) IS
    'Context id for one circuit (plane, layer, head), resolved from plane anchors '
    'and PRECEDES. Survives the factor-payload deletion; scopes every per-circuit read.';


-- generation.circuit_coupling -- one entry of one circuit's matrix.
--
-- The QK/OV analogue of generation.model_pair_score, without the slices. Returns
-- the mean magnitude this witness deposited for the pair in this circuit:
-- sum_score_fp1e9 / observation_count, on the 1e9 fixed-point scale the fold
-- uses. NULL means the pair was never attested here -- which is an answer, not a
-- missing value.
--
-- p_relation is a parameter rather than a hardcoded 'ATTENDS' because the same
-- shape serves both halves of a head: QK is which tokens couple, OV is what gets
-- written, and per Elhage et al. those are the only two observable objects in an
-- attention head. Naming one of them in the body would make the other
-- unreachable through this surface.
DROP FUNCTION IF EXISTS generation.circuit_coupling(bytea, bytea, text, integer, integer, text);
CREATE OR REPLACE FUNCTION generation.circuit_coupling(
    p_subject  bytea,
    p_object   bytea,
    p_plane    text,
    p_layer    integer DEFAULT NULL,
    p_head     integer DEFAULT NULL,
    p_relation text    DEFAULT 'ATTENDS')
RETURNS double precision
LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT (a.sum_score_fp1e9::double precision / NULLIF(a.observation_count, 0)) / 1e9
    FROM laplace.attestations a
    WHERE a.subject_id = p_subject
      AND a.object_id  = p_object
      AND a.type_id    = laplace.relation_type_id(p_relation)
      AND a.context_id = generation.circuit_coord(p_plane, p_layer, p_head);
END;

COMMENT ON FUNCTION generation.circuit_coupling(bytea, bytea, text, integer, integer, text) IS
    'One entry of one circuit''s coupling matrix, from attestations. NULL = never '
    'attested in this circuit, which is an answer rather than a missing value.';


-- generation.circuit_row -- one row of one circuit's matrix, top-k.
--
-- The analogue of generation.model_row_topk. Bounded by the attested partners of
-- this subject in this circuit, not by V.
DROP FUNCTION IF EXISTS generation.circuit_row(bytea, text, integer, integer, integer, text);
CREATE OR REPLACE FUNCTION generation.circuit_row(
    p_subject  bytea,
    p_plane    text,
    p_layer    integer DEFAULT NULL,
    p_head     integer DEFAULT NULL,
    p_k        integer DEFAULT 20,
    p_relation text    DEFAULT 'ATTENDS')
RETURNS TABLE(partner bytea, magnitude double precision, observations bigint)
LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT a.object_id,
           (a.sum_score_fp1e9::double precision / NULLIF(a.observation_count, 0)) / 1e9,
           a.observation_count
    FROM laplace.attestations a
    WHERE a.subject_id = p_subject
      AND a.type_id    = laplace.relation_type_id(p_relation)
      AND a.context_id = generation.circuit_coord(p_plane, p_layer, p_head)
    ORDER BY (a.sum_score_fp1e9::double precision / NULLIF(a.observation_count, 0)) DESC,
             a.object_id
    LIMIT p_k;
END;

COMMENT ON FUNCTION generation.circuit_row(bytea, text, integer, integer, integer, text) IS
    'Top-k partners of one token inside one circuit, from attestations. Bounded by '
    'attested partners rather than by vocabulary size.';


-- generation.circuit_matrix -- one circuit's whole sparse matrix, COO.
--
-- The direct analogue of a contraction tile: (row, col, value) triplets. What a
-- dense tile materialises as V*V floats is here exactly the attested entries and
-- nothing else, which is the same asymmetry Wanda measures from the other side --
-- half a checkpoint's weights are removable with no measured loss, and softmax
-- cannot express the removal.
DROP FUNCTION IF EXISTS generation.circuit_matrix(text, integer, integer, integer, text);
CREATE OR REPLACE FUNCTION generation.circuit_matrix(
    p_plane    text,
    p_layer    integer DEFAULT NULL,
    p_head     integer DEFAULT NULL,
    p_limit    integer DEFAULT 10000,
    p_relation text    DEFAULT 'ATTENDS')
RETURNS TABLE(subject bytea, object bytea, magnitude double precision)
LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT a.subject_id, a.object_id,
           (a.sum_score_fp1e9::double precision / NULLIF(a.observation_count, 0)) / 1e9
    FROM laplace.attestations a
    WHERE a.type_id    = laplace.relation_type_id(p_relation)
      AND a.context_id = generation.circuit_coord(p_plane, p_layer, p_head)
    ORDER BY a.subject_id, a.object_id
    LIMIT p_limit;
END;

COMMENT ON FUNCTION generation.circuit_matrix(text, integer, integer, integer, text) IS
    'One circuit''s coupling matrix as COO triplets. The sparse counterpart of a '
    'dense contraction tile -- only attested entries exist.';


-- generation.adjudicated_coupling -- what the SUBSTRATE believes, not one witness.
--
-- No counterpart exists in the float surface, and cannot: laplace.consensus is
-- the fold across every source and circuit, and a stored float tile has no
-- notion of a claim that lost. eff_mu = rating - 2*rd is the conservative lower
-- bound, freely <= 0.
DROP FUNCTION IF EXISTS generation.adjudicated_coupling(bytea, bytea, text);
CREATE OR REPLACE FUNCTION generation.adjudicated_coupling(
    p_subject  bytea,
    p_object   bytea,
    p_relation text DEFAULT 'ATTENDS')
RETURNS TABLE(eff_mu bigint, rating bigint, rd bigint, witness_count bigint)
LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT consensus.eff_mu(c.rating, c.rd), c.rating, c.rd, c.witness_count
    FROM laplace.consensus c
    WHERE c.subject_id = p_subject
      AND c.object_id  = p_object
      AND c.type_id    = laplace.relation_type_id(p_relation);
END;

COMMENT ON FUNCTION generation.adjudicated_coupling(bytea, bytea, text) IS
    'The folded belief for one pair across every witness, with its uncertainty. '
    'No row = unattested by anything, which the float surface cannot represent.';


-- generation.adjudicated_row -- the ranked query the softmax layer approximates.
--
-- The softmax output layer is equivalent to maximum inner product search: the
-- context vector is the query and the vocabulary embeddings are the database.
-- This is that query, answered exactly instead of approximately, ordered by
-- evidence rather than by dot product, and able to return the EMPTY SET when the
-- subject couples to nothing under this relation.
--
-- Rides consensus_subject_type_eff_mu_btree, so it is a bounded index scan and
-- not a scan of V.
DROP FUNCTION IF EXISTS generation.adjudicated_row(bytea, integer, text);
CREATE OR REPLACE FUNCTION generation.adjudicated_row(
    p_subject  bytea,
    p_k        integer DEFAULT 20,
    p_relation text    DEFAULT 'ATTENDS')
RETURNS TABLE(object bytea, eff_mu bigint, rd bigint, witness_count bigint)
LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT c.object_id, consensus.eff_mu(c.rating, c.rd), c.rd, c.witness_count
    FROM laplace.consensus c
    WHERE c.subject_id = p_subject
      AND c.type_id    = laplace.relation_type_id(p_relation)
    ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id
    LIMIT p_k;
END;

COMMENT ON FUNCTION generation.adjudicated_row(bytea, integer, text) IS
    'Top-k by adjudicated evidence -- the exact, abstaining counterpart of the '
    'softmax output layer''s maximum-inner-product search over the vocabulary.';
-- Full population of entities.highway_mask via highway_mask_refresh, batched with a
-- COMMIT per batch (10M+ entities in one tx would bloat and lock). This is the
-- REGENERATE tool: run after any highway bit renumbering (adding a relation reorders
-- the alphabetical codegen) or to populate a generation seeded before the fold-time
-- refresh existed. Idempotent; safe to re-run and to interrupt (committed batches
-- persist).
--
-- SCAN SET (2026-07-21): drive the batches from the CANDIDATE set, not from every
-- entity. highway_mask_refresh derives a mask purely from laplace.consensus participation, so
-- an entity that appears in no consensus row can only ever resolve to NULL -- which is
-- already its stored value. The old loop walked all ~9M entities, paying two indexed
-- consensus probes each, and the ~7M tier-3/4 content rows were guaranteed no-ops.
-- Candidates are therefore:
--   (a) consensus participants (subject or object)  -- may gain or change a mask
--   (b) entities with a non-NULL mask today         -- may need one CLEARED after a
--       per-source evict removed their last governed edge
-- (b) keeps the "recompute-not-accumulate: idempotent, self-healing, no drift"
-- guarantee that a participants-only scan would quietly break, and costs one
-- sequential pass instead of the previous ~18 batched join passes.
--
-- PROGRESS (2026-07-21): RAISE LOG, not RAISE NOTICE. NOTICE is client-only -- with
-- log_min_messages at its WARNING default the old NOTICEs reached the server log
-- never, and any client that discards notices (the ingest writer does) made a
-- multi-minute rebuild look like a dead stall. LOG is the substrate law for
-- long-running folds: always emit LOG progress.
--
-- No SET clause on the procedure: a PL/pgSQL procedure carrying a SET clause is
-- barred from transaction control (COMMIT), so references are schema-qualified
-- instead. Invoke with: CALL laplace.highway_mask_rebuild();
DROP PROCEDURE IF EXISTS laplace.highway_mask_rebuild(int);

CREATE OR REPLACE PROCEDURE laplace.highway_mask_rebuild(p_batch int DEFAULT 500000)
    LANGUAGE plpgsql AS $$
DECLARE
    last_id bytea := decode(repeat('00', 16), 'hex');
    ids bytea[];
    n bigint;
    total bigint := 0;
    scanned bigint := 0;
    candidates bigint;
    t0 timestamptz := clock_timestamp();
BEGIN
    -- Plain TEMP table (ON COMMIT PRESERVE ROWS): the per-batch COMMIT below would
    -- drop an ON COMMIT DROP table out from under the loop.
    DROP TABLE IF EXISTS _hmr_candidates;
    CREATE TEMP TABLE _hmr_candidates (id bytea PRIMARY KEY);

    INSERT INTO _hmr_candidates (id)
    SELECT c.subject_id FROM laplace.consensus c
    UNION
    SELECT c.object_id  FROM laplace.consensus c WHERE c.object_id IS NOT NULL
    UNION
    SELECT e.id FROM laplace.entities e WHERE e.highway_mask IS NOT NULL;
    GET DIAGNOSTICS candidates = ROW_COUNT;

    RAISE LOG 'highway_mask_rebuild: start — % mask candidates (consensus participants + already-masked)',
        candidates;
    COMMIT;

    LOOP
        SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM (
            SELECT id FROM _hmr_candidates WHERE id > last_id ORDER BY id LIMIT p_batch) s;
        EXIT WHEN ids IS NULL;
        n := consensus.highway_mask_refresh(ids);
        total := total + n;
        scanned := scanned + cardinality(ids);
        last_id := ids[cardinality(ids)];
        RAISE LOG 'highway_mask_rebuild: % masks written / % of % candidates (% percent) — %s elapsed',
            total, scanned, candidates,
            round(100.0 * scanned / NULLIF(candidates, 0), 1),
            round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
        COMMIT;
    END LOOP;

    RAISE LOG 'highway_mask_rebuild: done — % masks written / % candidates in %s',
        total, scanned, round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
    DROP TABLE IF EXISTS _hmr_candidates;
END $$;
-- evict_source: lawful retraction + refold of one SOURCE's testimony (GH #508).
--
-- The evictable unit is the source. Attestation rows carry no version and their
-- context slot is provenance; versions never coexist (markers gate each lane to one
-- derivation), so "evict version v" and "evict the source's testimony" are the same
-- operation — eviction IS the version transition: evict, then re-run the lane at
-- Version=N+1 and the hydrator re-derives everything the deleted markers gated.
--
-- Steps, per relation-type partition, per batch (one transaction each, COMMIT +
-- RAISE LOG progress — modeled on highway_mask_rebuild / highway_mask_drain):
--
--   (a) DELETE the source's evidence rows under the relation (LIST partition pruned
--       via a literal type in EXECUTE — a variable type plans generically and opens
--       every leaf, the attestation_merge lesson), RETURNING the touched cells and
--       the touched entity ids.
--   (b) REFOLD every touched cell in place from its SURVIVING evidence through the
--       consensus_fold AGGREGATE — the SQL surface of the same native scalar the
--       ingest fold runs (glicko2_fold_uniform_period), seeded from the neutral
--       prior, one uniform period per surviving row using the persisted fold inputs
--       (opponent_rd_fp1e9 / observation_count / sum_score_fp1e9), in the canonical
--       order (last_observed_at, id). Bit-parity with the incremental history is not
--       the contract (batch boundaries are not recoverable); the canonical fold of
--       the surviving evidence is.
--   (c) Cells with ZERO surviving evidence are DELETED, never zeroed — unattested is
--       not attested-false (the #688/#689 law); a consensus row with no witnesses is
--       a claim nobody makes.
--   (d) Touched entity ids queue into laplace.highway_mask_dirty — the CLEAR case the queue
--       exists for (deposit only OR-accumulates; eviction can remove an entity's
--       last governed edge) — and drain via highway_mask_drain (p_drain), whose
--       refresh recomputes masks from scratch and can therefore clear bits.
--   (e) The source's MARKER entities (p_marker_types, first_observed_by = source)
--       are deleted along with their physicality rows, so the lane's bitmap probe
--       re-yields every unit at the next run. Content entities are NEVER deleted —
--       content the lane minted (positions, tokens, scalars) is valid shared
--       content under the identity law. Physicalities carry no source attribution
--       by design (geometry is content identity, not testimony): a trajectory
--       linestring is a pure deterministic function of its entity's constituents,
--       stays byte-correct across versions, and re-derivation re-deposits it
--       idempotently — there is nothing epistemic to retract there.
--
-- p_relations NULL = every relation the source has rows under, discovered by one
-- indexed LIMIT-1 probe per leaf partition (plus a DISTINCT scan of the source's
-- rows in the DEFAULT partition, where dynamic relations coexist). Passing the
-- lane's declared relations skips discovery entirely.
--
-- Eviction on a source with zero rows is a NO-OP, not an error (the unseeded law).
-- Idempotent and resumable: every batch commits a consistent snapshot (evidence
-- deleted + its cells refolded in the same transaction), so an interrupted run
-- re-run to completion leaves exactly the state a single run would have.
--
-- No SET clause: a PL/pgSQL procedure carrying one is barred from transaction
-- control (COMMIT), so references are schema-qualified instead.
-- Invoke with: CALL ops.evict_source(laplace.source_id('ChessAnalysis'));
DROP PROCEDURE IF EXISTS laplace.evict_source(bytea, bytea[], bytea[], int, boolean);

CREATE OR REPLACE PROCEDURE ops.evict_source(
    p_source       bytea,
    p_relations    bytea[] DEFAULT NULL,
    p_marker_types bytea[] DEFAULT NULL,
    p_batch        int     DEFAULT 100000,
    p_drain        boolean DEFAULT true)
    LANGUAGE plpgsql AS $$
DECLARE
    rels           bytea[];
    rel            bytea;
    leaf           oid;
    leaf_types     bytea[];
    t              bytea;
    n_del          bigint;
    n_cells        bigint;
    n              bigint;
    evidence_total bigint := 0;
    refold_total   bigint := 0;
    culled_total   bigint := 0;
    marker_total   bigint := 0;
    file_marker_total bigint := 0;
    replay_total   bigint := 0;
    t0             timestamptz := clock_timestamp();
BEGIN
    -- Plain TEMP table (per-batch COMMIT would drop ON COMMIT DROP); TRUNCATE per
    -- batch. IF NOT EXISTS + explicit DROP at the end keeps DROP-NOTICE noise out
    -- of client output.
    CREATE TEMP TABLE IF NOT EXISTS _evict_cells (
        subject_id bytea NOT NULL,
        object_id  bytea,
        consensus_leaf oid NOT NULL,
        UNIQUE NULLS NOT DISTINCT (subject_id, object_id));
    TRUNCATE _evict_cells;
    -- A backend may retain the pre-routing temp-table shape across an extension
    -- update. Upgrade that shape once without emitting an IF NOT EXISTS notice
    -- on every ordinary call in the same session.
    IF NOT EXISTS (
        SELECT 1
        FROM pg_attribute a
        WHERE a.attrelid = 'pg_temp._evict_cells'::regclass
          AND a.attname = 'consensus_leaf'
          AND NOT a.attisdropped
    ) THEN
        ALTER TABLE _evict_cells ADD COLUMN consensus_leaf oid;
    END IF;
    ALTER TABLE _evict_cells
        ALTER COLUMN consensus_leaf SET NOT NULL;
    CREATE INDEX IF NOT EXISTS _evict_cells_leaf_idx
        ON _evict_cells (consensus_leaf);

    -- File checkpoints are keyed by file identity, not the decomposer source. The
    -- ingest journals are the ownership edge source eviction uses to find them.
    -- context_id is the vendor owner on new markers; NULL admits legacy markers.
    CREATE TEMP TABLE IF NOT EXISTS _evict_file_markers (
        file_source_id bytea NOT NULL,
        marker_type_id bytea NOT NULL,
        owner_source_id bytea NOT NULL,
        PRIMARY KEY (file_source_id, marker_type_id, owner_source_id));
    TRUNCATE _evict_file_markers;
    INSERT INTO _evict_file_markers
        (file_source_id, marker_type_id, owner_source_id)
    SELECT DISTINCT f.file_id,
           realize.canonical_id(
               'substrate/type/HasLayerCompleted/' || r.layer::text || '/v1'),
           r.source_id
    FROM laplace.ingest_run_journal r
    JOIN laplace.ingest_file_journal f ON f.run_id = r.run_id
    WHERE r.source_id = p_source AND f.file_id IS NOT NULL;

    IF p_relations IS NOT NULL THEN
        rels := p_relations;
    ELSE
        -- Discover the source's relations: one indexed LIMIT-1 probe per leaf in
        -- a named relation subtree (every such subtree holds exactly one type),
        -- DISTINCT inside every leaf descended from the DEFAULT partition
        -- (dynamic relations share its hash leaves). Checking only a leaf's own
        -- bound is wrong because the DEFAULT partition is itself subpartitioned:
        -- its leaves have HASH bounds, not the ancestor's DEFAULT bound.
        rels := ARRAY[]::bytea[];
        FOR leaf IN
            SELECT pt.relid
            FROM pg_extension e
            JOIN pg_namespace ns ON ns.oid = e.extnamespace
            CROSS JOIN LATERAL pg_partition_tree(
                (quote_ident(ns.nspname) || '.attestations')::regclass) pt
            WHERE e.extname = 'laplace_substrate' AND pt.isleaf
        LOOP
            IF EXISTS (
                SELECT 1
                FROM pg_partition_ancestors(leaf::regclass) pa
                JOIN pg_class c ON c.oid = pa.relid
                WHERE pg_get_expr(c.relpartbound, c.oid) = 'DEFAULT'
            ) THEN
                EXECUTE format(
                    'SELECT COALESCE(array_agg(DISTINCT a.type_id), ARRAY[]::bytea[]) '
                    'FROM %s a WHERE a.source_id = $1', leaf::regclass)
                INTO leaf_types USING p_source;
            ELSE
                EXECUTE format(
                    'SELECT ARRAY(SELECT a.type_id FROM %s a WHERE a.source_id = $1 LIMIT 1)',
                    leaf::regclass)
                INTO leaf_types USING p_source;
            END IF;
            FOREACH t IN ARRAY leaf_types LOOP
                IF NOT (t = ANY(rels)) THEN
                    rels := rels || t;
                END IF;
            END LOOP;
        END LOOP;
    END IF;

    RAISE LOG 'evict_source: start — source %, % relation(s)',
        encode(p_source, 'hex'), COALESCE(cardinality(rels), 0);

    -- Deleting a source followed by score replay is invalid for a cell carrying
    -- a transient-calibration receipt: the numeric model score was intentionally
    -- never persisted.  Refuse before the first DELETE rather than retaining a
    -- stale consensus value or fabricating a categorical replacement.
    IF EXISTS (
        SELECT 1
        FROM laplace.attestations source_evidence
        JOIN laplace.attestations transient_evidence
          ON transient_evidence.type_id = source_evidence.type_id
         AND transient_evidence.subject_id = source_evidence.subject_id
         AND transient_evidence.object_id IS NOT DISTINCT FROM source_evidence.object_id
        WHERE source_evidence.source_id = p_source
          AND transient_evidence.fold_replayable = false
    ) THEN
        RAISE EXCEPTION 'evict_source: source % touches transient-calibration evidence; no score replay exists',
            encode(p_source, 'hex');
    END IF;

    FOREACH rel IN ARRAY COALESCE(rels, ARRAY[]::bytea[]) LOOP
        LOOP
            TRUNCATE _evict_cells;

            -- (a) delete one batch of the source's evidence under this relation;
            --     queue every touched entity for mask repair; accumulate the
            --     touched cells for the refold below.
            EXECUTE format($q$
                WITH pick AS (
                    SELECT a.id, a.subject_id
                    FROM laplace.attestations a
                    WHERE a.type_id = %L::bytea AND a.source_id = $1
                    LIMIT %s),
                del AS (
                    DELETE FROM laplace.attestations a
                    USING pick
                    WHERE a.type_id = %L::bytea
                      AND a.id = pick.id AND a.subject_id = pick.subject_id
                    RETURNING a.subject_id, a.object_id),
                dirty AS (
                    INSERT INTO laplace.highway_mask_dirty (id)
                    SELECT DISTINCT u.id
                    FROM (SELECT d.subject_id AS id FROM del d
                          UNION
                          SELECT d.object_id FROM del d WHERE d.object_id IS NOT NULL) u
                    ON CONFLICT (id) DO NOTHING),
                cells AS (
                    INSERT INTO _evict_cells (subject_id, object_id, consensus_leaf)
                    SELECT DISTINCT d.subject_id, d.object_id,
                           consensus.partition_leaf(%L::bytea, d.subject_id)::oid
                    FROM del d
                    ON CONFLICT DO NOTHING
                    RETURNING 1)
                SELECT (SELECT count(*) FROM del), (SELECT count(*) FROM cells)
            $q$, rel, p_batch, rel, rel)
            INTO n_del, n_cells
            USING p_source;

            EXIT WHEN n_del = 0;
            evidence_total := evidence_total + n_del;

            -- (b) refold each touched cell in place from surviving evidence:
            --     one uniform period per surviving row, canonical order
            --     (last_observed_at, id), neutral-prior seed — the consensus_fold
            --     aggregate is the SQL surface of the ingest fold's native scalar.
            EXECUTE format($q$
                INSERT INTO laplace.consensus AS c
                    (id, subject_id, type_id, object_id,
                     rating, rd, volatility, witness_count, last_observed_at)
                SELECT laplace.consensus_id(f.subject_id, %L::bytea, f.object_id),
                       f.subject_id, %L::bytea, f.object_id,
                       (f.acc).rating, (f.acc).rd, (f.acc).volatility,
                       (f.acc).witness_count, f.last_ts
                FROM (
                    SELECT t.subject_id, t.object_id,
                           laplace.consensus_fold(false, NULL, NULL, NULL,
                               a.opponent_rating_fp1e9,
                               a.opponent_rd_fp1e9,
                               GREATEST(a.observation_count, 1),
                               a.sum_score_fp1e9,
                               consensus.glicko2_tau()
                               ORDER BY a.last_observed_at, a.id) AS acc,
                           max(a.last_observed_at) AS last_ts
                    FROM _evict_cells t
                    JOIN laplace.attestations a
                      ON a.type_id = %L::bytea
                     AND a.subject_id = t.subject_id
                     AND a.object_id IS NOT DISTINCT FROM t.object_id
                    GROUP BY t.subject_id, t.object_id
                ) f
                ON CONFLICT (id, type_id, subject_id) DO UPDATE
                SET object_id        = EXCLUDED.object_id,
                    rating           = EXCLUDED.rating,
                    rd               = EXCLUDED.rd,
                    volatility       = EXCLUDED.volatility,
                    witness_count    = EXCLUDED.witness_count,
                    last_observed_at = EXCLUDED.last_observed_at
            $q$, rel, rel, rel);
            GET DIAGNOSTICS n = ROW_COUNT;
            refold_total := refold_total + n;

            -- (c) zero-survivor cells are DELETED, not zeroed.
            FOR leaf IN
                SELECT DISTINCT consensus_leaf FROM _evict_cells
            LOOP
                EXECUTE format($q$
                    DELETE FROM ONLY %s c
                    USING _evict_cells t
                    WHERE t.consensus_leaf = %s::oid
                      AND c.type_id = %L::bytea
                      AND c.subject_id = t.subject_id
                      AND c.id = laplace.consensus_id(t.subject_id, %L::bytea, t.object_id)
                      AND NOT EXISTS (
                          SELECT 1 FROM laplace.attestations a
                          WHERE a.type_id = %L::bytea
                            AND a.subject_id = t.subject_id
                            AND a.object_id IS NOT DISTINCT FROM t.object_id)
                $q$, leaf::regclass, leaf, rel, rel, rel);
                GET DIAGNOSTICS n = ROW_COUNT;
                culled_total := culled_total + n;
            END LOOP;

            RAISE LOG 'evict_source: relation % — batch of % evidence row(s) over % cell(s) (running: % deleted, % refolded, % culled) — %s elapsed',
                encode(rel, 'hex'), n_del, n_cells,
                evidence_total, refold_total, culled_total,
                round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
            COMMIT;
        END LOOP;
    END LOOP;

    -- Per-file completion attestations are ops markers and never enter consensus, so
    -- retracting them needs no refold. The literal type keeps LIST pruning intact.
    FOR rel IN SELECT DISTINCT marker_type_id FROM _evict_file_markers LOOP
        LOOP
            EXECUTE format($q$
                WITH pick AS (
                    SELECT a.id, a.subject_id
                    FROM laplace.attestations a
                    JOIN _evict_file_markers m
                      ON m.marker_type_id = %L::bytea
                     AND m.file_source_id = a.source_id
                     AND (a.context_id = m.owner_source_id OR a.context_id IS NULL)
                    WHERE a.type_id = %L::bytea
                    LIMIT %s),
                del AS (
                    DELETE FROM laplace.attestations a
                    USING pick
                    WHERE a.type_id = %L::bytea
                      AND a.id = pick.id AND a.subject_id = pick.subject_id
                    RETURNING 1)
                SELECT count(*) FROM del
            $q$, rel, rel, p_batch, rel)
            INTO n;

            EXIT WHEN n = 0;
            file_marker_total := file_marker_total + n;
            RAISE LOG 'evict_source: % file checkpoint(s) deleted (running %) — %s elapsed',
                n, file_marker_total,
                round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
            COMMIT;
        END LOOP;
    END LOOP;

    -- (e) marker entities: the lane's derivation gates. Deleting them re-opens every
    -- unit for the hydrator's bitmap probe. first_observed_by scopes to this source;
    -- p_marker_types scopes to gate entities only — content entities never qualify.
    IF p_marker_types IS NOT NULL AND cardinality(p_marker_types) > 0 THEN
        LOOP
            WITH pick AS (
                SELECT e.id, e.tier
                FROM laplace.entities e
                WHERE e.type_id = ANY(p_marker_types)
                  AND e.first_observed_by = p_source
                LIMIT p_batch),
            del AS (
                DELETE FROM laplace.entities e
                USING pick
                WHERE e.id = pick.id AND e.tier = pick.tier
                RETURNING e.id),
            phys AS (
                DELETE FROM laplace.physicalities p
                USING del
                WHERE p.entity_id = del.id)
            SELECT count(*) INTO n FROM del;

            EXIT WHEN n = 0;
            marker_total := marker_total + n;
            RAISE LOG 'evict_source: % marker(s) deleted (running %) — %s elapsed',
                n, marker_total,
                round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
            COMMIT;
        END LOOP;
    END IF;

    -- Replay claims are applied source state. Keeping them after retraction makes a
    -- deterministic re-derive silently no-op. Historical NULL-owned rows cannot be
    -- attributed safely and intentionally remain untouched.
    DELETE FROM laplace.ingest_flush_journal receipt
    WHERE receipt.source_id = p_source
       OR EXISTS (
           SELECT 1
           FROM laplace.ingest_flush_journal_sources owner
           WHERE owner.working_set_id = receipt.working_set_id
             AND owner.source_id = p_source);
    GET DIAGNOSTICS replay_total = ROW_COUNT;
    IF replay_total > 0 THEN COMMIT; END IF;

    -- (d) drain the mask-repair queue through the existing machinery (refresh
    -- recomputes from scratch and can CLEAR bits deposit could only OR on).
    IF p_drain THEN
        CALL laplace.highway_mask_drain(p_batch);
    END IF;

    RAISE LOG 'evict_source: done — source %: % evidence row(s) deleted, % cell(s) refolded, % cell(s) culled, % marker(s) removed, % file checkpoint(s) removed, % replay claim(s) removed in %s',
        encode(p_source, 'hex'), evidence_total, refold_total, culled_total,
        marker_total, file_marker_total, replay_total,
        round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);

    DROP TABLE _evict_cells;
    DROP TABLE _evict_file_markers;
END $$;
-- ops.refold_source — the NON-DESTRUCTIVE half of evict_source (GH #1176).
--
-- THE INCIDENT THIS REPAIRS, measured 2026-08-21: the conceptnet ingest (run
-- 32502815485) applied all 651 units and then died mid-fold on pool exhaustion
-- (#1271). The ledger says applied; the folds never drained. Result: relation
-- aa43543b… holds 163,585 attestations but 28,793 consensus rows; 3d5f97dc…
-- 108,863 vs 66,789 — lanes whose folds finished are exact. Per-file resume
-- true-skips the files (their HasLayerCompleted markers exist), so re-running
-- repairs nothing, and until this procedure existed the ONLY recovery was
-- evict + full re-ingest: destroying 963,549 evidence rows to rebuild rows
-- that are all still present.
--
-- Consensus is DERIVED state: every cell is exactly the consensus_fold of its
-- surviving attestations. evict_source already proves it — its step (b) refolds
-- every touched cell in place after deleting testimony. This is the complete
-- rebuild form of that arm with NOTHING deleted: enumerate the cells the source's
-- testimony touches, refold each from ALL evidence, one uniform period, canonical
-- order (last_observed_at, id), neutral-prior seed, and UPSERT the derived row.
-- The INSERT half matters: an interrupted first fold can leave durable evidence
-- with no consensus row at all, and UPDATE-only repair cannot reconstruct it.
-- Idempotent by construction — a second run recomputes identical values. Touches
-- only laplace.consensus rows whose evidence justifies them; never mutates evidence.
--
-- Batched COMMITs exactly like evict_source, so a canceled repair keeps every
-- relation already refolded. No SET clause (a procedure carrying one may not
-- COMMIT); references schema-qualified instead — the ops.evict_source rule.
--
-- Run (operator, via the measurement lane like evict):
--   CALL ops.refold_source('ConceptNetDecomposer');
DROP PROCEDURE IF EXISTS ops.refold_source(text, boolean);

CREATE OR REPLACE PROCEDURE ops.refold_source(
    p_source_name text,
    p_dry_run     boolean DEFAULT false)
    LANGUAGE plpgsql AS $$
DECLARE
    src            bytea;
    rels           bytea[];
    rel            bytea;
    n_cells        bigint;
    n              bigint;
    refold_total   bigint := 0;
    t0             timestamptz := clock_timestamp();
BEGIN
    src := laplace.source_id(p_source_name);
    IF src IS NULL THEN
        RAISE EXCEPTION 'refold_source: unknown source %', p_source_name;
    END IF;

    -- A transient-calibration receipt has already consumed its continuous
    -- native score inside the original atomic write.  It is durable provenance,
    -- not a replayable fold input; rebuilding a cell from its categorical
    -- receipt would silently replace the original model result with 0/½/1.
    IF EXISTS (
        SELECT 1
        FROM laplace.attestations source_evidence
        JOIN laplace.attestations transient_evidence
          ON transient_evidence.type_id = source_evidence.type_id
         AND transient_evidence.subject_id = source_evidence.subject_id
         AND transient_evidence.object_id IS NOT DISTINCT FROM source_evidence.object_id
        WHERE source_evidence.source_id = src
          AND transient_evidence.fold_replayable = false
    ) THEN
        RAISE EXCEPTION 'refold_source: source % touches transient-calibration evidence; no score replay exists',
            p_source_name;
    END IF;

    SELECT array_agg(DISTINCT a.type_id) INTO rels
    FROM laplace.attestations a WHERE a.source_id = src;
    IF rels IS NULL THEN
        RAISE LOG 'refold_source: % has no testimony — nothing to refold', p_source_name;
        RETURN;
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS _refold_cells (
        subject_id bytea NOT NULL,
        object_id  bytea,
        UNIQUE NULLS NOT DISTINCT (subject_id, object_id));

    FOREACH rel IN ARRAY rels LOOP
        TRUNCATE _refold_cells;
        EXECUTE format($q$
            INSERT INTO _refold_cells (subject_id, object_id)
            SELECT DISTINCT a.subject_id, a.object_id
            FROM laplace.attestations a
            WHERE a.source_id = %L::bytea AND a.type_id = %L::bytea
            ON CONFLICT DO NOTHING
        $q$, src, rel);
        GET DIAGNOSTICS n_cells = ROW_COUNT;

        IF p_dry_run THEN
            RAISE LOG 'refold_source: WOULD refold % cell(s) of relation %',
                n_cells, encode(rel, 'hex');
            CONTINUE;
        END IF;

        -- Total reconstruction from evidence, not update-in-place. A source can
        -- have committed attestations before the first consensus insert for a cell
        -- (#1349/#1292), so the recovery primitive must materialize missing derived
        -- rows as well as replace stale ones. Identity stays canonical and the
        -- partitioned-table conflict target is the declared consensus PK.
        EXECUTE format($q$
            INSERT INTO laplace.consensus
                (id, subject_id, type_id, object_id,
                 rating, rd, volatility, witness_count, last_observed_at)
            SELECT laplace.consensus_id(f.subject_id, %L::bytea, f.object_id),
                   f.subject_id, %L::bytea, f.object_id,
                   (f.acc).rating, (f.acc).rd, (f.acc).volatility,
                   (f.acc).witness_count, f.last_ts
            FROM (
                SELECT t.subject_id, t.object_id,
                       laplace.consensus_fold(false, NULL, NULL, NULL,
                           a.opponent_rating_fp1e9,
                           a.opponent_rd_fp1e9,
                           GREATEST(a.observation_count, 1),
                           a.sum_score_fp1e9,
                           consensus.glicko2_tau()
                           ORDER BY a.last_observed_at, a.id) AS acc,
                       max(a.last_observed_at) AS last_ts
                FROM _refold_cells t
                JOIN laplace.attestations a
                  ON a.type_id = %L::bytea
                 AND a.subject_id = t.subject_id
                 AND a.object_id IS NOT DISTINCT FROM t.object_id
                GROUP BY t.subject_id, t.object_id
            ) f
            ON CONFLICT (id, type_id, subject_id) DO UPDATE
            SET object_id        = EXCLUDED.object_id,
                rating           = EXCLUDED.rating,
                rd               = EXCLUDED.rd,
                volatility       = EXCLUDED.volatility,
                witness_count    = EXCLUDED.witness_count,
                last_observed_at = EXCLUDED.last_observed_at
        $q$, rel, rel, rel);
        GET DIAGNOSTICS n = ROW_COUNT;
        refold_total := refold_total + n;
        RAISE LOG 'refold_source: relation % — % cell(s) touched, % consensus row(s) rebuilt',
            encode(rel, 'hex'), n_cells, n;
        COMMIT;
    END LOOP;

    DROP TABLE IF EXISTS _refold_cells;
    RAISE LOG 'refold_source: % — % row(s) rebuilt across % relation(s) in %s',
        p_source_name, refold_total, array_length(rels, 1),
        round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
END;
$$;
-- ops.activity — what this database is doing right now, as an installed surface.
--
-- The operator console can start work (POST /v1/op, ingest, evict, reindex) but
-- until now could not SEE work: "is the ingest still moving or is it wedged on a
-- lock?" was answered by hand-written psql against pg_stat_activity, typed fresh
-- every time, exactly the ad-hoc pattern ops.index_health was created to end.
-- Cancelling needs this too — ops.cancel_backend takes a pid, and a pid is
-- something you have to be able to look up before you can act on it.
--
-- One row per backend on THIS database, ordered longest-running first, which is
-- the order the question is asked in. Durations are seconds and NULL when the
-- corresponding clock never started (an idle backend has no query_start).
--
-- VISIBILITY IS PRIVILEGE-DEPENDENT AND THE ROW SAYS SO. Postgres shows `query`
-- and `state` for other users' backends only to a superuser or a role in
-- pg_read_all_stats; everyone else sees the row with those columns NULL. That is
-- indistinguishable from an idle backend unless it is named, so `restricted`
-- reports the difference explicitly rather than leaving a caller to conclude the
-- substrate is quiet when it is merely opaque.
DROP FUNCTION IF EXISTS ops.activity(double precision, boolean, boolean);
CREATE OR REPLACE FUNCTION ops.activity(
    p_min_seconds        double precision DEFAULT 0,
    p_include_idle       boolean          DEFAULT true,
    p_include_background boolean          DEFAULT false)
    RETURNS TABLE(pid int, is_self boolean, restricted boolean, usename text,
                  application_name text, client_addr text, backend_type text,
                  state text, wait_event_type text, wait_event text,
                  query_seconds double precision, xact_seconds double precision,
                  backend_seconds double precision, query text)
    -- This is a live observation, not a transaction-constant relation: both
    -- pg_stat_activity and clock_timestamp() may change between calls in one
    -- statement. Mark the function VOLATILE so the planner cannot fold or reorder
    -- those observations under a false constancy promise.
    LANGUAGE sql VOLATILE
BEGIN ATOMIC
    SELECT a.pid,
           a.pid = pg_backend_pid(),
           -- No state AND no query on a live backend is the privilege mask, not
           -- an idle session: an idle session still reports state='idle'.
           a.state IS NULL AND a.query IS NULL,
           a.usename::text,
           a.application_name,
           host(a.client_addr),
           a.backend_type,
           a.state,
           a.wait_event_type,
           a.wait_event,
           extract(epoch FROM clock_timestamp() - a.query_start)::double precision,
           extract(epoch FROM clock_timestamp() - a.xact_start)::double precision,
           extract(epoch FROM clock_timestamp() - a.backend_start)::double precision,
           a.query
    FROM pg_stat_activity a
    WHERE (a.datname = current_database()
           OR (p_include_background AND a.datname IS NULL))
      AND (p_include_idle OR a.state IS DISTINCT FROM 'idle')
      AND COALESCE(
              extract(epoch FROM clock_timestamp() - a.query_start),
              extract(epoch FROM clock_timestamp() - a.backend_start),
              0) >= GREATEST(p_min_seconds, 0)
    ORDER BY COALESCE(a.query_start, a.backend_start), a.pid;
END;

COMMENT ON FUNCTION ops.activity(double precision, boolean, boolean) IS
    'Live backends on this database, longest-running first. restricted=true means '
    'the caller lacks pg_read_all_stats and Postgres masked state/query for that '
    'backend — a different fact from an idle session, which reports state=idle. '
    'Pass the pid to ops.cancel_backend / ops.terminate_backend.';
-- ops.cancel_backend / ops.terminate_backend — stopping work that is already
-- running, as a named operation rather than a raw pg_cancel_backend() call.
--
-- The operator console could start long work and could not stop it: the only
-- cut-off it had was ops.ingest_run_close, which edits the JOURNAL ROW and
-- leaves the backend running — the journal says cancelled while the ingest keeps
-- writing. That is worse than no cancel at all, because the pipeline gate then
-- reports clear. These two signal the process; the journal row follows.
--
-- Both RETURN WHAT THEY ACTED ON, captured BEFORE the signal. pg_cancel_backend
-- returns a bare boolean, so a caller who only has that cannot answer "what did
-- I just kill?" — and on an operator surface with no authentication that is the
-- one question an audit needs. Reading it after the signal races the backend's
-- own teardown.
--
-- THREE REFUSALS, all because the pid is free text from a UI:
--   * a pid on another database — pg_cancel_backend is cluster-wide, so a typo
--     reaches a neighbouring database's backend, which is not this operator's to
--     touch;
--   * this backend's own pid — cancelling the connection executing the cancel
--     aborts the call and reports nothing;
--   * a pid that is not there at all — signalling a dead pid returns false and
--     is indistinguishable from "refused", so it is named.
--
-- Cancel is the first move: it ends the running statement and leaves the session
-- alive to roll back cleanly. Terminate drops the connection and is for a
-- backend that ignored a cancel (uninterruptible wait) — an in-flight ingest
-- batch loses its open transaction, which is the point.
DROP FUNCTION IF EXISTS ops.cancel_backend(int);
DROP FUNCTION IF EXISTS ops.terminate_backend(int);

CREATE OR REPLACE FUNCTION ops.cancel_backend(p_pid int)
    RETURNS TABLE(pid int, signalled boolean, was_state text, was_query text,
                  was_seconds double precision)
    LANGUAGE plpgsql VOLATILE
    AS $$
DECLARE
    a pg_stat_activity%ROWTYPE;
BEGIN
    SELECT * INTO a FROM pg_stat_activity s WHERE s.pid = p_pid;
    IF a.pid IS NULL THEN
        RAISE EXCEPTION 'cancel_backend: no backend with pid % is running', p_pid;
    END IF;
    IF a.datname IS DISTINCT FROM current_database() THEN
        RAISE EXCEPTION 'cancel_backend: pid % belongs to database %, not %',
            p_pid, COALESCE(a.datname, '(none)'), current_database();
    END IF;
    IF p_pid = pg_backend_pid() THEN
        RAISE EXCEPTION 'cancel_backend: pid % is this session — cancelling it aborts this call', p_pid;
    END IF;

    RETURN QUERY
    SELECT p_pid,
           pg_cancel_backend(p_pid),
           a.state,
           a.query,
           extract(epoch FROM clock_timestamp() - COALESCE(a.query_start, a.backend_start))::double precision;
END $$;

CREATE OR REPLACE FUNCTION ops.terminate_backend(p_pid int)
    RETURNS TABLE(pid int, signalled boolean, was_state text, was_query text,
                  was_seconds double precision)
    LANGUAGE plpgsql VOLATILE
    AS $$
DECLARE
    a pg_stat_activity%ROWTYPE;
BEGIN
    SELECT * INTO a FROM pg_stat_activity s WHERE s.pid = p_pid;
    IF a.pid IS NULL THEN
        RAISE EXCEPTION 'terminate_backend: no backend with pid % is running', p_pid;
    END IF;
    IF a.datname IS DISTINCT FROM current_database() THEN
        RAISE EXCEPTION 'terminate_backend: pid % belongs to database %, not %',
            p_pid, COALESCE(a.datname, '(none)'), current_database();
    END IF;
    IF p_pid = pg_backend_pid() THEN
        RAISE EXCEPTION 'terminate_backend: pid % is this session', p_pid;
    END IF;

    RETURN QUERY
    SELECT p_pid,
           pg_terminate_backend(p_pid),
           a.state,
           a.query,
           extract(epoch FROM clock_timestamp() - COALESCE(a.query_start, a.backend_start))::double precision;
END $$;

COMMENT ON FUNCTION ops.cancel_backend(int) IS
    'Cancel the running statement on one backend of THIS database, returning the '
    'state and query captured before the signal. Refuses another database, a dead '
    'pid, and this session. signalled=false means the role lacks pg_signal_backend.';

COMMENT ON FUNCTION ops.terminate_backend(int) IS
    'Drop one backend of THIS database — the escalation for a backend that ignored '
    'a cancel. Same refusals and same before-the-signal capture as ops.cancel_backend.';
-- ops.reindex_invalid / ops.analyze_substrate — the repair half of the operator
-- surface. ops.index_health names the damage; these fix it.
--
-- The 2026-08-13 cycle-shell incident left all 28 partitioned-parent secondaries
-- as empty invalid shells while every row count read green. index_health made
-- that VISIBLE as an installed operation; the repair was still hand-typed psql,
-- which is the same gap one step later — an operator who can see the damage from
-- the console and must leave it to fix the damage will eventually fix it wrong.
--
-- ONE COMMIT PER INDEX, so a rebuild of 28 partitioned parents is resumable and
-- interruptible: ops.cancel_backend on this procedure's pid loses the index in
-- flight and keeps every index already rebuilt. A single-transaction repair
-- would lose all of it and hold the locks for the whole run.
--
-- NOT CONCURRENTLY. REINDEX CONCURRENTLY is barred inside a transaction block,
-- and a PL/pgSQL procedure body is always in one (COMMIT starts the next). A
-- plain REINDEX takes an exclusive lock on the index's table for the rebuild —
-- which is the correct trade here, because the indexes this targets are ALREADY
-- INVALID: reads cannot use them, so the outage began before the repair did.
--
-- No SET clause: a procedure carrying one may not COMMIT, so references are
-- schema-qualified instead (the ops.evict_source rule).
DROP PROCEDURE IF EXISTS ops.reindex_invalid(boolean);

CREATE OR REPLACE PROCEDURE ops.reindex_invalid(p_dry_run boolean DEFAULT false)
    LANGUAGE plpgsql AS $$
DECLARE
    ix        record;
    n         int := 0;
    t0        timestamptz := clock_timestamp();
    t_index   timestamptz;
BEGIN
    FOR ix IN
        SELECT h.index_name, h.table_name, h.schema_name,
               h.is_partitioned_parent, h.leaf_count
        FROM ops.index_health() h
        ORDER BY h.table_name, h.index_name
    LOOP
        n := n + 1;
        IF p_dry_run THEN
            RAISE LOG 'reindex_invalid: WOULD rebuild %.% (partitioned parent: %, leaves: %)',
                ix.table_name, ix.index_name, ix.is_partitioned_parent, ix.leaf_count;
            CONTINUE;
        END IF;

        t_index := clock_timestamp();
        RAISE LOG 'reindex_invalid: rebuilding %.% on %', ix.schema_name, ix.index_name, ix.table_name;
        -- %I on identifiers the catalog itself supplied, never caller text. The
        -- schema is load-bearing: index names are unique per schema, and the four
        -- substrate schemas hold same-named indexes on partitioned mirrors.
        EXECUTE format('REINDEX INDEX %I.%I', ix.schema_name, ix.index_name);
        COMMIT;
        RAISE LOG 'reindex_invalid: % rebuilt in %s',
            ix.index_name, round(extract(epoch FROM clock_timestamp() - t_index)::numeric, 1);
    END LOOP;

    IF n = 0 THEN
        RAISE LOG 'reindex_invalid: no invalid index — nothing to repair';
    ELSE
        RAISE LOG 'reindex_invalid: % index(es) % in %s',
            n,
            CASE WHEN p_dry_run THEN 'would be rebuilt' ELSE 'rebuilt' END,
            round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
    END IF;
END $$;

COMMENT ON PROCEDURE ops.reindex_invalid(boolean) IS
    'Rebuild every index ops.index_health() reports as non-valid, one COMMIT each '
    'so the run is resumable and cancellable. p_dry_run logs the plan without '
    'touching anything. Not CONCURRENTLY: barred inside a procedure, and the '
    'targets are already unusable for reads. CALL ops.reindex_invalid();';

-- ANALYZE, unlike VACUUM, is legal inside a transaction and therefore inside a
-- procedure. VACUUM is NOT and cannot be wrapped here at any nesting — it has to
-- be issued by a client on a connection that is not in a transaction block, which
-- is why the maintenance endpoint owns it and this file does not pretend to.
DROP PROCEDURE IF EXISTS ops.analyze_substrate(text[]);

CREATE OR REPLACE PROCEDURE ops.analyze_substrate(p_tables text[] DEFAULT NULL)
    LANGUAGE plpgsql AS $$
DECLARE
    t       record;
    n       int := 0;
    t0      timestamptz := clock_timestamp();
BEGIN
    FOR t IN
        SELECT c.oid::regclass AS rel
        FROM pg_class c
        WHERE c.relnamespace IN ('laplace'::regnamespace, 'realize'::regnamespace,
                                 'consensus'::regnamespace, 'generation'::regnamespace)
          AND c.relkind IN ('r', 'p')
          AND (p_tables IS NULL OR c.relname = ANY(p_tables))
        ORDER BY c.relname
    LOOP
        n := n + 1;
        EXECUTE format('ANALYZE %s', t.rel);
        COMMIT;
    END LOOP;

    RAISE LOG 'analyze_substrate: % table(s) analyzed in %s',
        n, round(extract(epoch FROM clock_timestamp() - t0)::numeric, 1);
END $$;

COMMENT ON PROCEDURE ops.analyze_substrate(text[]) IS
    'Refresh planner statistics across the substrate schemas, one COMMIT per table. '
    'p_tables NULL = every ordinary and partitioned table. Fixes the class of '
    'slowdown where a correct index is present and the planner will not choose it. '
    'CALL ops.analyze_substrate();';
-- Retire the entity-mask GIN permanently.  The index's only intended readers
-- were four relation-band queries.  Those queries were also semantically wrong:
-- they inferred a relation type's governed band from the relation entity's
-- accumulated incident-edge mask.  They now use consensus.relation_mask_types,
-- which resolves the small relation vocabulary through the highway perfcache.
--
-- On the clean 2026-08-20 seed this partitioned GIN occupied 119 MB, had zero
-- scans, and every entities.highway_mask deposit maintained it.  That made all
-- 6.8M observed entity updates non-HOT.  This is a permanent schema correction,
-- not an ingest-time drop/rebuild cycle.
DO $do$
BEGIN
    BEGIN
        EXECUTE format('ALTER EXTENSION %I DROP INDEX laplace.entities_highway_bits_gin',
                       'laplace_substrate');
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    EXECUTE 'DROP INDEX IF EXISTS laplace.entities_highway_bits_gin';
END $do$;
CREATE INDEX IF NOT EXISTS entities_has_highway
    ON laplace.entities (id)
    WHERE highway_mask IS NOT NULL;
CREATE OR REPLACE VIEW laplace.v_entities_highway AS
SELECT e.*,
       consensus.highway_popcount(e.highway_mask) AS highway_density
FROM laplace.entities e
WHERE e.highway_mask IS NOT NULL;
-- Word → sense edges on the unrefuted consensus surface. lexical.senses()/bubble_up own
-- the ranked synset walk; this view is the shared HAS_SENSE join so callers
-- stop re-typing laplace.relation_type_id('HAS_SENSE') + v_consensus_unrefuted.
--
-- PERFORMANCE: inherits v_consensus_unrefuted (filter on consensus) plus a
-- type_id equality. Prefer subject_id / object_id predicates; do not
-- `SELECT * FROM laplace.v_word_senses` without a key.
CREATE OR REPLACE VIEW laplace.v_word_senses AS
SELECT c.subject_id AS word_id,
       c.object_id  AS sense_id,
       c.id         AS consensus_id,
       c.rating,
       c.rd,
       c.volatility,
       c.witness_count,
       c.last_observed_at,
       consensus.eff_mu(c.rating, c.rd) AS eff_mu
FROM laplace.v_consensus_unrefuted c
WHERE c.type_id = laplace.relation_type_id('HAS_SENSE')
  AND c.object_id IS NOT NULL;
-- Resolve one content id to its type=1 coord + trajectory. This is the seam
-- Rule #4 keeps catching: a correlated CTE reference to me.coord is NOT a
-- bound parameter for GiST KNN. Fetch through this function into locals (or a
-- MATERIALIZED CTE), then ORDER BY coord <<->> :anchor so the planner sees a
-- genuine parameter. LIMIT 1 matches every prior hand-rolled form.
--
-- PERFORMANCE: execution sub-millisecond on a known id (see laplace.v_word_points
-- contract). Requires trajectory IS NOT NULL — callers that only need coord
-- should `SELECT ... FROM laplace.v_word_points WHERE id = $1 AND coord IS NOT NULL
-- LIMIT 1` instead.
-- No SET search_path / no STRICT: both block SQL inlining (Rule #2 / #617).
DROP FUNCTION IF EXISTS laplace.word_anchor(bytea);
CREATE OR REPLACE FUNCTION structural.word_anchor(p_id bytea)
    RETURNS TABLE(
        id          bytea,
        type_id     bytea,
        tier        smallint,
        coord       geometry,
        trajectory  geometry,
        hilbert_index bytea)
    LANGUAGE sql STABLE PARALLEL SAFE
    -- STRUCTURAL bound, not an estimate: the body ends in LIMIT 1, so this
    -- returns at most one row. Undeclared, Postgres assumes 1000 -- a 1000x
    -- overestimate on the inner side of any join, which is what makes scanning
    -- look cheaper than probing.
    ROWS 1 AS $$
    SELECT w.id, w.type_id, w.tier, w.coord, w.trajectory, w.hilbert_index
    FROM laplace.v_word_points w
    WHERE w.id = p_id
      AND w.trajectory IS NOT NULL
    LIMIT 1
$$;
-- Canonical relation-in/relation-out shape cluster.
--
-- p_limit has one honest meaning for resource use and output: at most p_limit
-- deterministic coordinate-nearest candidates are admitted per DISTINCT resolved seed,
-- and therefore at most p_limit survivors can be returned for that seed. The old scalar
-- hid GREATEST(p_limit * 20, 2000), so asking for ten results silently realized and scored
-- two thousand curves. That was an unmeasured population multiplier, not a correctness
-- bound: coordinate KNN is only the declared prefilter and cannot prove global Frechet
-- completeness at any finite multiplier.
--
-- Duplicate caller seeds retain their input ordinals but share anchor lookup, KNN,
-- candidate curve realization, rendering and recurrence aggregation. There is no
-- procedural FOREACH/scalar call; every database operation consumes a relation.
DROP FUNCTION IF EXISTS laplace.structural_cluster_batch(bytea[], double precision, integer);
-- The scalar BEGIN ATOMIC body records a dependency on the batch core. Retire the
-- adapter first so future extension upgrades can replace the core without CASCADE.
DROP FUNCTION IF EXISTS structural.cluster(bytea, double precision, integer);
DROP FUNCTION IF EXISTS structural.cluster_batch(bytea[], double precision, integer);
CREATE FUNCTION structural.cluster_batch(
    p_seeds bytea[],
    p_eps   double precision DEFAULT 0.05,
    p_limit integer          DEFAULT 200)
    RETURNS TABLE(
        input_ordinal bigint,
        seed          bytea,
        entity_id     bytea,
        label         text,
        frechet       double precision,
        recurrence    bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH inputs AS MATERIALIZED (
        SELECT u.seed, u.ord::bigint AS input_ordinal
        FROM unnest(COALESCE(p_seeds, ARRAY[]::bytea[]))
             WITH ORDINALITY AS u(seed, ord)
        WHERE u.seed IS NOT NULL
    ), distinct_seeds AS MATERIALIZED (
        SELECT DISTINCT i.seed
        FROM inputs i
    ), seed_defs AS MATERIALIZED (
        SELECT s.seed,
               a.id AS anchor_id,
               a.coord,
               structural.entity_curve(a.id) AS curve
        FROM distinct_seeds s
        CROSS JOIN LATERAL structural.word_anchor(s.seed) a
        WHERE a.coord IS NOT NULL
    ), seed_candidates AS MATERIALIZED (
        SELECT a.seed, k.entity_id
        FROM seed_defs a
        CROSS JOIN LATERAL (
            SELECT w.id AS entity_id
            FROM laplace.v_word_points w
            WHERE w.id <> a.anchor_id
              AND w.trajectory IS NOT NULL
            ORDER BY w.coord <<->> a.coord, w.id
            LIMIT GREATEST(p_limit, 0)
        ) k
        WHERE a.curve IS NOT NULL
    ), candidate_curves AS MATERIALIZED (
        SELECT c.entity_id, structural.entity_curve(c.entity_id) AS curve
        FROM (SELECT DISTINCT sc.entity_id FROM seed_candidates sc) c
    ), scored AS MATERIALIZED (
        SELECT sc.seed,
               sc.entity_id,
               public.laplace_frechet_4d(cc.curve, sd.curve) AS frechet
        FROM seed_candidates sc
        JOIN seed_defs sd ON sd.seed = sc.seed
        JOIN candidate_curves cc ON cc.entity_id = sc.entity_id
        WHERE cc.curve IS NOT NULL
    ), survivors AS MATERIALIZED (
        SELECT s.seed, s.entity_id, s.frechet
        FROM scored s
        WHERE s.frechet <= p_eps
        ORDER BY s.seed, s.frechet, s.entity_id
    ), survivor_ids AS MATERIALIZED (
        SELECT DISTINCT s.entity_id FROM survivors s
    ), render_input AS MATERIALIZED (
        SELECT array_agg(s.entity_id ORDER BY s.entity_id) AS ids
        FROM survivor_ids s
    ), rendered AS MATERIALIZED (
        SELECT r.entity_id, r.label
        FROM render_input i
        CROSS JOIN LATERAL unnest(
            i.ids,
            realize.render_text_batch(i.ids)) AS r(entity_id, label)
    ), recurrences AS MATERIALIZED (
        SELECT s.entity_id, count(p.id)::bigint AS recurrence
        FROM survivor_ids s
        LEFT JOIN laplace.physicalities p ON p.entity_id = s.entity_id
        GROUP BY s.entity_id
    )
    SELECT i.input_ordinal,
           i.seed,
           s.entity_id,
           r.label,
           s.frechet,
           c.recurrence
    FROM inputs i
    JOIN survivors s ON s.seed = i.seed
    JOIN rendered r ON r.entity_id = s.entity_id
    JOIN recurrences c ON c.entity_id = s.entity_id
    ORDER BY i.input_ordinal, s.frechet, s.entity_id;
END;
-- Scalar adapter over the canonical set implementation. Shape distance is Frechet over
-- REALIZED entity curves, never packed physicalities.trajectory (Rule #3 / Issue 51).
DROP FUNCTION IF EXISTS laplace.structural_cluster(bytea, double precision, integer);
DROP FUNCTION IF EXISTS structural.cluster(bytea, double precision, integer);
CREATE FUNCTION structural.cluster(
        p_seed bytea, p_eps double precision DEFAULT 0.05, p_limit integer DEFAULT 200)
    RETURNS TABLE(entity_id bytea, label text, frechet double precision, recurrence bigint)
    LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT b.entity_id, b.label, b.frechet, b.recurrence
    FROM structural.cluster_batch(ARRAY[p_seed]::bytea[], p_eps, p_limit) b
    WHERE b.input_ordinal = 1
    ORDER BY b.frechet, b.entity_id;
END;
-- Retired: laplace_eff_mu(subject, type, object) -> bigint.
-- A convenience wrapper that looked up one consensus row and returned
-- consensus.eff_mu(rating, rd). It was marked `STABLE SET search_path`, and the SET clause
-- blocks SQL inlining — so in a WHERE/ORDER BY it would have run per-row and could
-- not match the (rating - 2*rd) expression indexes that every other eff_mu caller
-- relies on. It had zero callers tree-wide (readers open-code consensus.eff_mu(c.rating, c.rd)
-- against the consensus row they already hold), so it was dead code that also
-- violated the eff_mu inlining law. On the UPGRADE path the old catalog row would
-- linger; a fresh CREATE EXTENSION never had it. This DROP makes the two match.
DROP FUNCTION IF EXISTS laplace.laplace_eff_mu(bytea, bytea, bytea);
DROP FUNCTION IF EXISTS laplace.laplace_eff_mu(bytea, bytea, bytea);
-- ops.entity_attestations — inspect/census listing of consensus cells for a
-- subject (spec 37 WITNESS). Attestation listing is ops, not the fold itself.
-- Old names dropped (#532), including a mid-migration consensus.* placement.
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.laplace_entity_attestations(bytea, bigint);
DROP FUNCTION IF EXISTS laplace.laplace_entity_attestations(bytea, bigint);
DROP FUNCTION IF EXISTS ops.entity_attestations(bytea, bigint);
CREATE OR REPLACE FUNCTION ops.entity_attestations(
    p_subject bytea, p_min_eff_mu_raw bigint DEFAULT 0)
RETURNS TABLE(type_id bytea, object_id bytea, eff_mu_raw bigint, eff_mu numeric, witnesses bigint)
LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT c.type_id, c.object_id,
           consensus.eff_mu(c.rating, c.rd),
           consensus.eff_mu_display(c.rating, c.rd),
           c.witness_count
    FROM laplace.consensus c
    WHERE c.subject_id = p_subject
      AND c.object_id IS NOT NULL
      AND consensus.eff_mu(c.rating, c.rd) >= p_min_eff_mu_raw
    ORDER BY consensus.eff_mu(c.rating, c.rd) DESC;
END;
-- structural.entities_at_depth — tier slice of entities (geometry/structure
-- family). Old names dropped (#532).
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.laplace_entities_at_depth(smallint);
DROP FUNCTION IF EXISTS laplace.laplace_entities_at_depth(smallint);
DROP FUNCTION IF EXISTS structural.entities_at_depth(smallint);
CREATE OR REPLACE FUNCTION structural.entities_at_depth(p_depth smallint)
RETURNS SETOF laplace.entities
LANGUAGE sql STABLE
BEGIN ATOMIC
    SELECT * FROM laplace.entities WHERE tier = p_depth;
END;
-- taxonomy.ancestry — hierarchy walk (spec 37 TRAVERSE). Filename keeps the
-- historical laplace_ancestry stem; CREATE drops the redundant project prefix
-- now that the schema names the family. Old laplace.laplace_ancestry (and any
-- taxonomy.laplace_ancestry mid-migration name) dropped rather than shimmed (#532).
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.laplace_ancestry(bytea, bytea, integer);
DROP FUNCTION IF EXISTS laplace.laplace_ancestry(bytea, bytea, integer);
DROP FUNCTION IF EXISTS taxonomy.ancestry(bytea, bytea, integer);
CREATE OR REPLACE FUNCTION taxonomy.ancestry(
    p_entity_id bytea,
    p_band_mask  bytea,
    p_max_depth  integer DEFAULT 10)
RETURNS TABLE(ancestor_id bytea, depth integer, best_eff_mu numeric)
LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH RECURSIVE
        band_types AS (
            SELECT id FROM unnest(consensus.relation_mask_types(p_band_mask)) AS t(id)
        ),
        ancestry(ancestor_id, depth, eff_mu_raw, visited) AS (
            SELECT c.object_id, 1, consensus.eff_mu(c.rating, c.rd),
                   ARRAY[p_entity_id, c.object_id]
            FROM laplace.consensus c
            JOIN band_types bt ON bt.id = c.type_id
            WHERE c.subject_id = p_entity_id
              AND c.object_id IS NOT NULL
              AND consensus.eff_mu(c.rating, c.rd) > 0
            UNION ALL
            SELECT c.object_id, anc.depth + 1, consensus.eff_mu(c.rating, c.rd),
                   anc.visited || c.object_id
            FROM ancestry anc
            JOIN laplace.consensus c ON c.subject_id = anc.ancestor_id
            JOIN band_types bt ON bt.id = c.type_id
            WHERE c.object_id IS NOT NULL
              AND consensus.eff_mu(c.rating, c.rd) > 0
              AND anc.depth < p_max_depth
              AND NOT (c.object_id = ANY (anc.visited))
        )
    SELECT ancestor_id, min(depth)::integer, consensus.eff_mu_display(max(eff_mu_raw), 0)
    FROM ancestry
    GROUP BY ancestor_id;
END;
-- The jitter catalog: convicted training artifacts, as one indexed query.
-- A model-witnessed coupling is ARTIFACT-shaped when it is asserted (the
-- evidence row CONFIRMS: outcome=2) but corroborated by nobody: exactly one
-- witness on the consensus cell and wide RD (the fold never earned
-- confidence). Real structure replicates across independently trained
-- checkpoints (hash collision at the shared cell) and against lexical
-- witnesses; per-run noise cannot. p_rd_floor is the "still uncertain"
-- bound (fp1e9 Glicko-1 scale). Set-returning; the LIMIT belongs to the
-- caller (top-k is only ever a query LIMIT).
-- BEGIN ATOMIC: GH #764.
-- Model artifact scan → generation (ELECT / forward-pass family).
DROP FUNCTION IF EXISTS generation.model_jitter_catalog(text, bigint);
DROP FUNCTION IF EXISTS laplace.model_jitter_catalog(text, bigint);
CREATE OR REPLACE FUNCTION generation.model_jitter_catalog(
        p_relation text DEFAULT NULL,
        p_rd_floor bigint DEFAULT 150000000000)
    RETURNS TABLE(
        subject_id bytea, type_id bytea, object_id bytea,
        source_id bytea, outcome smallint, observations bigint,
        rating bigint, rd bigint, eff_mu bigint, witness_count bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH model_rels(tid) AS (
        SELECT laplace.relation_type_id(r)
        FROM unnest(CASE WHEN p_relation IS NULL
                         THEN ARRAY['ATTENDS','OV_RELATES','COMPLETES_TO',
                                    'CONTINUES_TO','SIMILAR_TO']
                         ELSE ARRAY[p_relation] END) AS r
    )
    SELECT a.subject_id, a.type_id, a.object_id,
           a.source_id, a.outcome, a.observation_count,
           c.rating, c.rd, consensus.eff_mu(c.rating, c.rd), c.witness_count
    FROM laplace.consensus c
    JOIN model_rels r ON r.tid = c.type_id
    JOIN laplace.attestations a
      ON a.subject_id = c.subject_id
     AND a.type_id    = c.type_id
     AND a.object_id  = c.object_id
    WHERE c.witness_count = 1
      AND c.rd >= p_rd_floor
      AND a.outcome = 2;
END;
-- lexical.translations — peer subjects sharing a band-typed object (sense /
-- translation-shaped co-denotation). Prefer lexical over taxonomy: the row is
-- a same-plane peer set, not a hierarchy walk. Old names dropped (#532).
-- BEGIN ATOMIC: GH #764.
DROP FUNCTION IF EXISTS laplace.laplace_translations(bytea, bytea);
DROP FUNCTION IF EXISTS laplace.laplace_translations(bytea, bytea);
DROP FUNCTION IF EXISTS lexical.translations(bytea, bytea);
CREATE OR REPLACE FUNCTION lexical.translations(
    p_entity_id bytea, p_band_mask bytea)
RETURNS TABLE(translation_id bytea, shared_object_id bytea, eff_mu numeric)
LANGUAGE sql STABLE
BEGIN ATOMIC
    WITH band_types AS (
        SELECT id FROM unnest(consensus.relation_mask_types(p_band_mask)) AS t(id)
    )
    SELECT DISTINCT a2.subject_id, a1.object_id,
           consensus.eff_mu_display(a2.rating, a2.rd)
    FROM laplace.consensus a1
    JOIN band_types bt ON bt.id = a1.type_id
    JOIN laplace.consensus a2
      ON a2.object_id  = a1.object_id
     AND a2.subject_id != a1.subject_id
     AND a2.type_id    = a1.type_id
    WHERE a1.subject_id = p_entity_id
      AND a1.object_id IS NOT NULL
      AND consensus.eff_mu(a1.rating, a1.rd) > 0
      AND consensus.eff_mu(a2.rating, a2.rd) > 0;
END;
-- ops.ducet_rank — recover a tier-0 atom's DUCET collation rank from its coord.
--
-- Super-Fibonacci places atom i (of N = laplace.atom_window()) using
--   s = i + 0.5,  r = sqrt(s/N),  R = sqrt(1 - s/N)
--   coord = (r*sin a, r*cos a, R*sin b, R*cos b)
-- so x^2 + y^2 = r^2 = s/N exactly. The rank is therefore recoverable from
-- geometry alone, with no collation table consulted at runtime: allkeys.txt is
-- baked into the placement at seed time.
--
-- VERIFIED 2026-08-12 on a seeded substrate: rank('a') = 12142.5 < rank('A') =
-- 12207.5 (DUCET puts lowercase first; codepoint order would invert it), and
-- rank('a-acute') = 12144.5 lands two ranks after 'a' rather than at codepoint
-- 225 -- secondary-weight behaviour codepoint ordering cannot produce. Every
-- recovered rank is an exact half integer, which pins both s = i + 0.5 and
-- N = atom_window (1,114,112, NOT the 1,114,240 tier-0 row count, which
-- includes sentinels).
--
-- Only meaningful for tier-0 physicalities (radius_origin = 1). Composed
-- entities are centroids and carry no rank; use ops.placement_health().
--
-- BEGIN ATOMIC, not AS $$ (G12 / GH #764): an atomic body parses at CREATE time
-- and records pg_depend, so dropping laplace.atom_window() or a referenced
-- relation fails loudly here instead of leaving an opaque string that breaks at
-- first call. Every object named below must therefore already be installed when
-- this file runs -- which is what the manifest ordering is for.
-- No DROP: signature and return type are unchanged, so CREATE OR REPLACE alone
-- does the job — and the DROP was not merely redundant but upgrade-blocking:
-- ops.ducet_ordered below is BEGIN ATOMIC, so the installed copy holds a real
-- pg_depend edge on this function, and the first live upgrade died on
-- "cannot drop function ops.ducet_rank because other objects depend on it"
-- (2026-08-13, run 31661560670). Same class as #1004 and #1006.
CREATE OR REPLACE FUNCTION ops.ducet_rank(p_coord geometry)
RETURNS double precision
LANGUAGE sql IMMUTABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT (public.ST_X(p_coord) ^ 2 + public.ST_Y(p_coord) ^ 2)
           * laplace.atom_window()::double precision;
END;

COMMENT ON FUNCTION ops.ducet_rank(geometry) IS
    'DUCET collation rank recovered from a tier-0 coord (x^2+y^2 = s/N). Returns i+0.5.';


-- ops.ducet_ordered — collation-ordered atom listing, straight from geometry.
--
-- Evaluation order is deliberate and is the whole point of the shape below:
-- ducet_rank is pure arithmetic on a stored geometry, so it is cheap enough to
-- range-filter and sort on. realize.codepoint_for_id is NOT cheap. So the inner
-- query does rank/filter/sort/LIMIT using only the cheap expression, and the
-- expensive resolution runs exactly p_limit times in the outer projection --
-- never once per tier-0 row.
--
-- The earlier revision of this function called codepoint_for_id THREE times per
-- row inside the projection and evaluated ducet_rank twice (SELECT and WHERE),
-- across all 1,114,240 atoms before LIMIT could apply. Measured cost of that
-- class of mistake elsewhere in this session: converse.label_or_hex at ~42 ms a
-- call, 4,587 calls, 195 seconds. Resolve last, on the surviving rows only.
--
-- UNITS, and why the WHERE/ORDER BY spell out the raw expression instead of
-- calling ducet_rank: physicalities_ducet_rank_btree indexes the UNSCALED
-- x^2 + y^2 (= s/N), and the planner does not match an index through
-- ducet_rank's * atom_window() scale factor. MEASURED 2026-08-13: predicating
-- on ducet_rank(p.coord) is a 1,434 ms seq scan + sort of every physicality;
-- predicating on the raw expression is a 6 ms Merge Append over the
-- per-partition expression indexes, identical six rows returned. So the bound
-- converts ONCE into index space (p_from / atom_window), the range filter and
-- sort run unscaled — order is preserved, the scale factor is a positive
-- constant — and ducet_rank projects the rank for the survivors only.
--
-- Internal aliases are rnk/cp_val rather than rank/codepoint: under BEGIN ATOMIC
-- the RETURNS TABLE columns are OUT parameters and sit in scope over the body,
-- so reusing their names for inner aliases invites a silent capture.
-- No DROP: same signature, same RETURNS TABLE shape — see the ducet_rank note.
CREATE OR REPLACE FUNCTION ops.ducet_ordered(p_from  integer DEFAULT 0,
                                             p_limit integer DEFAULT 50)
RETURNS TABLE(rank double precision, codepoint integer, ch text)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT w.rnk,
           cp.cp_val,
           CASE WHEN cp.cp_val BETWEEN 32 AND 1114111
                THEN chr(cp.cp_val) END
    FROM (
        SELECT e.id AS eid, ops.ducet_rank(p.coord) AS rnk
        FROM laplace.entities e
        JOIN laplace.physicalities p ON p.entity_id = e.id
        WHERE e.tier = 0
          AND (public.ST_X(p.coord) ^ 2 + public.ST_Y(p.coord) ^ 2)
              >= p_from::double precision / laplace.atom_window()::double precision
        ORDER BY (public.ST_X(p.coord) ^ 2 + public.ST_Y(p.coord) ^ 2)
        LIMIT p_limit
    ) w
    CROSS JOIN LATERAL (SELECT realize.codepoint_for_id(w.eid) AS cp_val) cp
    ORDER BY w.rnk;
END;

COMMENT ON FUNCTION ops.ducet_ordered(integer, integer) IS
    'Atoms in DUCET order recovered from geometry. Cheap rank filter first; '
    'codepoint resolution runs only on the LIMITed rows.';
-- ops.placement_health — placement confidence by tier, from radius_origin.
--
-- radius_origin is the resultant length of the constituent unit vectors: the
-- standard concentration statistic from directional statistics. It is already a
-- STORED generated column on physicalities and was, until this function, never
-- read as a predicate anywhere in the extension (physicalities_radius_btree was
-- dropped 2026-07-28 having taken 0 scans against 99M rows). It is the only
-- signal the geometry has for "this coordinate is a poor summary of its
-- trajectory".
--
-- Reading of the value:
--   r = 1      constituents coincide, or tier 0 (Super-Fibonacci, on the sphere)
--   r -> 1     tight cluster; the centroid is a faithful bucket
--   r -> 0     dispersed constituents; the Euclidean mean nearly cancels and the
--              normalised DIRECTION is dominated by accumulated float error
--
-- Below p_unreliable the coordinate should be treated as absent rather than
-- wrong: the geometry cannot otherwise abstain, since every placement is a
-- valid-looking 4-vector whether or not it means anything.
--
-- MEASURED 2026-08-12 (foundation + OMW), EXACT over 15,595,304 physicalities:
--
--   tier 0    1,114,240 rows   min 1.000000   avg 1.000000   0% under 0.1
--   composed 14,481,064 rows   min 0.003148   avg 0.453797   1.664% under 0.1
--                                                            1,184 rows under 0.02
--
-- The composed ladder does not inherit Super-Fibonacci's low discrepancy:
-- composed entities are centroids and are not on the spiral.
--
-- WHY THE CANCELLATION COLUMN EXISTS. Constituents are unit vectors, so
-- -log10(r) is the number of decimal digits destroyed by cancellation in
-- forming the mean. At the observed minimum r = 0.003148 that is ~2.5 digits.
-- fp64 carries ~15.95 decimal digits and so has ~13.5 left; fp32 carries ~7.22
-- and has ~4.7 left, and less than that for the 1,184 rows under 0.02. This is
-- the measurement that decides whether a code path may be narrowed to fp32, and
-- it is a WIDTH question entirely separate from determinism: a CPU fp32
-- reduction in fixed order is bit-reproducible, while a GPU reduction is not at
-- any width (CUDA defaults to -fmad=true and block reduction order is
-- undefined). Width governs the placement path; order governs anything feeding
-- a hash, coord, hilbert_index or trajectory.
--
-- Split is on n_constituents rather than entities.tier: it is on physicalities
-- already, so the tier-0/composed cut needs no join and the whole table
-- aggregates in ~1.3 s. radius_origin is STORED, so nothing is recomputed.
-- Use ops.placement_health_by_tier() when the finer per-tier cut is wanted.
--
-- BEGIN ATOMIC, not AS $$ (G12 / GH #764). The inner aggregate aliases are
-- n_rows/r_min/r_avg rather than rows/min_r/avg_r because RETURNS TABLE columns
-- are OUT parameters and are in scope over an atomic body -- an inner alias
-- sharing their name is a silent capture waiting to happen.
DROP FUNCTION IF EXISTS ops.placement_health(double precision, double precision);
DROP FUNCTION IF EXISTS ops.placement_health(double precision);
CREATE OR REPLACE FUNCTION ops.placement_health(
    p_unreliable double precision DEFAULT 0.1)
RETURNS TABLE(cohort              text,
              rows                bigint,
              min_r               numeric,
              avg_r               numeric,
              off_sphere          bigint,
              unreliable          bigint,
              pct_unreliable      numeric,
              worst_digits_lost   numeric,
              fp32_digits_left    numeric)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT CASE WHEN a.is_tier0 THEN 'tier0 (on spiral)'::text
                ELSE 'composed (centroid)'::text END,
           a.n_rows,
           a.r_min,
           a.r_avg,
           a.n_off,
           a.n_unrel,
           round((100.0 * a.n_unrel / NULLIF(a.n_rows, 0))::numeric, 4),
           -- log() has no (double, double) form -- only log(numeric, numeric) --
           -- so the raw minimum is cast rather than reusing the ROUNDED r_min,
           -- which would fold the cancellation figure to 6 decimal places before
           -- taking its logarithm. BEGIN ATOMIC caught this at CREATE time; the
           -- string body it replaced would have raised it at first call.
           round(-log(10::numeric, GREATEST(a.r_min_raw, 1e-300)::numeric), 2),
           round(7.22 + log(10::numeric, GREATEST(a.r_min_raw, 1e-300)::numeric), 2)
    FROM (
        SELECT (p.n_constituents = 0)                                      AS is_tier0,
               count(*)                                                    AS n_rows,
               round(min(p.radius_origin)::numeric, 6)                     AS r_min,
               round(avg(p.radius_origin)::numeric, 6)                     AS r_avg,
               count(*) FILTER (WHERE abs(p.radius_origin - 1.0) > 1e-9)   AS n_off,
               count(*) FILTER (WHERE p.radius_origin < p_unreliable)      AS n_unrel,
               min(p.radius_origin)                                        AS r_min_raw
        FROM laplace.physicalities p
        GROUP BY (p.n_constituents = 0)
    ) a
    ORDER BY a.is_tier0 DESC;
END;

COMMENT ON FUNCTION ops.placement_health(double precision) IS
    'Exact placement confidence, tier0 vs composed, with the cancellation figure '
    'that decides whether a path may be narrowed to fp32.';


-- ops.placement_health_by_tier — the finer per-tier cut. Needs the entities join,
-- so it samples; use ops.placement_health() when the exact tier0/composed split
-- is enough. plpgsql, because TABLESAMPLE takes a literal rather than a
-- parameter, so the percentage has to reach the parser through format().
DROP FUNCTION IF EXISTS ops.placement_health_by_tier(double precision, double precision);
CREATE OR REPLACE FUNCTION ops.placement_health_by_tier(
    p_sample_pct  double precision DEFAULT 2.0,
    p_unreliable  double precision DEFAULT 0.1)
RETURNS TABLE(tier            smallint,
              sampled         bigint,
              min_r           numeric,
              avg_r           numeric,
              max_r           numeric,
              off_sphere      bigint,
              unreliable      bigint,
              pct_unreliable  numeric)
LANGUAGE plpgsql STABLE PARALLEL SAFE
AS $$
BEGIN
    -- counts aggregated once in the inner query; the percentage is derived
    -- outside rather than re-running the FILTER a second time.
    RETURN QUERY EXECUTE format($fmt$
        SELECT a.tier, a.sampled, a.min_r, a.avg_r, a.max_r, a.off_sphere,
               a.unreliable,
               round((100.0 * a.unreliable / NULLIF(a.sampled, 0))::numeric, 2)
        FROM (
            SELECT e.tier,
                   count(*)                                                  AS sampled,
                   round(min(p.radius_origin)::numeric, 6)                    AS min_r,
                   round(avg(p.radius_origin)::numeric, 6)                    AS avg_r,
                   round(max(p.radius_origin)::numeric, 6)                    AS max_r,
                   count(*) FILTER (WHERE abs(p.radius_origin - 1.0) > 1e-9)  AS off_sphere,
                   count(*) FILTER (WHERE p.radius_origin < %L)               AS unreliable
            FROM laplace.physicalities p TABLESAMPLE SYSTEM (%L)
            JOIN laplace.entities e ON e.id = p.entity_id
            GROUP BY e.tier
        ) a
        ORDER BY a.tier
    $fmt$, p_unreliable, p_sample_pct);
END;
$$;

COMMENT ON FUNCTION ops.placement_health_by_tier(double precision, double precision) IS
    'Sampled placement confidence broken out per tier. Tier 0 must be exactly 1.0; '
    'low r above tier 0 means the centroid is a poor summary of its trajectory.';


-- ops.placement_unreliable — the offending rows themselves, so the signal is
-- actionable rather than merely observable.
--
-- Labels are resolved by ONE call to converse.label_or_hex_batch over the
-- already-LIMITed id array, not by p_limit scalar calls in the projection.
-- Measured cost of the scalar form: ~42 ms per label (4,587 labels = 195 s), so
-- at the default limit the difference is roughly one call against 50.
DROP FUNCTION IF EXISTS ops.placement_unreliable(double precision, integer);
CREATE OR REPLACE FUNCTION ops.placement_unreliable(
    p_threshold double precision DEFAULT 0.1,
    p_limit     integer          DEFAULT 50)
RETURNS TABLE(entity_id bytea, tier smallint, radius double precision, label text)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH picked AS (
        SELECT p.entity_id AS eid, e.tier AS etier, p.radius_origin AS r
        FROM laplace.physicalities p
        JOIN laplace.entities e ON e.id = p.entity_id
        WHERE p.radius_origin < p_threshold
        ORDER BY p.radius_origin, p.entity_id
        LIMIT p_limit
    ),
    ord AS (
        SELECT picked.eid, picked.etier, picked.r,
               row_number() OVER (ORDER BY picked.r, picked.eid) AS k
        FROM picked
    ),
    labs AS (
        SELECT converse.label_or_hex_batch(
                   array_agg(picked.eid ORDER BY picked.r, picked.eid)) AS l
        FROM picked
    )
    SELECT o.eid, o.etier, o.r, (labs.l)[o.k]
    FROM ord o CROSS JOIN labs
    ORDER BY o.k;
END;

COMMENT ON FUNCTION ops.placement_unreliable(double precision, integer) IS
    'Rows whose centroid is a poor summary of their trajectory. One batched '
    'label resolution over the LIMITed set.';
-- ops.metric_ladder — every rung of the comparison ladder for two entities, in
-- one result, ordered by how much of the trajectory each rung forgets.
--
-- The rungs are not interchangeable and the collisions are deliberate. From
-- MODEL_INGESTION_DESIGN.md: "a slice coordinate is a bucket, not an identity."
-- Geometry proposes candidates; typed evidence governs selection.
--
--   rung             operates on              order      cat/tac/act
--   ---------------- ----------------------- ---------- ----------------
--   coord_distance   collapsed point          forgotten  collide
--   hilbert          quantised point          forgotten  collide
--   hausdorff        realized curve as a SET  forgotten  collide
--   frechet          realized curve as a PATH preserved  separate
--   merkle_id        ordered childIds         preserved  separate exactly
--
-- REALIZED CURVES, NOT PACKED TRAJECTORIES. structural.entity_curve rebuilds
-- ST_MakeLine(child.coord ORDER BY ordinal) -- actual placements in trajectory
-- order. The `trajectory` column is mantissa-packed identity payload: entity id,
-- ordinal and flags encoded into double mantissas. Feeding it to a geometric
-- metric compares packed hashes as if they were positions, which is the error
-- the placement law forbids ("packed trajectory vertices ... must never be
-- presented as spatial coordinates") and which commit 2537fcd7 already fixed
-- once. Symptom if it regresses: Hausdorff between two anagrams returns ~1e-16
-- instead of exactly 0, because the ordinal differs in the low mantissa bits.
--
-- Each metric is evaluated ONCE, in the CTE, and reused for both `value` and
-- `collides`. The prior revision computed every metric twice -- including
-- Frechet, the expensive one -- by repeating the call in the collides column.
--
-- BEGIN ATOMIC, not AS $$ (G12 / GH #764). Two consequences visible below: the
-- 4D metric functions are schema-qualified, because an atomic body resolves
-- names at CREATE time and pins the OID rather than re-resolving through
-- search_path per call; and every literal in the UNION carries an explicit cast,
-- because the parsed body must match the declared return type exactly instead of
-- coercing an `unknown` at first execution.
-- DROP ORDER IS LOAD-BEARING: metric_ladder_words is BEGIN ATOMIC and pins
-- this function's OID in pg_depend, so on a live-DB extension UPDATE (where
-- both already exist) the base cannot drop while the words wrapper stands.
-- Fresh installs never notice — which is how the wrong order survived until
-- the first post-#764 upgrade ran against a populated cluster (2026-08-13).
DROP FUNCTION IF EXISTS ops.metric_ladder_words(text, text);
DROP FUNCTION IF EXISTS ops.metric_ladder(bytea, bytea);
CREATE OR REPLACE FUNCTION ops.metric_ladder(p_a bytea, p_b bytea)
RETURNS TABLE(rung          text,
              value         double precision,
              collides      boolean,
              order_bearing boolean)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH pt AS (
        -- one scan, both entities, pivoted; not six scalar subqueries
        SELECT (array_agg(s.coord         ORDER BY s.ord))[1] AS ca,
               (array_agg(s.coord         ORDER BY s.ord))[2] AS cb,
               (array_agg(s.hilbert_index ORDER BY s.ord))[1] AS ha,
               (array_agg(s.hilbert_index ORDER BY s.ord))[2] AS hb
        FROM (SELECT p.coord, p.hilbert_index,
                     CASE WHEN p.entity_id = p_a THEN 1 ELSE 2 END AS ord
              FROM laplace.physicalities p
              WHERE p.entity_id IN (p_a, p_b)) s
    ),
    m AS (
        SELECT public.laplace_distance_4d(pt.ca, pt.cb)        AS d_coord,
               pt.ha                                           AS ha,
               pt.hb                                           AS hb,
               public.laplace_hausdorff_4d(qa.curve, qb.curve)  AS d_haus,
               public.laplace_frechet_4d(qa.curve, qb.curve)    AS d_fre
        FROM pt
        CROSS JOIN LATERAL (SELECT structural.entity_curve(p_a) AS curve) qa
        CROSS JOIN LATERAL (SELECT structural.entity_curve(p_b) AS curve) qb
    )
    SELECT 'coord_distance'::text, m.d_coord, (m.d_coord = 0.0), false FROM m
    UNION ALL
    SELECT 'hilbert'::text, NULL::double precision, (m.ha = m.hb), false FROM m
    UNION ALL
    SELECT 'hausdorff'::text, m.d_haus, (m.d_haus = 0.0), false FROM m
    UNION ALL
    SELECT 'frechet'::text, m.d_fre, (m.d_fre = 0.0), true FROM m
    UNION ALL
    SELECT 'merkle_id'::text, NULL::double precision, (p_a = p_b), true;
END;

COMMENT ON FUNCTION ops.metric_ladder(bytea, bytea) IS
    'All comparison rungs for two entities over REALIZED curves. Coord/Hilbert/'
    'Hausdorff collide on anagrams by design; Frechet and Merkle id separate them.';


-- ops.metric_ladder_words — same ladder addressed by surface, for interactive use.
DROP FUNCTION IF EXISTS ops.metric_ladder_words(text, text);
CREATE OR REPLACE FUNCTION ops.metric_ladder_words(p_a text, p_b text)
RETURNS TABLE(rung          text,
              value         double precision,
              collides      boolean,
              order_bearing boolean)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT l.rung, l.value, l.collides, l.order_bearing
    FROM ops.metric_ladder(laplace.word_id(p_a), laplace.word_id(p_b)) l;
END;

COMMENT ON FUNCTION ops.metric_ladder_words(text, text) IS
    'ops.metric_ladder addressed by surface rather than id.';
-- ops.ingest_integrity_gate — refuse a seed run that wrote more physicalities
-- than entities.
--
-- A physicality whose entity_id has no row in laplace.entities is unreachable
-- content: structural.containers_of finds it, realize.render_text returns NULL
-- for anything containing it, and converse.label_or_hex falls through to hex. A
-- document holding one such constituent renders empty in full.
--
-- MEASURED 2026-08-12: 899,179 such rows, 5.8% of physicalities. 894,613 of them
-- (99.5%) fall inside the OMWDecomposer window 02:41:27-02:52:32, and the run
-- journal recorded the imbalance at write time:
--
--   source                    entities     physicalities
--   OMWDecomposer            5,111,969     6,006,582     <- +894,613
--   CILIDecomposer           2,212,105     2,212,105        1:1
--   WordFrameNetDecomposer      16,524        16,524        1:1
--   ChessOpenings               15,831        15,710        fewer
--   ChessPgn                    85,304        80,329        fewer
--
-- Entities without physicalities is normal. The inverse is not: identity is
-- written before projection, so a projection with no identity behind it means
-- the identity write was skipped or lost. Every other lane is 1:1 or has fewer
-- physicalities; OMW and SemLink are the only two that invert.
--
-- The runs reported status=ok and the document consensus gate passed. Nothing
-- asserted this invariant, and FKs from physicalities to entities are dropped by
-- design ("Referential integrity is structural (content-addressed ids)") --
-- which guarantees that a row present is the right row, and nothing about a row
-- being present at all.
--
-- Costs nothing: both counts are already columns on ingest_run_journal, so this
-- is a catalog-speed read, not the 4.3 s anti-join over physicalities.
--
-- BEGIN ATOMIC, not AS $$ (G12 / GH #764): the body parses at CREATE time and
-- records pg_depend on ingest_run_journal, so a column rename there fails here
-- rather than at the first call after a reseed.
DROP FUNCTION IF EXISTS ops.ingest_integrity_gate(timestamptz);
CREATE OR REPLACE FUNCTION ops.ingest_integrity_gate(p_since timestamptz DEFAULT NULL)
RETURNS TABLE(run_id        uuid,
              source_name   text,
              started_at    timestamptz,
              entities      bigint,
              physicalities bigint,
              orphaned      bigint,
              status        text)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT j.run_id, j.source_name, j.started_at,
           j.entities, j.physicalities,
           (j.physicalities - j.entities),
           j.status
    FROM laplace.ingest_run_journal j
    WHERE j.physicalities > j.entities
      AND (p_since IS NULL OR j.started_at >= p_since)
    ORDER BY (j.physicalities - j.entities) DESC;
END;

COMMENT ON FUNCTION ops.ingest_integrity_gate(timestamptz) IS
    'Runs that wrote more physicalities than entities. Non-empty = orphaned '
    'projections with no identity behind them; documents containing them render NULL.';


-- ops.orphan_physicality_count — the direct measurement, for when the journal is
-- not trusted or the rows predate it. Full anti-join: ~4.3 s at 15.6M rows.
DROP FUNCTION IF EXISTS ops.orphan_physicality_count();
CREATE OR REPLACE FUNCTION ops.orphan_physicality_count()
RETURNS bigint
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT count(*)
    FROM laplace.physicalities p
    WHERE NOT EXISTS (SELECT 1 FROM laplace.entities e WHERE e.id = p.entity_id);
END;

COMMENT ON FUNCTION ops.orphan_physicality_count() IS
    'Physicalities whose entity_id has no entities row. Must be 0.';
-- ops.render_trace — why did realize.render_text(id) return NULL?
--
-- render_node (generate_walk.c:1104-1126) accumulates children into one buffer
-- and discards ALL of it if any single child fails to resolve:
--
--     if (child_text != NULL)  append child_text
--     else if (!append_codepoint_render(&out, kids[r].child))  ok = false;
--     ...
--     e->text = ok ? out.data : NULL;
--
-- NULL then propagates to the root, so one unresolvable constituent out of
-- thirty makes an entire document unreadable at any p_max_depth. That is the
-- CORRECT behaviour -- rendering the other twenty-nine would manufacture
-- content with a valid hash, which is the one thing a provenance substrate
-- must not do. Abstention is the design (see "softmax can be zero").
--
-- What was missing is the diagnosis. render_text returns NULL and says nothing
-- about which constituent killed it, so the only way to find out was a manual
-- LEFT JOIN against the trajectory, one document at a time. MEASURED
-- 2026-08-12: three tier-4 documents with n_constituents=5 returned NULL at
-- both depth 8 and depth 32; ordinals 1 and 5 had no laplace.entities row.
-- Those are two of the 899,179 orphaned physicalities (ops.ingest_integrity_gate).
--
-- realize.render_gaps() does not answer this: it scans consensus for globally
-- unnameable ids, not the constituent closure of one entity.
--
-- Cost discipline: realize.codepoint_for_id is the expensive call, so it fires
-- only on rows the cheap entity join could not already classify, and labels
-- resolve through ONE converse.label_or_hex_batch rather than N scalar calls
-- (measured 2026-08-12: the scalar form is ~42 ms per call).
--
-- BEGIN ATOMIC, not AS $$ (G12 / GH #764). Codepoints render through to_hex
-- alone -- G14 bans lower()/upper()/initcap() anywhere on the read path, and
-- the conventional uppercase of "U+00E9" is not worth a case fold that is
-- Latin-shaped and silently a no-op for most of the codespace. Internal aliases
-- avoid the RETURNS TABLE column names, which are OUT parameters in scope over
-- an atomic body.
DROP FUNCTION IF EXISTS ops.render_trace(bytea, integer, boolean);
CREATE OR REPLACE FUNCTION ops.render_trace(
    p_entity        bytea,
    p_max_depth     integer DEFAULT 32,
    p_failures_only boolean DEFAULT true
)
RETURNS TABLE(
    parent_id  bytea,
    ordinal    integer,
    child_id   bytea,
    tier       smallint,
    label      text,
    verdict    text
)
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH clo AS (
        SELECT c.parent_id AS pid, c.ordinal AS ord, c.child_id AS cid
        FROM realize.constituents_closure(ARRAY[p_entity], p_max_depth) c
    ),
    -- Cheap pass first: an id with no entities row is an orphan and needs no
    -- further probing. An id that carries a trajectory renders by recursion.
    cheap AS (
        SELECT clo.pid, clo.ord, clo.cid, e.tier AS etier,
               (e.id IS NOT NULL) AS has_entity,
               EXISTS (SELECT 1 FROM laplace.v_word_points w
                       WHERE w.id = clo.cid AND w.trajectory IS NOT NULL) AS has_traj
        FROM clo
        LEFT JOIN laplace.entities e ON e.id = clo.cid
    ),
    -- codepoint_for_id only for rows still undecided: real entity, no trajectory.
    resolved AS (
        SELECT cheap.pid, cheap.ord, cheap.cid, cheap.etier,
               cheap.has_entity, cheap.has_traj,
               CASE WHEN cheap.has_entity AND NOT cheap.has_traj
                    THEN realize.codepoint_for_id(cheap.cid)
               END AS cp
        FROM cheap
    ),
    verdicted AS (
        SELECT r.pid, r.ord, r.cid, r.etier,
               CASE
                 WHEN NOT r.has_entity
                   THEN 'ORPHAN: physicality exists, no laplace.entities row'::text
                 WHEN r.has_traj
                   THEN 'ok: composed, renders by recursion'::text
                 WHEN r.cp IS NOT NULL
                   THEN ('ok: codepoint U+' || lpad(to_hex(r.cp), 4, '0'))::text
                 ELSE 'UNRENDERABLE: entity exists, no trajectory, no codepoint'::text
               END AS vd
        FROM resolved r
    ),
    kept AS (
        SELECT verdicted.pid, verdicted.ord, verdicted.cid,
               verdicted.etier, verdicted.vd
        FROM verdicted
        WHERE NOT p_failures_only OR verdicted.vd NOT LIKE 'ok:%'
    ),
    -- One batched label call over the surviving ids, joined back positionally.
    bag AS (
        SELECT array_agg(DISTINCT kept.cid) AS arr FROM kept
    ),
    labs AS (
        SELECT u.id AS lid, (l.res)[u.n] AS lbl
        FROM bag
        CROSS JOIN LATERAL (SELECT converse.label_or_hex_batch(bag.arr) AS res) l
        CROSS JOIN LATERAL unnest(bag.arr) WITH ORDINALITY AS u(id, n)
        WHERE bag.arr IS NOT NULL
    )
    SELECT kept.pid, kept.ord, kept.cid, kept.etier, labs.lbl, kept.vd
    FROM kept LEFT JOIN labs ON labs.lid = kept.cid
    ORDER BY kept.pid, kept.ord;
END;

-- The text below deliberately does not spell the scalar realizer name followed
-- by an open paren. ISA gate G2 (RenderBeforeSelectGateTests) regexes the whole
-- file with SQL comments stripped but STRING LITERALS PRESERVED, so naming it
-- here registers as a row-producing scalar call this function does not make --
-- and the gate pins the repository total at exactly 17.
COMMENT ON FUNCTION ops.render_trace(bytea, integer, boolean) IS
    'Why a render of this entity came back NULL: the constituent closure with a '
    'per-child verdict. Non-empty with p_failures_only means assembly aborted on '
    'those rows and discarded everything already accumulated.';
-- Band-masked attention centroid: where an entity's attention through a given
-- band lands on S³. This is the "general area" a concept occupies, as opposed
-- to its own coord, which is a function of its content (the composition of its
-- codepoints) and therefore says nothing about meaning — 'dog' and its
-- translations have unrelated coords by construction. The centroid over a
-- semantic band is where they converge.
--
-- Signature changed 2026-08-04: `concentration` added, so DROP before CREATE.
-- CREATE OR REPLACE cannot alter a return type.
-- FIX 1 (2026-08-04) — the band filter used to ask `laplace.entities` which band a
-- RELATION TYPE belongs to:
--
--     SELECT e.id FROM laplace.entities e
--     WHERE e.highway_mask IS NOT NULL
--       AND consensus.highway_mask_bits(e.highway_mask)
--           && consensus.highway_mask_bits(p_band_mask)
--
-- then joined that to consensus.type_id. A highway mask records which bands an
-- entity has EDGES IN; it is not a statement about which band a type BELONGS
-- TO. That is consensus.relation_highway_bit(type_id), from the manifest. Measured: the
-- CTE matched 0 rows for laplace.word_id('dog') against band 3 while dog carries 9
-- HAS_SENSE (bit 112) and 8 IS_SYNONYM_OF (bit 153), both band 3. Zero rows in,
-- NULL out, no error — on every call this function had ever served. It was also
-- a full scan of 4.34M laplace.entities with a set-returning function evaluated per row,
-- to build a set the manifest already determines and that has at most 233
-- members. GH #866.
--
-- FIX 2 (2026-08-04) — the mean is now projected back onto the sphere.
-- SUM(coord*w)/SUM(w) is the arithmetic mean of unit vectors, which is NOT a
-- unit vector: it lies strictly inside S³, and at the exact origin for an
-- antipodal pair. Measured immediately after FIX 1 landed, laplace.word_id('dog') band 3:
--
--     cx -0.00488  cy 0.03184  cz -0.22988  cm 0.15099   ||c|| = 0.27691
--
-- 0.277, not 1.0 — so every angular distance taken to that point was not an
-- angle, and laplace_forward_step was feeding it to a KNN over points that DO
-- lie on the sphere. The correct object is the Fréchet/Karcher mean under
-- geodesic distance; normalizing the weighted Euclidean sum is its standard
-- cheap approximation, exact for tightly clustered inputs and monotone
-- elsewhere.
--
-- The discarded norm is not noise — it is CONCENTRATION. 1.0 means every
-- attended point coincides; ~0 means they cancel, i.e. the entity attends in
-- every direction at once and its centroid carries no information. Returned
-- rather than thrown away, because "the centroid is meaningless here" is a
-- distinct answer from "the centroid is over there" and callers must be able to
-- tell them apart.
--
-- Degenerate case: norm = 0 (perfect cancellation, or a single antipodal pair)
-- has NO defined direction. Coordinates come back NULL with concentration 0 —
-- never a fabricated direction, and never a silent division by zero.
--
-- No SET search_path: it blocks inlining (pg_proc.proconfig, checked at
-- clauses.c:5168 for the set-returning path). Every reference is
-- schema-qualified instead. GH #860.
DROP FUNCTION IF EXISTS laplace.laplace_attention_centroid(bytea, bytea);
CREATE OR REPLACE FUNCTION generation.attention_centroid(
    p_entity   bytea,
    p_band_mask bytea)
RETURNS TABLE(cx float8, cy float8, cz float8, cm float8,
              total_weight float8, concentration float8)
LANGUAGE sql STABLE PARALLEL RESTRICTED AS $$
    WITH band_bits AS MATERIALIZED (
        SELECT consensus.highway_mask_bits(p_band_mask) AS bits
    ),
    attended AS (
        SELECT c.object_id,
               consensus.eff_mu(c.rating, c.rd)::float8 AS w
        FROM laplace.consensus c
        CROSS JOIN band_bits b
        WHERE c.subject_id = p_entity
          AND c.object_id IS NOT NULL
          AND consensus.relation_highway_bit(c.type_id) = ANY (b.bits)
          AND consensus.eff_mu(c.rating, c.rd) > 0
    ),
    weighted AS (
        SELECT w.coord, a.w
        FROM attended a
        JOIN laplace.v_word_points w ON w.id = a.object_id
        WHERE w.coord IS NOT NULL
    ),
    -- THIRD centroid path in this system, kept deliberately (GH #906 item 4).
    -- public.laplace_centroid_4d and the composer's math4d_centroid both exist and
    -- neither answers this: they take unweighted point sets, and this is a
    -- CONSENSUS-WEIGHTED mean -- each coordinate scaled by its edge's rated mass,
    -- normalized by total weight, then projected back onto the unit 3-sphere.
    -- Substituting either would silently drop the weighting, which IS the operation.
    --
    -- The parity that DOES hold, and the one a reader should check if this moves:
    -- with all weights equal this reduces exactly to math4d_centroid's arithmetic
    -- mean followed by its normalize step. Equal weights are the degenerate case, so
    -- any divergence there is a defect in one of the two, not a semantic difference.
    -- Unpinned by a test because no fixture yet builds an equal-weight attended set;
    -- that fixture is the missing gate, not a different centroid.
    summed AS (
        SELECT SUM(ST_X(coord) * w) / NULLIF(SUM(w), 0) AS mx,
               SUM(ST_Y(coord) * w) / NULLIF(SUM(w), 0) AS my,
               SUM(ST_Z(coord) * w) / NULLIF(SUM(w), 0) AS mz,
               SUM(ST_M(coord) * w) / NULLIF(SUM(w), 0) AS mm,
               SUM(w)                                   AS tw
        FROM weighted
    ),
    normed AS (
        SELECT s.*, sqrt(s.mx*s.mx + s.my*s.my + s.mz*s.mz + s.mm*s.mm) AS n
        FROM summed s
    )
    SELECT CASE WHEN n > 0 THEN mx / n END,
           CASE WHEN n > 0 THEN my / n END,
           CASE WHEN n > 0 THEN mz / n END,
           CASE WHEN n > 0 THEN mm / n END,
           tw,
           COALESCE(n, 0)
    FROM normed
$$;
-- Nearest laplace.entities to a 4D point, optionally scoped by relation band and tier.
--
-- TIER SCOPE (added 2026-08-05, GH #868). laplace.v_word_points spans every tier and
-- exposes `tier`; this read had no tier predicate, so a step from a word could
-- land on a codepoint, a sentence or a document with nothing saying which was
-- meant.
--
-- Scope MUST come from laplace.entities.tier, never from a radius band. Two structural
-- facts, both from the code rather than from any seed:
--
--   * tier 0 coords are placed by super_fibonacci directly ON the unit sphere.
--     Every codepoint sits at radius exactly 1, and they are the only inhabitants
--     of that shell.
--   * tier > 0 coord is math4d_centroid of the realize.constituents — a weighted mean of
--     unit vectors, which is not a unit vector. Composed laplace.entities are interior,
--     and how far interior tracks how DISPERSED their realize.constituents are, not how
--     deep the tier is.
--
-- So radius reveals dispersion, not depth: the composed tiers overlap each other
-- across essentially the whole interval and cannot be separated by it. The single
-- clean consequence is that any comparison point lying on the shell is searching a
-- neighbourhood only tier 0 occupies — which is how a normalized attention
-- centroid started returning a two-character entity for a step from 'dog'.
--
-- p_tiers NULL keeps the previous behaviour (every tier), so existing callers are
-- unchanged. It is a SCOPE, not a floor — spec 37 L6 forbids operator thresholds
-- and this adds none.
--
-- EXACT INDEXED ANGULAR ORDER. Previously the SELECT reported
-- laplace_l2_sq() against an SRID-less point while the ORDER BY ranked on <<->>
-- against ST_SetSRID(...,0) — two expressions on two scales, so the number
-- returned did not explain the order.
--
-- Reporting <<->> for both would agree, but would still be wrong as a metric.
-- <<->> is Euclidean — a CHORD. On the unit sphere chord and geodesic satisfy
-- d = 2*sin(theta/2), monotone in theta, so ordering by chord ORDERS BY ANGLE
-- **only when every candidate has the same radius**. They do not: tier 0 sits at
-- radius exactly 1 (super_fibonacci places codepoints on the sphere) while every
-- composed coord is a centroid and therefore interior. Across mixed radii, chord
-- order is a blend of angle and radius, and the radius half is dispersion of
-- realize.constituents rather than anything semantic.
--
-- laplace_direction_4d projects every non-zero coordinate onto S3. Chord distance
-- between those unit directions is strictly monotone with angular distance, so
-- physicalities_direction_gist supplies the exact angular order directly. No
-- guessed candidate pool or second ranking pass remains.
--
-- Rule #4 / L2: the comparison point must reach the planner as a bound parameter
-- or the GiST KNN silently degrades to a scan. A caller passing a
-- correlated LATERAL reference does NOT satisfy that — EXPLAIN before trusting
-- the index.
DROP FUNCTION IF EXISTS laplace.laplace_nearest_entity(float8, float8, float8, float8, integer, bytea, smallint[]);
CREATE OR REPLACE FUNCTION generation.nearest_entity(
    p_cx float8, p_cy float8, p_cz float8, p_cm float8,
    p_k integer DEFAULT 1,
    p_band_mask bytea DEFAULT NULL,
    p_tiers smallint[] DEFAULT NULL)
RETURNS TABLE(entity_id bytea, distance float8)
LANGUAGE sql STABLE PARALLEL RESTRICTED AS $$
    WITH nearest AS (
        SELECT w.id, w.coord,
               public.laplace_direction_4d(w.coord) <<->>
               public.laplace_direction_4d(public.ST_SetSRID(
                   public.ST_MakePoint(p_cx, p_cy, p_cz, p_cm), 0)) AS chord
        FROM laplace.v_word_points w
        WHERE public.laplace_direction_4d(w.coord) IS NOT NULL
          AND public.laplace_direction_4d(public.ST_SetSRID(
                  public.ST_MakePoint(p_cx, p_cy, p_cz, p_cm), 0)) IS NOT NULL
          AND (p_band_mask IS NULL
               OR consensus.highway_match(w.highway_mask, p_band_mask))
          AND (p_tiers IS NULL OR w.tier = ANY (p_tiers))
        ORDER BY public.laplace_direction_4d(w.coord)
                 <<->> public.laplace_direction_4d(public.ST_SetSRID(
                     public.ST_MakePoint(p_cx, p_cy, p_cz, p_cm), 0))
        LIMIT p_k
    )
    SELECT nearest.id,
           public.laplace_angular_distance_4d(
               nearest.coord,
               public.ST_SetSRID(public.ST_MakePoint(p_cx, p_cy, p_cz, p_cm), 0))
    FROM nearest
    ORDER BY nearest.chord, nearest.id
$$;
DROP FUNCTION IF EXISTS laplace.laplace_astar_path(bytea, bytea, bytea[], integer, bool);
CREATE OR REPLACE FUNCTION generation.astar_path(
    p_source bytea, p_target bytea,
    p_type_ids bytea[] DEFAULT NULL,
    p_max_depth integer DEFAULT NULL,
    p_use_geometry bool DEFAULT false)
RETURNS TABLE(step integer, entity_id bytea, g float8)
LANGUAGE sql STABLE AS $$
    SELECT step, entity_id, g
    FROM converse.astar_path_raw(
        p_source,
        ARRAY[p_target],
        p_type_ids,
        p_max_depth,
        false,
        p_use_geometry)
$$;
-- One hop of the forward pass: from an entity, through a relation band, to the
-- entity nearest that band's attention centroid.
--
-- TIER SCOPE (2026-08-05, GH #868). The step now stays at the subject's own tier.
-- A forward step is a move among peers — word to word, sentence to sentence.
-- Previously the KNN ran over every tier in laplace.v_word_points with no tier predicate,
-- so a step from a word could land on a codepoint, a sentence or a document.
--
-- That was not theoretical. This function could never return a row at all: its
-- `WHERE c.total_weight > 0` was evaluated against a centroid that was NULL on
-- every call (GH #866), so the forward path was dead from the day it was written.
-- When #866 made the centroid real and c2bc4c55 projected it back onto S³ as a
-- proper Fréchet/Karcher mean, the comparison point moved from the interior onto
-- the unit shell — the one neighbourhood tier 0 occupies exclusively, since
-- super_fibonacci seeds codepoints at radius exactly 1 while every composed coord
-- is a centroid and therefore interior. The first thing this ever returned for
-- 'dog' was a two-character entity.
--
-- NO THRESHOLD. laplace_attention_centroid now also returns `concentration` — 1.0
-- when every attended point coincides, approaching 0 when they cancel and the
-- centroid has no direction at all. It is deliberately NOT used here as a cutoff:
-- spec 37 L6 forbids operator floors, and "abstain below 0.3" would be exactly
-- that. The one case handled is the genuinely degenerate one — concentration 0
-- yields NULL coordinates, because a cancelled sum has no direction to point in,
-- and abstaining there is a fact about the data rather than a tuned threshold.
--
-- No SET search_path (GH #860). This body is scalar and carries a FROM clause, so
-- the scalar inliner rejects it either way; the clause is unjustified regardless
-- and its presence would be one more site for the sweep.
DROP FUNCTION IF EXISTS laplace.laplace_forward_step(bytea, bytea);
CREATE OR REPLACE FUNCTION generation.forward_step(
    p_entity   bytea,
    p_band_mask bytea)
RETURNS bytea
LANGUAGE sql STABLE PARALLEL RESTRICTED AS $$
    SELECT n.entity_id
    FROM generation.attention_centroid(p_entity, p_band_mask) c
    JOIN LATERAL generation.nearest_entity(
             c.cx, c.cy, c.cz, c.cm, 1, p_band_mask,
             ARRAY[generation.entity_tier_of(p_entity)::smallint]) n ON TRUE
    WHERE c.total_weight > 0
      AND c.cx IS NOT NULL          -- concentration 0 => no direction => abstain
      AND n.entity_id IS NOT NULL
      AND n.entity_id <> p_entity
    -- No LIMIT: the k argument to laplace_nearest_entity IS the cap (k = 1), and
    -- the KNN ranks before it cuts. A trailing LIMIT 1 read as a safeguard over an
    -- unordered pick, which is the opposite of what this call does -- and it could
    -- not have guarded the one real edge case anyway, since the self-match filter
    -- runs after the k = 1 pick and correctly yields no row.
$$;
DROP FUNCTION IF EXISTS laplace.laplace_distill(bytea, float8);
CREATE OR REPLACE FUNCTION generation.distill(
    p_band_mask  bytea,
    p_min_eff_mu float8 DEFAULT 0.5)
RETURNS TABLE(subject_id bytea, type_id bytea, object_id bytea, eff_mu float8)
LANGUAGE sql STABLE PARALLEL RESTRICTED AS $$
    WITH band_types AS (
        SELECT id FROM unnest(consensus.relation_mask_types(p_band_mask)) AS t(id)
    )
    SELECT c.subject_id, c.type_id, c.object_id,
           (consensus.eff_mu(c.rating, c.rd)::float8 / 1e9) AS eff_mu
    FROM laplace.consensus c
    JOIN band_types bt ON bt.id = c.type_id
    WHERE c.object_id IS NOT NULL
      -- Compare the BARE bigint consensus.eff_mu(= rating-2*rd, the indexed expression of
      -- consensus_eff_mu_btree) against a once-computed bigint threshold, instead of
      -- `consensus.eff_mu::float8/1e9 >= p_min` which wraps the column in ::float8/1e9 and defeats the
      -- functional index → whole-consensus scan. EXACT: consensus.eff_mu is integer, so
      -- `consensus.eff_mu::float8/1e9 >= p_min` ⟺ `consensus.eff_mu >= p_min*1e9` ⟺ `consensus.eff_mu >= ceil(p_min*1e9)`.
      AND consensus.eff_mu(c.rating, c.rd) >= ceil(p_min_eff_mu * 1e9)::bigint
    ORDER BY c.subject_id, consensus.eff_mu(c.rating, c.rd) DESC
$$;
-- RETIRED: consensus is derived state, not a cache that inference may delete
-- independently of testimony. Direct DELETE makes the graph disagree with its
-- surviving attestations and requires an out-of-band refold to become truthful
-- again. No caller exists; remove the executable alternate implementation while
-- preserving upgrade cleanup.
DROP FUNCTION IF EXISTS generation.prune(bigint, boolean);
DROP FUNCTION IF EXISTS laplace.laplace_prune(bigint, boolean);
DROP FUNCTION IF EXISTS laplace.laplace_witness(bytea, bytea, bytea, bytea, bigint);
CREATE OR REPLACE FUNCTION generation.witness(
    p_subject  bytea, p_type  bytea, p_object  bytea,
    p_source   bytea,
    p_score_fp1e9 bigint DEFAULT 1000000000)
RETURNS void
LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    v_affected bigint;
BEGIN
    -- One observation follows the same keyed, row-locked, native fold path as
    -- corpus ingest.  The historical hand-written id-only SELECT/UPDATE opened
    -- every LIST/HASH leaf and also duplicated the fold implementation.
    SELECT consensus.upsert_type(
        p_type,
        ARRAY[p_subject]::bytea[],
        ARRAY[p_object]::bytea[],
        ARRAY[consensus.glicko2_initial_rd()]::bigint[],
        ARRAY[1::bigint],
        ARRAY[p_score_fp1e9]::bigint[],
        ARRAY[now()]::timestamptz[])
    INTO v_affected;
END;
$$;
-- RETIRED: consensus is derived from durable attestations. A function that
-- directly mutates one consensus leaf creates state no witness can reproduce and
-- bypasses the canonical fold/refold law. No caller exists in SQL, C, app,
-- scripts, or tests; keep the upgrade surface as DROP-only so old installations
-- lose the hazardous alternate implementation.
DROP FUNCTION IF EXISTS generation.decay(bytea, bytea, bytea, float8);
DROP FUNCTION IF EXISTS laplace.laplace_decay(bytea, bytea, bytea, float8);
DROP FUNCTION IF EXISTS laplace.chess_outcome(boolean, bytea);
CREATE OR REPLACE FUNCTION chess.outcome(p_as_white boolean, p_result bytea)
    RETURNS smallint
    LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    -- The one place a game header becomes an outcome for ONE of its two players.
    -- A game's HAS_RESULT object is the verbatim PGN result token the decomposer
    -- recorded as content ("1-0" / "0-1" / "1/2-1/2"); which of Win/Draw/Loss
    -- that is depends entirely on the colour the player held. Every chess read
    -- that counts a record -- chess_player_record, chess_leaderboard,
    -- chess_opponents -- resolves it through here, so W/L/D is defined once.
    --
    -- The returned domain is {0 Loss, 1 Draw, 2 Win}: the attestation outcome
    -- enum, bit-identical to PlyOutcome by design. NULL means the source never
    -- asserted a result (an abandoned or untagged game) -- an abstention, not a
    -- draw, and never counted as one.
    SELECT CASE
        WHEN p_result = laplace.word_id('1/2-1/2') THEN 1::smallint
        WHEN p_result = laplace.word_id('1-0')
            THEN (CASE WHEN p_as_white THEN 2 ELSE 0 END)::smallint
        WHEN p_result = laplace.word_id('0-1')
            THEN (CASE WHEN p_as_white THEN 0 ELSE 2 END)::smallint
        ELSE NULL
    END
$$;
DROP FUNCTION IF EXISTS laplace.chess_player_id(text);
CREATE OR REPLACE FUNCTION chess.player_id(p_name text)
    RETURNS bytea
    LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    -- Name -> player entity id, O(1), no scan. The chess decomposer mints a
    -- player as realize.canonical_id('chess/player/' || PlayerAlias.Canonical(name)):
    -- "Last, First" is flipped to "First Last", lowercased, punctuation folded
    -- to spaces, runs of whitespace collapsed. This is that same normalisation,
    -- so a typed name resolves to the identical content-addressed id the
    -- ingest wrote -- an entity lookup, never an entity-resolution pass.
    --
    -- The C# original folds [^\p{L}\p{N}\s]+; POSIX [:alnum:] is the collation's
    -- letter/number class, which agrees with \p{L}\p{N} on every accented Latin
    -- name in the corpus (pinned by chess_read regress).
    SELECT realize.canonical_id('chess/player/' || btrim(regexp_replace(
        regexp_replace(
            lower(CASE
                WHEN strpos(btrim(p_name), ',') > 0
                    THEN btrim(substr(btrim(p_name), strpos(btrim(p_name), ',') + 1))
                         || ' ' ||
                         btrim(substr(btrim(p_name), 1, strpos(btrim(p_name), ',') - 1))
                ELSE btrim(p_name)
            END),
            '[^[:alnum:][:space:]]+', ' ', 'g'),
        '[[:space:]]+', ' ', 'g')))
$$;
DROP FUNCTION IF EXISTS laplace.chess_player_record(bytea);
CREATE OR REPLACE FUNCTION chess.player_record(p_player bytea)
    RETURNS TABLE(as_white boolean, games bigint, wins bigint, draws bigint,
                  losses bigint, unscored bigint, score double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- One player's record, straight off the witnessed game headers. Rides
    -- attestations_rdefault_object_id_idx to find the games he appears in (as
    -- HAS_WHITE or HAS_BLACK), then the (subject_id, type_id, object_id) index
    -- to pick up each game's HAS_RESULT -- both index lookups, so this stays
    -- interactive for a 9k-game career.
    --
    -- PLAYER-ID MIGRATION LAW (#1405): a playing can already be present while
    -- the governed player-id encoding changed later. The playing novelty gate
    -- correctly refuses to re-witness that source record, so a replay cannot
    -- repair old HAS_WHITE/HAS_BLACK rows by emitting them again. Career reads
    -- therefore admit ONLY the deterministic ChessPgn legacy-id bridge emitted
    -- by ChessPgnDecomposer.EmitPlayer. CORRESPONDS_TO is symmetric, so probe
    -- both indexed directions. This is not fuzzy/name identity and deliberately
    -- does not walk profile-provider or arbitrary CORRESPONDS_TO testimony.
    --
    -- GROUPING SETS emits three rows: as_white = true, false, and NULL for the
    -- career total, so every number on a player page comes from one pass over
    -- the same evidence and the splits can never disagree with the total.
    --
    -- score is the chess convention -- (wins + draws/2) / scored games -- over
    -- games the source actually scored; `unscored` reports the abstentions
    -- separately rather than silently folding them in as losses.
    -- GH #736: a colour header subjects on the shared LINE with context = the
    -- PLAYING, so the result join threads both -- the line finds the rows, the
    -- context pins each to its own playing (a shared line must not cross one
    -- playing's result onto another's appearance).
    WITH identity_ids AS MATERIALIZED (
        SELECT p_player AS id
        UNION
        SELECT a.object_id
        FROM laplace.attestations a
        WHERE a.subject_id = p_player
          AND a.object_id IS NOT NULL
          AND a.type_id = ANY (consensus.relation_set_ids('CHESS_PROFILE_IDENTITY'))
          AND a.source_id = laplace.source_id('ChessPgn')
          AND a.context_id IS NULL
        UNION
        SELECT a.subject_id
        FROM laplace.attestations a
        WHERE a.object_id = p_player
          AND a.type_id = ANY (consensus.relation_set_ids('CHESS_PROFILE_IDENTITY'))
          AND a.source_id = laplace.source_id('ChessPgn')
          AND a.context_id IS NULL
    ),
    sides AS (
        SELECT a.subject_id AS line,
               a.context_id AS event,
               (a.type_id = laplace.relation_type_id('HAS_WHITE')) AS white
        FROM laplace.attestations a
        JOIN identity_ids i ON i.id = a.object_id
        WHERE a.context_id IS NOT NULL
          AND a.type_id IN (laplace.relation_type_id('HAS_WHITE'),
                            laplace.relation_type_id('HAS_BLACK'))
    ),
    scored AS (
        SELECT s.white,
               chess.outcome(s.white, r.object_id) AS outcome
        FROM sides s
        LEFT JOIN laplace.attestations r
               ON r.subject_id = s.line
              AND r.context_id = s.event
              AND r.type_id = laplace.relation_type_id('HAS_RESULT')
    )
    SELECT sc.white,
           count(*)::bigint,
           count(*) FILTER (WHERE sc.outcome = 2)::bigint,
           count(*) FILTER (WHERE sc.outcome = 1)::bigint,
           count(*) FILTER (WHERE sc.outcome = 0)::bigint,
           count(*) FILTER (WHERE sc.outcome IS NULL)::bigint,
           (count(*) FILTER (WHERE sc.outcome = 2)
            + count(*) FILTER (WHERE sc.outcome = 1) / 2.0)
           / NULLIF(count(*) FILTER (WHERE sc.outcome IS NOT NULL), 0)
    FROM scored sc
    GROUP BY GROUPING SETS ((sc.white), ())
    ORDER BY sc.white NULLS FIRST
$$;
DROP FUNCTION IF EXISTS laplace.chess_player_ratings(bytea);
CREATE OR REPLACE FUNCTION chess.player_ratings(p_player bytea)
    RETURNS TABLE(rating integer, games bigint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Every Elo this player has been witnessed at, and how many games carried
    -- it. HAS_RATING is a per-game assertion -- context_id is the game the tag
    -- came from -- so a career is a distribution, not a single number, and the
    -- caller can take the peak, the mode, or plot the lot.
    --
    -- This is the SOURCE's Elo, transcribed: a number some federation or server
    -- computed elsewhere and the PGN carried. It is not the substrate's own
    -- rating of the player, which is the Glicko-2 fold over his attested edges
    -- and lives in consensus. Two different claims by two different raters,
    -- deliberately kept apart.
    --
    -- Non-numeric rating tags are skipped rather than coerced: a malformed tag is
    -- an unreadable witness, not a zero.
    WITH raw AS MATERIALIZED (
        SELECT a.object_id AS rating_id, count(*)::bigint AS games
        FROM laplace.attestations a
        WHERE a.subject_id = p_player
          AND a.type_id = laplace.relation_type_id('HAS_RATING')
        GROUP BY a.object_id
    ),
    batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(rating_id ORDER BY rating_id), '{}'::bytea[]) AS ids FROM raw
    ),
    named AS (
        SELECT p.id, p.txt
        FROM batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS p(id, txt)
    )
    SELECT n.txt::integer, raw.games
    FROM raw JOIN named n ON n.id = raw.rating_id
    WHERE n.txt ~ '^[0-9]{1,5}$'
    ORDER BY 1 DESC
$$;
-- Profile testimony asserted directly about the requested player identity plus provider
-- identities explicitly associated by a witnessed, context-bearing link.
--
-- Historical name-derived CORRESPONDS_TO rows were contextless. They are deliberately
-- excluded here: equal names are candidate referents, not identity. New explicit Lab
-- associations carry a deterministic provenance context, so the read can materialize the
-- selected provider profile without reopening the old contamination path.
--
-- Source and relation predicates are applied before rendering or ordering, so game volume
-- cannot crowd profile data out of this read.
CREATE OR REPLACE FUNCTION chess.player_profile_edges(p_player bytea)
    RETURNS TABLE(subject_id bytea, type_id bytea, object_id bytea)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH identity_ids(id) AS MATERIALIZED (
        SELECT p_player
        UNION
        SELECT a.object_id
        FROM laplace.attestations a
        WHERE a.subject_id = p_player
          AND a.object_id IS NOT NULL
          AND a.context_id IS NOT NULL
          AND a.type_id = ANY (consensus.relation_set_ids('CHESS_PROFILE_IDENTITY'))
          AND a.source_id = ANY (ARRAY[
              laplace.source_id('LichessPlayerProfile'),
              laplace.source_id('ChessComPlayerProfile'),
              laplace.source_id('FidePlayerProfile')
          ]::bytea[])
        UNION
        SELECT a.subject_id
        FROM laplace.attestations a
        WHERE a.object_id = p_player
          AND a.context_id IS NOT NULL
          AND a.type_id = ANY (consensus.relation_set_ids('CHESS_PROFILE_IDENTITY'))
          AND a.source_id = ANY (ARRAY[
              laplace.source_id('LichessPlayerProfile'),
              laplace.source_id('ChessComPlayerProfile'),
              laplace.source_id('FidePlayerProfile')
          ]::bytea[])
    )
    SELECT DISTINCT i.id, a.type_id, a.object_id
    FROM identity_ids i
    JOIN laplace.attestations a ON a.subject_id = i.id
    WHERE a.source_id = ANY (ARRAY[
              laplace.source_id('LichessPlayerProfile'),
              laplace.source_id('ChessComPlayerProfile'),
              laplace.source_id('FidePlayerProfile')
          ]::bytea[])
      AND a.type_id = ANY (consensus.relation_set_ids('CHESS_PROFILE_FACTS'))
    ORDER BY i.id, a.type_id, a.object_id;
END;
-- GH #736 re-key: the key OUT column was renamed (game_id -> event_id), which
-- CREATE OR REPLACE cannot do on the upgrade path.
DROP FUNCTION IF EXISTS laplace.chess_player_games(bytea, integer, integer);
CREATE OR REPLACE FUNCTION chess.player_games(
        p_player bytea, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
    RETURNS TABLE(event_id bytea, played_on text, event text, eco text,
                  as_white boolean, opponent_id bytea, opponent text,
                  result text, outcome smallint)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- A player's game log: the detail list behind chess_player_record, most
    -- recent first. Every field is a header the PGN decomposer transcribed
    -- verbatim (ON_DATE / HAS_EVENT / HAS_ECO / HAS_RESULT) plus the opposite
    -- colour edge for the opponent -- witnessed record only, nothing derived.
    --
    -- PLAYER-ID MIGRATION LAW (#1405): the playing novelty gate prevents an
    -- already-present PGN from being re-witnessed merely because the governed
    -- player-id encoding changed. Admit the exact requested id plus ONLY its
    -- deterministic ChessPgn legacy-id bridge. CORRESPONDS_TO is symmetric, so
    -- use two indexed arms rather than an OR. Provider/profile identity edges
    -- never enter this scope; equal human-readable names are not identity.
    --
    -- GH #736: a game-log row identifies a PLAYING, so the key column is the
    -- EVENT id. Colour headers subject on the shared LINE with context = the
    -- playing, which means every join below threads BOTH the line and the
    -- event: the line finds the header rows, the context pins them to this
    -- playing (a line shared by two playings must not leak one playing's
    -- headers into the other's row).
    --
    -- Ordering is by the playing's own asserted date, which means the career's
    -- dates must be resolved before the page can be cut. That stays cheap
    -- because dates are shared content: every game played on 1960.03.15 carries
    -- the SAME date entity, so a 9k-game career resolves a few thousand distinct
    -- ids in one realize_batch, not 9k renders. Games the source never dated
    -- sort last rather than being dropped.
    --
    -- Everything else renders once, for the page only: opponent, event, eco and
    -- result ids go into a single array and come back through one realize_batch.
    -- Per-row realize.label() here is what made a 1300-game career take 18s.
    WITH identity_ids AS MATERIALIZED (
        SELECT p_player AS id
        UNION
        SELECT a.object_id
        FROM laplace.attestations a
        WHERE a.subject_id = p_player
          AND a.object_id IS NOT NULL
          AND a.type_id = ANY (consensus.relation_set_ids('CHESS_PROFILE_IDENTITY'))
          AND a.source_id = laplace.source_id('ChessPgn')
          AND a.context_id IS NULL
        UNION
        SELECT a.subject_id
        FROM laplace.attestations a
        WHERE a.object_id = p_player
          AND a.type_id = ANY (consensus.relation_set_ids('CHESS_PROFILE_IDENTITY'))
          AND a.source_id = laplace.source_id('ChessPgn')
          AND a.context_id IS NULL
    ),
    mine AS MATERIALIZED (
        SELECT a.subject_id AS line,
               a.context_id AS event,
               (a.type_id = laplace.relation_type_id('HAS_WHITE')) AS white
        FROM laplace.attestations a
        JOIN identity_ids i ON i.id = a.object_id
        WHERE a.context_id IS NOT NULL
          AND a.type_id IN (laplace.relation_type_id('HAS_WHITE'),
                            laplace.relation_type_id('HAS_BLACK'))
    ),
    dated AS MATERIALIZED (
        SELECT m.line, m.event, m.white, d.object_id AS date_id
        FROM mine m
        LEFT JOIN laplace.attestations d
               ON d.subject_id = m.line
              AND d.context_id = m.event
              AND d.type_id = laplace.relation_type_id('ON_DATE')
    ),
    date_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(DISTINCT date_id), '{}'::bytea[]) AS ids
        FROM dated WHERE date_id IS NOT NULL
    ),
    date_text AS MATERIALIZED (
        SELECT p.id, p.txt
        FROM date_batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS p(id, txt)
    ),
    page AS MATERIALIZED (
        SELECT d.line, d.event, d.white, dt.txt AS played_on
        FROM dated d
        LEFT JOIN date_text dt ON dt.id = d.date_id
        ORDER BY dt.txt DESC NULLS LAST, d.event
        LIMIT p_limit OFFSET p_offset
    ),
    facts AS MATERIALIZED (
        SELECT pg.event, pg.white, pg.played_on,
               max(h.object_id) FILTER (
                   WHERE h.type_id = laplace.relation_type_id('HAS_EVENT')) AS event_name_id,
               max(h.object_id) FILTER (
                   WHERE h.type_id = laplace.relation_type_id('HAS_ECO')) AS eco_id,
               max(h.object_id) FILTER (
                   WHERE h.type_id = laplace.relation_type_id('HAS_RESULT')) AS result_id,
               max(h.object_id) FILTER (
                   WHERE h.type_id = CASE WHEN pg.white
                       THEN laplace.relation_type_id('HAS_BLACK')
                       ELSE laplace.relation_type_id('HAS_WHITE') END) AS opponent_id
        FROM page pg
        LEFT JOIN laplace.attestations h
               ON h.subject_id = pg.line
              AND h.context_id = pg.event
              AND h.type_id IN (laplace.relation_type_id('HAS_EVENT'),
                                laplace.relation_type_id('HAS_ECO'),
                                laplace.relation_type_id('HAS_RESULT'),
                                laplace.relation_type_id('HAS_WHITE'),
                                laplace.relation_type_id('HAS_BLACK'))
        GROUP BY pg.event, pg.white, pg.played_on
    ),
    surface_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(DISTINCT s), '{}'::bytea[]) AS ids
        FROM facts f,
             LATERAL (VALUES (f.event_name_id), (f.eco_id), (f.result_id), (f.opponent_id)) v(s)
        WHERE s IS NOT NULL
    ),
    surface_text AS MATERIALIZED (
        SELECT p.id, p.txt
        FROM surface_batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS p(id, txt)
    )
    SELECT f.event,
           f.played_on,
           ev.txt,
           ec.txt,
           f.white,
           f.opponent_id,
           COALESCE(NULLIF(op.txt, ''), 'Unrealized player'),
           rs.txt,
           chess.outcome(f.white, f.result_id)
    FROM facts f
    LEFT JOIN surface_text ev ON ev.id = f.event_name_id
    LEFT JOIN surface_text ec ON ec.id = f.eco_id
    LEFT JOIN surface_text rs ON rs.id = f.result_id
    LEFT JOIN surface_text op ON op.id = f.opponent_id
    ORDER BY f.played_on DESC NULLS LAST, f.event
$$;
-- GH #736 re-key: the input parameter was renamed (p_game -> p_event), which
-- CREATE OR REPLACE cannot do on the upgrade path.
DROP FUNCTION IF EXISTS laplace.chess_game(bytea);
-- The movetext column is gone. #1258 stopped storing PGN: a playing's mainline is its
-- line's typed move trajectory, and SAN/PGN is generated by replay at the read edge
-- (SubstrateClient.ChessGameAsync -> ChessReplay.ToMovetext). A column that can only
-- ever return NULL advertises a value the substrate cannot produce. Dropping a column
-- from RETURNS TABLE is not a REPLACE, so the purpose-schema name drops explicitly.
DROP FUNCTION IF EXISTS chess.game(bytea);
CREATE OR REPLACE FUNCTION chess.game(p_event bytea)
    RETURNS TABLE(white_id bytea, white text, black_id bytea, black text,
                  result text, played_on text, event text, eco text,
                  termination text, time_control text, tc_class text)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- One PLAYING, as its source recorded it (GH #736). The parameter is the
    -- playing-EVENT handle; the game CONTENT is the line it plays. Hop 1 follows
    -- the one record edge whose subject is the event -- (event, PLAYS_LINE, line)
    -- -- and every header below is a fact the decomposer subjected on the LINE
    -- with context = this event, so the playing's own headers come back even when
    -- the line is shared by many playings.
    --
    -- Every column here is a header the decomposer transcribed verbatim -- the
    -- record layer, untouched by any analysis. Nothing is replayed, evaluated or
    -- inferred: the calculated layer (positions, evals, motifs) hangs off the
    -- analysis sources and is read through the position surface (chess_moves),
    -- not here.
    --
    -- All headers arrive in one index scan and one realize.batch. Movetext is generated by
    -- managed replay from the playing's typed move trajectory; PGN serialization is not a
    -- substrate content object.
    WITH line AS MATERIALIZED (
        SELECT pl.object_id AS line
        FROM laplace.attestations pl
        WHERE pl.subject_id = p_event
          AND pl.type_id = laplace.relation_type_id('PLAYS_LINE')
        -- event -> line is expected to be unique, but nothing enforces it and a
        -- re-ingest of the same PGN under a second source deposits a second
        -- testimony row. laplace.attestations carry no fold to rank by, so the id is the
        -- tie-break that keeps the pick reproducible instead of scan-ordered.
        ORDER BY pl.object_id
        LIMIT 1
    ),
    hdr AS MATERIALIZED (
        SELECT max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_WHITE')) AS white_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_BLACK')) AS black_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_RESULT')) AS result_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('ON_DATE')) AS date_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_EVENT')) AS event_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_ECO')) AS eco_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_TERMINATION')) AS term_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_TIME_CONTROL')) AS tc_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_TC_CLASS')) AS tcc_id
        FROM line l
        JOIN laplace.attestations a
          ON a.subject_id = l.line
         AND a.context_id = p_event
        WHERE a.type_id IN (laplace.relation_type_id('HAS_WHITE'),
                            laplace.relation_type_id('HAS_BLACK'),
                            laplace.relation_type_id('HAS_RESULT'),
                            laplace.relation_type_id('ON_DATE'),
                            laplace.relation_type_id('HAS_EVENT'),
                            laplace.relation_type_id('HAS_ECO'),
                            laplace.relation_type_id('HAS_TERMINATION'),
                            laplace.relation_type_id('HAS_TIME_CONTROL'),
                            laplace.relation_type_id('HAS_TC_CLASS'))
    ),
    surface_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(DISTINCT s), '{}'::bytea[]) AS ids
        FROM hdr h,
             LATERAL (VALUES (h.white_id), (h.black_id), (h.result_id), (h.date_id),
                             (h.event_id), (h.eco_id), (h.term_id), (h.tc_id),
                             (h.tcc_id)) v(s)
        WHERE s IS NOT NULL
    ),
    surface_text AS MATERIALIZED (
        SELECT p.id, p.txt
        FROM surface_batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS p(id, txt)
    )
    SELECT h.white_id,
           COALESCE(NULLIF(w.txt, ''), 'Unrealized player'),
           h.black_id,
           COALESCE(NULLIF(bl.txt, ''), 'Unrealized player'),
           r.txt, d.txt, ev.txt, ec.txt, tm.txt, tc.txt, tcc.txt
    FROM hdr h
    LEFT JOIN surface_text w   ON w.id   = h.white_id
    LEFT JOIN surface_text bl  ON bl.id  = h.black_id
    LEFT JOIN surface_text r   ON r.id   = h.result_id
    LEFT JOIN surface_text d   ON d.id   = h.date_id
    LEFT JOIN surface_text ev  ON ev.id  = h.event_id
    LEFT JOIN surface_text ec  ON ec.id  = h.eco_id
    LEFT JOIN surface_text tm  ON tm.id  = h.term_id
    LEFT JOIN surface_text tc  ON tc.id  = h.tc_id
    LEFT JOIN surface_text tcc ON tcc.id = h.tcc_id
    WHERE h.white_id IS NOT NULL OR h.black_id IS NOT NULL
       OR EXISTS (SELECT 1 FROM line)
$$;
DROP FUNCTION IF EXISTS laplace.chess_time_pressure_outcome();
CREATE OR REPLACE FUNCTION chess.time_pressure_outcome()
    RETURNS TABLE(
        think_class     text,
        positions       bigint,
        plays           bigint,
        avg_eff_mu      numeric)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- "Do rushed moves lead to worse outcomes?" answered as a READ over the
    -- FOLDED consensus layer — never a query-time aggregation of raw evidence.
    --
    -- Both inputs are already folded at ingest. HAS_THINK_CLASS retains the set of distinct
    -- positions observed under each class; OUTCOME is deposited directly on the reusable
    -- class content id, one observation per classified ply. Exact transitions remain in line
    -- trajectories and are not recreated here as a statistical lookup table.
    -- The earlier evidence-layer form (joining 133M laplace.attestations by game
    -- context_id) timed out at 90s; this is the substrate's own answer: the
    -- adjudication already happened, the read is a lookup (GH #606).
    --
    -- Global (all positions). The per-PLAYER cut ("how does Magnus do when
    -- rushed") is deliberately NOT a query-time recompute either: it wants the
    -- analyzer to fold (player, time-class -> outcome) as its own consensus
    -- cell at ingest, then that read is a single indexed lookup — the same
    -- record-vs-calculate discipline. Tracked as the ingest-fold extension.
    WITH tc AS MATERIALIZED (
        SELECT c.object_id AS class_id, count(DISTINCT c.subject_id)::bigint AS positions
        FROM laplace.consensus c
        WHERE c.type_id = laplace.relation_type_id('HAS_THINK_CLASS')
        GROUP BY c.object_id
    ), outcome AS MATERIALIZED (
        SELECT c.subject_id AS class_id,
               consensus.eff_mu(c.rating, c.rd) AS mu,
               c.witness_count AS plays
        FROM laplace.consensus c
        WHERE c.type_id = ANY (consensus.relation_family_ids('OUTCOME'))
          AND c.object_id = public.laplace_hash128_blake3('Chess_Result')
    ), cls(id, label, ord) AS (
        VALUES
            (laplace.word_id('rushed'), 'rushed', 1),
            (laplace.word_id('normal'), 'normal', 2),
            (laplace.word_id('deep'),   'deep',   3),
            -- Think-time lenses: phase × clock × spent refinements the analyzer
            -- deposits beside the base classes, thresholds from the game's own
            -- clock distribution (ChessCanonical.ThinkLens). Content values on
            -- the same HAS_THINK_CLASS cell shape — no relation change. The
            -- fourth lens (late + fast + low clock) IS the base 'rushed' cell.
            (laplace.word_id('planned_quick'), 'planned_quick', 4),
            (laplace.word_id('pressed_think'), 'pressed_think', 5),
            (laplace.word_id('flagging'),      'flagging',      6)
    )
    SELECT cls.label,
           tc.positions,
           outcome.plays,
           round(consensus.eff_mu_display(outcome.mu, 0)::numeric, 3) AS avg_eff_mu
    FROM tc
    JOIN outcome ON outcome.class_id = tc.class_id
    JOIN cls ON cls.id = tc.class_id
    GROUP BY cls.label, cls.ord, tc.positions, outcome.plays, outcome.mu
    ORDER BY cls.ord
$$;
DROP FUNCTION IF EXISTS laplace.chess_ranked(integer, integer);
DROP FUNCTION IF EXISTS chess.ranked(integer, integer);
DROP FUNCTION IF EXISTS chess.ranked(integer, integer, text, text);

-- Sortable roster core. The two-argument wrapper below preserves the established
-- SQL/API contract while the web reader can request a real server-side order.
CREATE FUNCTION chess.ranked(
        p_limit integer, p_offset integer, p_sort text, p_direction text)
    RETURNS TABLE(rank bigint, player_id bytea, name text, games bigint,
                  rating double precision, rd double precision, eff_mu double precision)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH rated AS MATERIALIZED (
        SELECT e.id AS player,
               COALESCE(c.witness_count, 0) AS games,
               COALESCE(c.rating, consensus.glicko2_neutral_mu()) AS rating,
               COALESCE(c.rd, consensus.glicko2_initial_rd()) AS rd,
               CASE COALESCE(p_sort, 'strength')
                   WHEN 'games'  THEN COALESCE(c.witness_count, 0)::double precision
                   WHEN 'rating' THEN COALESCE(c.rating, consensus.glicko2_neutral_mu())::double precision
                   WHEN 'rd'     THEN COALESCE(c.rd, consensus.glicko2_initial_rd())::double precision
                   ELSE consensus.eff_mu(
                       COALESCE(c.rating, consensus.glicko2_neutral_mu()),
                       COALESCE(c.rd, consensus.glicko2_initial_rd()))::double precision
               END AS sort_value
        FROM laplace.entities e
        LEFT JOIN laplace.consensus c
          ON c.subject_id = e.id
         AND c.type_id = laplace.relation_type_id('OUTCOME')
         -- Player standing has exactly one canonical result cell. Joining only
         -- by subject+relation admitted unrelated/legacy result objects into the
         -- roster and could duplicate one player with a different fold state.
         AND c.object_id = laplace.entity_type_id('Chess_Result')
        WHERE e.type_id = laplace.entity_type_id('Chess_Player')
    ),
    page AS MATERIALIZED (
        -- Apply the bound before numbering. PostgreSQL can use a top-N sort here;
        -- numbering the entire roster first made page one pay for every rank.
        SELECT r.*
        FROM rated r
        ORDER BY
            CASE WHEN COALESCE(p_direction, 'desc') = 'asc'
                 THEN r.sort_value END ASC,
            CASE WHEN COALESCE(p_direction, 'desc') <> 'asc'
                 THEN r.sort_value END DESC,
            r.player
        LIMIT p_limit
        OFFSET p_offset
    ),
    batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(page.player ORDER BY page.player), '{}'::bytea[]) AS ids
        FROM page
    ),
    named AS (
        -- Name the bounded page once. Resolving one player at a time made the
        -- otherwise-indexed roster spend nearly all of its time in rendering.
        SELECT p.id, p.txt
        FROM batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS p(id, txt)
    )
    SELECT (p_offset + row_number() OVER (
               ORDER BY
                   CASE WHEN COALESCE(p_direction, 'desc') = 'asc'
                        THEN page.sort_value END ASC,
                   CASE WHEN COALESCE(p_direction, 'desc') <> 'asc'
                        THEN page.sort_value END DESC,
                   page.player))::bigint,
           page.player,
           COALESCE(NULLIF(n.txt, ''), 'Unrealized player'),
           page.games,
           round((page.rating / 1e9)::numeric, 3)::double precision,
           round((page.rd / 1e9)::numeric, 3)::double precision,
           consensus.eff_mu_display(page.rating, page.rd)::double precision
    FROM page
    LEFT JOIN named n ON n.id = page.player
    ORDER BY
        CASE WHEN COALESCE(p_direction, 'desc') = 'asc'
             THEN page.sort_value END ASC,
        CASE WHEN COALESCE(p_direction, 'desc') <> 'asc'
             THEN page.sort_value END DESC,
        page.player;
END;

CREATE FUNCTION chess.ranked(p_limit integer DEFAULT 200, p_offset integer DEFAULT 0)
    RETURNS TABLE(rank bigint, player_id bytea, name text, games bigint,
                  rating double precision, rd double precision, eff_mu double precision)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    SELECT * FROM chess.ranked(p_limit, p_offset, 'strength', 'desc');
END;
DROP FUNCTION IF EXISTS laplace.chess_players_by_initial(text, integer, integer);
DROP FUNCTION IF EXISTS chess.players_by_initial(text, integer, integer, text, text);
DROP FUNCTION IF EXISTS chess.players_by_initial(text, integer, integer);
DROP FUNCTION IF EXISTS chess.players_by_initial(text[], integer, integer, text, text);

CREATE FUNCTION chess.players_by_initial(
        p_initials text[], p_limit integer, p_offset integer, p_sort text, p_direction text)
    RETURNS TABLE(player_id bytea, name text, games bigint,
                  rating double precision, rd double precision, eff_mu double precision)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    WITH target AS MATERIALIZED (
        SELECT array_agg(DISTINCT laplace.word_id(left(v, 1))) AS cps
        FROM unnest(p_initials) q(v)
        WHERE length(v) > 0
    ),
    name_ids AS MATERIALIZED (
        -- This expression is exactly the physicalities_traj_first_id_btree key.
        SELECT w.id AS name_id
        FROM laplace.v_word_points w, target t
        WHERE w.trajectory IS NOT NULL
          AND (public.laplace_trajectory_constituent_ids(w.trajectory))[1] = ANY (t.cps)
    ),
    players AS MATERIALIZED (
        -- Primary names and aliases are both names. Restricting this to
        -- HAS_NAME_ALIAS hid players whose PGN supplied a primary name (including
        -- Karpov and Fischer) even though the normal label resolver showed them.
        SELECT DISTINCT c.subject_id AS player
        FROM laplace.consensus c
        JOIN name_ids n ON n.name_id = c.object_id
        WHERE c.type_id = ANY (
            consensus.relation_family_ids('HAS_NAME')
            || consensus.relation_family_ids('HAS_NAME_ALIAS'))
    ),
    rated AS MATERIALIZED (
        SELECT p.player,
               COALESCE(o.witness_count, 0) AS games,
               COALESCE(o.rating, consensus.glicko2_neutral_mu()) AS rating,
               COALESCE(o.rd, consensus.glicko2_initial_rd()) AS rd,
               CASE COALESCE(p_sort, 'strength')
                   WHEN 'games'  THEN COALESCE(o.witness_count, 0)::double precision
                   WHEN 'rating' THEN COALESCE(o.rating, consensus.glicko2_neutral_mu())::double precision
                   WHEN 'rd'     THEN COALESCE(o.rd, consensus.glicko2_initial_rd())::double precision
                   ELSE consensus.eff_mu(
                       COALESCE(o.rating, consensus.glicko2_neutral_mu()),
                       COALESCE(o.rd, consensus.glicko2_initial_rd()))::double precision
               END AS sort_value
        FROM players p
        LEFT JOIN laplace.consensus o
          ON o.subject_id = p.player
         AND o.type_id = laplace.relation_type_id('OUTCOME')
         AND o.object_id = laplace.entity_type_id('Chess_Result')
    ),
    page AS MATERIALIZED (
        SELECT r.*
        FROM rated r
        ORDER BY
            CASE WHEN COALESCE(p_direction, 'desc') = 'asc'
                 THEN r.sort_value END ASC,
            CASE WHEN COALESCE(p_direction, 'desc') <> 'asc'
                 THEN r.sort_value END DESC,
            r.player
        LIMIT p_limit
        OFFSET p_offset
    ),
    batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(page.player ORDER BY page.player), '{}'::bytea[]) AS ids
        FROM page
    ),
    surfaced AS (
        SELECT q.id, q.txt
        FROM batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS q(id, txt)
    )
    SELECT page.player,
           COALESCE(NULLIF(s.txt, ''), 'Unrealized player'),
           page.games,
           round((page.rating / 1e9)::numeric, 3)::double precision,
           round((page.rd / 1e9)::numeric, 3)::double precision,
           consensus.eff_mu_display(page.rating, page.rd)::double precision
    FROM page
    LEFT JOIN surfaced s ON s.id = page.player
    ORDER BY
        CASE WHEN COALESCE(p_direction, 'desc') = 'asc'
             THEN page.sort_value END ASC,
        CASE WHEN COALESCE(p_direction, 'desc') <> 'asc'
             THEN page.sort_value END DESC,
        page.player;
END;
DROP FUNCTION IF EXISTS chess.player_search_candidates(text, integer);
DROP FUNCTION IF EXISTS chess.player_search_candidates(text[], integer);
CREATE FUNCTION chess.player_search_candidates(p_queries text[], p_limit integer DEFAULT 600)
    RETURNS TABLE(player_id bytea, name text, games bigint,
                  rating double precision, rd double precision, eff_mu double precision)
    LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
    -- Exact content-address resolution wins.  A caller that supplied an exact
    -- username/name has already named one Chess_Player; broad constituent search
    -- after that point changes a lookup into a guess.  Preserve input order so
    -- the caller's literal form wins over its derived canonical/compact forms.
    WITH exact AS MATERIALIZED (
        SELECT e.id AS player
        FROM unnest(p_queries) WITH ORDINALITY AS q(value, ord)
        JOIN laplace.entities e
          ON e.id = chess.player_id(q.value)
         AND e.type_id = laplace.entity_type_id('Chess_Player')
        WHERE length(q.value) > 0
        ORDER BY q.ord
        LIMIT 1
    ),
    -- Only a failed exact lookup is allowed to enter the fuzzy/indexed path.
    -- "Karpov" cannot content-address "Karpov, Anatoly" because the missing
    -- given name is not present; this is where trajectory constituents belong.
    forms(value) AS MATERIALIZED (
        SELECT DISTINCT v
        FROM unnest(p_queries) q(v)
        WHERE length(v) >= 2
          AND NOT EXISTS (SELECT 1 FROM exact)
    ),
    required AS MATERIALIZED (
        SELECT f.value,
               array_agg(DISTINCT laplace.word_id(ch)) AS ids
        FROM forms f,
             LATERAL string_to_table(f.value, NULL) AS c(ch)
        WHERE ch ~ '^[[:alnum:]]$'
        GROUP BY f.value
    ),
    name_ids AS MATERIALIZED (
        SELECT DISTINCT w.id AS name_id
        FROM required r
        JOIN laplace.v_word_points w
          ON w.trajectory IS NOT NULL
         AND public.laplace_trajectory_constituent_ids(w.trajectory) @> r.ids
        WHERE cardinality(r.ids) >= 2
    ),
    players AS MATERIALIZED (
        SELECT x.player FROM exact x
        UNION
        SELECT DISTINCT c.subject_id AS player
        FROM laplace.consensus c
        JOIN name_ids n ON n.name_id = c.object_id
        JOIN laplace.entities e
          ON e.id = c.subject_id
         AND e.type_id = laplace.entity_type_id('Chess_Player')
        WHERE c.type_id = ANY (
            consensus.relation_family_ids('HAS_NAME')
            || consensus.relation_family_ids('HAS_NAME_ALIAS'))
          AND NOT EXISTS (SELECT 1 FROM exact)
    ),
    rated AS MATERIALIZED (
        SELECT p.player,
               COALESCE(o.witness_count, 0) AS games,
               COALESCE(o.rating, consensus.glicko2_neutral_mu()) AS rating,
               COALESCE(o.rd, consensus.glicko2_initial_rd()) AS rd
        FROM players p
        LEFT JOIN LATERAL (
            SELECT c.witness_count, c.rating, c.rd
            FROM laplace.consensus c
            WHERE c.subject_id = p.player
              AND c.type_id = ANY (consensus.relation_family_ids('OUTCOME'))
              AND c.object_id = laplace.entity_type_id('Chess_Result')
            ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.id
            LIMIT 1
        ) o ON true
        -- Profile-only identities are still valid exact results.  Strength only
        -- ranks the fuzzy candidate set after exact resolution has failed.
        ORDER BY (o.rating IS NOT NULL) DESC,
                 consensus.eff_mu(
                     COALESCE(o.rating, consensus.glicko2_neutral_mu()),
                     COALESCE(o.rd, consensus.glicko2_initial_rd())) DESC,
                 p.player
        LIMIT p_limit
    ),
    batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(r.player ORDER BY r.player), '{}'::bytea[]) AS ids
        FROM rated r
    ),
    surfaced AS (
        SELECT q.id, q.txt
        FROM batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS q(id, txt)
    )
    SELECT r.player,
           COALESCE(NULLIF(s.txt, ''), 'Unrealized player'),
           r.games,
           round((r.rating / 1e9)::numeric, 3)::double precision,
           round((r.rd / 1e9)::numeric, 3)::double precision,
           consensus.eff_mu_display(r.rating, r.rd)::double precision
    FROM rated r
    LEFT JOIN surfaced s ON s.id = r.player
    ORDER BY consensus.eff_mu(r.rating, r.rd) DESC, r.player;
END;
DROP FUNCTION IF EXISTS laplace.chess_head_to_head(bytea, integer);
CREATE OR REPLACE FUNCTION chess.head_to_head(p_player bytea, p_limit integer DEFAULT 25)
    RETURNS TABLE(opponent_id bytea, opponent text, games bigint,
                  rating double precision, rd double precision, eff_mu double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- Head-to-head as a READ. chess_opponents() answers the same question by walking every
    -- game this player appeared in, joining each to its result and regrouping by the opposite
    -- colour edge. That work was already done at ingest: each game folds its result onto the
    -- (player, PLAYED_BY, opponent) cell, so two players who met 28 times are ONE cell with 28
    -- witnesses, and this is a single index range over that player's subject rows.
    --
    -- PLAYED_BY sat in the manifest with zero rows for as long as the aggregate existed. It was
    -- removed at PLY grain, correctly -- one near-unique row per ply can never corroborate. At
    -- PAIRING grain it is the opposite: every repeat meeting lands on the same cell. Grain is
    -- what decides whether an edge accumulates.
    --
    -- Ranked by consensus.eff_mu rather than games so the rivalries a career is actually defined by come
    -- first: a long even series against a strong opponent outranks a short lopsided one.
    WITH rec AS MATERIALIZED (
        SELECT c.object_id AS opponent,
               c.witness_count AS games,
               c.rating,
               c.rd
        FROM laplace.consensus c
        WHERE c.subject_id = p_player
          AND c.type_id = laplace.relation_type_id('PLAYED_BY')
          AND c.object_id IS NOT NULL
        ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id
        LIMIT p_limit
    ),
    batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(rec.opponent ORDER BY rec.opponent), '{}'::bytea[]) AS ids
        FROM rec
    ),
    named AS (
        SELECT p.id, p.txt
        FROM batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS p(id, txt)
    )
    SELECT rec.opponent,
           COALESCE(NULLIF(n.txt, ''), 'Unrealized player'),
           rec.games,
           -- DISPLAY units, never raw fp1e9: consensus.eff_mu_display is the one scaling law
           -- (functions/mu/consensus.eff_mu_display.sql.in), rating/rd take the same /1e9 round.
           round((rec.rating / 1e9)::numeric, 3)::double precision,
           round((rec.rd / 1e9)::numeric, 3)::double precision,
           consensus.eff_mu_display(rec.rating, rec.rd)::double precision
    FROM rec
    LEFT JOIN named n ON n.id = rec.opponent
    ORDER BY consensus.eff_mu(rec.rating, rec.rd) DESC, rec.opponent
$$;
-- Exceptional chess standing reconstruction for migrations/forensics after a
-- correctness defect. This is deliberately NOT a steady-state maintenance loop:
-- durable game/evidence observations are authority and normal reads/folds must
-- derive standing from the declared event-time recipe. Deployment does not queue
-- this procedure and no scheduled worker calls it.
--
-- The procedure is bounded to an explicit caller-supplied set of canonical player
-- subjects. Replaying the same subjects is idempotent because every selected cell
-- is reconstructed from all durable evidence and UPSERTed to canonical consensus.
CREATE OR REPLACE PROCEDURE chess.repair_player_ratings_batch(
    p_outcome bytea,
    p_played bytea,
    p_rating bytea,
    p_subjects bytea[])
LANGUAGE plpgsql
AS $$
DECLARE
    v_repaired bigint := 0;
    v_scope bigint := 0;
    v_refolded bigint := 0;
BEGIN
    IF p_outcome IS NULL OR p_played IS NULL OR p_rating IS NULL THEN
        RAISE EXCEPTION 'repair_player_ratings_batch: required relation id is NULL';
    END IF;
    IF p_subjects IS NULL OR cardinality(p_subjects) = 0 THEN
        RAISE EXCEPTION 'repair_player_ratings_batch: empty subject batch';
    END IF;
    IF EXISTS (
        SELECT 1 FROM unnest(p_subjects) s(id)
        WHERE id IS NULL OR octet_length(id) <> 16
    ) THEN
        RAISE EXCEPTION 'repair_player_ratings_batch: subject ids must be canonical 16-byte ids';
    END IF;

    CREATE TEMP TABLE _chess_rating_values (
        rating_id bytea PRIMARY KEY,
        rating bigint NOT NULL
    ) ON COMMIT DROP;
    CREATE TEMP TABLE _chess_rating_cells (
        subject_id bytea NOT NULL,
        type_id bytea NOT NULL,
        object_id bytea,
        UNIQUE NULLS NOT DISTINCT (subject_id, type_id, object_id)
    ) ON COMMIT DROP;

    -- Historical GH #1321 repair: managed staging once persisted a literal zero
    -- instead of the opponent's rating. Recover it from the opponent identity and
    -- that opponent's HAS_RATING testimony in the same playing context, bounded to
    -- this explicitly selected repair set.
    INSERT INTO _chess_rating_values(rating_id, rating)
    WITH ids AS MATERIALIZED (
        SELECT COALESCE(array_agg(DISTINCT r.object_id ORDER BY r.object_id),
                        '{}'::bytea[]) AS values
        FROM laplace.attestations target
        JOIN laplace.attestations pairing
          ON pairing.subject_id = target.subject_id
         AND pairing.context_id = target.context_id
         AND pairing.type_id = p_played
        JOIN laplace.attestations r
          ON r.subject_id = pairing.object_id
         AND r.context_id = target.context_id
         AND r.type_id = p_rating
        WHERE target.subject_id = ANY(p_subjects)
          AND target.type_id = ANY(ARRAY[p_outcome, p_played])
          AND target.opponent_rating_fp1e9 = 0
          AND r.object_id IS NOT NULL
    ), rendered AS MATERIALIZED (
        SELECT paired.id, paired.value
        FROM ids,
             LATERAL ROWS FROM (
                 unnest(ids.values),
                 unnest(realize.batch(ids.values))
             ) paired(id, value)
    )
    SELECT id, value::bigint
    FROM rendered
    WHERE value ~ '^[0-9]{3,5}$';

    WITH resolved AS MATERIALIZED (
        SELECT target.id, target.type_id, target.subject_id,
               COALESCE(max(rv.rating) * 1000000000,
                        consensus.glicko2_neutral_mu()) AS opponent_rating
        FROM laplace.attestations target
        LEFT JOIN laplace.attestations pairing
          ON pairing.subject_id = target.subject_id
         AND pairing.context_id = target.context_id
         AND pairing.type_id = p_played
        LEFT JOIN laplace.attestations r
          ON r.subject_id = pairing.object_id
         AND r.context_id = target.context_id
         AND r.type_id = p_rating
        LEFT JOIN _chess_rating_values rv ON rv.rating_id = r.object_id
        WHERE target.subject_id = ANY(p_subjects)
          AND target.type_id = ANY(ARRAY[p_outcome, p_played])
          AND target.opponent_rating_fp1e9 = 0
        GROUP BY target.id, target.type_id, target.subject_id
    )
    UPDATE laplace.attestations target
    SET opponent_rating_fp1e9 = resolved.opponent_rating
    FROM resolved
    WHERE target.id = resolved.id
      AND target.type_id = resolved.type_id
      AND target.subject_id = resolved.subject_id;
    GET DIAGNOSTICS v_repaired = ROW_COUNT;

    INSERT INTO _chess_rating_cells(subject_id, type_id, object_id)
    SELECT DISTINCT evidence.subject_id, evidence.type_id, evidence.object_id
    FROM laplace.attestations evidence
    WHERE evidence.subject_id = ANY(p_subjects)
      AND (
          evidence.type_id = p_played
          OR (
              evidence.type_id = p_outcome
              AND EXISTS (
                  SELECT 1
                  FROM laplace.attestations pairing
                  WHERE pairing.subject_id = evidence.subject_id
                    AND pairing.context_id IS NOT DISTINCT FROM evidence.context_id
                    AND pairing.type_id = p_played
              )
          )
      )
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_scope = ROW_COUNT;

    IF v_scope = 0 THEN
        RAISE LOG 'repair_player_ratings_batch: no chess rating evidence in % subject(s); repaired % legacy opponent row(s)',
            cardinality(p_subjects), v_repaired;
        RETURN;
    END IF;

    INSERT INTO laplace.consensus AS target
        (id, subject_id, type_id, object_id, rating, rd, volatility,
         witness_count, last_observed_at)
    SELECT laplace.consensus_id(f.subject_id, f.type_id, f.object_id),
           f.subject_id, f.type_id, f.object_id,
           (f.acc).rating, (f.acc).rd, (f.acc).volatility,
           (f.acc).witness_count, f.last_ts
    FROM (
        SELECT cells.subject_id, cells.type_id, cells.object_id,
               laplace.consensus_fold(
                   false, NULL::bigint, NULL::bigint, NULL::bigint,
                   evidence.opponent_rating_fp1e9,
                   evidence.opponent_rd_fp1e9,
                   GREATEST(evidence.observation_count, 1),
                   evidence.sum_score_fp1e9,
                   consensus.glicko2_tau()
                   ORDER BY evidence.last_observed_at, evidence.id) AS acc,
               max(evidence.last_observed_at) AS last_ts
        FROM _chess_rating_cells cells
        JOIN laplace.attestations evidence
          ON evidence.type_id = cells.type_id
         AND evidence.subject_id = cells.subject_id
         AND evidence.object_id IS NOT DISTINCT FROM cells.object_id
        GROUP BY cells.subject_id, cells.type_id, cells.object_id
    ) f
    ON CONFLICT (id, type_id, subject_id) DO UPDATE
    SET object_id = EXCLUDED.object_id,
        rating = EXCLUDED.rating,
        rd = EXCLUDED.rd,
        volatility = EXCLUDED.volatility,
        witness_count = EXCLUDED.witness_count,
        last_observed_at = EXCLUDED.last_observed_at
    WHERE ROW(target.object_id, target.rating, target.rd, target.volatility,
              target.witness_count, target.last_observed_at)
          IS DISTINCT FROM
          ROW(EXCLUDED.object_id, EXCLUDED.rating, EXCLUDED.rd, EXCLUDED.volatility,
              EXCLUDED.witness_count, EXCLUDED.last_observed_at);
    GET DIAGNOSTICS v_refolded = ROW_COUNT;

    RAISE LOG 'repair_player_ratings_batch: % subject(s), repaired % legacy opponent row(s), replayed % cells, corrected/materialized % consensus row(s)',
        cardinality(p_subjects), v_repaired, v_scope, v_refolded;
END;
$$;

-- Transition compatibility for the one legacy deployment caller left behind when
-- PR #1453 retired the queue/journal/worker. This entrypoint MUST stay inert: it
-- validates only the declared relation ids, performs no table reads or writes, and
-- never calls repair_player_ratings_batch. Historical reconstruction requires an
-- explicit caller-selected subject set through the bounded batch procedure above.
DROP PROCEDURE IF EXISTS chess.repair_player_ratings(bytea, bytea, bytea);
CREATE PROCEDURE chess.repair_player_ratings(
    p_outcome bytea,
    p_played bytea,
    p_rating bytea)
LANGUAGE plpgsql
AS $$
BEGIN
    IF p_outcome IS NULL OR p_played IS NULL OR p_rating IS NULL THEN
        RAISE EXCEPTION 'repair_player_ratings: required relation id is NULL';
    END IF;
END;
$$;
-- Exact boards, UCI and FEN are deterministically replayed from the decomposed move stream.
-- Ordered position ids live in the line physicality. Retire the SQL per-ply projection and
-- remove both pre-purpose and purpose-schema names on upgrade.
DROP FUNCTION IF EXISTS laplace.chess_game_plies(bytea);
DROP FUNCTION IF EXISTS chess.game_plies(bytea);
DROP FUNCTION IF EXISTS laplace.chess_line(bytea);
CREATE OR REPLACE FUNCTION chess.line(p_line bytea)
    RETURNS TABLE(event_id bytea, played_on text, result text,
                  times_played bigint, rating double precision,
                  rd double precision, eff_mu double precision)
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    -- The line-grain read GH #736's re-key pays for: one row per PLAYING of this
    -- line (the events that carry a PLAYS_LINE edge onto it), each with the
    -- headers that playing asserted (ON_DATE / HAS_RESULT, pinned by context),
    -- alongside any explicitly promoted legacy line fold. Times played comes from the
    -- playing→line occurrence joins themselves; it must not depend on an OUTCOME
    -- projection existing.
    --
    -- The fold columns are LEFT-joined and repeat per playing: a line recorded
    -- before the fold ran returns its playings with NULL rating rather than
    -- nothing (unattested, not attested-false), and a line nobody played
    -- returns zero rows.
    WITH playings AS MATERIALIZED (
        SELECT pl.subject_id AS event
        FROM laplace.attestations pl
        WHERE pl.object_id = p_line
          AND pl.type_id = laplace.relation_type_id('PLAYS_LINE')
    ),
    play_count AS MATERIALIZED (
        SELECT count(*)::bigint AS n FROM playings
    ),
    hdr AS MATERIALIZED (
        -- The playings' headers off ONE scan of the line's subject rows, grouped
        -- by context: each playing's own date/result, never a sibling's.
        SELECT a.context_id AS event,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('ON_DATE')) AS date_id,
               max(a.object_id) FILTER (
                   WHERE a.type_id = laplace.relation_type_id('HAS_RESULT')) AS result_id
        FROM laplace.attestations a
        WHERE a.subject_id = p_line
          AND a.context_id IS NOT NULL
          AND a.type_id IN (laplace.relation_type_id('ON_DATE'),
                            laplace.relation_type_id('HAS_RESULT'))
        GROUP BY a.context_id
    ),
    fold AS MATERIALIZED (
        -- Ranked, not arbitrary. object_id is unconstrained here, and consensus is
        -- unique per (subject, type, OBJECT) -- so a line witnessed with more than
        -- one OUTCOME has several rows and the bare LIMIT took whichever the scan
        -- reached first. Strongest standing fold wins, object_id breaks the tie.
        -- No behaviour change where only one outcome is witnessed.
        SELECT c.witness_count, c.rating, c.rd
        FROM laplace.consensus c
        WHERE c.subject_id = p_line
          AND c.type_id = laplace.relation_type_id('OUTCOME')
          -- Standing fold only (Copilot #918): a fully-refuted OUTCOME is not
          -- the line's result.
          AND consensus.eff_mu(c.rating, c.rd) > 0
        ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id
        LIMIT 1
    ),
    surface_batch AS MATERIALIZED (
        SELECT COALESCE(array_agg(DISTINCT s), '{}'::bytea[]) AS ids
        FROM hdr h,
             LATERAL (VALUES (h.date_id), (h.result_id)) v(s)
        WHERE s IS NOT NULL
    ),
    surface_text AS MATERIALIZED (
        SELECT p.id, p.txt
        FROM surface_batch b,
             LATERAL ROWS FROM (
                 unnest(b.ids), unnest(realize.batch(b.ids))
             ) AS p(id, txt)
    )
    SELECT pg.event,
           d.txt,
           r.txt,
           pc.n,
           f.rating::double precision,
           f.rd::double precision,
           consensus.eff_mu(f.rating, f.rd)::double precision
    FROM playings pg
    LEFT JOIN hdr h ON h.event = pg.event
    LEFT JOIN surface_text d ON d.id = h.date_id
    LEFT JOIN surface_text r ON r.id = h.result_id
    LEFT JOIN fold f ON true
    CROSS JOIN play_count pc
    ORDER BY d.txt DESC NULLS LAST, pg.event
$$;
-- Retired: chess_leaderboard(integer) and chess_opponents(bytea, integer).
--
-- Both answered "what is this player's record" by AGGREGATING evidence at query time:
-- chess_leaderboard grouped every colour-header row in the corpus (~400k rows for ~200k
-- games, ~10s) and chess_opponents regrouped one player's whole career by opponent. They
-- were correct, and they were the wrong shape. A record that takes ten seconds has to be
-- cached to be usable, and the cache then has to be kept fresh -- state standing in for a
-- fold the substrate exists to have already done.
--
-- Each game now carries its result onto the player in the aggregating lane at ingest, so
-- the same two questions are reads of consensus cells: chess.ranked() orders by consensus.eff_mu
-- over one relation partition, chess.head_to_head() reads one folded cell per pairing.
-- witness_count IS games played. Nothing is recomputed and nothing is cached.
--
-- Dropped rather than left in place: two implementations of one fact is the duplication
-- the engineering rules forbid without a documented reason, and the surviving pair is
-- strictly better (Glicko-2 weighs WHO you beat; a win ratio cannot). The install SQL is
-- CREATE-OR-REPLACE and never drops, so on the UPGRADE path these catalog rows would
-- linger while a fresh CREATE EXTENSION would not have them; this DROP makes the two match.
--
-- chess.player_record() is NOT retired. The fold yields strength, not the W/D/L split, and
-- that split is a genuinely different question -- answered by index lookups on ONE player
-- (74ms measured over a 1341-game career), which is a read, not an aggregate.
DROP FUNCTION IF EXISTS laplace.chess_leaderboard(integer);
DROP FUNCTION IF EXISTS laplace.chess_opponents(bytea, integer);
-- Retired: laplace.constituent_edges (table), constituent_edges_rebuild(int) (procedure),
-- and constituents_closure_edges(bytea[], int) (the closure that read the table).
--
-- The whole subsystem was a second copy of a fact the substrate already stores exactly.
-- physicalities.trajectory IS the constituent sequence -- Trajectory.Build packs the ordered
-- child ids into the linestring mantissa and laplace_trajectory_constituents unpacks them
-- losslessly. realize.constituents() and realize.constituents_closure() read that trajectory directly, and
-- so does the live render path. constituent_edges held a decode of the same bytes in a
-- different shape, and its own rebuild header said so: "it only unpacks what
-- physicalities.trajectory already encodes."
--
-- It could never be trusted, because nothing maintained it. Ingest did not write it; the
-- only writer was a manual TRUNCATE-and-rebuild procedure invoked by CALL. On a fully
-- seeded database it held ZERO rows, which is the failure mode of derived-but-hand-refreshed
-- state: silently empty, and anything reading it silently returns nothing. The rebuild
-- comment anticipated a "(separately validated) cutover" that never landed, so after the
-- cutover never happened the only consumer left was its own regress test asserting that the
-- edges-based closure agrees with the trajectory-based one it was meant to replace.
--
-- The access pattern it was reaching for -- child->parent, or "which parents start with this
-- child" -- is real. The answer to a new access path over authoritative data is an INDEX,
-- which Postgres maintains on write, transactionally, always correct. It is not a copy of
-- the data that a human has to remember to regenerate. That distinction is the whole reason
-- this is being deleted rather than repaired: derived-and-auto-maintained is a read; derived
-- and-hand-maintained is a cache, and a cache over the substrate's own content is a bandaid
-- over the absence of the right index.
--
-- Order matters: the closure function references the table, so it goes first. The table was
-- registered with pg_extension_config_dump, so dropping it also removes it from the
-- extension's dump set -- intended, since there is nothing left to restore.
DROP FUNCTION IF EXISTS laplace.constituents_closure_edges(bytea[], integer);
DROP PROCEDURE IF EXISTS laplace.constituent_edges_rebuild(integer);
DROP TABLE IF EXISTS laplace.constituent_edges;
-- Retired flat-schema copies of index_usage_report / index_usage_detail.
-- Live surfaces are ops.index_usage_report / ops.index_usage_detail (GH #813/#764).
--
-- entity_type_counts_approx / partition_pressure were retired here when they had
-- zero callers (g4_dead_canonical). They are live again as ops.* — do NOT re-drop them.
--
-- WHY A DROP MODULE AND NOT JUST DELETING THE .sql.in FILES. Removing a file from the
-- manifests stops FUTURE installs from creating the function. It does nothing to a database
-- that already ran an upgrade carrying it — ALTER EXTENSION ... UPDATE has no mechanism to
-- retract a CREATE that a previous version performed. Those catalogs would keep the
-- instruments indefinitely, and the gate would never flag them again because the gate
-- scans SOURCE, not pg_proc.
--
-- IF EXISTS throughout: a fresh install never created these, and this module runs there too.
-- Qualify laplace.* so this cannot delete the ops.* replacements installed earlier.
DROP FUNCTION IF EXISTS laplace.index_usage_report(bigint);
DROP FUNCTION IF EXISTS laplace.index_usage_detail(text, integer);
-- converse.infer(prompt, limit): one forward pass over the substrate, installed.
--
-- Run by hand as three ad-hoc statements on 2026-08-01 ("the capital of
-- California is" -> sacramento) and promoted to a surface the same night:
-- an end user never runs SQL against the substrate, and an operator never
-- re-derives this composition.
--
--   EMBED    prompt_coherence: surface tokens -> content ids, one call.
--   ATTEND   the election seats the TOPIC -- one election, one key order,
--            converse.chat()'s verbatim; every other candidate becomes a BIAS head.
--   READ     one indexed scan: the topic's consensus objects. This is the
--            A->[...] distribution, and it is NOT collapsed here.
--   REWEIGHT bias_hits counts each candidate's own edges into the bias
--            family (bias synsets plus their one-hop in-edges), id space
--            only -- no realize.render, no string compare.
--   EMIT     realize_batch ONCE over the ranked survivors, position-aligned;
--            the single realize.render, at the end, where rendering belongs.
--
-- KNOWN LIMITS, stated not hidden: forward direction only (the both-direction
-- OR join belongs in C next to prompt_coherence, not rewritten here); one-hop
-- bias family; single-step emission. Relation-name attestation data (#756.1)
-- and new relation families (#756.2) are separate; this file owns #756.3 —
-- election rel_type_id narrows the READ when a prompt token names a relation.
-- On a single-witness seed the base weights are flat and bias_hits carries the
-- whole signal -- measured: the California read returns 39 candidates all at
-- consensus.eff_mu 1315.5, and exactly one (sacramento) carries a capital-family edge.
DROP FUNCTION IF EXISTS laplace.infer(text, int);
CREATE OR REPLACE FUNCTION converse.infer(p_prompt text, p_limit int DEFAULT 8)
    RETURNS TABLE(prediction text, weight double precision, bias_hits bigint)
    LANGUAGE sql STABLE AS $$
-- The prompt's language is a CONSTRAINT on which candidates may be seated, never
-- a score. Without it a foreign interjection outranks the content word on the
-- specificity scalar and takes the topic seat, which is the §7 violation seen on
-- every phrase probe. A candidate is dropped only when the prompt's language and
-- the candidate's primary language are both known and differ; concepts (no
-- HAS_LANGUAGE) and undetectable prompts are untouched, so this can only narrow a
-- language-blind field. converse.prompt_language_top and converse.word_language
-- are the existing definitions of both sides — neither was wired to this election.
WITH plang AS MATERIALIZED (
    SELECT converse.prompt_language_top(p_prompt) AS id
),
ranked AS (
    SELECT y.tok, y.synset_id, y.rel_type_id,
           row_number() OVER (ORDER BY y.specificity DESC NULLS LAST,
                                       y.rel_mass DESC NULLS LAST,
                                       y.peers DESC,
                                       y.ord DESC,
                                       y.denote_mu DESC NULLS LAST,
                                       y.synset_id) AS rk
    FROM converse.prompt_coherence(p_prompt) y
    WHERE (SELECT id FROM plang) IS NULL
       OR converse.word_language(y.synset_id) IS NULL
       OR converse.word_language(y.synset_id) = (SELECT id FROM plang)
),
topic AS (
    SELECT r.synset_id, r.rel_type_id, r.tok FROM ranked r WHERE r.rk = 1
),
-- EVERY sense of every bias token, not the per-token argmax. Shipped first
-- as prompt_coherence's elected sense per bias token and measured broken the
-- same night: "capital"'s elected sense is the washington synset, so the
-- capital-family intersection scored ZERO hits and sacramento ranked flat.
-- The bias head is a DISTRIBUTION over the token's senses; collapsing it to
-- one sense before the intersection is the KVP mistake this function exists
-- to not make. lexical.senses() per bias token is a per-row SRF over 2-6 rows --
-- tolerated here, ported to C with the rest when this graduates.
bias AS (
    SELECT DISTINCT s.synset_id
    FROM ranked r
    CROSS JOIN LATERAL lexical.senses(r.tok) s
    WHERE r.rk > 1 AND s.synset_id IS NOT NULL
),
-- The in-edge arm probes with = ANY(array), never a join. laplace.consensus is
-- LIST(type_id) with hash sub-partitions and this read constrains only
-- object_id, so no partition can be pruned: as a join the planner takes a full
-- index-only scan of EVERY partition and hash-joins, while the array form emits
-- one ScalarArrayOpExpr probe per bias id against
-- consensus_*_object_id_type_id_idx. A LATERAL rewrite is worse than the join.
-- ARRAY(SELECT ...) DELIBERATELY, not a CTE column. It reads like the worse form,
-- but the nesting is exactly what makes it fast: ARRAY(SELECT ...) is evaluated as
-- an InitPlan -- one sub-plan producing a BOUND CONSTANT array before the scan --
-- which lets the planner emit a ScalarArrayOp with runtime partition pruning. A CTE
-- column is a variable from a join, so the planner cannot bind it and falls back to
-- a join across the partition set. MEASURED here, identical 44,415 rows:
--   CROSS JOIN ids CTE, = ANY (ids.col)   14,299 ms
--   = ANY (ARRAY(SELECT ...))              3,342 ms
-- It is site-specific, not a rule: the same swap made taxonomy.bubble_up FASTER
-- (484.7ms -> 349.5ms). Measure before changing the shape either way.
biasfam AS (
    SELECT b.synset_id FROM bias b
    UNION
    SELECT c.subject_id FROM laplace.consensus c
    WHERE c.object_id = ANY (ARRAY(SELECT b2.synset_id FROM bias b2))
),
cand AS (
    SELECT c.object_id AS id, max(consensus.eff_mu(c.rating, c.rd)) AS m
    FROM topic t
    -- WordNet antonymy (and similar) lands on the WORD id; election seats a
    -- synset. Read both subjects or a typed antonym prompt returns empty
    -- while untyped still sees the synset's other consensus.edges(GH #756.3).
    JOIN laplace.consensus c ON c.subject_id IN (t.synset_id, t.tok)
    WHERE c.object_id IS NOT NULL
      -- Typed scan when the election named a relation; full distribution otherwise
      -- (GH #756.3 — prompt_coherence already returns rel_type_id).
      AND (t.rel_type_id IS NULL OR c.type_id = t.rel_type_id)
      -- NAMEABLE ONLY (forward_hygiene gate; the GH #878 leak class): a
      -- prediction must have a name — its own surface (words carry
      -- HAS_LANGUAGE, so converse.word_language() answers) or a realizable member
      -- (lexical.concept_members()). A candidate failing both realizes through the
      -- canonical arm as a raw key or hex address — internal bookkeeping
      -- leaked as an answer ("hubs are ADDRESSES, not names"). Id space via
      -- installed surfaces, no renders; the per-row cost rides the same
      -- tolerance lexical.senses() already documents above, until the C port (#757).
      -- CASE, not OR: PostgreSQL does not guarantee OR short-circuiting, so
      -- the cheap word check must be forced to run first or every word
      -- candidate also pays the lexical.concept_members() set-returning probe.
      AND CASE WHEN converse.word_language(c.object_id) IS NOT NULL THEN true
               ELSE EXISTS (SELECT 1 FROM lexical.concept_members(c.object_id)) END
    GROUP BY c.object_id
),
scored AS (
    SELECT d.id, d.m, count(f.synset_id) AS hits
    FROM cand d
    LEFT JOIN laplace.consensus c2 ON c2.subject_id = d.id
    LEFT JOIN biasfam f ON f.synset_id = c2.object_id
    GROUP BY d.id, d.m
    ORDER BY count(f.synset_id) DESC, d.m DESC, d.id
    LIMIT p_limit
),
ord AS (
    SELECT s.id, s.m, s.hits,
           row_number() OVER (ORDER BY s.hits DESC, s.m DESC, s.id) AS ix
    FROM scored s
),
lbl AS (
    SELECT realize.batch(array_agg(o.id ORDER BY o.ix), NULL) AS l FROM ord o
),
named AS (
    SELECT lbl.l[o.ix] AS prediction, o.m / 1e9 AS weight, o.hits AS bias_hits, o.ix
    FROM ord o CROSS JOIN lbl
),
dedup AS (
    -- Two synset ids can realize to the same surface (hot→cold×2). Keep the
    -- strongest row per label so typed antonym reads don't double-emit.
    SELECT DISTINCT ON (n.prediction) n.prediction, n.weight, n.bias_hits, n.ix
    FROM named n
    WHERE n.prediction IS NOT NULL AND n.prediction <> ''
    ORDER BY n.prediction, n.bias_hits DESC, n.weight DESC, n.ix
)
SELECT d.prediction, d.weight, d.bias_hits
FROM dedup d
ORDER BY d.bias_hits DESC, d.weight DESC, d.ix
$$;
-- chess.opening_preference(player, tc_class, limit): which openings a player
-- actually reaches for, per time-control class -- witnessed record only.
--
-- Promoted 2026-08-02 from a hand-run that took FOUR attempts to find the
-- layer map, which is the argument for its existence: the layering (GH #736)
-- is that the PLAYER is the OBJECT of HAS_WHITE/HAS_BLACK, whose subject is
-- the shared LINE and whose context pins the PLAYING; HAS_ECO and
-- HAS_TC_CLASS ride the same (line, context) pair. PLAYED_BY lives on a
-- different layer and does NOT reach the headers -- three empty joins proved
-- it. Nobody should have to rediscover that; this surface is the map.
--
-- p_tc_class filters in ID SPACE via the identity law (laplace.word_id of the class
-- surface, e.g. 'bullet', 'blitz'), never by rendering and comparing text.
-- Group by ids, realize ONCE over the page -- the read law's shape.
DROP FUNCTION IF EXISTS laplace.chess_opening_preference(bytea, text, int);
CREATE OR REPLACE FUNCTION chess.opening_preference(p_player bytea,
                                                    p_tc_class text DEFAULT NULL,
                                                    p_limit int DEFAULT 12)
    RETURNS TABLE(tc_class text, eco text, games bigint)
    LANGUAGE sql STABLE
 AS $$
WITH grouped AS (
    SELECT tcc.object_id AS tc_id, e.object_id AS eco_id, count(*) AS games
    FROM laplace.attestations a
    JOIN laplace.attestations tcc ON tcc.subject_id = a.subject_id
                         AND tcc.context_id = a.context_id
                         AND tcc.type_id = laplace.relation_type_id('HAS_TC_CLASS')
    JOIN laplace.attestations e ON e.subject_id = a.subject_id
                       AND e.context_id = a.context_id
                       AND e.type_id = laplace.relation_type_id('HAS_ECO')
    WHERE a.object_id = p_player
      AND a.context_id IS NOT NULL
      AND a.type_id IN (laplace.relation_type_id('HAS_WHITE'),
                        laplace.relation_type_id('HAS_BLACK'))
      AND (p_tc_class IS NULL OR tcc.object_id = laplace.word_id(lower(p_tc_class)))
    GROUP BY tcc.object_id, e.object_id
    ORDER BY count(*) DESC, tcc.object_id, e.object_id
    LIMIT p_limit
),
ord AS (
    SELECT g.*, row_number() OVER (ORDER BY g.games DESC, g.tc_id, g.eco_id) AS ix
    FROM grouped g
),
lbl AS (
    SELECT realize.batch(array_agg(v.id ORDER BY v.ord), NULL) AS l
    FROM (SELECT o.tc_id AS id, o.ix * 2 - 1 AS ord FROM ord o
          UNION ALL
          SELECT o.eco_id, o.ix * 2 FROM ord o) v
)
SELECT lbl.l[o.ix * 2 - 1], lbl.l[o.ix * 2], o.games
FROM ord o CROSS JOIN lbl
ORDER BY o.ix
$$;
-- chess.opening_games(opening, limit, offset): the PLAYINGS of one opening, ranked.
--
-- WHY THIS EXISTS. Openings and games were both in the substrate and joined correctly,
-- and no read surface joined them. ops.api('chess') listed fourteen chess functions and the
-- only one touching openings was chess_opening_preference, which is per-PLAYER and
-- returns ECO codes. Answering "which games were played in the Ruy Lopez" meant
-- hand-writing the layer map again (GH #736: the subject is the shared LINE, the context
-- pins the PLAYING) — the rediscovery chess_opening_preference's own header argues
-- nobody should have to do.
--
-- THE JOIN IS A CONTENT COLLISION, NOT A LOOKUP. The openings catalog attests
-- (final_position, OPENING_NAME, name); a game attests (line, GAME_HAS_OPENING, name).
-- Both mint `name` through the same content law, so they are the SAME id and laplace.word_id()
-- reproduces it, multi-word names included. The filter is in ID SPACE — one index seek
-- on attestations_object_btree — never a realize.render-and-compare.
--
-- IDS OUT, NOT HEADERS. This returns the ranked (line, event) pairs and stops.
-- chess.game(event) already owns reading a playing's white/black/result/date/ECO, and an
-- earlier cut of this function re-implemented all of it — five more relation names typed
-- a second time, which is both duplicated logic and exactly the vocabulary literalism the
-- ISA gate exists to stop. Compose instead:
--
--   SELECT g.*, d.white, d.black, d.result, d.played_on, d.eco
--   FROM chess.opening_games('Ruy Lopez', 25) g,
--        LATERAL chess.game(g.event_id) d;
--
-- Times played is counted from the occurrence joins. A legacy/promoted line OUTCOME may
-- supply an optional ranking, but the read does not require that projection to exist.
--
-- p_source selects one witness when they disagree: ChessPgn transcribes the PGN's own
-- Opening header, ChessAnalysis derives it by SAN prefix, ChessOpeningMatch derives it by
-- board identity. NULL (default) accepts any.
DROP FUNCTION IF EXISTS laplace.chess_opening_games(text, int, int, bytea);
CREATE OR REPLACE FUNCTION chess.opening_games(p_opening text,
                                               p_limit int DEFAULT 25,
                                               p_offset int DEFAULT 0,
                                               p_source bytea DEFAULT NULL)
    RETURNS TABLE(line_id bytea, event_id bytea, times_played bigint,
                  eff_mu double precision)
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
WITH claim AS MATERIALIZED (
    -- Line-grain, context_id NULL by design: every playing asserting the same opening for
    -- the same line MERGES into one evidence row whose observation count accumulates
    -- (ChessPgnDecomposer.RecordOpeningHeaders). So the playing cannot be read off this
    -- row — an earlier cut tried and returned a page of games with no date, no result and
    -- no players. PLAYS_LINE is the one record edge whose subject IS the event.
    SELECT DISTINCT a.subject_id AS line
    FROM laplace.attestations a
    WHERE a.object_id = laplace.word_id(p_opening)
      AND a.type_id = laplace.relation_type_id('GAME_HAS_OPENING')
      AND (p_source IS NULL OR a.source_id = p_source)
),
played AS MATERIALIZED (
    SELECT k.line, pl.subject_id AS event
    FROM claim k
    JOIN laplace.attestations pl ON pl.object_id = k.line
                        AND pl.type_id = laplace.relation_type_id('PLAYS_LINE')
),
play_count AS MATERIALIZED (
    SELECT p.line, count(*)::bigint AS n
    FROM played p
    GROUP BY p.line
),
fold AS MATERIALIZED (
    -- LEFT-joined below: a line recorded before the fold ran returns with NULL rather
    -- than vanishing (unattested is not attested-false).
    SELECT c.subject_id AS line, c.witness_count, c.rating, c.rd
    FROM laplace.consensus c
    JOIN claim k ON k.line = c.subject_id
    WHERE c.type_id = laplace.relation_type_id('OUTCOME')
)
SELECT g.line, g.event,
       pc.n,
       consensus.eff_mu_display(f.rating, f.rd)::double precision
FROM played g
JOIN play_count pc ON pc.line = g.line
LEFT JOIN fold f ON f.line = g.line
ORDER BY pc.n DESC,
         consensus.eff_mu(f.rating, f.rd) DESC NULLS LAST,
         g.line, g.event
LIMIT p_limit OFFSET p_offset
$$;
-- chess.opening_record(limit, offset, source): the opening leaderboard.
--
-- One row per opening the corpus has actually played, with how many distinct lines
-- reached it, how many playings those lines carry, and how the opening FARES —
-- the witness-weighted mean of the lines' own OUTCOME fold cells, white POV.
--
-- WHAT MAKES THIS CHEAP. Every number here was folded at ingest. The score is not a
-- GROUP BY over 63M laplace.attestations recomputed per call: it reads (line, OUTCOME,
-- Chess_Result) consensus cells, which is one row per line no matter how many times
-- the line was played. Consensus accumulates at ingest and there is no rebuild path;
-- this reads what the fold already deposited.
--
-- Weighting by witness_count, not a plain average over lines: an opening whose one
-- exotic line went 1-0 once must not outrank the Sicilian. The weight IS the number
-- of playings, which is exactly what witness_count counts on this cell.
DROP FUNCTION IF EXISTS laplace.chess_opening_record(int, int, bytea);
CREATE OR REPLACE FUNCTION chess.opening_record(p_limit int DEFAULT 25,
                                                p_offset int DEFAULT 0,
                                                p_source bytea DEFAULT NULL)
    RETURNS TABLE(opening text, lines bigint, playings bigint,
                  eff_mu double precision)
    LANGUAGE sql STABLE
 AS $$
WITH claim AS MATERIALIZED (
    -- (opening name id, line) pairs. DISTINCT because ChessPgn and ChessAnalysis both
    -- assert the opening for the same line — two witnesses, one line.
    SELECT DISTINCT a.object_id AS name_id, a.subject_id AS line
    FROM laplace.attestations a
    WHERE a.type_id = laplace.relation_type_id('GAME_HAS_OPENING')
      AND (p_source IS NULL OR a.source_id = p_source)
),
scored AS MATERIALIZED (
    SELECT k.name_id,
           count(*)                                          AS lines,
           COALESCE(sum(c.witness_count), 0)                 AS playings,
           -- Witness-weighted mean of the per-line conservative estimate.
           sum(consensus.eff_mu(c.rating, c.rd) * c.witness_count)
             / NULLIF(sum(c.witness_count), 0)               AS mu
    FROM claim k
    LEFT JOIN laplace.consensus c ON c.subject_id = k.line
                         AND c.type_id = laplace.relation_type_id('OUTCOME')
    GROUP BY k.name_id
),
ord AS MATERIALIZED (
    SELECT s.*, row_number() OVER (ORDER BY s.playings DESC, s.lines DESC, s.name_id) AS ix
    FROM scored s
    ORDER BY s.playings DESC, s.lines DESC, s.name_id
    LIMIT p_limit OFFSET p_offset
),
-- Render last and once, after LIMIT/OFFSET. name_id is the GROUP BY key upstream, so
-- the page is already distinct by construction — one realize call, p_limit ids.
lbl AS MATERIALIZED (
    SELECT realize.batch(array_agg(o.name_id ORDER BY o.ix), NULL) AS l FROM ord o
)
SELECT lbl.l[o.ix], o.lines::bigint, o.playings::bigint,
       round((o.mu / 1e9)::numeric, 3)::double precision
FROM ord o CROSS JOIN lbl
ORDER BY o.ix
$$;
-- One exact Syzygy edge from the substrate-resident material graph.
--
-- Material ingest stores each table entry as three adjacent Projection vertices:
--
--     position (role 0, WDL/DTZ) -> typed move (role 1) -> position (role 2)
--
-- The projection constituent GIN finds the chunk containing the position.  Decoding
-- three adjacent vertices is independent of corpus size; no relation scan and no
-- per-position attestation join is involved.
CREATE OR REPLACE FUNCTION chess.syzygy_transition(p_position bytea)
    RETURNS TABLE(move_id bytea, next_position bytea, wdl integer, dtz integer)
    AS 'laplace_substrate', 'pg_laplace_chess_syzygy_transition'
    LANGUAGE C STABLE ROWS 1;
-- chess.syzygy_line(line): the exact endgame oracle along one line.
--
-- Current packages are material graphs of exact position -> typed move -> position
-- trajectories.  chess.syzygy_transition performs the indexed graph lookup.  The
-- legacy attestation branch keeps already-seeded v2 data readable while a clean seed
-- writes the compact graph.
--
-- WDL is five-valued and SIDE-TO-MOVE POV, not white POV: 'win' means the player to
-- move in that position wins with perfect play. It is never mixed with the OUTCOME
-- fold's white-POV consensus.eff_mu, which is why this returns the token rather than a number.
--
-- Typed accessors below own the single laplace.relation_type_id('…') literals for this
-- vocabulary (ISA G3). New chess SQL must call these — never re-type the strings.
DROP FUNCTION IF EXISTS laplace.chess_has_wdl_type();
CREATE OR REPLACE FUNCTION chess.has_wdl_type() RETURNS bytea
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT laplace.relation_type_id('HAS_WDL')
$$;

DROP FUNCTION IF EXISTS laplace.chess_has_dtz_type();
CREATE OR REPLACE FUNCTION chess.has_dtz_type() RETURNS bytea
    LANGUAGE sql STABLE PARALLEL SAFE
 AS $$
    SELECT laplace.relation_type_id('HAS_DTZ')
$$;

DROP FUNCTION IF EXISTS laplace.chess_syzygy_line(bytea, int);
CREATE OR REPLACE FUNCTION chess.syzygy_line(p_line bytea, p_limit int DEFAULT 64)
    RETURNS TABLE(position_id bytea, wdl text, dtz text)
    LANGUAGE sql STABLE
 AS $$
WITH rel AS MATERIALIZED (
    SELECT chess.has_wdl_type() AS wdl, chess.has_dtz_type() AS dtz
),
line AS MATERIALIZED (
    SELECT u.ord AS ordinal, u.entity_id AS pos
    FROM LATERAL generation.trajectory_unpacked_points(p_line, 3::smallint)
         WITH ORDINALITY AS u(entity_id, run_length, ctier, ord)
),
compact AS MATERIALIZED (
    SELECT l.pos,
           t.wdl,
           t.dtz,
           min(l.ordinal) AS ord
    FROM line l
    CROSS JOIN LATERAL chess.syzygy_transition(l.pos) t
    GROUP BY l.pos, t.wdl, t.dtz
),
legacy AS MATERIALIZED (
    SELECT l.pos,
           max(a.object_id) FILTER (WHERE a.type_id = r.wdl) AS wdl_id,
           max(a.object_id) FILTER (WHERE a.type_id = r.dtz) AS dtz_id,
           min(l.ordinal) AS ord
    FROM line l
    JOIN rel r ON true
    JOIN laplace.attestations a ON a.subject_id = l.pos
                       AND a.type_id IN (r.wdl, r.dtz)
    GROUP BY l.pos
    HAVING max(a.object_id) FILTER (WHERE a.type_id = r.wdl) IS NOT NULL
),
chosen AS MATERIALIZED (
    SELECT c.pos,
           c.wdl,
           c.dtz::text AS dtz,
           NULL::bytea AS wdl_id,
           NULL::bytea AS dtz_id,
           c.ord
    FROM compact c
    UNION ALL
    SELECT l.pos,
           NULL::integer,
           NULL::text,
           l.wdl_id,
           l.dtz_id,
           l.ord
    FROM legacy l
    WHERE NOT EXISTS (SELECT 1 FROM compact c WHERE c.pos = l.pos)
    ORDER BY ord
    LIMIT p_limit
),
surfaces AS MATERIALIZED (
    SELECT COALESCE(array_agg(DISTINCT s), '{}'::bytea[]) AS ids
    FROM chosen o, LATERAL (VALUES (o.wdl_id), (o.dtz_id)) v(s)
    WHERE s IS NOT NULL
),
label AS MATERIALIZED (
    SELECT p.id, p.txt
    FROM surfaces b,
         LATERAL ROWS FROM (
             unnest(b.ids), unnest(realize.batch(b.ids, NULL))
         ) AS p(id, txt)
)
SELECT o.pos,
       COALESCE(
           CASE o.wdl
               WHEN 0 THEN 'loss'
               WHEN 1 THEN 'blessed-loss'
               WHEN 2 THEN 'draw'
               WHEN 3 THEN 'cursed-win'
               WHEN 4 THEN 'win'
           END,
           w.txt),
       COALESCE(o.dtz, d.txt)
FROM chosen o
LEFT JOIN label w ON w.id = o.wdl_id
LEFT JOIN label d ON d.id = o.dtz_id
ORDER BY o.ord
$$;
-- chess.opening_shape_peers(line_id): Hilbert/centroid locality prefilter, then
-- Frechet on REALIZED entity_curve — Cat/Act applied to chess opening lines.
--
-- NEVER Frechet on packed laplace.physicalities.trajectory (Rule #3). Catalog peers are
-- Chess_Game laplace.entities first-observed by ChessOpenings that carry a trajectory
-- (opening LINEs after the catalog-dual deposit) — not OPENING_NAME attestation
-- scans (that would re-introduce laplace.relation_type_id vocabulary literals; ISA G3).
--
-- IDS OUT: peer_line_id only. Name/ECO are separate laplace.attestations; realize.render via
-- realize_batch on a page of peer ids if needed — never per-row realize here.
DROP FUNCTION IF EXISTS laplace.chess_opening_shape_peers(bytea, integer, float8);
CREATE OR REPLACE FUNCTION chess.opening_shape_peers(
    p_line bytea,
    p_k integer DEFAULT 12,
    p_frechet_max float8 DEFAULT 0.05)
    RETURNS TABLE(
        peer_line_id bytea,
        geodesic double precision,
        frechet double precision)
    LANGUAGE plpgsql STABLE
 AS $peers$
DECLARE
    v_coord geometry;
    v_curve geometry;
    v_openings_src bytea := laplace.source_id('ChessOpenings');
    v_game_type bytea := laplace.entity_type_id('Chess_Game');
BEGIN
    SELECT p.coord, structural.entity_curve(p_line, 3::smallint)
      INTO v_coord, v_curve
    FROM laplace.physicalities p
    WHERE p.entity_id = p_line AND p.type = 3;
    IF v_coord IS NULL OR v_curve IS NULL THEN RETURN; END IF;

    RETURN QUERY
    WITH catalog AS MATERIALIZED (
        SELECT e.id AS line_id
        FROM laplace.entities e
        JOIN laplace.physicalities w ON w.entity_id = e.id AND w.type = 3
        WHERE e.type_id = v_game_type
          AND e.first_observed_by = v_openings_src
          AND e.id <> p_line
          AND w.coord IS NOT NULL
          AND w.trajectory IS NOT NULL
    ),
    knn AS (
        SELECT w.entity_id, w.coord
        FROM catalog c
        JOIN laplace.physicalities w ON w.entity_id = c.line_id AND w.type = 3
        ORDER BY w.coord <<->> v_coord
        LIMIT p_k
    ),
    scored AS (
        SELECT k.entity_id,
               public.laplace_angular_distance_4d(k.coord, v_coord) AS geo,
               public.laplace_frechet_4d(
                   structural.entity_curve(k.entity_id, 3::smallint), v_curve) AS fr
        FROM knn k
    )
    SELECT s.entity_id, s.geo, s.fr
    FROM scored s
    WHERE s.fr IS NOT NULL AND s.fr <= p_frechet_max
    ORDER BY s.fr ASC, s.geo ASC, s.entity_id
    LIMIT p_k;
END;
$peers$;
-- chess.distance_to_syzygy(line): observed distance along a line to the first
-- substrate-resident closing transition. Silence is not a draw — empty when the
-- line never reaches a decoded tablebase position.  Legacy v2 attestations remain
-- readable until the clean compact seed replaces them.
--
-- Relation vocabulary via chess_has_wdl_type / chess.has_dtz_type(ISA G3).
DROP FUNCTION IF EXISTS laplace.chess_distance_to_syzygy(bytea);
CREATE OR REPLACE FUNCTION chess.distance_to_syzygy(p_line bytea)
    RETURNS TABLE(
        position_id bytea,
        plies_to_close integer,
        d_men integer,
        wdl text,
        dtz text)
    LANGUAGE sql STABLE
 AS $$
WITH rel AS MATERIALIZED (
    SELECT chess.has_wdl_type() AS wdl, chess.has_dtz_type() AS dtz
),
line AS MATERIALIZED (
    SELECT (u.ord - 1)::int AS ply, u.entity_id AS pos
    FROM LATERAL generation.trajectory_unpacked_points(p_line, 3::smallint)
         WITH ORDINALITY AS u(entity_id, run_length, ctier, ord)
),
compact AS MATERIALIZED (
    SELECT l.ply, l.pos, t.wdl, t.dtz
    FROM line l
    CROSS JOIN LATERAL chess.syzygy_transition(l.pos) t
    ORDER BY l.ply
    LIMIT 1
),
legacy AS MATERIALIZED (
    SELECT l.ply, l.pos,
           max(a.object_id) FILTER (WHERE a.type_id = r.wdl) AS wdl_id,
           max(a.object_id) FILTER (WHERE a.type_id = r.dtz) AS dtz_id
    FROM line l
    JOIN rel r ON true
    JOIN laplace.attestations a ON a.subject_id = l.pos
                       AND a.type_id IN (r.wdl, r.dtz)
    GROUP BY l.ply, l.pos
    HAVING max(a.object_id) FILTER (WHERE a.type_id = r.wdl) IS NOT NULL
    ORDER BY l.ply
    LIMIT 1
),
hit AS MATERIALIZED (
    SELECT c.ply, c.pos, c.wdl, c.dtz::text AS dtz,
           NULL::bytea AS wdl_id, NULL::bytea AS dtz_id
    FROM compact c
    UNION ALL
    SELECT l.ply, l.pos, NULL::integer, NULL::text, l.wdl_id, l.dtz_id
    FROM legacy l
    WHERE NOT EXISTS (SELECT 1 FROM compact)
),
surfaces AS MATERIALIZED (
    SELECT COALESCE(array_agg(DISTINCT s), '{}'::bytea[]) AS ids
    FROM hit h, LATERAL (VALUES (h.wdl_id), (h.dtz_id)) v(s)
    WHERE s IS NOT NULL
),
label AS MATERIALIZED (
    SELECT p.id, p.txt
    FROM surfaces b,
         LATERAL ROWS FROM (
             unnest(b.ids), unnest(realize.batch(b.ids, NULL))
         ) AS p(id, txt)
)
SELECT h.pos,
       h.ply,
       -- Exact men is a board fact (compose-time). Not stored on laplace.physicalities;
       -- NULL here rather than lying with n_constituents (substructure count).
       NULL::integer,
       COALESCE(
           CASE h.wdl
               WHEN 0 THEN 'loss'
               WHEN 1 THEN 'blessed-loss'
               WHEN 2 THEN 'draw'
               WHEN 3 THEN 'cursed-win'
               WHEN 4 THEN 'win'
           END,
           w.txt),
       COALESCE(h.dtz, d.txt)
FROM hit h
LEFT JOIN label w ON w.id = h.wdl_id
LEFT JOIN label d ON d.id = h.dtz_id
$$;
-- chess.missed_finish(line): positions on the line where the closings catalog
-- says the side to move wins, but the played MOVE leaves a successor that is
-- not a loss/blessed-loss for the opponent (tablebase win abandoned).
-- Provenance read — not logistic HAS_EVAL.
--
-- Relation vocabulary via chess.has_wdl_type(ISA G3).
--
-- Both id lookups are bound ONCE, in CTEs, and the WDL scan is restricted to the
-- line's own positions -- the two defects this function shipped with (#844, #817):
--
--   per-row STABLE call   `WHERE a.type_id = chess.has_wdl_type()` put a
--                         `LANGUAGE sql STABLE` function inside a filter, so it ran
--                         once per attestation row instead of once per statement.
--                         The same held for laplace.word_id('loss') / laplace.word_id('blessed-loss')
--                         in the missed-finish predicate. chess_syzygy_line already
--                         binds its relation ids in a `rel` CTE; this follows it.
--
--   unbounded WDL scan    the `wdl` CTE selected EVERY HAS_WDL attestation in the
--                         database and discarded the non-line ones by join afterwards,
--                         so cost scaled with total Syzygy testimony rather than with
--                         the line being asked about. The subject restriction now
--                         lives inside the CTE: `line` drives, laplace.attestations is probed
--                         by subject_id.
DROP FUNCTION IF EXISTS laplace.chess_missed_finish(bytea, int);
CREATE OR REPLACE FUNCTION chess.missed_finish(p_line bytea, p_limit int DEFAULT 32)
    RETURNS TABLE(
        from_position bytea,
        to_position bytea,
        ply integer,
        from_wdl text,
        to_wdl text)
    LANGUAGE sql STABLE
 AS $$
WITH rel AS MATERIALIZED (
    SELECT chess.has_wdl_type() AS wdl
),
verdict AS MATERIALIZED (
    SELECT laplace.word_id('win')           AS win,
           laplace.word_id('loss')          AS loss,
           laplace.word_id('blessed-loss')  AS blessed_loss
),
line AS MATERIALIZED (
    SELECT (u.ord - 1)::int AS ply, u.entity_id AS pos
    FROM LATERAL generation.trajectory_unpacked_points(p_line, 3::smallint)
         WITH ORDINALITY AS u(entity_id, run_length, ctier, ord)
),
steps AS MATERIALIZED (
    SELECT a.ply, a.pos AS from_pos, b.pos AS to_pos
    FROM line a
    JOIN line b ON b.ply = a.ply + 1
),
-- Subject-restricted: the line's positions drive, laplace.attestations is probed by
-- subject_id. Both endpoints of every step are line points, so this covers the
-- from_pos join and the to_pos outer join alike.
-- One row per position. laplace.attestations is keyed by (subject, type, object, source,
-- context), so a position carrying Syzygy WDL from more than one source yields
-- several rows per pos. Left uncollapsed that is not merely duplication: the
-- to_pos join below tests `IS DISTINCT FROM loss`, so a position with both a
-- `loss` deposit and any other deposit would keep the non-loss row and report a
-- missed finish that is not one — and the duplicates then consume p_limit.
-- max(object_id) is the same deterministic collapse chess_syzygy_line uses.
wdl AS MATERIALIZED (
    SELECT l.pos AS pos, max(a.object_id) AS wdl_id
    FROM line l
    JOIN rel r ON true
    JOIN laplace.attestations a ON a.subject_id = l.pos
                       AND a.type_id = r.wdl
    GROUP BY l.pos
),
missed AS MATERIALIZED (
    SELECT s.ply, s.from_pos, s.to_pos, fw.wdl_id AS from_wdl_id, tw.wdl_id AS to_wdl_id
    FROM steps s
    JOIN wdl fw ON fw.pos = s.from_pos
    JOIN verdict v ON v.win = fw.wdl_id
    LEFT JOIN wdl tw ON tw.pos = s.to_pos
    -- After a winning move under optimal play, the successor (opponent to move)
    -- is a loss for the side then to move (= win preserved for the previous mover).
    -- Any other deposited WDL, or no deposit, is a missed finish signal.
    WHERE tw.wdl_id IS DISTINCT FROM v.loss
      AND tw.wdl_id IS DISTINCT FROM v.blessed_loss
    ORDER BY s.ply
    LIMIT p_limit
),
surfaces AS MATERIALIZED (
    SELECT COALESCE(array_agg(DISTINCT s), '{}'::bytea[]) AS ids
    FROM missed m, LATERAL (VALUES (m.from_wdl_id), (m.to_wdl_id)) v(s)
    WHERE s IS NOT NULL
),
label AS MATERIALIZED (
    SELECT p.id, p.txt
    FROM surfaces b,
         LATERAL ROWS FROM (
             unnest(b.ids), unnest(realize.batch(b.ids, NULL))
         ) AS p(id, txt)
)
SELECT m.from_pos, m.to_pos, m.ply, f.txt, t.txt
FROM missed m
LEFT JOIN label f ON f.id = m.from_wdl_id
LEFT JOIN label t ON t.id = m.to_wdl_id
ORDER BY m.ply
$$;
-- chess.opening_endgames(opening, limit): where an opening ACTUALLY ENDS UP, decided by
-- the tablebase rather than by the scoresheet.
--
-- This is the openings-to-syzygy correlation, and the point of both lanes being
-- content-addressed. Neither lane knows the other exists:
--
--   ChessOpenings      (final_position, OPENING_NAME, name)
--   ChessPgn/Analysis  (line, GAME_HAS_OPENING, name)     <- same content id
--   ChessSyzygy        (position, HAS_WDL, verdict) ctx = line
--
-- so opening -> line -> exact endgame verdict is two joins on ids that collided by
-- construction. No resolution pass, no mapping table, nothing to maintain when a new
-- opening or a new tablebase set lands.
--
-- COMPOSED, NOT REWRITTEN. It names no relation of its own: chess_opening_games already
-- resolves an opening to its lines and chess_syzygy_line already reads a line's verdicts,
-- so this is an aggregate over the two. That keeps one definition of each hop — and a
-- function that re-derives what two neighbours already compute is the wheel-reinvention
-- the ISA gate's vocabulary ratchet is aimed at.
--
-- WHAT THE ANSWER MEANS. A verdict here is not who won — it is what the position was
-- WORTH under perfect play at the moment the game reached a table, side-to-move POV. An
-- opening whose lines reach 'draw' verdicts steers into drawn endgames however the games
-- were actually scored, which no scoresheet aggregate can tell you.
--
-- UNPROBED IS NOT DRAWN. Lines whose endgames never reached a loaded table return no rows,
-- and that silence is correct: bool_or over zero rows is NULL, and a 3-4-5-man set covers
-- a small fraction of play. Read lines_probed against chess_opening_record's lines before
-- concluding anything about the opening as a whole.
DROP FUNCTION IF EXISTS laplace.chess_opening_endgames(text, int, int);
CREATE OR REPLACE FUNCTION chess.opening_endgames(p_opening text,
                                                  p_limit int DEFAULT 16,
                                                  p_scan_lines int DEFAULT 5000)
    RETURNS TABLE(wdl text, positions bigint, lines_probed bigint)
    LANGUAGE sql STABLE
 AS $$
WITH lines AS MATERIALIZED (
    SELECT DISTINCT g.line_id FROM chess.opening_games(p_opening, p_scan_lines) g
),
verdict AS MATERIALIZED (
    SELECT s.wdl, count(*) AS positions, count(DISTINCT l.line_id) AS lines_probed
    FROM lines l, LATERAL chess.syzygy_line(l.line_id) s
    WHERE s.wdl IS NOT NULL
    GROUP BY s.wdl
)
SELECT v.wdl, v.positions::bigint, v.lines_probed::bigint
FROM verdict v
ORDER BY v.positions DESC, v.wdl
LIMIT p_limit
$$;
-- lexical.sense_audit(term): why lexical.senses() returned what it returned.
--
-- Promoted 2026-08-02 from six ad-hoc queries run to diagnose a live
-- regression, because a diagnostic run more than once is a missing surface,
-- not a query. It answers, per candidate sense, the four questions that
-- diagnosis needed and could not get from lexical.senses() alone:
--
--   WHAT IS IT      the target's ENTITY TYPE. lexical.senses() returns a `synset_id`
--                   column, but bubble_up promotes any IS_SYNONYM_OF target
--                   into that slot, so the value is frequently typed Word or
--                   Sentence rather than WordNet_Synset. Measured on the
--                   multilingual seed: 55 Word + 9 Sentence, ZERO synsets.
--   HOW DID IT GET  the relation that admitted it. 63 of 64 candidates for
--   HERE            'glacier' arrived via IS_SYNONYM_OF -- i.e. they are
--                   TRANSLATIONS competing as senses, which is how an English
--                   prompt elected the Icelandic 'jökull'.
--   WHAT LANGUAGE   the attested HAS_LANGUAGE of the target. Present in the
--                   data and consulted by no elector.
--   HOW STRONG      denote_mu and witness count -- the numbers the election
--                   actually ranks on. English 'glacier' lost to Galician
--                   'glaciar' 1386 vs 1446 on witness count alone.
--
-- READ LAW. Ids until the end: the type, relation and language joins are all
-- id-space, and every label resolves in ONE realize_batch over the collected
-- ids, joined back by ordinal. No per-row realize, no string comparison, no
-- lower(). A diagnostic that violated the read law while diagnosing the read
-- path would be worth nothing.
-- p_lang_rel precedes p_limit: a non-defaulted parameter cannot follow a
-- defaulted one, and it cannot BE defaulted without writing the literal G3
-- forbids. The caller resolves it -- which is also what lets this audit any
-- relation, not only language.
DROP FUNCTION IF EXISTS laplace.sense_audit(text, bytea, int);
CREATE OR REPLACE FUNCTION lexical.sense_audit(p_term text, p_lang_rel bytea,
                                       p_limit int DEFAULT 64)
    RETURNS TABLE(sense text, sense_type text, via_relation text,
                  language text, denote_mu numeric, witnesses bigint)
    LANGUAGE sql STABLE AS $$
WITH w AS (SELECT laplace.word_id(p_term) AS id),
cand AS (
    SELECT s.synset_id, s.eff_mu, s.witnesses,
           row_number() OVER (ORDER BY s.eff_mu DESC, s.synset_id) AS rk
    FROM w CROSS JOIN LATERAL lexical.senses(w.id) s
),
capped AS (SELECT * FROM cand WHERE rk <= p_limit),
-- The relation that admitted this candidate. A target reachable by several
-- relations reports the strongest, which is the one that carried it.
via AS (
    SELECT c.object_id AS synset_id, c.type_id,
           row_number() OVER (PARTITION BY c.object_id
                              ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.type_id) AS rk
    FROM w CROSS JOIN laplace.consensus c
    WHERE c.subject_id = w.id AND c.object_id IN (SELECT synset_id FROM capped)
),
-- Language via converse.word_language() — the existing HAS_LANGUAGE surface — so this
-- diagnostic does not mint a new laplace.relation_type_id('HAS_LANGUAGE') literal
-- (W6 G3 shrink-only). Same strongest-language pick as the prior CTE.
lang AS (
    -- ONE set-based scan, not converse.word_language() per row. #787 fixed the same G3
    -- violation by calling converse.word_language(synset_id) per candidate; that helper
    -- is STRICT and carries a SET clause, so it cannot inline, and each call is
    -- its own consensus scan, the per-row shape W15 documents as a defect.
    -- Same G3 outcome, different cost.
    SELECT c.subject_id AS synset_id, c.object_id AS lang_id,
           row_number() OVER (PARTITION BY c.subject_id
                              ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id) AS rk
    FROM laplace.consensus c
    WHERE c.type_id = p_lang_rel
      AND c.subject_id IN (SELECT synset_id FROM capped)
),
rows AS (
    SELECT c.rk, c.synset_id, e.type_id, v.type_id AS via_id, l.lang_id,
           c.eff_mu, c.witnesses
    FROM capped c
    LEFT JOIN laplace.entities e ON e.id = c.synset_id
    LEFT JOIN via  v ON v.synset_id = c.synset_id AND v.rk = 1
    LEFT JOIN lang l ON l.synset_id = c.synset_id AND l.rk = 1
),
-- ONE realize.render pass over every id this result needs, position-aligned.
ids AS (
    SELECT array_agg(x ORDER BY ord) AS arr
    FROM (SELECT r.rk * 4 - 3 AS ord, r.synset_id AS x FROM rows r
          UNION ALL SELECT r.rk * 4 - 2, r.type_id  FROM rows r
          UNION ALL SELECT r.rk * 4 - 1, r.via_id   FROM rows r
          UNION ALL SELECT r.rk * 4,     r.lang_id  FROM rows r) z
),
lbl AS (SELECT realize.batch(arr, NULL) AS l FROM ids)
SELECT lbl.l[r.rk * 4 - 3],
       lbl.l[r.rk * 4 - 2],
       lbl.l[r.rk * 4 - 1],
       lbl.l[r.rk * 4],
       round(r.eff_mu::numeric, 0),
       r.witnesses
FROM rows r CROSS JOIN lbl
ORDER BY r.rk
$$;
-- election_token_profile: the per-token evidence profile an election ranks on.
--
-- W15 enumerates the axes a topic election may use and rules that no single one
-- of them can carry it — six keys have each failed with their own degenerate
-- class (denote_mu -> function words, total_mass -> degree, highway popcount ->
-- the tier-0 floor, ord DESC -> SVO word order, container IDF -> rare words,
-- coherence/total_mass -> zero without a direct edge). Judging a candidate
-- combination therefore means reading several axes for the same token at once.
--
-- That read was being hand-written each time it was needed: a CTE over
-- entity_container_degree, a lateral count over consensus_out, a witness sum,
-- and a hand-tuned witness transform, re-derived per investigation. This is the same
-- reinvented-wheel defect W16 documents in the read path, committed by the
-- person documenting it. One implementation, named, installed, callable through
-- `op` — so the next measurement quotes a function instead of a paragraph of SQL.
--
-- Text in, because the caller has surfaces and laplace.word_id() is the resolution the
-- elector itself performs. Ids that resolve to nothing come back with zeroes
-- rather than vanishing: an unattested surface is a real answer, and dropping
-- the row would be the EXISTS-collapses-NULL defect in another costume.
--
-- No SET search_path (GH #860), every reference schema-qualified (G11).
DROP FUNCTION IF EXISTS laplace.election_token_profile(text[]);
CREATE OR REPLACE FUNCTION converse.election_token_profile(p_surfaces text[])
    RETURNS TABLE(
        surface        text,
        entity_id      bytea,
        tier           integer,
        containers     bigint,
        icf            double precision,
        out_edges      bigint,
        witnesses      bigint,
        witness_sat    double precision,
        icf_x_sat      double precision,
        bands          integer)
    LANGUAGE sql STABLE AS $$
    WITH t AS MATERIALIZED (
        SELECT s.ord, s.surface, laplace.word_id(s.surface) AS id
        FROM unnest(p_surfaces) WITH ORDINALITY AS s(surface, ord)
    ),
    ids AS MATERIALIZED (
        SELECT i.id
        FROM (SELECT DISTINCT t.id FROM t WHERE t.id IS NOT NULL) i
    ),
    -- The array operation is invoked once for the bounded token set, not once
    -- with a one-element array for every token.
    deg AS MATERIALIZED (
        SELECT d.entity_id, d.degree, d.icf
        FROM (SELECT array_agg(ids.id ORDER BY ids.id) AS a FROM ids) b
        CROSS JOIN LATERAL structural.entity_container_degree(b.a) d
    ),
    -- The bounded ids drive subject-key probes directly. consensus_out hid the
    -- same scan behind one SRF invocation per token and imposed a 1,000,000-row
    -- truncation before this aggregate. A profile needs the full count; it does
    -- not need edge ordering or rendering.
    edg AS MATERIALIZED (
        SELECT ids.id AS entity_id,
               count(c.type_id)                                  AS out_edges,
               COALESCE(sum(c.witness_count), 0)::bigint         AS witnesses
        FROM ids
        LEFT JOIN laplace.consensus c ON c.subject_id = ids.id
        GROUP BY ids.id
    ),
    ent AS MATERIALIZED (
        SELECT ids.id AS entity_id, e.highway_mask
        FROM ids
        LEFT JOIN laplace.entities e ON e.id = ids.id
    )
    SELECT t.surface,
           t.id,
           generation.entity_tier_of(t.id),
           COALESCE(deg.degree, 0),
           COALESCE(deg.icf, 1.0),
           COALESCE(edg.out_edges, 0),
           COALESCE(edg.witnesses, 0),
           COALESCE(edg.witnesses, 0)::double precision,
           COALESCE(deg.icf, 1.0)
               * COALESCE(edg.witnesses, 0)::double precision,
           COALESCE(consensus.highway_popcount(ent.highway_mask), 0)
    FROM t
    LEFT JOIN deg ON deg.entity_id = t.id
    LEFT JOIN edg ON edg.entity_id = t.id
    LEFT JOIN ent ON ent.entity_id = t.id
    ORDER BY t.ord
$$;
-- structural.geometry_audit(): the S³ placement, per tier, as a standing surface.
--
-- Promoted 2026-08-02 from ad-hoc queries run while investigating Hilbert
-- partition skew. A diagnostic that answers a recurring structural question is
-- a surface, not a query typed twice.
--
-- WHAT IT ANSWERS, and why each column is here:
--
--   radius spread   THE GLOME IS A BALL, NOT JUST ITS SURFACE. Tier-0 atoms are
--                   placed by super_fibonacci and land at radius EXACTLY 1 --
--                   on S³. Composed entities are combinations of their
--                   children, and a combination of unit vectors has norm < 1,
--                   so they land INSIDE. Radius therefore encodes composition,
--                   not just position: broader/flatter composition cancels more
--                   and sits nearer the origin. Measured before this surface
--                   existed: a spike at exactly 1.00 plus a broad population
--                   around 0.39-0.51.
--
--   hilbert spread  physicalities is RANGE-partitioned on hilbert_index, a
--                   space-filling curve over the enclosing 4-BOX. The occupied
--                   region is the inscribed ball -- roughly 31% of that box in
--                   4D -- so equal-width curve ranges cannot yield equal
--                   populations. Measured: ~15x between the emptiest and
--                   fullest prefix band. This column makes that visible instead
--                   of leaving it to be rediscovered.
--
--   READS v_word_points, AND THAT IS THE POINT. The first draft hand-rolled
--   `entities JOIN laplace.physicalities` and used the WRONG KEY -- physicalities has
--   both `id` (its own identity) and `entity_id` (what it describes) -- so it
--   returned ZERO rows silently, which reads as "no skew" rather than "wrong
--   key". It also omitted the `type = 1` filter and was correct only because
--   no other physicality type exists yet.
--
--   v_word_points already encoded both: `p.entity_id = e.id AND p.type = 1`.
--   The wheel existed; re-deriving it introduced two defects in ten lines.
--   Every entity-to-physicality read belongs on this view, not on a fresh
--   join. (The view's name is misleading -- it carries EVERY tier, not just
--   words -- which is its own defect, but the join it encodes is canonical.)
--
-- Cheap by construction: one grouped pass, no per-row function calls, no
-- rendering. Sampling is the caller's choice via p_sample (percent); 0 = full
-- scan, which on a large substrate is a deliberate act.
-- VOLATILE, not STABLE (#844). The sampled mode builds `WHERE random() < ...`
-- into the executed statement, so this function does NOT return the same rows
-- for the same argument within a single statement -- which is exactly what
-- STABLE promises and what the planner is entitled to act on (folding repeated
-- calls, hoisting it out of a scan). It was declared STABLE when it landed;
-- p_sample = 0 happens to satisfy the promise, the default 0.3 does not.
-- Return-type change needs a DROP: CREATE OR REPLACE cannot alter a function's
-- RETURNS TABLE. Adding avg_constituents to this surface failed the upgrade
-- until this line existed -- the same trap prompt_coherence and infer hit.
DROP FUNCTION IF EXISTS laplace.geometry_audit(double precision);

CREATE OR REPLACE FUNCTION structural.geometry_audit(p_sample double precision DEFAULT 0.3)
    RETURNS TABLE(tier smallint, entities bigint,
                  min_radius numeric, avg_radius numeric, max_radius numeric,
                  on_sphere bigint, interior bigint, avg_constituents numeric,
                  hilbert_bands int, min_band bigint, max_band bigint)
    LANGUAGE plpgsql VOLATILE
    AS $$
DECLARE
    q text;
BEGIN
    -- TABLESAMPLE percent cannot be a bound parameter, so the sample clause is
    -- built here. p_sample is forced numeric before interpolation: it is the
    -- only user input that reaches the statement text, and it never reaches it
    -- as a string.
    q := format($f$
        WITH j AS (
            SELECT v.tier, v.radius_origin AS r,
                   substring(encode(v.hilbert_index,'hex'),1,1) AS band,
                   v.n_constituents AS nc
            FROM laplace.v_word_points v %s
        ),
        bands AS (
            SELECT tier, band, count(*) AS n FROM j GROUP BY tier, band
        )
        SELECT j.tier, count(*)::bigint,
               round(min(j.r)::numeric,3), round(avg(j.r)::numeric,3),
               round(max(j.r)::numeric,3),
               count(*) FILTER (WHERE j.r >= 0.999)::bigint,
               count(*) FILTER (WHERE j.r <  0.999)::bigint,
               round(avg(j.nc)::numeric,1),
               (SELECT count(*)::int FROM bands b WHERE b.tier = j.tier),
               (SELECT min(b.n)::bigint FROM bands b WHERE b.tier = j.tier),
               (SELECT max(b.n)::bigint FROM bands b WHERE b.tier = j.tier)
        FROM j GROUP BY j.tier ORDER BY j.tier
    $f$, CASE WHEN p_sample > 0 AND p_sample < 100
              -- TABLESAMPLE cannot be applied to a view (0A000), and standing on
              -- v_word_points is worth more than the cheaper sample: re-deriving
              -- the join is what produced two defects in the first draft. A
              -- Bernoulli filter costs a seq scan; this is a diagnostic, not a
              -- hot path, and the caller chooses the fraction.
              THEN format('WHERE random() < %s', (p_sample/100.0)::numeric)
              ELSE '' END);
    RETURN QUERY EXECUTE q;
END;
$$;
-- converse.resolve_audit(prompt): what the machine actually saw, and what it MISSED.
--
-- THE EDGE OF THE WINDOW, MADE VISIBLE. A bounded observer's characteristic
-- failure is mistaking the edge of its window for the edge of the world. This
-- surface exists so that edge is one call away instead of six ad-hoc queries.
--
-- Measured 2026-08-02, the failure this was built for: "Kot śpi na stole w
-- domu" answered ENGLISH. Polish has 87,985 language-tagged senses in the
-- substrate -- it was never a coverage gap. The Polish-SPECIFIC inflected
-- forms (`śpi`, `domu`) did not resolve at word tier, so the read discarded
-- them and judged the prompt on the residue: `kot` (also Slovenian), `na`
-- (also Irish), `stole` (an English verb). The tokens carrying the signal were
-- outside the frame, and NOTHING SAID SO.
--
-- Per prompt token this reports:
--   resolved      did it reach an entity at all
--   tier          WHICH tier answered (the floor is tier 0 and cannot miss;
--                 anything above it can, and does)
--   senses        how many candidate senses it carries
--   top_language  its strongest attested HAS_LANGUAGE
--   verdict       the honest word for what happened to this token
--
-- The verdict column is the point. `unresolved` is not a null to be swallowed;
-- it is a finding. A prompt where the content words are unresolved and only
-- function words survived is a prompt the machine cannot answer honestly, and
-- this says so in a column rather than leaving a confident wrong answer as the
-- only visible output.
--
-- WHY THE RELATION IS A PARAMETER. G3 (vocabulary literalism) forbids new
-- laplace.relation_type_id('LITERAL') sites; 243 existing ones are grandfathered in
-- scripts/isa-gate-baseline.json and the ceiling is shrink-only. Rather than
-- raise it for a diagnostic, the caller passes the relation id. That is also
-- correct on its own terms: a diagnostic that hardcodes one relation cannot
-- audit any other, and the id resolves ONCE at the call site instead of per
-- row.
--
-- READ LAW: ids until the end; one realize_batch over the collected ids joined
-- back by ordinal. No per-row realize, no string comparison, no lower().
DROP FUNCTION IF EXISTS laplace.resolve_audit(text, bytea);
CREATE OR REPLACE FUNCTION converse.resolve_audit(p_prompt text, p_lang_rel bytea)
    RETURNS TABLE(ord int, token text, resolved boolean, tier smallint,
                  senses bigint, top_language text, verdict text)
    LANGUAGE sql STABLE AS $$
WITH tok AS (
    -- prompt_words is the UAX-29 segmentation with its entity lookup. It
    -- returns one row per (ord, id) and an id living at two tiers appears
    -- TWICE (GH #752), so DISTINCT ON keeps one row per position -- otherwise
    -- a tier-collided token is double-counted in its own audit.
    SELECT DISTINCT ON (w.ord) w.ord, w.word, w.id
    FROM converse.prompt_words(p_prompt) w
    ORDER BY w.ord, w.id
),
enriched AS (
    SELECT t.ord, t.word, t.id,
           (SELECT min(e.tier) FROM laplace.entities e WHERE e.id = t.id) AS tier,
           (SELECT count(*) FROM lexical.senses(t.id)) AS n_senses,
           (SELECT c.object_id
              FROM laplace.consensus c
             WHERE c.subject_id = t.id
               AND c.type_id = p_lang_rel
             ORDER BY consensus.eff_mu(c.rating, c.rd) DESC, c.object_id
             LIMIT 1) AS lang_id
    FROM tok t
),
ord AS (
    SELECT e.*, row_number() OVER (ORDER BY e.ord) AS ix FROM enriched e
),
lbl AS (
    SELECT realize.batch(array_agg(o.lang_id ORDER BY o.ix), NULL) AS l
    FROM ord o
)
SELECT o.ord,
       o.word,
       o.id IS NOT NULL,
       o.tier,
       COALESCE(o.n_senses, 0),
       lbl.l[o.ix],
       CASE
         WHEN o.id IS NULL             THEN 'unresolved — outside the frame'
         WHEN o.tier = 0               THEN 'floor only — codepoint, no word sense'
         WHEN COALESCE(o.n_senses,0)=0 THEN 'resolved, no senses'
         WHEN o.lang_id IS NULL        THEN 'resolved, no language attested'
         ELSE 'resolved'
       END
FROM ord o CROSS JOIN lbl
ORDER BY o.ord
$$;
-- Upgrade cleanup after every first-party dependent has moved to the folded
-- rating/RD law. Fresh installs never create these historical second-stage
-- confidence transforms.
DROP FUNCTION IF EXISTS consensus.foundry_witness_sat(bigint);
DROP FUNCTION IF EXISTS consensus.foundry_rd_kappa();
DROP FUNCTION IF EXISTS laplace.foundry_witness_sat(bigint);
DROP FUNCTION IF EXISTS laplace.foundry_rd_kappa();
DROP FUNCTION IF EXISTS consensus.walk_edge_weight(bigint, bigint, bigint);
DROP FUNCTION IF EXISTS consensus.walk_edge_weight(bigint, bigint, bigint, double precision);
DROP FUNCTION IF EXISTS laplace.walk_edge_weight(bigint, bigint, bigint);
DROP FUNCTION IF EXISTS laplace.walk_edge_weight(bigint, bigint, bigint, double precision);
DROP FUNCTION IF EXISTS generation.steer_candidates(bytea[], bytea[], double precision);
